def zrodla_cisze(saved):
    """→ {część META ok: zbiór źródeł tej części, o których WIEMY, że w ostatnim odczycie nie odpowiedziały}, z plików zapisanych w tym przebiegu
    (SAVED; także z pamięci — wtedy to stan ostatniego odczytu). Część wieloźródłowa z błędem bez wpisu tutaj liczy jedno źródło jako milczące
    (zrodla_meta), nie wszystkie: awaria jednego portfela czy emitenta nie może wyglądać jak awaria całej grupy."""
    out = {}
    saved = saved if isinstance(saved, dict) else {}
    try:   # emitenci RWA: źródło milczy, gdy ostatni odczyt KAŻDEGO jego produktu zakończył się błędem (err w issuer.p)
        em = (saved.get('rwa') or {}).get('issuer')
        if isinstance(em, dict) and not em.get('off') and isinstance(em.get('p'), dict):
            odp, cichy = set(), set()
            for p in em['p'].values():
                i = ZRODLA_RWE.get(p.get('kind')) if isinstance(p, dict) else None
                if i:
                    (cichy if p.get('err') else odp).add(i)
            out['rwa-emitenci'] = cichy - odp
    except Exception:  # noqa
        pass
    try:   # stres: indeks stresu (urząd) i put/call (giełda opcji) to dwie części pliku z własnym ok
        ok = (saved.get('stres') or {}).get('ok')
        if isinstance(ok, dict):
            out['stres'] = {i for k, i in (('fsi', 'ofr'), ('pc', 'cboe')) if ok.get(k) is False}
    except Exception:  # noqa
        pass
    try:   # plik dzienny świata: ceny sesji (giełda Nasdaq) i poranne pliki State Street mają osobne wpisy błędów
        wd = saved.get('swiat-dzien') or {}
        bl = wd.get('bledy') if isinstance(wd.get('bledy'), dict) else {}
        cichy = {'nasdaq'} if (bl.get('px') or bl.get('seed_px') or ((wd.get('nq') or {}).get('fails') or 0) > 0) else set()
        if bl.get('ssga'):
            cichy.add('ssga')
        out['swiat-dzien'] = cichy
    except Exception:  # noqa
        pass
    return out


ZRODLA_META.update({'iip': 'imf'})   # v431 (F11Z30): wierzyciele i dłużnicy świata — ten sam dostawca co bilans płatniczy, rezerwy i COFER (liczba źródeł bez zmian)
ZRODLA_META.update({'inflacja': 'bis', 'koniunktura': 'oecd'})   # v366 (F2Z2): inflacja i koniunktura — te same dwa źródła co dotąd (liczba źródeł bez zmian)


def zrodla_meta(ok, errors=(), notes=(), saved=None):
    """→ {'n': liczba źródeł, które mają część w tym przebiegu, 'ok': ile z nich odpowiedziało albo ma świeże dane z pamięci} albo None, gdy nie ma
    żadnego źródła (strona nie pokazuje wtedy liczby — nigdy „0”). Źródło „odpowiedziało”, gdy choć jedna jego część ma ok True albo 'cached'
    (pamięć = dane jeszcze świeże, bez ponownego pytania). Część z jednym źródłem i ok False = źródło milczy. Część z kilkoma źródłami i ok False
    = co najmniej jedno zawiodło: znane z zapisanych plików (zrodla_cisze) milczą, pozostałe liczą się jako odpowiedziane; gdy nie wiadomo które,
    milczące jest jedno (dolna granica — nie osiem emitentów, gdy zawiódł jeden). Część bez wpisu w tabeli jest pomijana (test tabeli pilnuje,
    by takiej nie było)."""
    msgs = [str(x) for x in list(errors) + list(notes)]
    off = {i for i, fr in ZRODLA_WYLACZONE.items() if any(f in m for f in fr for m in msgs)}
    ok = ok or {}
    cisze = zrodla_cisze(saved)
    wszystkie, odp, niepewne = set(), set(), []
    for k, v in ok.items():
        ids = ZRODLA_META.get(k)
        if not ids:
            continue
        ids = [i for i in ((ids,) if isinstance(ids, str) else ids) if i not in off]
        wszystkie.update(ids)
        if any(s in ok for s in ZRODLA_SKLADOWE.get(k, ())):
            continue   # o odpowiedzi decydują części składowe tej samej grupy
        if v is True or v == 'cached':
            odp.update(ids)
        elif len(ids) > 1:
            znane = set(cisze.get(k) or ()) & set(ids)
            if znane:
                odp.update(set(ids) - znane)
            else:
                niepewne.append(ids)
    for ids in sorted(niepewne):
        odp.update(sorted(i for i in ids if i not in odp)[1:])   # jedno z nieodpowiedzianych milczy (dolna granica), reszta odpowiedziała
    return {'n': len(wszystkie), 'ok': len(odp)} if wszystkie else None


import functools as _mk_ft   # v272: pamięć postaci kluczy (biblioteka standardowa)


@_mk_ft.lru_cache(maxsize=256)
def _mask_formy(k, kawalki=False):
    """v272 (przegląd v271): postaci wartości sekretu, w których może się pojawić w komunikacie — dosłowna, z ucieczkami (repr: \\t, \\n;
    JSON: \\u0000) i zakodowana w adresie (%09, +); kawalki=True (klucz odrzucony przez klucz()) — także każdy kawałek ≥ 6 znaków między
    spacjami i znakami sterującymi (inna biblioteka mogła zakodować tylko sam znak). Najdłuższe najpierw."""
    f = {k, repr(k)[1:-1], json.dumps(k)[1:-1], urllib.parse.quote(k, safe=''), urllib.parse.quote_plus(k)}
    if kawalki:   # v278 (przegląd v272): nazwa zmiennej wklejona z wartością („FMP_KEY = …”) nie jest kawałkiem klucza — inaczej „Klucz ***” w meta
        f.update(p for p in _KLUCZ_ZLY.split(k) if len(p) >= 6   # v281: także „FRED_KEY:” / „FRED_KEY=” (nazwa ze znakiem przypisania)
                 and not re.fullmatch(r'[A-Z][A-Z0-9]*(?:_[A-Z0-9]+)*_(?:KEY|TOKEN|SECRET)', p.strip(':=;,')))
    return tuple(sorted((x for x in f if x), key=len, reverse=True))


def mask(text):
    """Komunikat błędu nigdy nie zawiera klucza (nawet gdy dostawca odbije adres z parametrem, także w postaci z ucieczkami — v272)."""
    text = str(text)
    for k in SECRETS:
        if k:
            for x in _mask_formy(k):
                text = text.replace(x, '***')
    for k in SECRETS_ZLE:
        for x in _mask_formy(k, True):
            text = text.replace(x, '***')
    return text


def klucz(name):
    """v272 (przegląd v271): sekret ze zmiennej środowiska (GitHub Secrets) bez spacji na końcach. Spacja, tabulator, nowa linia albo inny
    znak sterujący W ŚRODKU (np. sekret wklejony w dwóch liniach) = klucz nieużyty + błąd w meta (tylko nazwa, nigdy wartość): zapytanie z takim
    kluczem i tak by się nie udało, a komunikat biblioteki cytowałby adres z kluczem w postaci z ucieczkami. Wartość zostaje w SECRETS_ZLE
    (maskowana z kawałkami)."""
    v = os.environ.get(name, '').strip()
    if v and _KLUCZ_ZLY.search(v):
        if v not in SECRETS_ZLE:
            SECRETS_ZLE.append(v)
        META['errors'].append(f'Klucz {name}: spacja albo znak sterujący (np. nowa linia) w środku wartości — klucz nieużyty; popraw sekret w GitHub')
        return ''
    return v


import threading as _zuz_th, urllib.parse as _zuz_parse   # v222: blokada licznika (części w wątkach) i rozbiór adresu (biblioteka standardowa)

ZUZ_PLANY = {'cg': ('api.coingecko.com', 'x-cg-demo-api-key'),   # v222: darmowe plany z limitem — host i nagłówek klucza (bez klucza = nie z planu)
             'cmc': ('pro-api.coinmarketcap.com', None),
             'td': ('api.twelvedata.com', None),                # Twelve Data: kredyty = liczba symboli w zapytaniu
             'fmp': ('financialmodelingprep.com', None)}        # v295: FMP (plan darmowy 250 zapytań na dobę: indeksy i surowce)
ZUZ_DOST_H = 6        # v222: raport zużycia od dostawcy (CoinMarketCap) najwyżej raz na blok 6 godzin UTC
_ZUZ = {}             # v222: zapytania tego przebiegu do planów z limitem (td: kredyty)
_ZUZ_LOCK = _zuz_th.Lock()


def _zuz_licz(url, headers=None):
    """v222: zapytanie do darmowego planu z limitem → licznik tego przebiegu. CoinGecko tylko z kluczem w nagłówku (zapytanie bez klucza nie
    zużywa planu), Twelve Data: kredyty = liczba symboli w parametrze symbol. Licznik nigdy nie przerywa zapytania."""
    try:
        u = _zuz_parse.urlsplit(url)
        for k, (host, hdr) in ZUZ_PLANY.items():
            if u.hostname != host:
                continue
            if hdr and not any(str(h).lower() == hdr and v for h, v in (headers or {}).items()):
                return
            n = 1
            if k == 'td':
                _TD_T[0] = time.monotonic()   # v295: surowce nie pytają Twelve Data w tej samej minucie (limit 8 kredytów na minutę)
                s = _zuz_parse.parse_qs(u.query).get('symbol')
                n = max(1, len([x for x in s[0].split(',') if x.strip()])) if s else 1
            with _ZUZ_LOCK:
                _ZUZ[k] = _ZUZ.get(k, 0) + n
            return
    except Exception:
        return


import http.client as _http_client   # v272: InvalidURL (biblioteka standardowa; ponowny import jest nieszkodliwy)


def _otworz(url, headers=None, timeout=30):
    """v272 (przegląd v271): żądanie GET z identyfikatorem zbieracza. Zły adres albo nagłówek (np. znak sterujący w kluczu) = ValueError bez
    treści — komunikat biblioteki (http.client.InvalidURL, „Invalid header value”, „unknown url type”) cytuje cały adres albo nagłówek, a w nim
    klucz w postaci z ucieczkami (\\t, \\n); „from None” — także bez pierwotnego wyjątku w śladzie w dzienniku przebiegu."""
    try:
        return urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent': 'CapitalFlowAI-collector/1.0', **(headers or {})}),
                                      timeout=timeout)
    except (ValueError, _http_client.InvalidURL) as e:   # InvalidURL nie jest ValueError (http.client.HTTPException)
        raise ValueError(f'zły adres albo nagłówek zapytania ({type(e).__name__})') from None


def get(url, headers=None, timeout=30):
    _zuz_licz(url, headers)   # v222: licznik zużycia planów z limitem
    with _otworz(url, headers, timeout) as r:   # v272: zły adres/nagłówek — komunikat bez klucza
        return r.status, r.read().decode('utf-8', 'replace')


def get_json(url, headers=None, timeout=30):
    st, body = get(url, headers, timeout)
    return json.loads(body)


def get_bytes(url, headers=None, timeout=60):
    _zuz_licz(url, headers)   # v222: licznik zużycia planów z limitem
    with _otworz(url, headers, timeout) as r:   # v272: zły adres/nagłówek — komunikat bez klucza
        return r.read()


def soso(path, key, _retry=True):
    time.sleep(SOSO_SLEEP)
    try:
        j = get_json(SOSO + path, {'x-soso-api-key': key})
    except urllib.error.HTTPError as e:
        if e.code == 429 and _retry and (_DEADLINE[0] is None or time.monotonic() < _DEADLINE[0]):          # limit minutowy — odczekaj pełną minutę i spróbuj raz jeszcze
            print('SoSoValue 429 — czekam 65 s')
            time.sleep(65)
            return soso(path, key, _retry=False)
        raise
    if isinstance(j, dict) and j.get('code') not in (None, 0):
        raise RuntimeError(f'SoSoValue {path}: {j.get("message")}')
    return j['data'] if isinstance(j, dict) and 'data' in j else j


# v331 (ZB10-02): odczyt poprzednich plików z opublikowanej strony ma wspólny budżet czasu na przebieg. Dawniej każdy z ok. 60 plików czekał do 30 s, więc strona,
# która przyjmuje połączenia i nie odpowiada, zjadała 30 min (limit zadania 25 min) i nic się nie publikowało, choć pamięć Actions wystarcza.
PREV_SITE_TMO = 10      # s na jedno zapytanie o poprzedni plik
PREV_SITE_BUDGET = 90   # s łącznie na wszystkie takie zapytania w jednym przebiegu
PREV_SITE_FAILS = 2     # tyle kolejnych porażek sieci (brak odpowiedzi, odmowa, błąd serwera) = strona pominięta do końca przebiegu (zostaje pamięć Actions)
_PREV_SITE = {'run': None, 'spent': 0.0, 'fails': 0, 'off': False}   # liczniki jednego przebiegu (klucz: _RUN_T0 ustawiany przez main)


def _pclock():
    return time.monotonic()


def _prev_site_stan():
    st = _PREV_SITE
    if st['run'] != _RUN_T0[0]:   # nowy przebieg (main ustawia _RUN_T0) — liczniki od zera
        st.update(run=_RUN_T0[0], spent=0.0, fails=0, off=False)
    return st


def _prev_site(name):
    site = os.environ.get('SITE_URL', '').rstrip('/')
    if not site:
        return None
    st = _prev_site_stan()
    if st['off']:
        return None   # strona pominięta do końca przebiegu — zostaje pamięć Actions (zbiorczy wpis w META już jest)
    left = PREV_SITE_BUDGET - st['spent']
    if left < 1:
        st['off'] = True
        META['errors'].append(f'poprzednie pliki ze strony: budżet czasu przebiegu ({PREV_SITE_BUDGET} s) wyczerpany — dalej tylko pamięć Actions')
        return None
    t0, siec = _pclock(), False   # siec: nie odpowiedziała (czas, odmowa, błąd serwera) — 404 i uszkodzony JSON to odpowiedzi strony
    try:
        return get_json(f'{site}/data/{name}.json?t={int(time.time())}', timeout=min(PREV_SITE_TMO, left))
    except urllib.error.HTTPError as e:
        if e.code == 404:   # pliku jeszcze nie ma (pierwszy przebieg) — informacja, nie błąd
            META['notes'].append(f'poprzedni {name}.json: brak na stronie (404)'); return None
        META['errors'].append(mask(f'poprzedni {name}.json: {e}')); siec = True; return None
    except Exception as e:  # noqa
        META['errors'].append(mask(f'poprzedni {name}.json: {e}'))
        siec = not isinstance(e, ValueError)
        return None
    finally:
        st['spent'] += max(0.0, _pclock() - t0)
        st['fails'] = st['fails'] + 1 if siec else 0
        if st['fails'] >= PREV_SITE_FAILS and not st['off']:
            st['off'] = True
            META['errors'].append(f'poprzednie pliki ze strony: brak odpowiedzi ({st["fails"]} kolejne porażki) — dalej tylko pamięć Actions do końca przebiegu')


def _dict(x):
    """v331 (ZB10-04): pole ok / errs poprzedniego pliku bywa uszkodzone (tekst, lista, liczba) — wtedy pusty słownik, a nie wyjątek poza try."""
    return x if isinstance(x, dict) else {}


def _prev_cache(name):
    """v51: plik z pamięci GitHub Actions (CACHE_DIR) — przeżywa awarię publikacji strony."""
    d = os.environ.get('CACHE_DIR', '').strip()
    if not d:
        return None
    p = os.path.join(d, name + '.json')
    if not os.path.exists(p):
        return None
    try:
        with open(p, encoding='utf-8') as f:
            return json.load(f)
    except Exception as e:  # noqa
        META['errors'].append(mask(f'pamięć {name}.json: {e}'))
        return None


def previous(name):
    """Poprzedni plik: nowszy (wg pola at) z pamięci Actions i z opublikowanej strony — awaria API nie wymaże danych,
    a awaria publikacji nie zwielokrotni zapytań (v51)."""
    cands = [c for c in (_prev_cache(name), _prev_site(name)) if isinstance(c, dict)]
    if not cands:
        return None
    # v132: remis pola at (plik bez nowych danych, np. sama zmiana licznika prób SOPR) rozstrzyga czas przebiegu run.at — stara kopia z pamięci
    # Actions nie cofa licznika; pliki bez run.at jak dotąd (przy remisie pierwsza: pamięć Actions)
    return max(cands, key=lambda c: (str(c.get('at') or ''), str(c['run'].get('at') or '') if isinstance(c.get('run'), dict) else ''))


def fresh(prev, minutes):
    """Czy poprzedni plik (z opublikowanej strony) jest młodszy niż `minutes` minut."""
    try:
        at = datetime.datetime.fromisoformat(prev['at'])
        return (datetime.datetime.now(datetime.timezone.utc) - at).total_seconds() < minutes * 60
    except Exception:
        return False


NIEPELNY_MIN = 55   # v328 (pasy Z2 i Z3 planu napraw): plik z częścią nieudaną jest w main() „świeży” najwyżej tyle minut — ponowienie w następnej godzinie


def plik_niepelny(p):
    """v328: czy plik ma część, która w jego budowie zawiodła — pole 'ok' = {część: True/False}; False = część z poprzedniego pliku (z własnym 'part_at')
    albo brak. Plik bez pola 'ok' (sprzed v328) i plik pełny — nie."""
    ok = p.get('ok') if isinstance(p, dict) else None
    return isinstance(ok, dict) and any(v is False for v in ok.values())


def fresh_pelny(prev, minutes):
    """v328: jak fresh(), ale plik niepełny (plik_niepelny) jest świeży najwyżej NIEPELNY_MIN min — chwilowa awaria jednego z kilku zapytań pliku
    nie blokuje ponowienia na 6–24 h (jedna zasada dla instytucji/bop, TIC, kursów efektywnych, Meksyku, SPW, BLS i BEA)."""
    return fresh(prev, min(minutes, NIEPELNY_MIN) if plik_niepelny(prev) else minutes)


def _zapas_czas(prev, name):
    """v328: czas pobrania części `name` poprzedniego pliku: prev['part_at'][name], inaczej prev['at'] (jak _czesc_z_zapasem); brak = None."""
    pat = prev.get('part_at') if isinstance(prev, dict) and isinstance(prev.get('part_at'), dict) else {}
    return pat.get(name) or (prev.get('at') if isinstance(prev, dict) else None)


def _zapas_wiek_ok(kiedy, max_dni):
    """v328: czy część pobrana `kiedy` (ISO) nie jest starsza niż max_dni dni wobec chwili przebiegu (NOW); brak albo zły czas = nie."""
    tk, tn = _ix_dt(kiedy), _ix_dt(NOW)
    return tk is not None and tn is not None and (tn - tk).total_seconds() <= max_dni * 86400


def save(name, obj):
    os.makedirs(OUT, exist_ok=True)
    with open(f'{OUT}/{name}.json', 'w', encoding='utf-8') as f:
        json.dump(obj, f, ensure_ascii=False, separators=(',', ':'))
    SAVED[name] = obj
    if _RUN_T0[0] is not None:   # v185: chwila zapisu (sekundy od startu przebiegu) — czas części przebiegu do meta.json i kontroli
        _CZAS.append((name, time.monotonic() - _RUN_T0[0]))
    print(f'zapisano {OUT}/{name}.json ({os.path.getsize(f"{OUT}/{name}.json")} B)')


def ts(date_str):
    return int(datetime.datetime.strptime(date_str, '%Y-%m-%d').replace(tzinfo=datetime.timezone.utc).timestamp())


