CZAS_UWAGA_S = 18 * 60    # v185: przebieg dłuższy = notatka w meta (limit zadania w Actions: 25 min)


def czas_przebiegu(zapisy, calosc):
    """v185: (plik, sekundy od startu) przy kolejnych zapisach → {'s': cały przebieg (s), 'top': 5 najdłuższych części [[plik, s], …]}.
    Część = czas od poprzedniego zapisu do zapisu tego pliku (budowa pliku i to, co przed nim); ten sam plik dwa razy — suma."""
    d, t0 = {}, 0.0
    for n, t in zapisy:
        d[n] = d.get(n, 0.0) + max(0.0, t - t0); t0 = t
    top = sorted(d.items(), key=lambda x: -x[1])[:5]
    return {'s': round(calosc), 'top': [[n, round(s)] for n, s in top]}


AW_PO_NAPRAWIE_H = 48     # v207: tyle godzin wpis zamkniętej serii zostaje w meta.json (kontrola raz na dobę widzi też awarie, które minęły w nocy)
AW_NIEOBECNA_H = 6        # v211: trwająca seria części nieobecnej w przebiegach dłużej niż tyle godzin od ostatniej awarii — zamknięta jako „zniknęła”
                          # (część wyłączona albo zmieniona; nie naprawa i nie BŁĄD); części tylko z przebiegów pełnej godziny mają ost co godzinę
AW_MAX = 100              # v207: najwyżej tyle wpisów (najmłodsze wg ostatniej awarii) — ochrona pliku stanu


def _aw_t(s):
    """v207: zapis czasu ISO ze strefą → datetime UTC; brak strefy albo zły zapis = None."""
    try:
        t = datetime.datetime.fromisoformat(str(s))
    except (TypeError, ValueError):
        return None
    return t.astimezone(datetime.timezone.utc) if t.tzinfo else None


def _aw_seria(s, tn):
    """v211: zamknięta seria [od, do, n] z pliku (do ≥ od, n ≥ 1, nie z przyszłości) albo None."""
    if not (isinstance(s, list) and len(s) == 3):
        return None
    od, do, n = _aw_t(s[0]), _aw_t(s[1]), s[2]
    if od is None or do is None or do < od or do > tn or not isinstance(n, int) or isinstance(n, bool) or n < 1:
        return None
    return [s[0], s[1], n]


def awarie(prev, ok, now):
    """v207/v211: pamięć awarii części między przebiegami (meta.json → 'awarie'): kontrola dzienna widzi, od kiedy część nie działa i co
    naprawiło się samo w nocy. prev — 'awarie' poprzedniego meta.json; ok — META['ok'] tego przebiegu; now — czas przebiegu (ISO ze strefą).
    Wpis {część: {'od', 'ost', 'n', 'do'[, 'zn'][, 'prev']}}: od — pierwszy nieudany przebieg serii, ost — ostatni nieudany, n — nieudanych
    przebiegów w serii, do — koniec serii albo None (trwa); zn True — seria zamknięta, bo część zniknęła z przebiegów (nie naprawa); prev —
    poprzednia zamknięta seria [od, do, n] (nowa seria jej nie wymazuje; zostaje dłuższa z dwóch).
    ok False → seria trwa (n + 1) albo zaczyna się nowa; tylko True kończy serię (v211: 'cached' = bez zapytania — część po nieudanej próbie
    czeka na ponowienie — nic nie zmienia, jak brak części w przebiegu). Seria części nieobecnej dłużej niż AW_NIEOBECNA_H h od ostatniej
    awarii — zamknięta z zn. Zamknięty wpis znika AW_PO_NAPRAWIE_H h po końcu, prev — AW_PO_NAPRAWIE_H h po swoim końcu; złe wpisy pomijane;
    najwyżej AW_MAX wpisów."""
    tn = _aw_t(now)
    if tn is None:
        raise ValueError('awarie: czas przebiegu bez strefy')
    H48 = datetime.timedelta(hours=AW_PO_NAPRAWIE_H)
    out = {}
    for k, w in (prev.items() if isinstance(prev, dict) else ()):
        if not (isinstance(k, str) and isinstance(w, dict)):
            continue
        od, ost, n, do = _aw_t(w.get('od')), _aw_t(w.get('ost')), w.get('n'), w.get('do')
        tdo = _aw_t(do) if do is not None else None
        if (od is None or ost is None or ost < od or ost > tn or not isinstance(n, int) or isinstance(n, bool) or n < 1
                or (do is not None and (tdo is None or tdo < ost or tdo > tn))):
            continue
        e = {'od': w['od'], 'ost': w['ost'], 'n': n, 'do': do}
        if do is not None and w.get('zn') is True:
            e['zn'] = True
        p = _aw_seria(w.get('prev'), tn)
        if p and _aw_t(p[1]) <= od:
            e['prev'] = p
        out[k] = e
    for k, v in (ok.items() if isinstance(ok, dict) else ()):
        w = out.get(k)
        if v is False:
            if w and w['do'] is None:
                w['ost'] = now; w['n'] += 1
            else:
                e = {'od': now, 'ost': now, 'n': 1, 'do': None}
                c = ([[w['od'], w['do'], w['n']]] if w and not w.get('zn') else []) + ([w['prev']] if w and w.get('prev') else [])
                if c:   # v211: zamknięta seria nie znika przy nowej awarii — zostaje dłuższa z dwóch (ta i jej poprzednia)
                    e['prev'] = max(c, key=lambda s: (_aw_t(s[1]) - _aw_t(s[0]), s[1]))
                out[k] = e
        elif v is True and w and w['do'] is None:
            w['do'] = now
    for k in list(out):
        w = out[k]
        if w.get('prev') and tn - _aw_t(w['prev'][1]) > H48:
            del w['prev']
        if w['do'] is None and k not in (ok if isinstance(ok, dict) else {}) and tn - _aw_t(w['ost']) > datetime.timedelta(hours=AW_NIEOBECNA_H):
            w['do'] = now; w['zn'] = True
        if w['do'] is not None and tn - _aw_t(w['do']) > H48:
            del out[k]
    if len(out) > AW_MAX:
        out = dict(sorted(out.items(), key=lambda x: _aw_t(x[1]['ost']), reverse=True)[:AW_MAX])
    return out


NSDL_MONTHS = ('January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December')
OBCE_KEEP = 300           # tyle ostatnich dni trzyma plik (historia narasta z przebiegu na przebieg; v89: 300 — tło dla TRENDÓW)
NSDL_CATS = {'equity': 'eq', 'debt-general limit': 'debt', 'debt-vrr': 'debt', 'debt-far': 'debt', 'hybrid': 'hyb',
             'mutual funds': 'mf', 'aifs': 'aif'}


def _nsdl_num(tok):
    """'1,705.34' → 1705.34; '(126.43)' → -126.43 (nawias = minus); brak → None."""
    t = str(tok).replace(',', '').strip()
    neg = t.startswith('(') and t.endswith(')')
    try:
        v = float(t.strip('()').strip())
    except ValueError:
        return None
    return -v if neg else v


def parse_nsdl_html(text, totals=None):
    """Tabela NSDL „Daily Trends in FPI Investments” → [[data, akcje, dług, hybrydy, razem, INR za USD], ...] w mln USD.
    Dług = Debt-General Limit + Debt-VRR + Debt-FAR; tabela instrumentów pochodnych (dalej na stronie) pominięta.
    v95: bloki „Total for <miesiąc>” i „Total for <rok>” (archiwum) kończą ostatni dzień — ich „Total” trafia do `totals`, nie do dnia."""
    t = re.sub(r'<script.*?</script>|<style.*?</style>', '', text, flags=re.S | re.I)
    days, date, cat, blk = {}, None, None, None
    for r in re.findall(r'<tr[^>]*>(.*?)</tr>', t, flags=re.S | re.I):
        cells = [re.sub(r'\s+', ' ', _html.unescape(re.sub(r'<[^>]+>', '', c))).strip()
                 for c in re.findall(r'<t[dh][^>]*>(.*?)</t[dh]>', r, flags=re.S | re.I)]
        if not any(cells):
            continue
        if any('derivative' in c.lower() for c in cells):
            break
        if cells[0].lower().startswith('total for'):
            date, cat, blk = None, None, cells[0][9:].strip().lower()   # v95: suma miesiąca albo roku — nie dopisujemy jej do ostatniego dnia
            continue
        if date is None and blk and cells[0].lower() == 'total' and len(cells) >= 5:
            if totals is not None:
                totals.setdefault(blk, _nsdl_num(cells[4]))
            continue
        if re.match(r'^\d{2}-[A-Za-z]{3}-\d{4}$', cells[0]):
            date = datetime.datetime.strptime(cells[0], '%d-%b-%Y').date().isoformat(); cells = cells[1:]; cat = None; blk = None
            d = days.setdefault(date, {})
            if cells and cells[-1].lower().startswith('rs'):
                m = re.search(r'(\d+(?:\.\d+)?)', cells[-1])
                if m:
                    d['inr'] = float(m.group(1))
                cells = cells[:-1]
        if date is None or not cells:
            continue
        d = days[date]
        if cells[0].lower() == 'total' and len(cells) >= 5:
            d['tot'] = _nsdl_num(cells[4]); continue
        if cells[0].lower() in NSDL_CATS:
            cat = NSDL_CATS[cells[0].lower()]; cells = cells[1:]
        if cells and cells[0].lower() == 'sub-total' and cat and len(cells) >= 5:
            v = _nsdl_num(cells[4])
            if v is not None:
                d[cat] = round(d.get(cat, 0.0) + v, 2)
    out = [[k, days[k].get('eq'), days[k].get('debt'), days[k].get('hyb'), days[k].get('tot'), days[k].get('inr')]
           for k in sorted(days) if days[k].get('eq') is not None and days[k].get('tot') is not None]
    if not out:
        raise RuntimeError('brak dni w tabeli')
    return out


def parse_twse(j):
    """TWSE BFI82U (jeden dzień) → [data, zagraniczni, fundusze krajowe (SITC), dealerzy, razem] w mln TWD; brak sesji → None."""
    if not isinstance(j, dict) or j.get('stat') != 'OK' or not isinstance(j.get('data'), list):
        return None
    ds = str(j.get('date') or '')
    if not re.match(r'^\d{8}$', ds):
        return None
    fx = it = dl = tot = None
    for row in j['data']:
        if not isinstance(row, list) or len(row) < 4:
            continue
        name, v = str(row[0]).strip().lower(), _num(row[3])
        if v is None:
            continue
        if name.startswith('foreign'):
            fx = (fx or 0.0) + v          # inwestorzy zagraniczni (z Chin kontynentalnych) + zagraniczni dealerzy
        elif name.startswith('securities investment trust'):
            it = v
        elif name.startswith('dealers'):
            dl = (dl or 0.0) + v
        elif name.startswith('total'):
            tot = v
    if fx is None:
        return None
    m = lambda v: None if v is None else round(v / 1e6, 1)
    return [f'{ds[:4]}-{ds[4:6]}-{ds[6:]}', m(fx), m(it), m(dl), m(tot)]


def tw_dates(have, empty, now_tpe, first):
    """Dni robocze do pobrania z TWSE: brakujące w pliku, bez znanych dni bez sesji; dziś dopiero po 16:00 czasu Tajpej."""
    today = now_tpe.date(); out = []
    for i in range(35 if first else 10, -1, -1):
        d = today - datetime.timedelta(days=i)
        iso = d.isoformat()
        if d.weekday() >= 5 or iso in have or iso in empty or (d == today and now_tpe.hour < 16):
            continue
        out.append(iso)
    return out


def tw_back(have, empty, now_loc, skip=()):
    """v95: starsze dni robocze do uzupełnienia wstecz — od najnowszego, do TW_BACK_DAYS dni; bez dni znanych, bez dni bez sesji
    i bez dni z `skip` (już w kolejce albo odłożone na później)."""
    today = now_loc.date(); out = []
    for i in range(1, TW_BACK_DAYS + 1):
        d = today - datetime.timedelta(days=i)
        iso = d.isoformat()
        if d.weekday() >= 5 or iso in have or iso in empty or iso in skip:
            continue
        out.append(iso)
    return out


def _back_ok(t0, budget, cost):
    """v95.2: czy zmieści się jeszcze jedno zapytanie wstecz: czas od t0 + najdłuższy możliwy czas zapytania ≤ budżet,
    a cały przebieg nie trwa już dłużej niż BACK_LATE."""
    now = time.monotonic()
    if _RUN_T0[0] is not None and now - _RUN_T0[0] >= BACK_LATE:
        if not _BACK_LATE_NOTE[0]:
            _BACK_LATE_NOTE[0] = True
            META['notes'].append(f'historia wstecz pominięta w tym przebiegu: przebieg trwa już {now - _RUN_T0[0]:.0f} s (granica {BACK_LATE} s)')
        return False
    return now - t0 + cost <= budget


def _age_h(ts):
    """Godziny od chwili `ts` (ISO) do początku tego przebiegu (NOW); zły zapis → None."""
    try:
        return (datetime.datetime.fromisoformat(NOW) - datetime.datetime.fromisoformat(ts)).total_seconds() / 3600
    except (TypeError, ValueError):
        return None


def _twse_nodata(j):
    """v95: TWSE „No Data!” = dzień bez sesji; inna odpowiedź bez danych to błąd (ponowimy), nie święto."""
    return isinstance(j, dict) and str(j.get('stat') or '').strip().lower().startswith('no data')


def twd_rates(key):
    """FRED DEXTAUS (TWD za 1 USD, Fed H.10) → {data: kurs}; '.' = brak."""
    j = get_json(f'{FRED}?series_id=DEXTAUS&api_key={key}&file_type=json&sort_order=desc&limit={TW_FX_OBS}')
    out = {}
    for o in j.get('observations', []) if isinstance(j, dict) else []:
        v = _num(o.get('value'))
        if v and v > 0 and re.match(r'^\d{4}-\d{2}-\d{2}$', str(o.get('date', ''))):
            out[o['date']] = v
    return out


def _now_utc():
    return datetime.datetime.now(datetime.timezone.utc)   # osobno, żeby testy mogły ustawić czas


def _rate_for(rates, day):
    ks = [k for k in rates if k <= day] or []
    return (max(ks), rates[max(ks)]) if ks else (None, None)


def _rows(prev_part):
    return {r[0]: r for r in (prev_part or {}).get('d', []) if isinstance(r, list) and r and isinstance(r[0], str)}


def _ym_add(ym, k):
    y, m = int(ym[:4]), int(ym[5:7]) + k
    return f'{y + (m - 1) // 12:04d}-{(m - 1) % 12 + 1:02d}'


def nsdl_http(url, form=None, cookie='', timeout=30):
    """v95.2: archiwum NSDL — formularz i wynik w jednej sesji: ciasteczka z pobrania formularza (sesja ASP.NET, równoważenie
    obciążenia) idą razem z wysłaniem formularza. → (treść, ciasteczka)."""
    data = None if form is None else urllib.parse.urlencode(form).encode()
    h = {'User-Agent': 'CapitalFlowAI-collector/1.0'}
    if cookie:
        h['Cookie'] = cookie
    if data is not None:
        h.update({'Content-Type': 'application/x-www-form-urlencoded', 'Referer': url})
    with urllib.request.urlopen(urllib.request.Request(url, data=data, headers=h), timeout=timeout) as r:
        got = '; '.join(c.split(';', 1)[0].strip() for c in (r.headers.get_all('Set-Cookie') or []) if '=' in c.split(';', 1)[0])
        return r.read(), got or cookie


def nsdl_month(ym):
    """v95: archiwum NSDL — wszystkie dni raportu jednego miesiąca (ta sama tabela co bieżący miesiąc). Suma dni musi się zgadzać
    z sumą miesiąca podaną przez NSDL pod tabelą (±1 mln USD) — inaczej miesiąc odrzucony (ponowimy jutro)."""
    body, ck = nsdl_http(NSDL_ARCH, timeout=15)
    page = body.decode('utf-8', 'replace')
    form = {}
    for n in ('__VIEWSTATE', '__VIEWSTATEGENERATOR', '__EVENTVALIDATION'):
        m = re.search(r'name="%s"[^>]*value="([^"]*)"' % n, page)
        if m:
            form[n] = _html.unescape(m.group(1))
    if '__VIEWSTATE' not in form or '__EVENTVALIDATION' not in form:
        raise RuntimeError('brak pól formularza archiwum')
    y, mo = int(ym[:4]), int(ym[5:7])
    last = datetime.date(y + mo // 12, mo % 12 + 1, 1) - datetime.timedelta(days=1)
    form.update({'__EVENTTARGET': 'btnSubmit1', '__EVENTARGUMENT': '', 'hdnDate': f'{last.day:02d}-{NSDL_MONTHS[mo - 1][:3]}-{y}',
                 'HdnValexceldata': '', 'hdnFlag': ''})
    tot = {}
    rows = [r for r in parse_nsdl_html(nsdl_http(NSDL_ARCH, form, ck, timeout=30)[0].decode('utf-8', 'replace'), tot)
            if r[0][:7] == ym]
    if not rows:
        raise RuntimeError('brak dni tego miesiąca')
    mt = tot.get(NSDL_MONTHS[mo - 1].lower())
    if mt is None:
        raise RuntimeError('brak sumy miesiąca pod tabelą')
    s = sum(r[4] for r in rows)
    if abs(s - mt) > 1 + 0.001 * abs(mt):
        raise RuntimeError(f'suma dni {s:.2f} ≠ suma miesiąca {mt:.2f} mln USD')
    return rows


def nsdl_part(prev_in):
    rows = parse_nsdl_html(get_bytes(NSDL_URL, timeout=60).decode('utf-8', 'replace'))
    m = _rows(prev_in)
    want = [_ym_add(rows[-1][0][:7], -i) for i in range(1, NSDL_ARCH_MONTHS + 1)]   # v95: pełne miesiące przed bieżącym
    arch = {x for x in ((prev_in or {}).get('arch') or []) if isinstance(x, str) and x in want}
    afail = {k: v for k, v in ((prev_in or {}).get('afail') or {}).items()          # v95.2: miesiąc odrzucony dziś — ponowimy jutro
             if k in want and isinstance(v, str) and v[:10] == NOW[:10]}
    t0 = time.monotonic(); tried = 0
    for ym in [x for x in want if x not in arch and x not in afail]:
        if tried >= NSDL_ARCH_MAX or not _back_ok(t0, NSDL_BACK_BUDGET, 45):
            break                                        # reszta w następnym przebiegu
        tried += 1
        try:
            got = nsdl_month(ym)
        except (RuntimeError, ValueError, KeyError, IndexError) as e:   # zła treść: ten miesiąc jutro, starsze dalej (v95.2)
            afail[ym] = NOW; META['notes'].append(mask(f'NSDL archiwum {ym}: {e} — ponowimy jutro')); continue
        except Exception as e:                                          # sieć: przerwa do następnego przebiegu
            META['notes'].append(mask(f'NSDL archiwum {ym}: {e} — ponowimy w następnym przebiegu')); break
        m.update({r[0]: r for r in got}); arch.add(ym)      # archiwum = pełny, ostateczny miesiąc (zastępuje dni zebrane wcześniej)
    m.update({r[0]: r for r in rows})
    d = [m[k] for k in sorted(m)][-OBCE_KEEP:]
    return {'at': NOW, 'src': 'NSDL — Daily Trends in FPI Investments', 'url': NSDL_URL, 'unit': 'mln USD (przeliczenie NSDL)',
            'cols': ['data raportu', 'akcje', 'dług', 'hybrydy', 'razem', 'INR za USD'], 'asof': d[-1][0], 'arch': sorted(arch), **({'afail': afail} if afail else {}), 'd': d}


def twse_part(prev_tw, key):
    prev_tw = prev_tw if isinstance(prev_tw, dict) else {}
    have = {k: list(v) for k, v in _rows(prev_tw).items()}   # kopie — poprzedni plik nie jest zmieniany w miejscu
    now_tpe = _now_utc() + datetime.timedelta(hours=8)
    lim = (now_tpe.date() - datetime.timedelta(days=OBCE_EMPTY_DAYS)).isoformat()
    empty = {x for x in prev_tw.get('empty', []) if isinstance(x, str) and x >= lim}
    fails, bfails = [], []
    pend = {k: v for k, v in (prev_tw.get('pend') or {}).items() if isinstance(k, str) and k >= lim and _age_h(v) is not None}
    recent = tw_dates(set(have), empty, now_tpe, first=not have)[-TWSE_MAX:]
    # v197: ponowny odczyt ostatnich sesji — giełda poprawia liczby po pierwszej publikacji (dotąd dzień „w pliku” = nigdy więcej)
    chk = {k: v for k, v in (prev_tw.get('chk') or {}).items() if isinstance(k, str) and isinstance(v, str) and k in have}
    rtry = {k: v for k, v in (prev_tw.get('rtry') or {}).items() if isinstance(k, str) and isinstance(v, str) and k in have}   # v203: czas nieudanej próby
    ref = [k for k in sorted(have) if k not in recent and _d(k) and 0 <= (now_tpe.date() - _d(k)).days <= (TW_REFRESH_D if k in chk else TW_REFRESH_NEW)
           and (_age_h(chk.get(k)) is None or _age_h(chk[k]) >= TW_REFRESH_H)
           and (_age_h(rtry.get(k)) is None or _age_h(rtry[k]) >= TW_REFRESH_H)]   # v198: dzień bez chk do 14 dni — raz; v203: po błędzie — za 3 godz.
    rfails, zm = [], []
    wait = {k for k, v in pend.items() if _age_h(v) < TW_PEND_H}
    back = tw_back(set(have), empty, now_tpe, skip=set(recent) | wait)[:min(TW_BACK_MAX, max(0, TWSE_MAX - len(recent)))]   # v95: historia wstecz
    t0 = time.monotonic()
    for iso in recent + ref + back:
        old = iso in back
        again = iso in ref                               # v197: ponowny odczyt dnia, który już jest w pliku
        bad = bfails if old else (rfails if again else fails)
        if (old or again) and not _back_ok(t0, BACK_BUDGET, TWSE_SLEEP + TW_BACK_TIMEOUT):
            break                                        # ostatnie dni zawsze; ponowny odczyt (v203) i starsze — tylko w budżecie czasu (v95.1–v95.2)
        time.sleep(TWSE_SLEEP)
        try:
            u = TWSE_URL.format(d=iso.replace('-', ''))
            j = get_json(u, timeout=TW_BACK_TIMEOUT) if (old or again) else get_json(u)
            r = parse_twse(j)
        except Exception as e:
            bad.append(f'{iso}: {e}')
            if again:
                rtry[iso] = NOW                          # v203: następna próba za TW_REFRESH_H, nie co przebieg
            continue
        if again and (r is None or r[0] != iso):         # v197: „No Data!” albo inna data przy ponownym odczycie — poprzednie liczby, dzień NIE „bez sesji”
            rfails.append(f"{iso}: {str(j.get('stat'))[:60] if isinstance(j, dict) else 'nieczytelna odpowiedź'}"); rtry[iso] = NOW; continue
        if r is None:
            if iso < now_tpe.date().isoformat():
                if _twse_nodata(j) and (not old or iso in pend):
                    empty.add(iso); pend.pop(iso, None)   # dzień bez sesji (święto) — nie pytamy ponownie
                elif _twse_nodata(j):
                    pend[iso] = NOW     # v95.2: starszy dzień — święto dopiero po drugiej takiej odpowiedzi (≥ 12 h), nie po jednej awarii
                else:
                    bad.append(f"{iso}: {str(j.get('stat'))[:60] if isinstance(j, dict) else 'nieczytelna odpowiedź'}")   # v95: nie święto — ponowimy
            continue
        if again and have[r[0]][:5] != r[:5]:
            zm.append(iso)
        have[r[0]] = r[:5]; pend.pop(iso, None); chk[r[0]] = NOW; rtry.pop(r[0], None)
    if not have:
        raise RuntimeError('brak dni' + (f' ({fails[0]})' if fails else ''))
    if zm:
        META['notes'].append('TWSE: poprawione liczby sesji przy ponownym odczycie — ' + ', '.join(zm))
    if rfails:
        META['notes'].append(mask(f'TWSE ponowny odczyt: {len(rfails)} dni bez odpowiedzi, np. {rfails[0]} — zostają poprzednie liczby'))
    if fails:
        META['errors'].append(mask(f'TWSE: {len(fails)} dni bez odpowiedzi, np. {fails[0]}'))
    if bfails:
        META['notes'].append(mask(f'TWSE historia wstecz: {len(bfails)} dni bez odpowiedzi, np. {bfails[0]} — ponowimy'))
    d = [have[k] for k in sorted(have)][-OBCE_KEEP:]
    rates = {}
    if key:
        try:
            rates = twd_rates(key)
        except Exception as e:
            META['errors'].append(mask(f'TWSE kurs FRED DEXTAUS: {e}'))
    old = _rows(prev_tw)
    for r in d:
        rd, rt = _rate_for(rates, r[0])
        if rt and r[1] is not None:
            r[5:] = [round(r[1] / rt, 1), rd]
        elif r[0] in old and len(old[r[0]]) >= 7 and old[r[0]][1] == r[1]:
            r[5:] = old[r[0]][5:7]          # bez nowego kursu zostaje poprzednie przeliczenie (v197: tylko przy tej samej liczbie zagranicy)
        else:
            r[5:] = [None, None]
    keep = {r[0] for r in d}
    chk = {k: v for k, v in chk.items() if k in keep and _d(k) and (now_tpe.date() - _d(k)).days <= TW_REFRESH_NEW + 1}   # v198: dłużej niż okno „raz”
    rtry = {k: v for k, v in rtry.items() if k in keep and _d(k) and (now_tpe.date() - _d(k)).days <= TW_REFRESH_NEW + 1}
    return {'at': NOW, 'src': 'TWSE — Trading Value of Foreign & Other Investors (BFI82U)', **({'chk': chk} if chk else {}), **({'rtry': rtry} if rtry else {}),
            'url': 'https://www.twse.com.tw/en/trading/foreign/bfi82u.html', 'unit': 'mln TWD; ≈ mln USD kursem Fed H.10 (FRED DEXTAUS)',
            'cols': ['data', 'zagraniczni', 'fundusze krajowe', 'dealerzy', 'razem', '≈ mln USD (zagraniczni)', 'data kursu'],
            'asof': d[-1][0], 'empty': sorted(empty), **({'pend': pend} if pend else {}), 'd': d}


# v67: HKEX Stock Connect — dzienne kupno i sprzedaż akcji w Hongkongu przez inwestorów z Chin kontynentalnych (southbound)
HKEX_URL = 'https://www.hkex.com.hk/eng/csm/DailyStat/data_tab_daily_{d}e.js'
HKEX_SLEEP = 1.0


def parse_hkex(text):
    """Plik dzienny HKEX (JS `tabData = [...]`) → [data, netto, kupno, sprzedaż, liczba rynków] w mln HKD (Szanghaj + Shenzhen
    → Hongkong); dzień bez sesji albo bez kupna/sprzedaży → None. Northbound od 2024 bez podziału na kupno i sprzedaż — pomijamy."""
    t = str(text)
    try:
        j = json.loads(t[t.index('['):t.rindex(']') + 1])
    except (ValueError, json.JSONDecodeError):
        return None
    date, buy, sell, n, sb, bad = None, 0.0, 0.0, 0, 0, 0
    for m in j if isinstance(j, list) else []:
        if not isinstance(m, dict) or 'southbound' not in str(m.get('market', '')).lower():
            continue
        sb += 1
        if not m.get('tradingDay'):
            continue
        try:
            tb = m['content'][0]['table']; d = dict(zip(tb['schema'][0], [x['td'][0][0] for x in tb['tr']]))
        except (KeyError, IndexError, TypeError):
            bad += 1; continue
        b, s = _num(d.get('Buy Turnover')), _num(d.get('Sell Turnover'))
        if b is None or s is None or not re.match(r'^\d{4}-\d{2}-\d{2}$', str(m.get('date', ''))):
            bad += 1; continue
        if b == 0 and s == 0:
            continue      # v73: rynek bez handlu (święto w Chinach kontynentalnych przy otwartym Hongkongu: tradingDay 1, obrót 0,00)
        date = m['date']; buy += b; sell += s; n += 1
    if bad:
        return None       # v73: nieczytelna tabela rynku w dniu sesji = nieczytelny plik (ponowimy), nie dzień z częścią rynków
    if not n:
        return False if sb else None   # v69: False = dzień bez sesji (plik z tradingDay 0), None = nieczytelny plik
    return [date, round(buy - sell, 2), round(buy, 2), round(sell, 2), n]


def fred_rates(key, sid, limit=60):
    """FRED — kurs (dzienny albo średnia miesięczna, zależnie od serii; jednostek waluty za 1 USD, Fed H.10) → {data: kurs}; '.' = brak."""
    j = get_json(f'{FRED}?series_id={sid}&api_key={key}&file_type=json&sort_order=desc&limit={limit}')
    out = {}
    for o in j.get('observations', []) if isinstance(j, dict) else []:
        v = _num(o.get('value'))
        if v and v > 0 and re.match(r'^\d{4}-\d{2}-\d{2}$', str(o.get('date', ''))):
            out[o['date']] = v
    return out


def hkex_part(prev_hk, key):
    prev_hk = prev_hk if isinstance(prev_hk, dict) else {}
    have = {k: list(v) for k, v in _rows(prev_hk).items()}
    now_hk = _now_utc() + datetime.timedelta(hours=8)
    lim = (now_hk.date() - datetime.timedelta(days=OBCE_EMPTY_DAYS)).isoformat()
    empty = {x for x in prev_hk.get('empty', []) if isinstance(x, str) and x >= lim}
    fails, bfails, nf_new = [], [], []
    nf = {k: v for k, v in (prev_hk.get('nf') or {}).items()                  # v95.2: brak pliku za starszy dzień — pytamy znowu po tygodniu
          if isinstance(k, str) and _age_h(v) is not None and _age_h(v) < 24 * HK_NF_DAYS}
    for k in [k for k, r in have.items() if len(r) > 3 and r[2] == 0 and r[3] == 0]:
        del have[k]; empty.add(k)   # v73: dawny zapis „sesja z zerem” w dniu bez handlu → dzień bez sesji
    recent = tw_dates(set(have), empty, now_hk, first=not have)[-TWSE_MAX:]   # te same zasady dni co dla Tajwanu (UTC+8)
    back = tw_back(set(have), empty, now_hk, set(recent) | set(nf))[:min(TW_BACK_MAX, max(0, TWSE_MAX - len(recent)))]   # v95: historia wstecz, od najnowszego
    t0 = time.monotonic(); miss = 0
    for iso in recent + back:
        old = iso in back
        if old and (miss >= 3 or not _back_ok(t0, BACK_BUDGET, HKEX_SLEEP + TW_BACK_TIMEOUT)):
            break                                        # 3 braki pliku z rzędu albo koniec budżetu czasu — reszta w następnym przebiegu
        time.sleep(HKEX_SLEEP)
        try:
            r = parse_hkex(get_bytes(HKEX_URL.format(d=iso.replace('-', '')), timeout=TW_BACK_TIMEOUT if old else 30).decode('utf-8', 'replace'))
        except urllib.error.HTTPError as e:
            if old and e.code == 404:
                nf[iso] = NOW; nf_new.append(iso); miss += 1; continue   # v95.2: brak pliku za starszy dzień — bez stałej granicy
            if e.code != 404 or iso < now_hk.date().isoformat():
                (bfails if old else fails).append(f'{iso}: HTTP {e.code}')   # v69: 404 za dzień roboczy z przeszłości = brak pliku (święta mają plik) — ponowimy;
                # v329 (Z3-04): starszy dzień (historia wstecz) — notatka „ponowimy”, nie błąd części (jak przy innych wyjątkach i w TWSE)
            continue
        except Exception as e:
            (bfails if old else fails).append(f'{iso}: {e}'); continue
        if old:
            miss = 0
        if r is False:
            empty.add(iso); continue      # v69: święto w Hongkongu — plik z tradingDay 0
        if r is None:
            (bfails if old else fails).append(f'{iso}: nieczytelny plik'); continue
        have[r[0]] = r[:5]
    if not have:
        raise RuntimeError('brak dni' + (f' ({fails[0]})' if fails else ''))
    if fails:
        META['errors'].append(mask(f'HKEX: {len(fails)} dni bez odpowiedzi, np. {fails[0]}'))
    if bfails:
        META['notes'].append(mask(f'HKEX historia wstecz: {len(bfails)} dni bez odpowiedzi, np. {bfails[0]} — ponowimy'))
    if nf_new:
        META['notes'].append(mask(f'HKEX historia wstecz: brak pliku za {len(nf_new)} dni, np. {nf_new[0]} — ponowimy za tydzień'))
    d = [have[k] for k in sorted(have)][-OBCE_KEEP:]
    rates = {}
    if key:
        try:
            rates = fred_rates(key, 'DEXHKUS', limit=TW_FX_OBS)
        except Exception as e:
            META['errors'].append(mask(f'HKEX kurs FRED DEXHKUS: {e}'))
    old = _rows(prev_hk)
    for r in d:
        rd, rt = _rate_for(rates, r[0])
        if rt and r[1] is not None:
            r[5:] = [round(r[1] / rt, 1), rd]
        elif r[0] in old and len(old[r[0]]) >= 7:
            r[5:] = old[r[0]][5:7]
        else:
            r[5:] = [None, None]
    return {'at': NOW, 'src': 'HKEX — Stock Connect daily statistics (Southbound: Shanghai + Shenzhen → Hong Kong)',
            'url': 'https://www.hkex.com.hk/Mutual-Market/Stock-Connect/Statistics/Historical-Daily',
            'unit': 'mln HKD; ≈ mln USD kursem Fed H.10 (FRED DEXHKUS)',
            'cols': ['data', 'netto', 'kupno', 'sprzedaż', 'rynki', '≈ mln USD (netto)', 'data kursu'],
            'asof': d[-1][0], 'empty': sorted(empty), **({'nf': nf} if nf else {}), 'd': d}


# v71: Banco Central do Brasil (SGS, bez klucza) — „câmbio contratado”: dzienne przepływy dolarów przez rynek walutowy Brazylii
BCB_URL = 'https://api.bcb.gov.br/dados/serie/bcdata.sgs.{id}/dados?formato=json&dataInicial={a}&dataFinal={b}'   # „ultimos/N” ma limit 20
BCB_SERIES = (('fin', 13970), ('fin_buy', 13968), ('fin_sell', 13969), ('com', 13967), ('tot', 13961))
BCB_DAYS = 400    # dni kalendarzowe wstecz (v95: ok. 275 dni roboczych — pełna historia dla TRENDÓW od pierwszego przebiegu)


# v127.2: zapas — oficjalna usługa SOAP SGS tego samego banku (03.10.2026: host api.bcb.gov.br zniknął z DNS, NXDOMAIN)
BCB_WS = 'https://www3.bcb.gov.br/wssgs/services/FachadaWSSGS'
_BCB_WS = {'on': False, 'chw': []}   # w tym przebiegu API JSON już zawiodło na poziomie połączenia → kolejne serie od razu z SOAP;
                                     # v256: 'chw' — serie z SOAP po chwilowym błędzie API JSON, 'ws_zle' — SOAP w tym przebiegu zawiódł
BCB_CHW_MAX = 3   # v256: po tylu seriach z chwilowym błędem API JSON w przebiegu — dalsze serie od razu z SOAP
BCB_PRZERWA_DNI = 3       # v416: przerwa po stronie banku przy ostatnim udanym pobraniu młodszym niż tyle dób = poprzednie dane + notatka (⚠️), nie błąd (❌)
BCB_PRZERWA_PONOW_MIN = 30   # v416: po przerwie kolejne zapytanie do banku nie wcześniej niż po tylu minutach (przebieg co 10 min)


class BcbPrzerwa(RuntimeError):
    """v416: bank nie podaje danych — interfejs odrzuca zapytanie (strona z odmową zamiast JSON-u, HTTP 5xx, brak połączenia) i zapas SOAP też.
    Odróżnione od błędu danych (zły kształt, Fault SOAP, zła seria): tylko przerwa po stronie banku może zostać zastąpiona poprzednimi danymi."""


def _bcb_przerwa_blad(e):
    """v416: czy błąd pojedynczej serii to przerwa po stronie banku (nie błąd danych)."""
    if isinstance(e, BcbPrzerwa) or _bcb_conn_err(e):
        return True
    return isinstance(e, urllib.error.HTTPError) and 500 <= e.code <= 599


def _bcb_opis_json(e):
    """v416: przyczyna odpowiedzi, która nie jest JSON-em: strona HTML z odmową (bramka banku), pusta albo inna treść; bez treści błędu — jak dotąd."""
    doc = getattr(e, 'doc', None)
    if not isinstance(doc, str):
        return f'odpowiedź pusta albo nie JSON: {str(e)[:40]}'
    if doc.lstrip()[:1] == '<':
        return 'bramka banku odrzuciła zapytanie (strona z odmową zamiast danych)'
    return 'odpowiedź pusta' if not doc.strip() else f'odpowiedź nie jest JSON-em: {str(e)[:40]}'


def bcb_przerwa_dozwolona(e, pp, at=None, now=None):
    """v416: czy błąd e to przerwa po stronie banku, a poprzednia część pp (z danymi) jest z ostatniego udanego pobrania młodszego niż BCB_PRZERWA_DNI dób."""
    if not isinstance(e, BcbPrzerwa) or not isinstance(pp, dict) or not pp.get('d') and not pp.get('s'):
        return False
    t0, t1 = _ix_dt(at if at is not None else pp.get('at')), _ix_dt(now or NOW)
    return t0 is not None and t1 is not None and 0 <= (t1 - t0).total_seconds() < BCB_PRZERWA_DNI * 86400


def bcb_przerwa_wynik(pp, e):
    """v416: poprzednia część bez zmian danych + znacznik przerwy (od kiedy, ostatnia próba, ile prób, przyczyna)."""
    m = pp.get('przerwa') if isinstance(pp.get('przerwa'), dict) else {}
    n = m.get('n') if isinstance(m.get('n'), int) else 0
    return {**pp, 'przerwa': {'od': m.get('od') or NOW, 'ost': NOW, 'n': n + 1, 'powod': str(e)[:160]}}


def bcb_przerwa_odczekaj(pp, prev):
    """v416: czy po poprzedniej przerwie banku wolno jeszcze poczekać (ostatnia próba młodsza niż BCB_PRZERWA_PONOW_MIN min, a dane nie starsze niż BCB_PRZERWA_DNI dób)."""
    if not isinstance(pp, dict) or (prev.get('ok') or {}).get('br') is not False or not isinstance(pp.get('przerwa'), dict):
        return False
    t0, t1, ta = _ix_dt(pp['przerwa'].get('ost')), _ix_dt(NOW), _ix_dt(pp.get('at'))
    if t0 is None or t1 is None or ta is None:
        return False
    return 0 <= (t1 - t0).total_seconds() < BCB_PRZERWA_PONOW_MIN * 60 and 0 <= (t1 - ta).total_seconds() < BCB_PRZERWA_DNI * 86400


def bcb_przerwa_nota(pp):
    """v416: notatka o przerwie banku — poprzednie dane z datą (dzień danych i chwila pobrania) i zasada trzech dób."""
    m = pp.get('przerwa') or {}
    return (f"BCB: bank nie podaje danych od {str(m.get('od') or '—')[:16].replace('T', ' ')} UTC ({m.get('powod') or 'brak odpowiedzi'}) — zostają dane z dnia "
            f"{pp.get('asof') or '—'} (pobrane {str(pp.get('at') or '—')[:16].replace('T', ' ')} UTC); po {BCB_PRZERWA_DNI} dobach od pobrania będzie to błąd")


def _bcb_conn_err(e):
    """Awaria połączenia (DNS, brak trasy, czas, TLS, zerwane połączenie) — nie odpowiedź HTTP z kodem błędu."""
    if isinstance(e, urllib.error.HTTPError):
        return False
    return isinstance(e, (urllib.error.URLError, OSError, TimeoutError))


def _bcb_ws_post(xml, timeout=60):
    req = urllib.request.Request(BCB_WS, data=xml.encode('utf-8'),
                                 headers={'User-Agent': 'CapitalFlowAI-collector/1.0', 'Content-Type': 'text/xml; charset=utf-8', 'SOAPAction': '""'})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read()


def _bcb_ws_rows(raw):
    """Odpowiedź getValoresSeriesXML → [{'data': 'dd/mm/yyyy', 'valor': '…'}] jak z API JSON. Daty usługi: dzienne 'd/m/yyyy',
    miesięczne 'm/yyyy' (→ pierwszy dzień miesiąca). Wiersz zablokowany albo bez daty/wartości — pominięty (nigdy 0)."""
    s = raw.decode('utf-8', 'replace') if isinstance(raw, (bytes, bytearray)) else str(raw)
    m = re.search(r'<getValoresSeriesXMLReturn[^>]*>(.*?)</getValoresSeriesXMLReturn>', s, re.S)
    if not m:
        f = re.search(r'<faultstring>(.*?)</faultstring>', s, re.S)
        raise RuntimeError('SOAP: ' + (_html.unescape(f.group(1)).strip()[:120] if f else 'nieznany kształt odpowiedzi'))
    inner = _html.unescape(m.group(1))
    out = []
    for it in re.findall(r'<ITEM>(.*?)</ITEM>', inner, re.S):
        dm = re.search(r'<DATA>\s*([^<]*?)\s*</DATA>', it)
        vm = re.search(r'<VALOR>\s*([^<]*?)\s*</VALOR>', it)
        if not dm or not vm or re.search(r'<BLOQUEADO>\s*true\s*</BLOQUEADO>', it, re.I):
            continue
        p = dm.group(1).split('/')
        try:
            if len(p) == 3:
                d = f'{int(p[0]):02d}/{int(p[1]):02d}/{int(p[2]):04d}'
            elif len(p) == 2:
                d = f'01/{int(p[0]):02d}/{int(p[1]):04d}'
            else:
                continue
        except ValueError:
            continue
        if vm.group(1) != '':
            out.append({'data': d, 'valor': vm.group(1)})
    return out


def _bcb_ws(sid, a, b):
    """Jedna seria SGS z usługi SOAP (daty a, b jak w API JSON: 'dd/mm/yyyy')."""
    xml = ('<?xml version="1.0" encoding="UTF-8"?><soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" '
           'xmlns:pub="http://publico.ws.casosdeuso.sgs.pec.bcb.gov.br" xmlns:soapenc="http://schemas.xmlsoap.org/soap/encoding/" '
           'xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema"><soapenv:Body>'
           f'<pub:getValoresSeriesXML><in0 soapenc:arrayType="xsd:long[1]" xsi:type="soapenc:Array"><item>{int(sid)}</item></in0>'
           f'<in1>{a}</in1><in2>{b}</in2></pub:getValoresSeriesXML></soapenv:Body></soapenv:Envelope>')
    return _bcb_ws_rows(_bcb_ws_post(xml))


def _bcb_chwilowy(e):
    """v256: chwilowy błąd API JSON jednej serii — odpowiedź HTTP 5xx (06.10.2026: 502 Bad Gateway raz dla jednej, raz dla innej serii)
    albo treść, która nie jest JSON-em (pusta odpowiedź: „Expecting value”). Odpowiedź 4xx (zła seria, zły zakres dat) — nie: zapas by nie pomógł."""
    if isinstance(e, urllib.error.HTTPError):
        return 500 <= e.code <= 599
    return isinstance(e, ValueError)


def _bcb_get(sid, a, b):
    """v127.2: seria SGS — API JSON, a przy awarii połączenia usługa SOAP banku (jedna notatka na przebieg; dalsze serie od razu z SOAP).
    v256: chwilowy błąd API JSON jednej serii (HTTP 5xx, pusta odpowiedź) → ta seria z SOAP, reszta nadal z API JSON (te same liczby —
    06.10.2026 sprawdzone na 13968, 13970 i 22936); po BCB_CHW_MAX takich seriach w przebiegu dalsze od razu z SOAP. SOAP też zawiedzie →
    błąd z obiema przyczynami, a dalsze chwilowe błędy w tym przebiegu już bez próby SOAP (najwyżej jedno czekanie na SOAP)."""
    if _BCB_WS.get('json_zle'):   # v263 (przegląd v261): API JSON i SOAP w tym przebiegu nie odpowiadają — dalsze serie bez czekania
        raise BcbPrzerwa(f"API JSON i zapas SOAP w tym przebiegu niedostępne ({_BCB_WS['json_zle']})")
    if not _BCB_WS['on']:
        try:
            return get_json(BCB_URL.format(id=sid, a=a, b=b))
        except Exception as e:
            if _bcb_chwilowy(e):
                pw = str(e)[:60] if isinstance(e, urllib.error.HTTPError) else _bcb_opis_json(e)   # v416: strona z odmową nazwana wprost
                if _BCB_WS.get('ws_zle'):
                    raise BcbPrzerwa(f'{pw}; zapas SOAP w tym przebiegu niedostępny ({_BCB_WS["ws_zle"]})') from e
                try:
                    rows = _bcb_ws_raz(sid, a, b)
                except Exception as e2:
                    raise (BcbPrzerwa if _bcb_przerwa_blad(e2) else RuntimeError)(f'{pw}; zapas SOAP: {str(e2)[:90]}') from e
                ch = _BCB_WS.setdefault('chw', [])
                ch.append((str(sid), pw))
                if len(ch) >= BCB_CHW_MAX:
                    _BCB_WS['on'] = True
                    META['notes'].append(mask(f'BCB: API JSON z błędami dla {len(ch)} serii w tym przebiegu — dalsze serie od razu z usługi SOAP tego samego banku'))
                return rows
            if not _bcb_conn_err(e):
                raise
            if _BCB_WS.get('ws_zle'):   # v261: API JSON i SOAP nie odpowiadają — bez przełączania i bez czekania
                _BCB_WS['json_zle'] = str(e)[:90]   # v263: zapamiętane — dalsze serie bez kolejnego czekania na API JSON
                raise BcbPrzerwa(f'{str(e)[:90]}; zapas SOAP w tym przebiegu niedostępny ({_BCB_WS["ws_zle"]})') from e
            _BCB_WS['on'] = True
            META['notes'].append(mask(f'BCB: API JSON nie odpowiada ({str(e)[:90]}) — serie z usługi SOAP tego samego banku'))
    return _bcb_ws_raz(sid, a, b)


def _bcb_ws_raz(sid, a, b):
    """v261 (przegląd v256): SOAP z pamięcią awarii usługi — po pierwszej awarii połączenia (czas, DNS, TLS) albo odpowiedzi 5xx w przebiegu
    kolejne serie od razu z błędem: najwyżej jedno czekanie na SOAP, także po przełączeniu wszystkich serii. Błąd jednej serii (Fault SOAP)
    usługi nie wyłącza."""
    if _BCB_WS.get('ws_zle'):
        raise BcbPrzerwa(f'zapas SOAP w tym przebiegu niedostępny ({_BCB_WS["ws_zle"]})')
    try:
        rows = _bcb_ws(sid, a, b)
    except Exception as e:
        if _bcb_conn_err(e) or (isinstance(e, urllib.error.HTTPError) and e.code >= 500):
            _BCB_WS['ws_zle'] = str(e)[:90]
        raise
    _BCB_WS['soap_ok'] = _BCB_WS.get('soap_ok', 0) + 1   # v263: ile serii naprawdę przyszło z SOAP (ślad 'soap' w części tylko wtedy)
    return rows


def _bcb_date(s):
    m = re.match(r'^(\d{2})/(\d{2})/(\d{4})$', str(s or '').strip())
    return f'{m.group(3)}-{m.group(2)}-{m.group(1)}' if m else None


# v79: Brazylia — miesięczny bilans płatniczy (bank centralny, SGS): kapitał zagraniczny napływający do Brazylii (pasywa), mln USD
BCB_BOP = (('fdi', 22885), ('pi', 22924), ('pi_eq', 22927), ('pi_fund', 22936), ('pi_debt', 22939), ('oi', 22971),
           ('cb_dep', 22986), ('cb_loan', 23001), ('sdr', 23042))   # v81: pozycje banku centralnego i SDR — strona odejmuje je od pozostałych


def bcb_bop(prev_m):
    """SGS (miesięcznie) → [[YYYY-MM, bezpośrednie, portfelowe, akcje, fundusze, obligacje, pozostałe]] w mln USD, 25 miesięcy.
    Seria bez odpowiedzi zostawia stare wartości swojej kolumny (nowe miesiące: None, nigdy 0); bez żadnego miesiąca = błąd."""
    now_br = _now_utc() - datetime.timedelta(hours=3)
    a, b = f'01/{now_br.month:02d}/{now_br.year - 2}', now_br.strftime('%d/%m/%Y')
    got, fails = {}, []
    for name, sid in BCB_BOP:
        try:
            j = _bcb_get(sid, a, b)   # v127.2: z zapasem SOAP przy awarii połączenia
            if not isinstance(j, list):
                raise RuntimeError('nieznany kształt odpowiedzi')
            for r in j:
                d = _bcb_date(r.get('data')) if isinstance(r, dict) else None
                v = _num(r.get('valor')) if d else None
                if d and v is not None and v == v and abs(v) != float('inf'):
                    got.setdefault(d[:7], {})[name] = round(v, 1)
        except Exception as e:
            fails.append(f'{sid}: {e}')
    if not got:
        raise RuntimeError('brak miesięcy' + (f' ({fails[0]})' if fails else ''))
    have = {r[0]: list(r) for r in (prev_m or []) if isinstance(r, list) and r and isinstance(r[0], str)}
    cols = [n for n, _ in BCB_BOP]
    for m, vals in got.items():
        old = have.get(m) or []
        have[m] = [m] + [vals[c] if c in vals else (old[i + 1] if len(old) > i + 1 else None) for i, c in enumerate(cols)]
    if fails:
        META['errors'].append(mask(f'BCB bilans płatniczy: {len(fails)} serie bez odpowiedzi, np. {fails[0]}'))
    rows = [have[k] for k in sorted(have)][-25:]
    bad = [r[0] for r in rows if None not in r[2:6] and abs(r[2] - r[3] - r[4] - r[5]) > 1]
    if bad:
        META['notes'].append('BCB: portfelowe ≠ akcje + fundusze + obligacje w miesiącach: ' + ', '.join(bad))
    return rows


def bcb_part(prev_br):
    """BCB SGS → [data, finansowy saldo, kupno, sprzedaż, handlowy saldo, razem] w mln USD. Każda seria osobno: seria bez odpowiedzi
    zostawia stare wartości swojej kolumny, a nowe dni mają tam None (nigdy 0). Bez żadnego nowego dnia = błąd (zostaje poprzednia część)."""
    have = {k: list(v) for k, v in _rows(prev_br).items()}
    got, fails, przerwy = {}, [], []   # v416: przerwy — czy porażka serii to przerwa po stronie banku
    _BCB_WS['chw'] = []; _BCB_WS.pop('ws_zle', None)   # v256: liczniki chwilowych błędów API JSON — od nowa w każdym przebiegu
    _BCB_WS.pop('json_zle', None); _BCB_WS['soap_ok'] = 0   # v263
    now_br = _now_utc() - datetime.timedelta(hours=3)
    a, b = (now_br - datetime.timedelta(days=BCB_DAYS)).strftime('%d/%m/%Y'), now_br.strftime('%d/%m/%Y')
    for name, sid in BCB_SERIES:
        try:
            j = _bcb_get(sid, a, b)   # v127.2: z zapasem SOAP przy awarii połączenia
            if not isinstance(j, list):
                raise RuntimeError('nieznany kształt odpowiedzi')
            for r in j:
                d = _bcb_date(r.get('data')) if isinstance(r, dict) else None
                v = _num(r.get('valor')) if d else None
                if d and v is not None and v == v and abs(v) != float('inf'):
                    got.setdefault(d, {})[name] = round(v, 2)
        except Exception as e:
            fails.append(f'{sid}: {e}'); przerwy.append(_bcb_przerwa_blad(e))
    if not got:
        raise (BcbPrzerwa if fails and all(przerwy) else RuntimeError)('brak dni' + (f' ({fails[0]})' if fails else ''))   # v416: tylko przerwa banku może zostać zastąpiona poprzednimi danymi
    cols = [n for n, _ in BCB_SERIES]
    for d, vals in got.items():
        old = have.get(d) or []
        have[d] = [d] + [vals[c] if c in vals else (old[i + 1] if len(old) > i + 1 else None) for i, c in enumerate(cols)]
    if fails:
        META['errors'].append(mask(f'BCB: {len(fails)} serie bez odpowiedzi, np. {fails[0]}'))
    d = [have[k] for k in sorted(have)][-OBCE_KEEP:]
    try:   # v79: miesięczny bilans płatniczy — jego awaria nie zatrzymuje części dziennej
        mrows = bcb_bop((prev_br or {}).get('m'))
    except Exception as e:
        mrows = (prev_br or {}).get('m'); META['errors'].append(mask(f'BCB bilans płatniczy: {e}'))
    if _BCB_WS.get('chw'):   # v256: serie z SOAP po chwilowym błędzie API JSON — jedna notatka na przebieg (części dzienna i miesięczna)
        META['notes'].append(mask(f"BCB: API JSON chwilowo bez danych serii {', '.join(s for s, _ in _BCB_WS['chw'])} (np. {_BCB_WS['chw'][0][1]})"
                                  ' — te serie z usługi SOAP tego samego banku'))
    extra = {'m': mrows, 'm_cols': ['miesiąc', 'bezpośrednie', 'portfelowe', 'akcje', 'fundusze', 'obligacje', 'pozostałe',
                                    'bank centralny: waluty i depozyty', 'bank centralny: kredyty', 'SDR'],
             'm_src': 'Banco Central do Brasil — SGS, balanço de pagamentos (22885, 22924, 22927, 22936, 22939, 22971, 22986, 23001, 23042)'} if mrows else {}
    ch, ok_s = _BCB_WS.get('chw') or [], _BCB_WS.get('soap_ok', 0)
    if ch or (_BCB_WS['on'] and ok_s):   # v261/v263: ślad w części tylko, gdy coś naprawdę przyszło z SOAP — notatka wraca z pamięci (bcb_nota)
        extra['soap'] = {'at': NOW, 'serie': [s for s, _ in ch], 'np': (ch[0][1] if ch else None), 'wszystkie': bool(_BCB_WS['on']) and ok_s > len(ch)}
    return {**extra, 'at': NOW, 'src': 'Banco Central do Brasil — SGS, câmbio contratado (13961, 13967–13970)',
            'url': 'https://www.bcb.gov.br/estatisticas/tabelaespecial', 'unit': 'mln USD',
            'cols': ['data', 'finansowy saldo', 'finansowy kupno', 'finansowy sprzedaż', 'handlowy saldo', 'razem saldo'],
            'asof': d[-1][0], 'd': d}


def bcb_nota(pp):
    """v261 (przegląd v256): część Brazylii z serii z usługi SOAP — notatka także w przebiegach z pamięci (część odświeża się co 3 h, a kontrola
    czyta ostatni meta; wzór: Turcja v126, kursy walut v258)."""
    s = pp.get('soap') if isinstance(pp, dict) and isinstance(pp.get('soap'), dict) else None
    if not s:
        return
    kiedy = str(s.get('at') or pp.get('at') or '—')[:16].replace('T', ' ')
    if s.get('serie'):
        META['notes'].append(mask(f"BCB (odświeżenie {kiedy} UTC): API JSON chwilowo bez danych serii {', '.join(map(str, s['serie']))}"
                                  + (f" (np. {s['np']})" if s.get('np') else '') + ' — te serie z usługi SOAP tego samego banku'))
    elif s.get('wszystkie'):
        META['notes'].append(mask(f'BCB (odświeżenie {kiedy} UTC): API JSON nie odpowiadał — serie z usługi SOAP tego samego banku'))


# v74: Turcja — bank centralny (CBRT), tygodniowe transakcje netto nierezydentów w papierach (oczyszczone z cen i kursów), bez klucza
TCMB_PAGE = 'https://www.tcmb.gov.tr/wps/wcm/connect/EN/TCMB+EN/Main+Menu/Statistics/Monetary+and+Financial+Statistics/Securities+Statistics/'
TCMB_KEYS = (('tot', 'net transactions total'), ('eq', 'equity'), ('gdds', 'gdds (outright purchase)'),
             ('corp', 'debt securities issued by other than general'), ('intl', 'b.2. international market total'),
             ('eurob', 'general government issuances'))

# v126: Turcja przez API banku (EVDS3; grupa bie_mknethar — ta sama tabela co arkusz T1_En w pliku ZIP, 27.09.2026 wszystkie 30 liczb
# z 5 tygodni zgodne): pełna historia tygodni od 11.09.2020. Klucz właściciela EVDS_KEY tylko w nagłówku 'key' — nigdy w adresie, w plikach
# ani w komunikatach (mask); plik ZIP ze strony banku zostaje zapasem (brak klucza, klucz odrzucony, awaria API). Stary adres evds2 wyłączony
# 20.02.2026 (302 → strona HTML): przekierowań nie wykonujemy, więc klucz nie trafi pod inny adres. Warunki EVDS: podpis źródła i zdanie,
# że tłumaczenie nie jest oficjalne (strona Źródła), dane bez opłat dla użytkowników; przewodnik: pobierać raz dziennie, serie jednej grupy
# jednym zapytaniem (tak robimy).
EVDS_BASE = 'https://evds3.tcmb.gov.tr/igmevdsms-dis/'
EVDS_PAGE = 'https://evds3.tcmb.gov.tr/'      # pole 'url' części — strona publiczna, nigdy adres API
EVDS_SERIES = (('tot', 'TP.MKNETHAR.M20'), ('eq', 'TP.MKNETHAR.M7'), ('gdds', 'TP.MKNETHAR.M8'),
               ('corp', 'TP.MKNETHAR.M12'), ('intl', 'TP.MKNETHAR.M22'), ('eurob', 'TP.MKNETHAR.M23'))   # kolejność = TCMB_KEYS
EVDS_FIRST = datetime.date(2020, 9, 11)   # pierwszy tydzień serii w metodzie G20 (ogłoszenie banku 19.08.2021); starsze archiwum (bie_yymkpyuk)
                                          # liczone inaczej (z repo, bez rynku zagranicznego) — nie sklejamy
EVDS_CHUNK_W = 520     # tygodni w jednym zapytaniu: limit 1000 obserwacji liczy daty (sonda 27.09.2026: 315 tygodni × 6 serii w jednym
                       # zapytaniu) — cała historia jednym zapytaniem do 2030, potem kawałki (najnowszy pierwszy)
EVDS_RECENT_W = 13     # zwykłe odświeżenie: od najnowszego zapisanego piątku − 13 tygodni (bank poprawia ostatnie tygodnie — dane wstępne)
EVDS_FULL_D = 28       # pełne pobranie od początku serii co 28 dni (rzadkie poprawki starszych tygodni) albo od razu, gdy w historii brak tygodnia
EVDS_BUDGET = 120      # s na kolejne kawałki pełnego pobrania w jednym przebiegu (z _back_ok i BACK_LATE jak inne historie wstecz)
EVDS_TIMEOUT = 45      # s na jedno zapytanie
EVDS_TZ = datetime.timedelta(hours=3)     # Turcja: UTC+3 przez cały rok (bez zmiany czasu od 2016)
TCMB_KEEP = 600        # tygodni w części 'tr' (ok. 11,5 roku) na obu drogach — zapas ZIP nie przycina historii z API do OBCE_KEEP
TCMB_RELEASE_UTC = (3, 11, 30)   # publikacja: czwartek 14:30 w Stambule = 11:30 UTC (kalendarz banku), tydzień do piątku przed nim
TCMB_DAY_MIN = 1440    # część z tygodniem z ostatniej publikacji — odświeżana raz na dobę; bez niego — co OBCE_SLOW['tr'] (jak dotąd)


class _EvdsNoRedirect(urllib.request.HTTPRedirectHandler):
    """v126: urllib przenosi własne nagłówki (także klucz) pod każdy adres przekierowania, również na inny serwer. Poprawne zapytanie
    API nie jest przekierowywane — 3xx znaczy „adres przeniesiony” (evds2 → strona HTML), więc zamiast iść dalej: HTTPError."""
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def evds_get(url, key, timeout=EVDS_TIMEOUT):
    """Jedno zapytanie EVDS: klucz tylko w nagłówku 'key', bez przekierowań; odpowiedź nie-JSON (np. strona HTML) = RuntimeError."""
    req = urllib.request.Request(url, headers={'User-Agent': 'CapitalFlowAI-collector/1.0', 'Accept': 'application/json', 'key': key})
    with urllib.request.build_opener(_EvdsNoRedirect).open(req, timeout=timeout) as r:
        body = r.read()
    try:
        return json.loads(body.decode('utf-8-sig', 'replace'))
    except ValueError:
        raise RuntimeError('odpowiedź nie jest JSON (strona HTML zamiast danych?)') from None


def evds_url(a, b):
    """Adres zapytania w formie z przewodnika EVDS (parametry po '&' w ścieżce, bez '?'); daty dd-mm-rrrr; klucza w adresie nie ma."""
    return (f"{EVDS_BASE}series={'-'.join(c for _, c in EVDS_SERIES)}"
            f"&startDate={a.strftime('%d-%m-%Y')}&endDate={b.strftime('%d-%m-%Y')}&type=json")


def _tcmb_today():
    """Dzisiejsza data w Stambule (koniec zakresu zapytania i data pełnego pobrania); przez _now_utc — testy ustawiają czas."""
    return (_now_utc() + EVDS_TZ).date()


def _evds_day(it):
    """Data pozycji odpowiedzi: 'Tarih' dd-mm-rrrr; bez niej UNIXTIME (sekundy = północ w Stambule, czyli 21:00 UTC w czwartek) + 3 h;
    bez obu YEARWEEK (tydzień ISO → piątek). Zła data = None."""
    m = re.match(r'^(\d{2})-(\d{2})-(\d{4})$', str(it.get('Tarih') or '').strip())
    if m:
        try:
            return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
        except ValueError:
            return None
    u = it.get('UNIXTIME')
    u = _num(u.get('$numberLong') if isinstance(u, dict) else u) if u is not None else None
    if u is not None:
        try:
            return (datetime.datetime.fromtimestamp(int(u), datetime.timezone.utc) + EVDS_TZ).date()
        except (OverflowError, OSError, ValueError):
            return None
    m = re.match(r'^(\d{4})-(\d{1,2})$', str(it.get('YEARWEEK') or '').strip())
    if m:
        try:
            return datetime.date.fromisocalendar(int(m.group(1)), int(m.group(2)), 5)
        except ValueError:
            return None
    return None


def parse_evds(j, a=None, b=None, notes=None):
    """Odpowiedź EVDS {totalCount, items: [{Tarih, TP_MKNETHAR_M20: '…', …}]} → wiersze jak parse_tcmb: [[piątek ISO, razem, akcje,
    obligacje skarbowe, obligacje firm i banków, rynek zagraniczny razem, euroobligacje rządu]] rosnąco, mln USD, 2 miejsca po przecinku.
    Brak / null / nie-liczba = None (nigdy 0); wiersz bez żadnej z 6 wartości pominięty (EVDS wypełnia siatkę dat przed początkiem serii
    i po ostatniej publikacji wartościami null); data spoza [a, b] albo nie w piątek — pominięta z notatką (błędny zakres EVDS odpowiada
    innym zakresem zamiast błędem). Inny kształt (np. treść błędu JSON) albo brak tygodni z danymi = RuntimeError."""
    if not isinstance(j, dict) or not isinstance(j.get('items'), list):
        # najpierw maska, potem cięcie: klucz odbity przez serwer na granicy 80 znaków nie zostawi swojego początku
        msg = mask(str(j.get('message') or ''))[:80] if isinstance(j, dict) else ''
        raise RuntimeError('nieznany kształt odpowiedzi' + (f' ({msg})' if msg else ''))
    keys = [(c.replace('.', '_'), c) for _, c in EVDS_SERIES]
    out, off = {}, []
    for it in j['items']:
        if not isinstance(it, dict):
            continue
        d = _evds_day(it)
        if d is None:
            continue
        vals = []
        for u, c in keys:
            v = _num(it[u] if u in it else it.get(c))
            vals.append(round(v, 2) if v is not None and v == v and abs(v) != float('inf') else None)
        if all(v is None for v in vals):
            continue
        if d.weekday() != 4 or (a and d < a) or (b and d > b):
            off.append(d.isoformat())
            continue
        out[d.isoformat()] = [d.isoformat()] + vals
    if off and notes is not None:
        notes.append('CBRT EVDS: pominięte daty spoza zakresu albo nie w piątek: ' + ', '.join(sorted(off)[-5:]))
    if not out:
        raise RuntimeError('brak tygodni z danymi')
    return [out[k] for k in sorted(out)]


def evds_plan(have, today, full=None, keep=TCMB_KEEP):
    """→ [(od, do), …]. Pełne pobranie od EVDS_FIRST w kawałkach po najwyżej EVDS_CHUNK_W tygodni liczonych od dziś wstecz (najnowszy
    kawałek pierwszy i zawsze pełnej długości — ma opublikowane tygodnie; przerwane pobranie i tak daje bieżące tygodnie; każdy kawałek
    od piątku), gdy: historii nie ma albo nie sięga początku serii (i nie jest już przycięta do keep — bez pobierania
    w kółko), w historii brakuje tygodnia, albo ostatnie pełne pobranie (full, data ISO) jest starsze niż EVDS_FULL_D dni lub go nie było.
    Inaczej jedno okno: od najnowszego zapisanego piątku − EVDS_RECENT_W tygodni do dziś (piątek — pierwszy dzień tygodnia serii)."""
    ds = sorted({d for d in (_d(x) for x in have) if d})
    f = _d(full) if full else None
    short = not ds or (ds[0] > EVDS_FIRST + datetime.timedelta(days=7) and len(ds) < keep)
    gap = any((y - x).days > 7 for x, y in zip(ds, ds[1:]))
    if short or gap or f is None or (today - f).days >= EVDS_FULL_D:
        out, b = [], today
        while b >= EVDS_FIRST:
            a = b - datetime.timedelta(days=7 * EVDS_CHUNK_W - 1)
            a = max(EVDS_FIRST, a + datetime.timedelta(days=(4 - a.weekday()) % 7))
            out.append((a, b))
            b = a - datetime.timedelta(days=1)
        return out
    return [(ds[-1] - datetime.timedelta(days=7 * EVDS_RECENT_W), today)]


def evds_rows(key, have, full=None):
    """Zapytania według evds_plan → (wiersze jak parse_tcmb rosnąco, True gdy pełne pobranie skończone w całości). Kolejny kawałek tylko
    w budżecie czasu (EVDS_BUDGET, BACK_LATE), 1 s po poprzednim; awaria albo brak czasu na kolejny kawałek = notatka i wiersze
    z wcześniejszych (resztę dokończy następne odświeżenie). Awaria pierwszego zapytania = wyjątek (wtedy plik ZIP). Odpowiedź, która
    zaczyna się później niż tydzień po początku zakresu, to możliwe ucięcie najstarszych tygodni (limit obserwacji) — notatka."""
    plan = evds_plan(have, _tcmb_today(), full)
    t0, got, done = time.monotonic(), {}, plan[-1][0] == EVDS_FIRST
    for i, (a, b) in enumerate(plan):
        if i:
            if not _back_ok(t0, EVDS_BUDGET, EVDS_TIMEOUT):
                done = False
                META['notes'].append(f'CBRT EVDS: starsze tygodnie do {b.isoformat()} — brak czasu w tym przebiegu, dokończymy przy następnym odświeżeniu')
                break
            time.sleep(1)
        try:
            rows = parse_evds(evds_get(evds_url(a, b), key), a, b, META['notes'])
        except Exception as e:
            if not i:
                raise
            done = False
            META['notes'].append(mask(f'CBRT EVDS: starsze tygodnie {a.isoformat()}–{b.isoformat()}: {e} — dokończymy przy następnym odświeżeniu'))
            break
        if (_d(rows[0][0]) - a).days > 7:
            done = False
            META['notes'].append(f'CBRT EVDS: odpowiedź zaczyna się od {rows[0][0]}, pytaliśmy od {a.isoformat()} — możliwe ucięcie najstarszych tygodni')
        got.update({r[0]: r for r in rows})
    return [got[k] for k in sorted(got)], done


def _tcmb_day(v):
    s = str(v or '').strip()
    m = re.match(r'^(\d{2})\.(\d{2})\.(\d{4})$', s)
    if m:
        return f'{m.group(3)}-{m.group(2)}-{m.group(1)}'
    x = _num(s)
    if x is not None and 20000 < x < 80000:
        return (datetime.date(1899, 12, 30) + datetime.timedelta(days=int(x))).isoformat()
    return None


def parse_tcmb(rows):
    """Arkusz T1_En → [[tydzień do (piątek), razem, akcje, obligacje skarbowe (zakup bezwarunkowy), obligacje firm i banków,
    rynek zagraniczny razem, euroobligacje rządu]] w mln USD — tylko część „B. NET TRANSACTIONS”, wiersze po nazwie."""
    head, got = None, {}
    for _, r in sorted(rows.items()):
        lab = re.sub(r'\s+', ' ', r.get(2, '')).strip().lower()
        if lab.startswith('b. net transactions'):
            head = {c: _tcmb_day(v) for c, v in r.items() if c > 2}
            head = {c: d for c, d in head.items() if d}
            continue
        if head is None:
            continue
        if not lab or lab.startswith('('):
            break          # koniec części B (przypisy)
        for key, pre in TCMB_KEYS:
            if key not in got and lab.startswith(pre):
                got[key] = {head[c]: _num(v) for c, v in r.items() if c in head and _num(v) is not None and _num(v) == _num(v)}
                break
    if not head or 'tot' not in got:
        raise RuntimeError('brak części „B. NET TRANSACTIONS”')
    days = sorted({d for x in got.values() for d in x})
    return [[d] + [(got.get(k) or {}).get(d) for k, _ in TCMB_KEYS] for d in days]


def tcmb_zip_rows():
    """v74: plik ZIP ze strony banku (arkusz T1_En, część B) → wiersze parse_tcmb (ok. 5 ostatnich tygodni); bez klucza. Od v126 zapas
    dla API EVDS (brak klucza, klucz odrzucony, awaria API)."""
    import html as _h
    import zipfile
    page = get_bytes(TCMB_PAGE, timeout=60).decode('utf-8', 'replace')
    m = re.search(r'href="([^"]*Securities\+Statistics\.zip[^"]*)"', page)
    if not m:
        raise RuntimeError('brak odnośnika do pliku')
    href = _h.unescape(m.group(1))
    z = zipfile.ZipFile(io.BytesIO(get_bytes(href if href.startswith('http') else 'https://www.tcmb.gov.tr' + href, timeout=90)))
    name = next((n for n in z.namelist() if n.lower().endswith('.xlsx')), None)
    if not name:
        raise RuntimeError('brak pliku .xlsx w archiwum')
    return parse_tcmb(_xlsx_rows(z.read(name), 'T1_En'))


def _tcmb_scale(new):
    """v77: tydzień > 100 mld USD = zła skala (np. tysiące zamiast milionów) — cała odpowiedź odrzucona (wyjątek)."""
    big = [r[0] for r in new if any(v is not None and abs(v) > 1e5 for v in r[1:])]
    if big:
        raise RuntimeError(f'skala niezgodna ({big[-1]})')


def tcmb_part(prev_tr, key=''):
    """v74 + v126: Turcja — tygodniowe transakcje netto nierezydentów w papierach (mln USD). Z kluczem EVDS_KEY: API banku (EVDS3) — pełna
    historia od 11.09.2020 (pierwszy raz i co EVDS_FULL_D dni), zwykle okno ostatnich 13 tygodni; bez klucza albo po awarii API: plik ZIP
    ze strony banku (5 ostatnich tygodni) dopisany do zapisanej historii. Awaria API to notatka z przyczyną (dane i tak są — z pliku ZIP),
    nie błąd; błąd tylko wtedy, gdy zawiodą obie drogi (build_obce zostawia wtedy poprzednią część). Nowsze dane poprawiają zapisane tygodnie
    (dane wstępne). Pola dodane w v126 (poza nimi plik jak dotąd): via ('evds' / 'zip'), full (data ostatniego pełnego pobrania z API),
    evds_err (przyczyna zapasu ZIP, gdy jest klucz)."""
    prev_tr = prev_tr if isinstance(prev_tr, dict) else {}
    have = {k: list(v) for k, v in _rows(prev_tr).items()}
    new, via, full, why = None, 'zip', prev_tr.get('full'), None
    if key and not re.fullmatch(r'[!-~]{4,256}', key):   # nagłówek z niedozwolonym znakiem — urllib odbiłby wartość klucza w komunikacie
        why = 'klucz EVDS_KEY w złym formacie (niedozwolone znaki albo długość; popraw sekret)'
        META['notes'].append(f'CBRT EVDS: {why} — Turcja z pliku ZIP banku')
    elif key:
        try:
            rows, done = evds_rows(key, sorted(have), full)
            _tcmb_scale(rows)
            new, via = rows, 'evds'
            if done:
                full = _tcmb_today().isoformat()
        except urllib.error.HTTPError as e:
            why = ({401: 'klucz EVDS_KEY odrzucony', 403: 'klucz EVDS_KEY odrzucony', 429: 'limit zapytań'}.get(e.code)
                   or ('adres API przeniesiony' if 300 <= e.code < 400 else 'błąd serwera' if e.code >= 500 else 'zapytanie odrzucone')) + f' (HTTP {e.code})'
        except Exception as e:   # przekroczony czas, strona HTML, zły kształt, zła skala — dane z pliku ZIP
            why = mask(str(e) or type(e).__name__)[:120]   # najpierw maska, potem cięcie — klucz na granicy 120 znaków nie zostawi początku
        if why:
            why = mask(why)
            META['notes'].append(f'CBRT EVDS: {why} — Turcja z pliku ZIP banku')
    zip_path = new is None
    if zip_path:
        new = tcmb_zip_rows()
        _tcmb_scale(new)
    gap = [r[0] for r in new if None not in r[1:6] and abs(r[1] - r[2] - r[3] - r[4] - r[5]) > 1]
    if gap:
        META['notes'].append('CBRT: razem ≠ suma składników w tygodniach: ' + ', '.join(gap[-5:]) + (f' (i {len(gap) - 5} wcześniej)' if len(gap) > 5 else ''))
    keep_cells = zip_path and (prev_tr.get('via') == 'evds' or bool(prev_tr.get('full')))
    for r in new:      # nowsze dane poprawiają zapisany tydzień (dane wstępne)
        o = have.get(r[0])
        if keep_cells and o:   # plik ZIP na historii z API: „-” w pliku (None) nie kasuje liczby z API (np. obligacje firm 11.09.2026: ZIP „-”, EVDS −5,76)
            r = [r[0]] + [n if n is not None else (o[i] if i < len(o) else None) for i, n in enumerate(r[1:], 1)]
        have[r[0]] = r
    d = [have[k] for k in sorted(have)][-TCMB_KEEP:]
    out = {'at': NOW, 'via': via,
           'src': ('Central Bank of the Republic of Türkiye (CBRT) — EVDS, Securities Portfolio Held By Non-Residents (bie_mknethar), 2. Net Transactions'
                   if via == 'evds' else 'Central Bank of the Republic of Türkiye (CBRT) — Securities Statistics, Table 1, B. Net Transactions'),
           'url': EVDS_PAGE if via == 'evds' else TCMB_PAGE,
           'unit': 'mln USD; transakcje netto nierezydentów oczyszczone ze zmian cen i kursów; bez repo, zabezpieczeń i pożyczek papierów',
           'cols': ['tydzień do', 'razem', 'akcje', 'obligacje skarbowe (zakup bezwarunkowy)', 'obligacje firm i banków', 'rynek zagraniczny razem', 'euroobligacje rządu'],
           'asof': d[-1][0], 'd': d}
    if full:
        out['full'] = full
    if why:
        out['evds_err'] = why
    return out


# v86: Tajlandia — ThaiBMA „Non-resident Flows”: dzienne transakcje nierezydentów w tajskich obligacjach (mln THB), bez klucza;
# ≈ USD kursem Fed H.10 (FRED DEXTHUS). Źródło oddaje całą historię (od 2016) w jednym pliku JSON.
THBMA_URL = 'https://www.thaibma.or.th/nrdaily/GetNR/'
THBMA_PAGE = 'https://www.thaibma.or.th/EN/Market/NR/NRDaily.aspx'
TH_KEEP = 270      # ok. 13 miesięcy sesji — wystarcza na sumę 12 miesięcy (250 sesji)
TH_COLS = ('NetFlow', 'TotalNetTrade', 'ShortTermTrade', 'LongTermTrade', 'ExpireToday', 'NetHolding')
TH_STALE = 8       # dni kalendarzowych bez nowego pełnego dnia = błąd (najdłuższa przerwa w 10 latach: 6 dni — Songkran, Nowy Rok)


def parse_thbma(j):
    """ThaiBMA /nrdaily/GetNR/ → [[data, przepływ netto (transakcje netto − wykupy), transakcje netto, z wykupem w ciągu roku, później,
    wykupy, stan posiadania (wartość nominalna)]] mln THB, rosnąco. Dzień w toku (najnowsza data bez części popołudniowej P3 — ThaiBMA
    publikuje ją o 16:30 w Bangkoku) pominięty; zakończony dzień bez P3 albo bez sum — wiersz z brakami (None), żeby sumy okien pokazały
    „—”, a nie sięgnęły dzień dalej; powtórzona data — pierwszy wiersz (różne wiersze = uwaga)."""
    if not isinstance(j, list):
        raise RuntimeError('odpowiedź nie jest listą')
    rows = [r for r in j if isinstance(r, dict) and re.match(r'^\d{4}-\d{2}-\d{2}$', str(r.get('Asof') or '')[:10])]
    if not rows:
        raise RuntimeError('brak dni')
    newest = max(str(r['Asof'])[:10] for r in rows)
    out, seen, dup, hole = {}, {}, [], []
    for r in rows:
        day = str(r['Asof'])[:10]
        v = [_num(r.get(k)) for k in TH_COLS]
        if day in seen:
            if seen[day] != v:
                dup.append(day)
            continue
        seen[day] = v
        if r.get('P3Net') is None and day == newest:
            continue                      # dzień w toku
        if r.get('P3Net') is None or v[0] is None or v[1] is None:
            v = [None] * len(TH_COLS); hole.append(day)
        out[day] = [day] + v
    if not out:
        raise RuntimeError('brak pełnych dni')
    keep = set(sorted(out)[-TH_KEEP:])
    if [x for x in dup if x in keep]:
        META['notes'].append('ThaiBMA: różne wiersze dla tej samej daty (wzięty pierwszy): ' + ', '.join(sorted(x for x in dup if x in keep)))
    if [x for x in hole if x in keep]:
        META['notes'].append('ThaiBMA: zakończony dzień bez części popołudniowej albo bez sum (pokazany jako brak): ' + ', '.join(sorted(x for x in hole if x in keep)))
    return [out[k] for k in sorted(out)]


def _th_scale_ok(r):
    return r[1] is None or (abs(r[1]) <= 2e5 and (r[6] is None or 1e5 < r[6] < 1e7))   # dzień ≤ 200 mld THB; stan 0,1–10 bln THB


def thbma_part(prev_th, key):
    prev_th = prev_th if isinstance(prev_th, dict) else {}
    try:
        j = json.loads(get_bytes(THBMA_URL, timeout=120).decode('utf-8-sig', 'replace'))
    except ValueError:
        raise RuntimeError('odpowiedź nie jest JSON (np. przerwa techniczna)')
    d = [list(r) for r in parse_thbma(j)[-TH_KEEP:]]      # źródło oddaje całą historię — wiersze tylko ze źródła (bez starych dni z pliku)
    if len(d) < 30:
        raise RuntimeError(f'za mało dni ({len(d)})')
    if not _th_scale_ok(d[-1]):
        raise RuntimeError(f'skala niezgodna ({d[-1][0]})')    # najnowszy dzień — zostaje poprzednia część
    bad = [r[0] for r in d if not _th_scale_ok(r)]
    for r in d:
        if r[0] in bad:
            r[1:7] = [None] * 6                                # pojedynczy zły dzień = brak, nie blokada całej części
    if bad:
        META['errors'].append('ThaiBMA: wartości poza skalą (pokazane jako brak) w dniach: ' + ', '.join(bad[-5:]))
    gap = [r[0] for r in d[-30:] if None not in r[1:6] and (abs(r[2] - r[3] - r[4]) > 1 or abs(r[2] - r[5] - r[1]) > 1)]
    if gap:
        META['notes'].append('ThaiBMA: sumy niezgodne w dniach: ' + ', '.join(gap))
    rates = {}
    if key:
        try:
            rates = fred_rates(key, 'DEXTHUS', limit=400)
        except Exception as e:
            META['errors'].append(mask(f'ThaiBMA kurs FRED DEXTHUS: {e}'))
    old = _rows(prev_th)
    for r in d:
        rd, rt = _rate_for(rates, r[0])
        if rt and r[1] is not None:
            r[7:] = [round(r[1] / rt, 1), rt, rd]
        elif r[1] is not None and r[0] in old and len(old[r[0]]) >= 10 and old[r[0]][1] == r[1]:
            r[7:] = old[r[0]][7:10]
        else:
            r[7:] = [None, None, None]
    last = d[-1][0]
    if ((_now_utc() + datetime.timedelta(hours=7)).date() - datetime.date.fromisoformat(last)).days > TH_STALE:
        META['errors'].append(f'ThaiBMA: brak nowego pełnego dnia po {last}')
    return {'at': NOW, 'src': 'The Thai Bond Market Association (ThaiBMA) — Non-resident Flows (daily)', 'url': THBMA_PAGE,
            'unit': 'mln THB; ≈ mln USD kursem Fed H.10 (FRED DEXTHUS); stan posiadania w wartości nominalnej',
            'cols': ['data', 'przepływ netto', 'transakcje netto', 'z wykupem w ciągu roku', 'z wykupem później', 'wykupy', 'stan posiadania',
                     '≈ mln USD', 'kurs THB/USD', 'dzień kursu'],
            'asof': last, 'd': d}

OBCE_SLOW = {'br': 180, 'tr': 180, 'th': 180}   # v91: min — Brazylia i Turcja publikują raz w tygodniu, ThaiBMA raz dziennie (regulamin: umiar)


def tcmb_expected_friday(now_utc):
    """v126: najnowszy piątek, który o `now_utc` powinien być już opublikowany: ostatnia publikacja (czwartek 11:30 UTC) minus 6 dni.
    Publikacja przesunięta przez święto — część wygląda na spóźnioną i jest odświeżana co OBCE_SLOW['tr'] minut, jak dotąd."""
    wd, hh, mm = TCMB_RELEASE_UTC
    t = (now_utc - datetime.timedelta(days=(now_utc.weekday() - wd) % 7)).replace(hour=hh, minute=mm, second=0, microsecond=0)
    if t > now_utc:
        t -= datetime.timedelta(days=7)
    return (t - datetime.timedelta(days=6)).date()


def tcmb_fresh_min(pp, evds_key=''):
    """v126: ile minut zapisana część 'tr' jest ważna. Ma tydzień z ostatniej publikacji — TCMB_DAY_MIN (raz na dobę; przewodnik EVDS:
    raz dziennie wystarcza); nie ma (przed publikacją w czwartek, święto, opóźnienie) — OBCE_SLOW['tr'], jak dotąd. Z kluczem, gdy część
    jeszcze nie przyszła z API (pierwsze wdrożenie) albo historia nie sięga początku serii — też OBCE_SLOW['tr'], żeby pełna historia
    przyszła w ciągu ≤ 3 h, a nie po dobie (chyba że API zawiodło przy ostatnim odświeżeniu — wtedy następna próba po dobie)."""
    ds = sorted(d for d in (_d(k) for k in _rows(pp)) if d)
    if not ds or ds[-1] < tcmb_expected_friday(_now_utc()):
        return OBCE_SLOW['tr']
    if evds_key and not pp.get('evds_err') and (pp.get('via') != 'evds' or (ds[0] > EVDS_FIRST + datetime.timedelta(days=7) and len(ds) < TCMB_KEEP)):
        return OBCE_SLOW['tr']
    return TCMB_DAY_MIN


def evds_note(pp, evds_key):
    """v126: przyczyna zapasu ZIP z ostatniego odświeżenia części 'tr' — notatka także w przebiegach z pamięci (kontrola dzienna czyta
    ostatni plik meta, a Turcja odświeża się zwykle raz na dobę)."""
    if evds_key and isinstance(pp, dict) and pp.get('evds_err'):
        META['notes'].append(mask(f"CBRT EVDS (odświeżenie {str(pp.get('at') or '—')[:16].replace('T', ' ')} UTC): {pp['evds_err']} — Turcja z pliku ZIP banku"))


def build_obce(key, prev=None, evds_key=''):
    """data/obce.json — każda część osobno: awaria jednej zostawia jej poprzednią wersję (brak nie jest zerem)."""
    prev = prev if isinstance(prev, dict) else {}
    out = {'at': NOW, 'ok': {}, 'errs': {}}   # v77: stan i błędy części — widoczne także przy przebiegach z pamięci
    for part, fn in (('in', lambda: nsdl_part(prev.get('in'))), ('tw', lambda: twse_part(prev.get('tw'), key)),
                     ('hk', lambda: hkex_part(prev.get('hk'), key)),   # v67: Stock Connect southbound
                     ('br', lambda: bcb_part(prev.get('br'))),   # v71: Brazylia — rynek walutowy (BCB)
                     ('tr', lambda: tcmb_part(prev.get('tr'), evds_key) if evds_key else tcmb_part(prev.get('tr'))),   # v74: Turcja — nierezydenci w papierach (CBRT); v126: z kluczem przez API EVDS
                     ('th', lambda: thbma_part(prev.get('th'), key))):   # v86: Tajlandia — nierezydenci w obligacjach (ThaiBMA)
        n0 = len(META['errors'])
        pp = prev.get(part)
        if part == 'br' and bcb_przerwa_odczekaj(pp, prev):   # v416: bank w przerwie — kolejne zapytanie nie wcześniej niż po BCB_PRZERWA_PONOW_MIN min; dane z datą, ⚠️ (nie ❌)
            out[part] = pp; META['ok']['obce_br'] = False; out['ok'][part] = False
            META['notes'].append(mask(bcb_przerwa_nota(pp)))
            continue
        if part in OBCE_SLOW and isinstance(pp, dict) and (prev.get('ok') or {}).get(part) is True and \
                fresh(pp, tcmb_fresh_min(pp, evds_key) if part == 'tr' else OBCE_SLOW[part]):   # v126: Turcja z tygodniem z ostatniej publikacji — raz na dobę
            out[part] = pp; META['ok']['obce_' + part] = 'cached'; out['ok'][part] = True   # v91: źródło publikujące rzadziej — bez zapytania
            if part == 'tr':
                evds_note(pp, evds_key)
            if part == 'br':
                bcb_nota(pp)   # v261: serie z SOAP widoczne także w przebiegu z pamięci
            pe = (prev.get('errs') or {}).get(part) if isinstance(prev.get('errs'), dict) else None
            if isinstance(pe, list) and pe:   # v263: ostatnie błędy części zostają widoczne do jej następnego odświeżenia (dane mają dziurę)
                out['errs'][part] = pe; META['errors'].extend(e for e in pe if isinstance(e, str))
            continue
        try:
            out[part] = fn(); META['ok']['obce_' + part] = True
        except Exception as e:
            if part == 'br' and bcb_przerwa_dozwolona(e, pp):   # v416: przerwa po stronie banku, dane młodsze niż 3 doby — poprzednia część z datą + notatka, nie błąd
                out[part] = bcb_przerwa_wynik(pp, e); META['ok']['obce_br'] = False; out['ok'][part] = False
                META['notes'].append(mask(bcb_przerwa_nota(out[part])))
                continue
            META['errors'].append(mask(f"{ {'in': 'NSDL', 'tw': 'TWSE', 'hk': 'HKEX', 'br': 'BCB', 'tr': 'CBRT', 'th': 'ThaiBMA'}[part] }: {e}")); META['ok']['obce_' + part] = False
            if isinstance(prev.get(part), dict):
                out[part] = prev[part]
        out['ok'][part] = META['ok']['obce_' + part]
        if META['errors'][n0:]:
            out['errs'][part] = META['errors'][n0:]
    if not any(p in out for p in ('in', 'tw', 'hk', 'br', 'tr', 'th')):
        raise RuntimeError('żadna część nie odpowiedziała')
    return out


# v56: BIS — nominalne efektywne kursy walut (WS_EER, szeroki koszyk 64 gospodarek), bez klucza
EER_AREAS = ['US', 'XM', 'GB', 'CH', 'SE', 'NO', 'PL', 'JP', 'KR', 'CN', 'HK', 'IN', 'ID', 'SG', 'TH', 'MY', 'PH', 'AU', 'NZ',
             'CA', 'BR', 'MX', 'TR', 'IL', 'ZA', 'SA', 'RU']
EER_BASE = 'https://stats.bis.org/api/v2/data/dataflow/BIS/WS_EER/1.0/'


def eer_summary(daily, monthly):
    """Poziom (ostatni dzienny), zmiana 30 dni (dzienne) i 12 miesięcy (średnie miesięczne, ten sam miesiąc rok wcześniej), w %."""
    rows = {}
    for a in EER_AREAS:
        d = daily.get(a) or []; m = monthly.get(a) or []
        if not d and not m:
            continue
        r = {'v': None, 'd': None, 'c30': None, 'm': None, 'c12': None}
        if d:
            p, v = d[-1]
            lim = (datetime.date.fromisoformat(p) - datetime.timedelta(days=30)).isoformat()
            base = [x for q, x in d if q <= lim]
            r.update({'v': v, 'd': p, 'c30': round((v / base[-1] - 1) * 100, 2) if base and base[-1] else None})
        if m:
            p, v = m[-1]
            ago = f'{int(p[:4]) - 1:04d}-{p[5:7]}'
            prev = [x for q, x in m if q == ago]
            r.update({'m': p, 'c12': round((v / prev[0] - 1) * 100, 2) if prev and prev[0] else None})
        rows[a] = r
    return rows


EER_ZAPAS_DNI = 40   # v328: miesięczne zmiany (c12) z poprzedniego pliku najwyżej tyle dni od ich pobrania


def _eer_zapas(out, prev):
    """v328 (Z3-01): zapytanie miesięczne zawiodło — miesiąc i zmiana 12 mies. (m, c12) każdej waluty z poprzedniego pliku, z czasem ich pobrania
    (out['part_at']['m']); tylko gdy poprzedni plik jest młodszy niż EER_ZAPAS_DNI dni. Dane dzienne (v, d, c30) zawsze świeże."""
    pr = prev.get('rows') if isinstance(prev, dict) and isinstance(prev.get('rows'), dict) else {}
    kiedy = _zapas_czas(prev, 'm')
    if not pr or not _zapas_wiek_ok(kiedy, EER_ZAPAS_DNI):
        return
    n = 0
    for a, r in out['rows'].items():
        o = pr.get(a)
        if isinstance(o, dict) and o.get('m') and r.get('m') is None:
            r['m'], r['c12'] = o['m'], o.get('c12'); n += 1
    if n:
        out['part_at'] = {'m': kiedy}


def build_eer(prev=None):
    """data/eer.json — kursy efektywne BIS: dzienne 45 obserwacji (do zmiany 30 dni), miesięczne 14 (do zmiany 12 mies.)."""
    keys = '+'.join(EER_AREAS)
    daily = parse_cbpol_csv(get_bytes(EER_BASE + f'D.N.B.{keys}?lastNObservations=45&format=csv&detail=dataonly', timeout=90))
    ok_m = True
    try:
        monthly = parse_cbpol_csv(get_bytes(EER_BASE + f'M.N.B.{keys}?lastNObservations=14&format=csv&detail=dataonly', timeout=90))
    except Exception as e:
        META['errors'].append(mask(f'BIS kursy efektywne (miesięczne): {e}')); monthly = {}; ok_m = False
    rows = eer_summary(daily, monthly)
    if not rows:
        raise RuntimeError('żadna waluta')
    out = {'at': NOW, 'src': 'BIS — Effective exchange rates (WS_EER), nominal, broad basket', 'url': 'https://data.bis.org/topics/EER',
           'unit': 'indeks 2020=100; zmiany w %', 'asof': max((r['d'] or '') for r in rows.values()), 'rows': rows,
           'ok': {'d': True, 'm': ok_m}}   # v328: zapytanie miesięczne (m, c12) może zawieść osobno — wtedy z poprzedniego pliku (_eer_zapas), plik niepełny świeży 55 min
    if not ok_m:
        _eer_zapas(out, prev)
    return out


# v59: MFW COFER — skład walutowy światowych rezerw walutowych (kwartalnie), bez klucza
COFER_CUR = ['CI_USD', 'CI_EUR', 'CI_JPY', 'CI_GBP', 'CI_CNY', 'CI_CAD', 'CI_AUD', 'CI_CHF', 'CI_OTHC']
COFER_URL = ('https://api.imf.org/external/sdmx/3.0/data/dataflow/IMF.STA/COFER/+/G001.AFXRA+TFXRA+TFXRA_IMP.'
             + '+'.join(COFER_CUR + ['CI_T']) + '.SHRO_PT+NV_USD.Q?lastNObservations=9')


def _imf_quarter(p):
    s = str(p or '').strip()
    return s if re.match(r'^\d{4}-Q[1-4]$', s) else None


def _q_add(q, n):
    i = int(q[:4]) * 4 + int(q[-1]) - 1 + n
    return f'{i // 4:04d}-Q{i % 4 + 1}'


def parse_cofer(j):
    """COFER → udział walut w rezerwach przypisanych do walut (%), zmiana 1 kw. i 1 roku (pkt proc.), wartość (mld USD).
    Brak wartości = brak (nie zero); zmiana tylko z dokładnie tego kwartału rok / kwartał wcześniej."""
    ser = parse_imf_sdmx(j, _imf_quarter)
    alloc = dict(ser.get(('G001', 'AFXRA', 'CI_T', 'NV_USD', 'Q')) or [])
    total = dict(ser.get(('G001', 'TFXRA', 'CI_T', 'NV_USD', 'Q')) or [])
    if not alloc:
        raise RuntimeError('COFER: brak sumy rezerw przypisanych do walut')
    q = max(alloc)
    bn = lambda v: None if v is None else round(v / 1e9, 1)
    dif = lambda a, b: None if a is None or b is None else round(a - b, 2)
    rows = {}
    for c in COFER_CUR:
        sh = dict(ser.get(('G001', 'AFXRA', c, 'SHRO_PT', 'Q')) or []); v = dict(ser.get(('G001', 'AFXRA', c, 'NV_USD', 'Q')) or [])
        if sh.get(q) is None and v.get(q) is None:
            continue
        s0, v0, v4 = sh.get(q), v.get(q), v.get(_q_add(q, -4))
        rows[c[3:]] = {'sh': None if s0 is None else round(s0, 2), 'd1': dif(s0, sh.get(_q_add(q, -1))), 'd4': dif(s0, sh.get(_q_add(q, -4))),
                       'v': bn(v0), 'dv4': bn(None if v0 is None or v4 is None else v0 - v4)}
    if not rows:
        raise RuntimeError('COFER: żadna waluta')
    tq = total.get(q)
    imp = dict(ser.get(('G001', 'TFXRA_IMP', 'CI_T', 'SHRO_PT', 'Q')) or []).get(q)   # od 2026: część składu szacuje MFW
    return {'src': 'International Monetary Fund, Currency Composition of Official Foreign Exchange Reserves (COFER)',
            'url': 'https://data.imf.org/en/datasets/IMF.STA:COFER', 'unit': '% rezerw przypisanych do walut; mld USD',
            'asof': q, 'alloc': bn(alloc[q]), 'total': bn(tq), 'alloc_pct': round(alloc[q] / tq * 100, 1) if tq else None,
            'imp_pct': None if imp is None else round(imp, 2),
            'order': [c[3:] for c in COFER_CUR if c[3:] in rows], 'rows': rows}


def build_cofer():
    out = parse_cofer(get_json(COFER_URL, {'Accept': 'application/json'}))
    out['at'] = NOW
    return out


# v70: MFW — bilans płatniczy (BOP, BPM6), kwartalnie, bez klucza: ZMIERZONE przepływy kapitału 37 gospodarek.
# L_NIL_T = kapitał zagraniczny napływający do kraju; A_NFA_T = kapitał mieszkańców wysyłany za granicę; NETCD_T CAB = rachunek bieżący.
BIL_CTY = ['USA', 'CAN', 'BRA', 'MEX', 'CHL', 'COL', 'ARG', 'DEU', 'FRA', 'GBR', 'ITA', 'ESP', 'NLD', 'CHE', 'SWE', 'POL', 'IRL',
           'RUS', 'SAU', 'TUR', 'ISR', 'ZAF', 'EGY', 'NGA', 'IND', 'CHN', 'HKG', 'JPN', 'KOR', 'IDN', 'SGP', 'THA', 'MYS', 'PHL',
           'VNM', 'AUS', 'NZL']
BIL_KEYS = {('L_NIL_T', 'D_F'): 'in_d', ('L_NIL_T', 'P_F'): 'in_p', ('L_NIL_T', 'P_F5'): 'in_pe', ('L_NIL_T', 'P_F3'): 'in_pd',
            ('L_NIL_T', 'O_F'): 'in_o', ('A_NFA_T', 'D_F'): 'out_d', ('A_NFA_T', 'P_F'): 'out_p', ('A_NFA_T', 'O_F'): 'out_o',
            ('NETCD_T', 'CAB'): 'ca'}
BIL_URL = ('https://api.imf.org/external/sdmx/3.0/data/dataflow/IMF.STA/BOP/+/' + '+'.join(BIL_CTY)
           + '.L_NIL_T+A_NFA_T+NETCD_T.D_F+P_F+P_F5+P_F3+O_F+CAB.USD.Q?lastNObservations=8&dimensionAtObservation=TIME_PERIOD')


def parse_bilans(j, ctys=None):
    """BOP MFW → {kraj: {'q': ostatni kwartał z napływem, 's': {klucz: [[kwartał, mln USD]] rosnąco, najwyżej 8}}}.
    Wartość pusta / NaN = brak (nigdy 0). Straż skali: napływ portfelowy USA musi mieć rząd mld–bln USD na kwartał."""
    ctys = BIL_CTY if ctys is None else ctys   # v431: lista krajów opcjonalna — bez niej bilans.json liczy się jak dotąd (37 gospodarek)
    ser = parse_imf_sdmx(j, _imf_quarter)
    rows = {}
    for lab, d in ser.items():
        if len(lab) != 5:
            continue
        c, e, i, u, f = lab
        k = BIL_KEYS.get((e, i))
        if not k or u != 'USD' or f != 'Q' or c not in ctys:
            continue
        rows.setdefault(c, {})[k] = [[q, round(v / 1e6, 1)] for q, v in d][-8:]
    usa = (rows.get('USA') or {}).get('in_p')
    if usa and not 1e3 <= abs(usa[-1][1]) <= 1e7:
        raise RuntimeError(f'skala niezgodna (USA napływ portfelowy {usa[-1][1]} mln USD)')
    out = {}
    for c in ctys:
        s = rows.get(c)
        qs = [x[-1][0] for k, x in (s or {}).items() if k in ('in_d', 'in_p', 'in_o') and x]
        if qs:
            q = max(qs); lo = _q_add(q, -4)
            out[c] = {'q': q, 's': {k: x for k, x in s.items() if x and x[-1][0] >= lo}}   # v73: seria urwana dawno (np. Wietnam 2014) — poza plikiem
    if not out:
        raise RuntimeError('żaden kraj z napływem kapitału')
    return {'src': 'International Monetary Fund, Balance of Payments (BOP)', 'url': 'https://data.imf.org/en/datasets/IMF.STA:BOP',
            'unit': 'mln USD, transakcje w kwartale; in_* = kapitał zagraniczny napływający do kraju (net incurrence of liabilities), '
                    'out_* = kapitał mieszkańców wysyłany za granicę (net acquisition of financial assets); d bezpośrednie, '
                    'p portfelowe (pe akcje, pd obligacje), o pozostałe (kredyty, depozyty); ca = saldo rachunku bieżącego',
            'asof_max': max(r['q'] for r in out.values()), 'order': [c for c in ctys if c in out], 'rows': out}


def build_bilans():
    out = parse_bilans(get_json(BIL_URL, {'Accept': 'application/json'}))
    out['at'] = NOW
    return out


# ===================== v431 (F11Z30): WIERZYCIELE I DŁUŻNICY ŚWIATA — MFW IIP (stan aktywów i zobowiązań wobec zagranicy) i bilans płatniczy dla krajów spoza listy 37 (data/iip.json) =====================
# Międzynarodowa pozycja inwestycyjna (IIP, kwartalnie, bez klucza): ile kraj ma za granicą (aktywa), ile jest winien zagranicy (zobowiązania) i pozycja netto (aktywa − zobowiązania; plus = wierzyciel świata, minus = dłużnik)
# — STAN na koniec kwartału w mln USD (zmienia się też przez kursy walut i ceny papierów, nie tylko przez przepływy). Jedno zapytanie na dobę o ok. 100 gospodarek z wymiarami przypiętymi (aktywa, zobowiązania, netto;
# razem, portfel, bezpośrednie, pozostałe, rezerwy; USD; kwartał) i 5 ostatnimi obserwacjami (kwartał, poprzedni, rok wcześniej). Zestaw IDS bez filtra to 13,8 MB — nigdy. Kraj bez pozycji netto, z kwartałem starszym niż
# IIP_STARE_Q kwartałów od najnowszego w pliku albo z niezgodnością aktywa − zobowiązania ≠ netto (ponad 1%) nie wchodzi do pliku (powód w `pomin`) — brak jest brakiem, nigdy zerem.
# Bilans płatniczy (BOP): dla krajów spoza listy BIL_CTY (37 gospodarek w bilans.json zostaje bez zmian) trzy zapytania po IIP_BOP_PACZKA krajów tym samym schematem co bilans.json (pole `bop`: {kraj: {q, s}}); paczka bez
# odpowiedzi → kraje z poprzedniego pliku (bez zmiany kwartału) i błąd w `bledy`; ponowienie nie częściej niż co IIP_PONOW_MIN min. Liczba źródeł na stronie bez zmian (ten sam dostawca — ZRODLA_META: imf).
IIP_V = 1
IIP_EXTRA = ['AGO', 'ALB', 'ARM', 'AUT', 'AZE', 'BEL', 'BGD', 'BGR', 'BHR', 'BIH', 'BLR', 'BOL', 'CRI', 'CYP', 'CZE', 'DNK', 'DOM', 'DZA', 'ECU', 'EST', 'FIN', 'GEO', 'GRC', 'GTM', 'HND', 'HRV', 'HUN', 'ISL', 'JAM',
             'JOR', 'KAZ', 'KGZ', 'KHM', 'KWT', 'LKA', 'LTU', 'LUX', 'LVA', 'MAR', 'MDA', 'MKD', 'MLT', 'MMR', 'MNE', 'MNG', 'MOZ', 'MUS', 'NAM', 'NIC', 'NOR', 'NPL', 'PAK', 'PAN', 'PER', 'PRT', 'PRY', 'ROU',
             'SLV', 'SRB', 'SVK', 'SVN', 'TJK', 'TTO', 'UGA', 'UKR', 'URY', 'UZB', 'VEN', 'ZMB']   # sprawdzone 18.10.2026: wszystkie mają szereg IIP (nieaktualne odsiewa IIP_STARE_Q); Katar, ZEA, Oman, Tajwan, Kenia, Ghana, Etiopia i in. — brak w zbiorze MFW
IIP_CTY = BIL_CTY + IIP_EXTRA
IIP_KEYS = {('A_P', 'IIP'): 'a', ('L_P', 'IIP'): 'l', ('NETAL_P', 'NIIP'): 'n', ('A_P', 'P_MV'): 'pa', ('L_P', 'P_MV'): 'pl', ('A_P', 'D'): 'da', ('L_P', 'D'): 'dl',
            ('A_P', 'O'): 'oa', ('L_P', 'O'): 'ol', ('A_P', 'R'): 'r'}
IIP_BASE = 'https://api.imf.org/external/sdmx/3.0/data/dataflow/IMF.STA/IIP/+/'
IIP_TAIL = '.A_P+L_P+NETAL_P.IIP+P_MV+D+O+R+NIIP.USD.Q?lastNObservations=5&dimensionAtObservation=TIME_PERIOD'
IIP_URL = IIP_BASE + '+'.join(IIP_CTY) + IIP_TAIL
IIP_PAGE = 'https://data.imf.org/en/datasets/IMF.STA:IIP'
IIP_SRC = 'International Monetary Fund, International Investment Position (IIP) and Balance of Payments (BOP)'
IIP_BOP_PACZKA = 32       # krajów w jednym zapytaniu o bilans płatniczy (sonda 18.10.2026: 32 kraje, 117 KB, 3 s)
IIP_STARE_Q = 4           # kraj z kwartałem starszym o tyle kwartałów od najnowszego w pliku odpada (18.10.2026: Mjanma 2020, Kirgistan 2024, Azerbejdżan 2008, Wenezuela 2016)
IIP_ZGODA = 0.01          # dopuszczalna różnica aktywa − zobowiązania − netto (część większej z dwóch; 18.10.2026: ≤ 0,0001)
IIP_MIN_KRAJOW = 60       # mniej krajów w odpowiedzi = zły odczyt (18.10.2026: 99 z 106 zapytanych)
IIP_PONOW_MIN = 360       # po paczce bez odpowiedzi następna próba najwcześniej po tylu minutach
IIP_TIMEOUT = 60          # s na jedno zapytanie


def parse_iip(j):
    """IIP MFW → {'asof_max', 'order' (pozycja netto malejąco), 'rows': {kraj: {q, a, l, n, pa, pl, da, dl, oa, ol, r, n1, n4, a4, l4}}, 'pomin': {kraj: powód}} w mln USD (0,1).
    a/l/n = aktywa, zobowiązania, pozycja netto razem; pa/pl portfel, da/dl bezpośrednie, oa/ol pozostałe, r rezerwy (tylko aktywa); n1/n4/a4/l4 = kwartał i rok wcześniej (tylko dokładnie ten kwartał).
    Kwartał kraju = najnowszy z pozycją netto. Brak wartości = brak (nigdy 0). Straż skali: aktywa USA rzędu bilionów USD (mln USD: 1e7–2e8)."""
    ser = parse_imf_sdmx(j, _imf_quarter)
    by = {}
    for lab, rows in ser.items():
        if len(lab) != 5:
            continue
        c, e, i, u, f = lab
        k = IIP_KEYS.get((e, i))
        if k and u == 'USD' and f == 'Q' and c in IIP_CTY:
            by.setdefault(c, {})[k] = dict(rows)
    r1 = lambda v: None if v is None else round(v / 1e6, 1)
    kand, pomin = {}, {}
    for c in IIP_CTY:
        s = by.get(c)
        if not s or not s.get('n'):
            continue
        q = max(s['n'])
        g = lambda k, qq=q: (s.get(k) or {}).get(qq)
        a, l, n = g('a'), g('l'), g('n')
        if a is not None and l is not None and abs(a - l - n) > IIP_ZGODA * max(abs(a), abs(l), 1.0):
            pomin[c] = 'aktywa − zobowiązania ≠ pozycja netto'
            continue
        kand[c] = {'q': q, 'a': r1(a), 'l': r1(l), 'n': r1(n), 'pa': r1(g('pa')), 'pl': r1(g('pl')), 'da': r1(g('da')), 'dl': r1(g('dl')), 'oa': r1(g('oa')), 'ol': r1(g('ol')), 'r': r1(g('r')),
                   'n1': r1(g('n', _q_add(q, -1))), 'n4': r1(g('n', _q_add(q, -4))), 'a4': r1(g('a', _q_add(q, -4))), 'l4': r1(g('l', _q_add(q, -4)))}
    if len(kand) < IIP_MIN_KRAJOW:
        raise RuntimeError(f'IIP: tylko {len(kand)} krajów z pozycją netto (poniżej {IIP_MIN_KRAJOW})')
    top = max(r['q'] for r in kand.values())
    lo = _q_add(top, -IIP_STARE_Q)
    rows = {}
    for c, r in kand.items():
        if r['q'] < lo:
            pomin[c] = f'ostatni kwartał {r["q"]}'
        else:
            rows[c] = r
    usa = rows.get('USA')
    if usa and not (usa['a'] is not None and 1e7 <= usa['a'] <= 2e8):
        raise RuntimeError(f'IIP: skala niezgodna (aktywa USA {usa["a"]} mln USD)')
    return {'asof_max': max(r['q'] for r in rows.values()), 'order': sorted(rows, key=lambda c: (-rows[c]['n'], c)), 'rows': rows, 'pomin': dict(sorted(pomin.items()))}


IIP_BOP_PRZED, IIP_BOP_PO = BIL_URL.split('/+/')[0] + '/+/', BIL_URL[BIL_URL.index('.L_NIL_T'):]   # ten sam adres i te same wymiary co bilans.json — zmienia się tylko lista krajów


def iip_bop_url(kraje):
    return IIP_BOP_PRZED + '+'.join(kraje) + IIP_BOP_PO


def build_iip(prev=None, run_t0=None):
    """data/iip.json: stany IIP ok. 100 gospodarek (jedno zapytanie) + bilans płatniczy krajów spoza BIL_CTY (paczki). Błąd IIP = wyjątek (plik zostaje poprzedni);
    paczka BOP bez odpowiedzi = kraje z poprzedniego pliku i opis w `bledy`; przebieg zbieracza dłuższy niż BACK_LATE s (run_t0) — paczki bilansu dopiero w następnym przebiegu (kraje z poprzedniego pliku)."""
    out = parse_iip(get_json(IIP_URL, {'Accept': 'application/json'}, IIP_TIMEOUT))
    pv = prev.get('bop') if isinstance(prev, dict) and isinstance(prev.get('bop'), dict) else {}
    bop, bledy = {}, []
    for i in range(0, len(IIP_EXTRA), IIP_BOP_PACZKA):
        paczka = IIP_EXTRA[i:i + IIP_BOP_PACZKA]
        try:
            if run_t0 is not None and time.monotonic() - run_t0 > BACK_LATE:
                raise RuntimeError('przebieg zbyt długi, paczka w następnym przebiegu')
            bop.update(parse_bilans(get_json(iip_bop_url(paczka), {'Accept': 'application/json'}, IIP_TIMEOUT), paczka)['rows'])
        except Exception as e:
            bledy.append(mask(f'MFW bilans płatniczy (paczka {i // IIP_BOP_PACZKA + 1}): {e}'))
            bop.update({c: pv[c] for c in paczka if c in pv})
    if bop:
        lo = _q_add(max(r['q'] for r in bop.values()), -IIP_STARE_Q)
        bop = {c: bop[c] for c in IIP_EXTRA if c in bop and bop[c]['q'] >= lo}
    out.update({'v': IIP_V, 'src': IIP_SRC, 'url': IIP_PAGE,
                'unit': 'mln USD, stan na koniec kwartału; a aktywa za granicą, l zobowiązania wobec zagranicy, n pozycja netto (a − l; plus = wierzyciel świata); pa/pl papiery portfelowe, '
                        'da/dl bezpośrednie, oa/ol pozostałe (kredyty, depozyty), r rezerwy walutowe (tylko aktywa); n1 netto kwartał wcześniej, n4/a4/l4 rok wcześniej; '
                        'bop = bilans płatniczy krajów spoza listy 37 (mln USD, transakcje w kwartale, jak w bilans.json)',
                'zapytane': len(IIP_CTY), 'bop': bop, 'bledy': bledy, 'at': NOW})
    return out


# v337 (F2Z4): MFW — kto trzyma czyje papiery (Portfolio Investment Positions by Counterpart Economy, PIP, dawniej CPIS): STAN papierów
# portfelowych (akcje, udziały w funduszach, papiery dłużne) inwestorów z jednej gospodarki u emitentów z drugiej, na koniec półrocza; bez klucza.
# Zastępuje widok dawnego silnika z 24.09 (data/widoki/imf-portfolio-pairs.json, ważny do 24.10.2026). Raz na dobę lekkie zapytanie: Polska jako
# emitent — wszyscy posiadacze (ok. 13 KB, 5–8 s; daje najnowsze półrocze). Pełna macierz (wszyscy posiadacze × wszyscy emitenci; 10.10.2026: ok.
# 0,6 MB z kompresją, 39 s) tylko po nowym półroczu albo gdy część „pary” ma ponad PIP_PELNE_DNI dni (spóźnione zgłoszenia), nie w długim przebiegu
# (po PIP_LATE s od startu — wtedy w następnym) i najwyżej raz na PIP_PONOW_H h po błędzie. Z macierzy: PIP_TOP największych par dwóch różnych
# gospodarek i Polska jako inwestor. Kwoty w mln USD (0,1); brak = brak, nigdy 0. Świat (G001), regiony i grupy (U…, G…, GX…) poza parami;
# rezerwy banków centralnych i organizacji (TX093), papiery organizacji międzynarodowych (TX091) i nieprzypisane (TX983) — osobno, w sumie świata.
# Wymiary przypięte (S1.S1): gwiazdka w sektorach = ponad 45 s (sonda planisty 10.10.2026).
PIP_BASE = 'https://api.imf.org/external/sdmx/3.0/data/dataflow/IMF.STA/PIP/+/'
PIP_TAIL = '.S?lastNObservations=2&dimensionAtObservation=TIME_PERIOD&attributes=none'
PIP_POL_URL = PIP_BASE + '*.A.P_TOTINV_P_USD.S1.S1.POL' + PIP_TAIL
PIP_ALL_URL = PIP_BASE + '*.A.P_TOTINV_P_USD.S1.S1.*' + PIP_TAIL
PIP_PAGE = 'https://data.imf.org/en/datasets/IMF.STA:PIP'
PIP_SRC = 'International Monetary Fund, Portfolio Investment Positions by Counterpart Economy (PIP)'
PIP_TOP, PIP_POL_TOP = 20, 15
PIP_SWIAT = 'G001'
PIP_SPEC = ('TX091', 'TX093', 'TX983')   # organizacje międzynarodowe (emitent); SEFER + SSIO — banki centralne i organizacje (posiadacz); nieprzypisane
PIP_MIN_RAP = 10          # najnowsze półrocze = najnowsze, za które zgłosiło co najmniej tyle gospodarek (pojedyncze wczesne zgłoszenie nie przestawia okresu; 10.10.2026: 80)
PIP_PELNE_DNI = 30        # część „pary” starsza = pełna macierz jeszcze raz (spóźnione zgłoszenia i korekty)
PIP_PONOW_H = 6           # po nieudanej pełnej macierzy następna próba najwcześniej po tylu godzinach
PIP_LATE = BACK_LATE      # s od startu przebiegu — dalej bez pełnej macierzy
PIP_T_LEKKIE, PIP_T_PELNE = 60, 150   # limit czasu zapytania, s


def _pip_half(p):
    """'2025-S2' → '2025-S2'; inny zapis → None."""
    s = str(p or '').strip()
    return s if re.match(r'^\d{4}-S[12]$', s) else None


def _pip_prev(h):
    """Półrocze wcześniej: '2025-S2' → '2025-S1', '2025-S1' → '2024-S2'."""
    return f'{h[:4]}-S1' if h.endswith('S2') else f'{int(h[:4]) - 1}-S2'


def _pip_gosp(c):
    """Gospodarka (kraj albo terytorium): kod ISO 3 litery albo terytorium TX### spoza PIP_SPEC; świat, regiony i grupy — nie."""
    c = str(c or '')
    return bool(re.match(r'^[A-Z]{3}$', c)) or (bool(re.match(r'^TX\d{3}$', c)) and c not in PIP_SPEC)


def _pip_ser(j):
    """SDMX-JSON PIP → {(posiadacz, emitent): {półrocze: USD}} tylko dla stanu razem (P_TOTINV_P_USD, S1.S1, półrocznie)."""
    out = {}
    for lab, rows in parse_imf_sdmx(j, _pip_half).items():
        if len(lab) == 7 and lab[2] == 'P_TOTINV_P_USD' and lab[6] == 'S':
            out[(lab[0], lab[5])] = dict(rows)
    if not out:
        raise RuntimeError('PIP: brak serii stanu portfelowego')
    return out


def _pip_okres(ser):
    """Najnowsze półrocze, za które zgłosiło co najmniej PIP_MIN_RAP gospodarek-posiadaczy (dowolny emitent); brak = błąd."""
    rap = {}
    for (h, i), d in ser.items():
        if _pip_gosp(h):
            for p in d:
                rap.setdefault(p, set()).add(h)
    ok = [p for p, s in rap.items() if len(s) >= PIP_MIN_RAP]
    if not ok:
        raise RuntimeError(f'PIP: żadne półrocze nie ma {PIP_MIN_RAP} zgłaszających gospodarek')
    return max(ok)


def _pip_m(v):
    return None if v is None else round(v / 1e6, 1)


def _pip_rola(ser, kod, rola, L):
    """Gospodarka `kod` jako emitent (rola 'e': kto trzyma jej papiery) albo jako inwestor (rola 'p': czyje papiery trzyma) w półroczu L.
    swiat = wiersz świata (G001); suma = gospodarki + PIP_SPEC (do porównania ze światem w kontroli); rows = PIP_POL_TOP największych
    [kod, stan, zmiana od półrocza wcześniej]; inne = reszta gospodarek; n = gospodarki z dodatnim stanem. Brak czegokolwiek = None."""
    P, gosp, spec, swiat = _pip_prev(L), [], None, None
    for (h, i), d in ser.items():
        if (i if rola == 'e' else h) != kod:
            continue
        c, v = (h if rola == 'e' else i), d.get(L)
        if v is None:
            continue
        if c == PIP_SWIAT:
            swiat = v
        elif c in PIP_SPEC:
            spec = (spec or 0.0) + v
        elif _pip_gosp(c) and c != kod:
            gosp.append((c, v, d.get(P)))
    if swiat is None and not gosp:
        return None
    gosp.sort(key=lambda x: (-x[1], x[0]))
    top = gosp[:PIP_POL_TOP]
    return {'okres': L, 'poprz': P, 'swiat': _pip_m(swiat), 'suma': _pip_m(sum(v for _, v, _ in gosp) + (spec or 0.0)),
            'spec': _pip_m(spec), 'inne': _pip_m(sum(v for _, v, _ in gosp[PIP_POL_TOP:])) if len(gosp) > PIP_POL_TOP else None,
            'n': sum(1 for _, v, _ in gosp if v > 0),
            'rows': [[c, _pip_m(v), None if p is None else _pip_m(v - p)] for c, v, p in top]}


def _pip_pary(ser, L):
    """PIP_TOP największych stanów par dwóch różnych gospodarek w półroczu L: [posiadacz, emitent, stan, zmiana od półrocza wcześniej];
    n = pary gospodarek z wartością (także zero), rap = gospodarki-posiadacze z wartością w L."""
    P, rows, rap = _pip_prev(L), [], set()
    for (h, i), d in ser.items():
        v = d.get(L)
        if v is None or h == i or not (_pip_gosp(h) and _pip_gosp(i)):
            continue
        rap.add(h); rows.append((h, i, v, d.get(P)))
    if not rows:
        raise RuntimeError(f'PIP: brak par gospodarek w półroczu {L}')
    rows.sort(key=lambda x: (-x[2], x[0], x[1]))
    if not 1e11 <= rows[0][2] <= 1e14:   # największa para świata: setki mld – kilka bln USD (10.10.2026: 7,1 bln); inaczej zmiana skali (SCALE)
        raise RuntimeError(f'PIP: skala niezgodna (największa para {rows[0][2]:.0f} USD)')
    return {'okres': L, 'poprz': P, 'n': len(rows), 'rap': len(rap),
            'rows': [[h, i, _pip_m(v), None if p is None else _pip_m(v - p)] for h, i, v, p in rows[:PIP_TOP]]}


def build_pip(prev=None, run_t0=None, fetch=None):
    """data/pip.json (v337): lekkie zapytanie zawsze (Polska jako emitent i najnowsze półrocze); pełna macierz tylko wg reguł w nagłówku bloku.
    Część „pary” (z „pol_p”) niepobrana albo nieudana — z poprzedniego pliku z własną datą part_at; ok['pary'] = False, gdy była potrzebna
    (plik niepełny → ponowienie po 55 min w main()); błąd pełnej macierzy w polu bledy (main() przenosi do meta)."""
    fetch = fetch or (lambda url, timeout: get_json(url, {'Accept': 'application/json'}, timeout))
    prev = prev if isinstance(prev, dict) else {}
    ser = _pip_ser(fetch(PIP_POL_URL, PIP_T_LEKKIE))
    L = _pip_okres(ser)
    pol_e = _pip_rola(ser, 'POL', 'e', L)
    if not pol_e or pol_e['swiat'] is None or not 1e3 <= pol_e['swiat'] <= 1e7:   # Polska jako emitent: rząd 10–1000 mld USD (10.10.2026: 193,3)
        raise RuntimeError('PIP: brak wiersza świata dla Polski albo skala niezgodna')
    out = {'at': NOW, 'src': PIP_SRC, 'url': PIP_PAGE,
           'unit': 'mln USD; stan na koniec półrocza (nie przepływ); zmiana = stan minus stan półrocza wcześniej (z cenami i kursami walut)',
           'okres': L, 'pol_e': pol_e, 'pary': None, 'pol_p': None, 'ok': {'pol_e': True, 'pary': True}, 'part_at': {'pol_e': NOW}, 'bledy': []}
    pp = prev.get('pary') if isinstance(prev.get('pary'), dict) and _pip_half(prev['pary'].get('okres')) else None
    pat = prev['part_at'].get('pary') if isinstance(prev.get('part_at'), dict) else None
    proba = prev.get('pary_proba') if isinstance(prev.get('pary_proba'), str) else None
    potrzeba = pp is None or pp['okres'] < L or not _zapas_wiek_ok(pat, PIP_PELNE_DNI)
    late = run_t0 is not None and time.monotonic() - run_t0 > PIP_LATE
    if potrzeba and not late and not (proba and _zapas_wiek_ok(proba, PIP_PONOW_H / 24)):
        try:
            serm = _pip_ser(fetch(PIP_ALL_URL, PIP_T_PELNE))
            Lm = _pip_okres(serm)
            out['pary'], out['pol_p'] = _pip_pary(serm, Lm), _pip_rola(serm, 'POL', 'p', Lm)
            out['part_at']['pary'] = NOW
            return out
        except Exception as e:  # noqa — część z poprzedniego pliku, błąd w meta; ponowienie najwcześniej po PIP_PONOW_H h
            out['bledy'].append(mask(f'MFW PIP (pełna macierz): {e}')[:200]); proba = NOW
    if proba:
        out['pary_proba'] = proba
    if pp:
        out['pary'], out['pol_p'], out['part_at']['pary'] = pp, (prev.get('pol_p') if isinstance(prev.get('pol_p'), dict) else None), pat
    if potrzeba:
        out['ok']['pary'] = False
    return out


# v72: SAFE (Chiny) — kupno i sprzedaż walut przez banki w imieniu klientów, miesięcznie, w USD; bez klucza
SAFE_PAGE = 'https://www.safe.gov.cn/en/2023/0215/2048.html'
SAFE_LINK = 'Time-series Data of Foreign Exchange Settlement and Sales by Banks'
SAFE_SHEET = 'in USD (Monthly)'
SAFE_KEEP = 25     # miesięcy (12-miesięczna suma i porównanie rok do roku)


def _xlsx_rows(data, sheet):
    """Czytnik .xlsx na bibliotece standardowej (zip + ElementTree): {nr wiersza: {nr kolumny: tekst}} arkusza o podanej nazwie.
    v77: puste komórki i wiersze pomijane bez przesuwania sąsiednich; tekst sformatowany (kilka <r><t>) sklejany; komórka bez
    adresu = następna kolumna; system dat 1904 = jawny błąd (daty byłyby przesunięte o 4 lata)."""
    import html as _h
    import zipfile
    import xml.etree.ElementTree as ET
    z = zipfile.ZipFile(io.BytesIO(data))
    names = set(z.namelist())
    loc = lambda tag: str(tag).rsplit('}', 1)[-1]
    def text(el):   # v80: tekst elementu bez podpowiedzi fonetycznych (<rPh>)
        if loc(el.tag) == 'rPh':
            return ''
        own = (el.text or '') if loc(el.tag) == 't' else ''
        return own + ''.join(text(c) for c in el)
    strs = []
    if 'xl/sharedStrings.xml' in names:
        strs = [text(si) for si in ET.fromstring(z.read('xl/sharedStrings.xml')) if loc(si.tag) == 'si']
    wb = z.read('xl/workbook.xml').decode('utf-8')
    if re.search(r'date1904="(1|true)"', wb):
        raise RuntimeError('system dat 1904 — nieobsługiwany')
    attr = lambda tag, a: (re.search(r'\b' + a + r'="([^"]*)"', tag) or [None, None])[1]
    rid = None
    for tag in re.findall(r'<sheet\b[^>]*>', wb):
        if _h.unescape(attr(tag, 'name') or '') == sheet:
            rid = attr(tag, 'r:id')
    if not rid:
        raise RuntimeError(f'brak arkusza „{sheet}”')
    target = None
    for tag in re.findall(r'<Relationship\b[^>]*>', z.read('xl/_rels/workbook.xml.rels').decode('utf-8')):
        if attr(tag, 'Id') == rid:
            target = attr(tag, 'Target')
    path = 'xl/' + target.lstrip('/').replace('xl/', '', 1) if target else None
    if path not in names:
        raise RuntimeError('brak pliku arkusza')
    col = lambda c: sum((ord(ch) - 64) * 26 ** i for i, ch in enumerate(reversed(c)))
    rows, rn = {}, 0
    for row in ET.fromstring(z.read(path)).iter():
        if loc(row.tag) != 'row':
            continue
        r = row.get('r')
        rn = int(r) if r and r.isdigit() else rn + 1
        cn = 0
        for c in row:
            if loc(c.tag) != 'c':
                continue
            m = re.match(r'^([A-Z]+)\d*$', c.get('r') or '')
            cn = col(m.group(1)) if m else cn + 1
            t = c.get('t')
            if t == 'inlineStr':
                v = text(c)
            else:
                ve = next((x for x in c if loc(x.tag) == 'v'), None)
                if ve is None or ve.text is None:
                    continue          # pusta komórka — bez wartości, sąsiedzi na swoich miejscach
                v = ve.text
                if t == 's':
                    i = int(v); v = strs[i] if 0 <= i < len(strs) else ''
            rows.setdefault(rn, {})[cn] = v.strip()
    return rows


def _xlsx_month(v):
    """Nagłówek miesiąca: liczba seryjna Excela (46235 = 2026-08-01) albo tekst '2026-08' / '2026.08' → 'YYYY-MM'."""
    s = str(v or '').strip()
    m = re.match(r'^(\d{4})[.\-/](\d{1,2})$', s)
    if m and 1 <= int(m.group(2)) <= 12:
        return f'{m.group(1)}-{int(m.group(2)):02d}'
    x = _num(s)
    if x is not None and 20000 < x < 80000:
        d = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(x))
        return f'{d.year:04d}-{d.month:02d}'
    return None


def parse_safe(rows):
    """Arkusz „in USD (Monthly)” → [[YYYY-MM, klienci saldo, bieżący saldo, kapitałowy saldo, bezpośrednie saldo, portfelowe saldo,
    kapitałowy rozliczenie, kapitałowy sprzedaż]] w mld USD (plik: 100 mln USD). Wiersze po nazwie w sekcjach I/II/III, nie po numerze."""
    head = next((r for _, r in sorted(rows.items()) if r.get(1, '').strip().lower() == 'item'), None)
    if not head:
        raise RuntimeError('brak wiersza nagłówka')
    months = {c: _xlsx_month(v) for c, v in head.items() if c > 1}
    months = {c: m for c, m in months.items() if m}
    if not months:
        raise RuntimeError('brak miesięcy w nagłówku')
    sec, cust, got = None, False, {}
    for _, r in sorted(rows.items()):
        lab = re.sub(r'\s+', ' ', r.get(1, '')).strip()
        m = re.match(r'^(I|II|III|IV|V|VI|VII|VIII)\.\s', lab)
        if m:
            sec, cust = m.group(1), False
            continue
        if sec not in ('I', 'II', 'III'):
            continue
        low = lab.lower()
        if low.startswith('(ii) by banks for customers'):
            cust = True; key = 'cust'
        elif low.startswith('(i) by banks for themselves'):
            cust = False; continue
        elif cust and low.startswith('1. current account'):
            key = 'ca'
        elif cust and low.startswith('2. capital and financial account'):
            key = 'cfa'
        elif cust and 'direct investment' in low:
            key = 'fdi'
        elif cust and low.startswith('portfolio investment'):
            key = 'port'
        else:
            continue
        got[(sec, key)] = {months[c]: _num(v) for c, v in r.items() if c in months and _num(v) is not None and _num(v) == _num(v)}
    need = [('III', 'cust'), ('III', 'ca'), ('III', 'cfa')]
    if any(k not in got for k in need):
        raise RuntimeError('brak wierszy salda (klienci / bieżący / kapitałowy)')
    keys = [('III', 'cust'), ('III', 'ca'), ('III', 'cfa'), ('III', 'fdi'), ('III', 'port'), ('I', 'cfa'), ('II', 'cfa')]
    allm = sorted({mm for k in keys for mm in (got.get(k) or {})})
    bn = lambda v: None if v is None else round(v / 10, 2)
    out = [[mm] + [bn((got.get(k) or {}).get(mm)) for k in keys] for mm in allm]
    out = [r for r in out if any(x is not None for x in r[1:])][-SAFE_KEEP:]
    g = out[-1][6]   # straż skali: rozliczenia kapitałowe klientów w miesiącu to dziesiątki mld USD
    if g is not None and not 5 <= g <= 1000:
        raise RuntimeError(f'skala niezgodna (rozliczenia kapitałowe {g} mld USD)')
    return out


def build_safe():
    page = get_bytes(SAFE_PAGE, timeout=60).decode('utf-8', 'replace')
    href = next((h for h, t in re.findall(r'<a[^>]+href="([^"]+\.xlsx)"[^>]*>(.*?)</a>', page, re.S)
                 if SAFE_LINK.lower() in re.sub(r'<[^>]+>', '', t).lower()), None)
    if not href:
        raise RuntimeError('brak odnośnika do pliku')
    url = href if href.startswith('http') else 'https://www.safe.gov.cn' + href
    m = parse_safe(_xlsx_rows(get_bytes(url, timeout=90), SAFE_SHEET))
    ids = [r for r in m if None not in r[1:4] and abs(r[1] - r[2] - r[3]) > 0.2]
    if ids:
        META['notes'].append(f'SAFE: saldo klientów ≠ bieżący + kapitałowy w {len(ids)} mies. (np. {ids[-1][0]})')
    return {'at': NOW, 'src': 'State Administration of Foreign Exchange (SAFE), Data on Foreign Exchange Settlement and Sales by Banks',
            'url': SAFE_PAGE, 'file': url, 'unit': 'mld USD; saldo = rozliczenie (klienci sprzedają waluty bankom) minus sprzedaż (kupują od banków)',
            'cols': ['miesiąc', 'klienci saldo', 'rachunek bieżący saldo', 'kapitałowy i finansowy saldo', 'w tym bezpośrednie saldo',
                     'w tym portfelowe saldo', 'kapitałowy rozliczenie', 'kapitałowy sprzedaż'],
            'asof': m[-1][0], 'm': m}


# v76: Eurostat — miesięczny bilans płatniczy krajów UE (bop_c6_m), bez klucza
UE_GEO = ['AT', 'BE', 'BG', 'CY', 'CZ', 'DE', 'DK', 'EE', 'EL', 'ES', 'FI', 'FR', 'HR', 'HU', 'IE', 'IT', 'LT', 'LU', 'LV', 'MT',
          'NL', 'PL', 'PT', 'RO', 'SE', 'SI', 'SK']
UE_KEYS = {('FA__P__F', 'LIAB'): 'in_p', ('FA__D__F', 'LIAB'): 'in_d', ('FA__O__F', 'LIAB'): 'in_o',
           ('FA__P__F', 'ASS'): 'out_p', ('FA__D__F', 'ASS'): 'out_d', ('FA__O__F', 'ASS'): 'out_o'}
UE_URL = ('https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/bop_c6_m?format=JSON&lang=EN&currency=MIO_EUR'
          '&partner=WRL_REST&sector10=S1&sector10=S121&sectpart=S1&lastTimePeriod=24&' + '&'.join('geo=' + g for g in UE_GEO)
          + '&bop_item=FA__P__F&bop_item=FA__D__F&bop_item=FA__O__F&stk_flow=LIAB&stk_flow=ASS')


def parse_jsonstat(j):
    """JSON-stat 2.0 (Eurostat) → ({(kod wymiaru 1, 2, …): wartość}, id wymiarów, {(…): litery statusu}); indeks płaski = wiersz po
    wymiarach w kolejności 'id'; indeks kategorii jako obiekt albo lista (v80); status np. 'e' szacunek, 'p' wstępne (poufne bez wartości)."""
    try:
        ids, size = j['id'], j['size']
        keys = []
        for d in ids:
            idx = j['dimension'][d]['category']['index']
            if isinstance(idx, list):
                idx = {k: i for i, k in enumerate(idx)}
            keys.append([k for k, _ in sorted(idx.items(), key=lambda kv: kv[1])])
        vals = j.get('value') or {}
        stat = j.get('status') or {}
    except (KeyError, TypeError, AttributeError) as e:
        raise RuntimeError(f'nieznany kształt odpowiedzi ({e})')
    if isinstance(vals, list):
        vals = {str(i): v for i, v in enumerate(vals) if v is not None}
    if isinstance(stat, list):
        stat = {str(i): v for i, v in enumerate(stat) if v}

    def lab(flat):
        i, out = int(flat), []
        for s, ks in zip(reversed(size), reversed(keys)):
            out.append(ks[i % s]); i //= s
        return tuple(reversed(out))
    out, flags = {}, {}
    for flat, v in vals.items():
        try:
            k = lab(flat)
        except (ValueError, IndexError):
            continue
        x = _num(v)
        if x is not None and x == x:
            out[k] = x
            f = ''.join(ch for ch in str(stat.get(flat, '')).split('|')[0] if ch in 'ep')
            if f:
                flags[k] = f
    if not out:
        raise RuntimeError('brak wartości')
    return out, ids, flags


def parse_ue(j):
    """bop_c6_m → {kraj: {'m': ostatni miesiąc z kompletem składników, 's': {klucz: [[YYYY-MM, mln EUR]]}, 'f': {YYYY-MM: 'e'|'p'}}}.
    v80: „pozostałe” bez banku centralnego (S1 minus S121, tylko gdy są obie wartości; bez S121 = brak, nigdy suma z TARGET2)."""
    vals, ids, flags = parse_jsonstat(j)
    pos = {d: i for i, d in enumerate(ids)}
    rows, cb, fl = {}, {}, {}
    for lab, v in vals.items():
        item, flow, g, m = lab[pos['bop_item']], lab[pos['stk_flow']], lab[pos['geo']], lab[pos['time']]
        sec = lab[pos['sector10']] if 'sector10' in pos else 'S1'
        if g not in UE_GEO or not re.match(r'^\d{4}-\d{2}$', m):
            continue
        k = UE_KEYS.get((item, flow))
        if not k:
            continue
        if sec == 'S121':
            if item == 'FA__O__F':
                cb.setdefault(g, {}).setdefault(k, {})[m] = v
            continue
        if sec != 'S1':
            continue
        rows.setdefault(g, {}).setdefault(k, {})[m] = v
        if lab in flags and k.startswith('in_'):
            fl.setdefault(g, {})[m] = ''.join(sorted(set(fl.get(g, {}).get(m, '') + flags[lab])))
    out = {}
    for g in UE_GEO:
        s0 = rows.get(g) or {}
        s = {}
        for k, series in s0.items():
            if k.endswith('_o'):   # pozostałe bez banku centralnego
                c = (cb.get(g) or {}).get(k) or {}
                series = {m: v - c[m] for m, v in series.items() if m in c}
            if series:
                s[k] = [[m, round(v, 1)] for m, v in sorted(series.items())]
        have = lambda k: {m for m, _ in s.get(k, [])}
        full = have('in_p') & have('in_d') & have('in_o')
        anym = have('in_p') | have('in_d') | have('in_o')
        if anym:
            out[g] = {'m': max(full) if full else max(anym), 's': s}
            if fl.get(g):
                out[g]['f'] = fl[g]
    if not out:
        raise RuntimeError('żaden kraj z napływem kapitału')
    de = [abs(v) for _, v in ((out.get('DE') or {}).get('s', {}).get('in_p') or [])]
    if de and not 100 <= max(de) <= 1e6:
        raise RuntimeError(f'skala niezgodna (Niemcy, napływ portfelowy do {max(de)} mln EUR)')
    return {'src': 'Eurostat, Balance of payments by country — monthly data (BPM6), bop_c6_m', 'url': 'https://ec.europa.eu/eurostat/databrowser/view/bop_c6_m/default/table',
            'unit': 'mln EUR, transakcje w miesiącu; in_* = napływ kapitału z zagranicy (pasywa), out_* = kapitał mieszkańców za granicę (aktywa); '
                    'p portfelowe, d bezpośrednie, o pozostałe bez banku centralnego (S1 − S121); f = status Eurostatu (e szacunek, p wstępne)',
            'asof_max': max(r['m'] for r in out.values()), 'order': [g for g in UE_GEO if g in out], 'rows': out}


def build_ue():
    out = parse_ue(get_json(UE_URL))
    out['at'] = NOW
    return out


# v78: Kanada — Statistics Canada, tabela 36-10-0028-01 (International transactions in securities), miesięcznie, bez klucza
KAN_VEC = (('tot', 61915649), ('debt', 61915652), ('bond', 61915682), ('mm', 61915655), ('eq', 61915712))   # stałe numery wektorów „Net flows”
KAN_URL = 'https://www150.statcan.gc.ca/t1/wds/rest/getDataFromVectorByReferencePeriodRange?vectorIds={v}&startRefPeriod={a}&endReferencePeriod={b}'


def parse_kanada(j):
    """WDS → [[YYYY-MM, razem, dłużne, obligacje, rynek pieniężny, akcje]] w mln CAD; brak = None (nigdy 0); skala ≠ miliony = błąd."""
    names = {vid: k for k, vid in KAN_VEC}
    got = {}
    for x in j if isinstance(j, list) else []:
        o = (x or {}).get('object') or {}
        name = names.get(o.get('vectorId'))
        if not name:
            continue
        for p in o.get('vectorDataPoint') or []:
            m = re.match(r'^(\d{4}-\d{2})-01$', str(p.get('refPer', '')))
            v = p.get('value')
            if not m or not isinstance(v, (int, float)) or v != v:
                continue
            if p.get('scalarFactorCode') != 6:
                raise RuntimeError(f'skala niezgodna (scalarFactorCode {p.get("scalarFactorCode")})')
            got.setdefault(name, {})[m.group(1)] = round(float(v), 1)
    if 'tot' not in got:
        raise RuntimeError('brak serii „razem”')
    months = sorted({mm for d in got.values() for mm in d})[-25:]
    rows = [[mm] + [got.get(k, {}).get(mm) for k, _ in KAN_VEC] for mm in months]
    bad = [r[0] for r in rows if None not in (r[1], r[2], r[5]) and abs(r[1] - r[2] - r[5]) > 2]
    if bad:
        META['notes'].append('Statistics Canada: razem ≠ dłużne + akcje w miesiącach: ' + ', '.join(bad))
    return rows


def build_kanada():
    now = _now_utc().date()
    v = ','.join(f'%22{vid}%22' for _, vid in KAN_VEC)
    m = parse_kanada(get_json(KAN_URL.format(v=v, a=f'{now.year - 2}-{now.month:02d}-01', b=now.isoformat())))
    return {'at': NOW, 'src': 'Statistics Canada, Table 36-10-0028-01 International transactions in securities, portfolio transactions in Canadian and foreign securities, monthly',
            'url': 'https://www150.statcan.gc.ca/t1/tbl1/en/tv.action?pid=3610002801',
            'unit': 'mln CAD; transakcje nierezydentów w kanadyjskich papierach, netto (plus = zagranica kupiła netto)',
            'cols': ['miesiąc', 'razem', 'dłużne', 'obligacje', 'rynek pieniężny', 'akcje i jednostki funduszy'], 'asof': m[-1][0], 'm': m}


# v87: Polska — Ministerstwo Finansów: nierezydenci w krajowych skarbowych papierach wartościowych (SPW), miesięcznie, bez klucza.
# Odnośniki do plików zmieniają się co miesiąc — szukamy ich po stałych tytułach na stronie „Struktura inwestorów”.
SPW_PAGE = 'https://www.gov.pl/web/finanse/struktura-inwestorow'
SPW_BASE = 'https://www.gov.pl'
SPW_FILES = {'st': 'Struktura podmiotowa zadłużenia wobec nierezydentów w krajowych SPW',
             'kr': 'Zadłużenie wobec nierezydentów w krajowych SPW po krajach'}
SPW_A = re.compile(r'<a\b[^>]*href="(/attachment/[0-9a-f-]{36})"[^>]*>((?:(?!</a>).)*?)</a>', re.S)
SPW_FILE_RE = {'st': re.compile(r'Struktura_nierezydentow\d{2}\.xlsm'), 'kr': re.compile(r'Nierezydenci_kraje\d{2}\.xlsx')}   # v87.1: zapas — nazwa pliku
SPW_KEEP = 25      # miesięcy (zmiana 12 miesięcy i rok wcześniej)
SPW_GRP = 13       # miesięcy dla typów i regionów (zmiana 12 miesięcy)
SPW_STALE = 70     # dni po końcu najnowszego miesiąca bez nowego pliku = błąd (zwykle ok. miesiąca)
SPW_TYPES = (('bank', 'banki'), ('cb', 'banki centralne'), ('pub', 'instytucje publiczne'), ('ins', 'zakłady ubezpieczeniowe'),
             ('pen', 'fundusze emerytalne'), ('inv', 'fundusze inwestycyjne'), ('hf', 'fundusze hedgingowe'), ('hh', 'gospodarstwa domowe'),
             ('corp', 'przedsiębiorstwa niefinansowe'), ('oth', 'inne podmioty'), ('omni', 'rachunki zbiorcze'), ('tot', 'razem'))
SPW_REGS = (('ea', 'europa - kraje strefy euro'), ('eun', 'europa - kraje ue spoza strefy euro'), ('eur', 'europa - kraje spoza ue'),
            ('afr', 'afryka'), ('sam', 'ameryka południowa'), ('nam', 'ameryka północna'), ('oce', 'australia i oceania'),
            ('asia', 'azja'), ('me', 'bliski wschód'), ('omni', 'rachunki zbiorcze'), ('tot', 'razem'))


def _spw_month(v):
    x = _num(v)
    if x is None or not 30000 < x < 80000:
        return None
    d = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(x))
    return f'{d.year:04d}-{d.month:02d}'


def spw_sheet(rows, keys):
    """Arkusz MF → {miesiąc: {klucz: mln zł}}; kolumny po nazwach z wiersza nagłówka „Data” (najpierw nazwa dokładna, potem początek:
    „Banki” ≠ „Banki centralne”); brak kolumny „Razem” = błąd; pusta komórka = brak, nie zero."""
    col, out = None, {}
    for _, r in sorted(rows.items()):
        lab = re.sub(r'\s+', ' ', str(r.get(1, ''))).strip().lower()
        if col is None:
            if lab == 'data':
                heads = {c: re.sub(r'\s+', ' ', str(v)).strip().lower() for c, v in r.items() if c > 1}
                col = {}
                for k, pre in keys:
                    hit = [c for c, h in heads.items() if h == pre] or [c for c, h in heads.items() if h.startswith((pre + ' ', pre + '('))]
                    if len(hit) == 1:
                        col[k] = hit[0]
                if 'tot' not in col:
                    raise RuntimeError('brak kolumny „Razem”')
            continue
        m = _spw_month(r.get(1))
        if m:
            out[m] = {k: _num(r.get(c)) for k, c in col.items()}
    if not out:
        raise RuntimeError('brak miesięcy')
    return out


def spw_links(page):
    out, alt = {}, {}
    for href, txt in SPW_A.findall(page):
        t = re.sub(r'\s+', ' ', _html.unescape(re.sub(r'<[^>]+>', ' ', txt))).strip()
        for k, name in SPW_FILES.items():
            if t == name or t.startswith(name + ' '):     # „…w krajowych SPW” ≠ „…w krajowych SPW po krajach”
                out.setdefault(k, SPW_BASE + href)
            if SPW_FILE_RE[k].search(t.replace('\u200b', '').replace(' ', '')):
                alt.setdefault(k, SPW_BASE + href)      # v87.1: tytuł zmieniony — plik rozpoznany po nazwie
    for k, u in alt.items():
        out.setdefault(k, u)
    return out


def spw_countries(data):
    """Plik „po krajach” → [{'m': YYYY-MM, 'c': [[kraj PL, kraj EN, mln zł, udział %]]}] dla dwóch najnowszych arkuszy (pierwsze w pliku);
    bez wierszy sum, rachunków zbiorczych i banków centralnych (tak jak w źródle)."""
    import zipfile
    names = [_html.unescape(n) for n in re.findall(r'<sheet\b[^>]*\bname="([^"]+)"', zipfile.ZipFile(io.BytesIO(data)).read('xl/workbook.xml').decode('utf-8', 'replace'))]
    dated = []
    for nm in names:     # v87.1: arkusze według odczytanego miesiąca, od najnowszego (nie według kolejności w pliku)
        mm = re.search(r'\(\s*([A-Za-z]+)\s*(\d{4})\s*\)', nm)
        mo = MONTHS_EN.get(mm.group(1).capitalize()) if mm else None
        if mo:
            dated.append((f'{mm.group(2)}-{mo:02d}', nm))
    if not dated:
        raise RuntimeError('brak arkuszy z miesiącem')
    out = []
    for ym, nm in sorted(dated, reverse=True)[:2]:
        cs = []
        for _, r in sorted(_xlsx_rows(data, nm).items()):
            lab = re.sub(r'\s+', ' ', str(r.get(1, ''))).strip()
            v, sh = _num(r.get(2)), _num(r.get(3))
            if '/' not in lab or v is None or lab.lower().startswith(('suma', 'rachunki zbiorcze', 'banki centralne', 'razem', 'kraje')):
                continue
            pl, en = [x.strip() for x in lab.split('/', 1)]
            en = re.sub(r'\s*\(the\)', '', en).replace('(the ', '(')      # v87.1: „Netherlands (the)” → „Netherlands”
            cs.append([pl, en, v, None if sh is None else round(sh * 100, 2)])
        if not cs:
            raise RuntimeError(f'brak krajów w arkuszu „{nm}”')
        tot = sum(c[3] for c in cs if c[3] is not None)
        if not 99 <= tot <= 101:
            raise RuntimeError(f'udziały krajów w arkuszu „{nm}” sumują się do {tot:.1f}%, nie do 100%')
        out.append({'m': ym, 'c': cs})
    return out


SPW_KR_MAX_M = 3   # v328: kraje z poprzedniego pliku najwyżej tyle miesięcy starsze od stanu (m) — starszych nie pokazujemy


def _spw_zapas(out, prev, ostatni):
    """v328 (Z3-01): plik „po krajach” zawiódł — lista krajów (kr) z poprzedniego pliku, każdy arkusz z WŁASNYM miesiącem (strona podaje go przy tabeli),
    z czasem pobrania w out['part_at']['kr']; lista starsza niż SPW_KR_MAX_M miesięcy od stanu `ostatni` — bez zapasu (brak, nie stare dane)."""
    pk = prev.get('kr') if isinstance(prev, dict) else None
    if not (isinstance(pk, list) and pk and isinstance(pk[0], dict) and isinstance(pk[0].get('m'), str) and isinstance(pk[0].get('c'), list)):
        return
    if pk[0]['m'] < _ym_add(ostatni, -SPW_KR_MAX_M):
        return
    out['kr'] = pk
    out.setdefault('part_at', {})['kr'] = _zapas_czas(prev, 'kr')
    META['notes'].append(f"MF SPW: kraje z poprzedniego pliku (za {pk[0]['m']}), stan za {ostatni}")


def build_spw(prev=None):
    """data/spw.json — m: [[miesiąc, razem, obligacje, bony]] mln zł (wartość nominalna, koniec miesiąca), 25 miesięcy;
    t / r: {typ|region: [[miesiąc, mln zł]]} 13 miesięcy; kr: kraje (2 najnowsze miesiące, opcjonalnie)."""
    L = spw_links(get_bytes(SPW_PAGE, timeout=60).decode('utf-8', 'replace'))
    if 'st' not in L:
        raise RuntimeError('brak odnośnika do pliku struktury nierezydentów')
    data = get_bytes(L['st'], timeout=90)
    T = spw_sheet(_xlsx_rows(data, 'Razem_podmiot'), SPW_TYPES)
    R = spw_sheet(_xlsx_rows(data, 'Razem_region'), SPW_REGS)
    B = spw_sheet(_xlsx_rows(data, 'Obligacje skarbowe_podmiot'), (('tot', 'razem'),))
    S = spw_sheet(_xlsx_rows(data, 'Bony skarbowe_podmiot'), (('tot', 'razem'),))
    ms = sorted(m for m in T if T[m].get('tot') is not None)[-SPW_KEEP:]
    bad = [m for m in ms if not 1e4 < T[m]['tot'] < 1e7]     # razem poza 10 mld – 10 bln zł = zła skala
    if bad:
        raise RuntimeError(f'skala niezgodna ({bad[-1]})')
    lost = [k for G, keys in ((T, SPW_TYPES), (R, SPW_REGS)) for k, _ in keys if k not in G.get(ms[-1], {})]
    if lost:
        META['errors'].append('MF SPW: brak kolumn: ' + ', '.join(lost))     # v87.1: nowa albo zmieniona kolumna = błąd, nie cisza
    gap = [m for m in ms[-SPW_GRP:] if any(abs(sum(v for k, v in G.get(m, {}).items() if k != 'tot' and v is not None) - T[m]['tot']) > 1 for G in (T, R))
           or abs(((B.get(m) or {}).get('tot') or 0) + ((S.get(m) or {}).get('tot') or 0) - T[m]['tot']) > 1]
    if gap:
        META['errors'].append('MF SPW: sumy niezgodne w miesiącach: ' + ', '.join(gap))
    grp = ms[-SPW_GRP:]
    out = {'at': NOW, 'src': 'Ministerstwo Finansów — Struktura podmiotowa zadłużenia wobec nierezydentów w krajowych SPW (miesięcznie)',
           'url': SPW_PAGE, 'unit': 'mln zł, wartość nominalna, stan na koniec miesiąca', 'asof': ms[-1],
           'cols': ['miesiąc', 'razem', 'obligacje skarbowe', 'bony skarbowe'],
           'm': [[m, T[m]['tot'], (B.get(m) or {}).get('tot'), (S.get(m) or {}).get('tot')] for m in ms],
           't': {k: [[m, (T.get(m) or {}).get(k)] for m in grp] for k, _ in SPW_TYPES if k != 'tot'},
           'r': {k: [[m, (R.get(m) or {}).get(k)] for m in grp] for k, _ in SPW_REGS if k != 'tot'}}
    out['ok'] = {'st': True, 'kr': True}   # v328: plik „po krajach” może zawieść osobno — wtedy kr z poprzedniego pliku (_spw_zapas), plik niepełny świeży 55 min
    try:
        if 'kr' not in L:
            raise RuntimeError('brak odnośnika do pliku „po krajach”')
        out['kr'] = spw_countries(get_bytes(L['kr'], timeout=90))
        if out['kr'][0]['m'] != ms[-1]:
            META['notes'].append(f"MF SPW: kraje za {out['kr'][0]['m']}, stan za {ms[-1]} (tabela krajów ma własny miesiąc)")
    except Exception as e:
        META['errors'].append(mask(f'MF SPW kraje: {e}'))
        out['ok']['kr'] = False
        _spw_zapas(out, prev, ms[-1])
    y, mo = int(ms[-1][:4]), int(ms[-1][5:7])
    end = datetime.date(y + (mo == 12), mo % 12 + 1, 1) - datetime.timedelta(days=1)
    if (_now_utc().date() - end).days > SPW_STALE:
        META['errors'].append(f'MF SPW: brak nowego miesiąca po {ms[-1]}')
    return out


# v88: Meksyk — Banco de México (SIE, tabela CA138): stan meksykańskich papierów rządowych u nierezydentów, dziennie, mln MXN
# w wartości nominalnej; eksport CSV bez tokenu (formularz strony); ≈ USD kursem Fed H.10 (FRED DEXMXUS).
import urllib.parse
BMX_URL = 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?accion=consultarSeries'
BMX_PAGE = 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?accion=consultarCuadroAnalitico&idCuadro=CA138&sector=7&locale=es'
BMX_SER = (('ext', 'SF65218'), ('tot', 'SF65219'),    # Residentes en el Extranjero (II); Total en Circulación (I + II)
           ('bon', 'SF65137'), ('cet', 'SF65046'), ('udi', 'SF65107'), ('udv', 'SP68257'))   # v88.1: Bonos M, Cetes, Udibonos (mln UDI), wartość UDI
MX_KEEP = 270      # ok. 13 miesięcy sesji
MX_STALE = 21      # dni bez nowego dnia (zwykłe opóźnienie ok. 1,5 tygodnia) = błąd
# v126: oficjalne API SIE (sekret BANXICO_TOKEN, tylko nagłówek Bmx-Token): te same serie co formularz, jedno zapytanie na odświeżenie
# (kategoria „histórica”: 200 zapytań na 5 min, 10 000 na dobę — zbieracz pyta zwykle 4 razy na dobę, co 6 h; gdy odświeżenie Meksyku
# się nie uda, ponawia w każdym przebiegu co 20 min — do ok. 72 na dobę, plus przebiegi ręczne); formularz zostaje jako zapas
BMX_API = 'https://www.banxico.org.mx/SieAPIRest/service/v1/series/{ids}/datos/{a}/{b}'
BMX_TOKEN_KSZTALT = re.compile(r'[A-Za-z0-9]{64}')   # token SIE: 64 litery/cyfry (strona banku „token”); inny kształt nie jest wysyłany


def post_bytes(url, form, timeout=90):
    data = urllib.parse.urlencode(form, doseq=True).encode()
    req = urllib.request.Request(url, data=data, headers={'User-Agent': 'CapitalFlowAI-collector/1.0', 'Content-Type': 'application/x-www-form-urlencoded'})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read()


def parse_bmx(text):
    """CSV z SIE → [[data, nierezydenci, razem w obiegu, Bonos M, Cetes, Udibonos w pesos]] mln MXN, rosnąco; kolumny po kodach serii
    z wiersza „Fecha”; puste albo „N/E” = brak (nie zero); dzień bez nierezydentów pominięty (np. dni z samą wartością UDI);
    v88.1: Udibonos (mln UDI) × wartość UDI z tego dnia = mln MXN."""
    rows = list(csv.reader(io.StringIO(text)))
    head = next((r for r in rows if r and r[0].strip() == 'Fecha'), None)
    if not head:
        raise RuntimeError('brak wiersza z kodami serii')
    col = {c: head.index(c) for _, c in BMX_SER if c in head}     # v126: wartości po kodach serii, wiersze składa _bmx_join (wspólne z API)
    by = {c: {} for c in col}
    for r in rows:
        m = re.match(r'^(\d{2})/(\d{2})/(\d{4})$', r[0].strip()) if r else None
        if not m:
            continue
        for c, i in col.items():
            v = _num(r[i]) if i < len(r) and r[i].strip() not in ('', 'N/E') else None
            if v is not None:
                by[c][f'{m.group(3)}-{m.group(2)}-{m.group(1)}'] = v
    return _bmx_join(by)


def _bmx_join(by):
    """v126: wiersze Meksyku — wspólne dla formularza (CSV) i API SIE (JSON), więc obie drogi dają te same liczby.
    by = {kod serii: {RRRR-MM-DD: liczba}} (tylko liczby; brak = brak klucza) → [[data, nierezydenci, razem w obiegu, Bonos M, Cetes,
    Udibonos w pesos]] rosnąco; dzień bez nierezydentów pominięty (np. dni z samą wartością UDI); Udibonos (mln UDI) × wartość UDI z tego
    dnia = mln MXN; brak serii albo wartości = brak (None), nigdy zero."""
    col = {k: by[c] for k, c in BMX_SER if c in by}
    if 'ext' not in col:
        raise RuntimeError('brak serii SF65218 (nierezydenci)')
    out = {}
    for day, ext in col['ext'].items():
        if ext is None:
            continue
        v = {k: col[k].get(day) for k in col}
        udi = round(v['udi'] * v['udv'], 2) if v.get('udi') is not None and v.get('udv') is not None else None
        out[day] = [ext, v.get('tot'), v.get('bon'), v.get('cet'), udi]
    if not out:
        raise RuntimeError('brak dni')
    return [[k] + out[k] for k in sorted(out)]


def parse_bmx_api(j, ids=()):
    """v126: odpowiedź API SIE (JSON) → te same wiersze co parse_bmx. Kształt (dokumentacja SIE API v1, zapytanie o zakres dat):
    {"bmx": {"series": [{"idSerie": "SF65218", "titulo": "…", "datos": [{"fecha": "dd/mm/rrrr", "dato": "1,787,788.99" | "N/E"}]}]}};
    kolejność serii dowolna (po idSerie); przecinki tysięcy usuwa _num; „N/E” i puste = brak (nie zero); seria bez „datos” = brak danych
    w zakresie (kolumna pusta); seria z listy ids nieobecna w odpowiedzi = błąd (wtedy formularz)."""
    b = j.get('bmx') if isinstance(j, dict) else None
    ser = b.get('series') if isinstance(b, dict) else None
    if not isinstance(ser, list):
        raise RuntimeError('odpowiedź bez bmx.series')
    by = {}
    for s in ser:
        if not isinstance(s, dict) or not isinstance(s.get('idSerie'), str):
            continue
        vals = by.setdefault(s['idSerie'].strip(), {})
        for o in s.get('datos') if isinstance(s.get('datos'), list) else []:
            o = o if isinstance(o, dict) else {}
            m = re.match(r'^(\d{2})/(\d{2})/(\d{4})$', str(o.get('fecha', '')).strip())
            t = str(o.get('dato', '')).strip()
            v = _num(t) if m and t not in ('', 'N/E') else None
            if v is not None:
                vals[f'{m.group(3)}-{m.group(2)}-{m.group(1)}'] = v
    miss = [c for c in ids if c not in by]
    if miss:
        raise RuntimeError('brak serii w odpowiedzi: ' + ', '.join(miss))
    return _bmx_join(by)


class _BmxNoRedirect(urllib.request.HTTPRedirectHandler):
    """v126: przekierowanie z API SIE = błąd (HTTPError 3xx), nie nowe zapytanie — urllib przy przekierowaniu kopiuje wszystkie
    nagłówki zapytania (także Bmx-Token) na nowy adres, nawet na inny serwer."""

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


class BmxTokenOdrzucony(RuntimeError):
    """v126: bank nie przyjął tokenu (obiekt błędu SIE z komunikatem o tokenie, bez pól limitu) — notatka dla właściciela, nie błąd źródła."""


def bmx_fetch(url, token, timeout=60):
    """v126: jedno GET do API SIE: token TYLKO w nagłówku Bmx-Token (nigdy ?token= w adresie), bez przekierowań, bez kompresji → JSON."""
    req = urllib.request.Request(url, headers={'User-Agent': 'CapitalFlowAI-collector/1.0', 'Accept': 'application/json', 'Bmx-Token': token})
    with urllib.request.build_opener(_BmxNoRedirect).open(req, timeout=timeout) as r:
        return json.loads(r.read().decode('utf-8', 'replace'))


def _bmx_txt(x, token=''):
    """v126: tekst z odpowiedzi banku do komunikatu — NAJPIERW maskowanie całości (SECRETS i sam token, także gdy SECRETS jeszcze go nie ma),
    potem każdy ciąg ≥ 20 liter/cyfr (np. urywek tokenu) = ***; skraca dopiero wołający (token ucięty w połowie nie pasowałby już
    do SECRETS i przeszedłby przez końcowe maskowanie do meta.json)."""
    t = mask(' '.join(str(x or '').split()))
    if token:
        t = t.replace(token, '***')
    return re.sub(r'[A-Za-z0-9]{20,}', '***', t)


def bmx_api(token, ids, a, b):
    """v126: serie ids od a do b (RRRR-MM-DD) z API SIE — jedno zapytanie, bez ponawiania (blokada limitu trwa do końca okna).
    Błąd SIE: {"error": {"mensaje", "detalle", "timeReset"?, "secondsToReset"?}} (bank nie odbija tokenu). Token odrzucony = obiekt błędu
    SIE z komunikatem o tokenie i bez pól limitu (np. HTTP 400 „Token inválido”) → BmxTokenOdrzucony(komunikat banku); każda inna odmowa —
    także 401/403 bez obiektu błędu SIE (strona zapory albo CDN to nie bank o tokenie) → RuntimeError('HTTP kod: komunikat'
    + ' (blokada limitu jeszcze N s)' przy limicie). Komunikat: maskowany w całości, dopiero potem skrócony do 80 znaków."""
    code, why = 200, 'odpowiedź z polem error'
    try:
        j = bmx_fetch(BMX_API.format(ids=','.join(ids), a=a, b=b), token)
    except urllib.error.HTTPError as e:
        code, why = e.code, e.reason
        try:
            j = json.loads(e.read().decode('utf-8', 'replace'))
        except Exception:
            j = None
        finally:
            e.close()
        if not (isinstance(j, dict) and 'error' in j):
            j = {'error': None}
    if not (isinstance(j, dict) and 'error' in j):
        return j
    err = j['error'] if isinstance(j['error'], dict) else {}
    full = _bmx_txt(err.get('mensaje'), token)
    msg = full[:80]
    if 'token' in full.lower() and not ('timeReset' in err or 'secondsToReset' in err):
        raise BmxTokenOdrzucony(msg)
    wait = str(err.get('secondsToReset', '')).strip()
    raise RuntimeError(f'HTTP {code}: {msg or _bmx_txt(why, token)[:80]}' + (f' (blokada limitu jeszcze {wait} s)' if re.fullmatch(r'\d+', wait) else ''))


def _mx_bad(d):
    """Dni spoza skali (v126: wspólne dla formularza i API)."""
    return [r[0] for r in d if not 1e5 < r[1] < 1e8 or (r[2] is not None and not r[1] < r[2] < 1e9)]   # 0,1–100 bln MXN; mniej niż całość


def bmx_api_rows(token, now):
    """v126: wiersze Meksyku z API SIE (te same serie i ten sam zakres lat co formularz) albo None = formularz jak dotąd.
    Token w innym kształcie niż token SIE nie jest wysyłany; token odrzucony = JEDNA notatka (nazwa sekretu, nigdy wartość), nie błąd;
    inna awaria (sieć, limit, odpowiedź, skala) = błąd „Banxico API (zapas: formularz)”."""
    if not BMX_TOKEN_KSZTALT.fullmatch(token):
        META['notes'].append('BANXICO_TOKEN odrzucony przed wysłaniem: to nie jest token Banxico (64 litery i cyfry) — Meksyk z formularza')
        return None
    ids = [c for _, c in BMX_SER]
    b = (_now_utc() - datetime.timedelta(hours=6)).date()   # dzień w Meksyku (UTC−6, bez czasu letniego od 2022): koniec zakresu nie „jutro”
    try:
        d = parse_bmx_api(bmx_api(token, ids, f'{now.year - 2}-01-01', b.isoformat()), ids)[-MX_KEEP:]
        bad = _mx_bad(d)
        if bad:
            raise RuntimeError(f'skala niezgodna ({bad[-1]})')
    except BmxTokenOdrzucony as e:
        META['notes'].append(mask(f'BANXICO_TOKEN odrzucony przez bank ({e}) — Meksyk z formularza'))
        return None
    except Exception as e:
        META['errors'].append(mask(f'Banxico API (zapas: formularz): {e}'))
        return None
    print(f'MEKSYK: dane z API SIE (BANXICO_TOKEN), {len(d)} sesji do {d[-1][0]}')
    return d


MX_FX_DNI = 7   # v328: kurs z poprzedniego pliku najwyżej tyle dni przed dniem ostatnich danych


def _mx_fx_zapas(out, prev):
    """v328 (Z3-01): zapytanie o kurs (FRED DEXMXUS) zawiodło — kurs z poprzedniego pliku [kurs, dzień kursu], gdy dzień kursu jest nie późniejszy niż dzień
    ostatnich danych (asof) i nie wcześniejszy niż MX_FX_DNI dni przed nim; z czasem pobrania w out['part_at']['fx']. Inaczej — bez kursu (brak, nie zero)."""
    fx = prev.get('fx') if isinstance(prev, dict) else None
    if not (isinstance(fx, list) and len(fx) == 2 and _isnum(fx[0]) and fx[0] > 0 and isinstance(fx[1], str)):
        return
    try:
        wiek = (datetime.date.fromisoformat(out['asof']) - datetime.date.fromisoformat(fx[1])).days
    except (TypeError, ValueError):
        return
    if 0 <= wiek <= MX_FX_DNI:
        out['fx'] = [fx[0], fx[1]]
        out['part_at'] = {'fx': _zapas_czas(prev, 'fx')}


def build_meksyk(key, token='', prev=None):
    """data/meksyk.json — d: [[data, nierezydenci, razem w obiegu, Bonos M, Cetes, Udibonos]] mln MXN nominalnie (270 sesji);
    fx: [kurs MXN/USD, dzień kursu] (Fed, z dnia danych albo najbliższego wcześniejszego).
    v126: z tokenem (sekret BANXICO_TOKEN) najpierw oficjalne API SIE — te same serie i ten sam zakres, więc te same wiersze; bez tokenu,
    z tokenem odrzuconym albo po awarii API — formularz jak dotąd (bmx_api_rows). Plik ma te same pola co dotąd."""
    now = _now_utc().date()
    d = bmx_api_rows(token, now) if token else None
    if d is None:
        form = {'locale': 'es', 'idCuadro': 'CA138', 'sector': '7', 'version': '3', 'series': [c for _, c in BMX_SER],
                # v88.1: dwa lata wstecz — w styczniu też jest koniec poprzedniego roku
                'anoInicial': str(now.year - 2), 'anoFinal': str(now.year),
                # v328 (Z3-05): od v88.1 (komentarz w tej samej linii połknął dwa pola) formularz NIE wysyła pól 'tipoInformacion' ('4,1') i 'formatoHorizontal'
                # ('false') — i to działa (CSV z 6 kolumnami, sprawdzone 25–27.09.2026). Zestaw pól jest przypięty testem (MeksykV88); przywrócenie obu pól —
                # dopiero po sondzie w Actions (porównanie CSV z polami i bez), nie na ślepo (bez sondy nie wysyłamy POST)
                'metadatosWeb': 'true', 'formatoCSV.x': '10', 'formatoCSV.y': '10'}
        d = parse_bmx(post_bytes(BMX_URL, form).decode('latin-1'))[-MX_KEEP:]
    bad = _mx_bad(d)
    if bad:
        raise RuntimeError(f'skala niezgodna ({bad[-1]})')
    over = [r[0] for r in d[-30:] if None not in r[3:6] and r[3] + r[4] + r[5] > r[1] + 1]
    if over:
        META['notes'].append('Banxico: Bonos M + Cetes + Udibonos większe niż całość u nierezydentów w dniach: ' + ', '.join(over))
    out = {'at': NOW, 'src': 'Banco de México — SIE, Valores gubernamentales: tenencia de Residentes en el Extranjero (SF65218), Total en circulación (SF65219)',
           'url': BMX_PAGE, 'unit': 'mln MXN, wartość nominalna (rejestry INDEVAL, podlegają poprawkom)', 'cols': ['data', 'nierezydenci', 'razem w obiegu', 'Bonos M', 'Cetes', 'Udibonos (w pesos)'],
           'asof': d[-1][0], 'd': d}
    out['ok'] = {'d': True}   # v328: kurs (fx) może zawieść osobno — wtedy z poprzedniego pliku (_mx_fx_zapas), plik niepełny świeży 55 min
    if key:
        try:
            rates = fred_rates(key, 'DEXMXUS')
            rd, rt = _rate_for(rates, d[-1][0])        # v88.1: kurs z dnia danych albo najbliższego wcześniejszego (jak w przypisie przeglądu)
            if rt:
                out['fx'] = [rt, rd]
            out['ok']['fx'] = True
        except Exception as e:
            META['errors'].append(mask(f'Banxico kurs FRED DEXMXUS: {e}'))
            out['ok']['fx'] = False
            _mx_fx_zapas(out, prev)
    if (now - datetime.date.fromisoformat(d[-1][0])).days > MX_STALE:
        META['errors'].append(f'Banxico: brak nowego dnia po {d[-1][0]}')
    return out


# v82: Korea Płd. — FSS, miesięczny komunikat „Foreign Investors' Stock and Bond Investment” (po angielsku), bez klucza
FSS_LIST = 'https://www.fss.or.kr/eng/bbs/B0000211/list.do?menuNo=400010&pageIndex={p}'
FSS_BASE = 'https://www.fss.or.kr'
FSS_PAGES = 12
FSS_TITLE = re.compile(r'<a href="(/eng/bbs/B0000211/view\.do\?[^"]+)"[^>]*>\s*Foreign Investors(?:&#39;|\'|’) Stock and Bond Investment, ([A-Z][a-z]+) (\d{4})\s*</a>')
FSS_SENT = re.compile(r'Foreign investors (bought|sold) a net KRW\s?([\d.,]+) (billion|trillion) of listed stocks? and (?:(bought|sold) )?a net KRW\s?([\d.,]+) '
                      r'(billion|trillion) of listed bonds in ([A-Z][a-z]+) (\d{4})')
MONTHS_EN = {m: i for i, m in enumerate(['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October',
                                         'November', 'December'], 1)}


def parse_fss(text):
    """Komunikat FSS → [YYYY-MM, akcje, obligacje] w mld KRW (plus = zakupy netto zagranicy); inne zdanie = None (nigdy zgadywanie)."""
    t = re.sub(r'\s+', ' ', _html.unescape(re.sub(r'<[^>]+>', ' ', str(text))))
    m = FSS_SENT.search(t)
    mo = MONTHS_EN.get(m.group(7)) if m else None
    if not mo:
        return None

    def val(side, num, unit):
        v = _num(num)
        if v is None:
            return None
        v *= 1000 if unit == 'trillion' else 1
        return round(v if side == 'bought' else -v, 1)
    return [f'{m.group(8)}-{mo:02d}', val(m.group(1), m.group(2), m.group(3)), val(m.group(4) or m.group(1), m.group(5), m.group(6))]   # bez drugiego czasownika = ten sam kierunek


def fss_months(a, b):
    """Lista miesięcy 'YYYY-MM' od a do b włącznie."""
    out, (y, m) = [], (int(a[:4]), int(a[5:7]))
    while f'{y:04d}-{m:02d}' <= b:
        out.append(f'{y:04d}-{m:02d}'); m += 1
        if m > 12:
            y, m = y + 1, 1
    return out


def build_korea(key, prev=None):
    """data/korea.json — [[YYYY-MM, akcje mld KRW, obligacje mld KRW, akcje ≈ mln USD, obligacje ≈ mln USD, kurs]]; 25 miesięcy.
    v83: komunikaty ze strony 1 czytane zawsze (poprawki); brakujące miesiące szukane na kolejnych stronach i zgłaszane przy
    każdym przebiegu; brak nowego komunikatu zbyt długo = błąd; wartość ponad 100 bln KRW = nieczytelna."""
    have = {r[0]: list(r) for r in ((prev or {}).get('m') or []) if isinstance(r, list) and r and isinstance(r[0], str)}
    had, newest, fails, missing = bool(have), None, [], []
    for p in range(1, FSS_PAGES + 1):
        page = get_bytes(FSS_LIST.format(p=p), timeout=60).decode('utf-8', 'replace')
        for href, mon, yr in FSS_TITLE.findall(page):
            mo = MONTHS_EN.get(mon)
            if not mo:
                continue
            ym = f'{yr}-{mo:02d}'
            newest = max(newest or ym, ym)
            if p > 1 and ym in have and have[ym][1] is not None and have[ym][2] is not None:
                continue
            try:
                r = parse_fss(get_bytes(FSS_BASE + _html.unescape(href), timeout=60).decode('utf-8', 'replace'))
                if not r or r[0] != ym or r[1] is None or r[2] is None or max(abs(r[1]), abs(r[2])) > 1e5:
                    raise RuntimeError('nieznany układ komunikatu')
                old = have.get(ym) or []
                have[ym] = r + (old[3:6] if len(old) >= 6 and old[1:3] == r[1:3] else [None, None, None])
            except Exception as e:
                fails.append(f'{ym}: {e}')
        if newest:
            lo = max(min(have) if had and have else _q_ym_add(newest, -12), _q_ym_add(newest, -24))
            missing = [m for m in fss_months(lo, newest) if m not in have]
            if not missing:
                break
    if not have:
        raise RuntimeError('brak komunikatów' + (f' ({fails[0]})' if fails else ''))
    if fails:
        META['errors'].append(mask(f'FSS: {len(fails)} komunikaty nieczytelne, np. {fails[0]}'))
    if missing:
        META['errors'].append(f'FSS: brak komunikatów za miesiące: {", ".join(missing)}')
    last = max(have)
    due = datetime.date(int(_q_ym_add(last, 2)[:4]), int(_q_ym_add(last, 2)[5:7]), 1) + datetime.timedelta(days=34)
    if _now_utc().date() > due:
        META['errors'].append(f'FSS: brak nowego komunikatu po {last} (ostatni termin {due.isoformat()})')
    rates = {}
    if key:
        try:
            rates = fred_rates(key, 'EXKOUS')   # Fed H.10, średnia miesięczna KRW za 1 USD
        except Exception as e:
            META['errors'].append(mask(f'FSS kurs FRED EXKOUS: {e}'))
    rows = [have[k] for k in sorted(have)][-25:]
    for r in rows:
        rt = rates.get(r[0] + '-01')
        if rt:
            r[3:6] = [round(r[1] * 1000 / rt, 1) if r[1] is not None else None, round(r[2] * 1000 / rt, 1) if r[2] is not None else None, rt]
        elif len(r) < 6 or r[5] is None:
            r[3:6] = [None, None, None]
    return {'at': NOW, 'src': 'Financial Supervisory Service (Korea) — monthly press release „Foreign Investors’ Stock and Bond Investment”',
            'url': FSS_LIST.format(p=1),
            'unit': 'mld KRW; akcje = zakupy netto (KOSPI, KOSDAQ, rozliczenie), obligacje = inwestycje netto (zakupy netto minus wykupy); '
                    '≈ mln USD po średnim kursie miesiąca (Fed H.10, FRED EXKOUS)',
            'cols': ['miesiąc', 'akcje mld KRW', 'obligacje mld KRW', 'akcje ≈ mln USD', 'obligacje ≈ mln USD', 'KRW za 1 USD'], 'asof': rows[-1][0], 'm': rows}


def _q_ym_add(ym, k):
    t = int(ym[:4]) * 12 + int(ym[5:7]) - 1 + k
    return f'{t // 12:04d}-{t % 12 + 1:02d}'


KR_ZAPAS_CZESCI = ('fng', 'mk', 'stabh', 'stabc')   # v276: części z własną datą/czasem danych — przy błędzie poprzednia wersja (deriv i defi: strona podpisuje je czasem pliku)
KR_ZAPAS_MAX_H = 3   # v281 (przegląd v276): najwyżej tyle godzin od pobrania części — strona dokłada zmiany 30 dni / 1 rok z 'mk' bez sprawdzania wieku,
#                      a panel stablecoinów podpisuje 'stabc' datą historii albo czasem pliku; dłużej — część znika jak przed v276 („—”)


def build_krypto(cg_key, prev=None):
    """data/krypto.json — każda część osobno (awaria jednej nie kasuje pozostałych); CoinGecko z kluczem w nagłówku. v276: część z własną datą
    albo czasem danych (KR_ZAPAS_CZESCI), która zawiodła, zostaje z poprzedniego pliku z czasem pobrania w 'part_at' — nie znika do następnej
    budowy; deriv i defi bez tego (strona podpisuje je czasem całego pliku — stara liczba wyglądałaby na świeżą)."""
    out = {'at': NOW, 'src': 'krypto', 'attribution': 'Data by CoinGecko', 'part_at': {}}
    hdr = {'x-cg-demo-api-key': cg_key} if cg_key else None
    jobs = [('deriv', lambda: parse_deriv(get_json(CG + '/derivatives/exchanges?per_page=20', hdr))),
            ('defi', lambda: parse_defi(get_json(CG + '/global/decentralized_finance_defi', hdr))),
            ('fng', lambda: parse_fng(get_json(FNG_URL))),
            ('mk', lambda: parse_mk([get_json(CG + f'/coins/markets?vs_currency=usd&order=market_cap_desc&per_page=250&page={p}'
                                             '&price_change_percentage=24h,7d,30d,1y', hdr) for p in (1, 2)])),
            ('stabh', lambda: parse_stabh(get_json('https://stablecoins.llama.fi/stablecoincharts/all'))),
            ('stabc', lambda: parse_stabc(ste_llama_zapamietaj(get_json('https://stablecoins.llama.fi/stablecoins?includePrices=true'))))]   # v58: per sieć
    udane = 0
    for name, job in jobs:
        try:
            out[name] = job(); META['ok']['krypto.' + name] = True; out['part_at'][name] = NOW; udane += 1
        except Exception as e:
            META['errors'].append(mask(f'krypto {name}: {e}')); META['ok']['krypto.' + name] = False
            if name in KR_ZAPAS_CZESCI:
                _czesc_z_zapasem(out, prev, name, max_h=KR_ZAPAS_MAX_H)   # v276: poprzednia wersja z własną datą danych (v281: najwyżej 3 h)
    if not udane:
        raise RuntimeError('żadne źródło rynku krypto nie odpowiedziało')
    return out


