def _t10_num(v):
    """Liczba skończona albo None (bool, tekst, NaN i nieskończoność = brak)."""
    return float(v) if isinstance(v, (int, float)) and not isinstance(v, bool) and v == v and abs(v) != float('inf') else None


def t10_row(x):
    """Wiersz odpowiedzi /coins/markets → [id, SYMBOL, nazwa, cena USD, kapitalizacja USD, zmiana 24 h %, czas notowania] albo None: bez poprawnego id,
    bez miejsca w rankingu kapitalizacji (token pochodny) albo bez dodatniej kapitalizacji. Cena ≤ 0 i brak zmiany = None, nigdy 0."""
    if not isinstance(x, dict):
        return None
    cid, rk, mc = x.get('id'), x.get('market_cap_rank'), _t10_num(x.get('market_cap'))
    if not (isinstance(cid, str) and T10_ID.match(cid)) or not (isinstance(rk, int) and not isinstance(rk, bool) and rk > 0) or not (mc and mc > 0):
        return None
    px, ch = _t10_num(x.get('current_price')), _t10_num(x.get('price_change_percentage_24h'))
    sym = re.sub(r'\s+', ' ', str(x.get('symbol') or '')).strip().upper()[:16] or cid[:8].upper()
    name = re.sub(r'\s+', ' ', str(x.get('name') or '')).strip()[:60] or sym
    upd = x.get('last_updated')
    try:
        upd = datetime.datetime.fromisoformat(upd[:19]).isoformat() + 'Z' if isinstance(upd, str) and T10_ISO.match(upd) else None
    except ValueError:                                     # data niemożliwa (np. 30 lutego) = brak czasu, nie zgadywanie
        upd = None
    return [cid, sym, name, px if px and px > 0 else None, mc, ch, upd]


def t10_img(x):
    """Adres małego obrazka monety (50 px) — tylko z serwera obrazów; inny adres = bez logo."""
    u = x.get('image') if isinstance(x, dict) else None
    if not isinstance(u, str) or not u.startswith(T10_LOGO_HOSTS) or len(u) > 400 or any(c in u for c in ' "\'<>\\'):
        return None
    return u.replace('/large/', '/small/', 1)


def _t10_mime(b):
    """Rodzaj obrazka z pierwszych bajtów (PNG, JPEG, WebP, GIF) albo None — SVG i HTML nie są logo."""
    if not isinstance(b, (bytes, bytearray)):
        return None
    if b[:8] == b'\x89PNG\r\n\x1a\n':
        return 'image/png'
    if b[:3] == b'\xff\xd8\xff':
        return 'image/jpeg'
    if b[:4] == b'RIFF' and b[8:12] == b'WEBP':
        return 'image/webp'
    if b[:6] in (b'GIF87a', b'GIF89a'):
        return 'image/gif'
    return None


def _t10_age(iso, now):
    """Wiek znacznika czasu w minutach (None = brak albo zły format)."""
    try:
        t = datetime.datetime.fromisoformat(str(iso).replace('Z', '+00:00'))
        return (now - t).total_seconds() / 60 if t.tzinfo else None
    except (TypeError, ValueError):
        return None


def _t10_ok_row(r):
    return (isinstance(r, list) and len(r) == len(T10_COLS) and isinstance(r[0], str) and bool(T10_ID.match(r[0]))
            and _t10_num(r[4]) is not None and r[4] > 0)


def _t10_mono():
    """Zegar budowniczego (monotoniczny) — w testach podmieniony."""
    return time.monotonic()


def _t10_sleep(s):
    """Czekanie budowniczego — w testach podmienione (zapisuje odstępy, przesuwa zegar)."""
    time.sleep(s)


def _t10_left(st):
    """Sekundy, które zostały z budżetu budowniczego."""
    return st['end'] - _t10_mono()


def _t10_get(url, hdr, st):
    """Jedno zapytanie do API z odstępem T10_SLEEP (limit minutowy) i limitem czasu ≤ tego, co zostało z budżetu; 429 = jedno ponowienie po T10_WAIT_429 s
    w całym przebiegu (gdy budżet na nie wystarcza). Budżet wyczerpany = wyjątek „limit czasu” (część w następnym przebiegu)."""
    if st['n']:
        if _t10_left(st) < T10_SLEEP + 2:
            raise RuntimeError(f'limit czasu ({T10_BUDGET} s)')
        _t10_sleep(T10_SLEEP)
    left = _t10_left(st)
    if left < 2:
        raise RuntimeError(f'limit czasu ({T10_BUDGET} s)')
    st['n'] += 1
    try:
        return get_json(url, hdr, timeout=max(1, min(T10_TIMEOUT, left)))
    except urllib.error.HTTPError as e:
        if e.code != 429 or st['retry'] or _t10_left(st) < T10_WAIT_429 + 3:
            raise
        st['retry'] = True
        _t10_sleep(T10_WAIT_429)
        st['n'] += 1
        return get_json(url, hdr, timeout=max(1, min(T10_TIMEOUT, _t10_left(st))))


def t10_logos(top, imgs, prev_logo=None, at=None, end=None, late=False):
    """data/krypto-top10-logo.json: {id monety: data:image/…} tylko dla monet obecnych w grupach. Logo z poprzedniego pliku zostaje (bez pobierania);
    nowe — z adresu z odpowiedzi API tego przebiegu (najwyżej T10_LOGO_NEW; każde z limitem czasu ≤ T10_IMG_TIMEOUT i ≤ tego, co zostało do end). Przebieg długi
    (late) albo budżet wyczerpany — bez nowych logo (w następnym przebiegu). Nie-obraz, za duże albo awaria = bez logo (notatka, nie błąd)."""
    old = prev_logo.get('logo') if isinstance(prev_logo, dict) and isinstance(prev_logo.get('logo'), dict) else {}
    need = []
    for k, _ in T10_CATS:
        for r in (((top or {}).get('g') or {}).get(k) or {}).get('c') or []:
            if _t10_ok_row(r) and r[0] not in need:
                need.append(r[0])
    logo, new, bad = {}, 0, []
    for cid in need:
        v = old.get(cid)
        if isinstance(v, str) and len(v) <= T10_LOGO_MAX * 4 // 3 + 40 and T10_DATA.match(v):
            logo[cid] = v
            continue
        u = (imgs or {}).get(cid)
        left = None if end is None else end - _t10_mono()
        if not u or new >= T10_LOGO_NEW or late or (left is not None and left < 2 + (T10_IMG_SLEEP if new else 0)):
            continue
        if new:
            _t10_sleep(T10_IMG_SLEEP)
            left = None if end is None else end - _t10_mono()
        new += 1
        try:
            b = get_bytes(u, timeout=max(1, min(T10_IMG_TIMEOUT, left)) if left is not None else T10_IMG_TIMEOUT)
            m = _t10_mime(b)
            if not m or len(b) > T10_LOGO_MAX:
                bad.append(f'{cid}: {"za duże" if m else "nie obraz"}')
                continue
            logo[cid] = f'data:{m};base64,' + base64.b64encode(bytes(b)).decode('ascii')
        except Exception as e:  # noqa — jedno logo nie psuje pliku
            bad.append(f'{cid}: {e}')
    nxt = sum(1 for cid in need if cid not in logo and (imgs or {}).get(cid))
    if bad or nxt:
        META['notes'].append(mask(f'krypto top 10 — loga: {len(bad)} bez obrazka (strona: znaczek z symbolem)'
                                  + (f', np. {bad[0]}' if bad else '') + (f'; {nxt} w następnym przebiegu' if nxt > len(bad) else ''))[:300])
    return {'at': at or _now_utc().replace(microsecond=0).isoformat(), 'n': len(logo), 'logo': logo}


def t10_glowny(pools):
    """v437: {id monety: sektor główny} dla monet, które są kandydatami choć jednego sektora (pools: {sektor: [id…]}). Wskazanie wprost z T10_GLOWNY, gdy ten sektor
    jest wśród kandydatów monety; inaczej pierwszy wg T10_PRIO z sektorów, w których moneta jest kandydatem (węższa kategoria wygrywa)."""
    gdzie = {}
    for k, _ in T10_CATS:
        for i in (pools or {}).get(k) or []:
            if k not in gdzie.setdefault(i, []):
                gdzie[i].append(k)
    return {i: (T10_GLOWNY[i] if T10_GLOWNY.get(i) in ks else min(ks, key=T10_PRIO.index)) for i, ks in gdzie.items()}


def _t10_fresh(r, now):
    """v330 (ZB04-02): wiersz z poprzedniego pliku wolno przenieść, gdy jego WŁASNE notowanie (kolumna upd) ma mniej niż T10_MAX_AGE min; brak czasu
    albo zły format = nie (brak danych, nie stara cena). Dawniej wiek liczony z czasu PLIKU, a ten dostaje nowy czas w każdym przebiegu."""
    a = _t10_age(r[6], now)
    return a is not None and a < T10_MAX_AGE


def t100_pack(rows, at):
    """v439: warstwa Top 100 jednej grupy — monety poza dziesiątką grupy (miejsca 11–100 w kategorii wg kapitalizacji) jako [kapitalizacja USD, zmiana 24 h %]
    (bez nazw i identyfikatorów: strona rysuje tylko linie i zakończenia, bez opisów monet); {'at': czas składu, 'c': [...]} albo None, gdy monet brak."""
    c = [[round(r[4]), round(r[5], 3) if r[5] is not None else None] for r in rows if r[4] and r[4] > 0]
    return {'at': at, 'c': c} if c and at else None


def t100_prev(w, now):
    """v439: warstwa Top 100 z poprzedniego pliku — tylko poprawna (czas składu z datą, wiersze [kapitalizacja > 0, zmiana albo null]) i młodsza niż T100_MAX_AGE;
    inaczej None (brak danych, nigdy stara liczba pod nowym czasem)."""
    if not isinstance(w, dict) or not isinstance(w.get('c'), list):
        return None
    a = _t10_age(w.get('at'), now)
    if a is None or a < 0 or a >= T100_MAX_AGE:
        return None
    c = [r for r in w['c'] if isinstance(r, list) and len(r) == 2 and _t10_num(r[0]) and r[0] > 0 and (r[1] is None or _t10_num(r[1]) is not None)][:T10_WIDE - T10_N]
    return {'at': w['at'], 'c': c} if c else None


def build_krypto_top10(cg_key, prev=None, prev_logo=None, now=None, run_t0=None):
    """(data/krypto-top10.json, data/krypto-top10-logo.json): grupy top 10 w 8 kategoriach. Kategoria bez składu młodszego niż T10_SKLAD albo z mniej
    niż T10_N kandydatami — pobranie kategorii; pozostałe (i kategorie z błędem, które mają poprzednich kandydatów) — ceny kandydatów jednym zapytaniem
    ids=…; wiersze bez nowych cen = poprzednie, ale tylko te, których własne notowanie (upd) ma mniej niż T10_MAX_AGE min (v330: dawniej wiek z czasu PLIKU), inaczej grupa pusta. Każda awaria części = błąd
    „krypto top 10: …” w meta; żadnej monety w żadnej grupie: bez poprzedniego pliku wyjątek (jak dotąd), z poprzednim plikiem (v330) PLIK Z PUSTYMI GRUPAMI (strona: „brak danych”, ok = False, błąd w meta, loga bez zmian) — poprzedni plik ze starymi cenami nie zostaje. Cały budowniczy ≤ T10_BUDGET s; przebieg
    zbieracza dłuższy niż T10_LATE s (run_t0 — start przebiegu, domyślnie _RUN_T0) — bez składu kategorii i bez nowych logo (notatka; w następnym przebiegu)."""
    now = now or _now_utc()
    at = now.replace(microsecond=0).isoformat()
    hdr = {'x-cg-demo-api-key': cg_key} if cg_key else None   # klucz tylko w nagłówku, nigdy w adresie ani w pliku
    pg = prev.get('g') if isinstance(prev, dict) and isinstance(prev.get('g'), dict) else {}
    t0 = _t10_mono()
    run_t0 = _RUN_T0[0] if run_t0 is None else run_t0
    late = run_t0 is not None and t0 - run_t0 > T10_LATE
    st, errs, imgs, G = {'n': 0, 'retry': False, 'end': t0 + T10_BUDGET}, [], {}, {}
    for k, cat in T10_CATS:
        p = pg.get(k) if isinstance(pg.get(k), dict) else {}
        pool = [i for i in (p.get('pool') or []) if isinstance(i, str) and T10_ID.match(i)][:T10_POOL]
        age = _t10_age(p.get('sk'), now)
        G[k] = {'cat': cat, 'sk': p.get('sk') if age is not None else None, 'pool': pool, 'rows': None, 'skl': False,
                'prev': [r for r in (p.get('c') or []) if _t10_ok_row(r)], 'todo': age is None or age >= T10_SKLAD or len(pool) < T10_N}

    def take(j, what):
        if not isinstance(j, list):
            raise RuntimeError(f'{what}: zła odpowiedź')
        rows = []
        for x in j:
            r = t10_row(x)
            if r:
                rows.append(r)
                u = t10_img(x)
                if u:
                    imgs.setdefault(r[0], u)
        return rows

    if late and any(G[k]['todo'] for k, _ in T10_CATS):
        META['notes'].append(f'krypto top 10: przebieg długi (> {T10_LATE} s) — skład kategorii i nowe loga w następnym przebiegu')
    for k, cat in T10_CATS:                                   # 1) skład kategorii na nowo (nie w długim przebiegu)
        if not G[k]['todo'] or late:
            continue
        try:
            rows = take(_t10_get(CG + f'/coins/markets?vs_currency=usd&category={cat}&order=market_cap_desc&per_page={T10_WIDE}&page=1'
                                 '&price_change_percentage=24h', hdr, st), cat)   # v439: 100 wierszy (10 grupy + warstwa Top 100) tym samym zapytaniem
            if not rows:
                raise RuntimeError(f'{cat}: brak monet z miejscem w rankingu')
            rows.sort(key=lambda r: -r[4])
            G[k].update(rows=rows, sk=at, skl=True, pool=[r[0] for r in rows[:T10_POOL]])
        except Exception as e:  # noqa — jedna kategoria nie kasuje pozostałych
            errs.append(f'{k}: {e}')
    rest = [k for k, _ in T10_CATS if G[k]['rows'] is None and G[k]['pool']]
    ids = sorted({i for k in rest for i in G[k]['pool']})
    if ids:                                                   # 2) ceny i kapitalizacje kandydatów — jedno zapytanie
        try:
            by = {r[0]: r for r in take(_t10_get(CG + '/coins/markets?vs_currency=usd&ids=' + ','.join(ids)
                                                 + '&order=market_cap_desc&per_page=250&page=1&price_change_percentage=24h', hdr, st), 'ceny')}
            for k in rest:
                rows = sorted((by[i] for i in G[k]['pool'] if i in by), key=lambda r: -r[4])
                if rows:
                    G[k].update(rows=rows, pool=[r[0] for r in rows])
                else:
                    errs.append(f'{k}: żaden kandydat bez ceny')
        except Exception as e:  # noqa
            errs.append(f'ceny ({len(ids)} monet): {e}')
    out = {'at': at, 'cols': list(T10_COLS), 'n': T10_N, 'g': {}, 'ok': {}}
    WB = {}   # v439: pełna lista kategorii po wykluczeniach (bez sektora głównego) — baza warstwy Top 100
    bezk = {}   # v437: wykluczenia sektora (stare reguły + stablecoiny); sektor główny liczony z kandydatów bez nich
    for k, _ in T10_CATS:
        bezk[k] = set(T10_BEZ.get(k, ())) | T10_STABILNE
        if k in T10_BEZ_Z:   # v155: moneta z kandydatów grupy memecoinów (ten albo poprzedni skład) to memecoin, nie gra
            bezk[k] |= {i for i in (G[T10_BEZ_Z[k]]['pool'] or []) if isinstance(i, str)} | {r[0] for r in (G[T10_BEZ_Z[k]]['rows'] or [])}   # v439: także memecoiny z głębi listy
    glowny = t10_glowny({k: [i for i in G[k]['pool'] if i not in bezk[k]] for k, _ in T10_CATS})   # v437: każda moneta w jednym sektorze
    for k, cat in T10_CATS:                                   # 3) plik: top 10 wg kapitalizacji
        g = G[k]
        rows = g['rows']
        if rows is None:
            rows = [r for r in g['prev'] if _t10_fresh(r, now)]   # v330 (ZB04-02): wiek z czasu notowania wiersza, nie pliku
            if not any(e.startswith(k + ':') for e in errs):
                errs.append(f'{k}: ' + ('poprzednie ceny' if rows else 'brak danych'))
        bez = bezk[k]
        inne = {i for i, s in glowny.items() if s != k}   # v437: moneta, której sektorem głównym jest inny — tu nie stoi (kandydaci zostają: reguła liczona od nowa w każdym przebiegu)
        WB[k] = sorted((r for r in rows if r[0] not in bez), key=lambda r: -r[4])
        rows = [r for r in WB[k] if r[0] not in inne][:T10_N]
        pool = [i for i in g['pool'] if i not in bez]   # v155: kandydaci też bez wykluczonych (kolejne ceny tylko dla monet grupy)
        out['g'][k] = {'cat': cat, 'sk': g['sk'] if rows else None, 'pool': pool if rows else [], 'c': rows}
        out['ok'][k] = g['rows'] is not None
    # v439: warstwa Top 100 (miejsca 11–100 kategorii) — z tego samego zapytania składu (co T10_SKLAD); między składami poprzednia, najwyżej T100_MAX_AGE; bez monet grupy — bez warstwy.
    # Każda moneta w jednym sektorze (jak v437): bez monet z dziesiątek wszystkich grup i bez monet, których sektor główny (liczony z całych list) jest inny
    cid = {r[0] for k, _ in T10_CATS for r in out['g'][k]['c']}
    gw = t10_glowny({k: [r[0] for r in WB[k]] for k, _ in T10_CATS})
    for k, _ in T10_CATS:
        o, g = out['g'][k], G[k]
        pk = pg.get(k) if isinstance(pg.get(k), dict) else {}
        wl = [r for r in WB[k] if r[0] not in cid and gw.get(r[0], k) == k][:T10_WIDE - T10_N]
        w = (t100_pack(wl, g['sk']) if g['skl'] else t100_prev(pk.get('w'), now)) if o['c'] else None
        if w:
            o['w'] = w
    pusty = not any(out['g'][k]['c'] for k, _ in T10_CATS)
    if pusty and not pg:   # v330 (ZB04-02): bez poprzedniego pliku nie ma czego chronić; z plikiem — zapis pustych grup (main inaczej zostawiłby stare ceny)
        raise RuntimeError('żadna grupa nie ma monet' + (f' ({"; ".join(errs)[:300]})' if errs else ''))
    if errs:
        META['errors'].append(mask('krypto top 10: ' + '; '.join(errs))[:500])
    out['calls'] = st['n']
    if pusty and isinstance(prev_logo, dict) and isinstance(prev_logo.get('logo'), dict):   # v330: awaria źródła — loga zostają (po powrocie bez ponownego pobierania)
        return out, prev_logo
    return out, t10_logos(out, imgs, prev_logo, at, st['end'], late)


ETF_KEEP_DAYS = 300  # v55: tyle dni trzyma etf.json (SoSoValue oddaje tylko ok. 21 ostatnich — reszta z poprzedniego pliku); v89: 300 (TRENDY)


def etf_merge_days(prev_day, new_day):
    """v55: [[ts, mln USD], ...] — nowe okno SoSoValue + starsze dni z poprzedniego pliku, TYLKO gdy okna się nakładają
    (bez cichej luki w sumie 22 sesji); dla tego samego dnia wygrywa nowa wartość; ostatnie ETF_KEEP_DAYS dni."""
    new = [r for r in (new_day or []) if isinstance(r, list) and len(r) == 2 and isinstance(r[0], int)]
    old = [r for r in (prev_day or []) if isinstance(r, list) and len(r) == 2 and isinstance(r[0], int) and not isinstance(r[0], bool)
           and isinstance(r[1], (int, float)) and not isinstance(r[1], bool)]
    if not new or not old or max(r[0] for r in old) < min(r[0] for r in new):
        return new
    m = {r[0]: r[1] for r in old}; m.update({r[0]: r[1] for r in new})
    return [[k, m[k]] for k in sorted(m)][-ETF_KEEP_DAYS:]


# v180 (przegląd jakości 05.10): opłata z prospektu emitenta, gdy źródło notowań podaje 0 — FBTC: 0,25% rocznie od końca zwolnienia z opłaty
# (31.07.2024); źródło wciąż podaje 0, a strona pokazywała „0,00%” przy drugim co do wielkości funduszu BTC w USA. Inna niż 0 wartość od źródła
# wygrywa (zmiana opłaty albo poprawione źródło); u funduszy spoza listy 0 zostaje (prawdziwe zwolnienia z opłaty po debiucie).
ETF_FEE_FIX = {'FBTC': 0.25}
import math as _etf_math   # v180: isfinite (ponowny import jest nieszkodliwy)


def etf_fee(ticker, v):
    """Roczna opłata funduszu w %: sponsor_fee (ułamek) × 100, zaokrąglona do 4 miejsc; nie-liczba = None (brak, nigdy 0);
    0 dla funduszu z ETF_FEE_FIX = opłata z prospektu."""
    if isinstance(v, bool) or not isinstance(v, (int, float)) or not _etf_math.isfinite(v):
        return None
    f = round(v * 100, 4)
    return ETF_FEE_FIX.get(ticker, f) if f == 0 else f


ETF_SUMA_TOL = 0.05   # v199: mln USD — suma przepływów funduszy wobec przepływu dnia (na żywo równe co do grosza; dawniej max(0,5 mln, 2%))
ETF_FUNDS_MAX = 20    # v203: najwyżej tyle funduszy na monetę (było 12 — lista BTC ma już 12); obcięta lista = sumy nie da się sprawdzić
ETF_STALE_SES = 2     # v205: moneta ponad tyle sesji (dni roboczych) za najnowszą = stale (strona: przepływy „—”, data przy nazwie)


def _etf_rowne(x, y):
    """v194: dwie liczby z zestawienia dnia równe (te same dane źródła); brak albo nie-liczba = nie (lista funduszy pobierana znowu)."""
    ok = lambda v: isinstance(v, (int, float)) and not isinstance(v, bool) and _etf_math.isfinite(v)  # noqa: E731
    return ok(x) and ok(y) and abs(x - y) <= 1e-6 * max(1.0, abs(y))


# v279: samouczenie pory publikacji przepływów ETF w USA. Dzień D pojawia się u źródła wieczorem albo w nocy UTC, różnie dla monet i dni
# (07.10: SOL i XRP z 06.10 już o 00:58 UTC, BTC i ETH jeszcze nie o 01:58). Zbieracz zapisuje, kiedy nowy dzień każdej monety pojawił się
# pierwszy raz ('pub'), uczy się z tego okna publikacji ('okno') i w oknie — gdy oczekiwanego dnia brak — pyta w każdym przebiegu (co ~10 min)
# zamiast raz na godzinę. Poza oknem i przy komplecie — jak dotąd (plan 100 000 zapytań na miesiąc).
ETF_PUB_KEEP = 30                     # obserwacji pory publikacji na monetę
ETF_PUB_MIN = 5                       # tyle obserwacji (wszystkie monety) = okno z danych; mniej = okno domyślne
ETF_OKNO_DOM = (21 * 60, 30 * 60)     # min od północy UTC dnia danych: 21:00 tego dnia – 06:00 następnego (okno domyślne)
ETF_OKNO_GRAN = (20 * 60, 40 * 60)    # granice okna z danych: 20:00 – 16:00 następnego dnia (v282: było 14:00)
ETF_SZYBKO_MIN = 4                    # min — w oknie pytanie, gdy plik starszy (v282: było 9 — przebiegi GitHuba bywają co 5–7 min)
ETF_FUNDS_PONOW = 55                  # v282: min — lista funduszy niezgodna z przepływem dnia: ponownie najwyżej tak często (ten sam dzień danych)


def etf_oczekiwany(now):
    """v279: dzień danych, którego przepływów oczekujemy: ostatni dzień roboczy D (pon–pt) taki, że teraz ≥ D 20:00 UTC (po sesji w USA)."""
    d = (now - datetime.timedelta(hours=20)).date()
    while d.weekday() >= 5:
        d -= datetime.timedelta(days=1)
    return d


def _etf_obs(rows):
    """v279/v282: obserwacje jednej monety ([dzień, czas pierwszego zobaczenia]) → minuty od północy UTC dnia danych; złe i poza 0–3 doby — pominięte."""
    out = []
    for r in (rows if isinstance(rows, list) else []):
        try:
            d, t = datetime.date.fromisoformat(r[0]), _ix_dt(r[1])
            m = (t - datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)).total_seconds() / 60
        except (TypeError, ValueError, IndexError):
            continue
        if 0 <= m <= 3 * 24 * 60:
            out.append(m)
    return out


def etf_okno(pub, coin=None):
    """v279: okno publikacji z obserwacji 'pub' (minuty od północy UTC dnia danych do pierwszego zobaczenia) → (od, do, n): 10. centyl − 60
    i 90. centyl + 30 min, w granicach ETF_OKNO_GRAN; mniej niż ETF_PUB_MIN obserwacji — ETF_OKNO_DOM. Obserwacja poza 0–3 doby — pominięta.
    v282 (przegląd v279): coin — okno tej monety z jej obserwacji (≥ ETF_PUB_MIN), inaczej ze wszystkich monet razem, inaczej domyślne;
    okno puste (od > do — publikacje późniejsze niż granica) = bez trybu szybkiego (co godzinę jak dotąd)."""
    pub = pub if isinstance(pub, dict) else {}
    obs = _etf_obs(pub.get(coin)) if coin is not None else []
    if len(obs) < ETF_PUB_MIN:
        obs = [m for rows in pub.values() for m in _etf_obs(rows)]
    if len(obs) < ETF_PUB_MIN:
        return ETF_OKNO_DOM[0], ETF_OKNO_DOM[1], len(obs)
    obs.sort()
    q = lambda p: obs[min(len(obs) - 1, int(p * (len(obs) - 1) + 0.5))]  # noqa: E731
    od = max(ETF_OKNO_GRAN[0], q(0.1) - 60)
    do = min(ETF_OKNO_GRAN[1], max(od + 60, q(0.9) + 30))
    if do - od < 30:   # okno przycięte granicą do mniej niż 30 min — publikacje po granicy: puste (od > do)
        return int(od), int(od) - 1, len(obs)
    return int(od), int(do), len(obs)


def etf_brakujace(prev, now):
    """v282: monety do trybu szybkiego — bez oczekiwanego dnia (etf_oczekiwany; poza 'stale', z poprawną datą), gdy teraz jest w oknie
    publikacji TEJ monety (etf_okno(pub, moneta)). → zbiór (pusty = bez trybu szybkiego)."""
    if not isinstance(prev, dict) or not isinstance(prev.get('assets'), dict):
        return set()
    E = etf_oczekiwany(now)
    m = (now - datetime.datetime(E.year, E.month, E.day, tzinfo=datetime.timezone.utc)).total_seconds() / 60
    out = set()
    for s, a in prev['assets'].items():
        if isinstance(a, dict) and not a.get('stale') and isinstance(a.get('asof'), str) and re.match(r'^\d{4}-\d{2}-\d{2}$', a['asof']) \
                and a['asof'] < E.isoformat():   # moneta bez poprawnej daty — bez trybu szybkiego
            od, do, _ = etf_okno(prev.get('pub'), s)
            if od <= m <= do:
                out.add(s)
    return out


def etf_szybko(prev, now):
    """v279: czy pytać o przepływy mimo pliku młodszego niż godzina — v282: któraś moneta bez oczekiwanego dnia w swoim oknie (etf_brakujace). → bool."""
    return bool(etf_brakujace(prev, now))


def etf_pub(prev_pub, prev_assets, assets, stare, now_iso):
    """v279: obserwacje pory publikacji — moneta pobrana teraz (nie przeniesiona z poprzedniego pliku), której dzień danych jest nowszy niż
    w poprzednim pliku: [dzień, czas pierwszego zobaczenia]; najwyżej ETF_PUB_KEEP ostatnich na monetę. Bez poprzedniego wpisu monety — bez
    obserwacji (nie wiadomo, kiedy dzień się pojawił)."""
    out = {s: [list(r) for r in rows if isinstance(r, list) and len(r) == 2] for s, rows in prev_pub.items() if isinstance(rows, list)} \
        if isinstance(prev_pub, dict) else {}
    for s, a in assets.items():
        pa = prev_assets.get(s) if isinstance(prev_assets, dict) else None
        if s in stare or not isinstance(pa, dict) or not isinstance(a.get('asof'), str) or not isinstance(pa.get('asof'), str):
            continue
        if a['asof'] > pa['asof']:
            out[s] = (out.get(s, []) + [[a['asof'], now_iso]])[-ETF_PUB_KEEP:]
    return out


def build_etf(key, cg_key, prev=None, tylko=None):
    """v282: tylko — zbiór monet do pobrania (tryb szybki: monety bez oczekiwanego dnia); pozostałe z poprzedniego pliku bez zapytań
    (z historią dni i stanem); None = wszystkie (pełna budowa, 'pelne_at' = teraz)."""
    out = {'at': NOW, 'asof': '', 'src': 'SoSoValue', 'live': True, 'mcap': {}, 'assets': {}}
    prev_assets = prev.get('assets') if isinstance(prev, dict) and isinstance(prev.get('assets'), dict) else {}
    # kapitalizacje (CoinGecko) — do udziału ETF w rynku
    pm = prev.get('mcap') if isinstance(prev, dict) and isinstance(prev.get('mcap'), dict) else {}
    pma_s = (prev.get('mcap_at') or prev.get('at')) if isinstance(prev, dict) else None
    pma = _ix_dt(pma_s)
    if (pm and all(isinstance(pm.get(s), (int, float)) and not isinstance(pm.get(s), bool) and pm[s] > 0 for s in ETF_SYMS)
            and pma is not None and 0 <= (_now_utc() - pma).total_seconds() < 55 * 60):
        # v280: tryb szybki (v279) — kapitalizacje sprzed < 55 min z poprzedniego pliku, bez zapytania planu CoinGecko (10 000 / mies.)
        out['mcap'], out['mcap_at'] = dict(pm), pma_s
        META['ok']['coingecko'] = 'cached'
        if isinstance(prev.get('tok'), dict) and prev['tok']:
            out['tok'] = prev['tok']   # v295c: ceny tokenów złota z tego samego (poprzedniego) zapytania — każda z własną chwilą notowania
    else:
        try:
            # v295c: + pax-gold i tether-gold (tokeny złota — panel CRYPTO „Złoto i surowce a krypto”) i chwila notowania — to samo jedno zapytanie
            u = ('https://api.coingecko.com/api/v3/simple/price?ids=' + ','.join(list(CG_IDS.values()) + list(ZK_CG_IDS.values()))
                 + '&vs_currencies=usd&include_market_cap=true&include_last_updated_at=true')
            j = get_json(u, {'x-cg-demo-api-key': cg_key} if cg_key else None)   # klucz w nagłówku, nie w adresie
            tk = zk_cg_tok(j)   # v295c: ceny tokenów złota z chwilą notowania (bez wyjątku; token bez ceny albo chwili — bez wpisu)
            if tk:
                out['tok'] = tk
            out['mcap'] = {s: j[CG_IDS[s]]['usd_market_cap'] for s in ETF_SYMS}
            out['mcap_at'] = NOW
            META['ok']['coingecko'] = True
        except Exception as e:
            META['errors'].append(mask(f'CoinGecko: {e}'))
            META['ok']['coingecko'] = False
    nowe, stare, pominiete = 0, {}, set()
    for s in ETF_SYMS:
        pa = prev_assets.get(s) if isinstance(prev_assets.get(s), dict) else {}
        if tylko is not None and s not in tylko and isinstance(pa.get('day'), list) and pa['day'] and isinstance(pa.get('asof'), str) and _d(pa['asof']):
            out['assets'][s] = json.loads(json.dumps(pa)); pominiete.add(s)   # v282: tryb szybki — moneta z oczekiwanym dniem bez zapytań
            out['asof'] = max(out['asof'], pa['asof'])
            continue
        try:
            _etf_coin(out, s, key, pa.get('day'), prev_a=pa); nowe += 1
        except Exception as e:   # v49: brak jednej monety nie kasuje pozostałych
            META['errors'].append(mask(f'SoSoValue {s.upper()}: {e}'))
            # v194 (przegląd v190–v192): poprzedni wpis monety z własną datą zamiast braku wiersza — i bez utraty historii dni starszej niż okno
            # źródła (ok. 21 sesji; następny przebieg łączy nowe okno z tą historią)
            if isinstance(pa.get('day'), list) and pa['day'] and isinstance(pa.get('asof'), str) and _d(pa['asof']):
                stare[s] = pa
    if not nowe and (tylko is None or not pominiete):   # wszystkie monety zawiodły — main zostawia poprzedni plik z jego czasem
        raise RuntimeError('SoSoValue: brak danych dla wszystkich monet')   # v283: w trybie szybkim z przeniesionymi monetami — bez wyjątku (błąd monety w meta)
    top = max(a['asof'] for a in out['assets'].values())
    for s, pa in stare.items():   # v199/v203: poprzedni wpis z własną datą i historią dni (stan „stale” — niżej, jak dla każdej monety)
        out['assets'][s] = json.loads(json.dumps(pa))
        META['notes'].append(f'SoSoValue {s.upper()}: poprzednie dane z {pa["asof"]}')
    # v205 (przegląd v202–v204): każda moneta (pobrana albo przeniesiona) ponad ETF_STALE_SES sesji za najnowszą = stale — liczby zostają (prawdziwe
    # dla swojej daty; przy wznowieniu lista funduszy nie jest pobierana co przebieg), strona pokazuje przepływy „—” i datę przy nazwie
    for s, a in out['assets'].items():
        ad = _d(a['asof']) if isinstance(a.get('asof'), str) else None
        if ad and a['asof'] < top and _bdays(ad, _d(top)) > ETF_STALE_SES:
            a['stale'] = True
            META['notes'].append(f'SoSoValue {s.upper()}: dane z {a["asof"]} — ponad {ETF_STALE_SES} sesje za najnowszymi ({top}); na stronie przepływy „—”')
        else:
            a.pop('stale', None)
    out['assets'] = {s: out['assets'][s] for s in ETF_SYMS if s in out['assets']}
    ph = prev.get('hk') if isinstance(prev, dict) and isinstance(prev.get('hk'), dict) and prev['hk'] else None
    ph = ({s: a for s, a in ph.items() if _etf_hk_ok(a)} or None) if ph else None   # v293c (CR-08/G9): stary zapis HK (monety ÷ 1e6) — bez przeniesienia, pobranie od nowa
    hat = _ix_dt(prev.get('hk_at')) if isinstance(prev, dict) else None
    if ph and hat is not None and 0 <= (_now_utc() - hat).total_seconds() < ETF_FUNDS_EVERY * 60:   # v192: Hongkong najwyżej co 6 h
        out['hk'], out['hk_at'] = ph, prev['hk_at']
    else:
        nowe_hk = _etf_hk(out, key, ph)   # v61: Hongkong (próba, nie psuje części USA)
        if out.get('hk') and set(nowe_hk or ()) >= {'btc', 'eth'}:   # v194: czas tylko dla kompletu z tego przebiegu
            out['hk_at'] = NOW
    # fundusze publikują dane w różnych godzinach — jeśli daty różnią się między monetami, pokazujemy zakres, nie najnowszą
    out['pub'] = etf_pub(prev.get('pub') if isinstance(prev, dict) else None, prev_assets, out['assets'], set(stare) | pominiete, NOW)   # v279: pora publikacji
    out['okno'] = {s: dict(zip(('od', 'do', 'n'), etf_okno(out['pub'], s))) for s in ETF_SYMS}   # v282: okno publikacji każdej monety (min od północy UTC dnia danych)
    out['pelne_at'] = NOW if tylko is None else ((prev.get('pelne_at') or prev.get('at')) if isinstance(prev, dict) else NOW)   # v282: ostatnia pełna budowa
    dates = sorted({a['asof'] for a in out['assets'].values()})
    out['asof'] = dates[0] if len(dates) == 1 else f'{dates[0]} – {dates[-1]}'
    return out


ETF_HK_V = 2   # v293c (CR-08/G9): wersja zapisu części HK — przepływy w MONETACH (pola *_ntv, 'unit') i szacunek w mln USD; wpisy bez tej wersji
#                (v61–v292: liczby monet dzielone przez 1e6 jak dolary — 3534 BTC zapisane jako „0,0035 mln USD”) nie są przenoszone ani łączone
ETF_HK_PX_DNI = 3   # dzień bez zamknięcia w pliku cen krypto — ostatnie wcześniejsze zamknięcie najwyżej tyle dni wstecz; dalej USD = brak (None), nie zero


def _etf_hk_ok(a):
    """v293c: wpis monety HK w bieżącym zapisie (ETF_HK_V) — tylko taki wolno przenieść z poprzedniego pliku albo łączyć z nowymi dniami."""
    return isinstance(a, dict) and a.get('v') == ETF_HK_V


def _etf_hk_px(sym):
    """v293c: dzienne zamknięcia {dzień: cena w USDT} monety z pliku ceny-krypto (zapisany w tym przebiegu albo z pamięci Actions — bez sieci);
    brak pliku, monety albo liczb = {} (USD przepływów = brak)."""
    try:
        kc = SAVED.get('ceny-krypto') if isinstance(SAVED.get('ceny-krypto'), dict) else _prev_cache('ceny-krypto')
        q = kc.get('q') if isinstance(kc, dict) and isinstance(kc.get('q'), dict) else {}
        rows = q.get(sym).get('d') if isinstance(q.get(sym), dict) else None
        return {r[0]: float(r[1]) for r in (rows if isinstance(rows, list) else []) if isinstance(r, list) and len(r) >= 2 and isinstance(r[0], str)
                and isinstance(r[1], (int, float)) and not isinstance(r[1], bool) and r[1] > 0}
    except Exception:  # noqa — plik cen jest pomocniczy; awaria = USD brak, nie błąd części
        return {}


def _etf_hk_usd(day_ntv, px):
    """v293c: [[ts, monety]] → [[ts, mln USD albo None]]: monety × zamknięcie dnia danych (dzień bez zamknięcia — ostatnie wcześniejsze, najwyżej
    ETF_HK_PX_DNI dni; dalej None — brak, nie zero)."""
    out = []
    for t, v in day_ntv:
        d = datetime.datetime.fromtimestamp(t, datetime.timezone.utc).date()
        p = next((px[k] for k in ((d - datetime.timedelta(days=i)).isoformat() for i in range(ETF_HK_PX_DNI + 1)) if k in px), None)
        out.append([t, round(v * p / 1e6, 6) if p is not None and isinstance(v, (int, float)) and not isinstance(v, bool) else None])
    return out


def _etf_hk(out, key, prev_assets_hk):
    """v61: ETF-y spot w Hongkongu (SoSoValue country_code=HK), BTC i ETH — dane dzienne (bez listy funduszy).
    Brak/awaria = notatka w meta (nie błąd strony); pole 'fields' mówi, co zwraca API (nazwy pól, bez wartości).
    v293c (CR-08/G9): źródło podaje przepływy HK (total_net_inflow, cum_net_inflow) w MONETACH, nie w USD (7.10: cum 3533,66 = BTC; × cena ≈ aktywa
    297,5 mln USD) — dawniej dzielone przez 1e6 jak dolary („0,0035 mln USD”). Teraz: monety w polach *_ntv z jednostką 'unit', szacunek w mln USD
    (day, d1, w, m) z dziennego zamknięcia (_etf_hk_usd; brak ceny = None), 'aum' — aktywa w mln USD (to pole źródło podaje w USD); 'v' = ETF_HK_V."""
    hk = {}
    isnum = lambda v: isinstance(v, (int, float)) and not isinstance(v, bool)  # noqa: E731
    for s in ('btc', 'eth'):
        if _DEADLINE[0] is not None and time.monotonic() > _DEADLINE[0]:
            META['notes'].append('SoSoValue HK: pominięte — limit czasu przebiegu'); break
        try:
            rows = soso(f'/etfs/summary-history?symbol={s.upper()}&country_code=HK&limit=60', key)
            rows = sorted([r for r in (rows or []) if isinstance(r, dict) and r.get('date') and isnum(r.get('total_net_inflow'))], key=lambda r: r['date'])
            if not rows:
                META['notes'].append(f'SoSoValue HK {s.upper()}: brak danych'); continue
            last = rows[-1]
            pd = (prev_assets_hk or {}).get(s) if isinstance(prev_assets_hk, dict) else None
            pd = pd if _etf_hk_ok(pd) else None   # v293c: stary zapis (monety ÷ 1e6) — bez łączenia z nowymi dniami
            day_ntv = etf_merge_days(pd.get('day_ntv') if pd else None, [[ts(r['date']), float(r['total_net_inflow'])] for r in rows])
            day = _etf_hk_usd(day_ntv, _etf_hk_px(s.upper()))
            ntv, usd = [v for _, v in day_ntv], [v for _, v in day]
            sm = lambda xs, n: sum(xs[-n:]) if len(xs) >= n and all(isnum(x) for x in xs[-n:]) else None  # noqa: E731
            num = lambda k: float(last[k]) if isnum(last.get(k)) else None  # noqa: E731
            aum = num('total_net_assets')
            hk[s] = {'sym': s.upper(), 'v': ETF_HK_V, 'unit': s.upper(), 'asof': last['date'],
                     'day_ntv': day_ntv, 'd1_ntv': ntv[-1], 'w_ntv': sm(ntv, 5), 'm_ntv': sm(ntv, 22), 'cum_ntv': num('cum_net_inflow'),
                     'day': day, 'd1': usd[-1], 'w': sm(usd, 5), 'm': sm(usd, 22), 'm_n': min(len(day), 22),
                     'usd': 'szacunek: monety × dzienne zamknięcie (USDT)', 'aum': aum / 1e6 if aum is not None else None,
                     'fields': sorted(str(k) for k in last)[:20]}
            META['notes'].append(f'SoSoValue HK {s.upper()}: {len(rows)} dni do {last["date"]}; pola: {", ".join(hk[s]["fields"])}')
        except Exception as e:
            META['notes'].append(mask(f'SoSoValue HK {s.upper()}: {e}'))
    nowe = sorted(hk)
    if isinstance(prev_assets_hk, dict):   # v194: moneta bez odpowiedzi — poprzedni wpis (z własną datą i historią dni), nie brak; v293c: tylko w bieżącym zapisie
        for s in ('btc', 'eth'):
            if s not in hk and _etf_hk_ok(prev_assets_hk.get(s)):
                hk[s] = prev_assets_hk[s]
    if hk:
        out['hk'] = hk
    return nowe

def _etf_coin(out, s, key, prev_day=None, prev_a=None):
        """v49: dane jednej monety (wydzielone z build_etf, żeby błąd jednej nie kasował pozostałych)."""
        rows = soso(f'/etfs/summary-history?symbol={s.upper()}&country_code=US&limit=60', key)
        rows = [r for r in rows if r.get('date') and r.get('total_net_inflow') is not None]
        rows.sort(key=lambda r: r['date'])
        if not rows:
            raise RuntimeError(f'SoSoValue: brak danych dla {s}')
        day = etf_merge_days(prev_day, [[ts(r['date']), r['total_net_inflow'] / 1e6] for r in rows])   # v55: historia dłuższa niż okno API
        last = rows[-1]
        out['asof'] = max(out['asof'], last['date'])
        aum = last['total_net_assets'] / 1e6 if last.get('total_net_assets') else None
        mc = out['mcap'].get(s)
        a = {'sym': s.upper(), 'asof': last['date'], 'day': day, 'd1': day[-1][1],
             'w': sum(v for _, v in day[-5:]), 'm': sum(v for _, v in day[-22:]) if len(day) >= 22 else None, 'm_n': min(len(day), 22),   # v51: 22 sesje albo brak (nie cicha niepełna suma)
            
             'cum': last['cum_net_inflow'] / 1e6, 'aum': aum,
             'share': (aum * 1e6 / mc * 100) if (aum and mc) else None, 'funds': []}
        # v192: lista i szczegóły funduszy (1 + N zapytań po ok. 7 s) tylko przy nowym dniu danych albo gdy lista starsza niż 6 h; niepełna lista
        # (limit czasu, błąd funduszu) bez funds_at — następny przebieg pobiera ją znowu
        pf = prev_a.get('funds') if isinstance(prev_a, dict) and isinstance(prev_a.get('funds'), list) else None
        fat = _ix_dt(prev_a.get('funds_at')) if isinstance(prev_a, dict) else None
        # v194 (przegląd v190–v192): ponownie tylko przy TYM SAMYM zestawieniu dnia (data, przepływ dnia, suma od startu) — poprawka źródła
        # w liczbach dnia = lista znowu (dotąd do 6 h ze starymi liczbami funduszy)
        same = (isinstance(prev_a, dict) and prev_a.get('asof') == last['date'] and _etf_rowne(prev_a.get('d1'), a['d1'])
                and _etf_rowne(prev_a.get('cum'), a['cum']))
        stara = not (pf and same and fat is not None and 0 <= (_now_utc() - fat).total_seconds() < ETF_FUNDS_EVERY * 60)
        # v282 (przegląd v279): lista bez funds_at (niezgodna z przepływem dnia albo niepełna) — przy tym samym zestawieniu dnia ponownie najwyżej
        # co ETF_FUNDS_PONOW min (tryb szybki co ~10 min pobierał ją w każdej budowie: 1 + N zapytań); nowy dzień danych — od razu
        ftry = _ix_dt(prev_a.get('funds_try')) if isinstance(prev_a, dict) else None
        wstrzymana = bool(stara and pf and same and fat is None and ftry is not None and 0 <= (_now_utc() - ftry).total_seconds() < ETF_FUNDS_PONOW * 60)
        if wstrzymana:
            stara = False
        pelna = True
        lst = []
        if stara:
            try:
                lst = soso(f'/etfs?symbol={s.upper()}&country_code=US', key)
            except Exception as e:   # v194: błąd listy nie kasuje monety — lista z poprzedniego pliku tylko z tego samego dnia danych
                META['errors'].append(mask(f'SoSoValue {s.upper()}: lista funduszy — {e}')); pelna = False
                if pf and isinstance(prev_a, dict) and prev_a.get('asof') == last['date']:
                    a['funds'] = [dict(f) for f in pf if isinstance(f, dict)]
        elif wstrzymana:   # v282: niezgodna lista z poprzedniego pliku, bez czasu listy — ponowienie po ETF_FUNDS_PONOW min
            a['funds'] = [dict(f) for f in pf if isinstance(f, dict)]; a['funds_try'] = prev_a['funds_try']
        else:
            a['funds'] = [dict(f) for f in pf if isinstance(f, dict)]; a['funds_at'] = prev_a['funds_at']
        obc = len(lst or []) > ETF_FUNDS_MAX   # v203
        for it in (lst or [])[:ETF_FUNDS_MAX]:
            if _DEADLINE[0] is not None and time.monotonic() > _DEADLINE[0]:   # v49: limit czasu przebiegu
                META['errors'].append(f'SoSoValue {s.upper()}: lista funduszy pominięta — limit czasu przebiegu'); pelna = False; break
            if not TICKER.match(str(it.get('ticker', ''))):
                # ticker spoza wzorca nie trafia na stronę — i nie znika po cichu
                META['errors'].append(f'SoSoValue {s.upper()}: odrzucony ticker {str(it.get("ticker"))[:20]!r}')
                continue
            try:
                d = soso(f'/etfs/{it["ticker"]}/market-snapshot', key)
                a['funds'].append({'t': it['ticker'], 'n': it.get('name'), 'cty': 'us',
                                   'aum': d['net_assets'] / 1e6 if d.get('net_assets') is not None else None,
                                   'cum': d['cum_inflow'] / 1e6 if d.get('cum_inflow') is not None else None,
                                   'd1': d['net_inflow'] / 1e6 if d.get('net_inflow') is not None else None,
                                   'fee': etf_fee(it['ticker'], d.get('sponsor_fee')),   # v180: 0 od źródła przy znanej opłacie z prospektu
                                   'prem': d.get('prem_dsc')})
            except Exception as e:
                META['errors'].append(mask(f'SoSoValue {it.get("ticker")}: {e}')); pelna = False
        if stara and pelna:
            # v194: czas listy tylko, gdy suma przepływów funduszy zgadza się z przepływem dnia z zestawienia (tolerancja jak w kontroli: 0,5 mln
            # albo 2%) — przy zmianie dnia szczegóły funduszy bywają jeszcze z dnia poprzedniego; inaczej następny przebieg pobiera listę znowu
            d1f = [f.get('d1') for f in a['funds']]
            nl = [x for x in d1f if isinstance(x, (int, float)) and not isinstance(x, bool)]
            if obc:
                META['notes'].append(f'SoSoValue {s.upper()}: lista funduszy obcięta do {ETF_FUNDS_MAX} z {len(lst)} — suma nie sprawdzana')
            if a['funds'] and len(nl) == len(d1f) and (obc or abs(sum(nl) - a['d1']) <= ETF_SUMA_TOL):
                a['funds_at'] = NOW   # v192: pełna lista z tego przebiegu
            else:
                META['notes'].append(f'SoSoValue {s.upper()}: lista funduszy niezgodna z przepływem dnia ({a["d1"]:+.1f} mln; suma {sum(nl):+.1f} mln z '
                                     f'{len(nl)} z {len(d1f)} funduszy) — znowu za {ETF_FUNDS_PONOW} min albo przy nowym dniu danych')
        if stara and 'funds_at' not in a:   # v282: pobrana, ale niezgodna albo niepełna — czas próby (ponowienie najwyżej co ETF_FUNDS_PONOW min)
            a['funds_try'] = NOW
        a['funds'].sort(key=lambda f: -(f['aum'] or 0))
        if not a['aum'] and a['funds']:
            # suma aktywów tylko wtedy, gdy KAŻDY fundusz ma aktywa — brak nie jest zerem
            a['aum'] = (sum(f['aum'] for f in a['funds']) or None) if all(f['aum'] is not None for f in a['funds']) else None
            if a['aum'] and mc:
                a['share'] = a['aum'] * 1e6 / mc * 100
        out['assets'][s] = a
        print(f'{s.upper()}: dzień {last["date"]} {a["d1"]:+.1f} mln, AUM {a["aum"]}, funduszy {len(a["funds"])}')


