def _fund_ssga_bytes(t, pobierz):
    """v342 (F1Z2): plik State Street funduszu t — nowa ścieżka (FUND_SSGA_URL); 404 albo 410 (plik pod inną ścieżką) = jedna próba dawnej
    (FUND_SSGA_URL_STARA). pobierz(adres) → bajty (zbieracz: get_bytes / get_bytes_maks; plik dzienny świata: _wd_req)."""
    try:
        return pobierz(FUND_SSGA_URL.format(t=t.lower()))
    except urllib.error.HTTPError as e:
        if e.code not in (404, 410):
            raise
    return pobierz(FUND_SSGA_URL_STARA.format(t=t.lower()))


def _fund_x_get(url, timeout, maks):
    """v342: zapytanie kroku rozszerzenia — z limitem rozmiaru odpowiedzi (get_bytes_maks: czytanie przerwane po maks + 1 B)."""
    return get_bytes_maks(url, timeout=timeout, maks=maks)


def _fund_x_dt(s):
    try:
        t = datetime.datetime.fromisoformat(str(s))
    except (TypeError, ValueError):
        return None
    return t if t.tzinfo else t.replace(tzinfo=datetime.timezone.utc)


def _fund_sesja_przed(day):
    """v342: ostatnia sesja NYSE przed dniem `day` (data) — dni robocze bez TD_NYSE_CLOSED (po 2027 — same dni robocze)."""
    d = day - datetime.timedelta(days=1)
    while d.weekday() >= 5 or d.isoformat() in TD_NYSE_CLOSED:
        d -= datetime.timedelta(days=1)
    return d.isoformat()


def _fund_x_pub(now):
    """v342: ostatnia chwila publikacji plików State Street ≤ now (dni robocze, FUND_X_PUB_H:00 UTC)."""
    c = now.replace(hour=FUND_X_PUB_H, minute=0, second=0, microsecond=0)
    if c > now:
        c -= datetime.timedelta(days=1)
    while c.weekday() >= 5:
        c -= datetime.timedelta(days=1)
    return c


def _fund_x_ssga_pora(p, now):
    """v342: czy pobrać plik State Street funduszu rozszerzenia (bramka publikacji — plik najwyżej raz po każdej publikacji, nie co 6 h).
    Okno ponowień: dni robocze FUND_X_PUB_H:00–FUND_X_PONOW_DO:00 UTC (w weekend i nocą bez zapytań — nowego pliku i tak nie ma).
    Bez danych (pierwszy raz) — tak. Po błędzie: najwcześniej po FUND_RETRY min; blokada (HTTP 403, 429 — err_kod) = koniec tej drogi do następnej
    publikacji (jedna próba po niej); inny błąd — ponowienie tylko w oknie ponowień. Plik pobrany przed ostatnią publikacją — tak; pobrany po niej,
    a bez oczekiwanej sesji (ostatnia sesja NYSE przed dniem tej publikacji — w weekend: czwartek, bo piątek przychodzi w poniedziałek; publikacja
    spóźniona) — ponowienie co FUND_X_PONOW min, tylko w oknie ponowień (recenzja v342: także po 18:00 UTC i w weekend bez zapytań)."""
    pub = _fund_x_pub(now)
    okno = now.weekday() < 5 and FUND_X_PUB_H <= now.hour < FUND_X_PONOW_DO
    e = _fund_x_dt(p.get('err_at')) if p.get('err_at') else None
    if e is not None:
        if (now - e).total_seconds() < FUND_RETRY * 60:
            return False
        if p.get('err_kod') in (403, 429):
            return e < pub
        return okno or e < pub
    h, at = p.get('h') or [], _fund_x_dt(p.get('at'))
    if at is None or at < pub:
        return True
    last = h[-1][0] if h and isinstance(h[-1], list) and h[-1] and isinstance(h[-1][0], str) else ''
    return okno and last < _fund_sesja_przed(pub.date()) and (now - at).total_seconds() >= FUND_X_PONOW * 60


def _fund_num(x):
    try:
        v = float(str(x).replace(',', '').strip())
    except ValueError:
        return None
    return v if _isnum(v) and v > 0 else None


def parse_ssga_navhist(data, ticker):
    """State Street navhist-us-en-{ticker}.xlsx → [[data, NAV, liczba jednostek]] rosnąco. Symbol w pliku musi się zgadzać."""
    rows = _xlsx_rows(data, 'navhist')
    tick, head, out = None, None, []
    for k in sorted(rows):
        r = rows[k]
        c1 = str(r.get(1, '')).strip()
        if c1.lower().startswith('ticker'):
            tick = re.sub(r'[^A-Z]', '', str(r.get(2, '')).upper())
        elif c1 == 'Date' and 'share' in str(r.get(3, '')).lower():
            head = k
        elif head is not None:
            try:
                d = datetime.datetime.strptime(c1, '%d-%b-%Y').date().isoformat()
            except ValueError:
                break                      # koniec tabeli (dalej są zastrzeżenia prawne)
            nav, sh = _fund_num(r.get(2)), _fund_num(r.get(3))
            if nav and sh:
                out.append([d, round(nav, 6), round(sh)])
    if tick != ticker:
        raise RuntimeError(f'{ticker}: w pliku inny symbol ({tick})')
    if head is None or len(out) < 20:
        raise RuntimeError(f'{ticker}: brak tabeli NAV')
    return sorted({r[0]: r for r in out}.values())


def parse_ishares_hist(data):
    """iShares (BlackRock) — plik funduszu (Excel 2003 XML), arkusz „Historical”: As Of, NAV per Share, Shares Outstanding →
    [[data, NAV, liczba jednostek]] rosnąco."""
    import xml.etree.ElementTree as ET
    ns = '{urn:schemas-microsoft-com:office:spreadsheet}'
    txt = data.decode('utf-8-sig', 'replace')
    txt = re.sub(r'&(?!(amp|lt|gt|quot|apos|#\d+|#x[0-9a-fA-F]+);)', '&amp;', txt)   # gołe „&” w nazwach spółek
    root = ET.fromstring(txt)
    ws = next((w for w in root.iter(ns + 'Worksheet') if w.get(ns + 'Name') == 'Historical'), None)
    if ws is None:
        raise RuntimeError('brak arkusza Historical')
    head, out = None, []
    for row in ws.iter(ns + 'Row'):
        cells = [(c.find(ns + 'Data').text if c.find(ns + 'Data') is not None else '') or '' for c in row.iter(ns + 'Cell')]
        if head is None:
            if 'As Of' in cells and 'Shares Outstanding' in cells:
                head = {n: i for i, n in enumerate(cells)}
            continue
        try:
            d = datetime.datetime.strptime(cells[head['As Of']].strip(), '%b %d, %Y').date().isoformat()
        except (ValueError, IndexError, KeyError):
            continue
        nav = _fund_num(cells[head['NAV per Share']]) if 'NAV per Share' in head and len(cells) > head['NAV per Share'] else None
        sh = _fund_num(cells[head['Shares Outstanding']]) if len(cells) > head['Shares Outstanding'] else None
        if nav and sh:
            out.append([d, round(nav, 6), round(sh)])
    if len(out) < 20:
        raise RuntimeError('za krótka historia')
    return sorted({r[0]: r for r in out}.values())


def parse_ishares_screener(j, syms=None):
    """Zestawienie iShares → {symbol: (id funduszu, data, NAV, liczba jednostek = aktywa funduszu / NAV)}; tylko gdy obie daty są te same.
    v309: syms — symbole do wyjęcia (domyślnie FUND_ISH; zbieracz: FUND_ISH + FUND_ISH_SU z jednej odpowiedzi, bez nowego zapytania)."""
    out = {}
    for pid, f in (j.items() if isinstance(j, dict) else []):
        if not isinstance(f, dict):
            continue
        t = str(f.get('localExchangeTicker') or '').upper()
        if t not in (FUND_ISH if syms is None else syms):
            continue
        g = lambda k: (f.get(k) or {}).get('r') if isinstance(f.get(k), dict) else None
        nav, tna, d1, d2 = g('navAmount'), g('totalNetAssetsFund'), g('navAmountAsOf'), g('totalNetAssetsFundAsOf')
        if _isnum(nav) and nav > 0 and _isnum(tna) and tna > 0 and d1 and d1 == d2 and re.match(r'^\d{8}$', str(d1)):
            s = str(d1)
            sh = tna / nav; r3 = round(sh, -3)                  # v94: aktywa / NAV różni się od prawdziwej liczby o kilka jednostek (NAV do 6 miejsc)
            out[t] = (str(f.get('portfolioId') or pid), f'{s[:4]}-{s[4:6]}-{s[6:]}', round(nav, 6), int(r3) if abs(sh - r3) <= 10 else round(sh))
    return out


