def _isnum(x):
    return isinstance(x, (int, float)) and not isinstance(x, bool) and x == x and abs(x) != float('inf')


def _d(s):
    try:
        return datetime.date.fromisoformat(str(s)[:10])
    except ValueError:
        return None


def _tr_sums(vals, size, k, dates=None, span=None, wt=None, blk=None):
    """Sumy k kolejnych pełnych bloków po `size` wartości, od końca: [ostatni, poprzedni, …]. Blok z brakiem (None) albo — gdy podano
    daty i `span` — rozciągnięty na więcej niż `span` dni kalendarzowych (brakujący dzień w pliku) kończy listę.
    v293: wt — liczba sesji w każdej wartości (fund_group info['ns']: przepływ dnia ze złym wierszem pliku dodany do następnego dnia = 2 sesje).
    Blok zbiera wtedy wartości od końca do `size` SESJI, nie wartości — „5 sesji” to naprawdę 5 sesji (EWZ 06.10.2026: dotąd 5 wartości = 6 sesji);
    wartość z kilku sesji na granicy bloku — blok o jedną sesję dłuższy (dłuższy niż size + 1 = koniec listy). Bez wt — jak dotąd.
    blk (lista, opcjonalnie) ← (liczba sesji, indeks pierwszej wartości) kolejnych bloków."""
    out, b = [], len(vals)
    for i in range(k):
        if wt is None:
            a, n = len(vals) - (i + 1) * size, size
            b = a + size
        else:
            a, n = b, 0
            while a > 0 and n < size:
                a -= 1
                n += wt[a] if _isnum(wt[a]) and wt[a] >= 1 else 1
            if not size <= n <= size + 1:
                break
        bl = vals[a:b] if a >= 0 else []
        if not bl or (wt is None and len(bl) < size) or not all(_isnum(x) for x in bl):
            break
        if dates is not None and span:
            d0, d1 = _d(dates[a]), _d(dates[b - 1])
            if not d0 or not d1 or (d1 - d0).days > span:
                break
        out.append(sum(bl))
        if blk is not None:
            blk.append((n, a))
        b = a
    return out


def _mean(xs):
    return sum(xs) / len(xs)


def _sd(xs):
    m = _mean(xs)
    return (sum((x - m) ** 2 for x in xs) / (len(xs) - 1)) ** 0.5 if len(xs) > 1 else 0.0


def _tr_clear(w, typ, days):
    """Wyraźny kierunek tygodnia: |suma| ≥ 0,5 typowego tygodnia i (gdy suma < 1 typowego tygodnia) większość dni ze zmianą ma znak sumy
    (v94: dni bez zmiany się nie liczą — fundusz, który tworzy jednostki raz w tygodniu, nie ma „dni w różne strony”)."""
    if not w or not typ or abs(w) < TR_DIR * typ:
        return False
    nz = [x for x in days or [] if x != 0]
    return days is None or abs(w) >= TR_ALL * typ or sum(1 for x in nz if x * w > 0) >= len(nz) // 2 + 1


def trend_state(vals, size, dates=None, span=None, wt=None):
    """v293: _trend_state z liczbą sesji wartości (wt, jak w _tr_sums). Bez wt — wynik bajt w bajt jak dotąd.
    v296: ostatni blok z innej liczby sesji niż size (wartość z 2 sesji na jego początku — blok 6 sesji) — bez oceny ('gap'), jak blok
    z brakiem: przepływu pierwszej z 5 ostatnich sesji nie znamy osobno, a suma 6 sesji na tle bloków po 5 była zawyżona o ok. 1/5
    (dotąd pole 'ns', „6 sesji do …” i ocena siły z tej sumy)."""
    return _trend_state(vals, size, dates, span, wt, [])


def _trend_state(vals, size, dates, span, wt, bl):
    """Stan trendu jednej serii (wartości w kolejności dat, None = brak). size = 5 (sesje), 7 (dni) albo 1 (tygodnie raportu).
    → {st, w, base, d, n, x, lc}. st: in_up / in_flat / in_down (napływ jak zwykle, ale większy / taki sam / słabszy),
    in_rev (napływ po tygodniach odpływu), in_new (napływ po okresie bez wyraźnego kierunku), in_dir (napływ, historia za krótka
    do oceny siły), in_stop (zwykle napływ, w tym tygodniu prawie nic); to samo dla out_*; mixed (duża suma, dni w różne strony);
    none; short; gap."""
    sums = _tr_sums(vals, size, 1 + TR_BASE_MAX, dates, span, wt, bl)
    if not sums or bl[0][0] != size:   # v296: ostatni blok z 6 sesji (wartość z 2 sesji na granicy) — wartości jednej z 5 sesji brak = bez oceny
        return {'st': 'gap'}
    w, prev = sums[0], sums[1:]
    if len(prev) < TR_BASE_MIN:
        return {'st': 'short', 'w': w, 'n': len(prev)}
    n = len(prev); lc = n < TR_BASE_MAX
    base = _mean(prev[:TR_BASE_MIN])
    typ = _mean([abs(x) for x in prev])
    sd = max(_sd(prev), TR_FLOOR * typ)
    if sd <= 0:
        return {'st': 'none', 'w': w, 'base': base, 'n': n, 'x': False, 'lc': lc}
    d = (w - base) / sd
    clear = _tr_clear(w, typ, None if size == 1 else vals[bl[0][1]:])   # v293: dni ostatniego bloku (bez wt = vals[-size:])
    bpos, bneg = base > 0 and base >= TR_DIR * typ, base < 0 and -base >= TR_DIR * typ
    if clear:
        s = 'in' if w > 0 else 'out'
        same, opp = (bpos, bneg) if w > 0 else (bneg, bpos)
        dd = d if w > 0 else -d                        # wynik w stronę kierunku tygodnia
        if lc:
            st = s + '_dir'
        elif same:
            st = s + ('_up' if dd >= TR_STRONG else '_down' if dd <= -TR_STRONG else '_flat')
        else:
            st = s + ('_rev' if opp else '_new')
    elif w and abs(w) >= TR_DIR * typ:
        st = 'mixed'                                   # duża suma z kilku dni, pozostałe dni w drugą stronę
    elif not lc and bpos and d <= -TR_STRONG:
        st = 'in_stop'                                 # v90: zwykle napływ, w tym tygodniu prawie nic (osobny stan — nie „słabszy napływ”)
    elif not lc and bneg and d >= TR_STRONG:
        st = 'out_stop'
    else:
        st = 'none'
    return {'st': st, 'w': w, 'base': base, 'd': d, 'n': n, 'x': not lc and abs(d) >= TR_EXC, 'lc': lc}


def trend_streak(vals):
    """Ile ostatnich wartości z rzędu ma ten sam znak (brak albo zero przerywa); znak: +1 / −1 / 0."""
    n, sg = 0, 0
    for x in reversed(vals):
        if not _isnum(x) or x == 0:
            break
        s = 1 if x > 0 else -1
        if sg and s != sg:
            break
        sg = s; n += 1
    return n, sg


def trend_day_z(vals):
    """Ostatnia wartość w odchyleniach od średniej najwyżej 60 poprzednich (tylko liczby); None, gdy mniej niż TR_DAY_N."""
    if not vals or not _isnum(vals[-1]):
        return None
    prev = [x for x in vals[-61:-1] if _isnum(x)]
    if len(prev) < TR_DAY_N:
        return None
    sd = _sd(prev)
    return (vals[-1] - _mean(prev)) / sd if sd > 0 else None


def wilson(k, n, z=1.96, n_eff=None):
    """95% przedział Wilsona dla odsetka k/n (w %); n_eff — mniejsza liczba niezależnych obserwacji (np. tygodni przy wielu rynkach)."""
    if not n:
        return None, None
    p = k / n; m = n_eff or n; den = 1 + z * z / m
    c = (p + z * z / (2 * m)) / den; h = z * ((p * (1 - p) / m + z * z / (4 * m * m)) ** 0.5) / den
    return max(0.0, round(100 * (c - h), 1)) + 0.0, min(100.0, round(100 * (c + h), 1)) + 0.0


def _iso_weeks(dates, vals, today):
    """Wartości dzienne → pełne tygodnie kalendarzowe (pon–nd) od najstarszego: [(poniedziałek, suma, wartości dni)].
    Tydzień z brakiem (None), tydzień z dniem dzisiejszym (niezakończony) i niepełny pierwszy tydzień historii (mniej niż 4 dni) są pomijane."""
    wk = {}
    for d, v in zip(dates, vals):
        dd = _d(d)
        if dd is None:
            continue
        wk.setdefault(dd - datetime.timedelta(days=dd.weekday()), []).append(v)
    cur = today - datetime.timedelta(days=today.weekday())
    W = [(m, sum(v), v) for m, v in sorted(wk.items()) if m < cur and all(_isnum(x) for x in v)]
    return W[1:] if W and len(W[0][2]) < 4 else W


def trend_persist(dates, vals, today, weeks=None, d0=None):
    """Jak często po tygodniu z wyraźnym kierunkiem następny tydzień kalendarzowy miał ten sam kierunek. Wyraźny tydzień — ta sama reguła
    co na kartach, z typowym tygodniem liczonym tylko z 4–8 wcześniejszych tygodni. → (k, n, pierwszy, ostatni poniedziałek par).
    v296: d0 (fund_group info['d0']) — pierwsza sesja każdej wartości; wartość z sesji dwóch tygodni kalendarzowych (przepływ dnia ze złym
    wierszem w piątek dodany do poniedziałku) — oba tygodnie niepełne, poza parami (brak, nie przepływ przeniesiony do następnego tygodnia)."""
    if d0 is not None and len(d0) == len(dates):
        mon = lambda s: (lambda x: x - datetime.timedelta(days=x.weekday()) if x else None)(_d(s))   # noqa: E731
        cut = {m for a, d in zip(d0, dates) if mon(a) != mon(d) for m in (mon(a), mon(d)) if m}
        vals = [None if mon(d) in cut else v for d, v in zip(dates, vals)]
    W = _iso_weeks(dates, vals, today)
    k = n = 0; first = last = None
    for i in range(len(W) - 1):
        prev = [s for _, s, _ in W[max(0, i - TR_BASE_MAX):i]]
        if len(prev) < TR_BASE_MIN or (W[i + 1][0] - W[i][0]).days != 7:
            continue
        m, s, days = W[i]
        if _tr_clear(s, _mean([abs(x) for x in prev]), days):
            n += 1; k += 1 if s * W[i + 1][1] > 0 else 0
            first = first or m; last = W[i + 1][0]
            if weeks is not None:
                weeks.add(m)
    return k, n, first and first.isoformat(), last and last.isoformat()


def _bdays(a, b, skip=()):
    """Dni robocze (pon–pt) po dniu a do dnia b włącznie, bez dni z `skip` (znane dni bez sesji)."""
    n, d = 0, a
    while d < b:
        d += datetime.timedelta(days=1)
        n += d.weekday() < 5 and d.isoformat() not in skip
    return n


def _tr_row(sid, g, m, size, dates, vals, usd=None, hold=None, lag=1, weekly_days=None, cur='USD', span=None, skip=(), wt=None):
    """Jeden wiersz TRENDÓW. lag = zwykłe opóźnienie publikacji w dniach roboczych (dane sesyjne); dane z każdego dnia kalendarza
    (size 7) — za stare po 3 dniach; weekly_days = po ilu dniach od końca tygodnia dane tygodniowe są za stare."""
    if not dates or not vals or len(dates) != len(vals):
        return None
    if wt is not None and len(wt) != len(vals):   # v293: wt — liczba sesji wartości (fundusze, fund_group info['ns'])
        wt = None
    ld = _d(dates[-1])
    if ld is None:
        return None
    t = trend_state(vals, size, dates, span, wt)
    today = _now_utc().date()
    age = (today - ld).days
    stale = age > weekly_days if weekly_days else (age > 3 if size == 7 else _bdays(ld, today, skip) > lag + 2)
    st = 'stale' if stale else t['st']
    r = {'id': sid, 'g': g, 'm': m, 'sz': size, 'cur': cur, 'date': ld.isoformat(), 'age': age, 'st': st}
    for k in ('w', 'base', 'd'):
        if _isnum(t.get(k)):
            r[k] = round(t[k], 2)
    for k in ('n', 'lc'):   # v296: bez 'ns' — blok z 6 sesji jest bez oceny ('gap')
        if k in t:
            r[k] = t[k]
    ev = st not in ('stale', 'gap', 'short')
    r['x'] = bool(ev and t.get('x'))                   # bez oceny — bez dopisków oceny
    ratio = 1.0 if cur == 'USD' else None
    if usd is not None and cur != 'USD':
        us = _tr_sums(usd, size, 1, dates, span, wt)
        if us:
            r['wu'] = round(us[0], 1)
            if _isnum(t.get('w')) and t['w']:
                ratio = us[0] / t['w']
    if ratio is not None and _isnum(t.get('w')) and _isnum(t.get('base')):
        r['du'] = round((t['w'] - t['base']) * ratio, 1)   # odchylenie od zwykłego poziomu w mln USD (do kafli)
    if _isnum(hold) and hold and _isnum(t.get('w')):
        r['ph'] = round(100 * t['w'] / hold, 2)
    vd = vals if wt is None else [x if k == 1 else None for x, k in zip(vals, wt)]   # v293: wartość z kilku sesji to nie „dzień” — bez oceny
    r['s'], r['sg'] = trend_streak(vd)                                                 # dnia, bez „ostatniego dnia” i bez serii dni (karta dzienna:
    dz = trend_day_z(vd) if size != 1 and ev else None                                 # „brak danych z tej sesji”); tło porównania też bez niej
    if dz is not None:
        r['dz'] = round(dz, 2)
    if _isnum(vd[-1]):
        r['last'] = round(vd[-1], 2)
    return r


def _tr_weeks(ds, vals, n=30):
    """Dane tygodniowe → kolejne tygodnie co 7 dni od ostatniego wstecz, z tolerancją ±3 dni (np. raport CFTC przesunięty na poniedziałek
    po święcie). Brakujący tydzień = None (nie zero, nie sklejenie); etykieta = prawdziwa data raportu albo termin wyliczony."""
    pts = sorted((d, v) for d, v in ((_d(a), b) for a, b in zip(ds, vals)) if d)
    if not pts:
        return [], []
    last = pts[-1][0]; B = {}
    for d, v in pts:
        k = round((last - d).days / 7)
        if abs((last - d).days - 7 * k) <= 3:
            B[k] = (d, v)
    out_d, out_v = [], []
    for k in range(n - 1, -1, -1):
        d, v = B.get(k, (last - datetime.timedelta(days=7 * k), None))
        out_d.append(d.isoformat()); out_v.append(v)
    return out_d, out_v


def _jpy_per_usd(S):
    """JPY za 1 USD ze średnich miesięcznych EBC (kursy.json: jednostek za 1 EUR) → {miesiąc: kurs}; brak pliku = pusty słownik."""
    m = (S.get('kursy') or {}).get('m') if isinstance(S.get('kursy'), dict) else None
    m = m if isinstance(m, dict) else {}
    j = {r[0]: r[1] for r in m.get('JPY') or [] if isinstance(r, list) and len(r) == 2 and _isnum(r[1]) and r[1] > 0}
    u = {r[0]: r[1] for r in m.get('USD') or [] if isinstance(r, list) and len(r) == 2 and _isnum(r[1]) and r[1] > 0}
    return {mo: j[mo] / u[mo] for mo in j if mo in u}


def _tr_cols(part, *idx):
    """Kolumny części pliku: (daty, kolumna idx[0], kolumna idx[1], …); nie-liczba = None."""
    d = [r for r in (part or {}).get('d') or [] if isinstance(r, list) and r and isinstance(r[0], str) and _d(r[0])]
    return ([r[0] for r in d],) + tuple([r[i] if len(r) > i and _isnum(r[i]) else None for r in d] for i in idx)


def _tr_fxd(part, ci, date):
    """v346 (T10-05): dzień kursu USD użytego dla sesji `date` — kolumna ci wiersza z tą datą (ISO); brak albo zły zapis = None (nigdy zgadywany)."""
    for r in reversed((part or {}).get('d') or []):
        if isinstance(r, list) and r and r[0] == date:
            v = r[ci] if len(r) > ci else None
            return v if isinstance(v, str) and _d(v) else None
    return None


def _tr_fx(r, fd, kind):
    """v346 (T10-05): wiersz z przeliczeniem na USD (jest `wu`) dostaje opis kursu: fxk „d” = kursy dzienne, „1” = jeden kurs na cały okres; fxd = jego dzień.
    Pola tylko opisowe — nie wchodzą do żadnej reguły ani do dziennika."""
    if r and 'wu' in r and fd:
        r['fxd'] = fd; r['fxk'] = kind


def _tr_sessions(part, *idx):
    """Tajwan i Hongkong: kolumny na pełnym kalendarzu dni roboczych od pierwszego do ostatniego wiersza, bez znanych dni bez sesji
    (part['empty']); dzień bez wiersza = None (brak, nie zero) — pomijany dzień nie jest cicho sklejany z sąsiednimi."""
    cols = _tr_cols(part, *idx)
    if not cols[0]:
        return cols
    empty = {x for x in (part or {}).get('empty') or [] if isinstance(x, str)}
    by = [dict(zip(cols[0], c)) for c in cols[1:]]
    have = set(cols[0])
    d0, d1 = _d(cols[0][0]), _d(cols[0][-1])
    cal = [(d0 + datetime.timedelta(days=i)).isoformat() for i in range((d1 - d0).days + 1)]
    cal = [c for c in cal if c in have or (_d(c).weekday() < 5 and c not in empty)]
    return (cal,) + tuple([b.get(c) for c in cal] for b in by)


def _cftc_roll(ds):
    """Raport CFTC w tygodniu wygasania kontraktów kwartalnych (±7 dni od 3. środy marca, czerwca, września, grudnia)."""
    d = _d(ds)
    if not d or d.month not in (3, 6, 9, 12):
        return False
    first = datetime.date(d.year, d.month, 1)
    wed3 = first + datetime.timedelta(days=(2 - first.weekday()) % 7 + 14)
    return abs((d - wed3).days) <= 7


def fund_split(a, b):
    """v93/v94: podział jednostek między dniami a i b ([data, NAV, liczba jednostek]): 1 = zwykły dzień; k (2, 3, 3/2, 1/2 …) = podział,
    gdy liczba jednostek zmienia się o prosty ułamek, a wartość funduszu (NAV × liczba) prawie nie; 0 = skok bez wyjaśnienia (dzień pomijany).
    v233: podział tylko z jednym ułamkiem zgodnym i z liczbą jednostek, i z NAV; jednostki ×ułamek przy NAV bez zmian (FUND_STALE_*) = 0.
    v235: NAV ±3% w regule bez poprawki; zgodność NAV ±10% dla ułamków nie do pomylenia (±5% dla FUND_BLISKIE).
    v239: drugie pasmo (FUND_STALE_U2/N2); „lustro” tylko w fund_pary (wstecz, po skoku jednostek) — dzień krachu przy płaskich jednostkach = 1."""
    nr, sr = b[1] / a[1], b[2] / a[2]
    if abs(sr - 1) > 0.15 and abs(nr * sr - 1) < 0.1:
        # v233: ułamek pasuje i do liczby jednostek, i do NAV (po 5%) i jest jedyny — dwa możliwe (5:4 i 4:3 przy napływie) = skok, nie zgadywanie
        ks = [k for q in FUND_PODZIALY for k in (q, 1 / q) if abs(sr / k - 1) < 0.05 and abs(nr * k - 1) < (0.05 if q in FUND_BLISKIE else 0.10)]
        return ks[0] if len(ks) == 1 else 0
    if abs(nr - 1) < FUND_STALE_N and any(abs(sr / k - 1) < FUND_STALE_U for q in FUND_PODZIALY for k in (q, 1 / q)):
        return 0   # v233: jednostki zmienione o ułamek podziału, NAV prawie bez zmian — podział bez poprawki NAV (skok, nie przepływ 25–33%)
    if abs(nr - 1) < FUND_STALE_N2 and any(abs(sr / k - 1) < FUND_STALE_U2 for q in FUND_PODZIALY for k in (q, 1 / q)):
        return 0   # v239: to samo w dniu ruchu ceny do 6%, gdy liczba jednostek trafia w ułamek prawie dokładnie (±0,5%)
    return 1 if 0.6 < nr < 1.6 and 1 / 3 < sr < 3 and 1 / FUND_PARA_X < nr * sr < FUND_PARA_X else 0   # v231: aktywa ponad 1,35× w dobę — skok


def fund_pary(h):
    """v233: współczynniki kolejnych par dni historii h (jak fund_split, para i = h[i] → h[i+1]). Druga noga podziału rozłożonego na dni
    (skok jednostek bez poprawki NAV, a 1–FUND_NOGI par później sama poprawka NAV — okno od dnia przed skokiem do końca tej pary to rozpoznany
    podział, pary pomiędzy zwykłe) = 0: inaczej dawała fałszywy zwrot (−25% przy 4:3) w zwrotach dziennych i w cenie tygodniowej (v239: także
    po 2–3 dniach). Tylko wstecz (wiersze do końca pary) — dziennik TRENDÓW nie zna dnia następnego."""
    P = [fund_split(a, b) for a, b in zip(h, h[1:])]
    for j in range(1, len(P)):
        if P[j] != 1:
            continue
        for i in range(j - 1, max(-1, j - 1 - FUND_NOGI), -1):   # najbliższy wcześniejszy skok (najwyżej FUND_NOGI par wstecz)
            if P[i] == 0:
                if all(P[x] == 1 for x in range(i + 1, j)) and fund_split(h[i], h[j + 1]) not in (0, 1):
                    P[j] = 0
                break
    return P


def _fund_rows(h):
    """Poprawne wiersze historii bez wierszy powtórzonych (ten sam NAV i ta sama liczba jednostek — np. dzień wolny w USA w pliku złota)."""
    h = [r for r in h or [] if isinstance(r, list) and len(r) == 3 and _d(r[0]) and _isnum(r[1]) and _isnum(r[2]) and r[1] > 0 and r[2] > 0]
    return h[:1] + [b for a, b in zip(h, h[1:]) if not (b[1] == a[1] and b[2] == a[2])]


def fund_flows(h, bez=None):
    """Historia funduszu [[data, NAV, liczba jednostek]] → {data: przepływ w mln USD} = zmiana liczby jednostek × NAV z tego dnia;
    w dniu podziału jednostek poprzednia liczba mnożona przez współczynnik podziału (v93); skok bez wyjaśnienia — dzień pominięty.
    v226: bez = daty złych wierszy już znane (historia oczyszczona w fund_group) — bez drugiego wykrywania."""
    out = {}
    h = _fund_rows(h)
    bad = set(_fund_clean(h)[1]) if bez is None else set(bez)   # v223: para dni z wierszem z błędem pliku — dzień pominięty (brak)
    for (a, b), k in zip(zip(h, h[1:]), fund_pary(h)):   # v233: podział rozłożony na dwa dni = obie pary skok (brak)
        if a[0] in bad or b[0] in bad:
            continue
        if k:
            out[b[0]] = (b[2] - a[2] * k) * b[1] / 1e6
    return out


def fund_group(fu, members, info=None):
    """Grupa funduszy → (daty, przepływy, aktywa w mln USD) do ostatniego wspólnego dnia. v94: dzień, którego nie ma któryś fundusz
    (np. inny kalendarz), nie przerywa serii — przepływy pozostałych funduszy z tego dnia dodajemy do najbliższego wspólnego dnia (sumy dokładne).
    v223: zły wiersz pliku (_fund_clean) poza sumą — jak inny kalendarz; wiersz bez przepływu (skok bez wyjaśnienia) = brak grupy w najbliższym
    wspólnym dniu (dotąd suma pomijała fundusz — brak liczony jak zero); aktywa z ostatniego poprawnego wiersza (zły najnowszy: „% aktywów” ×20 000).
    v293: info (słownik, opcjonalnie) ← 'ns': liczba sesji w każdej wartości = dni kalendarza plików grupy (także dni ze złym wierszem) od
    poprzedniej wartości; 2+ = przepływ z pominiętego dnia dodany do tego dnia (dotąd liczony jak jedna sesja — „ostatni dzień” EWZ 06.10.2026
    był sumą 05.10 i 06.10). Daty, wartości i aktywa bez zmian.
    v296: info ← także 'd0': pierwsza sesja (dzień kalendarza plików) każdej wartości — trend_persist pomija tygodnie, między którymi wartość
    przenosi przepływ (zły wiersz w piątek → przepływ w poniedziałku)."""
    F, B, H, C, S0 = [], [], [], set(), []
    for t in members:
        h = _fund_rows(((fu or {}).get(t) or {}).get('h') or [])
        bad = set(_fund_clean(h)[1])
        hk = [r for r in h if r[0] not in bad]   # v223: zły wiersz pliku poza sumą grupy — przepływ przez dwa dni trafia do następnego wiersza (jak inny kalendarz)
        fl = fund_flows(hk, bez=())   # v226: historia już oczyszczona — bez drugiego wykrywania (oznaczałoby kolejne dni po trwałym skoku)
        if bad:   # v227: para przez złe wiersze z aktywami ponad FUND_GR_X razy (trwały skok — np. podział bez poprawki NAV) — brak, nie przepływ
            for a, b in zip(hk, hk[1:]):
                if b[0] in fl and any(a[0] < x < b[0] for x in bad) and not (1 / FUND_GR_X < b[1] * b[2] / (a[1] * a[2]) < FUND_GR_X):
                    del fl[b[0]]
        if not fl:
            return [], [], None
        F.append(fl); B.append({r[0] for r in hk[1:]} - set(fl))   # v223: wiersz bez przepływu (skok bez wyjaśnienia) — brak grupy, nie zero
        C.update(r[0] for r in h); S0.append(hk[0][0])              # v293: kalendarz sesji plików (z dniami złych wierszy), początek
        H.append(hk[-1])                                             # v223: aktywa z ostatniego wiersza bez błędu pliku
    end = min(max(f) for f in F)
    days, vals, pend, zly = [], [], 0.0, False
    for d in sorted({d for f in F for d in f if d <= end} | {d for b in B for d in b if d <= end}):
        zly = zly or any(d in b for b in B)
        if all(d in f or d in b for f, b in zip(F, B)):
            days.append(d); vals.append(None if zly else sum(f[d] for f in F) + pend); pend, zly = 0.0, False
        else:
            pend += sum(f[d] for f in F if d in f)
    if info is not None:   # v293: sesje w każdej wartości — dni kalendarza od poprzedniej wartości (pierwsza: od najwcześniejszego początku)
        cal, j, prev, ns, d0 = sorted(C), 0, min(S0), [], []
        for d in days:
            k, a = 0, None
            while j < len(cal) and cal[j] <= d:
                if cal[j] > prev:
                    k += 1; a = a or cal[j]
                j += 1
            ns.append(max(1, k)); d0.append(a or d); prev = d
        info['ns'] = ns; info['d0'] = d0
    aum = sum(r[1] * r[2] for r in H) / 1e6
    return days, vals, aum


# v120: TRENDY — sygnały dzienne. Dla każdego rynku ostatni dzień jego danych: czy przepływ i ruch ceny odbiegają od zwykłego poziomu
# (z = odchylenie w rozrzutach z najwyżej 60 poprzednich dni), klasa dnia (f / p / fp / x / none), kierunek z założenia = kontynuacja,
# oraz test na całej historii pliku: jak często po takim dniu następna sesja miała ten sam znak. To opis danych i ich historii —
# nie prognoza i nie rekomendacja. Brak w danych = None, nigdy zero. Wszystko z plików tego przebiegu, bez zapytań do sieci.

def _td_z(vals, i, demean=True):
    """Wartość o indeksie i w rozrzutach najwyżej TD_LB poprzednich liczb (None pomijany — nigdy nie zastępowany zerem); mniej niż TD_MIN → None.
    Przepływy (demean=True): (v − średnia) / max(rozrzut, TD_FLOOR × typowy |dzień|); tło z samych zer: 0 albo ±TD_Z2 (niżej). Zwroty
    (demean=False): r / pierwiastek średniego r² (średni dzienny zwrot ≈ 0 — odejmowanie go dodałoby tylko szum); same zerowe zwroty w tle =
    cena stoi (plik bez aktualizacji) → brak porównania, None. Uogólnienie trend_day_z na dowolny indeks; tamta bez zmian."""
    if not vals or i < 0 or i >= len(vals) or not _isnum(vals[i]):
        return None
    prev = [x for x in vals[max(0, i - TD_LB):i] if _isnum(x)]
    if len(prev) < TD_MIN:
        return None
    if demean:
        m = _mean(prev)
        sd = max(_sd(prev), TD_FLOOR * _mean([abs(x) for x in prev]))
        if sd > 0:
            return (vals[i] - m) / sd
        # Rozrzut 0 zdarza się tylko wtedy, gdy wszystkie poprzednie dni to dokładnie 0 (liczba jednostek funduszu bez zmian przez tygodnie).
        # Prawdziwa liczba dnia nie może wtedy wyjść jako brak (strona napisałaby „brak danych”): dzień taki jak zwykle → 0; każdy inny jest
        # „dużo większy niż zwykle” → ±TD_Z2 (znak = kierunek). Tło nadal bez dnia t; jedna reguła dla wszystkich rynków.
        return 0.0 if vals[i] == m else (TD_Z2 if vals[i] > m else -TD_Z2)
    rms = (sum(x * x for x in prev) / len(prev)) ** 0.5
    return vals[i] / rms if rms > 0 else None


def _td_class(zf, zp, bd=False):
    """Klasa dnia z odchyleń przepływu (zf) i ceny (zp) → (reguła, kierunek, siła). Reguły rozłączne: fp (oba w tę samą stronę),
    f (tylko przepływ), p (tylko cena), x (sprzeczne — bez kierunku), none. Kierunek z założenia = kontynuacja (napływ / wzrost → +1).
    Obligacje (bd): cena nie wchodzi do reguły (wypłata odsetek obniża NAV — sp zawsze 0). Siła 0–3 = [wejście strzela] + [drugie zgodne,
    |z| ≥ 1] + [największe |z| wchodzące do reguły ≥ 2] — opisuje dzień, nigdy nie jest testowana. Jedne progi dla wszystkich rynków."""
    sf = 0 if zf is None or abs(zf) < TD_Z1 else (1 if zf > 0 else -1)
    sp = 0 if bd or zp is None or abs(zp) < TD_Z1 else (1 if zp > 0 else -1)
    if sf and sp == sf:
        rule, d = 'fp', sf
    elif sf and not sp:
        rule, d = 'f', sf
    elif sp and not sf:
        rule, d = 'p', sp
    elif sf and sp == -sf:
        rule, d = 'x', 0
    else:
        rule, d = 'none', 0
    if not d:
        return rule, 0, 0
    zs = [abs(zf) if zf is not None else 0.0] + ([] if bd else [abs(zp) if zp is not None else 0.0])
    return rule, d, 1 + int(rule == 'fp') + int(max(zs) >= TD_Z2)


def _td_next(date):
    """Następna sesja: pierwszy dzień pon–pt po dniu `date` (świąt w USA nie modelujemy — karta może stać się „nieaktualna” o sesję za wcześnie)."""
    d = _d(date) + datetime.timedelta(days=1)
    while d.weekday() >= 5:
        d += datetime.timedelta(days=1)
    return d


def _td_live(date, now_ny):
    """Karta aktualna do 16:15 czasu Nowego Jorku w dniu następnej sesji (ten sam zegar co _drop_open_session); później „nieaktualna”."""
    nx = _td_next(date)
    now = now_ny.replace(tzinfo=None) if getattr(now_ny, 'tzinfo', None) else now_ny
    return now < datetime.datetime(nx.year, nx.month, nx.day, 16, 15)


def _td_live_cr(date, now_utc):
    """v123: krypto — następny dzień = kolejna doba UTC (7 dni w tygodniu, bez weekendów i świąt); karta aktualna do końca tej doby
    (północ UTC po niej), potem „nieaktualna”. Zegar bez strefy traktowany jak UTC."""
    end = _d(date) + datetime.timedelta(days=2)
    now = now_utc.astimezone(datetime.timezone.utc).replace(tzinfo=None) if getattr(now_utc, 'tzinfo', None) else now_utc
    return now < datetime.datetime(end.year, end.month, end.day)


def _td_month_first(dates, i):
    """Czy wiersz i jest pierwszym wierszem swojego miesiąca kalendarzowego (obligacje: sesja wypłaty odsetek obniża NAV — nie jest wynikiem)."""
    return i <= 0 or str(dates[i])[:7] != str(dates[i - 1])[:7]


def _td_pairs(dates, flow, ret, pub=0, bd=False):
    """Test wstecz jednego rynku → [(data sygnału, reguła, kierunek, trafienie)]. Dla każdego dnia t: z liczone tylko z danych ≤ t;
    sygnał jest znany w sesji s = t + pub; wynik = zwrot sesji s+1 (ret[s+1], w %), wymagany: nie więcej niż TD_GAP dni po sesji s (i sesja s
    nie dalej niż TD_GAP dni od dnia t — przy pub > 0 luka w pliku nie może przesunąć sygnału o tydzień), bez
    podziału jednostek (zwrot None), różny od zera (dzień bez zmiany ceny to ani trafienie, ani pudło), u obligacji nie pierwszy wiersz
    miesiąca. Trafienie = ten sam znak co kierunek. Dni sprzeczne (x) zwracane z trafieniem None — nigdy nie są parą."""
    out = []
    n = len(dates)
    for t in range(n):
        zf = _td_z(flow, t) if flow else None
        zp = _td_z(ret, t, demean=False) if ret else None
        if zf is None and zp is None:
            continue
        rule, d, _ = _td_class(zf, zp, bd)
        if rule == 'none':
            continue
        if rule == 'x':
            out.append((dates[t], 'x', 0, None))
            continue
        s = t + pub
        if not ret or s + 1 >= n:
            continue
        r = ret[s + 1]
        if r is None or r == 0:
            continue
        a, b = _d(dates[s]), _d(dates[s + 1])
        if not a or not b or (b - a).days > TD_GAP or (a - _d(dates[t])).days > TD_GAP:
            continue
        if bd and _td_month_first(dates, s + 1):
            continue
        out.append((dates[t], rule, d, 1 if (r > 0) == (d > 0) else 0))
    return out


def _td_pool(lines, rules=None, since=None):   # v123: rules/since — linie krypto; None = TD_RULES / TD_SINCE w chwili wywołania
    """Pary wszystkich rynków rodziny razem → 7 linii (fam, reguła) z TD_RULES, zawsze wszystkie. lines: {(fam, reguła): [(data, trafienie, id)]}.
    Zakres 95% (Wilson) liczony na dni z sygnałem (rynki poruszają się razem), nie na pary. Połowy historii dzielone po datach sygnału.
    lk/ln/ldays = pary z datą sygnału ≥ TD_SINCE (poza próbą). Ocena: short (< TD_NEFF dni), edge (dolna granica > 50 i obie połowy > 50),
    anti (górna granica < 50 i obie połowy < 50 — informacja, nigdy odwrócenie strony), inaczej none. Brak liczby = None, nigdy zero."""
    def pct(hs):
        return round(100 * sum(hs) / len(hs), 1) if hs else None
    out = []
    for fam, rule in (TD_RULES if rules is None else rules):
        pr = sorted((lines or {}).get((fam, rule)) or [], key=lambda x: x[0])
        n = len(pr); k = sum(h for _, h, _ in pr)
        ds = sorted({d for d, _, _ in pr}); days = len(ds)
        lo, hi = wilson(k, n, n_eff=days) if n else (None, None)
        mid = ds[days // 2] if days > 1 else None
        p1 = pct([h for d, h, _ in pr if mid and d < mid]); p2 = pct([h for d, h, _ in pr if mid and d >= mid])
        late = [(d, h) for d, h, _ in pr if d >= (TD_SINCE if since is None else since)]
        if days < TD_NEFF:
            vd = 'short'
        elif lo is not None and lo > 50 and p1 is not None and p1 > 50 and p2 is not None and p2 > 50:
            vd = 'edge'
        elif hi is not None and hi < 50 and p1 is not None and p1 < 50 and p2 is not None and p2 < 50:
            vd = 'anti'
        else:
            vd = 'none'
        out.append({'fam': fam, 'rule': rule, 'k': k, 'n': n, 'days': days, 'from': ds[0] if ds else None, 'to': ds[-1] if ds else None,
                    'p': pct([h for _, h, _ in pr]), 'ci': [lo, hi], 'h1': p1, 'h2': p2, 'lk': sum(h for _, h in late), 'ln': len(late),
                    'ldays': len({d for d, _ in late}), 'm': len({i for _, _, i in pr}), 'need': max(0, TD_NEFF - days), 'vd': vd})
    return out


def _td_rules():
    """Słownik `dr` w trendy.json: stałe reguły i lista rynków poza sygnałami dziennymi (strona opisuje powody w metodzie)."""
    return {'lb': TD_LB, 'min': TD_MIN, 'z1': TD_Z1, 'z2': TD_Z2, 'floor': TD_FLOOR, 'gap': TD_GAP, 'neff': TD_NEFF, 'pub': dict(TD_PUB),
            'pubsym': dict(TD_PUB_SYM), 'excluded': list(TD_EXCLUDED)}      # pubsym: wyjątki według pliku, sprawdzane przed pub (wydawca)


def _td_fund_px(h):
    """Poprawne wiersze historii funduszu → (daty, NAV, zwroty w %): zwrot tylko między kolejnymi wierszami bez podziału jednostek
    (fund_split ≠ 1 → None; poziomu nie trzeba korygować, bo zwroty liczymy wyłącznie dzień do dnia)."""
    dates = [r[0] for r in h]; px = [r[1] for r in h]
    bad = set(_fund_clean(h)[1])   # v223: zwrot z pary dni z wierszem z błędem pliku — brak
    ret = [None] + [(b[1] / a[1] - 1) * 100 if k == 1 and a[0] not in bad and b[0] not in bad else None
                    for (a, b), k in zip(zip(h, h[1:]), fund_pary(h))]   # v233: także podział rozłożony na dwa dni = brak
    return dates, px, ret


def _td_series_fund(fu, sym):
    """Fundusz ETF → seria dzienna: daty = wiersze NAV, przepływ dnia z fund_flows (mln USD; skok bez wyjaśnienia = brak), zwrot NAV.
    Rodzina z TD_FAM (reszta = eq), opóźnienie publikacji: najpierw wyjątek pliku z TD_PUB_SYM, potem TD_PUB według wydawcy.
    Mniej niż 2 wiersze — bez serii."""
    p = fu.get(sym) if isinstance(fu, dict) else None
    h = _fund_rows(p.get('h') if isinstance(p, dict) else None)
    if len(h) < 2:
        return None
    dates, px, ret = _td_fund_px(h)
    fl = fund_flows(h)
    flow = [fl.get(d) for d in dates]
    iss = p.get('iss') if isinstance(p.get('iss'), str) else None
    return {'id': sym, 'fam': next((f for f, ms in TD_FAM.items() if sym in ms), 'eq'), 'grp': TD_GRP.get(sym), 'iss': iss,
            'pub': TD_PUB_SYM.get(sym, TD_PUB.get(iss, 0)), 'sym': sym, 'cur': 'USD', 'dates': dates, 'flow': flow, 'fu': flow, 'ret': ret}


def _td_series_ob(ob, spec, fu):
    """Wiersz kraju (Indie akcje, Tajwan, Hongkong) → seria: daty = dni przepływu (tw/hk: pełny kalendarz sesji, dzień bez wiersza = brak),
    przepływ w walucie kraju (fu = kolumna ≈ mln USD; Indie już w USD), cena = NAV funduszu USA z tego samego dnia ISO (brak NAV = brak,
    nigdy zero); zwrot tylko między kolejnymi dniami serii z NAV i bez podziału jednostek między nimi. Bez pliku funduszu — bez wiersza.
    nopool: pary reguły „p” (sama cena) nie idą do linii zbiorczych — wejście ceny to NAV tego samego funduszu, który ma własny wiersz
    (ten sam dzień, ta sama sesja wyniku liczyłyby się dwa razy); własne k/n karty liczone jak zwykle."""
    iid, part, col, ucol, sym, cur = spec
    if not isinstance(ob, dict) or not isinstance(ob.get(part), dict):
        return None
    p = fu.get(sym) if isinstance(fu, dict) else None
    h = _fund_rows(p.get('h') if isinstance(p, dict) else None)
    if len(h) < 2:
        return None
    cols = (_tr_sessions if part in ('tw', 'hk') else _tr_cols)(ob[part], *([col, ucol] if ucol else [col]))
    dates, flow = cols[0], cols[1]
    if not dates:
        return None
    fuv = cols[2] if ucol else flow
    zle = set(_fund_clean(h)[1])
    hk = [r for r in h if r[0] not in zle]   # v223: NAV z wiersza z błędem pliku nie jest ceną (zwrot między poprawnymi dniami)
    nav = {str(r[0])[:10]: r[1] for r in hk}
    splits = [b[0] for (a, b), k in zip(zip(hk, hk[1:]), fund_pary(hk)) if k != 1]   # v233: fund_pary (podział rozłożony na dwa dni)
    px = [nav.get(str(d)[:10]) for d in dates]
    ret = [None]
    for i in range(1, len(dates)):
        ok = px[i] is not None and px[i - 1] is not None and not any(dates[i - 1] < s <= dates[i] for s in splits)
        ret.append((px[i] / px[i - 1] - 1) * 100 if ok else None)
    return {'id': iid, 'fam': 'eq', 'grp': None, 'iss': None, 'pub': 0, 'sym': sym, 'cur': cur, 'dates': dates, 'flow': flow, 'fu': fuv, 'ret': ret,
            'nopool': ('p',)}


def _td_series_px(ce, sym):
    """Rynek tylko z ceną (zamknięcia z pliku cen) → seria bez przepływów: f / zf / fu = brak (None), zwrot między kolejnymi wierszami."""
    q = (ce.get('q') or {}).get(sym) if isinstance(ce, dict) else None
    d = [r for r in ((q or {}).get('d') or []) if isinstance(r, list) and len(r) > 1 and _isnum(r[1]) and r[1] > 0 and _d(r[0])]
    if len(d) < 2:
        return None
    dates = [str(r[0])[:10] for r in d]; px = [r[1] for r in d]
    ret = [None] + [(px[i] / px[i - 1] - 1) * 100 for i in range(1, len(px))]
    return {'id': sym, 'fam': 'eq', 'grp': None, 'iss': None, 'pub': 0, 'sym': sym, 'cur': None, 'dates': dates, 'flow': None, 'fu': None, 'ret': ret}


def _td_row(s, vd_by, own, now_ny, today, now_utc=None):   # v123: now_utc — zegar kart krypto (doba UTC)
    """Karta jednego rynku z ostatniego dnia jego serii. Stany: buy/sell (kierunek, aktualna, linia z przewagą), obs (kierunek, aktualna,
    bez przewagi — szara karta po stronie kierunku; ocena „anti” nigdy nie odwraca strony), x (sprzeczne), quiet (spokojny dzień),
    stale (po 16:15 NY następnej sesji — reguła i siła nadal policzone do opisu), short (żadne wejście reguły nie ma 40 dni historii),
    nodata (brak liczb z tego dnia). Wszystkie brakujące liczby = None, nigdy zero; z i zwrot na 2 miejsca, kwoty na 1."""
    i = len(s['dates']) - 1
    date = s['dates'][i]
    bd = s['fam'] == 'bd'
    flow, ret = s['flow'], s['ret']
    zf = _td_z(flow, i) if flow else None
    zp = _td_z(ret, i, demean=False) if ret else None
    rule, d, sg = _td_class(zf, zp, bd)
    inputs = [v for v in ([flow] if bd else [flow, ret]) if v]              # wejścia reguły (u obligacji cena nie wchodzi)
    has_now = any(_isnum(v[i]) for v in inputs)
    has_hist = any(sum(1 for x in v[max(0, i - TD_LB):i] if _isnum(x)) >= TD_MIN for v in inputs)
    live = _td_live_cr(date, now_utc) if s['fam'] == 'cr' else _td_live(date, now_ny)
    signal = rule in ('f', 'p', 'fp')
    vd = vd_by.get((s['fam'], rule)) if signal else None
    if not has_now:
        st = 'nodata'
    elif not has_hist:
        st = 'short'
    elif not live:
        st = 'stale'
    elif rule == 'x':
        st = 'x'
    elif rule == 'none':
        st = 'quiet'
    else:
        st = ('buy' if d > 0 else 'sell') if vd == 'edge' else 'obs'
    side = ('buy' if d > 0 else 'sell') if st in ('buy', 'sell', 'obs') else 'none'
    o = own.get((s['id'], rule), (0, 0)) if signal else (None, None)

    def rnd(x, k):
        return round(x, k) if _isnum(x) else None
    return {'id': s['id'], 'fam': s['fam'], 'grp': s['grp'], 'iss': s['iss'], 'pub': s['pub'], 'sym': s['sym'], 'date': date,
            'nx': (_d(date) + datetime.timedelta(days=1) if s['fam'] == 'cr' else _td_next(date)).isoformat(), 'live': live, 'age': (today - _d(date)).days,
            'f': rnd(flow[i] if flow else None, 2), 'cur': s['cur'], 'fu': rnd(s['fu'][i] if s['fu'] else None, 2), 'zf': rnd(zf, 2),
            'r': rnd(ret[i] if ret else None, 2), 'zp': rnd(zp, 2), 'rule': rule, 'dir': d, 'side': side, 'str': sg, 'st': st, 'vd': vd,
            'ik': o[0], 'in': o[1]}


def build_daily(S):
    """Sygnały dzienne → (d, bd): d = karty rynków (fundusze z TR_FE, wiersze krajów z TD_OB, rynki tylko z ceną z TD_PX — lista zamknięta,
    wyniki niczego nie dodają ani nie usuwają; rynek bez serii cen jest pomijany, nie pokazywany jako karta z samymi brakami),
    bd = 7 linii testu wstecz (zawsze wszystkie, także z n = 0). Zepsuta seria jednego rynku (budowa, test wstecz albo karta) → uwaga
    w meta, bez jego karty; reszta zostaje. Gdy nie powstała żadna karta (brak serii wejściowych albo wszystkie zepsute) → (None, None):
    blok niepoliczony, strona go ukrywa — pusta lista znaczyłaby „dziś zero rynków”, a to nieprawda. Nie zmienia S.
    Zegary: _ny_now (aktualność karty), _now_utc (wiek danych) — w testach podmieniane."""
    S = S if isinstance(S, dict) else {}
    fu = (S.get('fundusze') or {}).get('f') if isinstance(S.get('fundusze'), dict) else None
    ob = S.get('obce') if isinstance(S.get('obce'), dict) else {}
    ce = S.get('ceny') if isinstance(S.get('ceny'), dict) else {}
    todo = [(sym, lambda sym=sym: _td_series_fund(fu, sym)) for sym in TD_GRP] + \
           [(sp[0], lambda sp=sp: _td_series_ob(ob, sp, fu)) for sp in TD_OB] + \
           [(sym, lambda sym=sym: _td_series_px(ce, sym)) for sym in TD_PX]
    series = []
    for name, fn in todo:
        try:
            s = fn()
            if s:
                series.append(s)
        except Exception as e:
            META['notes'].append(mask(f'trendy dziennie {name}: {e}'))
    if not series:
        return None, None                                   # żadnej serii wejściowej — blok niepoliczony (None), nie „zero rynków” ([])
    lines = {key: [] for key in TD_RULES}
    own = {}
    good = []
    for s in series:
        try:
            pr = _td_pairs(s['dates'], s['flow'], s['ret'], s['pub'], s['fam'] == 'bd')
        except Exception as e:                              # zepsuta seria jednego rynku: uwaga, bez jego par i karty; reszta zostaje
            META['notes'].append(mask(f"trendy dziennie {s['id']}: {e}"))
            continue
        good.append(s)
        for dt, rule, d, hit in pr:
            if hit is None:
                continue
            if (s['fam'], rule) in lines and rule not in s.get('nopool', ()):
                lines[(s['fam'], rule)].append((dt, hit, s['id']))
            o = own.setdefault((s['id'], rule), [0, 0]); o[0] += hit; o[1] += 1
    bd = _td_pool(lines)
    vd_by = {(b['fam'], b['rule']): b['vd'] for b in bd}
    now_ny, today = _ny_now(), _now_utc().date()
    rows = []
    for s in good:
        try:
            rows.append(_td_row(s, vd_by, own, now_ny, today))
        except Exception as e:                              # zepsuty ostatni dzień jednego rynku: uwaga, bez jego karty
            META['notes'].append(mask(f"trendy dziennie {s['id']}: {e}"))
    return (rows, bd) if rows else (None, None)


def _td_series_cr(kc, sym, today):
    """v123: para <SYM>USDT z pliku cen krypto → seria dzienna (doba UTC). Tylko zamknięte doby: wiersz z datą ≥ dziś (UTC) odpada —
    budowniczy pliku już pomija trwającą dobę, to druga straż. Zamknięcie musi być liczbą > 0; inne wiersze odpadają (brak, nigdy zero).
    Daty muszą ściśle rosnąć — inaczej ValueError (uwaga w meta, bez karty tej pary). Zwrot w % tylko między kolejnymi dobami
    kalendarzowymi: luka w danych = brak (None), nigdy zero ani zwrot przez dwie doby. Bez przepływów: f / zf / fu / waluta = brak.
    Mniej niż 2 wiersze — bez serii (bez karty)."""
    q = (kc.get('q') or {}).get(sym) if isinstance(kc, dict) else None
    d = [r for r in ((q or {}).get('d') or []) if isinstance(r, list) and len(r) > 1 and _isnum(r[1]) and r[1] > 0 and _d(r[0]) and _d(r[0]) < today]
    if len(d) < 2:
        return None
    dates = [str(r[0])[:10] for r in d]; px = [r[1] for r in d]
    if any(a >= b for a, b in zip(dates, dates[1:])):
        raise ValueError('daty nie rosną')
    ret = [None] + [(px[i] / px[i - 1] - 1) * 100 if (_d(dates[i]) - _d(dates[i - 1])).days == 1 else None for i in range(1, len(px))]
    return {'id': sym, 'fam': 'cr', 'grp': None, 'iss': None, 'pub': 0, 'sym': sym, 'cur': None, 'dates': dates, 'flow': None, 'fu': None, 'ret': ret}


def build_daily_cr(S):
    """v123: sygnały dzienne krypto → (wiersze, linie): pary z TR_CR_SYMS, reguła „p” (sam ruch ceny), test na następnej dobie UTC,
    linie z TD_RULES_CR z własną wersją (v) i datą wdrożenia (since). Brak pliku cen krypto albo żadnej serii → (None, None), nie „zero
    monet”. Zepsuta seria jednej pary → uwaga w meta, bez jej karty; reszta zostaje. Nie zmienia S. Zegar: _now_utc (w testach podmieniany)."""
    S = S if isinstance(S, dict) else {}
    kc = S.get('ceny-krypto') if isinstance(S.get('ceny-krypto'), dict) else None
    if not kc:
        return None, None
    now_utc = _now_utc(); today = now_utc.date()
    series = []
    for sym in TR_CR_SYMS:
        try:
            s = _td_series_cr(kc, sym, today)
            if s:
                series.append(s)
        except Exception as e:
            META['notes'].append(mask(f'trendy dziennie krypto {sym}: {e}'))
    if not series:
        return None, None
    lines = {key: [] for key in TD_RULES_CR}; own = {}; good = []
    for s in series:
        try:
            pr = _td_pairs(s['dates'], None, s['ret'], 0, False)
        except Exception as e:                              # zepsuta seria jednej pary: uwaga, bez jej par i karty
            META['notes'].append(mask(f"trendy dziennie krypto {s['id']}: {e}")); continue
        good.append(s)
        for dt, rule, d, hit in pr:
            if hit is None:
                continue
            if ('cr', rule) in lines:
                lines[('cr', rule)].append((dt, hit, s['id']))
            o = own.setdefault((s['id'], rule), [0, 0]); o[0] += hit; o[1] += 1
    bd = _td_pool(lines, TD_RULES_CR, TD_SINCE_CR)
    for b in bd:
        b['v'], b['since'] = TD_VC, TD_SINCE_CR               # linie krypto niosą własną wersję i datę wdrożenia
    vd_by = {(b['fam'], b['rule']): b['vd'] for b in bd}
    rows = []
    for s in good:
        try:
            rows.append(_td_row(s, vd_by, own, None, today, now_utc))
        except Exception as e:
            META['notes'].append(mask(f"trendy dziennie krypto {s['id']}: {e}"))
    return (rows, bd) if rows else (None, None)


# v125: sygnały dzienne krypto, wersja reguły 2 (rodzina „cr”) — pięć powodów z pliku data/krypto-dzien.json (tylko dla zbieracza),
# dwie linie łączone, okno pomiaru od 06:00 UTC doby po dacie danych przez 24 h. Ocena w próbie: zakres 99,3% (7 linii naraz), porównanie
# ze „zwykłą dobą” (b0), obie połowy historii. Licznik „od wdrożenia” wyłącznie z dziennika kart zapisanych tak, jak były na stronie
# (data/krypto-dziennik.json), oceniany tylko w punktach kontrolnych 100/200/400 dób z sygnałem (zakres 99,8%), każda ocena zamrożona.
# Brak = None, nigdy zero; bez zapytań do sieci. Wersja 1 (build_daily_cr) bez zmian — działa, dopóki plik dzienny nie jest pełny (ready).

def _td_cut(day):
    """Granica „na czas” doby danych `day`: 'YYYY-MM-DDTHH:MM:SS' doby następnej, TD_CR_CUT minut po północy UTC (05:30);
    porównywalna z iso[:19]."""
    t = datetime.datetime.combine(_d(day) + datetime.timedelta(days=1), datetime.time()) + datetime.timedelta(minutes=TD_CR_CUT)
    return t.strftime('%Y-%m-%dT%H:%M:%S')


def _td_early(iso, day):
    """True, gdy czas `iso` (UTC, pierwsze 19 znaków) jest przed granicą doby danych `day`; None albo '' → False (nieznany czas = po czasie)."""
    return isinstance(iso, str) and len(iso) >= 19 and iso[:19] < _td_cut(day)


def _td_cal(first, last):
    """Wszystkie doby kalendarzowe od first do last włącznie (ISO) — oś serii krypto (7 dni w tygodniu)."""
    d0, d1 = _d(first), _d(last)
    return [(d0 + datetime.timedelta(days=k)).isoformat() for k in range((d1 - d0).days + 1)]


def _td_series_cr2(kd, sym, today):
    """Para → seria kalendarzowa (doby UTC < today): zamknięcie, otwarcie świecy 06:00 i pięć wejść {p, t, e, s, h} (e tylko dla par
    z TD_CR_FLOWS) oraz znaczniki „na czas”. Brak = None, nigdy 0. Daty w q muszą rosnąć, inaczej ValueError. `late` (stan karty) i znacznik
    „na czas” premii kontraktów najnowszej doby są ŚCISŁE: na czas tylko wtedy, gdy `seen` części nazywa najnowszą dobę i jest przed granicą
    (nieznany czas zapisu = po czasie). Premia: także `sp` — poprzednia para [doba, czas zapisu], którą budowniczy zachowuje, gdy zapisze
    nowszą dobę premii (ok. 00:20 UTC premia doby D+1 jest już zapisana, a świece D+1 jeszcze nie — karta doby D nie traci wtedy głosu
    premii, która przyszła na czas). Przepływy i stablecoiny najnowszej doby: także tło (TD_LB dób przed nią) musi być zapisane przed jej
    granicą — wiersz tła zapisany później zmieniłby z po czasie (przegląd 27.09)."""
    q = ((kd.get('q') or {}).get(sym) or {}) if isinstance(kd, dict) else {}
    rows = [r for r in (q.get('d') or []) if isinstance(r, list) and len(r) == 5 and _d(r[0]) and _d(r[0]) < today
            and _isnum(r[1]) and r[1] > 0]
    if len(rows) < 2:
        return None
    days = [str(r[0])[:10] for r in rows]
    if any(a >= b for a, b in zip(days, days[1:])):
        raise ValueError('daty nie rosną')
    by = {str(r[0])[:10]: r for r in rows}
    dates = _td_cal(days[0], days[-1])

    def col(k, pos):
        return [(by[d][k] if d in by and _isnum(by[d][k]) and (by[d][k] > 0 if pos else by[d][k] >= 0) else None) for d in dates]
    close, qv, tb, o6 = col(1, True), col(2, False), col(3, False), col(4, True)
    p = [None] + [(close[i] / close[i - 1] - 1) * 100 if close[i] and close[i - 1] else None for i in range(1, len(dates))]
    t = [100 * (2 * b / a - 1) if a and b is not None and b <= a else None for a, b in zip(qv, tb)]
    hq = (kd.get('hl') or {}).get(sym) or {}
    hd = {str(r[0])[:10]: r for r in (hq.get('d') or []) if isinstance(r, list) and len(r) == 3}
    h = [hd[d][1] / 100 if d in hd and _isnum(hd[d][1]) and _isnum(hd[d][2]) and hd[d][2] >= TD_CR_HMIN else None for d in dates]
    # stablecoiny: pierwsza opublikowana ZMIANA doby (kolumna 5, USD), wyliczona przez budowniczego z jednej odpowiedzi dostawcy — nigdy
    # różnica dwóch zapisanych poziomów (przeliczona wstecz historia poziomów dałaby skok na dobie granicznej)
    st = {str(r[0])[:10]: r for r in ((kd.get('st') or {}).get('d') or []) if isinstance(r, list) and len(r) == 6}
    s, s_on = [], []
    for d in dates:
        b = st.get(d)
        ok = bool(b) and _isnum(b[5])
        s.append(b[5] / 1e6 if ok else None)
        s_on.append(ok and (b[3] is None or _td_early(b[3], d)) and (b[4] is None or _td_early(b[4], d)))
    inp = {'p': p, 't': t, 's': s, 'h': h}
    on = {'s': s_on}
    if sym in TD_CR_FLOWS:
        cm = {str(r[0])[:10]: r for r in (((kd.get('cm') or {}).get(sym.lower()) or {}).get('d') or [])
              if isinstance(r, list) and len(r) == 5 and _isnum(r[1]) and _isnum(r[2])}
        inp['e'] = [cm[d][1] - cm[d][2] if d in cm else None for d in dates]
        on['e'] = [d in cm and _td_early(cm[d][3], d) and (cm[d][4] is None or _td_early(cm[d][4], d)) for d in dates]
    last = dates[-1]
    bg0 = (_d(last) - datetime.timedelta(days=TD_LB)).isoformat()

    def bg_ok(by_day):
        """Tło najnowszej doby (wiersze z TD_LB dób przed nią) zapisane przed jej granicą: seen null (zasilenie) albo przed 05:30 doby po niej."""
        return not any(bg0 <= d < last and r[4] is not None and not _td_early(r[4], last) for d, r in by_day.items())
    s_on[-1] = s_on[-1] and bg_ok(st)
    if 'e' in on:
        on['e'][-1] = on['e'][-1] and bg_ok(cm)

    def seen_ok(x, keys=('seen',)):
        for k in keys:
            sn = x.get(k) if isinstance(x.get(k), list) and len(x.get(k)) == 2 else None
            if sn and sn[0] == last and _td_early(sn[1], last):
                return True
        return False
    on['h'] = [True] * len(dates)                 # test wstecz: historyczne doby q i h liczymy jako na czas (tekst metody m.4)
    on['h'][-1] = seen_ok(hq, ('seen', 'sp'))
    return {'id': sym, 'sym': sym, 'dates': dates, 'close': close, 'o6': o6, 'in': inp, 'on': on, 'late': not seen_ok(q)}


def _td_votes(s, i):
    """→ ({k: (wartość, z, głos, na_czas)}, N). Głos = kierunek·znak(z), gdy |z| ≥ TD_Z1 i wejście dotarło na czas; inaczej 0."""
    out, N = {}, 0
    for k, dr in TD_CR_IN:
        vals = s['in'].get(k)
        if vals is None:
            continue
        z = _td_z(vals, i, demean=(k != 'p'))
        on = s['on'][k][i] if k in s['on'] else True
        v = dr * (1 if z > 0 else -1) if (z is not None and abs(z) >= TD_Z1 and on) else 0
        out[k] = (vals[i] if 0 <= i < len(vals) else None, z, v, on)
        N += v
    return out, N


def _td_win(s, i):
    """Wynik doby danych i (%): otwarcie 06:00 UTC doby i+2 / otwarcie 06:00 UTC doby i+1 − 1; brak → None."""
    o = s['o6']
    if i + 2 >= len(o) or not o[i + 1] or not o[i + 2]:
        return None
    return (o[i + 2] / o[i + 1] - 1) * 100


def _td_pairs_cr2(s, votes=None):
    """→ [(doba, linia, głos, trafienie)]: linia k dla każdego wejścia, które strzela; 'n2' przy |N| ≥ 2; 'all' przy N ≠ 0.
    Wynik None albo 0 → bez pary; doba sprzeczna (głosy za i przeciw po równo) daje tylko pary wejść."""
    out = []
    for i in range(len(s['dates'])):
        V, N = votes[i] if votes is not None else _td_votes(s, i)
        if not any(x[2] for x in V.values()):
            continue
        y = _td_win(s, i)
        if y is None or y == 0:
            continue
        d = s['dates'][i]
        for k, x in V.items():
            if x[2]:
                out.append((d, k, x[2], 1 if (y > 0) == (x[2] > 0) else 0))
        if N:
            g = 1 if N > 0 else -1
            h = 1 if (y > 0) == (g > 0) else 0
            if abs(N) >= 2:
                out.append((d, 'n2', g, h))
            out.append((d, 'all', g, h))
    return out


def _td_vd_cr2(k, n, days, h1, h2, bm, bn, z=None):
    """short / edge / anti / none — zakres rodzinny (z = TD_CR_ZM w próbie, TD_CR_ZL w punkcie kontrolnym dziennika; n_eff = dni)
    wobec max/min(50, b0); obie połowy historii po tej samej stronie progu."""
    if days < TD_NEFF or not n:
        return 'short'
    la, ha = wilson(k, n, z=z or TD_CR_ZM, n_eff=days)
    if la > bm and h1 is not None and h1 > bm and h2 is not None and h2 > bm:
        return 'edge'
    if ha < bn and h1 is not None and h1 < bn and h2 is not None and h2 < bn:
        return 'anti'
    return 'none'


def _td_pct(hs):
    """Odsetek trafień w % (1 miejsce po przecinku); pusta lista → None (nigdy 0)."""
    return round(100 * sum(hs) / len(hs), 1) if hs else None


def _td_stat(pr, ys, z=None):
    """Jedna linia (albo jeden punkt kontrolny dziennika): pary [(doba, trafienie, moneta, głos)], ys {moneta: {doba: y}} → k, n, days,
    from, to, p, ci (95%), ca (z), h1/h2 (podział na medianie dób sygnału), u (udział okien wzrostowych każdej monety wśród dób z [from, to]
    z y ≠ 0), b0, bm, bn, vd."""
    z = z or TD_CR_ZM
    pr = sorted(pr, key=lambda x: x[0])
    n = len(pr); k = sum(p[1] for p in pr)
    ds = sorted({p[0] for p in pr}); days = len(ds)
    mid = ds[days // 2] if days > 1 else None
    h1 = _td_pct([p[1] for p in pr if mid and p[0] < mid]); h2 = _td_pct([p[1] for p in pr if mid and p[0] >= mid])
    u = {}
    for c in {p[2] for p in pr}:
        yy = [v for d, v in (ys.get(c) or {}).items() if ds[0] <= d <= ds[-1] and v]
        u[c] = sum(1 for v in yy if v > 0) / len(yy) if yy else 0.5
    b0 = 100 * sum(u[p[2]] if p[3] > 0 else 1 - u[p[2]] for p in pr) / n if n else None
    bm, bn = max(50.0, b0 if b0 is not None else 50.0), min(50.0, b0 if b0 is not None else 50.0)
    lo, hi = wilson(k, n, n_eff=days) if n else (None, None)
    la, ha = wilson(k, n, z=z, n_eff=days) if n else (None, None)
    return {'k': k, 'n': n, 'days': days, 'from': ds[0] if ds else None, 'to': ds[-1] if ds else None, 'p': _td_pct([p[1] for p in pr]),
            'ci': [lo, hi], 'ca': [la, ha], 'h1': h1, 'h2': h2, 'u': u, 'b0': b0, 'bm': bm, 'bn': bn,
            'vd': _td_vd_cr2(k, n, days, h1, h2, bm, bn, z)}


def _td_side(pr, u, g):
    """Opisowy podział linii według strony głosu (g = +1 kupno, −1 sprzedaż) — nigdy nie oceniany: {k, n, days, p, b0 (zwykła doba
    tej strony), ci}."""
    q = [p for p in pr if p[3] == g]
    n = len(q); k = sum(p[1] for p in q); days = len({p[0] for p in q})
    b0 = 100 * sum(u[p[2]] if g > 0 else 1 - u[p[2]] for p in q) / n if n else None
    lo, hi = wilson(k, n, n_eff=days) if n else (None, None)
    return {'k': k, 'n': n, 'days': days, 'p': _td_pct([p[1] for p in q]), 'b0': None if b0 is None else round(b0, 1), 'ci': [lo, hi]}


def _td_y1(pr, today):
    """Pary linii z ostatnich TD_CR_Y1 dni (obie strony; sam opis, nigdy nie oceniany)."""
    lo = (today - datetime.timedelta(days=TD_CR_Y1)).isoformat()
    q = [p for p in pr if p[0] >= lo]
    n = len(q); k = sum(p[1] for p in q); ds = sorted({p[0] for p in q})
    a, b = wilson(k, n, n_eff=len(ds)) if n else (None, None)
    return {'k': k, 'n': n, 'days': len(ds), 'p': _td_pct([p[1] for p in q]), 'ci': [a, b], 'from': ds[0] if ds else None,
            'to': ds[-1] if ds else None}


def _td_pool_cr2(lines, ys, since=None, log=None, today=None):
    """7 linii (TD_RULES_CR2, zawsze wszystkie). lines: {(rodzina, k): [(doba, trafienie, id, głos)]}; ys: {id: {doba: y}} (każda doba
    z wynikiem); log: dziennik (None = nieznany w tym przebiegu → lk/ln/ldays null, lvd 'wait'). Ocena dziennika (`lvd`, `lc`) istnieje tylko
    w punktach kontrolnych zapisanych w dzienniku (`cp`) i nigdy nie jest liczona od nowa między nimi; lk/ln/ldays to bieżący licznik (bez oceny)."""
    since = since or TD_SINCE_CR2
    today = today or _now_utc().date()
    JL, _ = _td_cr_pairs(log, since) if isinstance(log, dict) else (None, None)
    out = []
    for fam, rule in TD_RULES_CR2:
        pr = sorted((lines or {}).get((fam, rule)) or [], key=lambda x: x[0])
        S = _td_stat(pr, ys)
        days, bm = S['days'], S['bm']
        sq = math.sqrt(bm / 100 * (1 - bm / 100) / days) if days else None
        L = sorted(JL[rule]) if JL is not None else None
        cps = sorted(((log or {}).get('cp') or {}).get(rule) or [], key=lambda x: x[0]) if JL is not None else []
        lc = None
        if cps:
            c = cps[-1]
            lc = {'c': c[0], 'k': c[1], 'n': c[2], 'p': round(100 * c[1] / c[2], 1) if c[2] else None, 'b0': c[3], 'ca': [c[6], c[7]],
                  'vd': c[8], 'to': c[9]}
        nx = [c for c in TD_CR_LOOKS if not lc or c > lc['c']]
        out.append({'fam': fam, 'rule': rule, 'k': S['k'], 'n': S['n'], 'days': days, 'from': S['from'], 'to': S['to'],
                    'p': S['p'], 'ci': S['ci'], 'ca': S['ca'], 'cl': TD_CR_CL, 'M': TD_CR_M,
                    'b0': None if S['b0'] is None else round(S['b0'], 1),
                    'thr': round(bm + 100 * TD_CR_ZM * sq, 1) if days else None,
                    'mde': round(bm + 100 * (TD_CR_ZM + TD_CR_ZP) * sq, 1) if days else None,
                    'h1': S['h1'], 'h2': S['h2'],
                    'sb': _td_side(pr, S['u'], 1), 'ss': _td_side(pr, S['u'], -1), 'y1': _td_y1(pr, today),
                    'lk': sum(x[1] for x in L) if L is not None else None, 'ln': len(L) if L is not None else None,
                    'ldays': len({x[0] for x in L}) if L is not None else None,
                    'lvd': lc['vd'] if lc else 'wait', 'lc': lc, 'lnx': nx[0] if nx else None, 'cll': TD_CR_CLL,
                    'm': len({p[2] for p in pr}), 'need': max(0, TD_NEFF - days), 'vd': S['vd'], 'v': TD_VC2, 'since': since, 'wh': TD_CR_WH,
                    'cut': TD_CR_CUT})
    return out


def _td_live_cr2(date, now_utc):
    """Karta doby danych `date` jest aktualna do końca swojego okna: now < 06:00 UTC doby date+2 (zegar bez strefy = UTC)."""
    end = _d(date) + datetime.timedelta(days=2)
    now = now_utc.astimezone(datetime.timezone.utc).replace(tzinfo=None) if getattr(now_utc, 'tzinfo', None) else now_utc
    return now < datetime.datetime(end.year, end.month, end.day, TD_CR_WH)


def _td_row_cr2(s, vd_by, own, today, now_utc):
    """Karta najnowszej doby serii (SPEC-v125 §5.1 z dopiskiem SPEC-v125-ADDENDUM). Stany po kolei: nodata → short → stale → late → x → quiet
    → buy/sell (kolor) → obs. Kolor tylko wtedy, gdy linia obejmująca kartę ma potwierdzoną przewagę (ek), żaden głosujący powód po drugiej
    stronie jej nie ma, a linia połączenia karty (n2 przy |N| ≥ 2, inaczej all) nie wychodzi „odwrotnie” (anti).
    Reguła wiersza v2: 'c' (N ≠ 0), 'cx' (są głosy, ale po równo — sprzeczne), 'c0' (żaden powód nie głosuje). Nigdy kody v1 ('x', 'none'):
    strona sprzed v125 (karta przeglądarki otwarta przed wdrożeniem, TRD_DRL = f/p/fp/x/none) odrzuca wtedy KAŻDY wiersz v2 i pokazuje
    swoją notę, zamiast opisywać kartę v2 zdaniami v1, które dla niej są nieprawdziwe (przegląd 27.09).
    v330 (Z05-1): odchylenie z w rs i zp przez _tdw_rz (jak świat od v127) — publikowana liczba nie przekracza progu 1 ani 2 przez samo zaokrąglenie
    (BNB 30.10.2024: −1,9962 → było −2,00, teraz −1,99: strona czyta „mocno” z liczby, a siła dnia liczona z niezaokrąglonej)."""
    i = len(s['dates']) - 1
    date = s['dates'][i]
    V, N = _td_votes(s, i)
    has_now = any(_isnum(x[0]) for x in V.values())
    has_hist = any(sum(1 for x in s['in'][k][max(0, i - TD_LB):i] if _isnum(x)) >= TD_MIN for k in V)
    live = _td_live_cr2(date, now_utc)
    fired = {k: x[2] for k, x in V.items() if x[2]}
    d = (1 if N > 0 else -1) if N else 0
    rule = 'c' if d else ('cx' if fired else 'c0')    # kody tylko wersji 2 — stara strona ich nie zna (docstring)
    lead = 'n2' if abs(N) >= 2 else 'all'
    ek = ([k for k, g in fired.items() if g == d and vd_by.get(('cr', k)) == 'edge']
          + (['n2'] if abs(N) >= 2 and vd_by.get(('cr', 'n2')) == 'edge' else [])
          + (['all'] if vd_by.get(('cr', 'all')) == 'edge' else [])) if d else []
    against = [k for k, g in fired.items() if g == -d and vd_by.get(('cr', k)) == 'edge'] if d else []
    colour = bool(ek) and not against and vd_by.get(('cr', lead)) != 'anti'
    if not has_now:
        st = 'nodata'
    elif not has_hist:
        st = 'short'
    elif not live:
        st = 'stale'
    elif s['late']:
        st = 'late'
    elif rule == 'cx':
        st = 'x'
    elif rule == 'c0':
        st = 'quiet'
    else:
        st = ('buy' if d > 0 else 'sell') if colour else 'obs'
    side = ('buy' if d > 0 else 'sell') if st in ('buy', 'sell', 'obs') else 'none'
    agree = [k for k, g in fired.items() if g == d] if d else []
    strong = any(V[k][1] is not None and abs(V[k][1]) >= TD_Z2 for k in agree)
    sg = min(3, len(agree) + int(strong)) if d else 0
    o = own.get(s['id'], (0, 0)) if d else (None, None)
    lv = vd_by.get(('cr', lead))

    def rnd(x, k):
        return (round(x, k) if k else int(round(x))) if _isnum(x) else None
    rs = [[k, rnd(50 + V[k][0] / 2 if k == 't' and _isnum(V[k][0]) else V[k][0], TD_CR_DIG[k]), _tdw_rz(V[k][1]), V[k][2]]
          for k, _ in TD_CR_IN if k in V]
    return {'id': s['id'], 'fam': 'cr', 'grp': None, 'iss': None, 'pub': 0, 'sym': s['sym'], 'date': date,
            'nx': (_d(date) + datetime.timedelta(days=1)).isoformat(), 'live': live, 'age': (today - _d(date)).days,
            'f': None, 'cur': None, 'fu': None, 'zf': None, 'r': rnd(V['p'][0], 2), 'zp': _tdw_rz(V['p'][1]),
            'rule': rule, 'dir': d, 'side': side, 'str': sg, 'st': st,
            'vd': ('edge' if colour else ('none' if lv == 'edge' else lv)) if d else None,
            'ik': o[0], 'in': o[1], 'ici': list(wilson(o[0], o[1])) if d and o[1] else None,
            'rs': rs, 'N': N, 'ek': ek if colour else [],
            'lt': [k for k, _ in TD_CR_IN if k in V and _isnum(V[k][0]) and not V[k][3]]}


# v125: dziennik (data/krypto-dziennik.json) — karty tak, jak były na stronie, zanim zaczęło się ich okno pomiaru

def _td_vstr(row):
    """Karta → kod głosów, np. 'p0t-e-s0h0' ('+'/'-' głos, '0' spokój, '.' bez z, brak albo po czasie; brak klucza = nie dotyczy)."""
    lt = set(row.get('lt') or [])
    return ''.join(k + ('.' if z is None or k in lt else '+' if g > 0 else '-' if g < 0 else '0') for k, _, z, g in row.get('rs') or [])


def _td_vparse(vs):
    """Kod głosów → {wejście: głos} (+1, −1 albo 0)."""
    out = {}
    for i in range(0, len(vs or '') - 1, 2):
        out[vs[i]] = {'+': 1, '-': -1}.get(vs[i + 1], 0)
    return out


def _td_cr_pairs(log, since=None, upto=None):
    """Dziennik → (linie {reguła: [(doba, trafienie, moneta, głos)]}, ys {moneta: {doba: y}}) z wierszy since ≤ D (≤ upto, gdy podane)
    ze znanym wynikiem; para wymaga y ≠ 0. Te same kształty co linie w próbie, więc jedna funkcja (_td_stat) ocenia jedne i drugie."""
    since = since or TD_SINCE_CR2
    acc = {k: [] for _, k in TD_RULES_CR2}; ys = {}
    for r in (log or {}).get('rows') or []:
        if not (isinstance(r, list) and len(r) == 7):
            continue
        d, sym, N, st, vs, at, y = r
        if not isinstance(d, str) or d < since or (upto and d > upto) or not _isnum(y):
            continue
        ys.setdefault(sym, {})[d] = y
        if y == 0:
            continue
        for k, g in _td_vparse(vs).items():
            if g and k in acc:
                acc[k].append((d, 1 if (y > 0) == (g > 0) else 0, sym, g))
        if isinstance(N, int) and not isinstance(N, bool) and N:
            g = 1 if N > 0 else -1; h = 1 if (y > 0) == (g > 0) else 0
            acc['all'].append((d, h, sym, g))
            if abs(N) >= 2:
                acc['n2'].append((d, h, sym, g))
    return acc, ys


def _td_cr_cp(log, today, iso):
    """Punkty kontrolne oceny dziennika: dla każdej linii i każdego c z TD_CR_LOOKS, którego jeszcze nie ma, gdy linia ma c dób z sygnałem
    wśród wierszy „dojrzałych” (doba ≤ today − TD_CR_SETTLE): test jej pierwszych c dób sygnału przy z = TD_CR_ZL wobec zwykłej doby samego
    dziennika. Zapis raz: [c, k, n, b0, h1, h2, lo, hi, vd, doba c-tego sygnału, czas wyliczenia] — nigdy liczony od nowa."""
    cp = {k: [list(x) for x in v if isinstance(x, list) and len(x) == 11] for k, v in ((log or {}).get('cp') or {}).items()}
    upto = (today - datetime.timedelta(days=TD_CR_SETTLE)).isoformat()
    L, Y = _td_cr_pairs(log, (log or {}).get('since'), upto)
    for _, rule in TD_RULES_CR2:
        pr = sorted(L[rule]); ds = sorted({p[0] for p in pr}); have = {x[0] for x in cp.get(rule, [])}
        for c in TD_CR_LOOKS:
            if c in have or len(ds) < c:
                continue
            S = _td_stat([p for p in pr if p[0] <= ds[c - 1]], Y, TD_CR_ZL)
            cp.setdefault(rule, []).append([c, S['k'], S['n'], None if S['b0'] is None else round(S['b0'], 1), S['h1'], S['h2'],
                                            S['ca'][0], S['ca'][1], S['vd'], ds[c - 1], iso])
    return {k: sorted(v) for k, v in cp.items() if v}


TD_PG_EST_N = 10   # v208: szacunek terminu oceny linii dopiero od tylu dojrzałych dni z sygnałem
TD_PG_EST_D = 14   # v208: … i od tylu dni kalendarzowych dziennika (od since do granicy dni dojrzałych)


def _td_pg(lines, lines_all, names, looks, cp, since, today, settle):
    """v208: postęp nauki do punktów kontrolnych (strona: „X z 100 dni z sygnałem do pierwszej oceny”) → {'do': granica dni dojrzałych (ISO),
    'l': {nazwa: [n, c, est]}}: n — dni z sygnałem linii ze znanym wynikiem (wszystkie, także młodsze niż `settle` — jak pierścień „od startu”),
    c — najmniejszy punkt kontrolny z `looks` bez zapisanej oceny w cp (None = wszystkie zapisane), est — szacowana data (ISO) oceny c: tempo
    z dni DOJRZAŁYCH (doba ≤ today − settle; te same pary co punkty kontrolne) na dni kalendarzowe od since do granicy, plus settle dni
    dojrzewania — dopiero od TD_PG_EST_N dni dojrzałych i TD_PG_EST_D dni dziennika, inaczej None. `lines` / `lines_all` — {klucz: [(doba, …)]}
    z funkcji par dziennika (z granicą / bez); `names` — [(klucz, nazwa w cp)]. Szacunek, nie obietnica (strona tak go podpisuje)."""
    upto = today - datetime.timedelta(days=settle)
    span = (upto - _d(since)).days + 1 if since else 0
    out = {}
    for key, name in names:
        nm = len({p[0] for p in (lines or {}).get(key) or []})
        n = max(nm, len({p[0] for p in (lines_all or {}).get(key) or []}))
        have = {x[0] for x in ((cp or {}).get(name) or []) if isinstance(x, list) and x}
        c = next((x for x in looks if x not in have), None)
        est = None
        if c is not None and nm >= TD_PG_EST_N and span >= TD_PG_EST_D:
            est = (upto + datetime.timedelta(days=math.ceil(max(0, c - nm) * span / nm) + settle)).isoformat()
        out[name] = [n, c, est, nm]   # v211: + dni dojrzałe (punkt kontrolny liczy tylko je — strona: „ocena w ciągu kilku dni”, gdy n ≥ c)
    return {'do': upto.isoformat(), 'l': out}


def _td_sh_glos(V, N, r):
    """v216: głos kandydata z głosów wiersza: para składników (oba ≠ 0 i zgodne → ich znak) albo próg |N| ≥ r (→ znak N); inaczej 0."""
    if isinstance(r, tuple):
        a, b = V.get(r[0]), V.get(r[1])
        return a if a and b and a == b else 0
    return (1 if N > 0 else -1) if isinstance(N, int) and not isinstance(N, bool) and abs(N) >= r else 0


def _td_sh_pairs_cr(log, since=None, upto=None):
    """v216: dziennik krypto → {kandydat: [(doba, trafienie, moneta, głos)]} (TD_SH_CR); te same wiersze co _td_cr_pairs (since ≤ D ≤ upto,
    znany wynik y ≠ 0)."""
    since = since or TD_SINCE_CR2
    acc = {k: [] for k, _ in TD_SH_CR}
    for r in (log or {}).get('rows') or []:
        if not (isinstance(r, list) and len(r) == 7):
            continue
        d, sym, N, st, vs, at, y = r
        if not isinstance(d, str) or d < since or (upto and d > upto) or not _isnum(y) or y == 0:
            continue
        V = _td_vparse(vs)
        for k, reg in TD_SH_CR:
            g = _td_sh_glos(V, N, reg)
            if g:
                acc[k].append((d, 1 if (y > 0) == (g > 0) else 0, sym, g))
    return acc


def _td_sh_cp_cr(log, today, iso):
    """v216: punkty kontrolne kandydatów krypto — jak _td_cr_cp (te same dni dojrzałe, b0 z dziennika), ale z = TD_CR_ZLS; zapis raz:
    [c, k, n, b0, h1, h2, lo, hi, vd, doba c-tego sygnału, czas wyliczenia]."""
    cp = {k: [list(x) for x in v if isinstance(x, list) and len(x) == 11] for k, v in ((log or {}).get('cs') or {}).items()}
    upto = (today - datetime.timedelta(days=TD_CR_SETTLE)).isoformat()
    L = _td_sh_pairs_cr(log, (log or {}).get('since'), upto)
    _, Y = _td_cr_pairs(log, (log or {}).get('since'), upto)
    for k, _ in TD_SH_CR:
        pr = sorted(L[k]); ds = sorted({p[0] for p in pr}); have = {x[0] for x in cp.get(k, [])}
        for c in TD_CR_LOOKS:
            if c in have or len(ds) < c:
                continue
            S = _td_stat([p for p in pr if p[0] <= ds[c - 1]], Y, TD_CR_ZLS)
            cp.setdefault(k, []).append([c, S['k'], S['n'], None if S['b0'] is None else round(S['b0'], 1), S['h1'], S['h2'],
                                         S['ca'][0], S['ca'][1], S['vd'], ds[c - 1], iso])
    return {k: sorted(v) for k, v in cp.items() if v}


def _td_cr_valid(log):
    """Czy to dziennik: słownik z listą rows oraz polami v i since (pusty obiekt albo inny plik — nie)."""
    return isinstance(log, dict) and isinstance(log.get('rows'), list) and 'v' in log and 'since' in log


def _td_cr_log(log, rows, series, now_utc):
    """Aktualizacja dziennika: karta doby danych D zapisywana raz, w pierwszym przebiegu z D+1 TD_CR_WH:00 ≤ now < D+2 TD_CR_WH:00, gdy jej
    stan należy do TD_CR_JST (karta „po czasie” nigdy); późniejsze przebiegi dopisują tylko wynik (%, 4 miejsca), gdy znane jest otwarcie
    06:00 doby D+2. Wiersze nigdy nie są usuwane (licznik nie spada). Punkty kontrolne (cp) dopisywane raz i zamrożone. Inne v/since → nowy
    dziennik, dawne sumy i punkty kontrolne w 'prev'. `log` musi być poprawnym dziennikiem albo None (o znaczeniu braku decyduje wywołujący)."""
    log = log if _td_cr_valid(log) else {}
    prev = log.get('prev')
    if log and (log.get('v') != TD_VC2 or log.get('since') != TD_SINCE_CR2):
        o, _ = _td_cr_pairs(log, log.get('since') or '0000')
        prev = {'v': log.get('v'), 'since': log.get('since'),
                'oos': {k: [sum(x[1] for x in v), len(v), len({x[0] for x in v})] for k, v in o.items()}, 'cp': log.get('cp') or {},
                **({'cs': log['cs']} if log.get('cs') else {})}   # v216: oceny kandydatów starej wersji też zostają (pole tylko, gdy są)
        log = {}
    now = now_utc.astimezone(datetime.timezone.utc)
    iso = now.replace(microsecond=0).strftime('%Y-%m-%dT%H:%M:%SZ')
    R = {(r[0], r[1]): list(r) for r in (log.get('rows') or []) if isinstance(r, list) and len(r) == 7}
    for row in rows or []:
        w0 = datetime.datetime.combine(_d(row['date']) + datetime.timedelta(days=1), datetime.time(TD_CR_WH), datetime.timezone.utc)
        key = (row['date'], row['id'])
        if key not in R and row['date'] >= TD_SINCE_CR2 and row['st'] in TD_CR_JST and w0 <= now < w0 + datetime.timedelta(days=1):
            R[key] = [row['date'], row['id'], row['N'], row['st'], _td_vstr(row), iso, None]
    by = {s['id']: s for s in series or []}
    for key, r in R.items():
        s = by.get(key[1])
        if r[6] is None and s and key[0] in s['dates']:
            y = _td_win(s, s['dates'].index(key[0]))
            r[6] = round(y, 4) if y is not None else None
    out = {'at': iso, 'v': TD_VC2, 'since': TD_SINCE_CR2, 'wh': TD_CR_WH, 'rows': [R[k] for k in sorted(R)], 'cp': {}}
    out['cp'] = _td_cr_cp(dict(out, cp=log.get('cp') or {}), now.date(), iso)
    out['pg'] = _td_pg(_td_cr_pairs(out, out['since'], (now.date() - datetime.timedelta(days=TD_CR_SETTLE)).isoformat())[0],   # v208: postęp nauki
                       _td_cr_pairs(out, out['since'])[0], [(k, k) for _, k in TD_RULES_CR2], TD_CR_LOOKS, out['cp'], out['since'], now.date(), TD_CR_SETTLE)
    out['cs'] = _td_sh_cp_cr(dict(out, cs=log.get('cs') or {}), now.date(), iso)   # v216: kandydaci „w cieniu” — oceny i postęp
    out['pgs'] = _td_pg(_td_sh_pairs_cr(out, out['since'], (now.date() - datetime.timedelta(days=TD_CR_SETTLE)).isoformat()),
                        _td_sh_pairs_cr(out, out['since']), [(k, k) for k, _ in TD_SH_CR], TD_CR_LOOKS, out['cs'], out['since'], now.date(), TD_CR_SETTLE)
    if prev:
        out['prev'] = prev
    return out


def _td_cr_from_csv(path=None):
    """Dzienna kopia dziennika w repozytorium (archiwum/krypto-dziennik.csv, zapisywana przez narzedzia/archiwum.py) → (dziennik, 'ok')
    z wierszami TEJ wersji reguły (punkty kontrolne policzy od nowa następny _td_cr_log); (None, 'none'), gdy pliku nie ma albo nie ma w nim
    żadnego wiersza tej wersji (nic nie zarchiwizowano — nowy dziennik niczego nie traci); (None, 'bad'), gdy plik jest, ale nie da się go
    odczytać (inny nagłówek, błąd odczytu albo CSV)."""
    path = path or TD_CR_CSV
    try:
        with open(path, encoding='utf-8', newline='') as f:
            rd = csv.reader(f)
            if next(rd, None) != TD_CR_CSV_COLS:
                return None, 'bad'
            raw = list(rd)
    except FileNotFoundError:
        return None, 'none'
    except (OSError, csv.Error, UnicodeDecodeError):
        return None, 'bad'
    rows = []
    for r in raw:
        if len(r) != len(TD_CR_CSV_COLS):
            continue
        d = dict(zip(TD_CR_CSV_COLS, r))
        try:
            if int(d['v'] or 0) != TD_VC2 or d['since'] != TD_SINCE_CR2 or not _d(d['date']):
                continue
            rows.append([d['date'], d['coin'], int(d['n']), d['state'], d['votes'], d['saved_at'], float(d['y']) if d['y'] != '' else None])
        except (TypeError, ValueError):
            continue
    if not rows:
        return None, 'none'
    return {'at': None, 'v': TD_VC2, 'since': TD_SINCE_CR2, 'wh': TD_CR_WH, 'rows': sorted(rows), 'cp': {}}, 'ok'


_CR_LOG = [None, None]     # v125: [poprzedni dziennik (main, przed trendami), nowy dziennik (build_daily_cr2)]


def build_daily_cr2(S):
    """v125: sygnały dzienne krypto, wersja 2 → (wiersze, linie). Wejście: S['krypto-dzien'] (plik tylko dla zbieracza). Bez pliku albo bez
    żadnej serii → (None, None). Zepsuta seria jednej monety → uwaga w meta, bez jej karty. Dziennik: _CR_LOG[0] (poprzedni) → _CR_LOG[1] (nowy);
    licznik „od wdrożenia” (lk/ln/ldays) i ocena w punktach kontrolnych (lvd/lc) wyłącznie z dziennika. Brak poprzedniego dziennika (albo zły
    plik): odtworzenie z archiwum/krypto-dziennik.csv; nowy, pusty dziennik tylko wtedy, gdy archiwum nie ma żadnego wiersza tej wersji reguły
    (po 2 dobach od TD_SINCE_CR2 — z błędem w meta); nieczytelne archiwum — licznik wstrzymany (null), nic nie jest zapisywane. Nie zmienia S.
    Zegar: _now_utc."""
    S = S if isinstance(S, dict) else {}
    kd = S.get('krypto-dzien') if isinstance(S.get('krypto-dzien'), dict) else None
    if not kd:
        return None, None
    now_utc = _now_utc(); today = now_utc.date()
    series = []
    for sym in TR_CR_SYMS:
        try:
            s = _td_series_cr2(kd, sym, today)
            if s:
                series.append(s)
        except Exception as e:
            META['notes'].append(mask(f'trendy dziennie krypto {sym}: {e}'))
    if not series:
        return None, None
    lines = {key: [] for key in TD_RULES_CR2}; own = {}; ys = {}; good = []
    for s in series:
        try:
            pr = _td_pairs_cr2(s)
            ys[s['id']] = {s['dates'][i]: y for i in range(len(s['dates'])) for y in [_td_win(s, i)] if y is not None}
        except Exception as e:
            META['notes'].append(mask(f"trendy dziennie krypto {s['id']}: {e}")); continue
        good.append(s)
        for dt, k, v, hit in pr:
            lines[('cr', k)].append((dt, hit, s['id'], v))
            if k == 'all':
                o = own.setdefault(s['id'], [0, 0]); o[0] += hit; o[1] += 1
    bd = _td_pool_cr2(lines, ys, today=today)              # pola dziennika null, dopóki dziennik nie jest znany
    vd_by = {(b['fam'], b['rule']): b['vd'] for b in bd}
    rows = []
    for s in good:
        try:
            rows.append(_td_row_cr2(s, vd_by, own, today, now_utc))
        except Exception as e:
            META['notes'].append(mask(f"trendy dziennie krypto {s['id']}: {e}"))
    if not rows:
        return None, None
    try:
        log0 = _CR_LOG[0] if _td_cr_valid(_CR_LOG[0]) else None
        if log0 is None:
            log0, why = _td_cr_from_csv()
            if why == 'bad':
                META['errors'].append('Dziennik krypto: brak poprzedniego pliku, a kopia w archiwum jest nieczytelna — licznik „od wdrożenia” '
                                      'wstrzymany, nic nie nadpisano')
                return rows, bd
            if log0 is not None:
                META['notes'].append(f"Dziennik krypto: odtworzony z archiwum ({len(log0['rows'])} wierszy do {log0['rows'][-1][0]})")
            elif today > _d(TD_SINCE_CR2) + datetime.timedelta(days=2):
                META['errors'].append('Dziennik krypto: brak poprzedniego pliku i brak jego kopii w archiwum — nowy dziennik, licznik „od wdrożenia” od zera')
        _CR_LOG[1] = _td_cr_log(log0, rows, good, now_utc)
        bd = _td_pool_cr2(lines, ys, log=_CR_LOG[1], today=today)
    except Exception as e:                                   # awaria dziennika: licznik null („—”), uwaga w meta, nic nie zapisujemy
        _CR_LOG[1] = None
        META['notes'].append(mask(f'trendy dziennie krypto, dziennik: {e}'))
    return rows, bd


# v127: sygnały dzienne świata, wersja reguły 2 (rodziny eq / bd / pm) — reguły, linie, ocena, dziennik (Zw2) i budowniczy pliku data/swiat-dzien.json (Zw4)
def _tdw_fam(sym):
    return next((f for f, ms in TD_FAM.items() if sym in ms), 'eq')


def _tdw_off(day):
    """Przesunięcie Nowego Jorku względem UTC w godzinach: −4 od 2. niedzieli marca do 1. niedzieli listopada, inaczej −5 (reguła USA od 2007).
    Bez bazy stref — zbieracz, testy i strona liczą tak samo."""
    d = _d(day) if isinstance(day, str) else day
    m2 = datetime.date(d.year, 3, 8); m2 += datetime.timedelta(days=(6 - m2.weekday()) % 7)
    n1 = datetime.date(d.year, 11, 1); n1 += datetime.timedelta(days=(6 - n1.weekday()) % 7)
    return -4 if m2 <= d < n1 else -5


def _tdw_at(day, minutes):
    """Dzień sesji + minuty po północy czasu Nowego Jorku → 'YYYY-MM-DDTHH:MM:SS' (UTC), porównywalne z iso[:19]."""
    d = _d(day)
    return (datetime.datetime(d.year, d.month, d.day) + datetime.timedelta(minutes=minutes, hours=-_tdw_off(d))).strftime('%Y-%m-%dT%H:%M:%S')


def _tdw_cut(s):
    return _tdw_at(s, TD_W_CUT)


def _tdw_end(s):
    return _tdw_at(s, TD_W_END_HALF if s in TD_NYSE_HALF else TD_W_END)


def _tdw_early(iso, s):
    """True, gdy czas `iso` (UTC, ≥ 19 znaków) jest przed granicą sesji s; None/'' → False."""
    return isinstance(iso, str) and len(iso) >= 19 and iso[:19] < _tdw_cut(s)


def _tdw_next(day):
    """Następna sesja NYSE po dniu `day`: pon–pt bez dni z TD_NYSE_CLOSED (po TD_NYSE_LAST — sam pon–pt)."""
    d = _d(day) + datetime.timedelta(days=1)
    while d.weekday() >= 5 or d.isoformat() in TD_NYSE_CLOSED:
        d += datetime.timedelta(days=1)
    return d.isoformat()


def _tdw_mv(a, b):
    """Ruch zamknięcie→zamknięcie (b / a − 1)·100; brak liczby, ≤ 0 albo iloraz w 2% od podziału jednostek (TD_W_SPLIT) → None."""
    if not (_isnum(a) and _isnum(b)) or a <= 0 or b <= 0:
        return None
    q = b / a
    if any(abs(q / k - 1) < 0.02 or abs(q * k - 1) < 0.02 for k in TD_W_SPLIT):
        return None
    return (q - 1) * 100


def _tdw_oc(o, c):
    """Wynik sesji otwarcie→zamknięcie (%); brak, ≤ 0 albo iloraz poza TD_W_YR → None."""
    if not (_isnum(o) and _isnum(c)) or o <= 0 or c <= 0:
        return None
    q = c / o
    return (q - 1) * 100 if TD_W_YR[0] < q < TD_W_YR[1] else None


def _tdw_seen(r, k):
    x = r[k] if isinstance(r, list) and len(r) > k else None
    return x if isinstance(x, str) and len(x) >= 19 else None


def _tdw_series(wd, sym):
    """ETF → seria na osi sesji docelowych T = kalendarz pliku + następna sesja (karta). Dla sesji docelowej j (dzień danych = T[j−1]):
    in.p[j] = ruch zamknięcie→zamknięcie sesji T[j−1]; in.f[j] = przepływ funduszu z wiersza z datą T[j−1]; in.o[j] = zagraniczni (TD_W_OB,
    z liczony na osi lokalnej); y[j] = otwarcie→zamknięcie sesji T[j] (None dla karty). on[k][j] = wiersz zapisany przed granicą sesji T[j]
    (wiersz bez czasu zapisu = seria wstępna, na czas). cl[j] = zamknięcie dnia danych zapisane po granicy (karta „late”: na stronie tylko opis,
    w dzienniku brak) — ta sesja nie daje par także w próbie. `late` = to samo dla karty, surowo (nieznany czas najnowszego zamknięcia = po
    czasie); `nopx` = brak zamknięcia dnia danych (od granicy karta też „late” — v127, przegląd); `pend` = wejścia jeszcze oczekiwane.
    `dz` (v127, przegląd 2: próba ⊆ dziennik) = sesja bez par, bo wejście z głosem w rodzinie miało w chwili granicy T[j] inną wartość albo
    inne z niż w pliku końcowym, choć jego własny wiersz dnia danych był na czas: wiersz w oknie z tego wejścia albo poprzedni wiersz pary
    przepływu zapisany od granicy T[j] — karta dziennika mogła wtedy mieć głos, którego próba nie ma (albo odwrotnie), a z nim inną sumę N
    („każda karta”); próba nie dodaje par, których dziennik nigdy nie miał.
    Brak = None, nigdy 0. Daty kalendarza muszą rosnąć (ValueError)."""
    cal = [c for c in (wd.get('cal') or []) if isinstance(c, str) and _d(c)]
    if len(cal) < 2:
        return None
    if any(a >= b for a, b in zip(cal, cal[1:])):
        raise ValueError('kalendarz sesji nie rośnie')
    px = ((wd.get('px') or {}).get(sym) or {})
    by = {str(r[0])[:10]: r for r in (px.get('d') or []) if isinstance(r, list) and len(r) >= 3}
    if not by:
        return None
    n = len(cal); nxt = _tdw_next(cal[-1]); T = cal + [nxt]
    o = [by[d][1] if d in by and _isnum(by[d][1]) and by[d][1] > 0 else None for d in cal]
    c = [by[d][2] if d in by and _isnum(by[d][2]) and by[d][2] > 0 else None for d in cal]
    ps = [_tdw_seen(by.get(d), 3) for d in cal]
    mv = [None] + [_tdw_mv(c[i - 1], c[i]) for i in range(1, n)]             # ruch sesji i
    y = [_tdw_oc(o[i], c[i]) for i in range(n)] + [None]                     # wynik sesji docelowej j
    fam = _tdw_fam(sym)
    inp = {'p': [None] + mv}
    ok = lambda x, s: x is None or _tdw_early(x, s)                          # noqa: E731 — wiersz bez czasu zapisu (historia) = na czas
    onc = [True] + [ok(ps[i], T[i + 1]) for i in range(n)]                   # zamknięcie dnia danych T[j−1] zapisane przed granicą T[j]
    newest = by.get(cal[-1])
    late = bool(newest) and c[-1] is not None and not _tdw_early(ps[-1], nxt)   # surowo: nieznany czas najnowszego zamknięcia = po czasie
    if late:
        onc[n] = False
    # v127 (przegląd): ruch ceny T[j−1] to dwa zamknięcia — głos tylko, gdy OBA były zapisane przed granicą T[j] (zamknięcie T[j−2] dopisane
    # później nie daje w próbie głosu, którego karta w chwili granicy nie miała)
    on = {'p': [onc[j] and (j < 2 or ok(ps[j - 2], T[j])) for j in range(n + 1)]}
    # zamknięcie dnia danych po granicy → sesja bez par (jak dziennik); v127 (przegląd): także BRAK tego zamknięcia w okresie zapisów na żywo
    # (od pierwszego wiersza z czasem zapisu) — w chwili granicy go nie było, karta była tylko opisem („late”), dziennik jej nie zapisał
    f0 = next((cal[i] for i in range(n) if ps[i]), None)
    cl = [not onc[j] or (j >= 1 and f0 is not None and cal[j - 1] >= f0 and c[j - 1] is None) for j in range(n + 1)]
    # v127 (przegląd 2): próba ⊆ dziennik — dz[j] = sesja j bez par (opis w docstringu); tylko wejścia z głosem w rodzinie karty
    dz = [False] * (n + 1)
    allowed = TD_W_VOTE.get(fam, ())

    def k_on(x):
        """Najmniejsze j, dla którego wiersz zapisany o x był przed granicą T[j] (granica = 09:00 NY dnia T[j], ten sam dzień w UTC); dla
        mniejszych j wiersz był „po czasie”. Wiersz bez czasu zapisu (historia) → 0."""
        if not x:
            return 0
        k = bisect.bisect_left(T, x[:10])
        if k < len(T) and T[k] == x[:10]:
            hm = x[11:19]                                                   # granica 13:00 UTC (EDT) albo 14:00 UTC (EST)
            if hm >= '14:00:00' or (hm >= '13:00:00' and not _tdw_early(x, T[k])):
                k += 1
        return k
    # (p) z ruchu ceny = najwyżej TD_LB poprzednich ruchów; zamknięcie z tego okna zapisane od granicy T[j] → w chwili granicy ruchów obok
    # niego nie było (inne z). Spóźnione zamknięcie T[j−2] (poprzednie wartości) → brak wartości i w chwili granicy, i w próbie (on['p']
    # fałsz, bez głosu w obu) — sesja zostaje; zamknięcie T[j−1] po granicy → cl.
    if 'p' in allowed:
        for i in range(n):
            if c[i] is None or not ps[i]:
                continue
            for j in range(i + 2, min(i + TD_LB + 2, k_on(ps[i]) - 1, n) + 1):
                if on['p'][j] and inp['p'][j] is not None:
                    dz[j] = True
    pend = []
    zo = None
    if sym in TD_GRP:
        rows = [r for r in (((wd.get('fl') or {}).get(sym) or {}).get('d') or []) if isinstance(r, list) and len(r) >= 3]
        fl = fund_flows([[r[0], r[1], r[2]] for r in rows])
        fs = {r[0]: _tdw_seen(r, 3) for r in rows}
        kept = [r[0] for r in _fund_rows([[r[0], r[1], r[2]] for r in rows])]
        fpv = dict(zip(kept[1:], kept))                                       # dzień → poprzedni wiersz tej samej pary przepływu (jak fund_flows)
        inp['f'] = [None] + [fl.get(d) for d in cal]
        # v127 (przegląd): przepływ to para wierszy wydawcy — głos tylko, gdy OBA były zapisane przed granicą (dopisany później poprzedni
        # wiersz zmienia przepływ, którego karta w chwili granicy nie widziała)
        on['f'] = [True] + [ok(fs.get(d), T[j + 1]) and ok(fs.get(fpv.get(d)), T[j + 1]) for j, d in enumerate(cal)]
        # v127 (przegląd 2): wiersz wydawcy zapisany od granicy T[j] zmienia przepływ swojego dnia i przepływ następnego wiersza (jego
        # poprzednika) — w chwili granicy ten przepływ liczono od starszego wiersza. Gdy taki przepływ jest wartością sesji j (spóźniony
        # poprzedni wiersz pary, choć wiersz dnia danych był na czas) albo leży w jej oknie z → dz[j]. Spóźniony sam wiersz dnia danych →
        # brak wartości w obu (on['f'] fałsz) — sesja zostaje.
        if 'f' in allowed:
            ks = sorted({d for d in kept if isinstance(d, str)})
            for r in rows:
                x = _tdw_seen(r, 3)
                if not x or not isinstance(r[0], str):
                    continue
                kl = k_on(x); q_lo = bisect.bisect_left(cal, r[0]); b = bisect.bisect_right(ks, r[0])
                q_hi = bisect.bisect_right(cal, ks[b] if b < len(ks) else r[0]) - 1
                for j in range(q_lo + 1, min(q_hi + TD_LB + 1, kl - 1, n) + 1):
                    d = cal[j - 1]
                    if d in fs and ok(fs[d], T[j]):
                        dz[j] = True
        if max((r[0] for r in rows), default='') < cal[-1]:
            pend.append('f')
    if sym in TD_W_OB:
        part, lag = TD_W_OB[sym]
        P = (wd.get('ob') or {}).get(part) or {}
        prt = {'d': [[r[0], r[1]] for r in (P.get('d') or []) if isinstance(r, list) and len(r) >= 2], 'empty': P.get('empty') or []}
        cols = (_tr_sessions if part in ('tw', 'hk') else _tr_cols)(prt, 1)
        ld, lv = cols[0], cols[1]
        ls = {str(r[0])[:10]: _tdw_seen(r, 2) for r in (P.get('d') or []) if isinstance(r, list)}
        vo = [None] * (n + 1); zo = [None] * (n + 1); oo = [True] * (n + 1); src = [None] * (n + 1); srci = [None] * (n + 1)
        for i, L in enumerate(ld):                                            # daty lokalne rosną: najnowszy dzień L danej sesji wygrywa …
            j = bisect.bisect_left(T, L) if lag == 0 else bisect.bisect_right(T, L)
            if j > n:
                continue
            # … v127 (przegląd): chyba że był znany dopiero od granicy T[j] (wiersz zapisany po niej albo luka widoczna dopiero z wierszem
            # zapisanym po niej) — wtedy starszy wiersz na czas zostaje, jak na karcie w chwili granicy (np. Tajwan w Święto Dziękczynienia)
            if src[j] is not None and vo[j] is not None and oo[j]:
                kn = ls.get(L) if L in ls else next((ls.get(x) for x in ld[i + 1:] if x in ls), None)
                if kn is not None and not _tdw_early(kn, T[j]):
                    continue
            src[j] = L; srci[j] = i
            if lv[i] is None:
                vo[j] = zo[j] = None; oo[j] = True; continue
            vo[j] = lv[i]; zo[j] = _td_z(lv, i); sn = ls.get(L)
            oo[j] = sn is None or _tdw_early(sn, T[j])
        inp['o'] = vo; on['o'] = oo
        # v127 (przegląd 2): z zagranicznych = najwyżej TD_LB poprzednich wierszy na osi lokalnej; wiersz z tego okna zapisany od granicy
        # T[j] → w chwili granicy okno było inne (inne z) → dz[j]. Spóźniony sam wiersz wartości → brak głosu w obu (on['o'] fałsz).
        if 'o' in allowed:
            js = [j for j in range(n + 1) if srci[j] is not None]; iv = [srci[j] for j in js]   # rosną razem (nowszy dzień lokalny → późniejsza sesja)
            for x, L in enumerate(ld):
                kx = k_on(ls.get(L))
                for q in range(bisect.bisect_right(iv, x), bisect.bisect_right(iv, x + TD_LB)):   # sesje, w których oknie z jest wiersz x
                    j = js[q]
                    if j >= kx:
                        break
                    if oo[j] and vo[j] is not None:
                        dz[j] = True
        exp = nxt if lag == 0 else cal[-1]                                     # dzień lokalny, na który karta jeszcze czeka
        empty = set(prt['empty'])
        if src[n] is None and exp not in empty and (not ld or ld[-1] < exp):
            pend.append('o')
    iss = (((wd.get('fl') or {}).get(sym) or {}).get('iss'))
    return {'id': sym, 'sym': sym, 'fam': fam, 'iss': iss if iss in ('ssga', 'ishares') else None, 'dates': T, 'cal': cal, 'y': y,
            'in': inp, 'zo': zo, 'on': on, 'cl': cl, 'dz': dz, 'late': late, 'nopx': c[-1] is None, 'pend': pend, 'close': c}


def _tdw_votes(s, j):
    """→ ({k: (wartość, z, głos, na_czas)}, N). Głos = kierunek·znak(z) przy |z| ≥ TD_Z1, na czas i tylko dla wejść z głosem w rodzinie."""
    out, N = {}, 0
    allowed = TD_W_VOTE.get(s['fam'], ())
    for k, dr in TD_W_IN:
        vals = s['in'].get(k)
        if vals is None:
            continue
        z = s['zo'][j] if k == 'o' else _td_z(vals, j, demean=(k != 'p'))
        on = s['on'][k][j]
        v = dr * (1 if z > 0 else -1) if (k in allowed and z is not None and abs(z) >= TD_Z1 and on) else 0
        out[k] = (vals[j] if 0 <= j < len(vals) else None, z, v, on)
        N += v
    return out, N


def _tdw_pairs(s, votes=None):
    """→ [(sesja, (rodzina, wejście) | ('w', 'all'), głos, trafienie)]; wynik None albo 0 → bez pary; sprzeczna karta → tylko pary wejść;
    sesja, której zamknięcie dnia danych zapisano po granicy (cl), nie daje par — jak karta „late”, której dziennik nie zapisuje; v127
    (przegląd 2): także sesja, w której wejście z głosem miało w chwili granicy inną wartość albo inne z (dz) — próba ⊆ dziennik."""
    out = []
    cl = s.get('cl') or []; dz = s.get('dz') or []
    for j in range(len(s['dates'])):
        if (j < len(cl) and cl[j]) or (j < len(dz) and dz[j]):
            continue
        V, N = votes[j] if votes is not None else _tdw_votes(s, j)
        if not any(x[2] for x in V.values()):
            continue
        y = s['y'][j]
        if y is None or y == 0:
            continue
        d = s['dates'][j]
        for k, x in V.items():
            if x[2]:
                out.append((d, (s['fam'], k), x[2], 1 if (y > 0) == (x[2] > 0) else 0))
        if N:
            g = 1 if N > 0 else -1
            out.append((d, ('w', 'all'), g, 1 if (y > 0) == (g > 0) else 0))
    return out


def _tdw_pct(hs):
    return round(100 * sum(hs) / len(hs), 1) if hs else None


def _tdw_neff(pr):
    """Liczba niezależnych obserwacji linii = min(sesje z sygnałem, n_eff grup sesji), gdzie n_eff grup = p(1−p)·n² / [D/(D−1)·Σ_d (k_d − p·n_d)²]
    (wariancja ilorazu z grupowaniem po sesji — pary tej samej sesji są zależne). Pusta linia → 0; jedna sesja albo zerowa wariancja → sesje."""
    by = {}
    for p in pr:
        a = by.setdefault(p[0], [0, 0]); a[0] += p[1]; a[1] += 1
    D = len(by); n = len(pr)
    if D < 2:
        return float(D)
    k = sum(a[0] for a in by.values()); ph = k / n
    ss = sum((a[0] - ph * a[1]) ** 2 for a in by.values()) * D / (D - 1)
    if ss <= 0 or ph <= 0 or ph >= 1:
        return float(D)
    return min(float(D), ph * (1 - ph) * n * n / ss)


def _tdw_wil(k, n, z, ne=None):
    """Zakres Wilsona w % BEZ zaokrąglenia — wyłącznie do werdyktu (publikowane liczby: produkcyjny wilson, do 0,1)."""
    if not n:
        return None, None
    p = k / n; m = ne or n; den = 1 + z * z / m
    c = (p + z * z / (2 * m)) / den; h = z * ((p * (1 - p) / m + z * z / (4 * m * m)) ** 0.5) / den
    return 100 * (c - h), 100 * (c + h)


def _tdw_vd(k, n, days, ne, h1, h2, bm, bn, z=None):
    """short / edge / anti / none: zakres Wilsona przy z (TD_W_ZM w próbie, TD_W_ZL w punkcie kontrolnym) i n_eff = ne, wobec bm/bn
    (zwykła sesja); obie połowy po tej samej stronie progu. Wszystko na liczbach niezaokrąglonych (h1, h2 w % bez zaokrąglenia)."""
    if days < TD_NEFF or not n:
        return 'short'
    la, ha = _tdw_wil(k, n, z or TD_W_ZM, ne)
    if la > bm and h1 is not None and h1 > bm and h2 is not None and h2 > bm:
        return 'edge'
    if ha < bn and h1 is not None and h1 < bn and h2 is not None and h2 < bn:
        return 'anti'
    return 'none'


def _tdw_ut(series):
    """b0t: udział sesji wzrostowych rynku (y ≠ 0) w TD_W_UT sesjach PRZED daną sesją, gdy jest ich co najmniej TD_W_UTMIN → {rynek: {sesja: u}}
    (w chwili pary — bez zaglądania w przyszłość); mniej → brak wpisu (b0t bierze wtedy udział z całego okresu linii)."""
    out = {}
    for s in series or []:
        up = [0]; nz = [0]
        for v in s['y']:
            up.append(up[-1] + (1 if v is not None and v > 0 else 0)); nz.append(nz[-1] + (1 if v else 0))
        m = {}
        for j, d in enumerate(s['dates']):
            a = max(0, j - TD_W_UT); cnt = nz[j] - nz[a]
            if cnt >= TD_W_UTMIN:
                m[d] = (up[j] - up[a]) / cnt
        out[s['id']] = m
    return out


def _tdw_b0(pr, u, ut=None):
    """Zwykła sesja par [(sesja, trafienie, rynek, głos)] w %: (b0 — udział rynku z całego okresu linii u, b0t — z 250 sesji przed parą ut)."""
    if not pr:
        return None, None
    a = b = 0.0
    for d, h, m, g in pr:
        um = u.get(m, 0.5); tm = ((ut or {}).get(m) or {}).get(d, um)
        a += um if g > 0 else 1 - um; b += tm if g > 0 else 1 - tm
    return 100 * a / len(pr), 100 * b / len(pr)


def _tdw_stat(pr, ys, z=None, ut=None):
    """Jedna linia (albo punkt kontrolny): pary [(sesja, trafienie, rynek, głos)], ys {rynek: {sesja: y}} → k, n, days, ne, from, to, p,
    ci (95%, ne), ca (z, ne), h1/h2 (podział w medianie sesji z sygnałem), u (udział sesji wzrostowych rynku w [from, to], y ≠ 0), b0, b0t,
    bm = max(50, b0, b0t), bn = min(50, b0, b0t), vd (liczby niezaokrąglone)."""
    z = z or TD_W_ZM
    pr = sorted(pr, key=lambda x: x[0])
    n = len(pr); k = sum(p[1] for p in pr)
    ds = sorted({p[0] for p in pr}); days = len(ds)
    ne = _tdw_neff(pr)
    mid = ds[days // 2] if days > 1 else None
    a1 = [p[1] for p in pr if mid and p[0] < mid]; a2 = [p[1] for p in pr if mid and p[0] >= mid]
    h1u = 100 * sum(a1) / len(a1) if a1 else None; h2u = 100 * sum(a2) / len(a2) if a2 else None
    u = {}
    for c in {p[2] for p in pr}:
        yy = [v for d, v in (ys.get(c) or {}).items() if ds[0] <= d <= ds[-1] and v]
        u[c] = sum(1 for v in yy if v > 0) / len(yy) if yy else 0.5
    b0, b0t = _tdw_b0(pr, u, ut)
    bm = max(50.0, b0, b0t) if n else 50.0
    bn = min(50.0, b0, b0t) if n else 50.0
    lo, hi = wilson(k, n, n_eff=ne) if n else (None, None)
    la, ha = wilson(k, n, z=z, n_eff=ne) if n else (None, None)
    return {'k': k, 'n': n, 'days': days, 'ne': ne, 'from': ds[0] if ds else None, 'to': ds[-1] if ds else None,
            'p': _tdw_pct([p[1] for p in pr]), 'ci': [lo, hi], 'ca': [la, ha], 'h1': _tdw_pct(a1), 'h2': _tdw_pct(a2), 'u': u,
            'b0': b0, 'b0t': b0t, 'bm': bm, 'bn': bn, 'vd': _tdw_vd(k, n, days, ne, h1u, h2u, bm, bn, z)}


def _tdw_ok(q, u, ut=None):
    """Brama koloru (może tylko odebrać kolor): pary linii po stronie karty (dla linii „każda karta” — w rodzinie karty) trafiały częściej
    niż max(50, zwykła sesja tych par) — na liczbach niezaokrąglonych."""
    if not q:
        return False
    b0, b0t = _tdw_b0(q, u, ut)
    return 100 * sum(p[1] for p in q) / len(q) > max(50.0, b0, b0t)


def _tdw_side(q, u, ut=None, ci=True):
    """Opis podzbioru par (strona, rodzina): k, n, sesje, %, zwykła sesja (b0, b0t), zakres 95% (n_eff) — sam opis, bez oceny."""
    n = len(q); k = sum(p[1] for p in q)
    b0, b0t = _tdw_b0(q, u, ut)
    out = {'k': k, 'n': n, 'days': len({p[0] for p in q}), 'p': _tdw_pct([p[1] for p in q]),
           'b0': None if b0 is None else round(b0, 1), 'b0t': None if b0t is None else round(b0t, 1)}
    if ci:
        lo, hi = wilson(k, n, n_eff=_tdw_neff(q)) if n else (None, None)
        out['ci'] = [lo, hi]
    return out


def _tdw_y1(pr, today):
    lo = (today - datetime.timedelta(days=TD_W_Y1)).isoformat()
    q = [p for p in pr if p[0] >= lo]
    n = len(q); k = sum(p[1] for p in q); ds = sorted({p[0] for p in q})
    a, b = wilson(k, n, n_eff=_tdw_neff(q)) if n else (None, None)
    return {'k': k, 'n': n, 'days': len(ds), 'p': _tdw_pct([p[1] for p in q]), 'ci': [a, b], 'from': ds[0] if ds else None,
            'to': ds[-1] if ds else None}


def _tdw_prevs(log):
    """Poprzednie wersje reguły w dzienniku (lista, najstarsza pierwsza; dawny zapis jednego słownika też)."""
    p = (log or {}).get('prev') if isinstance(log, dict) else None
    p = [p] if isinstance(p, dict) else p if isinstance(p, list) else []
    return [x for x in p if isinstance(x, dict)]


def _tdw_cpl(v):
    return sorted(x for x in (v or []) if isinstance(x, list) and len(x) == 13)


def _tdw_pool(lines, ys, since=None, log=None, today=None, ut=None, gates=None):
    """7 linii (TD_RULES_W2, zawsze wszystkie). lines: {(rodzina, wejście): [(sesja, trafienie, rynek, głos)]}; log: dziennik (None = nieznany
    w tym przebiegu → lk/ln/ldays null, lvd 'wait'). Ocena „od wdrożenia” wyłącznie w punktach kontrolnych dziennika (cp). gates (słownik) →
    wypełniany bramą koloru {(rodzina, reguła): {(rodzina rynku, strona): bool}}."""
    since = since or TD_SINCE_W2
    today = today or _now_utc().date()
    JL, _ = _tdw_jpairs(log, since) if isinstance(log, dict) else (None, None)
    prevs = _tdw_prevs(log)
    fm = {}
    out = []
    for fam, rule in TD_RULES_W2:
        pr = sorted((lines or {}).get((fam, rule)) or [], key=lambda x: x[0])
        S = _tdw_stat(pr, ys, ut=ut)
        days, bm, ne = S['days'], S['bm'], S['ne']
        sq = math.sqrt(bm / 100 * (1 - bm / 100) / ne) if ne else None
        sub = {}
        for fc in (('eq', 'bd', 'pm') if fam == 'w' else (fam,)):
            for g in (1, -1):
                sub[(fc, g)] = [p for p in pr if p[3] == g and (fam != 'w' or fm.setdefault(p[2], _tdw_fam(p[2])) == fc)]
                if gates is not None:
                    gates.setdefault((fam, rule), {})[(fc, g)] = _tdw_ok(sub[(fc, g)], S['u'], ut)
        L = sorted(JL[(fam, rule)]) if JL is not None else None
        cps = _tdw_cpl(((log or {}).get('cp') or {}).get(fam + '.' + rule)) if JL is not None else []
        lc = None
        if cps:
            c = cps[-1]
            lc = {'c': c[0], 'k': c[1], 'n': c[2], 'p': round(100 * c[1] / c[2], 1) if c[2] else None, 'b0': c[3], 'b0t': c[11],
                  'ca': [c[6], c[7]], 'vd': c[8], 'to': c[9], 'thr': c[12]}
        nx = [c for c in TD_W_LOOKS if not lc or c > lc['c']]
        pv = []
        for P in prevs:
            o = ((P.get('oos') or {}).get(fam + '.' + rule)) or [0, 0, 0]
            pc = _tdw_cpl((P.get('cp') or {}).get(fam + '.' + rule))
            pv.append({'v': P.get('v'), 'since': P.get('since'), 'k': o[0], 'n': o[1], 'days': o[2],
                       'c': pc[-1][0] if pc else None, 'vd': pc[-1][8] if pc else None})
        line = {'fam': fam, 'rule': rule, 'k': S['k'], 'n': S['n'], 'days': days, 'ne': round(ne, 1), 'from': S['from'], 'to': S['to'],
                'p': S['p'], 'ci': S['ci'], 'ca': S['ca'], 'cl': TD_W_CL, 'M': TD_W_M,
                'b0': None if S['b0'] is None else round(S['b0'], 1), 'b0t': None if S['b0t'] is None else round(S['b0t'], 1),
                'thr': round(bm + 100 * TD_W_ZM * sq, 1) if ne else None,
                'mde': round(bm + 100 * (TD_W_ZM + TD_W_ZP) * sq, 1) if ne else None,
                'h1': S['h1'], 'h2': S['h2'],
                'sb': _tdw_side([p for p in pr if p[3] == 1], S['u'], ut), 'ss': _tdw_side([p for p in pr if p[3] == -1], S['u'], ut),
                'y1': _tdw_y1(pr, today),
                'lk': sum(x[1] for x in L) if L is not None else None, 'ln': len(L) if L is not None else None,
                'ldays': len({x[0] for x in L}) if L is not None else None,
                'lvd': lc['vd'] if lc else 'wait', 'lc': lc, 'lnx': nx[0] if nx else None, 'cll': TD_W_CLL,
                'lthr': round(bm + 100 * TD_W_ZL * math.sqrt(bm / 100 * (1 - bm / 100) / nx[0]), 1) if nx else None,
                'm': len({p[2] for p in pr}), 'need': max(0, TD_NEFF - days), 'vd': S['vd'], 'v': TD_VW2, 'since': since,
                'cut': TD_W_CUT, 'ws': TD_W_OPEN, 'we': TD_W_CLOSE, 'win': 'oc', 'pv': pv}
        if fam == 'w':
            line['sf'] = {fc: {'b': _tdw_side(sub[(fc, 1)], S['u'], ut, ci=False), 's': _tdw_side(sub[(fc, -1)], S['u'], ut, ci=False)}
                          for fc in ('eq', 'bd', 'pm')}
        out.append(line)
    return out


def _tdw_live(s_day, now_utc):
    """Karta sesji S aktualna do 16:15 NY (sesja skrócona 13:15); zegar bez strefy = UTC."""
    now = now_utc.astimezone(datetime.timezone.utc).replace(tzinfo=None) if getattr(now_utc, 'tzinfo', None) else now_utc
    return now.strftime('%Y-%m-%dT%H:%M:%S') < _tdw_end(s_day)


def _tdw_rz(z):
    """z do publikacji (2 miejsca) bez przeskoku progu (v127, przegląd): |z| < 1 albo < 2 nigdy nie wychodzi jako 1,00 albo 2,00 — strona
    czyta „strzela” i „mocno” z opublikowanej liczby tak samo, jak zbieracz liczy głos i siłę dnia z liczby niezaokrąglonej."""
    if not _isnum(z):
        return None
    r = round(z, 2)
    for t in (TD_Z2, TD_Z1):
        if abs(r) >= t > abs(z):
            return math.copysign(round(t - 0.01, 2), z)
    return r


def _tdw_row(s, vd_by, own, today, now_utc, gates=None, lcv=None):
    """Karta (wiersz `d`). Reguła wiersza v2: c (N ≠ 0), cx (głosy się znoszą), c0 (bez głosu) — kody nieznane stronie sprzed v127 (jak
    krypto v125, dopisek A1). Kolor: linia pokrywająca kartę (jej zgodny powód albo „każda karta”) ma przewagę w próbie ORAZ przechodzi bramę
    strony (i rodziny dla „każda karta”) ORAZ jej ostatni punkt kontrolny dziennika nie jest „anti”; żaden powód przeciw nie ma przewagi;
    „każda karta” nie jest „anti”. vx = linie z przewagą, które koloru nie dały, z powodem: sd (strona), fm (rodzina), lc (licznik),
    vs (powód przeciw z przewagą), wa („każda karta” odwrotnie)."""
    j = len(s['dates']) - 1
    S = s['dates'][j]; date = s['cal'][-1]
    V, N = _tdw_votes(s, j)
    has_now = any(_isnum(x[0]) for x in V.values())
    has_hist = any(sum(1 for x in s['in'][k][max(0, j - TD_LB):j] if _isnum(x)) >= TD_MIN for k in V)
    live = _tdw_live(S, now_utc)
    now_iso = (now_utc.astimezone(datetime.timezone.utc) if getattr(now_utc, 'tzinfo', None) else now_utc).strftime('%Y-%m-%dT%H:%M:%S')
    before = now_iso < _tdw_cut(S)
    fired = {k: x[2] for k, x in V.items() if x[2]}
    d = (1 if N > 0 else -1) if N else 0
    rule = 'c' if d else ('cx' if fired else 'c0')
    fam = s['fam']
    cand = ([k for k, g in fired.items() if g == d and vd_by.get((fam, k)) == 'edge']
            + (['all'] if vd_by.get(('w', 'all')) == 'edge' else [])) if d else []
    ek, vx = [], []
    for L in cand:
        key = ('w', 'all') if L == 'all' else (fam, L)
        if gates is not None and not (gates.get(key) or {}).get((fam, d), False):
            vx.append([L, 'fm' if L == 'all' else 'sd'])
        elif (lcv or {}).get(key) == 'anti':
            vx.append([L, 'lc'])
        else:
            ek.append(L)
    against = [k for k, g in fired.items() if g == -d and vd_by.get((fam, k)) == 'edge'] if d else []
    wa = vd_by.get(('w', 'all')) == 'anti'
    colour = bool(ek) and not against and not wa
    if ek and not colour:
        vx += [[L, 'vs' if against else 'wa'] for L in ek]
    if not has_now:
        st = 'nodata'
    elif not has_hist:
        st = 'short'
    elif not live:
        st = 'stale'
    elif s['late'] or (s.get('nopx') and not before):                    # v127 (przegląd): bez zamknięcia dnia danych w chwili granicy —
        st = 'late'                                                      # karta tylko opisem i poza dziennikiem (w próbie: cl, bez par)
    elif rule == 'cx':
        st = 'x'
    elif rule == 'c0':
        st = 'quiet'
    else:
        st = ('buy' if d > 0 else 'sell') if colour else 'obs'
    side = ('buy' if d > 0 else 'sell') if st in ('buy', 'sell', 'obs') else 'none'
    agree = [k for k, g in fired.items() if g == d] if d else []
    strong = any(V[k][1] is not None and abs(V[k][1]) >= TD_Z2 for k in agree)
    sg = min(3, len(agree) + int(strong)) if d else 0
    o = own.get(s['id'], (0, 0)) if d else (None, None)
    lv = vd_by.get(('w', 'all'))

    def rnd(x, k):
        return round(x, k) if _isnum(x) else None
    rs = [[k, rnd(V[k][0], TD_W_DIG[k]), _tdw_rz(V[k][1]), V[k][2]] for k, _ in TD_W_IN if k in V]
    fx = V.get('f', (None, None))
    return {'id': s['id'], 'fam': fam, 'grp': TD_GRP.get(s['id']), 'iss': s.get('iss'), 'pub': 0, 'sym': s['sym'], 'date': date, 'nx': S,
            'live': live, 'age': (today - _d(date)).days, 'we': TD_W_CLOSE_HALF if S in TD_NYSE_HALF else TD_W_CLOSE,
            'oc': {'tw': 'TWD', 'hk': 'HKD', 'in': 'USD'}[TD_W_OB[s['id']][0]] if s['id'] in TD_W_OB else None,
            'f': rnd(fx[0], 2), 'cur': 'USD' if 'f' in V else None, 'fu': rnd(fx[0], 2), 'zf': _tdw_rz(fx[1]),
            'r': rnd(V['p'][0], 2), 'zp': _tdw_rz(V['p'][1]),
            'rule': rule, 'dir': d, 'side': side, 'str': sg, 'st': st,
            'vd': ('edge' if colour else ('none' if lv == 'edge' else lv)) if d else None,
            'ik': o[0], 'in': o[1], 'ici': list(wilson(o[0], o[1])) if d and o[1] else None,
            'rs': rs, 'N': N, 'ek': ek if colour else [], 'vx': vx,
            'lt': [k for k, _ in TD_W_IN if k in V and _isnum(V[k][0]) and not V[k][3]],
            'pw': [k for k in s['pend'] if before and k in V and not _isnum(V[k][0])]}


# ---- dziennik (data/swiat-dziennik.json): karty takie, jakie były na granicy (09:00 NY sesji docelowej) ----

def _tdw_vstr(row):
    lt = set(row.get('lt') or [])
    return ''.join(k + ('.' if z is None or k in lt else '+' if g > 0 else '-' if g < 0 else '0') for k, _, z, g in row.get('rs') or [])


def _tdw_vparse(vs):
    out = {}
    for i in range(0, len(vs or '') - 1, 2):
        out[vs[i]] = {'+': 1, '-': -1}.get(vs[i + 1], 0)
    return out


def _tdw_jpairs(log, since=None, upto=None):
    """Dziennik → (lines {(rodzina, wejście): [(sesja, trafienie, rynek, głos)]}, ys {rynek: {sesja: y}}) z wierszy since ≤ S (≤ upto) ze
    znanym wynikiem; para wymaga y ≠ 0. Te same kształty co w próbie — jedna funkcja (_tdw_stat) ocenia oba."""
    since = since or TD_SINCE_W2
    acc = {key: [] for key in TD_RULES_W2}; ys = {}
    for r in (log or {}).get('rows') or []:
        if not (isinstance(r, list) and len(r) == 7):
            continue
        d, sym, N, st, vs, at, y = r
        if not isinstance(d, str) or d < since or (upto and d > upto) or not _isnum(y):
            continue
        ys.setdefault(sym, {})[d] = y
        if y == 0:
            continue
        fam = _tdw_fam(sym)
        for k, g in _tdw_vparse(vs).items():
            if g and (fam, k) in acc:
                acc[(fam, k)].append((d, 1 if (y > 0) == (g > 0) else 0, sym, g))
        if isinstance(N, int) and not isinstance(N, bool) and N:
            g = 1 if N > 0 else -1
            acc[('w', 'all')].append((d, 1 if (y > 0) == (g > 0) else 0, sym, g))
    return acc, ys


def _tdw_sh_pairs(log, since=None, upto=None):
    """v216: dziennik świata → {kandydat: [(sesja, trafienie, rynek, głos)]} (TD_SH_W, tylko rynki rodziny kandydata); te same wiersze co
    _tdw_jpairs."""
    since = since or TD_SINCE_W2
    acc = {k: [] for k, _, _ in TD_SH_W}
    for r in (log or {}).get('rows') or []:
        if not (isinstance(r, list) and len(r) == 7):
            continue
        d, sym, N, st, vs, at, y = r
        if not isinstance(d, str) or d < since or (upto and d > upto) or not _isnum(y) or y == 0:
            continue
        fam = _tdw_fam(sym); V = _tdw_vparse(vs)
        for k, f, reg in TD_SH_W:
            g = _td_sh_glos(V, N, reg) if fam == f else 0
            if g:
                acc[k].append((d, 1 if (y > 0) == (g > 0) else 0, sym, g))
    return acc


def _tdw_sh_cp(log, today, iso, ut=None):
    """v216: punkty kontrolne kandydatów świata — jak _tdw_cp (b0 z dziennika, b0t z 250 sesji rynku), z = TD_W_ZLS; zapis raz (13 pól)."""
    cp = {k: _tdw_cpl(v) for k, v in ((log or {}).get('cs') or {}).items()}
    upto = (today - datetime.timedelta(days=TD_W_SETTLE)).isoformat()
    L = _tdw_sh_pairs(log, (log or {}).get('since'), upto)
    _, Y = _tdw_jpairs(log, (log or {}).get('since'), upto)
    for name, _, _ in TD_SH_W:
        pr = sorted(L[name]); ds = sorted({p[0] for p in pr}); have = {x[0] for x in cp.get(name, [])}
        for c in TD_W_LOOKS:
            if c in have or len(ds) < c:
                continue
            S = _tdw_stat([p for p in pr if p[0] <= ds[c - 1]], Y, TD_W_ZLS, ut)
            bm = S['bm']; thr = round(bm + 100 * TD_W_ZLS * math.sqrt(bm / 100 * (1 - bm / 100) / S['ne']), 1) if S['ne'] else None
            cp.setdefault(name, []).append([c, S['k'], S['n'], None if S['b0'] is None else round(S['b0'], 1), S['h1'], S['h2'],
                                            S['ca'][0], S['ca'][1], S['vd'], ds[c - 1], iso,
                                            None if S['b0t'] is None else round(S['b0t'], 1), thr])
    return {k: sorted(v) for k, v in cp.items() if v}


def _tdw_cp(log, today, iso, ut=None):
    """Punkty kontrolne 100/200/400 sesji z sygnałem (wiersze ≥ TD_W_SETTLE dni): [c, k, n, b0, h1, h2, lo, hi, vd, dzień c, zapisano, b0t, próg]
    przy z = TD_W_ZL, zwykła sesja z własnych wyników dziennika (b0) i z 250 sesji rynku przed parą (b0t, ut); zapisane — nigdy przeliczane."""
    cp = {k: _tdw_cpl(v) for k, v in ((log or {}).get('cp') or {}).items()}
    upto = (today - datetime.timedelta(days=TD_W_SETTLE)).isoformat()
    L, Y = _tdw_jpairs(log, (log or {}).get('since'), upto)
    for key in TD_RULES_W2:
        name = key[0] + '.' + key[1]
        pr = sorted(L[key]); ds = sorted({p[0] for p in pr}); have = {x[0] for x in cp.get(name, [])}
        for c in TD_W_LOOKS:
            if c in have or len(ds) < c:
                continue
            S = _tdw_stat([p for p in pr if p[0] <= ds[c - 1]], Y, TD_W_ZL, ut)
            bm = S['bm']; thr = round(bm + 100 * TD_W_ZL * math.sqrt(bm / 100 * (1 - bm / 100) / S['ne']), 1) if S['ne'] else None
            cp.setdefault(name, []).append([c, S['k'], S['n'], None if S['b0'] is None else round(S['b0'], 1), S['h1'], S['h2'],
                                            S['ca'][0], S['ca'][1], S['vd'], ds[c - 1], iso,
                                            None if S['b0t'] is None else round(S['b0t'], 1), thr])
    return {k: sorted(v) for k, v in cp.items() if v}


def _tdw_lcv(log):
    """Werdykt ostatniego zapisanego punktu kontrolnego każdej linii → {(rodzina, reguła): vd} (weto koloru przy „anti”)."""
    out = {}
    for name, v in (((log or {}).get('cp') or {}) if isinstance(log, dict) else {}).items():
        v = _tdw_cpl(v)
        if v and '.' in name:
            f, r = name.split('.', 1); out[(f, r)] = v[-1][8]
    return out


def _tdw_valid(log):
    return isinstance(log, dict) and isinstance(log.get('rows'), list) and 'v' in log and 'since' in log


def _tdw_log(log, rows, series, now_utc, ut=None):
    """Karta sesji S (S ≥ TD_SINCE_W2, stan z TD_W_JST) zapisywana raz — w pierwszym przebiegu z granicą(S) ≤ teraz < końcem karty S;
    później tylko wynik (%, 4 miejsca), gdy znane są otwarcie i zamknięcie S. Wiersze nigdy nie są usuwane; punkty kontrolne raz i na zawsze.
    Inne v/since → nowy dziennik; sumy i punkty kontrolne starej wersji dopisane do listy 'prev' (nic nie ginie)."""
    log = log if _tdw_valid(log) else {}
    prevs = _tdw_prevs(log)
    if log and (log.get('v') != TD_VW2 or log.get('since') != TD_SINCE_W2):
        o, _ = _tdw_jpairs(log, log.get('since') or '0000')
        prevs = prevs + [{'v': log.get('v'), 'since': log.get('since'),
                          'oos': {k[0] + '.' + k[1]: [sum(x[1] for x in v), len(v), len({x[0] for x in v})] for k, v in o.items()},
                          'cp': log.get('cp') or {}, **({'cs': log['cs']} if log.get('cs') else {})}]   # v216: oceny kandydatów starej wersji (pole tylko, gdy są)
        log = {}
    now = now_utc.astimezone(datetime.timezone.utc)
    iso = now.replace(microsecond=0).strftime('%Y-%m-%dT%H:%M:%SZ'); n19 = iso[:19]
    R = {(r[0], r[1]): list(r) for r in (log.get('rows') or []) if isinstance(r, list) and len(r) == 7}
    for row in rows or []:
        S = row['nx']; key = (S, row['id'])
        if key not in R and S >= TD_SINCE_W2 and row['st'] in TD_W_JST and _tdw_cut(S) <= n19 < _tdw_end(S):
            R[key] = [S, row['id'], row['N'], row['st'], _tdw_vstr(row), iso, None]
    by = {s['id']: s for s in series or []}
    for key, r in R.items():
        s = by.get(key[1])
        if r[6] is None and s and key[0] in s['dates']:
            y = s['y'][s['dates'].index(key[0])]
            r[6] = round(y, 4) if y is not None else None
    out = {'at': iso, 'v': TD_VW2, 'since': TD_SINCE_W2, 'cut': TD_W_CUT, 'rows': [R[k] for k in sorted(R)], 'cp': {}}
    out['cp'] = _tdw_cp(dict(out, cp=log.get('cp') or {}), now.date(), iso, ut)
    out['pg'] = _td_pg(_tdw_jpairs(out, out['since'], (now.date() - datetime.timedelta(days=TD_W_SETTLE)).isoformat())[0],   # v208: postęp nauki
                       _tdw_jpairs(out, out['since'])[0], [(k, k[0] + '.' + k[1]) for k in TD_RULES_W2], TD_W_LOOKS, out['cp'], out['since'], now.date(), TD_W_SETTLE)
    out['cs'] = _tdw_sh_cp(dict(out, cs=log.get('cs') or {}), now.date(), iso, ut)   # v216: kandydaci „w cieniu” — oceny i postęp
    out['pgs'] = _td_pg(_tdw_sh_pairs(out, out['since'], (now.date() - datetime.timedelta(days=TD_W_SETTLE)).isoformat()),
                        _tdw_sh_pairs(out, out['since']), [(k, k) for k, _, _ in TD_SH_W], TD_W_LOOKS, out['cs'], out['since'], now.date(), TD_W_SETTLE)
    if prevs:
        out['prev'] = prevs
    return out


def _tdw_pk_read(path):
    """v127 (przegląd): plik punktów kontrolnych obok kopii dziennika (TD_W_PK) → ({(v, since): {linia: [13 pól punktu]}},
    {(v, since): {linia: [trafienia, pary, sesje]}}); brak albo nieczytelny plik → dwa puste słowniki (punkty bieżącej wersji przeliczy
    wtedy _tdw_cp, jak w krypto v125, a sumy poprzednich wersji wracają z ich wierszy)."""
    try:
        with open(path, encoding='utf-8', newline='') as f:
            rd = csv.reader(f)
            if next(rd, None) != TD_W_PK_COLS:
                return {}, {}
            raw = list(rd)
    except (OSError, csv.Error, UnicodeDecodeError):
        return {}, {}
    cps, oos = {}, {}
    num = lambda x: float(x) if x != '' else None                         # noqa: E731 — puste pole = brak, nigdy 0
    for r in raw:
        if len(r) != len(TD_W_PK_COLS):
            continue
        d = dict(zip(TD_W_PK_COLS, r))
        try:
            key = (int(d['v']), d['since'])
            if not d['since'] or '.' not in d['line']:
                continue
            if d['kind'] == 'cp':
                cps.setdefault(key, {}).setdefault(d['line'], []).append(
                    [int(d['c']), int(d['k']), int(d['n']), num(d['b0']), num(d['h1']), num(d['h2']), num(d['lo']), num(d['hi']), d['vd'],
                     d['date_c'], d['at'], num(d['b0t']), num(d['thr'])])
            elif d['kind'] == 'oos':
                oos.setdefault(key, {})[d['line']] = [int(d['k']), int(d['n']), int(d['days'])]
        except (TypeError, ValueError):
            continue
    order = {k[0] + '.' + k[1]: i for i, k in enumerate(TD_RULES_W2)}
    srt = lambda o: {n: o[n] for n in sorted(o, key=lambda x: (order.get(x, len(order)), x))}   # noqa: E731 — linie w kolejności TD_RULES_W2
    return ({k: srt({n: sorted(v, key=lambda x: x[0]) for n, v in c.items()}) for k, c in cps.items()},
            {k: srt(o) for k, o in oos.items()})


def _tdw_from_csv(path=None):
    """Kopia dziennika w archiwum → (dziennik, 'ok' | 'none' | 'bad'): wiersze bieżącej wersji (v, since) wracają do dziennika. v127 (przegląd):
    wiersze innych wersji i plik punktów kontrolnych obok (TD_W_PK: zamrożone punkty każdej wersji, sumy poprzednich wersji) odtwarzają listę
    prev (najstarsza pierwsza) i zamrożone punkty bez przeliczania — nic ze starszych wersji nie ginie; bez pliku punktów sumy poprzednich
    wersji liczymy z ich wierszy, a punkty bieżącej wersji przelicza _tdw_cp."""
    path = path or TD_W_CSV
    try:
        with open(path, encoding='utf-8', newline='') as f:
            rd = csv.reader(f)
            if next(rd, None) != TD_W_CSV_COLS:
                return None, 'bad'
            raw = list(rd)
    except FileNotFoundError:
        return None, 'none'
    except (OSError, csv.Error, UnicodeDecodeError):
        return None, 'bad'
    by = {}
    for r in raw:
        if len(r) != len(TD_W_CSV_COLS):
            continue
        d = dict(zip(TD_W_CSV_COLS, r))
        try:
            if not d['since'] or not _d(d['date']):
                continue
            by.setdefault((int(d['v']), d['since']), []).append(
                [d['date'], d['sym'], int(d['n']), d['state'], d['votes'], d['saved_at'], float(d['y']) if d['y'] != '' else None])
        except (TypeError, ValueError):
            continue
    cps, oos = _tdw_pk_read(os.path.join(os.path.dirname(path), TD_W_PK))
    cur = (TD_VW2, TD_SINCE_W2)
    prev = []
    for key in sorted((set(by) | set(cps) | set(oos)) - {cur}, key=lambda x: (x[1], x[0])):
        o = oos.get(key)
        if o is None:                                                        # bez pliku punktów: suma z wierszy tej wersji (jak _tdw_log)
            L, _ = _tdw_jpairs({'rows': by.get(key) or []}, key[1])
            o = {k[0] + '.' + k[1]: [sum(x[1] for x in q), len(q), len({x[0] for x in q})] for k, q in L.items()}
        prev.append({'v': key[0], 'since': key[1], 'oos': o, 'cp': cps.get(key) or {}})
    rows = by.get(cur) or []
    if not rows and not prev:
        return None, 'none'
    out = {'at': None, 'v': TD_VW2, 'since': TD_SINCE_W2, 'cut': TD_W_CUT, 'rows': sorted(rows), 'cp': cps.get(cur) or {}}
    if prev:
        out['prev'] = prev
    return out, 'ok'


_W_LOG = [None, None]     # [poprzedni dziennik (main, przed trendami), nowy dziennik (build_daily_w2)]


def build_daily_w2(S):
    """v127: sygnały dzienne świata, wersja 2 → (wiersze, linie). Wejście: S['swiat-dzien'] (plik tylko dla zbieracza). Bez pliku albo bez
    żadnej serii → (None, None). Zepsuta seria jednego rynku → uwaga w meta, bez jego karty. Dziennik jak w krypto (v125): _W_LOG[0] → _W_LOG[1];
    brak → odtworzenie z archiwum/swiat-dziennik.csv; nieczytelne archiwum → licznik wstrzymany, nic nie zapisujemy. Kolejność: najpierw
    dziennik bez nowych kart (wyniki zapisanych kart, punkty kontrolne), potem karty (weto „anti” z punktu kontrolnego), potem zapis kart,
    które właśnie minęły granicę. Nie zmienia S."""
    S = S if isinstance(S, dict) else {}
    wd = S.get('swiat-dzien') if isinstance(S.get('swiat-dzien'), dict) else None
    if not wd:
        return None, None
    now_utc = _now_utc(); today = now_utc.date()
    if today.isoformat() > '2027-12-01':
        META['notes'].append('trendy dziennie świat: lista dni bez sesji NYSE kończy się na 2027 — dopisać następny rok')
    series = []
    for sym in TD_W_SYMS:
        try:
            s = _tdw_series(wd, sym)
            if s:
                series.append(s)
        except Exception as e:
            META['notes'].append(mask(f'trendy dziennie świat {sym}: {e}'))
    if not series:
        return None, None
    lines = {key: [] for key in TD_RULES_W2}; own = {}; ys = {}; good = []
    for s in series:
        try:
            pr = _tdw_pairs(s)
            ys[s['id']] = {s['dates'][j]: s['y'][j] for j in range(len(s['dates'])) if s['y'][j] is not None}
        except Exception as e:
            META['notes'].append(mask(f"trendy dziennie świat {s['id']}: {e}")); continue
        good.append(s)
        for dt_, key, v, hit in pr:
            lines[key].append((dt_, hit, s['id'], v))
            if key == ('w', 'all'):
                o = own.setdefault(s['id'], [0, 0]); o[0] += hit; o[1] += 1
    ut = _tdw_ut(good); gates = {}
    bd = _tdw_pool(lines, ys, today=today, ut=ut, gates=gates)
    vd_by = {(b['fam'], b['rule']): b['vd'] for b in bd}
    logA = None
    try:
        log0 = _W_LOG[0] if _tdw_valid(_W_LOG[0]) else None
        why = 'ok'
        if log0 is None:
            log0, why = _tdw_from_csv()
            if why == 'bad':
                META['errors'].append('Dziennik świata: brak poprzedniego pliku, a kopia w archiwum jest nieczytelna — licznik „od wdrożenia” '
                                      'wstrzymany, nic nie nadpisano')
            elif log0 is not None and log0['rows']:
                META['notes'].append(f"Dziennik świata: odtworzony z archiwum ({len(log0['rows'])} wierszy do {log0['rows'][-1][0]})")
            else:
                if log0 is not None:                         # v127 (przegląd): z archiwum wróciły tylko poprzednie wersje reguły (prev)
                    META['notes'].append(f"Dziennik świata: z archiwum odtworzone tylko poprzednie wersje reguły ({len(_tdw_prevs(log0))})")
                if today > _d(TD_SINCE_W2) + datetime.timedelta(days=4):
                    META['errors'].append('Dziennik świata: brak poprzedniego pliku i brak jego kopii w archiwum — nowy dziennik, licznik „od wdrożenia” od zera')
        if why != 'bad':
            logA = _tdw_log(log0, [], good, now_utc, ut)
    except Exception as e:
        logA = None
        META['notes'].append(mask(f'trendy dziennie świat, dziennik: {e}'))
    lcv = _tdw_lcv(logA)
    rows = []
    for s in good:
        try:
            rows.append(_tdw_row(s, vd_by, own, today, now_utc, gates, lcv))
        except Exception as e:
            META['notes'].append(mask(f"trendy dziennie świat {s['id']}: {e}"))
    if not rows:
        return None, None
    if logA is not None:
        try:
            _W_LOG[1] = _tdw_log(logA, rows, good, now_utc, ut)
            bd = _tdw_pool(lines, ys, log=_W_LOG[1], today=today, ut=ut)
        except Exception as e:
            _W_LOG[1] = None
            META['notes'].append(mask(f'trendy dziennie świat, dziennik: {e}'))
    return rows, bd


