_WD_TERMIN = [None]
_WD_SENT = []                           # v127 (przegląd): zapytania naprawdę wysłane w tym przebiegu (pole req) …
_WD_CUT = [False]                       # … i czy któreś zapytanie trafiło na koniec czasu budowniczego (uwaga w meta, bez przerwy i bez błędu)


class WdBudget(RuntimeError):
    """Koniec czasu budowniczego. `tmo` = limit (s) zapytania, które przez to nie zdążyło; None — zapytania nie wysłano (v127, przegląd 2)."""

    def __init__(self, msg='limit czasu', tmo=None):
        super().__init__(msg)
        self.tmo = tmo


def wd_tmo(cap):
    """Limit jednego zapytania = min(cap, czas, który został budowniczemu); < 1 s → WdBudget (wzór lev_tmo)."""
    left = _WD_TERMIN[0] - time.monotonic() if _WD_TERMIN[0] else cap
    if left < 1:
        _WD_CUT[0] = True
        raise WdBudget('limit czasu')
    return min(cap, left)


def _wd_req(get, url, cap):
    """v127 (przegląd): jedno zapytanie budowniczego — limit wd_tmo(cap), liczone jako wysłane (req). Porażka zapytania, któremu limit
    skrócono do końca czasu budowniczego (limit < cap i czasu już brak), to koniec czasu (WdBudget: uwaga, bez przerwy i bez wpisu
    w bledy), nie awaria dostawcy; WdBudget niesie limit tego zapytania (tmo — przegląd 2: seria wstępna iShares rozróżnia plik, który
    miał większość czasu budowniczego, od zapytania wysłanego z resztką czasu)."""
    tmo = wd_tmo(cap)
    _WD_SENT.append(1)
    try:
        return get(url, timeout=tmo)
    except Exception:
        if tmo < cap and _WD_TERMIN[0] and _WD_TERMIN[0] - time.monotonic() < 1:
            _WD_CUT[0] = True
            raise WdBudget('limit czasu', tmo)
        raise


def _wd_get_json(url, timeout):
    return get_json(url, timeout=timeout)


def _wd_get_bytes(url, timeout):
    return get_bytes(url, timeout=timeout)


def wd_num(x):
    try:
        v = float(str(x).replace(',', '').replace('$', '').strip())
    except ValueError:
        return None
    return v if _isnum(v) and v > 0 else None


def _wd_ny(now_utc):
    """Czas Nowego Jorku (naiwny) z reguły USA (_tdw_off) — bez bazy stref."""
    u = now_utc.astimezone(datetime.timezone.utc).replace(tzinfo=None)
    return u + datetime.timedelta(hours=_tdw_off(u.date()))


def wd_parse_nq(j, now_utc):
    """Nasdaq quote API → ({dzień: (otwarcie, zamknięcie)}, {wszystkie daty}). Wiersz z wolumenem „N/A” albo bez liczby = wiersz zastępczy:
    cena brak (nigdy 0), data zostaje (kalendarz sesji). Wiersz z dzisiejszą datą (NY) przed WD_POLL_M (17:00 NY) → pominięty: trwająca
    sesja albo zamknięcie jeszcze nieostateczne (v127, przegląd: ponowienie brakujących cen między 16:15 a 17:00 NY nie zapisze
    wcześniejszego zamknięcia jako pierwszej publikacji i nie przesunie kalendarza przed 17:00)."""
    rows = (((j or {}).get('data') or {}).get('tradesTable') or {}).get('rows')
    if not isinstance(rows, list):
        raise RuntimeError('nieznany kształt odpowiedzi')
    ny = _wd_ny(now_utc); today = ny.date().isoformat(); open_s = ny.hour * 60 + ny.minute < WD_POLL_M
    out, dates = {}, set()
    for r in rows:
        if not isinstance(r, dict):
            continue
        try:
            d = datetime.datetime.strptime(str(r.get('date')), '%m/%d/%Y').date().isoformat()
        except ValueError:
            continue
        if d > today or (d == today and open_s):
            continue
        dates.add(d)
        o, c, v = wd_num(r.get('open')), wd_num(r.get('close')), wd_num(r.get('volume'))
        if o and c and v:
            out[d] = (round(o, 4), round(c, 4))
    return out, dates


def _wd_iso():
    return _now_utc().astimezone(datetime.timezone.utc).replace(microsecond=0).strftime('%Y-%m-%dT%H:%M:%SZ')


def _wd_plus(iso, minutes):
    return (datetime.datetime.strptime(iso[:19], '%Y-%m-%dT%H:%M:%S') + datetime.timedelta(minutes=minutes)).strftime('%Y-%m-%dT%H:%M:%SZ')


def _wd_seen(day, iso, stamp_all=False):
    """Czas zapisu dla wiersza z datą `day`: po serii wstępnej swojej części (stamp_all) — zawsze iso; w serii wstępnej iso tylko dla wiersza
    najwyżej WD_FRESH dni starszego od chwili zapisu, starszy — null (historia, „na czas” z założenia)."""
    if stamp_all:
        return iso
    return iso if day >= (_d(iso[:10]) - datetime.timedelta(days=WD_FRESH)).isoformat() else None


def _wd_rv(wd, part, key, day):
    """Różnica przy ponownym odczycie dnia już zapisanego: liczona raz na (seria, dzień) → True, gdy nowa."""
    seen = wd.setdefault('rvd', {}).setdefault(part, {}).setdefault(key, [])
    if day in seen:
        return False
    seen.append(day); wd['rv'][part] = wd['rv'].get(part, 0) + 1
    return True


def _wd_esum(err):
    """{ticker: błąd} → {błąd: liczba tickerów} (krótko w meta)."""
    out = {}
    for e in err.values():
        out[e] = out.get(e, 0) + 1
    return out


def _wd_fetch_px(syms, a, b, n, now):
    """Równolegle (WD_THREADS) ceny tickerów z Nasdaq → ({ticker: ({dzień: (o, c)}, {daty})}, {ticker: błąd})."""
    got, err = {}, {}

    def one(t):
        return t, wd_parse_nq(_wd_req(_wd_get_json, WD_NQ_URL.format(t=t, a=a, b=b, n=n), WD_TIMEOUT), now)
    with _wd_cf.ThreadPoolExecutor(WD_THREADS) as ex:
        futs = [(t, ex.submit(one, t)) for t in syms]
        for t0, f in futs:
            try:
                t, q = f.result()
                got[t] = q
            except WdBudget:
                pass
            except Exception as e:  # noqa
                err[t0] = mask(str(e))[:60]
    return got, err


def _wd_merge_px(wd, got, iso, stamp_all=False):
    """Nowe dni cen. Kalendarz rośnie tylko o daty SPY (także wiersze zastępcze — sesja była, ceny brak); wiersz raz zapisany nie jest
    nadpisywany (różnica > 0,05% → rv.px raz na dzień); nowy wiersz [dzień, otwarcie, zamknięcie, seen]."""
    cal = wd['cal']
    if 'SPY' in got:
        new = sorted(d for d in got['SPY'][1] if not cal or d > cal[-1])
        cal.extend(new)
    cs = set(cal)
    for t, (q, _) in got.items():
        p = wd['px'].setdefault(t, {'d': [], 'miss': []})
        have = {r[0]: r for r in p['d']}
        add = []
        for d, (o, c) in sorted(q.items()):
            if d in have:
                r = have[d]
                if abs(r[1] / o - 1) > 5e-4 or abs(r[2] / c - 1) > 5e-4:
                    _wd_rv(wd, 'px', t, d)
                continue
            if d in cs:
                add.append([d, o, c, _wd_seen(d, iso, stamp_all)])
        if add:
            p['d'] = sorted(p['d'] + add)


def _wd_rows_merge(wd, part, key, P, rows, iso, stamp_all=False):
    """Wiersze wydawcy [dzień, NAV, jednostki] → P['d'] [dzień, NAV, jednostki, seen]; tylko nowe dni (pierwsza publikacja); różnica
    przy ponownym odczycie → rv (raz na dzień)."""
    have = {r[0]: r for r in P['d']}
    for r in rows or []:
        if not (isinstance(r, list) and len(r) >= 3 and isinstance(r[0], str) and _d(r[0]) and _isnum(r[1]) and _isnum(r[2])):
            continue
        if r[0] in have:
            o = have[r[0]]
            if abs(o[1] - r[1]) > 1e-6 * max(1, r[1]) or abs(o[2] - r[2]) > max(1, 1e-6 * r[2]):
                _wd_rv(wd, part, key, r[0])
            continue
        have[r[0]] = [r[0], r[1], r[2], _wd_seen(r[0], iso, stamp_all)]
    P['d'] = [have[k] for k in sorted(have)]


def _wd_fl_from_saved(wd, fundusze, iso):
    f = (fundusze or {}).get('f') if isinstance(fundusze, dict) else None
    for t in WD_SSGA + WD_ISH:
        P = wd['fl'].setdefault(t, {'iss': 'ssga' if t in FUND_SSGA else 'ishares', 'd': []})
        _wd_rows_merge(wd, 'fl', t, P, ((f or {}).get(t) or {}).get('h'), iso, bool(wd['bf'].get('fl')))


def _wd_su_fl_from_saved(wd, fundusze, iso):
    """v309: NAV i liczba jednostek funduszy surowcowych (WD_SU_FL) z części 'su' pliku fundusze zapisanego w tym przebiegu → część fl,
    ten sam kształt wierszy co 35 funduszy reguł głównych: [dzień, NAV, jednostki, czas zapisu]. Pierwsze dopisanie funduszu = seria wstępna
    (ok. 300 dni z pliku fundusze; czas zapisu tylko wierszy z ostatnich WD_FRESH dni, starsze — null = historia); potem dzień PO ostatnim
    zapisanym — z czasem zapisu (pierwsza publikacja), a dni dopisane WSTECZ (historia z pełnego pliku wydawcy, gdy fundusz zaczął od
    samego zestawienia) — jak seria wstępna. Wiersz raz zapisany zostaje (inna wartość przy ponownym odczycie → rv.fl, raz na dzień).
    Brak funduszu w pliku fundusze = brak wpisu (nigdy pusty fundusz ani zero)."""
    su = fundusze.get('su') if isinstance(fundusze, dict) and isinstance(fundusze.get('su'), dict) else {}
    for t in WD_SU_FL:
        e = su.get(t) if isinstance(su.get(t), dict) else {}
        h = [r for r in e.get('h') if isinstance(r, list) and len(r) >= 3 and isinstance(r[0], str)] if isinstance(e.get('h'), list) else []
        if not h:
            continue
        P = wd['fl'].setdefault(t, {'iss': 'ishares', 'd': []})
        if not isinstance(P.get('d'), list):
            P['d'] = []
        last = P['d'][-1][0] if P['d'] and isinstance(P['d'][-1], list) and P['d'][-1] and isinstance(P['d'][-1][0], str) else None
        _wd_rows_merge(wd, 'fl', t, P, [r for r in h if last is None or r[0] <= last], iso)   # seria wstępna albo historia wstecz
        if last is not None:
            _wd_rows_merge(wd, 'fl', t, P, [r for r in h if r[0] > last], iso, True)   # nowy dzień — chwila zapisu
        P['iss'] = 'ishares'; P['seed'] = 'fu'   # seria z pliku fundusze (nie z pełnego pliku wydawcy w tym budowniczym)


def _wd_ob_from_saved(wd, obce, iso):
    for part in ('tw', 'hk', 'in'):
        src = ((obce or {}).get(part) or {}) if isinstance(obce, dict) else {}
        P = wd['ob'].setdefault(part, {'d': [], 'empty': []})
        if isinstance(src.get('empty'), list):
            P['empty'] = [x for x in src['empty'] if isinstance(x, str)]
        have = {r[0]: r for r in P['d']}
        for r in src.get('d') or []:
            if not (isinstance(r, list) and len(r) > 1 and isinstance(r[0], str) and _d(r[0]) and _isnum(r[1])):
                continue
            if r[0] in have:
                if abs(have[r[0]][1] - r[1]) > 0.05:
                    _wd_rv(wd, 'ob', part, r[0])
                continue
            have[r[0]] = [r[0], r[1], _wd_seen(r[0], iso, bool(wd['bf'].get('ob')))]
        P['d'] = [have[k] for k in sorted(have)]


def _wd_ssga_fetch(tickers):
    """Pliki State Street (cała historia w jednym pliku) → ({ticker: wiersze}, {ticker: błąd}). Parser produkcji (parse_ssga_navhist)."""
    got, err = {}, {}

    def one(t):
        return t, parse_ssga_navhist(_fund_ssga_bytes(t, lambda u: _wd_req(_wd_get_bytes, u, WD_TIMEOUT)), t)   # v342 (F1Z2): nowa ścieżka, zapas — stara
    with _wd_cf.ThreadPoolExecutor(WD_THREADS) as ex:
        for t0, f in [(t, ex.submit(one, t)) for t in tickers]:
            try:
                t, h = f.result(); got[t] = h
            except WdBudget:
                pass
            except Exception as e:  # noqa
                err[t0] = mask(str(e))[:60]
    return got, err


def _wd_prev_session(day):
    """Ostatnia zaplanowana sesja NYSE przed dniem `day` (pon–pt bez TD_NYSE_CLOSED)."""
    d = _d(day) - datetime.timedelta(days=1)
    while d.weekday() >= 5 or d.isoformat() in TD_NYSE_CLOSED:
        d -= datetime.timedelta(days=1)
    return d.isoformat()


def _wd_trim(wd):
    cal = wd['cal'][-WD_KEEP:]; wd['cal'] = cal
    if not cal:
        return
    lo = cal[0]; lo_fl = (_d(lo) - datetime.timedelta(days=10)).isoformat()
    for p in wd['px'].values():
        p['d'] = [r for r in p['d'] if r[0] >= lo]
        p['miss'] = [d for d in p.get('miss') or [] if d >= lo]
    for p in wd['fl'].values():
        p['d'] = [r for r in p['d'] if r[0] >= lo_fl]
    for p in wd['ob'].values():
        p['d'] = [r for r in p['d'] if r[0] >= lo_fl]
    for part in (wd.get('rvd') or {}).values():
        for k in list(part):
            part[k] = [d for d in part[k] if d >= lo_fl]
            if not part[k]:
                del part[k]


def _wd_px_ok(wd):
    cal = wd['cal']
    if len(cal) < WD_MIN_CAL:
        return False
    for t in TD_W_SYMS:
        rows = (wd['px'].get(t) or {}).get('d') or []
        if not rows:
            return False
        span = [d for d in cal if d >= rows[0][0]]
        if len(rows) < WD_MIN_SHARE * len(span):
            return False
    return True


def _wd_nq_ok(wd, iso):
    """Czy wolno pytać Nasdaq (poza oknem przerwy po awarii)."""
    nx = (wd.get('nq') or {}).get('next')
    return not nx or iso[:19] >= nx[:19]


def _wd_nq_fail(wd, iso, why):
    q = wd.setdefault('nq', {'fails': 0, 'next': None, 'since': None})
    q['fails'] = q.get('fails', 0) + 1; q['since'] = q.get('since') or iso
    q['next'] = _wd_plus(iso, min(WD_NQ_BACK[1], max(WD_NQ_BACK[0], 20 * 2 ** q['fails'])))
    q['why'] = why


def _wd_seed_skip(P, iso):
    se = P.get('se') or {}
    return bool(se.get('at')) and iso[:19] < _wd_plus(se['at'], WD_SEED_BACK_M)[:19]


def _wd_seed_fail(wd, P, t, iso, why, fundusze, cut=False):
    """Porażka serii wstępnej jednego funduszu: przerwa 6 h; po WD_SEED_FAILS — historia z pliku fundusze (300 dni) i seed 'short'.
    v127 (przegląd 2): cut=True — pełny plik ucięty limitem czasu budowniczego (_wd_seed_cut): licznik `se.cut` (takie próby z rzędu)
    i uwaga w meta z nazwą funduszu zamiast wpisu w bledy (koniec czasu to uwaga, nie błąd); inna porażka zeruje `se.cut`."""
    se = P.setdefault('se', {'n': 0, 'at': None}); se['n'] += 1; se['at'] = iso; se['why'] = why
    if cut:
        se['cut'] = se.get('cut', 0) + 1
        nx = (f"; następna próba po {_wd_plus(iso, WD_SEED_BACK_M)} (po {WD_SEED_FAILS} porażkach — ok. 300 dni z pliku fundusze)"
              if se['n'] < WD_SEED_FAILS else '')
        META['notes'].append(f"{WD_LABEL}: {t} — pełny plik wydawcy nie zmieścił się w limicie czasu budowniczego ({WD_T} s) "
                             f"po raz {se['cut']} z rzędu{nx}")
    else:
        se.pop('cut', None)
        wd['bledy'].setdefault('seed_fl', {})[t] = why
    if se['n'] >= WD_SEED_FAILS:
        h = ((((fundusze or {}).get('f') or {}).get(t) or {}).get('h')) if isinstance(fundusze, dict) else None
        _wd_rows_merge(wd, 'fl', t, P, h, iso)
        P['seed'] = 'short'
        cz = f" (w tym {se['cut']} razy ucięty limitem czasu budowniczego)" if se.get('cut') else ''
        META['notes'].append(f"{WD_LABEL}: {t} — pełny plik wydawcy nieczytelny {se['n']} razy{cz}; przepływy od "
                             f"{P['d'][0][0] if P['d'] else '—'} (z pliku fundusze, ok. 300 dni) — krótsza historia tego funduszu")


def _wd_seed_cut(wd, P, t, iso, e, fundusze):
    """v127 (przegląd 2): pełny plik iShares ucięty końcem czasu budowniczego (WdBudget z zapytania o plik). Zapytanie wysłane z co najmniej
    połową limitu budowniczego (tmo ≥ WD_T / 2) — plik nie mieści się w czasie całego przebiegu: to próba serii wstępnej (se.at → przerwa
    6 h, kolejka idzie dalej; porażka liczona do WD_SEED_FAILS, po 3 — ok. 300 dni z pliku fundusze, seed 'short'; uwaga z nazwą funduszu
    i liczbą takich prób z rzędu). Zapytanie wysłane z resztką czasu (tmo < WD_T / 2) albo niewysłane — zwykły koniec czasu, bez zmian
    (następny przebieg zaczyna od tego funduszu z pełnym czasem). Inaczej jeden zawsze wolny plik blokowałby wszystkie fundusze iShares
    (koniec czasu kończy pętlę), a plik świata nigdy nie byłby gotowy. → True, gdy próba zapisana."""
    tmo = getattr(e, 'tmo', None)
    if tmo is None or tmo < WD_T / 2:
        return False
    _wd_seed_fail(wd, P, t, iso, f'limit czasu budowniczego ({WD_T} s)', fundusze, cut=True)
    return True


def _wd_blockers(wd):
    """v127 (przegląd): powody, dla których plik z kalendarzem nie jest gotowy, choć nic już nie czeka (wszystkie ceny i fundusze zasiane
    albo „short”) → lista tekstów; seria jeszcze w toku (także w przerwie po awarii) → [] (to nie blokada)."""
    if not all((wd['px'].get(t) or {}).get('seed') for t in TD_W_SYMS) or \
            not all((wd['fl'].get(t) or {}).get('seed') for t in WD_SSGA + WD_ISH):
        return []
    out = []
    cal = wd['cal'][-WD_KEEP:]
    if len(cal) < WD_MIN_CAL:
        out.append(f'kalendarz sesji {len(cal)} z {WD_MIN_CAL}')
    low = []
    for t in TD_W_SYMS:
        rows = (wd['px'].get(t) or {}).get('d') or []
        span = [d for d in cal if rows and d >= rows[0][0]]
        if not rows or len(rows) < WD_MIN_SHARE * len(span):
            low.append(t)
    if low:
        out.append(f'ceny w mniej niż {round(100 * WD_MIN_SHARE)}% sesji: {", ".join(low)}')
    if not wd['bf'].get('ob'):
        out.append('brak danych inwestorów zagranicznych (plik obce)')
    return out


def build_swiat_dzien(prev=None, saved=None, run_t0=None):
    """v127: plik dzienny świata. Części w kolejności pilności, jeden limit czasu (WD_T; WD_T_LATE i bez serii wstępnej w spóźnionym przebiegu):
    (1) ceny dnia (od 17:00 NY: sonda SPY, potem pozostałe 43; brakujące — także SPY — najwyżej co 55 min, po 48 h „miss”; po awarii Nasdaq
    przerwa 55 min → 6 h), (2) wiersze wydawców i zagranicznych z plików zapisanych w tym przebiegu (bez zapytań), (3) poranne pliki State Street
    (od 00:40 NY dnia sesji do jej granicy: sonda SPY, potem brakujące; GLD i GLDM bez sondy), (4) seria wstępna: najpierw ceny (SPY pierwszy —
    bez niego nic), pliki wydawców dopiero z kalendarzem (State Street raz, iShares po WD_SEED_ISH; porażka → przerwa 6 h, po 3 — 300 dni z
    pliku fundusze), (5) przycięcie, flagi, `ready` (trwała). Czas zapisu (`seen`) brany po powrocie zapytania. Bez kalendarza — szkielet pliku
    (cal [], ready false) z danymi przerw. Awaria części = poprzednie dane + wpis w `bledy`; koniec czasu = uwaga, nie błąd.
    v309: + 7 funduszy surowcowych (WD_SU_PX — ceny: seria wstępna w kroku 4b, potem w cenach dnia na końcu kolejki) i NAV z jednostkami
    3 z nich (WD_SU_FL — z części 'su' pliku fundusze, krok 2) — wejścia linii su.cm.p i su.cm.f reguł „w cieniu” SUROWCE. Poza TD_W_SYMS:
    gotowość, karty reguł głównych i bledy pliku bez zmian; ich problemy — uwaga w meta."""
    now = _now_utc(); iso = _wd_iso(); ny = _wd_ny(now)
    tr = round(time.monotonic() - run_t0, 1) if run_t0 is not None else None
    late = tr is not None and tr > WD_LATE
    t0 = time.monotonic(); _WD_TERMIN[0] = t0 + (WD_T_LATE if late else WD_T); _WD_SENT.clear(); _WD_CUT[0] = False
    prev = prev if isinstance(prev, dict) else {}
    cp = lambda k: json.loads(json.dumps(prev.get(k) or {}))  # noqa: E731
    wd = {'at': NOW, 'v': 1, 'src': WD_SRC, 'keep': WD_KEEP, 'cut': TD_W_CUT,
          'cal': list(prev.get('cal') or []), 'px': cp('px'), 'fl': cp('fl'), 'ob': cp('ob'), 'rv': {}, 'rvd': cp('rvd'),
          'bf': dict(prev.get('bf') or {}), 'try': prev.get('try'), 'nq': cp('nq') or {'fails': 0, 'next': None, 'since': None},
          'ready': prev.get('ready') is True, 'bledy': {}, 'req': 0, 'tr': tr}
    saved = saved if isinstance(saved, dict) else {}
    stop = False
    su_err = {}                                           # v309: problemy funduszy surowcowych — uwaga w meta (bledy i stan pliku bez zmian)
    today_ny = ny.date().isoformat(); mins = ny.hour * 60 + ny.minute
    # (1) ceny dnia
    try:
        if wd['bf'].get('px') and wd['cal']:
            is_s = ny.weekday() < 5 and today_ny not in TD_NYSE_CLOSED
            want = today_ny if (is_s and mins >= WD_POLL_M) else _wd_prev_session(today_ny)
            a = (_d(today_ny) - datetime.timedelta(days=20)).isoformat()
            su_px = tuple(t for t in WD_SU_PX if (wd['px'].get(t) or {}).get('seed'))   # v309: fundusze surowcowe po serii wstępnej
            lack = [t for t in TD_W_SYMS + su_px if not any(r[0] == wd['cal'][-1] for r in (wd['px'].get(t) or {}).get('d', [])[-3:])
                    and wd['cal'][-1] not in ((wd['px'].get(t) or {}).get('miss') or [])]
            err = {}
            if wd['cal'][-1] < want and _wd_nq_ok(wd, iso):
                got, err = _wd_fetch_px(['SPY'], a, today_ny, 15, now)
                if 'SPY' in err:
                    _wd_nq_fail(wd, _wd_iso(), err['SPY']); got = {}
                elif 'SPY' in got:
                    wd['nq'] = {'fails': 0, 'next': None, 'since': None}
                if got.get('SPY') and max(got['SPY'][1], default='') > wd['cal'][-1]:
                    rest, err2 = _wd_fetch_px([t for t in TD_W_SYMS if t != 'SPY'] + list(su_px), a, today_ny, 15, now)   # v309: fundusze
                    # surowcowe na końcu kolejki (koniec czasu budowniczego zabiera najpierw je, nie 43 rynki)
                    got.update(rest); err.update(err2); wd['try'] = _wd_iso()
                _wd_merge_px(wd, got, _wd_iso(), True)
            elif wd['cal'][-1] >= want and lack and _wd_nq_ok(wd, iso) and \
                    (not wd.get('try') or wd['try'][:19] <= _wd_plus(iso, -WD_RETRY_M)[:19]):
                got, err = _wd_fetch_px(lack, a, today_ny, 15, now); wd['try'] = _wd_iso()   # najwyżej co godzinę, do 48 h
                _wd_merge_px(wd, got, _wd_iso(), True)
            end = datetime.datetime.fromisoformat(_tdw_at(wd['cal'][-1], TD_W_CLOSE))
            if (now.astimezone(datetime.timezone.utc).replace(tzinfo=None) - end).total_seconds() > WD_GAP_H * 3600:
                for t in lack:
                    P = wd['px'].setdefault(t, {'d': [], 'miss': []})
                    if not any(r[0] == wd['cal'][-1] for r in P['d']) and wd['cal'][-1] not in P.setdefault('miss', []):
                        P['miss'].append(wd['cal'][-1])
            esu = {t: err.pop(t) for t in [x for x in err if x in WD_SU_PX]}   # v309: fundusze surowcowe — uwaga w meta, nie bledy pliku
            if esu:
                su_err['px'] = _wd_esum(esu)
            if err:
                wd['bledy']['px'] = _wd_esum(err)
    except WdBudget:
        stop = True
    except Exception as e:
        wd['bledy']['px'] = mask(str(e))[:140]
    stop = stop or _WD_CUT[0]                             # v127 (przegląd): pula wątków połyka koniec czasu pojedynczego zapytania
    # (2) wiersze wydawców i zagranicznych z plików zapisanych w tym przebiegu (bez zapytań)
    try:
        if wd['cal']:
            _wd_fl_from_saved(wd, saved.get('fundusze'), iso)
            try:                                          # v309: fundusze surowcowe (część 'su' pliku fundusze) — awaria = uwaga, nie błąd pliku
                _wd_su_fl_from_saved(wd, saved.get('fundusze'), iso)
            except Exception as e:  # noqa
                su_err['fl'] = mask(str(e))[:140]
            _wd_ob_from_saved(wd, saved.get('obce'), iso)
            wd['bf']['ob'] = any(((wd['ob'].get(p) or {}).get('d')) for p in ('tw', 'hk', 'in'))
    except Exception as e:
        wd['bledy']['fl'] = mask(str(e))[:140]
    # (3) poranne pliki State Street (dla sesji S = następnej po najnowszym zapisanym zamknięciu)
    try:
        if not stop and wd['bf'].get('fl') and wd['cal']:
            D = wd['cal'][-1]; S = _tdw_next(D)
            lack = [t for t in WD_SSGA if not any(r[0] >= D for r in ((wd['fl'].get(t) or {}).get('d') or [])[-3:])]
            if lack and today_ny == S and mins >= WD_SSGA_M and iso[:19] < _tdw_cut(S):
                gold = [t for t in lack if t in ('GLD', 'GLDM')]
                rest = [t for t in lack if t not in gold]
                probe = ['SPY'] if 'SPY' in rest else rest[:1]
                got, err = _wd_ssga_fetch(gold + probe); at = _wd_iso()
                for t, h in got.items():
                    _wd_rows_merge(wd, 'fl', t, wd['fl'].setdefault(t, {'iss': 'ssga', 'd': []}), h, at, True)
                if probe and any(r[0] >= D for r in got.get(probe[0]) or []):
                    more = [t for t in rest if t not in probe]
                    g2, e2 = _wd_ssga_fetch(more); at = _wd_iso(); err.update(e2)
                    for t, h in g2.items():
                        _wd_rows_merge(wd, 'fl', t, wd['fl'].setdefault(t, {'iss': 'ssga', 'd': []}), h, at, True)
                if err:
                    wd['bledy']['ssga'] = _wd_esum(err)
    except WdBudget:
        stop = True
    except Exception as e:
        wd['bledy']['ssga'] = mask(str(e))[:140]
    stop = stop or _WD_CUT[0]
    # (4) seria wstępna: najpierw ceny (SPY = kalendarz sesji), pliki wydawców dopiero z kalendarzem
    try:
        if not stop and not late and not wd['bf'].get('px') and _wd_nq_ok(wd, iso):
            a = (now.date() - datetime.timedelta(days=WD_SEED_DAYS)).isoformat(); b = now.date().isoformat()
            pend = [t for t in TD_W_SYMS if not (wd['px'].get(t) or {}).get('seed') and not _wd_seed_skip(wd['px'].get(t) or {}, iso)]
            rest = pend[:WD_SEED_PX]
            if not (wd['px'].get('SPY') or {}).get('seed'):              # SPY sam i pierwszy: jego daty to kalendarz; bez niego nic więcej
                got, err = _wd_fetch_px(['SPY'], a, b, 9999, now); at = _wd_iso(); rest = []
                if 'SPY' in got:
                    wd['nq'] = {'fails': 0, 'next': None, 'since': None}
                    _wd_merge_px(wd, got, at); wd['px']['SPY']['seed'] = True
                    rest = [t for t in pend if t != 'SPY'][:WD_SEED_PX - 1]
                elif 'SPY' in err:
                    _wd_nq_fail(wd, at, err['SPY']); wd['bledy']['seed_px'] = _wd_esum(err)
            if rest:
                got, err = _wd_fetch_px(rest, a, b, 9999, now); at = _wd_iso()
                _wd_merge_px(wd, got, at)
                for t in got:
                    wd['px'][t]['seed'] = True; wd['px'][t].pop('se', None)
                for t, e in err.items():
                    P = wd['px'].setdefault(t, {'d': [], 'miss': []}); se = P.setdefault('se', {'n': 0, 'at': None})
                    se['n'] += 1; se['at'] = at; se['why'] = e
                if err:
                    wd['bledy']['seed_px'] = _wd_esum(err)
            wd['bf']['px'] = all((wd['px'].get(t) or {}).get('seed') for t in TD_W_SYMS) and _wd_px_ok(dict(wd, cal=wd['cal'][-WD_KEEP:]))
        if not stop and not late and not wd['bf'].get('fl') and wd['cal']:
            fu = saved.get('fundusze')
            todo = [t for t in WD_SSGA if not (wd['fl'].get(t) or {}).get('seed') and not _wd_seed_skip(wd['fl'].get(t) or {}, iso)]
            if todo:
                got, err = _wd_ssga_fetch(todo); at = _wd_iso()
                for t in todo:
                    P = wd['fl'].setdefault(t, {'iss': 'ssga', 'd': []})
                    if t in got:
                        _wd_rows_merge(wd, 'fl', t, P, got[t], at); P['seed'] = True; P.pop('se', None)
                    elif t in err:
                        _wd_seed_fail(wd, P, t, at, err[t], fu)
            f = ((fu or {}).get('f') or {}) if isinstance(fu, dict) else {}
            n = 0
            for t in WD_ISH:
                P = wd['fl'].setdefault(t, {'iss': 'ishares', 'd': []})
                if P.get('seed') or n >= WD_SEED_ISH or _wd_seed_skip(P, iso):
                    continue
                pid = (f.get(t) or {}).get('pid')
                if not pid:                                  # v127 (przegląd): plik fundusze jest, a fundusz bez identyfikatora pliku wydawcy —
                    if f:                                    # jak nieczytelny plik (przerwa 6 h, po 3 razach 300 dni z pliku fundusze), nie cisza
                        _wd_seed_fail(wd, P, t, iso, 'brak identyfikatora pliku wydawcy (pid) w pliku fundusze', fu)
                    continue
                n += 1
                try:
                    h = parse_ishares_hist(_wd_req(_wd_get_bytes, FUND_ISH_DOC.format(pid=pid), WD_DOC_TIMEOUT))
                    _wd_rows_merge(wd, 'fl', t, P, h, _wd_iso()); P['seed'] = True; P.pop('se', None)
                except WdBudget as e:                        # v127 (przegląd 2): plik, który miał większość czasu budowniczego, a nie zdążył —
                    _wd_seed_cut(wd, P, t, _wd_iso(), e, fu)  # próba zapisana (przerwa 6 h, porażka); potem koniec czasu jak dotąd
                    raise
                except Exception as e:  # noqa
                    _wd_seed_fail(wd, P, t, _wd_iso(), mask(str(e))[:60], fu)
            wd['bf']['fl'] = all((wd['fl'].get(t) or {}).get('seed') for t in WD_SSGA + WD_ISH)
    except WdBudget:
        stop = True
    except Exception as e:
        wd['bledy']['seed'] = mask(str(e))[:140]
    stop = stop or _WD_CUT[0]
    # (4b) v309: seria wstępna cen 7 funduszy surowcowych (WD_SU_PX — linia su.cm.p reguł „w cieniu” SUROWCE): dopiero po gotowych cenach
    # 44 rynków (bf.px) i po krokach 1–4 (pierwszeństwo w czasie budowniczego), poza spóźnionym przebiegiem i przerwą po awarii Nasdaq;
    # historia jak 44 rynki (WD_SEED_DAYS, tylko sesje kalendarza SPY; wiersz z ostatnich WD_FRESH dni z czasem zapisu, starszy — null).
    # Fundusz bez żadnego wiersza ceny albo z błędem → przerwa WD_SEED_BACK_M (jak 44 rynki); problemy — uwaga w meta, nie bledy.
    try:
        if not stop and not late and wd['bf'].get('px') and wd['cal'] and _wd_nq_ok(wd, iso):
            pend = [t for t in WD_SU_PX if not (wd['px'].get(t) or {}).get('seed') and not _wd_seed_skip(wd['px'].get(t) or {}, iso)]
            if pend:
                a = (now.date() - datetime.timedelta(days=WD_SEED_DAYS)).isoformat(); b = now.date().isoformat()
                got, err = _wd_fetch_px(pend[:WD_SEED_PX], a, b, 9999, now); at = _wd_iso()
                for t in [x for x in got if not got[x][0]]:   # odpowiedź bez żadnej ceny (inny symbol, pusta tabela) — jak błąd
                    del got[t]; err[t] = 'brak wierszy cen'
                _wd_merge_px(wd, got, at)
                for t in got:
                    wd['px'][t]['seed'] = True; wd['px'][t].pop('se', None)
                for t, e in err.items():
                    P = wd['px'].setdefault(t, {'d': [], 'miss': []}); se = P.setdefault('se', {'n': 0, 'at': None})
                    se['n'] += 1; se['at'] = at; se['why'] = e
                if err:
                    su_err['seed_px'] = _wd_esum(err)
    except WdBudget:
        stop = True
    except Exception as e:
        su_err['seed'] = mask(str(e))[:140]
    stop = stop or _WD_CUT[0]
    # (5) przycięcie, flagi, błędy
    _wd_trim(wd)
    wd['ready'] = bool(wd['cal']) and (wd['ready'] or all(wd['bf'].get(k) for k in ('px', 'fl', 'ob')))
    run_rv = {k: v for k, v in wd['rv'].items() if v}
    wd['rv'] = {k: (prev.get('rv') or {}).get(k, 0) + wd['rv'].get(k, 0) for k in ('px', 'fl', 'ob')}   # licznik narastający
    q = wd['nq']
    if q.get('fails'):
        META['notes'].append(f"{WD_LABEL}: Nasdaq niedostępny od {q.get('since')} ({q.get('fails')} prób) — następna próba po {q.get('next')}")
    if not wd['cal']:
        META['notes'].append(f'{WD_LABEL}: brak kalendarza sesji (seria wstępna cen jeszcze niepobrana) — plik bez danych, wersja 1 świata zostaje')
    if stop:
        META['notes'].append(f'{WD_LABEL}: limit czasu budowniczego ({WD_T_LATE if late else WD_T} s) — reszta w następnym przebiegu')
    why = _wd_blockers(wd) if wd['cal'] and not wd['ready'] else []
    if why:                                               # v127 (przegląd): gotowość zablokowana na stałe — powód w meta, nie cisza
        META['notes'].append(f"{WD_LABEL}: plik jeszcze niegotowy, choć seria wstępna się skończyła — {'; '.join(why)}; wersja 1 świata zostaje")
    if run_rv:
        META['notes'].append(f"{WD_LABEL}: dostawca przepisał dni już zapisane (w pliku zostaje pierwsza publikacja): {run_rv}")
    if wd['bledy']:
        META['errors'].append(mask(f"{WD_LABEL}: {wd['bledy']}"))
    if su_err:                                            # v309: fundusze surowcowe (reguły „w cieniu” TRENDÓW) — uwaga, stan pliku bez zmian
        META['notes'].append(mask(f"{WD_LABEL}: fundusze surowcowe (TRENDY, reguły w cieniu): {su_err}")[:300])
    wd['req'] = len(_WD_SENT)                             # v127 (przegląd): zapytania naprawdę wysłane
    wd['t'] = round(time.monotonic() - t0, 2)
    return wd


def _tr_try(name, fn, out):
    """Jedno źródło TRENDÓW — błąd jednego źródła nie usuwa pozostałych (uwaga w meta zamiast pustej zakładki)."""
    try:
        for r in fn() or []:
            if r:
                out.append(r)
    except Exception as e:
        META['notes'].append(mask(f'trendy {name}: {e}'))


def _tr_flows(S):
    """Serie przepływów z obiektów zapisanych w tym przebiegu (brak pliku albo części = brak wiersza)."""
    rows = []
    today = _now_utc().date()
    ob = S.get('obce') if isinstance(S.get('obce'), dict) else {}

    def india():
        if not ob.get('in'):
            return []
        ds, eq, db = _tr_cols(ob['in'], 1, 2)
        return [_tr_row('in_eq', 'eq', 'flow', 5, ds, eq, span=TR_SPAN), _tr_row('in_bd', 'bd', 'flow', 5, ds, db, span=TR_SPAN)]

    def twhk():
        out = []
        for k, cur in (('tw', 'TWD'), ('hk', 'HKD')):
            if ob.get(k):
                ds, v, u = _tr_sessions(ob[k], 1, 5)
                r = _tr_row(k, 'eq', 'flow', 5, ds, v, usd=u, cur=cur, skip=set(ob[k].get('empty') or []))
                _tr_fx(r, _tr_fxd(ob[k], 6, r['date']) if r else None, 'd')   # v346 (T10-05): dzień ostatniego kursu dziennego
                out.append(r)
        return out

    def thai():
        if not ob.get('th'):
            return []
        ds, v, u, h = _tr_cols(ob['th'], 1, 7, 6)
        r = _tr_row('th', 'bd', 'flow', 5, ds, v, usd=u, hold=next((x for x in reversed(h) if _isnum(x)), None), cur='THB', span=TR_SPAN)
        _tr_fx(r, _tr_fxd(ob['th'], 9, r['date']) if r else None, 'd')   # v346 (T10-05)
        return [r]

    def brazil():
        if not ob.get('br'):
            return []
        ds, v = _tr_cols(ob['br'], 1)
        return [_tr_row('br', 'fx', 'flow', 5, ds, v, lag=7, span=TR_SPAN)]   # publikacja w środy za tydzień do piątku

    def turkey():
        if not ob.get('tr'):
            return []
        ds, eq, gb = _tr_cols(ob['tr'], 2, 3)
        return [_tr_row('tr_eq', 'eq', 'flow', 1, *_tr_weeks(ds, eq), weekly_days=16),
                _tr_row('tr_bd', 'bd', 'flow', 1, *_tr_weeks(ds, gb), weekly_days=16)]

    def japan():
        inst = S.get('instytucje') if isinstance(S.get('instytucje'), dict) else {}
        mof = [w for w in ((inst.get('mof') or {}).get('d') or []) if isinstance(w, dict) and w.get('to')]
        if not mof:
            return []
        ds = [w['to'] for w in mof]
        rates = _jpy_per_usd(S); out = []
        for key, sid, g in (('equity_net', 'jp_eq', 'eq'), ('ltdebt_net', 'jp_bd', 'bd')):
            v = [(w.get('liabilities') or {}).get(key) for w in mof]
            wd, wv = _tr_weeks(ds, [x / 10 if _isnum(x) else None for x in v])      # mld JPY
            fx = [_rate_for(rates, d[:7]) for d in wd]                                # średni kurs miesiąca EBC (ostatni znany ≤ miesiąc tygodnia)
            usd = [x * 1000 / rt if _isnum(x) and rt else None for x, (_, rt) in zip(wv, fx)]
            r = _tr_row(sid, g, 'flow', 1, wd, wv, usd=usd, weekly_days=20, cur='JPY')
            if r and fx and fx[-1][0]:
                r['fxm'] = fx[-1][0]
            out.append(r)
        return out

    def mexico():
        mx = S.get('meksyk') if isinstance(S.get('meksyk'), dict) else {}
        md = [r for r in mx.get('d') or [] if isinstance(r, list) and len(r) > 1 and isinstance(r[0], str) and _d(r[0])]
        if len(md) < 2:
            return []
        ch = [md[i][1] - md[i - 1][1] if _isnum(md[i][1]) and _isnum(md[i - 1][1]) else None for i in range(1, len(md))]
        fx = (mx.get('fx') or [None])[0]
        usd = [x / fx if _isnum(x) and _isnum(fx) and fx > 0 else None for x in ch]
        r = _tr_row('mx', 'bd', 'stock', 5, [r[0] for r in md[1:]], ch, usd=usd, hold=md[-1][1], lag=10, cur='MXN', span=TR_SPAN)
        fxs = mx.get('fx') if isinstance(mx.get('fx'), list) else []
        _tr_fx(r, fxs[1] if len(fxs) > 1 and isinstance(fxs[1], str) and _d(fxs[1]) else None, '1')   # v346 (T10-05): jeden kurs pliku na cały okres
        return [r]

    def etfs():
        etf = S.get('etf') if isinstance(S.get('etf'), dict) else {}; out = []
        for k in ('btc', 'eth', 'sol', 'xrp'):
            a = (etf.get('assets') or {}).get(k) or {}
            day = [r for r in a.get('day') or [] if isinstance(r, list) and len(r) == 2 and _isnum(r[0])]
            if day:
                ds = [datetime.datetime.fromtimestamp(r[0], datetime.timezone.utc).date().isoformat() for r in day]
                out.append(_tr_row('etf_' + k, 'cr', 'flow', 5, ds, [r[1] if _isnum(r[1]) else None for r in day], hold=a.get('aum'), span=TR_SPAN))
        return out

    def coinmetrics():
        cm = S.get('cm') if isinstance(S.get('cm'), dict) else {}; out = []
        for k in ('btc', 'eth'):
            a = (cm.get('assets') or {}).get(k) or {}
            # v318 (drobne8; recenzja TRENDY fali 7): tylko ZAMKNIĘTE doby UTC — jawny warunek jak w stable() (dostawca publikuje dobę po jej końcu, więc dziś
            # warunek nic nie zmienia; pilnuje podpisu „7 pełnych dób do …” na kartach giełd BTC i ETH)
            a = dict(a, d=[r for r in a.get('d') or [] if isinstance(r, list) and r and isinstance(r[0], str) and _d(r[0]) and _d(r[0]) < today])
            ds, v, u, sp = _tr_cols(a, 3, 6, 7)
            if ds:
                u = [x / 1e6 if _isnum(x) else None for x in u]      # Coin Metrics podaje USD — tu mln USD jak w pozostałych wierszach
                out.append(_tr_row('cm_' + k, 'cr', 'exch', 7, ds, v, usd=u, hold=next((x for x in reversed(sp) if _isnum(x)), None), cur=k.upper()))
        return out

    def stable():
        kr = S.get('krypto') if isinstance(S.get('krypto'), dict) else {}
        dd = {r[0]: r[1] for r in (kr.get('stabh') or {}).get('dd') or []
              if isinstance(r, list) and len(r) == 2 and _isnum(r[1]) and _d(r[0]) and _d(r[0]) < today}   # bez dzisiejszego, niezamkniętego dnia
        if len(dd) < 2:
            return []
        d0, d1 = _d(min(dd)), _d(max(dd))
        cal = [(d0 + datetime.timedelta(days=i)).isoformat() for i in range((d1 - d0).days + 1)]
        ch = [(dd[b] - dd[a]) / 1e6 if a in dd and b in dd else None for a, b in zip(cal, cal[1:])]   # mln USD; brak dnia = brak
        return [_tr_row('stab', 'cr', 'supply', 7, cal[1:], ch)]

    def cftc():
        cf = S.get('cftc') if isinstance(S.get('cftc'), dict) else {}; out = []
        for k in TR_CFTC:
            h = ((cf.get('markets') or {}).get(k) or {}).get('hist') or {}
            ds, lv = h.get('dates') or [], h.get('lev_funds') or []
            if len(ds) == len(lv) and len(ds) > 1:
                wd, wv = _tr_weeks(ds, lv, n=len(ds) + 4)
                ch = [wv[i] - wv[i - 1] if _isnum(wv[i]) and _isnum(wv[i - 1]) else None for i in range(1, len(wv))]
                r = _tr_row('cf_' + k, 'pos', 'pos', 1, wd[1:], ch, weekly_days=14, cur='CT')
                if r and _cftc_roll(r['date']):
                    r['roll'] = True; r['x'] = False       # rolowanie kontraktów kwartalnych zawyża zmiany — bez „wyjątkowo”
                out.append(r)
        su = S.get('surowce') if isinstance(S.get('surowce'), dict) else {}   # v92: surowce — fundusze zarządzające (managed money)
        for k in TR_CS:   # v295: stała (dawniej CFTCD_MARKETS)
            h = ((su.get('markets') or {}).get(k) or {}).get('hist') or {}
            ds, lv = h.get('dates') or [], h.get('mm') or []
            if len(ds) == len(lv) and len(ds) > 1:
                wd, wv = _tr_weeks(ds, lv, n=len(ds) + 4)
                ch = [wv[i] - wv[i - 1] if _isnum(wv[i]) and _isnum(wv[i - 1]) else None for i in range(1, len(wv))]
                out.append(_tr_row('cs_' + k, 'pos', 'pos', 1, wd[1:], ch, weekly_days=14, cur='CT'))
        pz = su.get('pozycje') if isinstance(su.get('pozycje'), dict) else {}   # v303: + 6 wierszy z części „pozycje” (TR_CS_POZ, świadomie)
        for k, sub in TR_CS_POZ:
            e = (pz.get(sub) or {}).get(k) if isinstance(pz.get(sub), dict) else None
            h = e.get('h') if isinstance(e, dict) and isinstance(e.get('h'), dict) else {}
            ds, lv = h.get('d') or [], h.get('net') or []       # netto funduszy zarządzających (managed money), stan na wtorek
            if isinstance(ds, list) and isinstance(lv, list) and len(ds) == len(lv) and len(ds) > 1:
                wd, wv = _tr_weeks(ds, lv, n=len(ds) + 4)
                ch = [wv[i] - wv[i - 1] if _isnum(wv[i]) and _isnum(wv[i - 1]) else None for i in range(1, len(wv))]
                out.append(_tr_row('cs_' + k, 'pos', 'pos', 1, wd[1:], ch, weekly_days=14, cur='CT'))
        return out

    def funds():
        fu = (S.get('fundusze') or {}).get('f') if isinstance(S.get('fundusze'), dict) else None
        if not isinstance(fu, dict):
            return []
        out = []
        for gid, members in TR_FE:
            inf = {}
            ds, v, aum = fund_group(fu, members, inf)
            if ds:
                r = _tr_row(gid, 'fe', 'flow', 5, ds, v, hold=aum, span=TR_SPAN, wt=inf.get('ns'))   # v293: bloki po sesjach
                if r:
                    iss = {(fu.get(t) or {}).get('iss') for t in members}   # v94: źródło grupy — wydawcy jej funduszy
                    r['iss'] = 'both' if len(iss) > 1 else (next(iter(iss)) or '')
                    lasts = {t: ((fu.get(t) or {}).get('h') or [[None]])[-1][0] for t in members}
                    top = max(x for x in lasts.values() if x)
                    for t, x in lasts.items():
                        if x and _bdays(_d(x), _d(top)) >= 5:
                            META['notes'].append(f'trendy {gid}: {t} ma dane tylko do {x} — grupa liczona do tego dnia')
                out.append(r)
        return out

    for name, fn in (('fundusze', funds), ('in', india), ('tw/hk', twhk), ('th', thai), ('br', brazil), ('tr', turkey), ('jp', japan), ('jpx', lambda: _jpx_tr_rows(S)), ('mx', mexico),
                     ('etf', etfs), ('cm', coinmetrics), ('stab', stable), ('cftc', cftc)):
        _tr_try(name, fn, rows)
    return rows


def _px_state(w, prev, typ):
    """Ceny: stan z ruchu tygodnia (w) i ruchu 4 tygodni przed nim (prev), progi względem typowego tygodniowego ruchu (typ, w %)."""
    if abs(w) < TR_PX_MIN * typ:
        return 'flat'
    pc = abs(prev) >= TR_PX_MIN * 2 * typ       # 4 tygodnie ≈ dwa razy tyle co tydzień (pierwiastek z 4)
    if w > 0:
        return 'up_cont' if pc and prev > 0 else 'dn_fade' if pc else 'up_new'
    return 'dn_cont' if pc and prev < 0 else 'up_fade' if pc else 'dn_new'


def _tr_prices(S):
    """Ceny ETF-ów krajów (Twelve Data, dzienne zamknięcia w USD) i największych kryptowalut (CoinGecko, zmiany 7 i 30 dni)
    oraz dane do „czy tydzień zapowiada następny”: pary tygodni kalendarzowych (ta sama reguła wyraźnego ruchu, bez patrzenia w przód)."""
    out, pairs = [], {'k': 0, 'n': 0, 'weeks': set(), 'from': None, 'to': None}
    today = _now_utc().date()
    cur = today - datetime.timedelta(days=today.weekday())
    ce = S.get('ceny') if isinstance(S.get('ceny'), dict) else {}
    for sym in TR_PX_SYMS:
        d = [r for r in ((ce.get('q') or {}).get(sym) or {}).get('d') or []
             if isinstance(r, list) and len(r) > 1 and _isnum(r[1]) and r[1] > 0 and _d(r[0])]
        if len(d) < 26:
            continue
        c = [r[1] for r in d]
        wk = [(c[-1 - 5 * i] / c[-1 - 5 * (i + 1)] - 1) * 100 for i in range(min(TR_PX_WEEKS + 1, (len(c) - 1) // 5))]   # [ten tydzień, poprzedni, …]
        if len(wk) < 21:
            continue
        typ = _sd(wk[1:])
        prev = (c[-6] / c[-26] - 1) * 100
        z = wk[0] / typ if typ > 0 else None
        out.append({'id': sym, 'g': 'eq', 'date': d[-1][0], 'w': round(wk[0], 2), 'pr': round(prev, 2), 'typ': round(typ, 2),
                    'z': round(z, 2) if z is not None else None, 'st': _px_state(wk[0], prev, typ) if typ > 0 else 'flat'})
        lastc = {}                                   # tygodnie kalendarzowe: zamknięcie ostatniej sesji tygodnia, bez bieżącego tygodnia
        for r in d:
            m = _d(r[0]) - datetime.timedelta(days=_d(r[0]).weekday())
            if m < cur:
                lastc[m] = r[1]
        ms = sorted(lastc)
        ret = [(ms[i], (lastc[ms[i]] / lastc[ms[i - 1]] - 1) * 100) for i in range(1, len(ms)) if (ms[i] - ms[i - 1]).days == 7]
        for i in range(len(ret) - 1):
            past = [x for _, x in ret[max(0, i - TR_PX_WEEKS):i]]
            if len(past) < 20 or (ret[i + 1][0] - ret[i][0]).days != 7:
                continue
            (m0, a), (m1, b) = ret[i], ret[i + 1]
            if abs(a) >= TR_PX_MIN * _sd(past):
                pairs['n'] += 1; pairs['k'] += 1 if a * b > 0 else 0; pairs['weeks'].add(m0)
                pairs['from'] = min(pairs['from'] or m0, m0); pairs['to'] = max(pairs['to'] or m1, m1)
    fu = (S.get('fundusze') or {}).get('f') if isinstance(S.get('fundusze'), dict) else None   # v93: cena jednostki (NAV) największego funduszu grupy
    if isinstance(fu, dict):
        for gid, members in TR_FE:
            if gid not in TR_FP:
                continue
            cand = [(t, _fund_px_rows(t, _fund_rows((fu.get(t) or {}).get('h')))) for t in members]   # v221: bez pojedynczych wierszy z błędem pliku
            cand = [(t, h) for t, h in cand if len(h) >= 5 * 21 + 1]        # v94: tylko fundusz z historią na cały rachunek i z bieżącą datą
            newest = max((h[-1][0] for _, h in cand), default=None)
            cand = [(t, h) for t, h in cand if _bdays(_d(h[-1][0]), _d(newest)) <= 3]
            best = max(cand, key=lambda c: c[1][-1][1] * c[1][-1][2], default=None)
            if not best:
                continue
            cal = [r[0] for r in _fund_rows((fu.get(best[0]) or {}).get('h')) if r[0] <= best[1][-1][0]][-(5 * (TR_PX_WEEKS + 1) + 1):]   # v293: sesje
            h = [r for r in best[1] if r[0] >= cal[0]]      # pliku (także dni ze złym wierszem) — okno liczone w sesjach, nie w wierszach
            px, f = {h[-1][0]: h[-1][1]}, 1.0              # NAV w jednostkach po ostatnim podziale; skok bez wyjaśnienia ucina starszą część
            P = fund_pary(best[1])                          # v235: pary z całej historii — pierwsza para wycinka widzi dzień przed sobą
            for (a, b), k in zip(zip(reversed(h[:-1]), reversed(h[1:])), reversed(P[-(len(h) - 1):])):   # v233: podział na dwa dni = skok
                if not k:
                    META['notes'].append(f'trendy {best[0]}: skok NAV bez podziału jednostek ({b[0]}) — cena liczona od tego dnia'); break
                f *= k; px[a[0]] = a[1] / f
            c = [px.get(d) for d in cal if d >= min(px)]   # v293: zły wiersz = brak ceny tego dnia; tydzień = 5 SESJI (dotąd 5 wierszy — z pominiętym
            if len(c) < 26:                                 # wierszem 6 sesji: EWZ 06.10.2026 +18,62% zamiast +17,85%)
                continue
            R = lambda i, j: (c[i] / c[j] - 1) * 100 if c[i] and c[j] else None   # noqa: E731 — brak na którymkolwiek końcu = brak, nie zero
            wk = [R(-1 - 5 * i, -1 - 5 * (i + 1)) for i in range(min(TR_PX_WEEKS + 1, (len(c) - 1) // 5))]
            prev = R(-6, -26)
            ok = [x for x in wk[1:] if x is not None]
            if wk and (wk[0] is None or prev is None):
                META['notes'].append(f'trendy {best[0]}: zamknięcie sprzed 5 albo 25 sesji z błędem pliku — cena tygodniowa bez oceny')
            if len(ok) < 20:
                continue
            typ = _sd(ok)
            if wk[0] is None or prev is None:   # v296: karta zostaje — „—” (albo znana zmiana tygodnia) z datą, stan 'gap' bez oceny; dotąd znikała,
                g = {'id': 'fp_' + gid[3:], 'g': 'fp', 'sym': best[0], 'date': best[1][-1][0], 'typ': round(typ, 2), 'z': None, 'st': 'gap'}   # a kafel
                if wk[0] is not None:                                                                                       # rynków wybierał
                    g['w'] = round(wk[0], 2)                                                                                # inny rynek bez słowa
                if prev is not None:
                    g['pr'] = round(prev, 2)
                out.append(g)
                continue
            z = wk[0] / typ if typ > 0 else None
            out.append({'id': 'fp_' + gid[3:], 'g': 'fp', 'sym': best[0], 'date': best[1][-1][0], 'w': round(wk[0], 2), 'pr': round(prev, 2),
                        'typ': round(typ, 2), 'z': round(z, 2) if z is not None else None, 'st': _px_state(wk[0], prev, typ) if typ > 0 else 'flat'})
    kr = S.get('krypto') if isinstance(S.get('krypto'), dict) else {}
    mk = kr.get('mk') or {}
    cols = mk.get('cols') or []
    if all(c in cols for c in ('sym', 'p7d', 'p30d')):
        i_s, i7, i30 = cols.index('sym'), cols.index('p7d'), cols.index('p30d')
        by = {}
        for r in mk.get('rows') or []:      # wiersze od największej kapitalizacji — przy powtórzonym symbolu zostaje pierwszy
            if isinstance(r, list) and len(r) == len(cols):
                by.setdefault(str(r[i_s]).upper(), r)
        for sym in TR_CR_SYMS:
            r = by.get(sym)
            if not r or not _isnum(r[i7]) or not _isnum(r[i30]) or r[i7] <= -100:
                continue
            prev = ((1 + r[i30] / 100) / (1 + r[i7] / 100) - 1) * 100     # 23 dni przed ostatnim tygodniem
            mk_at = (kr.get('part_at') or {}).get('mk') if isinstance(kr.get('part_at'), dict) else None   # v281: czas pobrania części 'mk'
            out.append({'id': sym, 'g': 'cr', 'date': str(mk_at or kr.get('at') or '')[:10], 'w': round(r[i7], 2), 'pr': round(prev, 2), 'z': None,
                        'st': _px_state(r[i7], prev, TR_CR_TYP)})
    return out, pairs


def build_trendy(S):
    """data/trendy.json — przepływy (f), ceny (p) i „czy tydzień zapowiada następny” (b) z obiektów zapisanych w tym przebiegu."""
    S = S if isinstance(S, dict) else {}
    today = _now_utc().date()
    flows = _tr_flows(S)
    prices, pp = [], {'k': 0, 'n': 0, 'weeks': set(), 'from': None, 'to': None}
    try:
        prices, pp = _tr_prices(S)
    except Exception as e:
        META['notes'].append(mask(f'trendy ceny: {e}'))
    base = []
    ob = S.get('obce') if isinstance(S.get('obce'), dict) else {}
    try:
        if ob.get('th'):
            ds, v = _tr_cols(ob['th'], 1)
            k, n, a, b = trend_persist(ds, v, today)
            if n:
                base.append({'id': 'th', 'kind': 'flow', 'k': k, 'n': n, 'weeks': n, 'from': a, 'to': b, 'ci': list(wilson(k, n))})
        md = [r for r in ((S.get('meksyk') or {}).get('d') or []) if isinstance(r, list) and len(r) > 1 and isinstance(r[0], str)]
        if len(md) > 1:
            ch = [md[i][1] - md[i - 1][1] if _isnum(md[i][1]) and _isnum(md[i - 1][1]) else None for i in range(1, len(md))]
            k, n, a, b = trend_persist([r[0] for r in md[1:]], ch, today)
            if n:
                base.append({'id': 'mx', 'kind': 'flow', 'k': k, 'n': n, 'weeks': n, 'from': a, 'to': b, 'ci': list(wilson(k, n))})
    except Exception as e:
        META['notes'].append(mask(f'trendy historia: {e}'))
    try:                                  # v95: dzienne przepływy krajów razem — niepewność liczona na tygodnie
        K = N = 0; wk = set(); a0 = b0 = None
        for part, col in TR_OB:
            if not isinstance(ob.get(part), dict):
                continue
            ds, v = _tr_sessions(ob[part], col) if part in ('tw', 'hk') else _tr_cols(ob[part], col)
            k, n, a, b = trend_persist(ds, v, today, wk)
            K += k; N += n
            if n:
                a0 = min(a0 or a, a); b0 = max(b0 or b, b)
        if N:
            base.append({'id': 'ob', 'kind': 'flow', 'k': K, 'n': N, 'weeks': len(wk), 'from': a0, 'to': b0, 'ci': list(wilson(K, N, n_eff=len(wk)))})
    except Exception as e:
        META['notes'].append(mask(f'trendy historia krajów: {e}'))
    try:                                  # v90: fundusze ETF — wszystkie grupy razem, niepewność liczona na tygodnie
        fu = (S.get('fundusze') or {}).get('f') if isinstance(S.get('fundusze'), dict) else None
        if isinstance(fu, dict):
            K = N = 0; wk = set(); a0 = b0 = None
            for gid, members in TR_FE:
                inf = {}
                ds, v, _ = fund_group(fu, members, inf)
                k, n, a, b = trend_persist(ds, v, today, wk, inf.get('d0'))   # v296: tygodnie z wartością z sesji dwóch tygodni — poza parami
                K += k; N += n
                if n:
                    a0 = min(a0 or a, a); b0 = max(b0 or b, b)
            if N:
                base.append({'id': 'fe', 'kind': 'flow', 'k': K, 'n': N, 'weeks': len(wk), 'from': a0, 'to': b0, 'ci': list(wilson(K, N, n_eff=len(wk)))})
    except Exception as e:
        META['notes'].append(mask(f'trendy historia funduszy: {e}'))
    if pp['n']:
        nw = len(pp['weeks'])            # rynki są ze sobą powiązane: niepewność liczona na tygodnie, nie na pary rynek-tydzień
        base.append({'id': 'px', 'kind': 'price', 'k': pp['k'], 'n': pp['n'], 'weeks': nw, 'from': pp['from'].isoformat(),
                     'to': pp['to'].isoformat(), 'ci': list(wilson(pp['k'], pp['n'], n_eff=nw))})
    daily = {'dv': TD_V, 'dsince': TD_SINCE, 'dr': _td_rules(), 'd': None, 'bd': None}   # v120: sygnały dzienne (ten sam przebieg, ten sam `at`)
    try:
        daily['d'], daily['bd'] = build_daily(S)
    except Exception as e:
        daily['d'] = daily['bd'] = None     # awaria to nie „zero rynków”: null w pliku (strona ukrywa blok), nigdy pusta lista
        META['notes'].append(mask(f'trendy dziennie: {e}'))
    try:                                  # v123: rodzina krypto — dopisana na końcu d i bd; awaria nie rusza wierszy i linii świata
        try:
            cd, cb = build_daily_cr(S)                       # v1 (sam ruch ceny, od zamknięcia do zamknięcia) — zawsze, bez sieci
        except Exception as e1:
            META['notes'].append(mask(f'trendy dziennie krypto: {e1}')); cd = cb = None
        kd = S.get('krypto-dzien') if isinstance(S.get('krypto-dzien'), dict) else None
        if kd and kd.get('ready') is True:                   # v125: wersja 2 dopiero po pełnym dopełnieniu pliku dziennego (flaga trwała)
            try:
                cd2, cb2 = build_daily_cr2(S)
            except Exception as e2:
                META['notes'].append(mask(f'trendy dziennie krypto v2: {e2}')); cd2 = cb2 = None
            if cd2:                                          # karty v2 PO kartach v1, linie v2 po linii v1 (v: 1, tuż po liniach świata; jej licznik
                cd, cb = (cd or []) + cd2, (cb or []) + cb2  # od TD_SINCE_CR liczy się dalej). Karta przeglądarki sprzed v125 odrzuca każdy wiersz v2
                                                             # (reguły c/cx/c0) i pokazuje sekcję v1 jak dotąd; strona v125 bierze tylko karty v2
        if cd:
            daily['d'] = (daily['d'] or []) + cd
            daily['bd'] = (daily['bd'] or []) + cb
    except Exception as e:
        META['notes'].append(mask(f'trendy dziennie krypto: {e}'))
    wd2 = S.get('swiat-dzien') if isinstance(S.get('swiat-dzien'), dict) else None
    if wd2 and wd2.get('ready') is True and not any(isinstance(b, dict) and b.get('fam') in TD_FAM_W for b in (daily['bd'] or [])):
        META['notes'].append('trendy dziennie świat v2: pominięte — brak linii wersji 1 (stara karta czytałaby linie v2 jako linie v1)')
    elif wd2 and wd2.get('ready') is True:                   # v127: świat — wersja 2 dopiero po dopełnieniu pliku dziennego (flaga trwała)
        try:
            wr2, wl2 = build_daily_w2(S)
        except Exception as e:
            META['notes'].append(mask(f'trendy dziennie świat v2: {e}')); wr2 = wl2 = None
        if wr2:                                              # karty v2 (reguły c / cx / c0 — strona sprzed v127 ich nie przyjmuje) przed kartami v1
            daily['d'] = wr2 + (daily['d'] or [])            # świata i krypto, które zostają bez zmian (stara karta przeglądarki czyta wersję 1);
            daily['bd'] = (daily['bd'] or []) + wl2          # 7 linii v1 świata na początku bd (licznik od TD_SINCE liczy się dalej), linie v2 na końcu
    su_td = None
    try:                                  # v303: SUROWCE — blok reguł „w cieniu” TD_SH_SU (dziennik _SUT_LOG; strona: opis, licznik, data rejestracji)
        su_td = _sut_build(S)
    except Exception as e:
        _SUT_LOG[1] = None                 # awaria bloku nie rusza reszty pliku; poprzedni dziennik zostaje (main)
        META['notes'].append(mask(f'trendy surowce (w cieniu): {e}'))
    ng_td = None
    try:                                  # v373: nowe grupy — blok reguł „w cieniu” TD_SH_NG (dziennik _NGT_LOG; strona: opis, licznik, data rejestracji)
        ng_td = _ngt_build(S)
    except Exception as e:
        _NGT_LOG[1] = None                 # awaria bloku nie rusza reszty pliku; poprzedni dziennik zostaje (main)
        META['notes'].append(mask(f'trendy nowe grupy (w cieniu): {e}'))
    fw_td = None
    try:                                  # v413: najnowsze źródła — blok reguł „w cieniu” TD_SH_FW (dziennik _FWT_LOG; strona: opis, licznik, data rejestracji)
        fw_td = _fwt_build(S)
    except Exception as e:
        _FWT_LOG[1] = None                 # awaria bloku nie rusza reszty pliku; poprzedni dziennik zostaje (main)
        META['notes'].append(mask(f'trendy najnowsze źródła (w cieniu): {e}'))
    return {'at': NOW, 'v': 1, 'src': 'CapitalFlowAI — obliczenia z plików tej strony (fundusze, obce, meksyk, instytucje, kursy, etf, cm, krypto, cftc, surowce, ceny)',
            'rules': {'base_min': TR_BASE_MIN, 'base_max': TR_BASE_MAX, 'dir': TR_DIR, 'all': TR_ALL, 'floor': TR_FLOOR, 'strong': TR_STRONG,
                      'exc': TR_EXC, 'day_z': TR_DAY_Z, 'span': TR_SPAN, 'px_min': TR_PX_MIN, 'cr_typ': TR_CR_TYP},
            'f': flows, 'p': prices, 'b': base, **daily, **({'su': su_td} if su_td else {}), **({'ng': ng_td} if ng_td else {}), **({'fw': fw_td} if fw_td else {})}   # v303: su tylko, gdy blok policzony


# ===================== v303: SUROWCE w TRENDACH — blok „w cieniu” TD_SH_SU (dział SUROWCE, etap 7) =====================
# Rejestracja z góry: checkpoints/REGULY_SUROWCE_2026-10-08_PL.md (suma SHA-256 dokumentu w SUT_SHA) — lista zamknięta 08.10.2026, przed
# jakimkolwiek wynikiem. Trafności tych linii NIE liczymy na historii (nie ma testu „w próbie”): jedyne źródło ocen to dziennik
# data/surowce-dziennik.json z kartami liczonymi na żywo od wdrożenia. Karta sesji (świat) / doby (krypto) jest liczona w każdym przebiegu
# PRZED swoją granicą (09:00 NY / 05:30 UTC) z danych, które w tej chwili są w plikach strony, i zamrażana na granicy (saved_at = chwila
# wyliczenia); karta, której przed granicą nie było, trafia do dziennika „po czasie” — bez głosu. Dzień danych głosuje najwyżej raz w linii
# (najnowszy, którego wcześniejsza karta nie użyła; za stary — wcale). Progi wyłącznie ze stałych reguł głównych (TD_LB, TD_MIN, TD_Z1, TD_Z2,
# TD_FLOOR, TD_GAP); własny Bonferroni: m = 4 linie × 3 oceny = 12; punkty kontrolne 100/200/400 dni z sygnałem zamrażane raz; strona pokazuje
# tylko opis, licznik i datę rejestracji — linię dopiero z werdyktem „przewaga” w punkcie 200 (TD_SH_JAWNE). Linie cm.p i cm.f biorą dane
# funduszy surowcowych z części px i fl pliku swiat-dzien — od v309 zbiera je build_swiat_dzien (WD_SU_PX; WD_SU_FL z części 'su' pliku
# fundusze); bez danych linia czeka, z danymi rusza sama (reguły, kierunki, progi i SUT_SHA bez zmian). Bez zapytań do sieci.
SUT_V = 1                       # wersja bloku (zmiana linii albo reguły = nowa rejestracja, nowa wersja; stare oceny zostają w 'prev')
SUT_REG = '2026-10-08'          # data rejestracji (dokument z sumą SHA-256)
SUT_SINCE = '2026-10-08'        # najwcześniejsza data karty w dzienniku (sesja docelowa świata / doba karty krypto)
# SHA-256 pliku checkpoints/REGULY_SUROWCE_2026-10-08_PL.md (dokument rejestracji, zatwierdzony w repozytorium projektu przed wdrożeniem kodu)
SUT_SHA = '79d4eef13ba7fc33f0630fdb323baf3979e55007a8d120ad9213f8811630fe5b'
SUT_CM_PX = ('GSG', 'CMDY', 'COMT', 'DBC', 'USO', 'CPER', 'DBA')   # fundusze surowcowe — ruch ceny (su.cm.p)
SUT_CM_FL = ('GSG', 'CMDY', 'COMT')                               # fundusze surowcowe iShares — przepływ (su.cm.f)
TD_SH_SU = (('cm.p', 'w', 'px', 1, TD_Z1), ('cm.f', 'w', 'fl', 1, TD_Z1), ('eq.cu', 'w', 'cuau', 1, TD_Z1), ('cr.au', 'cr', 'au', 1, TD_Z2))
#            (nazwa, rodzina: 'w' sesja NYSE / 'cr' doba krypto, wejście, kierunek z góry, próg |z|) — lista zamknięta 08.10.2026
SUT_M = len(TD_SH_SU) * len(TD_W_LOOKS)                                   # 12 prób naraz (4 linie × 3 oceny) — także linie jeszcze bez danych
SUT_ZL = statistics.NormalDist().inv_cdf(1 - 0.025 / SUT_M)            # 2,8653
SUT_CLL = round(100 - 5 / SUT_M, 1)                                     # 99.6
SUT_EQ = tuple(s for s in TD_W_SYMS if _tdw_fam(s) == 'eq')             # 33 rynki rodziny „eq” (wynik su.eq.cu: średnia ich sesji)
SUT_ZW_W = 1      # sesje NYSE: pierwsza sesja, w której wejście mogło głosować (po publikacji), najwyżej tyle sesji przed sesją karty — dla
                  # zamknięć i ceny złota: dzień danych najwyżej 2 sesje przed kartą (dostępność danych, nie próg sygnału)
SUT_ZW_CR = 3     # doby: pierwsza doba krypto, w której wejście mogło głosować, najwyżej tyle dób przed dobą karty (j.w.)
# publikacja wejścia z datą d (stanu albo dnia): (dni po d, minuty po północy, strefa); w tygodniu ze świętem (dzień bez sesji NYSE między
# d a dniem publikacji) — ostrożnie dzień roboczy później. Zamknięcie dnia: 16:00 NY; LBMA PM: 15:00 UTC (15:00 w Londynie zimą, 14:00 UTC
# latem — górna granica); pliki wydawców funduszy: 23:59 NY; CFTC i ICE (stan na wtorek): piątek 15:30 NY; EIA WPSR (stan na piątek): środa 10:30 NY
SUT_PUB = {'close': (0, 960, 'ny'), 'lbma': (0, 900, 'utc'), 'ishares': (0, 1439, 'ny'), 'cftc': (3, 930, 'ny'), 'ice': (3, 930, 'ny'),
           'wpsr': (5, 630, 'ny')}
SUT_KIND = {'px': ('close',), 'fl': ('ishares',), 'cuau': ('close', 'lbma'), 'au': ('lbma',)}   # wejście linii → rodzaje publikacji
SUT_CSV = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'archiwum', 'surowce-dziennik.csv')   # kopia dzienna (narzedzia/archiwum.py)
SUT_CSV_COLS = ['date', 'line', 'sym', 'g', 'state', 'z', 'saved_at', 'y', 'dd', 'v', 'reg']
SUT_JST = ('ok', 'late')        # stany wiersza: ok — karta przed granicą (głos albo spokój), late — po czasie (bez głosu)
_SUT_LOG = [None, None]         # [poprzedni dziennik (main, przed trendami), nowy dziennik (_sut_build)]


def _sut_pub(kind, d):
    """Chwila publikacji (UTC, 'YYYY-MM-DDTHH:MM:SS') wejścia rodzaju `kind` z datą d. Dzień bez sesji NYSE (TD_NYSE_CLOSED) w (d, dzień
    publikacji] albo publikacja w sobotę/niedzielę — dzień roboczy później (ostrożnie, nigdy wcześniej)."""
    dd, m, tz = SUT_PUB[kind]
    p = _d(d) + datetime.timedelta(days=dd)
    if dd:
        if any((_d(d) + datetime.timedelta(days=k)).isoformat() in TD_NYSE_CLOSED for k in range(1, dd + 1)):
            p += datetime.timedelta(days=1)
        while p.weekday() >= 5 or p.isoformat() in TD_NYSE_CLOSED:
            p += datetime.timedelta(days=1)
    if tz == 'utc':
        return p.isoformat() + 'T%02d:%02d:00' % divmod(m, 60)
    return _tdw_at(p.isoformat(), m)


def _sut_sesja_pub(kind, d):
    """Pierwsza sesja NYSE, w której karta (granica 09:00 NY) może użyć wejścia `kind` z datą d — pierwsza sesja z granicą po publikacji."""
    pub = _sut_pub(kind, d)
    s = pub[:10] if _d(pub[:10]).weekday() < 5 and pub[:10] not in TD_NYSE_CLOSED else _tdw_next(pub[:10])
    return s if _tdw_cut(s) > pub else _tdw_next(s)


def _sut_doba_pub(kind, d):
    """Pierwsza doba krypto D′, której karta (granica 05:30 UTC doby D′+1) może użyć wejścia `kind` z datą d."""
    pub = datetime.datetime.strptime(_sut_pub(kind, d), '%Y-%m-%dT%H:%M:%S')
    return (pub - datetime.timedelta(minutes=TD_CR_CUT)).date().isoformat()


def _sut_iso(now_utc):
    n = now_utc.astimezone(datetime.timezone.utc) if getattr(now_utc, 'tzinfo', None) else now_utc.replace(tzinfo=datetime.timezone.utc)
    return n.replace(microsecond=0).strftime('%Y-%m-%dT%H:%M:%SZ')


def _sut_cel(fam, now_utc):
    """Karta liczona teraz: świat — pierwsza sesja NYSE z granicą (09:00 NY) po teraz; krypto — doba danych D′ z granicą (05:30 UTC D′+1) po teraz."""
    n19 = _sut_iso(now_utc)[:19]
    if fam == 'cr':
        return (datetime.datetime.strptime(n19, '%Y-%m-%dT%H:%M:%S') - datetime.timedelta(minutes=TD_CR_CUT)).date().isoformat()
    d = _wd_ny(now_utc if getattr(now_utc, 'tzinfo', None) else now_utc.replace(tzinfo=datetime.timezone.utc)).date().isoformat()
    if _d(d).weekday() < 5 and d not in TD_NYSE_CLOSED and n19 < _tdw_cut(d):
        return d
    return _tdw_next(d)


def _sut_poprz(fam, cel):
    return _wd_prev_session(cel) if fam == 'w' else (_d(cel) - datetime.timedelta(days=1)).isoformat()


def _sut_granica(fam, cel):
    return _tdw_cut(cel) if fam == 'w' else _td_cut(cel)


def _sut_koniec(fam, cel):
    """Koniec karty (po nim nie zapisujemy już karty „po czasie”): świat — 16:15 NY (13:15 w sesji skróconej); krypto — 06:00 UTC doby D′+2."""
    if fam == 'w':
        return _tdw_end(cel)
    return (_d(cel) + datetime.timedelta(days=2)).isoformat() + 'T%02d:00:00' % TD_CR_WH


def _sut_ser(rows, k=1):
    """Wiersze [dzień, …, wartość w kolumnie k, …] → posortowane [(dzień, wartość > 0)]; brak, zero i zły dzień pominięte (nigdy 0)."""
    by = {}
    for r in rows or []:
        if isinstance(r, list) and len(r) > k and isinstance(r[0], str) and _d(r[0]) and _isnum(r[k]) and r[k] > 0:
            by[str(r[0])[:10]] = float(r[k])
    return sorted(by.items())


def _sut_zm(ser, split=False):
    """[(dzień, wartość)] → [(dzień, zmiana w % | None)] wobec poprzedniego dnia z wartością; dalej niż TD_GAP dni = None; split — iloraz
    bliski ułamkowi podziału jednostek = None (_tdw_mv). Tylko dzień i dzień przed nim — nic z dni późniejszych."""
    out = []
    for i, (d, v) in enumerate(ser):
        if not i or (_d(d) - _d(ser[i - 1][0])).days > TD_GAP:
            out.append((d, None)); continue
        pv = ser[i - 1][1]
        out.append((d, _tdw_mv(pv, v) if split else (v / pv - 1) * 100))
    return out


def _sut_fl(rows):
    """Wiersze pliku wydawcy [dzień, NAV, jednostki, …] → [(dzień, przepływ mln USD | None)] (fund_flows: złe wiersze i podziały wykrywane
    tylko z dni wcześniejszych); poprzedni wiersz dalej niż TD_GAP dni albo dzień bez przepływu = None."""
    h = [[r[0], r[1], r[2]] for r in rows or [] if isinstance(r, list) and len(r) >= 3]
    h = sorted({str(r[0])[:10]: r for r in h if isinstance(r[0], str)}.values(), key=lambda r: r[0])
    k = _fund_rows(h)
    fl = fund_flows(k)
    out = []
    for a, b in zip(k, k[1:]):
        ok = (_d(b[0]) - _d(a[0])).days <= TD_GAP
        out.append((b[0], fl.get(b[0]) if ok else None))
    return out


def _sut_wejscia(S):
    """Wejścia linii z plików tego przebiegu → {(linia, symbol): ([(dzień, zmiana | przepływ | None)], demean)}. Brak pliku albo serii = brak wpisu."""
    out = {}
    su = S.get('surowce') if isinstance(S.get('surowce'), dict) else {}
    ce = su.get('ceny') if su.get('v') == SU_V and isinstance(su.get('ceny'), dict) else {}
    au = _sut_ser(((ce.get('gold') or {}) if isinstance(ce.get('gold'), dict) else {}).get('d'))
    cu = _sut_ser(((ce.get('copper') or {}) if isinstance(ce.get('copper'), dict) else {}).get('d'))
    if len(au) > 1:
        out[('cr.au', 'BTC')] = (_sut_zm(au), False)
    A = dict(au)
    ra = [(d, v / A[d]) for d, v in cu if d in A]                # stosunek miedź/złoto tylko z dni, w których są obie ceny
    if len(ra) > 1:
        out[('eq.cu', 'EQ')] = (_sut_zm(ra), False)
    wd = S.get('swiat-dzien') if isinstance(S.get('swiat-dzien'), dict) else {}
    for sym in SUT_CM_PX:
        c = _sut_ser((((wd.get('px') or {}).get(sym) or {}).get('d')), 2)
        if len(c) > 1:
            out[('cm.p', sym)] = (_sut_zm(c, split=True), False)
    for sym in SUT_CM_FL:
        f = _sut_fl((((wd.get('fl') or {}).get(sym) or {}).get('d')))
        if f:
            out[('cm.f', sym)] = (f, True)
    return out


def _sut_karta(ch, demean, thr, kinds, cel, fam, prev_dd):
    """Karta linii dla sesji/doby `cel` z serii wejścia ch → (głos przed kierunkiem, z, dzień danych) albo None (brak karty). Dzień danych =
    najnowszy dzień serii przed kartą (świat: < cel; krypto: ≤ cel), którego publikacja jest przed granicą karty; zużyty przez wcześniejszą
    kartę (≤ prev_dd) albo za stary (pierwsza sesja / doba, w której mógł głosować, wcześniej niż SUT_ZW_W sesji / SUT_ZW_CR dób przed
    kartą) = brak karty. z z najwyżej TD_LB poprzednich wartości serii (_td_z; ruch ceny bez odejmowania średniej, przepływ ze średnią
    i dolną granicą rozrzutu)."""
    cut = _sut_granica(fam, cel)

    def wolno(d):
        return (d < cel if fam == 'w' else d <= cel) and all(_sut_pub(k, d) < cut for k in kinds)
    i = len(ch) - 1
    while i >= 0 and not wolno(ch[i][0]):
        i -= 1
    if i < 0:
        return None
    d = ch[i][0]
    lo = cel
    if fam == 'w':
        for _ in range(SUT_ZW_W):
            lo = _wd_prev_session(lo)
        first = max(_sut_sesja_pub(k, d) for k in kinds)
    else:
        lo = (_d(cel) - datetime.timedelta(days=SUT_ZW_CR)).isoformat()
        first = max(_sut_doba_pub(k, d) for k in kinds)
    if first < lo or (prev_dd and d <= prev_dd):
        return None
    z = _td_z([x for _, x in ch], i, demean)
    if z is None:
        return None
    return ((1 if z > 0 else -1) if abs(z) >= thr else 0), z, d


def _sut_valid(log):
    return isinstance(log, dict) and isinstance(log.get('rows'), list) and 'v' in log and 'reg' in log


def _sut_rows(log):
    """Poprawne wiersze dziennika: [dzień, linia, symbol, głos, stan, z, zapisano, y, dzień danych]."""
    return [list(r) for r in ((log or {}).get('rows') or []) if isinstance(r, list) and len(r) == 9 and isinstance(r[0], str) and _d(r[0])
            and r[1] in {n for n, *_ in TD_SH_SU} and isinstance(r[2], str) and r[4] in SUT_JST]


def _sut_oc(wd, syms):
    """Wyniki sesji (otwarcie→zamknięcie, %) z pliku swiat-dzien → {symbol: {sesja: wynik | None}} (wiersz pliku = pierwsza publikacja)."""
    px = (wd or {}).get('px') or {}
    return {s: {r[0]: _tdw_oc(r[1], r[2]) for r in ((px.get(s) or {}).get('d') or []) if isinstance(r, list) and len(r) >= 3 and isinstance(r[0], str)}
            for s in syms}


def _sut_y_w(oc, T, sym, now19):
    """Wynik sesji T z indeksu _sut_oc: fundusz — jego sesja; 'EQ' — średnia 33 rynków rodziny eq, gdy mają ją wszystkie, a od WD_GAP_H
    (48 h) po zamknięciu sesji — gdy ma ją co najmniej WD_MIN_SHARE (90%) z nich. Brak → None (nigdy 0)."""
    if sym != 'EQ':
        return (oc.get(sym) or {}).get(T)
    ys = [y for y in ((oc.get(s) or {}).get(T) for s in SUT_EQ) if y is not None]
    late = now19 >= (datetime.datetime.strptime(_tdw_at(T, TD_W_CLOSE), '%Y-%m-%dT%H:%M:%S') + datetime.timedelta(hours=WD_GAP_H)).strftime('%Y-%m-%dT%H:%M:%S')
    if ys and (len(ys) == len(SUT_EQ) or (late and len(ys) >= WD_MIN_SHARE * len(SUT_EQ))):
        return sum(ys) / len(ys)
    return None


def _sut_ut_w(wd, name):
    """Udział sesji wzrostowych w TD_W_UT sesjach przed parą (b0t, jak reguły świata) z pliku swiat-dzien → {symbol: {sesja: udział}}."""
    cal = [c for c in ((wd or {}).get('cal') or []) if isinstance(c, str)]
    if not cal:
        return None
    by = _sut_oc(wd, SUT_EQ if name == 'eq.cu' else SUT_CM_PX)
    if name == 'eq.cu':
        ys = []
        for c in cal:
            v = [by[s].get(c) for s in SUT_EQ if by[s].get(c) is not None]
            ys.append(sum(v) / len(v) if v and len(v) >= WD_MIN_SHARE * len(SUT_EQ) else None)
        ser = [{'id': 'EQ', 'dates': cal, 'y': ys}]
    else:
        ser = [{'id': s, 'dates': cal, 'y': [by[s].get(c) for c in cal]} for s in SUT_CM_PX if by[s]]
    return _tdw_ut(ser)


def _sut_pary(rows, name, since, upto=None):
    """Wiersze linii → (pary [(dzień, trafienie, symbol, głos)], ys {symbol: {dzień: y}}): para — karta na czas z głosem i wynikiem ≠ 0;
    ys — każdy wiersz z wynikiem (zwykła sesja/doba okresu)."""
    pr, ys = [], {}
    for d, ln, sym, g, st, z, at, y, dd in rows:
        if ln != name or d < since or (upto and d > upto) or not _isnum(y):
            continue
        ys.setdefault(sym, {})[d] = y
        if st == 'ok' and g and y != 0:
            pr.append((d, 1 if (y > 0) == (g > 0) else 0, sym, g))
    return pr, ys


def _sut_cp(log, rows, today, iso, wd):
    """Punkty kontrolne 100/200/400 dni z sygnałem (wiersze dojrzałe: świat ≥ TD_W_SETTLE, krypto ≥ TD_CR_SETTLE dni) przy z = SUT_ZL:
    [c, k, n, b0, h1, h2, lo, hi, vd, dzień c, zapisano, b0t, próg] — zapis raz, nigdy liczone od nowa (jak _tdw_sh_cp)."""
    cp = {k: [list(x) for x in v if isinstance(x, list) and len(x) == 13] for k, v in ((log or {}).get('cp') or {}).items()}
    for name, fam, *_ in TD_SH_SU:
        settle = TD_W_SETTLE if fam == 'w' else TD_CR_SETTLE
        pr, ys = _sut_pary(rows, name, SUT_SINCE, (today - datetime.timedelta(days=settle)).isoformat())
        pr = sorted(pr); ds = sorted({p[0] for p in pr}); have = {x[0] for x in cp.get(name, [])}
        ut = None
        for c in TD_W_LOOKS:
            if c in have or len(ds) < c:
                continue
            q = [p for p in pr if p[0] <= ds[c - 1]]
            if fam == 'w':
                ut = ut if ut is not None else (_sut_ut_w(wd, name) or {})
                S_ = _tdw_stat(q, ys, SUT_ZL, ut)
                ne = S_['ne']; b0t = None if S_['b0t'] is None else round(S_['b0t'], 1)
            else:
                S_ = _td_stat(q, ys, SUT_ZL)
                ne = S_['days']; b0t = None
            bm = S_['bm']
            thr = round(bm + 100 * SUT_ZL * math.sqrt(bm / 100 * (1 - bm / 100) / ne), 1) if ne else None
            cp.setdefault(name, []).append([c, S_['k'], S_['n'], None if S_['b0'] is None else round(S_['b0'], 1), S_['h1'], S_['h2'],
                                            S_['ca'][0], S_['ca'][1], S_['vd'], ds[c - 1], iso, b0t, thr])
    return {k: sorted(v) for k, v in cp.items() if v}


def _sut_log(log, S, now_utc):
    """Dziennik bloku: karty liczone na żywo przed granicą (nadpisywane do granicy, potem zamrożone), karta bez wiersza przed granicą →
    „po czasie” (bez głosu, tylko gdy dziennik istniał przed tą granicą), wyniki dopisywane raz, punkty kontrolne raz, postęp (pg).
    Inna wersja albo rejestracja → nowy dziennik, stare oceny w 'prev'. Nie zmienia S."""
    log = log if _sut_valid(log) else {}
    prevs = [x for x in (log.get('prev') or []) if isinstance(x, dict)] if isinstance(log.get('prev'), list) else []
    if log and (log.get('v') != SUT_V or log.get('reg') != SUT_REG):
        prevs = prevs + [{'v': log.get('v'), 'reg': log.get('reg'), 'cp': log.get('cp') or {}, 'n': len(log.get('rows') or [])}]
        log = {}
    iso = _sut_iso(now_utc); n19 = iso[:19]; today = _d(iso)
    was = log.get('at') if isinstance(log.get('at'), str) else None
    R = {(r[0], r[1], r[2]): r for r in _sut_rows(log)}
    W = _sut_wejscia(S)

    def zuzyty(name, sym, przed):
        return max((r[8] for (d, ln, s), r in R.items() if ln == name and s == sym and d < przed and r[4] == 'ok' and isinstance(r[8], str)),
                   default=None)
    for name, fam, inp, dr, thr in TD_SH_SU:
        cel = _sut_cel(fam, now_utc); pc = _sut_poprz(fam, cel); kinds = SUT_KIND[inp]
        for (ln, sym), (ch, dm) in W.items():
            if ln != name:
                continue
            if cel >= SUT_SINCE:
                k = _sut_karta(ch, dm, thr, kinds, cel, fam, zuzyty(name, sym, cel))
                if k:
                    R[(cel, name, sym)] = [cel, name, sym, k[0] * dr, 'ok', _tdw_rz(k[1]), iso, None, k[2]]
            if (pc >= SUT_SINCE and (pc, name, sym) not in R and was and was[:19] < _sut_granica(fam, pc) <= n19 < _sut_koniec(fam, pc)):
                k = _sut_karta(ch, dm, thr, kinds, pc, fam, zuzyty(name, sym, pc))
                if k:
                    R[(pc, name, sym)] = [pc, name, sym, 0, 'late', None, iso, None, k[2]]
    wd = S.get('swiat-dzien') if isinstance(S.get('swiat-dzien'), dict) else {}
    kd = S.get('krypto-dzien') if isinstance(S.get('krypto-dzien'), dict) else None
    btc = oc = None
    for key, r in R.items():
        if r[7] is not None:
            continue
        if r[1] == 'cr.au':
            if btc is None:
                try:                                            # zepsuty plik dzienny krypto nie zatrzymuje kart (wynik dojdzie później)
                    btc = (_td_series_cr2(kd, 'BTC', today) if kd else None) or {}
                except Exception as e:  # noqa
                    btc = {}; META['notes'].append(mask(f'trendy surowce (w cieniu): wynik bitcoina — {e}')[:200])
            y = _td_win(btc, btc['dates'].index(r[0])) if btc and r[0] in btc['dates'] else None
        elif r[0] < today.isoformat() or n19 >= _tdw_at(r[0], TD_W_CLOSE):
            oc = oc if oc is not None else _sut_oc(wd, SUT_EQ + SUT_CM_PX)
            y = _sut_y_w(oc, r[0], r[2], n19)
        else:
            y = None
        if y is not None:
            r[7] = round(y, 4)
    rows = [R[k] for k in sorted(R)]
    out = {'at': iso, 'v': SUT_V, 'reg': SUT_REG, 'sha': SUT_SHA, 'since': SUT_SINCE, 'cut': {'w': TD_W_CUT, 'cr': TD_CR_CUT},
           'rows': rows, 'cp': {}}
    out['cp'] = _sut_cp(log, rows, today, iso, wd)
    pg = {}
    for name, fam, *_ in TD_SH_SU:
        settle = TD_W_SETTLE if fam == 'w' else TD_CR_SETTLE
        od = min((r[0] for r in rows if r[1] == name), default=None)
        a, _ = _sut_pary(rows, name, SUT_SINCE, (today - datetime.timedelta(days=settle)).isoformat())
        b, _ = _sut_pary(rows, name, SUT_SINCE)
        g = _td_pg({name: a}, {name: b}, [(name, name)], TD_W_LOOKS, out['cp'], od, today, settle)['l'][name]
        pg[name] = g + [od]                                     # [n, c, szacunek, dni dojrzałe, pierwsza karta]
    out['pg'] = pg
    if prevs:
        out['prev'] = prevs
    return out


def _sut_from_csv(path=None):
    """Kopia dzienna dziennika (archiwum/surowce-dziennik.csv, narzedzia/archiwum.py) → (dziennik, 'ok') z wierszami TEJ wersji i rejestracji
    (punkty kontrolne policzy od nowa _sut_log z tych samych wierszy); (None, 'none') — brak pliku albo wierszy tej wersji; (None, 'bad') —
    plik jest, ale nieczytelny (inny nagłówek, błąd odczytu)."""
    path = path or SUT_CSV
    try:
        with open(path, encoding='utf-8', newline='') as f:
            rd = csv.reader(f)
            if next(rd, None) != SUT_CSV_COLS:
                return None, 'bad'
            raw = list(rd)
    except FileNotFoundError:
        return None, 'none'
    except (OSError, csv.Error, UnicodeDecodeError):
        return None, 'bad'
    rows = []
    num = lambda x: float(x) if x != '' else None   # noqa: E731 — puste pole = brak, nigdy 0
    for r in raw:
        if len(r) != len(SUT_CSV_COLS):
            continue
        d = dict(zip(SUT_CSV_COLS, r))
        try:
            if int(d['v'] or 0) != SUT_V or d['reg'] != SUT_REG or not _d(d['date']):
                continue
            rows.append([d['date'], d['line'], d['sym'], int(d['g']), d['state'], num(d['z']), d['saved_at'], num(d['y']), d['dd'] or None])
        except (TypeError, ValueError):
            continue
    rows = [r for r in rows if r in _sut_rows({'rows': [r]})]
    if not rows:
        return None, 'none'
    return {'at': None, 'v': SUT_V, 'reg': SUT_REG, 'since': SUT_SINCE, 'rows': sorted(rows), 'cp': {}}, 'ok'


def _sut_summary(log):
    """Dziennik → pole 'su' pliku trendy.json: wersja, data rejestracji, suma dokumentu, m, poziom, punkty kontrolne, stan dziennika, postęp
    linii (l: [n, c, szacunek, dni dojrzałe, pierwsza karta]) i TYLKO linie z werdyktem „przewaga” w punkcie TD_SH_JAWNE (ok: [linia, c,
    werdykt ostatniej oceny, dzień c]) — żadnych liczb ocen przed ujawnieniem."""
    pg = log.get('pg') if isinstance(log.get('pg'), dict) else {}
    L, ok = {}, []
    for name, *_ in TD_SH_SU:
        g = pg.get(name)
        L[name] = g if isinstance(g, list) and len(g) == 5 else [0, TD_W_LOOKS[0], None, 0, None]
        cps = [x for x in ((log.get('cp') or {}).get(name) or []) if isinstance(x, list) and len(x) == 13]
        if any(x[0] == TD_SH_JAWNE and x[8] == 'edge' for x in cps):
            last = max(cps, key=lambda x: x[0])
            ok.append([name, last[0], last[8], last[9]])
    return {'v': SUT_V, 'reg': SUT_REG, 'sha': SUT_SHA, 'm': SUT_M, 'cll': SUT_CLL, 'looks': list(TD_W_LOOKS), 'jawne': TD_SH_JAWNE,
            'at': log.get('at'), 'l': L, 'ok': ok}


def _sut_arch_byl(path=None):
    """Czy archiwum miało już kiedyś kopię dziennika: archiwum/indeks.json (obok SUT_CSV) z wpisem surowce-dziennik o co najmniej jednym
    wierszu → True; indeks bez takiego wpisu → False (pierwsze wdrożenie: dziennika nie było ani na stronie, ani w archiwum); brak albo
    nieczytelny indeks → None (wtedy ostrożnie reguła daty)."""
    path = path or os.path.join(os.path.dirname(SUT_CSV), 'indeks.json')
    try:
        with open(path, encoding='utf-8') as f:
            ix = json.load(f)
    except (OSError, ValueError):
        return None
    fl = ix.get('files') if isinstance(ix, dict) else None
    if not isinstance(fl, dict):
        return None
    e = fl.get('surowce-dziennik')
    return isinstance(e, dict) and _isnum(e.get('rows')) and e['rows'] > 0


def _sut_build(S):
    """v303: blok „w cieniu” SUROWCE → pole 'su' pliku trendy.json albo None (bez danych surowców i bez dziennika — bez pola). Dziennik:
    _SUT_LOG[0] (poprzedni) → _SUT_LOG[1] (nowy); brak → odtworzenie z archiwum/surowce-dziennik.csv; nieczytelne archiwum → błąd w meta,
    licznik wstrzymany, nic nie zapisujemy; brak pliku i kopii → błąd w meta tylko wtedy, gdy dziennik już był (wpis w archiwum/indeks.json;
    bez czytelnego indeksu — po 4 dniach od SUT_SINCE), a przy pierwszym wdrożeniu — uwaga. Liczone tylko z plików tego przebiegu
    (surowce, swiat-dzien, krypto-dzien), bez sieci."""
    S = S if isinstance(S, dict) else {}
    su = S.get('surowce') if isinstance(S.get('surowce'), dict) else {}
    rd = lambda k: isinstance(S.get(k), dict) and S[k].get('ready') is True   # noqa: E731
    log0 = _SUT_LOG[0] if _sut_valid(_SUT_LOG[0]) else None
    if log0 is None and not (su.get('v') == SU_V and isinstance(su.get('ceny'), dict) and (rd('swiat-dzien') or rd('krypto-dzien'))):
        return None
    now_utc = _now_utc()
    if log0 is None:
        log0, why = _sut_from_csv()
        if why == 'bad':
            META['errors'].append('Dziennik surowców (TRENDY): brak poprzedniego pliku, a kopia w archiwum jest nieczytelna — licznik wstrzymany, '
                                  'nic nie nadpisano')
            return None
        if log0 is not None:
            META['notes'].append(f"Dziennik surowców (TRENDY): odtworzony z archiwum ({len(log0['rows'])} wierszy do {log0['rows'][-1][0]})")
        else:
            byl = _sut_arch_byl()
            if byl or (byl is None and now_utc.date() > _d(SUT_SINCE) + datetime.timedelta(days=4)):
                META['errors'].append('Dziennik surowców (TRENDY): brak poprzedniego pliku i brak jego kopii w archiwum — nowy dziennik, licznik od zera')
            else:                              # pierwsze wdrożenie (także po 12.10): dziennika nie było ani na stronie, ani w archiwum
                META['notes'].append('Dziennik surowców (TRENDY): nowy dziennik — pierwszy zapis (archiwum jeszcze go nie miało)')
    _SUT_LOG[1] = _sut_log(log0, S, now_utc)
    return _sut_summary(_SUT_LOG[1])


# ===================== v373: nowe grupy w TRENDACH — blok „w cieniu” TD_SH_NG (F1Z2 i F5Z4 planu źródeł) =====================
# Rejestracja z góry: docs/REGULY_NOWE_GRUPY_2026-10-14_PL.md (suma SHA-256 dokumentu w NGT_SHA) — lista zamknięta 14.10.2026, przed jakimkolwiek wynikiem.
# Sześć linii: przepływ do funduszy regionów i krajów (rg.f), do trzech nowych funduszy sektorowych (sk.f) i do funduszu Polski (pl.f); zmiana indeksów giełdy
# w Warszawie → fundusz Polski (pl.ix); zmiana zapasów miedzi w magazynach giełdy metali (kierunek odwrotny) → fundusz miedzi (me.cu); zmiana dziennego
# indeksu zbóż → fundusz surowców rolnych (zb.goi). Mechanika jak w bloku SUROWCE (TD_SH_SU), tylko sesje NYSE: karta sesji jest liczona w każdym przebiegu PRZED
# granicą 09:00 NY z danych, które w tej chwili są w plikach strony, i zamrażana na granicy (saved_at); karta, której przed granicą nie było, trafia do dziennika
# „po czasie” (bez głosu); dzień danych głosuje najwyżej raz w linii i symbolu (najnowszy, którego wcześniejsza karta nie użyła; za stary — wcale). Progi wyłącznie
# ze stałych reguł głównych (TD_LB, TD_MIN, TD_Z1, TD_FLOOR, TD_GAP); własny Bonferroni: m = 6 linii × 3 oceny = 18; punkty kontrolne 100/200/400 sesji
# z sygnałem zamrażane raz. Strona pokazuje tylko opis, datę rejestracji i licznik sesji z sygnałem do najbliższej oceny — NIC nie jest ujawniane (pole 'ok'
# nie istnieje). Wejścia pochodzą z plików tego przebiegu (fundusze, polska-rynek, metale, zboza-dzien), wyniki z cen sesji funduszy w plikach swiat-dzien i ng-ceny
# (14 dodatkowych funduszy zbiera build_ng_ceny: WD_NG_PX); bez zapytań do sieci. Reguły głównych sygnałów i bloku SUROWCE bez zmian.
NGT_V = 1                       # wersja bloku (zmiana linii albo reguły = nowa rejestracja, nowa wersja; stare oceny zostają w 'prev')
NGT_REG = '2026-10-14'          # data rejestracji (dokument z sumą SHA-256)
NGT_SINCE = '2026-10-15'        # najwcześniejsza data karty w dzienniku (pierwsza sesja docelowa po dniu rejestracji)
# SHA-256 pliku docs/REGULY_NOWE_GRUPY_2026-10-14_PL.md (dokument rejestracji zapisany przed kodem i przed jakimkolwiek wynikiem)
NGT_SHA = '79dfa4a6f07c4fd9f2a26b59768793f907f75aa5c14a2d5c10a4a131533ec41e'
NGT_RG = ('EWC', 'EWW', 'ECH', 'ILF', 'KSA', 'UAE', 'QAT', 'KWT', 'TUR', 'EIS', 'EZA', 'EWS', 'EIDO', 'THD', 'EWM', 'EPHE', 'EWA')   # regiony i kraje (rg.f)
NGT_SK = ('XLB', 'XLRE', 'XLC')                                   # sektory spoza reguł głównych (sk.f)
NGT_IX = ('WIG20', 'WIG', 'mWIG40', 'sWIG80')                     # indeksy giełdy w Warszawie (pl.ix)
TD_SH_NG = (('rg.f', 'fl', 1, TD_Z1), ('sk.f', 'fl', 1, TD_Z1), ('pl.f', 'fl', 1, TD_Z1), ('pl.ix', 'ix', 1, TD_Z1), ('me.cu', 'cu', -1, TD_Z1),
            ('zb.goi', 'goi', 1, TD_Z1))
#           (nazwa, wejście, kierunek z góry, próg |z|) — lista zamknięta 14.10.2026; sesja NYSE, wynik: otwarcie → zamknięcie funduszu
NGT_SYMS = {'rg.f': NGT_RG, 'sk.f': NGT_SK, 'pl.f': ('EPOL',), 'pl.ix': NGT_IX, 'me.cu': ('cu',), 'zb.goi': ('goi',)}   # symbole wejścia każdej linii
NGT_OUT = {'pl.ix': 'EPOL', 'me.cu': 'CPER', 'zb.goi': 'DBA'}     # fundusz wyniku; pozostałe linie: sam fundusz wejścia
NGT_OUTS = tuple(sorted({NGT_OUT.get(n, s) for n, ss in NGT_SYMS.items() for s in ss}))   # wszystkie fundusze wyniku (muszą mieć ceny w swiat-dzien)
NGT_M = len(TD_SH_NG) * len(TD_W_LOOKS)                                  # 18 prób naraz (6 linii × 3 oceny) — także linie jeszcze bez danych
NGT_ZL = statistics.NormalDist().inv_cdf(1 - 0.025 / NGT_M)              # 2,9913
NGT_CLL = round(100 - 5 / NGT_M, 1)                                      # 99.7
NGT_ZW = 1        # sesje NYSE: pierwsza sesja, w której wejście mogło głosować (po publikacji), najwyżej tyle sesji przed sesją karty (dostępność danych)
# publikacja wejścia z datą d: (dni po d, minuty po północy, strefa); w tygodniu ze świętem NYSE — ostrożnie dzień roboczy później. Pliki iShares: 23:59 NY dnia d;
# State Street: ok. 06:00 UTC następnego dnia roboczego (zapas do 08:00); zamknięcie sesji w Warszawie ok. 15:05 UTC (zapas do 18:00); zapasy w magazynach metali
# — wieczór dnia d, w plikach najpóźniej ok. 01:00 UTC następnego dnia (zapas do 06:00); dzienny indeks zbóż — rano następnego dnia (zapas do 10:00 UTC)
NGT_PUB = {'ishares': (0, 1439, 'ny'), 'ssga': (1, 480, 'utc'), 'gpw': (0, 1080, 'utc'), 'lme': (1, 360, 'utc'), 'igc': (1, 600, 'utc')}
NGT_CSV = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'archiwum', 'ng-dziennik.csv')   # kopia dzienna (narzedzia/archiwum.py)
NGT_CSV_COLS = ['date', 'line', 'sym', 'g', 'state', 'z', 'saved_at', 'y', 'dd', 'v', 'reg']
NGT_JST = ('ok', 'late')        # stany wiersza: ok — karta przed granicą (głos albo spokój), late — po czasie (bez głosu)
_NGT_LOG = [None, None]         # [poprzedni dziennik (main, przed trendami), nowy dziennik (_ngt_build)]


def _ngt_out(line, sym):
    """Fundusz wyniku wiersza (linia, symbol wejścia)."""
    return NGT_OUT.get(line, sym)


def _ngt_pub(kind, d):
    """Chwila publikacji (UTC, 'YYYY-MM-DDTHH:MM:SS') wejścia rodzaju `kind` z datą d. Dzień bez sesji NYSE (TD_NYSE_CLOSED) w (d, dzień publikacji] albo
    publikacja w sobotę/niedzielę — dzień roboczy później (ostrożnie, nigdy wcześniej)."""
    dd, m, tz = NGT_PUB[kind]
    p = _d(d) + datetime.timedelta(days=dd)
    if dd:
        if any((_d(d) + datetime.timedelta(days=k)).isoformat() in TD_NYSE_CLOSED for k in range(1, dd + 1)):
            p += datetime.timedelta(days=1)
        while p.weekday() >= 5 or p.isoformat() in TD_NYSE_CLOSED:
            p += datetime.timedelta(days=1)
    if tz == 'utc':
        return p.isoformat() + 'T%02d:%02d:00' % divmod(m, 60)
    return _tdw_at(p.isoformat(), m)


def _ngt_sesja_pub(kind, d):
    """Pierwsza sesja NYSE, w której karta (granica 09:00 NY) może użyć wejścia `kind` z datą d — pierwsza sesja z granicą po publikacji."""
    pub = _ngt_pub(kind, d)
    s = pub[:10] if _d(pub[:10]).weekday() < 5 and pub[:10] not in TD_NYSE_CLOSED else _tdw_next(pub[:10])
    return s if _tdw_cut(s) > pub else _tdw_next(s)


def _ngt_wejscia(S):
    """Wejścia linii z plików tego przebiegu → {(linia, symbol): ([(dzień, zmiana | przepływ | None)], demean, rodzaj publikacji)}. Brak pliku albo serii =
    brak wpisu (linia czeka). Przepływ: wiersze wydawcy [dzień, NAV, jednostki] z pliku fundusze (te same funkcje co reguły główne); zmiana: zamknięcie
    indeksu (podział jednostek = brak), zapasy metalu (bez filtra podziału), indeks zbóż."""
    out = {}
    fu = S.get('fundusze') if isinstance(S.get('fundusze'), dict) else {}
    F = fu.get('f') if isinstance(fu.get('f'), dict) else {}
    for line, syms in (('rg.f', NGT_RG), ('sk.f', NGT_SK), ('pl.f', ('EPOL',))):
        for sym in syms:
            e = F.get(sym) if isinstance(F.get(sym), dict) else {}
            f = _sut_fl(e.get('h')) if isinstance(e.get('h'), list) else []
            if f:
                out[(line, sym)] = (f, True, ('ssga' if e.get('iss') == 'ssga' else 'ishares',))
    pr = S.get('polska-rynek') if isinstance(S.get('polska-rynek'), dict) else {}
    idx = ((pr.get('gpw') or {}).get('idx') or {}) if isinstance(pr.get('gpw'), dict) else {}
    for sym in NGT_IX:
        ser = _sut_ser((idx.get(sym) or {}).get('d') if isinstance(idx.get(sym), dict) else None, 1)
        if len(ser) > 1:
            out[('pl.ix', sym)] = (_sut_zm(ser, split=True), False, ('gpw',))
    mt = S.get('metale') if isinstance(S.get('metale'), dict) else {}
    cu = (((mt.get('lme') or {}).get('m') or {}).get('cu') or {}) if isinstance(mt.get('lme'), dict) else {}
    ser = _sut_ser(cu.get('d') if isinstance(cu, dict) else None, 3)
    if len(ser) > 1:
        out[('me.cu', 'cu')] = (_sut_zm(ser), False, ('lme',))
    zd = S.get('zboza-dzien') if isinstance(S.get('zboza-dzien'), dict) else {}
    g = (((zd.get('goi') or {}).get('s') or {}).get('goi') or {}) if isinstance(zd.get('goi'), dict) else {}
    ser = _sut_ser(g.get('d') if isinstance(g, dict) else None, 1)
    if len(ser) > 1:
        out[('zb.goi', 'goi')] = (_sut_zm(ser, split=True), False, ('igc',))
    return out


def _ngt_karta(ch, demean, thr, kinds, cel, prev_dd):
    """Karta linii dla sesji `cel` z serii wejścia ch → (głos przed kierunkiem, z, dzień danych) albo None (brak karty). Dzień danych = najnowszy dzień serii
    przed sesją, którego publikacja jest przed granicą karty (09:00 NY); zużyty przez wcześniejszą kartę (≤ prev_dd) albo za stary (pierwsza sesja, w której mógł
    głosować, wcześniejsza niż NGT_ZW sesji przed kartą) = brak karty. z z najwyżej TD_LB poprzednich wartości serii (_td_z; ruch bez odejmowania średniej,
    przepływ ze średnią i dolną granicą rozrzutu). Tylko dni ≤ dzień danych — nic z dni późniejszych."""
    cut = _tdw_cut(cel)

    def wolno(d):
        return d < cel and all(_ngt_pub(k, d) < cut for k in kinds)
    i = len(ch) - 1
    while i >= 0 and not wolno(ch[i][0]):
        i -= 1
    if i < 0:
        return None
    d = ch[i][0]
    lo = cel
    for _ in range(NGT_ZW):
        lo = _wd_prev_session(lo)
    first = max(_ngt_sesja_pub(k, d) for k in kinds)
    if first < lo or (prev_dd and d <= prev_dd):
        return None
    z = _td_z([x for _, x in ch], i, demean)
    if z is None:
        return None
    return ((1 if z > 0 else -1) if abs(z) >= thr else 0), z, d


def _ngt_valid(log):
    return isinstance(log, dict) and isinstance(log.get('rows'), list) and 'v' in log and 'reg' in log


def _ngt_rows(log):
    """Poprawne wiersze dziennika: [dzień, linia, symbol, głos, stan, z, zapisano, y, dzień danych]."""
    return [list(r) for r in ((log or {}).get('rows') or []) if isinstance(r, list) and len(r) == 9 and isinstance(r[0], str) and _d(r[0])
            and r[1] in NGT_SYMS and r[2] in NGT_SYMS[r[1]] and r[4] in NGT_JST]


def _ngt_ut_w(wd, name):
    """Udział sesji wzrostowych w TD_W_UT sesjach przed parą (b0t, jak reguły świata) z pliku swiat-dzien → {symbol wejścia: {sesja: udział}}."""
    cal = [c for c in ((wd or {}).get('cal') or []) if isinstance(c, str)]
    if not cal:
        return None
    by = _sut_oc(wd, tuple({_ngt_out(name, s) for s in NGT_SYMS[name]}))
    ser = [{'id': s, 'dates': cal, 'y': [by[_ngt_out(name, s)].get(c) for c in cal]} for s in NGT_SYMS[name] if by[_ngt_out(name, s)]]
    return _tdw_ut(ser)


def _ngt_cp(log, rows, today, iso, wd):
    """Punkty kontrolne 100/200/400 sesji z sygnałem (wiersze dojrzałe: ≥ TD_W_SETTLE dni) przy z = NGT_ZL:
    [c, k, n, b0, h1, h2, lo, hi, vd, dzień c, zapisano, b0t, próg] — zapis raz, nigdy liczone od nowa (jak _sut_cp)."""
    cp = {k: [list(x) for x in v if isinstance(x, list) and len(x) == 13] for k, v in ((log or {}).get('cp') or {}).items()}
    for name, *_ in TD_SH_NG:
        pr, ys = _sut_pary(rows, name, NGT_SINCE, (today - datetime.timedelta(days=TD_W_SETTLE)).isoformat())
        pr = sorted(pr); ds = sorted({p[0] for p in pr}); have = {x[0] for x in cp.get(name, [])}
        ut = None
        for c in TD_W_LOOKS:
            if c in have or len(ds) < c:
                continue
            q = [p for p in pr if p[0] <= ds[c - 1]]
            ut = ut if ut is not None else (_ngt_ut_w(wd, name) or {})
            S_ = _tdw_stat(q, ys, NGT_ZL, ut)
            ne = S_['ne']; b0t = None if S_['b0t'] is None else round(S_['b0t'], 1)
            bm = S_['bm']
            thr = round(bm + 100 * NGT_ZL * math.sqrt(bm / 100 * (1 - bm / 100) / ne), 1) if ne else None
            cp.setdefault(name, []).append([c, S_['k'], S_['n'], None if S_['b0'] is None else round(S_['b0'], 1), S_['h1'], S_['h2'],
                                            S_['ca'][0], S_['ca'][1], S_['vd'], ds[c - 1], iso, b0t, thr])
    return {k: sorted(v) for k, v in cp.items() if v}


def _ngt_log(log, S, now_utc):
    """Dziennik bloku: karty liczone na żywo przed granicą (nadpisywane do granicy, potem zamrożone), karta bez wiersza przed granicą → „po czasie” (bez głosu,
    tylko gdy dziennik istniał przed tą granicą), wyniki dopisywane raz, punkty kontrolne raz, postęp (pg). Inna wersja albo rejestracja → nowy dziennik, stare
    oceny w 'prev'. Nie zmienia S."""
    log = log if _ngt_valid(log) else {}
    prevs = [x for x in (log.get('prev') or []) if isinstance(x, dict)] if isinstance(log.get('prev'), list) else []
    if log and (log.get('v') != NGT_V or log.get('reg') != NGT_REG):
        prevs = prevs + [{'v': log.get('v'), 'reg': log.get('reg'), 'cp': log.get('cp') or {}, 'n': len(log.get('rows') or [])}]
        log = {}
    iso = _sut_iso(now_utc); n19 = iso[:19]; today = _d(iso)
    was = log.get('at') if isinstance(log.get('at'), str) else None
    R = {(r[0], r[1], r[2]): r for r in _ngt_rows(log)}
    W = _ngt_wejscia(S)
    cel = _sut_cel('w', now_utc); pc = _sut_poprz('w', cel)

    def zuzyty(name, sym, przed):
        return max((r[8] for (d, ln, s), r in R.items() if ln == name and s == sym and d < przed and r[4] == 'ok' and isinstance(r[8], str)),
                   default=None)
    for name, inp, dr, thr in TD_SH_NG:
        for (ln, sym), (ch, dm, kinds) in W.items():
            if ln != name:
                continue
            if cel >= NGT_SINCE:
                k = _ngt_karta(ch, dm, thr, kinds, cel, zuzyty(name, sym, cel))
                if k:
                    R[(cel, name, sym)] = [cel, name, sym, k[0] * dr, 'ok', _tdw_rz(k[1]), iso, None, k[2]]
            if (pc >= NGT_SINCE and (pc, name, sym) not in R and was and was[:19] < _tdw_cut(pc) <= n19 < _tdw_end(pc)):
                k = _ngt_karta(ch, dm, thr, kinds, pc, zuzyty(name, sym, pc))
                if k:
                    R[(pc, name, sym)] = [pc, name, sym, 0, 'late', None, iso, None, k[2]]
    wd0 = S.get('swiat-dzien') if isinstance(S.get('swiat-dzien'), dict) else {}
    nc = S.get('ng-ceny') if isinstance(S.get('ng-ceny'), dict) else {}
    wd = {'cal': wd0.get('cal'), 'px': {**(wd0.get('px') or {}), **(nc.get('px') or {})}}   # ceny wyników: plik świat dziennie + plik ng-ceny (14 funduszy)
    oc = None
    for key, r in R.items():
        if r[7] is not None:
            continue
        if r[0] < today.isoformat() or n19 >= _tdw_at(r[0], TD_W_CLOSE):
            oc = oc if oc is not None else _sut_oc(wd, NGT_OUTS)
            y = (oc.get(_ngt_out(r[1], r[2])) or {}).get(r[0])
            if y is not None:
                r[7] = round(y, 4)
    rows = [R[k] for k in sorted(R)]
    out = {'at': iso, 'v': NGT_V, 'reg': NGT_REG, 'sha': NGT_SHA, 'since': NGT_SINCE, 'cut': {'w': TD_W_CUT}, 'rows': rows, 'cp': {}}
    out['cp'] = _ngt_cp(log, rows, today, iso, wd)
    pg = {}
    for name, *_ in TD_SH_NG:
        od = min((r[0] for r in rows if r[1] == name), default=None)
        a, _ = _sut_pary(rows, name, NGT_SINCE, (today - datetime.timedelta(days=TD_W_SETTLE)).isoformat())
        b, _ = _sut_pary(rows, name, NGT_SINCE)
        g = _td_pg({name: a}, {name: b}, [(name, name)], TD_W_LOOKS, out['cp'], od, today, TD_W_SETTLE)['l'][name]
        pg[name] = g + [od]                                     # [n, c, szacunek, dni dojrzałe, pierwsza karta]
    out['pg'] = pg
    if prevs:
        out['prev'] = prevs
    return out


def _ngt_from_csv(path=None):
    """Kopia dzienna dziennika (archiwum/ng-dziennik.csv, narzedzia/archiwum.py) → (dziennik, 'ok') z wierszami TEJ wersji i rejestracji (punkty kontrolne
    policzy od nowa _ngt_log z tych samych wierszy); (None, 'none') — brak pliku albo wierszy tej wersji; (None, 'bad') — plik jest, ale nieczytelny."""
    path = path or NGT_CSV
    try:
        with open(path, encoding='utf-8', newline='') as f:
            rd = csv.reader(f)
            if next(rd, None) != NGT_CSV_COLS:
                return None, 'bad'
            raw = list(rd)
    except FileNotFoundError:
        return None, 'none'
    except (OSError, csv.Error, UnicodeDecodeError):
        return None, 'bad'
    rows = []
    num = lambda x: float(x) if x != '' else None   # noqa: E731 — puste pole = brak, nigdy 0
    for r in raw:
        if len(r) != len(NGT_CSV_COLS):
            continue
        d = dict(zip(NGT_CSV_COLS, r))
        try:
            if int(d['v'] or 0) != NGT_V or d['reg'] != NGT_REG or not _d(d['date']):
                continue
            rows.append([d['date'], d['line'], d['sym'], int(d['g']), d['state'], num(d['z']), d['saved_at'], num(d['y']), d['dd'] or None])
        except (TypeError, ValueError):
            continue
    rows = [r for r in rows if r in _ngt_rows({'rows': [r]})]
    if not rows:
        return None, 'none'
    return {'at': None, 'v': NGT_V, 'reg': NGT_REG, 'since': NGT_SINCE, 'rows': sorted(rows), 'cp': {}}, 'ok'


def _ngt_summary(log):
    """Dziennik → pole 'ng' pliku trendy.json: wersja, data rejestracji, suma dokumentu, m, poziom, punkty kontrolne, stan dziennika i postęp linii
    (l: [n, c, szacunek, dni dojrzałe, pierwsza karta]). Żadnych liczb ocen i żadnego ujawnienia (nie ma pola 'ok')."""
    pg = log.get('pg') if isinstance(log.get('pg'), dict) else {}
    L = {}
    for name, *_ in TD_SH_NG:
        g = pg.get(name)
        L[name] = g if isinstance(g, list) and len(g) == 5 else [0, TD_W_LOOKS[0], None, 0, None]
    return {'v': NGT_V, 'reg': NGT_REG, 'sha': NGT_SHA, 'm': NGT_M, 'cll': NGT_CLL, 'looks': list(TD_W_LOOKS), 'at': log.get('at'), 'l': L}


def _ngt_arch_byl(path=None):
    """Czy archiwum miało już kiedyś kopię dziennika: archiwum/indeks.json z wpisem ng-dziennik o co najmniej jednym wierszu → True; indeks bez takiego wpisu
    → False (pierwsze wdrożenie); brak albo nieczytelny indeks → None (wtedy ostrożnie reguła daty)."""
    path = path or os.path.join(os.path.dirname(NGT_CSV), 'indeks.json')
    try:
        with open(path, encoding='utf-8') as f:
            ix = json.load(f)
    except (OSError, ValueError):
        return None
    fl = ix.get('files') if isinstance(ix, dict) else None
    if not isinstance(fl, dict):
        return None
    e = fl.get('ng-dziennik')
    return isinstance(e, dict) and _isnum(e.get('rows')) and e['rows'] > 0


def _ngt_build(S):
    """v373: blok „w cieniu” nowych grup → pole 'ng' pliku trendy.json albo None (bez gotowego pliku swiat-dzien albo bez żadnego wejścia linii — bez pola). Dziennik:
    _NGT_LOG[0] (poprzedni) → _NGT_LOG[1] (nowy); brak → odtworzenie z archiwum/ng-dziennik.csv; nieczytelne archiwum → błąd w meta, licznik wstrzymany,
    nic nie zapisujemy; brak pliku i kopii → błąd w meta tylko wtedy, gdy dziennik już był (wpis w archiwum/indeks.json; bez czytelnego indeksu — po 4 dniach od
    NGT_SINCE), a przy pierwszym wdrożeniu — uwaga. Liczone tylko z plików tego przebiegu, bez sieci."""
    S = S if isinstance(S, dict) else {}
    rd = lambda k: isinstance(S.get(k), dict) and S[k].get('ready') is True   # noqa: E731
    log0 = _NGT_LOG[0] if _ngt_valid(_NGT_LOG[0]) else None
    if log0 is None and not (rd('swiat-dzien') and _ngt_wejscia(S)):
        return None
    now_utc = _now_utc()
    if log0 is None:
        log0, why = _ngt_from_csv()
        if why == 'bad':
            META['errors'].append('Dziennik nowych grup (TRENDY): brak poprzedniego pliku, a kopia w archiwum jest nieczytelna — licznik wstrzymany, '
                                  'nic nie nadpisano')
            return None
        if log0 is not None:
            META['notes'].append(f"Dziennik nowych grup (TRENDY): odtworzony z archiwum ({len(log0['rows'])} wierszy do {log0['rows'][-1][0]})")
        else:
            byl = _ngt_arch_byl()
            if byl or (byl is None and now_utc.date() > _d(NGT_SINCE) + datetime.timedelta(days=4)):
                META['errors'].append('Dziennik nowych grup (TRENDY): brak poprzedniego pliku i brak jego kopii w archiwum — nowy dziennik, licznik od zera')
            else:                              # pierwsze wdrożenie: dziennika nie było ani na stronie, ani w archiwum
                META['notes'].append('Dziennik nowych grup (TRENDY): nowy dziennik — pierwszy zapis (archiwum jeszcze go nie miało)')
    _NGT_LOG[1] = _ngt_log(log0, S, now_utc)
    return _ngt_summary(_NGT_LOG[1])


# ===================== v413: najnowsze źródła w TRENDACH — blok „w cieniu” TD_SH_FW (F11Z22 planu tygodnia źródeł) =====================
# Rejestracja z góry: docs/REGULY_FALE_1_3_2026-10-17_PL.md (suma SHA-256 dokumentu w FWT_SHA) — lista zamknięta 17.10.2026, przed jakimkolwiek wynikiem.
# Sześć linii: zmiana pozycji netto zagranicznych inwestorów w kontraktach na indeksy w Indiach (in.fii) → fundusz Indii INDA i w kontraktach terminowych na Tajwanie (tw.fn) → EWT;
# zmiana stosunku put/call na Tajwanie (tw.pc, kierunek odwrotny) → EWT; zmiana zamknięcia CSI 300 (cn.csi) → MCHI; zmiana „ogona” stopy SOFR, czyli 99. percentyl minus stopa
# (us.sofr, kierunek odwrotny) → SPY; zmiana mediany lokalnych premii USDT (st.pr, kierunek odwrotny) → EEM. Mechanika jak w bloku nowych grup (TD_SH_NG), tylko sesje NYSE: karta
# sesji jest liczona w każdym przebiegu PRZED granicą 09:00 NY z danych, które w tej chwili są w plikach strony, i zamrażana na granicy (saved_at); karta, której przed granicą
# nie było, trafia do dziennika „po czasie” (bez głosu); dzień danych głosuje najwyżej raz w linii (najnowszy, którego wcześniejsza karta nie użyła; za stary — wcale) i nigdy
# w sesji D. Progi wyłącznie ze stałych reguł głównych (TD_LB, TD_MIN, TD_Z1, TD_FLOOR, TD_GAP); własny Bonferroni: m = 6 linii × 3 oceny = 18; punkty kontrolne 100/200/400 sesji
# z sygnałem zamrażane raz. Strona pokazuje tylko opis, datę rejestracji i licznik sesji z sygnałem do najbliższej oceny — NIC nie jest ujawniane (pole 'ok' nie istnieje).
# Wejścia pochodzą z plików plynnosc-usa, chiny-tw, indie i premie-stable (w tym przebiegu zapisywanych dopiero PO trendach — wtedy z pamięci poprzedniego przebiegu, _prev_cache),
# wyniki z cen sesji w pliku swiat-dzien (INDA, EWT, MCHI, SPY, EEM); bez zapytań do sieci i bez nowego budowniczego cen. Reguły głównych sygnałów, bloku SUROWCE i nowych grup bez zmian.
FWT_V = 1                       # wersja bloku (zmiana linii albo reguły = nowa rejestracja, nowa wersja; stare oceny zostają w 'prev')
FWT_REG = '2026-10-17'          # data rejestracji (dokument z sumą SHA-256)
FWT_SINCE = '2026-10-19'        # najwcześniejsza data karty w dzienniku (pierwsza sesja docelowa po dniu rejestracji — poniedziałek)
# SHA-256 pliku docs/REGULY_FALE_1_3_2026-10-17_PL.md (dokument rejestracji zapisany przed kodem i przed jakimkolwiek wynikiem)
FWT_SHA = '323394ebdd8e45c8bf70964dce4336ad1c2a728c49e645ff334c4829d6440057'
TD_SH_FW = (('in.fii', 'fii', 1, TD_Z1), ('tw.fn', 'fn', 1, TD_Z1), ('tw.pc', 'pc', -1, TD_Z1), ('cn.csi', 'csi', 1, TD_Z1), ('us.sofr', 'sofr', -1, TD_Z1),
            ('st.pr', 'pr', -1, TD_Z1))
#           (nazwa, wejście, kierunek z góry, próg |z|) — lista zamknięta 17.10.2026; sesja NYSE, wynik: otwarcie → zamknięcie funduszu
FWT_SYMS = {'in.fii': ('FII',), 'tw.fn': ('FN',), 'tw.pc': ('PC',), 'cn.csi': ('CSI',), 'us.sofr': ('SOFR',), 'st.pr': ('PR',)}   # symbol wejścia każdej linii (jeden na linię)
FWT_OUT = {'in.fii': 'INDA', 'tw.fn': 'EWT', 'tw.pc': 'EWT', 'cn.csi': 'MCHI', 'us.sofr': 'SPY', 'st.pr': 'EEM'}                  # fundusz wyniku każdej linii
FWT_DM = {'in.fii': True, 'tw.fn': True, 'tw.pc': False, 'cn.csi': False, 'us.sofr': True, 'st.pr': True}   # z: True = „przepływ” (ze średnią i dolną granicą), False = „ruch” (bez średniej)
FWT_KIND = {'in.fii': ('azja',), 'tw.fn': ('azja',), 'tw.pc': ('azja',), 'cn.csi': ('azja',), 'us.sofr': ('nyfed',), 'st.pr': ('stbl',)}   # linia → rodzaje publikacji wejścia
FWT_OUTS = tuple(sorted(set(FWT_OUT.values())))   # wszystkie fundusze wyniku (muszą mieć ceny w swiat-dzien): EEM, EWT, INDA, MCHI, SPY
FWT_M = len(TD_SH_FW) * len(TD_W_LOOKS)                                  # 18 prób naraz (6 linii × 3 oceny) — także linie jeszcze bez danych
FWT_ZL = statistics.NormalDist().inv_cdf(1 - 0.025 / FWT_M)              # 2,9913
FWT_CLL = round(100 - 5 / FWT_M, 1)                                      # 99.7
FWT_ZW = 1        # sesje NYSE: pierwsza sesja, w której wejście mogło głosować (po publikacji), najwyżej tyle sesji przed sesją karty (dostępność danych)
# publikacja wejścia z datą d: (dni po d, minuty po północy, strefa); w tygodniu ze świętem NYSE — ostrożnie dzień roboczy później. Giełdy azjatyckie (Indie, Tajwan, Chiny): pliki dnia d
# gotowe wieczorem czasu lokalnego, najpóźniej ok. 13:30 UTC dnia d — zapisujemy 20:00 UTC (karta wejdzie najwcześniej do następnej sesji NYSE); SOFR dnia d bank publikuje o 8:00 w Nowym Jorku
# następnego dnia roboczego (zapas: 8:30); premie USDT — okno zapytań kończy się 300 min po ustaleniu kursu we Frankfurcie (14:10, czyli 17:10 UTC latem, 18:10 zimą) — zapisujemy 21:00 UTC
FWT_PUB = {'azja': (0, 1200, 'utc'), 'nyfed': (1, 510, 'ny'), 'stbl': (0, 1260, 'utc')}
FWT_CSV = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'archiwum', 'fw-dziennik.csv')   # kopia dzienna (narzedzia/archiwum.py)
FWT_CSV_COLS = ['date', 'line', 'sym', 'g', 'state', 'z', 'saved_at', 'y', 'dd', 'v', 'reg']
FWT_JST = ('ok', 'late')        # stany wiersza: ok — karta przed granicą (głos albo spokój), late — po czasie (bez głosu)
_FWT_LOG = [None, None]         # [poprzedni dziennik (main, przed trendami), nowy dziennik (_fwt_build)]



def _fwt_out(line, sym):
    """Fundusz wyniku wiersza (linia, symbol wejścia)."""
    return FWT_OUT[line]



def _fwt_pub(kind, d):
    """Chwila publikacji (UTC, 'YYYY-MM-DDTHH:MM:SS') wejścia rodzaju `kind` z datą d. Dzień bez sesji NYSE (TD_NYSE_CLOSED) w (d, dzień publikacji] albo
    publikacja w sobotę/niedzielę — dzień roboczy później (ostrożnie, nigdy wcześniej)."""
    dd, m, tz = FWT_PUB[kind]
    p = _d(d) + datetime.timedelta(days=dd)
    if dd:
        if any((_d(d) + datetime.timedelta(days=k)).isoformat() in TD_NYSE_CLOSED for k in range(1, dd + 1)):
            p += datetime.timedelta(days=1)
        while p.weekday() >= 5 or p.isoformat() in TD_NYSE_CLOSED:
            p += datetime.timedelta(days=1)
    if tz == 'utc':
        return p.isoformat() + 'T%02d:%02d:00' % divmod(m, 60)
    return _tdw_at(p.isoformat(), m)


def _fwt_sesja_pub(kind, d):
    """Pierwsza sesja NYSE, w której karta (granica 09:00 NY) może użyć wejścia `kind` z datą d — pierwsza sesja z granicą po publikacji."""
    pub = _fwt_pub(kind, d)
    s = pub[:10] if _d(pub[:10]).weekday() < 5 and pub[:10] not in TD_NYSE_CLOSED else _tdw_next(pub[:10])
    return s if _tdw_cut(s) > pub else _tdw_next(s)


def _fwt_plik(S, nazwa):
    """Plik wejściowy: z obiektów tego przebiegu (S), a gdy go tam jeszcze nie ma (pliki fal 1–3 zapisuje main() dopiero po trendach) — z pamięci Actions poprzedniego
    przebiegu (lokalny plik, bez sieci; najwyżej kilkanaście minut starszy). Brak = {}."""
    p = S.get(nazwa)
    if isinstance(p, dict) and p:
        return p
    try:
        p = _prev_cache(nazwa)
    except Exception:  # noqa
        p = None
    return p if isinstance(p, dict) else {}


def _fwt_ser(pary, zm):
    """[(dzień, liczba | None)] → posortowane [(dzień, zmiana | None)]: zm='roz' — różnica wobec poprzedniego dnia z wartością; zm='pct' — (v / poprzednia − 1)·100 dla
    poprzedniej > 0. Poprzedni dzień dalej niż TD_GAP dni kalendarzowych = None. Tylko dzień i dzień przed nim — nic z dni późniejszych."""
    by = {}
    for d, v in pary:
        if isinstance(d, str) and _d(d) and _isnum(v):
            by[d[:10]] = float(v)
    ser = sorted(by.items())
    out = []
    for i, (d, v) in enumerate(ser):
        if not i or (_d(d) - _d(ser[i - 1][0])).days > TD_GAP:
            out.append((d, None)); continue
        pv = ser[i - 1][1]
        out.append((d, v - pv if zm == 'roz' else ((v / pv - 1) * 100 if pv > 0 else None)))
    return out


def _fwt_wejscia(S):
    """Wejścia linii z plików tego przebiegu → {(linia, symbol): ([(dzień, zmiana | None)], demean, rodzaje publikacji)}. Brak pliku albo serii (mniej niż 2 dni) = brak wpisu
    (linia czeka). Indie: pozycja netto grupy FII = długie − krótkie z jednego dnia (indie.fao.hist); Tajwan: wartość pozycji netto zagranicznych (chiny-tw.tw.in.h[3]) i stosunek
    wolumenu opcji sprzedaży do kupna (chiny-tw.tw.pc.h[1] / [2]); Chiny: zamknięcie CSI 300 (chiny-tw.csi.h[1]); SOFR: 99. percentyl minus stopa (plynnosc-usa.stopy.sofr[5] − [1]);
    premie: mediana koszyka (premie-stable.kosz[1])."""
    out = {}

    def dodaj(linia, pary, zm):
        ser = _fwt_ser(pary, zm)
        if len(ser) > 1:
            out[(linia, FWT_SYMS[linia][0])] = (ser, FWT_DM[linia], FWT_KIND[linia])
    ind = _fwt_plik(S, 'indie')
    fao = ind.get('fao') if isinstance(ind.get('fao'), dict) else {}
    pary = []
    for r in fao.get('hist') if isinstance(fao.get('hist'), list) else []:
        f = r.get('FII') if isinstance(r, dict) else None
        if isinstance(f, list) and len(f) == 2 and _isnum(f[0]) and _isnum(f[1]):
            pary.append((r.get('d'), f[0] - f[1]))
    dodaj('in.fii', pary, 'roz')
    ct = _fwt_plik(S, 'chiny-tw')
    tw = ct.get('tw') if isinstance(ct.get('tw'), dict) else {}
    h = ((tw.get('in') or {}).get('h') if isinstance(tw.get('in'), dict) else None)
    dodaj('tw.fn', [(r[0], r[3]) for r in h if isinstance(r, list) and len(r) >= 4] if isinstance(h, list) else [], 'roz')
    h = ((tw.get('pc') or {}).get('h') if isinstance(tw.get('pc'), dict) else None)
    dodaj('tw.pc', [(r[0], r[1] / r[2]) for r in h if isinstance(r, list) and len(r) >= 3 and _isnum(r[1]) and _isnum(r[2]) and r[2] > 0] if isinstance(h, list) else [], 'pct')
    h = ((ct.get('csi') or {}).get('h') if isinstance(ct.get('csi'), dict) else None)
    dodaj('cn.csi', [(r[0], r[1]) for r in h if isinstance(r, list) and len(r) >= 2] if isinstance(h, list) else [], 'pct')
    pl = _fwt_plik(S, 'plynnosc-usa')
    h = ((pl.get('stopy') or {}).get('sofr') if isinstance(pl.get('stopy'), dict) else None)
    dodaj('us.sofr', [(r[0], r[5] - r[1]) for r in h if isinstance(r, list) and len(r) >= 6 and _isnum(r[5]) and _isnum(r[1])] if isinstance(h, list) else [], 'roz')
    ps = _fwt_plik(S, 'premie-stable')
    h = ps.get('kosz')
    dodaj('st.pr', [(r[0], r[1]) for r in h if isinstance(r, list) and len(r) >= 3 and _isnum(r[2]) and r[2] >= PST_KOSZ_MIN] if isinstance(h, list) else [], 'roz')
    return out



def _fwt_karta(ch, demean, thr, kinds, cel, prev_dd):
    """Karta linii dla sesji `cel` z serii wejścia ch → (głos przed kierunkiem, z, dzień danych) albo None (brak karty). Dzień danych = najnowszy dzień serii
    przed sesją, którego publikacja jest przed granicą karty (09:00 NY); zużyty przez wcześniejszą kartę (≤ prev_dd) albo za stary (pierwsza sesja, w której mógł
    głosować, wcześniejsza niż FWT_ZW sesji przed kartą) = brak karty. z z najwyżej TD_LB poprzednich wartości serii (_td_z; ruch bez odejmowania średniej,
    przepływ ze średnią i dolną granicą rozrzutu). Tylko dni ≤ dzień danych — nic z dni późniejszych."""
    cut = _tdw_cut(cel)

    def wolno(d):
        return d < cel and all(_fwt_pub(k, d) < cut for k in kinds)
    i = len(ch) - 1
    while i >= 0 and not wolno(ch[i][0]):
        i -= 1
    if i < 0:
        return None
    d = ch[i][0]
    lo = cel
    for _ in range(FWT_ZW):
        lo = _wd_prev_session(lo)
    first = max(_fwt_sesja_pub(k, d) for k in kinds)
    if first < lo or (prev_dd and d <= prev_dd):
        return None
    z = _td_z([x for _, x in ch], i, demean)
    if z is None:
        return None
    return ((1 if z > 0 else -1) if abs(z) >= thr else 0), z, d


def _fwt_valid(log):
    return isinstance(log, dict) and isinstance(log.get('rows'), list) and 'v' in log and 'reg' in log


def _fwt_rows(log):
    """Poprawne wiersze dziennika: [dzień, linia, symbol, głos, stan, z, zapisano, y, dzień danych]."""
    return [list(r) for r in ((log or {}).get('rows') or []) if isinstance(r, list) and len(r) == 9 and isinstance(r[0], str) and _d(r[0])
            and r[1] in FWT_SYMS and r[2] in FWT_SYMS[r[1]] and r[4] in FWT_JST]


def _fwt_ut_w(wd, name):
    """Udział sesji wzrostowych w TD_W_UT sesjach przed parą (b0t, jak reguły świata) z pliku swiat-dzien → {symbol wejścia: {sesja: udział}}."""
    cal = [c for c in ((wd or {}).get('cal') or []) if isinstance(c, str)]
    if not cal:
        return None
    by = _sut_oc(wd, (FWT_OUT[name],))
    ser = [{'id': s, 'dates': cal, 'y': [by[FWT_OUT[name]].get(c) for c in cal]} for s in FWT_SYMS[name] if by[FWT_OUT[name]]]
    return _tdw_ut(ser)


def _fwt_cp(log, rows, today, iso, wd):
    """Punkty kontrolne 100/200/400 sesji z sygnałem (wiersze dojrzałe: ≥ TD_W_SETTLE dni) przy z = FWT_ZL:
    [c, k, n, b0, h1, h2, lo, hi, vd, dzień c, zapisano, b0t, próg] — zapis raz, nigdy liczone od nowa (jak _sut_cp)."""
    cp = {k: [list(x) for x in v if isinstance(x, list) and len(x) == 13] for k, v in ((log or {}).get('cp') or {}).items()}
    for name, *_ in TD_SH_FW:
        pr, ys = _sut_pary(rows, name, FWT_SINCE, (today - datetime.timedelta(days=TD_W_SETTLE)).isoformat())
        pr = sorted(pr); ds = sorted({p[0] for p in pr}); have = {x[0] for x in cp.get(name, [])}
        ut = None
        for c in TD_W_LOOKS:
            if c in have or len(ds) < c:
                continue
            q = [p for p in pr if p[0] <= ds[c - 1]]
            ut = ut if ut is not None else (_fwt_ut_w(wd, name) or {})
            S_ = _tdw_stat(q, ys, FWT_ZL, ut)
            ne = S_['ne']; b0t = None if S_['b0t'] is None else round(S_['b0t'], 1)
            bm = S_['bm']
            thr = round(bm + 100 * FWT_ZL * math.sqrt(bm / 100 * (1 - bm / 100) / ne), 1) if ne else None
            cp.setdefault(name, []).append([c, S_['k'], S_['n'], None if S_['b0'] is None else round(S_['b0'], 1), S_['h1'], S_['h2'],
                                            S_['ca'][0], S_['ca'][1], S_['vd'], ds[c - 1], iso, b0t, thr])
    return {k: sorted(v) for k, v in cp.items() if v}


def _fwt_log(log, S, now_utc):
    """Dziennik bloku: karty liczone na żywo przed granicą (nadpisywane do granicy, potem zamrożone), karta bez wiersza przed granicą → „po czasie” (bez głosu,
    tylko gdy dziennik istniał przed tą granicą), wyniki dopisywane raz, punkty kontrolne raz, postęp (pg). Inna wersja albo rejestracja → nowy dziennik, stare
    oceny w 'prev'. Nie zmienia S."""
    log = log if _fwt_valid(log) else {}
    prevs = [x for x in (log.get('prev') or []) if isinstance(x, dict)] if isinstance(log.get('prev'), list) else []
    if log and (log.get('v') != FWT_V or log.get('reg') != FWT_REG):
        prevs = prevs + [{'v': log.get('v'), 'reg': log.get('reg'), 'cp': log.get('cp') or {}, 'n': len(log.get('rows') or [])}]
        log = {}
    iso = _sut_iso(now_utc); n19 = iso[:19]; today = _d(iso)
    was = log.get('at') if isinstance(log.get('at'), str) else None
    R = {(r[0], r[1], r[2]): r for r in _fwt_rows(log)}
    W = _fwt_wejscia(S)
    cel = _sut_cel('w', now_utc); pc = _sut_poprz('w', cel)

    def zuzyty(name, sym, przed):
        return max((r[8] for (d, ln, s), r in R.items() if ln == name and s == sym and d < przed and r[4] == 'ok' and isinstance(r[8], str)),
                   default=None)
    for name, inp, dr, thr in TD_SH_FW:
        for (ln, sym), (ch, dm, kinds) in W.items():
            if ln != name:
                continue
            if cel >= FWT_SINCE:
                k = _fwt_karta(ch, dm, thr, kinds, cel, zuzyty(name, sym, cel))
                if k:
                    R[(cel, name, sym)] = [cel, name, sym, k[0] * dr, 'ok', _tdw_rz(k[1]), iso, None, k[2]]
            if (pc >= FWT_SINCE and (pc, name, sym) not in R and was and was[:19] < _tdw_cut(pc) <= n19 < _tdw_end(pc)):
                k = _fwt_karta(ch, dm, thr, kinds, pc, zuzyty(name, sym, pc))
                if k:
                    R[(pc, name, sym)] = [pc, name, sym, 0, 'late', None, iso, None, k[2]]
    wd0 = S.get('swiat-dzien') if isinstance(S.get('swiat-dzien'), dict) else {}
    wd = {'cal': wd0.get('cal'), 'px': wd0.get('px') or {}}   # ceny wyników: plik świat dziennie (INDA, EWT, MCHI, SPY, EEM)
    oc = None
    for key, r in R.items():
        if r[7] is not None:
            continue
        if r[0] < today.isoformat() or n19 >= _tdw_at(r[0], TD_W_CLOSE):
            oc = oc if oc is not None else _sut_oc(wd, FWT_OUTS)
            y = (oc.get(_fwt_out(r[1], r[2])) or {}).get(r[0])
            if y is not None:
                r[7] = round(y, 4)
    rows = [R[k] for k in sorted(R)]
    out = {'at': iso, 'v': FWT_V, 'reg': FWT_REG, 'sha': FWT_SHA, 'since': FWT_SINCE, 'cut': {'w': TD_W_CUT}, 'rows': rows, 'cp': {}}
    out['cp'] = _fwt_cp(log, rows, today, iso, wd)
    pg = {}
    for name, *_ in TD_SH_FW:
        od = min((r[0] for r in rows if r[1] == name), default=None)
        a, _ = _sut_pary(rows, name, FWT_SINCE, (today - datetime.timedelta(days=TD_W_SETTLE)).isoformat())
        b, _ = _sut_pary(rows, name, FWT_SINCE)
        g = _td_pg({name: a}, {name: b}, [(name, name)], TD_W_LOOKS, out['cp'], od, today, TD_W_SETTLE)['l'][name]
        pg[name] = g + [od]                                     # [n, c, szacunek, dni dojrzałe, pierwsza karta]
    out['pg'] = pg
    if prevs:
        out['prev'] = prevs
    return out


def _fwt_from_csv(path=None):
    """Kopia dzienna dziennika (archiwum/fw-dziennik.csv, narzedzia/archiwum.py) → (dziennik, 'ok') z wierszami TEJ wersji i rejestracji (punkty kontrolne
    policzy od nowa _fwt_log z tych samych wierszy); (None, 'none') — brak pliku albo wierszy tej wersji; (None, 'bad') — plik jest, ale nieczytelny."""
    path = path or FWT_CSV
    try:
        with open(path, encoding='utf-8', newline='') as f:
            rd = csv.reader(f)
            if next(rd, None) != FWT_CSV_COLS:
                return None, 'bad'
            raw = list(rd)
    except FileNotFoundError:
        return None, 'none'
    except (OSError, csv.Error, UnicodeDecodeError):
        return None, 'bad'
    rows = []
    num = lambda x: float(x) if x != '' else None   # noqa: E731 — puste pole = brak, nigdy 0
    for r in raw:
        if len(r) != len(FWT_CSV_COLS):
            continue
        d = dict(zip(FWT_CSV_COLS, r))
        try:
            if int(d['v'] or 0) != FWT_V or d['reg'] != FWT_REG or not _d(d['date']):
                continue
            rows.append([d['date'], d['line'], d['sym'], int(d['g']), d['state'], num(d['z']), d['saved_at'], num(d['y']), d['dd'] or None])
        except (TypeError, ValueError):
            continue
    rows = [r for r in rows if r in _fwt_rows({'rows': [r]})]
    if not rows:
        return None, 'none'
    return {'at': None, 'v': FWT_V, 'reg': FWT_REG, 'since': FWT_SINCE, 'rows': sorted(rows), 'cp': {}}, 'ok'


def _fwt_summary(log):
    """Dziennik → pole 'fw' pliku trendy.json: wersja, data rejestracji, suma dokumentu, m, poziom, punkty kontrolne, stan dziennika i postęp linii
    (l: [n, c, szacunek, dni dojrzałe, pierwsza karta]). Żadnych liczb ocen i żadnego ujawnienia (nie ma pola 'ok')."""
    pg = log.get('pg') if isinstance(log.get('pg'), dict) else {}
    L = {}
    for name, *_ in TD_SH_FW:
        g = pg.get(name)
        L[name] = g if isinstance(g, list) and len(g) == 5 else [0, TD_W_LOOKS[0], None, 0, None]
    return {'v': FWT_V, 'reg': FWT_REG, 'sha': FWT_SHA, 'm': FWT_M, 'cll': FWT_CLL, 'looks': list(TD_W_LOOKS), 'at': log.get('at'), 'l': L}


def _fwt_arch_byl(path=None):
    """Czy archiwum miało już kiedyś kopię dziennika: archiwum/indeks.json z wpisem fw-dziennik o co najmniej jednym wierszu → True; indeks bez takiego wpisu
    → False (pierwsze wdrożenie); brak albo nieczytelny indeks → None (wtedy ostrożnie reguła daty)."""
    path = path or os.path.join(os.path.dirname(FWT_CSV), 'indeks.json')
    try:
        with open(path, encoding='utf-8') as f:
            ix = json.load(f)
    except (OSError, ValueError):
        return None
    fl = ix.get('files') if isinstance(ix, dict) else None
    if not isinstance(fl, dict):
        return None
    e = fl.get('fw-dziennik')
    return isinstance(e, dict) and _isnum(e.get('rows')) and e['rows'] > 0


def _fwt_build(S):
    """v413: blok „w cieniu” fal 1–3 → pole 'fw' pliku trendy.json albo None (bez gotowego pliku swiat-dzien albo bez żadnego wejścia linii — bez pola). Dziennik:
    _FWT_LOG[0] (poprzedni) → _FWT_LOG[1] (nowy); brak → odtworzenie z archiwum/fw-dziennik.csv; nieczytelne archiwum → błąd w meta, licznik wstrzymany,
    nic nie zapisujemy; brak pliku i kopii → błąd w meta tylko wtedy, gdy dziennik już był (wpis w archiwum/indeks.json; bez czytelnego indeksu — po 4 dniach od
    FWT_SINCE), a przy pierwszym wdrożeniu — uwaga. Liczone tylko z plików tego przebiegu, bez sieci."""
    S = S if isinstance(S, dict) else {}
    rd = lambda k: isinstance(S.get(k), dict) and S[k].get('ready') is True   # noqa: E731
    log0 = _FWT_LOG[0] if _fwt_valid(_FWT_LOG[0]) else None
    if log0 is None and not (rd('swiat-dzien') and _fwt_wejscia(S)):
        return None
    now_utc = _now_utc()
    if log0 is None:
        log0, why = _fwt_from_csv()
        if why == 'bad':
            META['errors'].append('Dziennik najnowszych źródeł (TRENDY): brak poprzedniego pliku, a kopia w archiwum jest nieczytelna — licznik wstrzymany, '
                                  'nic nie nadpisano')
            return None
        if log0 is not None:
            META['notes'].append(f"Dziennik najnowszych źródeł (TRENDY): odtworzony z archiwum ({len(log0['rows'])} wierszy do {log0['rows'][-1][0]})")
        else:
            byl = _fwt_arch_byl()
            if byl or (byl is None and now_utc.date() > _d(FWT_SINCE) + datetime.timedelta(days=4)):
                META['errors'].append('Dziennik najnowszych źródeł (TRENDY): brak poprzedniego pliku i brak jego kopii w archiwum — nowy dziennik, licznik od zera')
            else:                              # pierwsze wdrożenie: dziennika nie było ani na stronie, ani w archiwum
                META['notes'].append('Dziennik najnowszych źródeł (TRENDY): nowy dziennik — pierwszy zapis (archiwum jeszcze go nie miało)')
    _FWT_LOG[1] = _fwt_log(log0, S, now_utc)
    return _fwt_summary(_FWT_LOG[1])


# ===================== v373: ceny dodatkowych funduszy dla bloku TD_SH_NG (osobny plik data/ng-ceny.json) =====================
# Wyniki linii bloku „w cieniu” nowych grup (otwarcie → zamknięcie sesji NYSE) potrzebują cen 14 funduszy, których nie ma w pliku świat dziennie (44 rynki
# reguł głównych + 7 funduszy surowcowych): EPOL, EWW, ECH, UAE, QAT, KWT, EWS, EIDO, THD, EWM, EPHE, XLB, XLRE, XLC. Osobny plik, żeby nie ruszać pliku
# świat dziennie (gotowość, karty i testy reguł głównych bez zmian): ta sama publiczna droga bez klucza (Nasdaq), ten sam kalendarz sesji (z pliku świat dziennie),
# ta sama zasada „pierwsza publikacja z czasem zapisu”, seria wstępna ok. 420 dni. Ceny dnia — w pierwszym przebiegu po tym, jak plik świat dziennie dopisze sesję,
# brakujące najwyżej co 55 min, po 48 h „miss” (brak na stałe, nigdy 0). Awaria = poprzednie dane i uwaga w meta (nie błąd strony). +14 zapytań na dobę.
WD_NG_PX = ('EPOL', 'EWW', 'ECH', 'UAE', 'QAT', 'KWT', 'EWS', 'EIDO', 'THD', 'EWM', 'EPHE', 'XLB', 'XLRE', 'XLC')
NGC_V = 1
NGC_SEED_DNI = 420                      # dni kalendarzowych serii wstępnej (≈ 290 sesji — z zapasem na udział sesji wzrostowych w 250 sesjach przed parą)
NGC_T = 60                              # s — cały budowniczy (zapytania: 14 funduszy równolegle, limit zapytania WD_TIMEOUT)
NGC_KEEP = 520                          # sesji w pliku (≈ 2 lata)
NGC_SRC = 'ceny: otwarcie i zamknięcie sesji w USA (jak plik świat dziennie) dodatkowych funduszy linii reguł w cieniu'


def _ngc_build(prev, saved):
    """v373: data/ng-ceny.json = {at, v, src, px: {fundusz: {d: [[dzień, otwarcie, zamknięcie, seen]], miss, seed, se}}, rv, rvd, try, bledy}. Kalendarz
    sesji z pliku świat dziennie (SAVED, gotowy) — bez niego plik zostaje bez zmian (poprzednie dane + wpis w bledy). Jedna droga zapytań (_wd_fetch_px) i jedno
    scalanie (_wd_merge_px) z plikiem świat dziennie; seria wstępna najwyżej raz na WD_SEED_BACK_M min po porażce."""
    now = _now_utc(); iso = _wd_iso(); ny = _wd_ny(now)
    prev = prev if isinstance(prev, dict) and prev.get('v') == NGC_V and isinstance(prev.get('px'), dict) else {}
    cp = lambda k: json.loads(json.dumps(prev.get(k) or {}))  # noqa: E731
    out = {'at': NOW, 'v': NGC_V, 'src': NGC_SRC, 'px': cp('px'), 'rv': {}, 'rvd': cp('rvd'), 'try': prev.get('try'), 'bledy': {}}
    wd0 = (saved or {}).get('swiat-dzien') if isinstance(saved, dict) else None
    cal = [c for c in (wd0.get('cal') or []) if isinstance(c, str) and _d(c)] if isinstance(wd0, dict) and wd0.get('ready') is True else []
    if not cal:
        out['bledy']['kalendarz'] = 'brak kalendarza sesji (plik świat dziennie jeszcze niegotowy)'
        return out
    wd = {'cal': cal, 'px': out['px'], 'rv': out['rv'], 'rvd': out['rvd']}
    for t in WD_NG_PX:
        out['px'].setdefault(t, {'d': [], 'miss': []})
    today_ny = ny.date().isoformat()
    stop = False
    # (1) ceny dnia dla funduszy z serią wstępną: sesja kalendarza (cal[-1]) bez wiersza → najwyżej co WD_RETRY_M min
    try:
        lack = [t for t in WD_NG_PX if out['px'][t].get('seed') and not any(r[0] == cal[-1] for r in out['px'][t]['d'][-3:])
                and cal[-1] not in (out['px'][t].get('miss') or [])]
        if lack and _wd_nq_ok(wd0, iso) and (not out['try'] or out['try'][:19] <= _wd_plus(iso, -WD_RETRY_M)[:19]):
            a = (_d(today_ny) - datetime.timedelta(days=20)).isoformat()
            got, err = _wd_fetch_px(lack, a, today_ny, 15, now); out['try'] = iso
            _wd_merge_px(wd, got, iso, True)
            if err:
                out['bledy']['px'] = _wd_esum(err)
        end = datetime.datetime.fromisoformat(_tdw_at(cal[-1], TD_W_CLOSE))
        if (now.astimezone(datetime.timezone.utc).replace(tzinfo=None) - end).total_seconds() > WD_GAP_H * 3600:
            for t in lack:
                P = out['px'][t]
                if not any(r[0] == cal[-1] for r in P['d']) and cal[-1] not in P.setdefault('miss', []):
                    P['miss'].append(cal[-1])
    except WdBudget:
        stop = True
    except Exception as e:  # noqa
        out['bledy']['px'] = mask(str(e))[:140]
    # (2) seria wstępna (po cenach dnia): porażka → przerwa WD_SEED_BACK_M min; odpowiedź bez żadnej ceny = jak błąd
    try:
        pend = [t for t in WD_NG_PX if not out['px'][t].get('seed') and not _wd_seed_skip(out['px'][t], iso)]
        if pend and not stop and _wd_nq_ok(wd0, iso):
            a = (_d(today_ny) - datetime.timedelta(days=NGC_SEED_DNI)).isoformat()
            got, err = _wd_fetch_px(pend, a, today_ny, 9999, now); at = _wd_iso()
            for t in [x for x in got if not got[x][0]]:
                del got[t]; err[t] = 'brak wierszy cen'
            _wd_merge_px(wd, got, at)
            for t in got:
                out['px'][t]['seed'] = True; out['px'][t].pop('se', None)
            for t, e in err.items():
                se = out['px'][t].setdefault('se', {'n': 0, 'at': None}); se['n'] += 1; se['at'] = at; se['why'] = e
            if err:
                out['bledy']['seed_px'] = _wd_esum(err)
    except WdBudget:
        pass
    except Exception as e:  # noqa
        out['bledy']['seed'] = mask(str(e))[:140]
    for P in out['px'].values():                       # przycięcie do ostatnich NGC_KEEP sesji kalendarza
        P['d'] = P['d'][-NGC_KEEP:]
        P['miss'] = [d for d in P.get('miss') or [] if d >= cal[max(0, len(cal) - NGC_KEEP)]]
    return out


def build_ng_ceny(prev=None, saved=None):
    """v373: wrapper — własny limit czasu budowniczego (NGC_T s) na wspólnej drodze zapytań pliku świat dziennie (_WD_TERMIN / _WD_CUT); poprzedni stan
    limitu przywrócony po zakończeniu."""
    old = _WD_TERMIN[0]
    _WD_TERMIN[0] = time.monotonic() + NGC_T; _WD_CUT[0] = False
    try:
        return _ngc_build(prev, saved)
    finally:
        _WD_TERMIN[0] = old


# ===================== v295: SUROWCE v2 — dział SUROWCE, etapy 1–2 (dane) =====================
# data/surowce.json w wersji 2. Zgodność wstecz: klucze v92 (at, src, url, data_url, unit, asof, order, markets) zostają — „markets” (CFTC:
# złoto, srebro, miedź, WTI) czyta build_trendy. Nowe części: ceny (dziennie), zapasy (tygodniowo), mies (miesięcznie); każda część ma czas
# udanego pobrania (part_at), stan (ok: true | false | 'cached' — bez próby w tym przebiegu), najbliższą spodziewaną publikację (next) i krótki
# zamaskowany błąd (err — strona go nie pokazuje). Bramki ŹRÓDEŁ (st) zamiast całego pliku co 6 h: każde źródło ma okno według kalendarza
# publikacji, a po błędzie ponowienie po godzinie. Źródło z błędem = poprzednie dane z ich datą; brak = null, nigdy 0. „at” = chwila ostatniego
# udanego pobrania którejkolwiek części (nie przebiegu). Długie historie (400 sesji, 6 lat tygodni, 120 miesięcy): data/surowce-hist.json —
# strona wczytuje go dopiero po rozwinięciu wykresu. Kody źródeł (pole z) — pełne nazwy wyłącznie na stronie „Źródła”:
#   eia — EIA Open Data API v2 (klucz EIA_KEY): ceny spot 11 serii jednym zapytaniem + Henry Hub; eia_t — to samo API, zapasy tygodniowe;
#   eia_dz — strona EIA „Daily Prices” (T+1, bez klucza; wartości wstępne do czasu API: pole pre); acer — ACER TERMINAL (LNG UE i TTF wyliczony);
#   gld — archiwum funduszu GLD (LBMA PM wyliczona: NAV/jedn. ÷ uncje/jedn.); td — Twelve Data XAU/USD (notowanie co godzinę, pole live);
#   fmp — FMP (srebro SIUSD, kontrolnie BZUSD i GCUSD, raz na dobę); sprott — kalkulator trustów fizycznych (miedź COP, uran SPUT);
#   wpsr / wngsr — pliki raportów tygodniowych EIA (ir.eia.gov, bez klucza); wb — Bank Światowy (Pink Sheet); imf — MFW PCPS; fao — FAO; cftc.
# Budżet czasu: najcięższe przebiegi automatu trwają 14,3–14,5 min z 25 — budowniczy ma SU_BUDZET_S s (każde zapytanie tylko, gdy zmieści się
# z całym swoim limitem), a w przebiegu dłuższym niż SU_LATE s ciężkie źródła (SU_CIEZKIE) czekają na następny przebieg (10 min później).
SU_V = 2
SU_PARTS = ('ceny', 'zapasy', 'mies', 'markets', 'pozycje', 'fundusze', 'banki')   # v298: + etap 3 (przepływy kapitału w surowcach)
SU_D, SU_H = 90, 400            # sesji: część ceny (surowce.json) / historia (surowce-hist.json)
SU_W, SU_WH = 26, 6 * 53 + 4    # tygodni: część zapasy / historia (pasmo 5 lat dla 26 tygodni)
SU_M, SU_MH, SU_K = 36, 120, 24  # miesięcy: część mies / historia / serie kontrolne MFW (mies.k)
SU_BUDZET_S = 150               # s na cały budowniczy; źródło startuje tylko, gdy zmieszczą się wszystkie jego zapytania z pełnymi limitami
SU_LATE = BACK_LATE             # s od startu przebiegu — dalej tylko lekkie źródła
SU_SPOT_DNI = 600               # dni wstecz w zapytaniu EIA spot: ok. 410 sesji × 11 serii < 5000 wierszy (limit API)
SU_TYG_LAT = 6                  # lat historii tygodniowej z API EIA (pasmo 5 lat + bieżący rok)
