def _su_ma_dane(prev, part, v2=True):
    """v301: czy część etapu 3 ma wcześniejsze dane — poprzedni plik v2 z co najmniej jednym wpisem (banki: kraj w kr, fundusze: fundusz w f)."""
    e = prev.get(part) if v2 and isinstance(prev, dict) and isinstance(prev.get(part), dict) else {}
    sub = e.get({'banki': 'kr', 'fundusze': 'f', 'pozycje': 'cftc'}.get(part, ''))   # v421: pozycje — wpisy USA (cftc)
    return isinstance(sub, dict) and any(isinstance(x, dict) for x in sub.values())


def _su_wtorek_po(now, h, m):
    """Wtorek (stan pozycji) raportu tygodniowego publikowanego w piątek o h:m UTC, który według kalendarza już wyszedł.
    v325 (zb07-05): h:m to godzina UTC przy czasie letnim w USA (CFTC 19:30 UTC = 15:30 w Nowym Jorku); przy czasie zimowym w USA
    termin o godzinę później (CFTC 20:30 UTC) — publikacja w stałej godzinie czasu Nowego Jorku."""
    for back in range(8):
        d = (now - datetime.timedelta(days=back)).date()
        if d.weekday() == 4 and (datetime.datetime(d.year, d.month, d.day, h, m, tzinfo=datetime.timezone.utc)
                                 - datetime.timedelta(hours=_tdw_off(d) + 4)) <= now:
            return (d - datetime.timedelta(days=3)).isoformat()
    return ''


def _su_due3(src, z, now, S):
    """v298: bramki źródeł etapu 3 (z _su_due dla źródeł spoza etapów 1–2). Naśladowca (SU_ZA) bierze odpowiedź lidera z tego przebiegu
    (bez zapytania); własne pobranie — tylko na start, po błędzie (po SU_ZA_PONOW min) i gdy lider ma nowsze dane (np. naśladowca pominięty
    przez budżet czasu). Pozycje — piątek po publikacji co 30 min, aż przyjdzie nowy wtorek (gdy brakuje najwyżej 2 raportów); poza oknem
    co 12 h (święto przesuwa publikację na poniedziałek); banki — MFW raz na dobę, SAFE w dniach 5–20."""
    at, tr = _su_min(now, z.get('at')), _su_min(now, z.get('try'))
    asof = z.get('asof') if isinstance(z.get('asof'), str) else ''
    first, today = at == float('inf'), now.date()
    st = S.get('st') if isinstance(S.get('st'), dict) else {}
    if src in SU_ZA:
        lider = SU_ZA[src]
        if lider in (S.get('udane') or ()):
            return True
        if first:
            return tr >= 60
        if z.get('err'):
            return tr >= SU_ZA_PONOW[src]
        return str((st.get(lider) or {}).get('asof') or '') > asof and tr >= 60
    if src in ('cit', 'tff', 'ice', 'iceab'):
        exp = _su_wtorek_po(now, *(SU_ICE_PUB if src in ('ice', 'iceab') else (19, 30)))
        if first:
            return tr >= 60
        if exp and asof < exp and _cftc_iso(asof) and (datetime.date.fromisoformat(exp) - _cftc_iso(asof)).days <= SU_POZ_DNI:
            return tr >= 30   # brakuje 1–2 raportów: okno co 30 min; dłuższa przerwa w pracy urzędu (2025: 6 tygodni) — co 12 h
        return at >= 12 * 60 and tr >= 60
    if src == 'gldm':     # archiwum GLDM — te same terminy co GLD (po sesji NYSE): 01:00, ponowienie 13:00 UTC
        return _su_termin(now, z, ((1, 0), (13, 0)))
    if src == 'imf_il':   # MFW dopisuje kraje w różnych dniach miesiąca — raz na dobę (11 KB)
        return tr >= 60 and (first or at >= 24 * 60)
    if src == 'irfcl':    # v338: druga tabela MFW (Rosja, Polska; 3,8 KB) — raz na dobę, po błędzie najwyżej co 6 h (jak SAFE; źródło uzupełniające)
        return tr >= (SU_SAFE_PONOW if z.get('err') else 60) and (first or at >= 24 * 60)
    if src == 'safe_zl':  # SAFE ok. 7. dnia miesiąca: w dniach 5–20 co 6 h, aż przyjdzie poprzedni miesiąc; poza tym raz na tydzień
        pon = SU_SAFE_PONOW if z.get('err') else 60   # v301: po błędzie (także przed pierwszym udanym pobraniem) — najwcześniej po 6 h
        if first:
            return tr >= pon
        if asof < _su_prev_month(now) and 5 <= now.day <= 20:
            return tr >= 360
        return at >= 7 * 24 * 60 and tr >= pon
    return False


# ---- v344: zmiana zapytania źródła albo pól czytanych z jego odpowiedzi wymusza jedno ponowne pobranie ----
# Bramki _su_due3 liczą czas od ostatniego udanego pobrania, więc po wdrożeniu v338 (lista MFW 10 → 55 krajów; z pliku SAFE nowe pole rez_cn) część „banki”
# czekała ze starym kształtem do końca doby (MFW) albo tygodnia (SAFE) — nie na „nowy miesiąc”. Stan źródła niesie teraz odcisk konfiguracji z ostatniego
# udanego pobrania (z['cfg']); gdy odcisk jest inny albo go brak (stan sprzed v344), źródło jest należne od razu (z odstępem między próbami jak dotąd:
# godzina, po błędzie SAFE 6 h), a po udanym pobraniu zapisuje nowy odcisk i wraca zwykły rytm. imf_il: odcisk z adresu zapytania — dopisanie albo
# usunięcie kraju w SU_BANKI zmienia go samo; safe_zl: odcisk ręczny SU_CFG_WER — podnieść wpis, gdy z tej samej odpowiedzi zbieramy nowe pole.
# Źródła bez wpisu (irfcl i reszta) — bez zmian. Nigdy nie pobrane (first) — zwykła bramka.
SU_CFG_WER = {'safe_zl': 'rez1'}   # v338: rezerwy Chin (parse_safe_rezerwy) z tego samego pliku SAFE


def _su_cfg(src):
    """v344: odcisk konfiguracji źródła (adres zapytania MFW IL albo ręczna wersja pól), None = źródło bez kontroli."""
    if src == 'imf_il':
        import hashlib as _su_hash
        return 'u' + _su_hash.sha1(SU_IMF_IL_ZL_URL.encode('utf-8')).hexdigest()[:10]
    return SU_CFG_WER.get(src)


def _su_cfg_zmiana(src, z, now):
    """v344: True, gdy ostatnie udane pobranie źródła było z inną konfiguracją (albo bez odcisku) i minął odstęp między próbami."""
    c = _su_cfg(src)
    if c is None or z.get('cfg') == c or _su_min(now, z.get('at')) == float('inf'):
        return False
    return _su_min(now, z.get('try')) >= (SU_SAFE_PONOW if src == 'safe_zl' and z.get('err') else 60)


def _su_next3(part, out, now):
    """v298: najbliższa spodziewana publikacja części etapu 3 (ISO, UTC); termin w przeszłości = publikacja zaległa."""
    utc = datetime.timezone.utc
    today = now.date()
    if part == 'pozycje':    # CFTC: piątek 15:30 czasu Nowego Jorku (19:30 UTC latem); ICE wcześniej tego samego dnia
        exp = _su_cftc_wtorek(now)
        fri = datetime.date.fromisoformat(exp) + datetime.timedelta(days=3) if exp else today
        if str(((out.get('pozycje') or {}).get('asof') or {}).get('cftc') or '') >= exp:
            fri += datetime.timedelta(days=7)
        return datetime.datetime(fri.year, fri.month, fri.day, 19, 30, tzinfo=utc).isoformat()
    if part == 'fundusze':   # archiwa funduszy złota po sesji NYSE — pobranie o 01:00 UTC (wtorek–sobota)
        d = today if now.hour < 1 else today + datetime.timedelta(days=1)
        while d.weekday() in (6, 0):
            d += datetime.timedelta(days=1)
        return datetime.datetime(d.year, d.month, d.day, 1, 0, tzinfo=utc).isoformat()
    if part == 'banki':      # SAFE ok. 7. dnia miesiąca (Chiny); MFW — bez kalendarza (kraje w różnych dniach miesiąca)
        y, m = (now.year, now.month) if now.day < 7 else ((now.year + 1, 1) if now.month == 12 else (now.year, now.month + 1))
        return datetime.datetime(y, m, 7, 12, 0, tzinfo=utc).isoformat()
    return None


# ---- parsery etapu 3 (nagrania w testach SurowceEtap3V298) ----
def _su_cot_grupy(v, groups):
    g = {}
    for gk, lo, sh, sp in groups:
        L, S, P = v(lo), v(sh), (v(sp) if sp else None)
        g[gk] = {'long': L, 'short': S, 'spread': P, 'net': L - S if L is not None and S is not None else None}
    return g


def _su_cot_ok(oi, g, groups, tol=0):
    """Suma pozycji grup = open interest: osobno long + spread i short + spread (spread liczy się po obu stronach); tol — dopuszczalna
    różnica w kontraktach (raporty disaggregated i ICE — dokładnie; CIT — SU_CIT_TOL)."""
    tl = [oi] + [x['long'] for x in g.values()] + [x['short'] for x in g.values()] + [g[gk]['spread'] for gk, _, _, sp in groups if sp]
    return (None not in tl and abs(sum(x['long'] + (x['spread'] or 0) for x in g.values()) - oi) <= tol
            and abs(sum(x['short'] + (x['spread'] or 0) for x in g.values()) - oi) <= tol)


def parse_ice_cot(text, poz=None):
    """ICE Futures Europe — Commitments of Traders (CSV z BOM, układ jak CFTC disaggregated) → ({kod towaru: {dzień: rekord}}, [złe wiersze]).
    Tylko wiersze „FutOnly” (bez opcji); klucz CFTC_Commodity_Code (kod rynku w pliku pusty); nazwy kolumn z pojedynczym „_” (CFTC ma
    „Swap__”); data z kolumny MM/DD/YYYY bez zer wiodących (np. 7/28/2026), sprawdzana z kolumną RRMMDD; rekord jak w parse_cftcd; wiersz,
    w którym grupy nie sumują się do open interest, trafia do złych (pomijany — brak, nie zero)."""
    rows = list(csv.reader(io.StringIO(text.lstrip('\ufeff'))))
    if not rows:
        raise RuntimeError('pusty plik')
    I = {re.sub(r'_+', '_', n.strip()): i for i, n in enumerate(rows[0])}
    need = ['Market_and_Exchange_Names', 'As_of_Date_Form_MM/DD/YYYY', 'CFTC_Commodity_Code', 'Open_Interest_All', 'FutOnly_or_Combined']
    need += [c for _, lo, sh, sp in SU_ICE_G for c in (lo, sh, sp) if c]
    miss = [n for n in need if n not in I]
    if miss:
        raise RuntimeError('brak kolumn ' + ', '.join(miss)[:160])
    want = {c for _, c, _ in (poz or SU_POZ_ICE)}   # v421: poz — lista rynków innego pliku tego układu (Murban); domyślnie Londyn
    out, bad = {}, []
    for r in rows[1:]:
        if len(r) != len(rows[0]) or r[I['FutOnly_or_Combined']].strip() != 'FutOnly':
            continue
        code = r[I['CFTC_Commodity_Code']].strip()
        if code not in want:
            continue
        m = re.fullmatch(r'(\d{1,2})/(\d{1,2})/(\d{4})', r[I['As_of_Date_Form_MM/DD/YYYY']].strip())
        try:
            day = datetime.date(int(m.group(3)), int(m.group(1)), int(m.group(2))).isoformat() if m else None
        except ValueError:
            day = None
        yy = r[I['As_of_Date_In_Form_YYMMDD']].strip() if 'As_of_Date_In_Form_YYMMDD' in I else ''
        if not day or (yy and yy != day[2:].replace('-', '')):
            bad.append(f'{code} {r[I["As_of_Date_Form_MM/DD/YYYY"]].strip()} (data)'); continue
        v = lambda n: _cftc_int(r[I[n]])   # noqa: E731
        oi = v('Open_Interest_All')
        g = _su_cot_grupy(v, SU_ICE_G)
        if not _su_cot_ok(oi, g, SU_ICE_G):
            bad.append(f'{code} {day}'); continue
        out.setdefault(code, {})[day] = {'name': r[I['Market_and_Exchange_Names']].strip(), 'date': day, 'oi': oi, 'g': g}
    return out, bad


def parse_cit(text, header=None):
    """CFTC Supplemental — Commodity Index Traders (futures + opcje, 13 rynków rolnych) → ({kod rynku: {dzień: rekord}}, [złe wiersze]).
    Plik roczny z nagłówkiem (annualci.txt), tygodniowy bez (header=SU_CIT_COLS — pierwsze 19 kolumn). Grupy: nc — duzi niekomercyjni
    bez funduszy indeksowych (long, short, spread), c — komercyjni bez nich, cit — fundusze indeksowe, nonrept — małe pozycje; suma = open
    interest (long + spread i short + spread) z tolerancją SU_CIT_TOL kontraktów (zaokrąglenia CFTC), inaczej wiersz do złych."""
    rows = list(csv.reader(io.StringIO(text)))
    if header is None:
        if not rows:
            return {}, []
        header, rows = rows[0], rows[1:]
    I = {n.strip(): i for i, n in enumerate(header)}
    miss = [n for n in SU_CIT_COLS if n not in I]
    if miss:
        raise RuntimeError('brak kolumn ' + ', '.join(miss)[:160])
    out, bad = {}, []
    for r in rows:
        if len(r) < len(SU_CIT_COLS):
            continue
        code, day = r[I['CFTC_Contract_Market_Code']].strip(), r[I['As_of_Date_In_Form_YYYY-MM-DD']].strip()
        if not _cftc_iso(day):
            bad.append(f'{code} {day} (data)'); continue
        v = lambda n: _cftc_int(r[I[n]])   # noqa: E731
        oi = v('Open_Interest_All')
        g = _su_cot_grupy(v, SU_CIT_G)
        if not _su_cot_ok(oi, g, SU_CIT_G, SU_CIT_TOL):
            bad.append(f'{code} {day}'); continue
        out.setdefault(code, {})[day] = {'name': r[I['Market_and_Exchange_Names']].strip(), 'date': day, 'oi': oi, 'g': g}
    return out, bad


def parse_spdr_ilosc(data, produkt):
    """Archiwum funduszu SPDR (xlsx, arkusz „US {produkt} Historical Archive”: GLD, GLDM) → {dzień: (uncje złota w funduszu, odchylenie wartości
    aktywów od uncji × ceny złota w % — cena = NAV/jedn. ÷ uncje/jedn., jak seria gold)}; kolumny po nazwie; wiersze świąt („US Holiday”)
    i bez liczby pominięte. Kolumny „Tonnes of Gold” nie używamy: tony zawsze = uncje ÷ 32 150,7466 (w pliku inny sposób zaokrąglenia —
    różnica do 0,015 t)."""
    rows = _xlsx_rows(data, f'US {produkt} Historical Archive')
    head = next((k for k in sorted(rows) if str(rows[k].get(1, '')).strip() == 'Date'), None)
    if head is None:
        raise RuntimeError(f'{produkt}: brak nagłówka')
    col = {re.sub(r'\s+', ' ', str(v)).strip(): c for c, v in rows[head].items()}
    co, cv = col.get('Total Ounces of Gold in the Trust'), col.get('Total Net Asset Value in the Trust')
    cn = next((c for n, c in col.items() if n.startswith('NAV/Share')), None)
    cs = col.get('Ounces of Gold per Share')
    if not co:
        raise RuntimeError(f'{produkt}: brak kolumny uncji złota w funduszu')
    out = {}
    for k in sorted(rows):
        if k <= head:
            continue
        r = rows[k]
        try:
            d = datetime.datetime.strptime(str(r.get(1, '')).strip(), '%d-%b-%Y').date().isoformat()
        except ValueError:
            continue
        oz = _num(r.get(co))
        if not (_isnum(oz) and oz > 0):
            continue
        tv, nav, ops = (_num(r.get(c)) if c else None for c in (cv, cn, cs))
        rr = (tv / (oz * nav / ops) - 1) * 100 if _isnum(tv) and _isnum(nav) and _isnum(ops) and nav > 0 and ops > 0 else None
        out[d] = (oz, None if rr is None else round(rr, 4))
    if not out:
        raise RuntimeError(f'{produkt}: brak wierszy z uncjami')
    return out


def parse_sprott_ilosci(j):
    """Kalkulator trustów fizycznych → {id funduszu: (dzień, ilość w jednostce źródła)} dla SU_FU_SPROTT. Najpierw podpis listy z parse_sprott
    (kolejność, zakres ceny jednostki, jeden/dwa metale — wyjątek przy zmianie), potem ilości; ilość ≤ 0 albo zła data = fundusz pominięty."""
    parse_sprott(j)
    out = {}
    for fid, i, pole in SU_FU_SPROTT:
        r = j[i]
        q, d = _num(r.get(pole)), str(r.get('dateTimeStamp') or '')[:10]
        if _isnum(q) and q > 0 and re.match(r'^\d{4}-\d{2}-\d{2}$', d):
            out[fid] = (d, q)
    return out


def parse_imf_il_zloto(j, odrz=None):
    """MFW IL, wskaźnik RGV_REVS (złoto w rezerwach; jednostka FTO — uncje trojańskie) → ({kraj ISO2: {RRRR-MM: uncje}}, [kraje z inną
    jednostką]). Straż skali: zmiana atrybutu SCALE dotyka wszystkich krajów naraz, więc gdy ostatnia wartość więcej niż co piątego kraju jest poza
    SU_BANKI_T ton — cała odpowiedź odrzucona. v338: przy ok. 55 krajach pojedynczy kraj spoza zakresu (np. rezerwa spadła do zera) jest pomijany
    (jego opis trafia do odrz), a nie odrzuca pozostałych."""
    ser = parse_imf_sdmx(j)
    iso = {c3: c2 for c2, c3 in SU_BANKI}
    out, inna = {}, []
    for lab, rows in ser.items():
        if len(lab) != 4 or lab[1] != 'RGV_REVS' or lab[3] != 'M' or lab[0] not in iso:
            continue
        if lab[2] != 'FTO':
            inna.append(lab[0]); continue
        out[iso[lab[0]]] = {m: v for m, v in rows}
    if not out:
        raise RuntimeError('brak krajów z jednostką FTO' + (f' (inna jednostka: {", ".join(inna)})' if inna else ''))
    zle = [(c2, rows[max(rows)] / SU_OZ_T) for c2, rows in sorted(out.items())
           if not SU_BANKI_T[0] <= rows[max(rows)] / SU_OZ_T <= SU_BANKI_T[1]]
    if zle and len(zle) * 5 > len(out):
        c2, t = zle[0]
        raise RuntimeError(f'{c2}: {t:.1f} t poza zakresem {SU_BANKI_T[0]:g}–{SU_BANKI_T[1]:g} t — zmiana skali? odpowiedź odrzucona')
    for c2, t in zle:
        del out[c2]
        if odrz is not None:
            odrz.append(f'{c2} ({t:.1f} t)')
    return out, inna


def parse_safe_zloto(data):
    """SAFE „Official Reserve Assets” (xlsx) → {RRRR-MM: uncje}: wiersz nagłówka „Item”/„项目” z miesiącami „RRRR.MM” (kolumna USD; obok SDR
    z tą samą ilością), wiersz „Gold”/„黄金”, a najwyżej 3 wiersze niżej ilość tekstem „7673万盎司” (万 = 10 000 uncji). Wartość spoza
    SU_SAFE_WAN = cały plik odrzucony."""
    import html as _h
    import zipfile as _zf
    wb = _zf.ZipFile(io.BytesIO(data)).read('xl/workbook.xml').decode('utf-8', 'replace')
    for name in [_h.unescape(x) for x in re.findall(r'<sheet\b[^>]*\bname="([^"]*)"', wb)]:
        rows = _xlsx_rows(data, name)
        ks = sorted(rows)
        head = next((k for k in ks if re.search(r'Item|项目', str(rows[k].get(1, ''))) and any(re.fullmatch(r'20\d{2}\.(0[1-9]|1[0-2])', str(v).strip())
                                                                                                    for v in rows[k].values())), None)
        gold = next((k for k in ks if re.search(r'黄金|^\W*\d*\.?\s*Gold\b', str(rows[k].get(1, '')).strip(), re.I)), None)
        if head is None or gold is None:
            continue
        months = {c: str(v).strip().replace('.', '-') for c, v in rows[head].items() if re.fullmatch(r'20\d{2}\.(0[1-9]|1[0-2])', str(v).strip())}
        qrow = next((rows[k] for k in ks if gold < k <= gold + 3 and any('万盎司' in str(v) for v in rows[k].values())), None)
        if not qrow:
            raise RuntimeError('brak wiersza ilości złota (万盎司)')
        out = {}
        for c, m in months.items():
            mm = re.fullmatch(r'\s*([\d.,]+)\s*万盎司\s*', str(qrow.get(c, '')))
            if mm:
                w = _num(mm.group(1))
                if not (_isnum(w) and SU_SAFE_WAN[0] <= w <= SU_SAFE_WAN[1]):
                    raise RuntimeError(f'{m}: {mm.group(1)} 万盎司 poza zakresem — plik odrzucony')
                out[m] = w * 10000
        if not out:
            raise RuntimeError('brak miesięcy z ilością złota')
        return out
    raise RuntimeError('brak arkusza z nagłówkiem miesięcy i wierszem złota')


# ---- v338 (F1Z4): rezerwy Chin razem z tego samego pliku SAFE co złoto (tabela rezerw na stronie: Chiny o 1–3 miesiące świeższe niż w MFW) ----
SU_SAFE_REZ = (20000, 60000)   # 100 mln USD — rezerwy razem w pliku SAFE (I–IX 2026: 37 511–38 827 = 3,75–3,88 bln USD); spoza zakresu = plik odrzucony
SU_SAFE_SUMA = 0.5             # 100 mln USD — składniki (waluty, pozycja w MFW, SDR, złoto, inne) muszą sumować się do „razem” (w pliku z 08.10.2026: dokładnie)


def parse_safe_rezerwy(data):
    """SAFE „Official Reserve Assets” (xlsx) → {RRRR-MM: [razem, waluty obce, złoto]} w mld USD (komórki w 100 mln USD ÷ 10). Wiersze po nazwie
    („合计” razem, „外汇储备” waluty obce, „黄金” złoto + trzy pozostałe składniki); miesiąc bez liczb (kolejne miesiące roku) pominięty; składniki
    nie sumują się do „razem” (SU_SAFE_SUMA) albo „razem” spoza SU_SAFE_REZ = cały plik odrzucony."""
    import html as _h
    import zipfile as _zf
    wb = _zf.ZipFile(io.BytesIO(data)).read('xl/workbook.xml').decode('utf-8', 'replace')
    for name in [_h.unescape(x) for x in re.findall(r'<sheet\b[^>]*\bname="([^"]*)"', wb)]:
        rows = _xlsx_rows(data, name)
        ks = sorted(rows)
        head = next((k for k in ks if re.search(r'Item|项目', str(rows[k].get(1, ''))) and any(re.fullmatch(r'20\d{2}\.(0[1-9]|1[0-2])', str(v).strip())
                                                                                                    for v in rows[k].values())), None)
        lab = lambda k: str(rows[k].get(1, '')).replace('\xa0', ' ')   # noqa: E731
        find = lambda pat: next((k for k in ks if re.search(pat, lab(k))), None)   # noqa: E731
        sk = [find(p) for p in ('合计', '外汇储备', '基金组织储备头寸', '特别提款权', '黄金', '其他储备资产')]
        if head is None or None in sk:
            continue
        months = {c: str(v).strip().replace('.', '-') for c, v in rows[head].items() if re.fullmatch(r'20\d{2}\.(0[1-9]|1[0-2])', str(v).strip())}
        out = {}
        for c, m in sorted(months.items()):
            v = [_num(rows[k].get(c)) for k in sk]
            if not all(_isnum(x) for x in v):
                continue
            tot, parts = v[0], v[1:]
            if not SU_SAFE_REZ[0] <= tot <= SU_SAFE_REZ[1]:
                raise RuntimeError(f'{m}: rezerwy razem {tot} (100 mln USD) poza zakresem — plik odrzucony')
            if abs(sum(parts) - tot) > SU_SAFE_SUMA:
                raise RuntimeError(f'{m}: składniki rezerw ({sum(parts):.2f}) ≠ razem ({tot:.2f}) — plik odrzucony')
            out[m] = [round(tot / 10, 3), round(parts[0] / 10, 3), round(parts[3] / 10, 3)]
        if not out:
            raise RuntimeError('brak miesięcy z rezerwami razem')
        return out
    raise RuntimeError('brak arkusza z nagłówkiem miesięcy i wierszami rezerw')


# ---- wpisy części pozycje ----
def _su_poz_wpis(code, recs, prev_e, glowna, hf=(), extra=None):
    """Rekordy jednego rynku {dzień: {'name','oi','g'}} → wpis części pozycje: ostatni raport — open interest, pos (wszystkie grupy [long, short,
    spread] — kontrola sumy), netto grupy głównej (glowna: 'mm' fundusze zarządzające, 'cit' fundusze indeksowe, 'asset_mgr' zarządzający
    aktywami) i jego udział w open interest (pct, %); zmiana tygodnia d1 / d1p — tylko wobec raportu sprzed 7 dni (inaczej null); historia
    13 tygodni z okna 90 dni (h: d, net, oi + pola hf), brakujące starsze tygodnie z poprzedniego wpisu tego rynku."""
    days = sorted(recs)
    last, ld = recs[days[-1]], _cftc_iso(days[-1])
    fields = (('net', glowna),) + tuple(hf)
    H = {}
    ph = prev_e.get('h') if isinstance(prev_e, dict) and isinstance(prev_e.get('h'), dict) else {}
    for i, d in enumerate(ph.get('d') or []):
        dd = _cftc_iso(d)
        vals = {'oi': _cftc_hv(ph.get('oi'), i), **{f: _cftc_hv(ph.get(f), i) for f, _ in fields}}
        if dd and 0 < (ld - dd).days <= CFTC_SPAN_DAYS and vals['oi'] and vals['net'] is not None:
            H[d] = vals
    for d in days:
        dd = _cftc_iso(d)
        if (ld - dd).days <= CFTC_SPAN_DAYS:
            H[d] = {'oi': recs[d]['oi'], **{f: recs[d]['g'][g]['net'] for f, g in fields}}
    hd = sorted(H)[-CFTC_WEEKS:]
    oi, n = last['oi'], last['g'][glowna]['net']
    pct = round(100.0 * n / oi, 1) if oi and n is not None else None
    w = H.get((ld - datetime.timedelta(days=7)).isoformat())
    e = {'code': code, 'asof': days[-1], 'oi': oi, 'net': n, 'pct': pct,
         'd1': n - w['net'] if w and n is not None and w['net'] is not None else None,
         'd1p': round(100.0 * n / oi - 100.0 * w['net'] / w['oi'], 1) if w and pct is not None and w['net'] is not None and w['oi'] else None,   # v301: z dokładnych udziałów
         'pos': {gk: [x['long'], x['short'], x['spread']] for gk, x in last['g'].items()},
         'h': {'d': hd, 'oi': [H[d]['oi'] for d in hd], **{f: [H[d][f] for d in hd] for f, _ in fields}}}
    if extra:
        e.update(extra)
    return e


def _su_poz_zapisz(ctx, sub, pairs, rows, prev_sub, glowna, hf=(), extra=None, nazwa=''):
    """Wpisy jednej podczęści (cftc, ice, cit, tff) z rekordów rows {kod: {dzień: rekord}}; pairs — [(id, kod, dodatki wpisu)]. Rynek bez
    rekordów — notatka; poprzedni wpis zostaje (najwyżej CFTC_KEEP_DAYS dni od jego daty) z polem kept. Bez żadnego rynku = wyjątek."""
    out, brak, now = {}, [], ctx['now'].date()
    starsze = []   # v301: rynki z danymi starszymi niż poprzedni wpis
    for k, code, dod in pairs:
        recs = rows.get(code) or {}
        pe = prev_sub.get(k) if isinstance(prev_sub.get(k), dict) else None
        pd = _cftc_iso(pe.get('asof')) if pe else None
        nd = max((x for x in map(_cftc_iso, recs) if x), default=None)
        if pd and nd and nd < pd:   # v301: dane starsze niż poprzedni wpis tego rynku (plik roku poprzedniego, plik sprzed podmiany) nie
            starsze.append(k)       # zastępują go — poprzedni zostaje jak przy braku rynku (kept, najwyżej CFTC_KEEP_DAYS dni od jego daty)
        elif recs:
            out[k] = _su_poz_wpis(code, recs, pe, glowna, hf, dict(extra or {}, **(dod or {})))
            continue
        else:
            brak.append(k)
        if pd and 0 <= (now - pd).days <= CFTC_KEEP_DAYS:
            out[k] = dict(pe, kept=True)
    if brak:
        ctx['uwagi'].append(f'pozycje {nazwa or sub}: brak rynku w raporcie — {", ".join(brak[:8])}' + (' …' if len(brak) > 8 else ''))
    if starsze:
        ctx['uwagi'].append(f'pozycje {nazwa or sub}: dane starsze niż poprzedni wpis (zostaje poprzedni) — {", ".join(starsze[:8])}'
                            + (' …' if len(starsze) > 8 else ''))
    if not any(not e.get('kept') for e in out.values()):
        raise RuntimeError('dane starsze niż poprzednie wpisy (poprzednie zostają)' if starsze else 'żaden rynek nie ma danych z tego pobrania')
    ctx['poz'][sub] = out
    return max(e['asof'] for e in out.values() if not e.get('kept'))


def _su_poz_prev(ctx, sub):
    pp = ctx['prev'].get('pozycje') if isinstance(ctx.get('prev'), dict) and isinstance(ctx['prev'].get('pozycje'), dict) else {}
    return pp.get(sub) if isinstance(pp.get(sub), dict) else {}


def _su_poz_krotka(rows, pairs, prev_sub):
    """Czy historia któregoś rynku (nowe rekordy + poprzedni wpis) ma mniej niż 13 tygodni — wtedy plik roczny."""
    for k, code, _ in pairs:
        d = set(rows.get(code) or {})
        pe = prev_sub.get(k) if isinstance(prev_sub.get(k), dict) else {}
        d |= set(((pe.get('h') or {}).get('d') or []) if isinstance(pe.get('h'), dict) else [])
        if len(d) < CFTC_WEEKS:
            return True
    return False


def _su_poz_rok(ctx, src, rows, prev_sub, pairs):
    """Czy pobrać plik roczny: historia któregoś rynku krótsza niż 13 tygodni i plik roczny nie był pobierany dla tego raportu (najwyżej raz
    na raport tygodniowy — rynek z krótką historią, np. nowy, nie ściąga pliku przy każdym przebiegu). Zapamiętuje raport w st[src]['rok']."""
    z = ctx['st'].setdefault(src, {})
    tyg = max((d for days in rows.values() for d in days), default='')
    if not _su_poz_krotka(rows, pairs, prev_sub) or z.get('rok') == tyg:
        return False
    z['rok'] = tyg
    return True


def _su_raw(ctx, src, url):
    """Odpowiedź lidera z tego przebiegu (ctx['raw']) albo własne pobranie źródła src."""
    raw = ctx.get('raw') if isinstance(ctx.get('raw'), dict) else {}
    return raw[url] if url in raw else _su_get(ctx, src, url)


def _su_zip_txt(b):
    with zipfile.ZipFile(io.BytesIO(b)) as z:
        names = [n for n in z.namelist() if n.lower().endswith('.txt')]
        if not names:
            raise RuntimeError('brak pliku .txt w archiwum')
        return z.read(names[0]).decode('utf-8', 'replace')


def _su_poz_dodaj(rows, bad, parsed, nadpisz=True):
    p, b = parsed
    bad.extend(b)
    for code, days in p.items():
        tgt = rows.setdefault(code, {})
        for d, rec in days.items():
            if nadpisz or d not in tgt:
                tgt[d] = rec


def _su_poz_cftcd(ctx):
    """Pozycje — CFTC disaggregated, 30 rynków (SU_POZ_CFTC): pliki roczny i tygodniowy z pobrania części „markets” w tym przebiegu (bez
    zapytań); bez niego — własne pobranie (rok bieżący, tydzień; rok poprzedni przy krótkiej historii w styczniu–kwietniu)."""
    pairs = [(k, c, {'g': g}) for k, c, g in SU_POZ_CFTC]
    want, prev_sub, now = {c for _, c, _ in pairs}, _su_poz_prev(ctx, 'cftc'), ctx['now']
    raw = ctx.get('raw') if isinstance(ctx.get('raw'), dict) else {}
    rows, bad = {}, []

    def rok(y, nadpisz=True):
        try:
            _su_poz_dodaj(rows, bad, parse_cftcd(_su_zip_txt(_su_raw(ctx, 'cftcd', CFTCD_YEAR_URL.format(y))), want=want), nadpisz)
        except urllib.error.HTTPError as e:
            (ctx['uwagi'] if e.code == 404 else ctx['bledy']).append(f'cftcd rok {y}: HTTP {e.code}')
        except Exception as e:
            ctx['bledy'].append(f'cftcd rok {y}: {e}')
    for y in sorted(y for y in (now.year - 1, now.year) if CFTCD_YEAR_URL.format(y) in raw) or [now.year]:
        rok(y)
    try:
        _su_poz_dodaj(rows, bad, parse_cftcd(_su_raw(ctx, 'cftcd', CFTCD_WEEK_URL).decode('utf-8', 'replace'), header=CFTCD_COLS, want=want))
    except Exception as e:
        ctx['bledy'].append(f'cftcd tydzień: {e}')
    if CFTCD_YEAR_URL.format(now.year - 1) not in raw and now.month <= 4 and _su_poz_rok(ctx, 'cftcd', rows, prev_sub, pairs):
        rok(now.year - 1, nadpisz=False)
    if bad:
        ctx['uwagi'].append('pozycje cftc: suma pozycji ≠ open interest (wiersz pominięty) — ' + ', '.join(bad[-5:]))
    return _su_poz_zapisz(ctx, 'cftc', pairs, rows, prev_sub, 'mm', nazwa='USA (30 rynków)')


def _su_poz_ice_plik(ctx, src, url, poz, glowna, nazwa):
    """Pozycje — ICE Futures Europe (plik roczny CSV ok. 0,3 MB); rok poprzedni tylko przy krótkiej historii (start, styczeń–kwiecień) albo
    gdy pliku bieżącego roku jeszcze nie ma (HTTP 404 albo plik bez wierszy rynków) — v301: wtedy tylko w styczniu albo bez wpisów z bieżącego
    roku; w innym miesiącu to błąd części (wpisy zostają z datą), nie dane sprzed roku."""
    pairs = [(k, c, {'g': g}) for k, c, g in poz]
    prev_sub, now = _su_poz_prev(ctx, src), ctx['now']
    rows, bad = {}, []

    def rok(y, nadpisz=True):
        t = _su_get(ctx, src, url.format(y)).decode('utf-8-sig', 'replace')
        p = parse_ice_cot(t, poz) if t.strip('\ufeff \t\r\n') else ({}, [])   # v301: plik bez treści — jak plik bez wierszy (nie wyjątek)
        _su_poz_dodaj(rows, bad, p, nadpisz)
        return any(p[0].values())
    nie = None   # v301: (opis błędu, notatka) — plik bieżącego roku bez wierszy rynków (przed pierwszym raportem roku) jak HTTP 404
    try:
        if not rok(now.year):
            nie = (f'plik {now.year} bez wierszy rynków', f'plik {now.year} bez wierszy rynków — rok poprzedni (w pierwszych dniach stycznia to normalne)')
    except urllib.error.HTTPError as e:
        if e.code != 404:
            raise
        nie = (f'brak pliku {now.year} (HTTP 404)', f'brak pliku {now.year} (HTTP 404 — w pierwszych dniach stycznia to normalne)')
    if nie and now.month != 1 and any(isinstance(e, dict) and str(e.get('asof') or '')[:5] == f'{now.year}-' for e in prev_sub.values()):
        # v301 (przegląd): rok poprzedni tylko w styczniu albo bez wpisów z bieżącego roku (start, długa przerwa). W innym miesiącu brak pliku
        # albo plik bez wierszy (np. w piątek w chwili podmiany pliku ok. 17:44 UTC, gdy automat pyta co 30 min) to błąd części — wpisy zostają
        # z datą, bez zapytania o rok poprzedni; dawniej dane sprzed roku zastępowały świeższe (09.10.2026: Londyn „stan na 29 wrz 2025”)
        raise RuntimeError(f'{nie[0]} — poza styczniem bez roku poprzedniego (wpisy z {now.year} zostają z datą)')
    if nie:
        ctx['uwagi'].append(f'pozycje {src}: ' + nie[1])
    if nie or (now.month <= 4 and _su_poz_rok(ctx, src, rows, prev_sub, pairs)):
        rok(now.year - 1, nadpisz=False)
    if bad:
        ctx['uwagi'].append(f'pozycje {src}: suma pozycji ≠ open interest albo zła data (wiersz pominięty) — ' + ', '.join(bad[-5:]))
    return _su_poz_zapisz(ctx, src, pairs, rows, prev_sub, glowna, nazwa=nazwa)


def _su_poz_ice(ctx):
    """Pozycje — ICE Futures Europe (Londyn): plik roczny COTHist{rok}.csv; logika w _su_poz_ice_plik (v421: wspólna z Murbanem)."""
    return _su_poz_ice_plik(ctx, 'ice', SU_ICE_URL, SU_POZ_ICE, 'mm', 'Londyn')


def _su_poz_iceab(ctx):
    """v421 (F11Z24): pozycje — ICE Futures Abu Dhabi (ropa Murban): IFADCOTHist{rok}.csv, ten sam układ i rok poprzedni jak w Londynie; grupa
    główna 'prod' (producenci i handlowcy). Źródło uzupełniające (SU_MIEKKIE): jego błąd nie psuje części pozycje."""
    return _su_poz_ice_plik(ctx, 'iceab', SU_AB_URL, SU_POZ_AB, 'prod', 'Abu Zabi')




def _su_poz_cit(ctx):
    """Pozycje — CFTC CIT (fundusze indeksowe, 13 rynków rolnych): plik tygodniowy (6,5 KB); roczny (70 KB) tylko przy krótkiej historii."""
    kod = {k: c for k, c, _ in SU_POZ_CFTC}
    pairs = [(k, kod[k], {}) for k in SU_POZ_CIT]
    prev_sub, now = _su_poz_prev(ctx, 'cit'), ctx['now']
    rows, bad = {}, []
    _su_poz_dodaj(rows, bad, parse_cit(_su_get(ctx, 'cit', SU_CIT_WEEK_URL).decode('utf-8', 'replace'), header=SU_CIT_COLS))
    if _su_poz_rok(ctx, 'cit', rows, prev_sub, pairs):
        for y in (now.year, now.year - 1):
            try:
                _su_poz_dodaj(rows, bad, parse_cit(_su_zip_txt(_su_get(ctx, 'cit', SU_CIT_YEAR_URL.format(y)))), nadpisz=False)
            except urllib.error.HTTPError as e:
                (ctx['uwagi'] if e.code == 404 else ctx['bledy']).append(f'cit rok {y}: HTTP {e.code}')
            if now.month > 4 or not _su_poz_krotka(rows, pairs, prev_sub):
                break
    if bad:
        ctx['uwagi'].append('pozycje cit: suma pozycji ≠ open interest (wiersz pominięty) — ' + ', '.join(bad[-5:]))
    for c, days in rows.items():
        for rec in days.values():
            rec['pct_l'] = round(100.0 * rec['g']['cit']['long'] / rec['oi'], 1) if rec['oi'] else None
    out = _su_poz_zapisz(ctx, 'cit', pairs, rows, prev_sub, 'cit', nazwa='fundusze indeksowe')
    for k, e in ctx['poz']['cit'].items():
        if not e.get('kept'):
            r = (rows.get(e['code']) or {}).get(e['asof'])
            e['pct_l'] = r.get('pct_l') if r else None   # udział długich pozycji funduszy indeksowych w open interest (%)
    return out


def _su_poz_tff(ctx):
    """Pozycje — CFTC TFF, kod 221602 (kontrakty na szeroki indeks surowców): plik tygodniowy FinFutWk.txt (73 KB, ten sam co data/cftc.json);
    roczny (0,55 MB) tylko przy krótkiej historii. Grupa główna: zarządzający aktywami (asset_mgr); w historii także netto dealerów (dn)."""
    pairs = [(k, c, {}) for k, c in SU_POZ_TFF]
    codes, prev_sub, now = {c for _, c in SU_POZ_TFF}, _su_poz_prev(ctx, 'tff'), ctx['now']
    rows, bad = {}, []

    def dodaj(parsed, nadpisz=True):
        for code, days in parsed.items():
            for d, r in days.items():
                rec = cftc_record(r)
                if not cftc_consistent(rec):
                    bad.append(f'{code} {d}'); continue
                if nadpisz or d not in rows.get(code, {}):
                    rows.setdefault(code, {})[d] = rec
    dodaj(parse_cftc_csv(_su_get(ctx, 'tff', CFTC_WEEK_URL).decode('utf-8', 'replace'), header=CFTC_COLS, codes=codes))
    if _su_poz_rok(ctx, 'tff', rows, prev_sub, pairs):
        for y in (now.year, now.year - 1):
            try:
                dodaj(parse_cftc_csv(_su_zip_txt(_su_get(ctx, 'tff', CFTC_YEAR_URL.format(y))), codes=codes), nadpisz=False)
            except urllib.error.HTTPError as e:
                (ctx['uwagi'] if e.code == 404 else ctx['bledy']).append(f'tff rok {y}: HTTP {e.code}')
            if now.month > 4 or not _su_poz_krotka(rows, pairs, prev_sub):
                break
    if bad:
        ctx['uwagi'].append('pozycje tff: suma pozycji ≠ open interest (wiersz pominięty) — ' + ', '.join(bad[-5:]))
    return _su_poz_zapisz(ctx, 'tff', pairs, rows, prev_sub, 'asset_mgr', hf=(('dn', 'dealer'),), nazwa='indeks surowców')


# ---- fundusze ----
def _su_fu_spdr(ctx, src, produkt, data):
    g = parse_spdr_ilosc(data, produkt)
    last = max(g)
    od = (datetime.date.fromisoformat(last) - datetime.timedelta(days=SU_FU_HIST_DNI)).isoformat()
    tgt = ctx['H']['f'].setdefault(produkt, {})
    for d, (oz, _r) in g.items():
        if d >= od:
            tgt[d] = round(oz / SU_OZ_T, 3)
    z = ctx['st'].setdefault(src, {})
    z['q'] = {produkt: [last, round(g[last][0], 2)]}
    z['nav_r'] = {produkt: g[last][1]}   # odchylenie wartości aktywów od uncji × ceny (%) — kontrola dzienna
    return last


def _su_fu_gld(ctx):
    """Fundusze — GLD: archiwum z pobrania ceny złota w tym przebiegu (źródło gld; bez zapytania) albo własne pobranie."""
    return _su_fu_spdr(ctx, 'gld_t', 'GLD', _su_raw(ctx, 'gld_t', SU_GLD_URL))


def _su_fu_gldm(ctx):
    """Fundusze — GLDM: archiwum funduszu (0,2 MB), te same terminy co GLD."""
    return _su_fu_spdr(ctx, 'gldm', 'GLDM', _su_get(ctx, 'gldm', SU_GLDM_URL))


def _su_fu_sprott(ctx):
    """Fundusze — trusty fizyczne Sprott (odpowiedź źródła sprott z tego przebiegu albo własne pobranie): ilości metalu. Bez udanego lidera
    w tym przebiegu — także sprawdzenie kolejności listy złotem i srebrem (jak w _su_sprott). Skok ilości > SU_FU_SKOK w ≤ 7 dni = punkt odrzucony."""
    j = _su_json(_su_raw(ctx, 'sprott_t', SU_SPROTT_URL))
    day, _vals, kon = parse_sprott(j)
    if 'sprott' not in (ctx.get('udane') or ()):
        od = (datetime.date.fromisoformat(day) - datetime.timedelta(days=7)).isoformat()
        for cid, tol in (('gold', 0.05), ('silver', 0.10)):
            ref = _su_last(sorted((d, x) for d, x in (ctx['H']['d'].get(cid) or {}).items() if od <= d <= day))
            if ref and abs(kon[cid] / ref[1] - 1) > tol:
                raise RuntimeError(f'{cid} z listy {kon[cid]:.2f} wobec {ref[1]} ({ref[0]}) — zmiana kolejności listy? odpowiedź odrzucona')
    il = parse_sprott_ilosci(j)
    jedn = {fid: qu for fid, _m, _u, _z, qu in SU_FU}
    q, asof = {}, ''
    for fid, (d, x) in il.items():
        v = round(x / SU_OZ_T, 3) if jedn[fid] == 'oz' else (round(x / 1e6, 3) if jedn[fid] == 'lb' else round(x, 3))
        tgt = ctx['H']['f'].setdefault(fid, {})
        p = _su_last(sorted((a, b) for a, b in tgt.items() if a < d))
        if p and (datetime.date.fromisoformat(d) - datetime.date.fromisoformat(p[0])).days <= 7 and abs(v / p[1] - 1) > SU_FU_SKOK_FU.get(fid, SU_FU_SKOK):
            ctx['bledy'].append(f'sprott_t {fid}: {p[1]} → {v} ({(v / p[1] - 1) * 100:+.0f}%) — punkt odrzucony (zmiana kolejności listy?)'); continue
        tgt[d] = v
        q[fid] = [d, x]
        asof = max(asof, d)
    if not q:
        raise RuntimeError('żaden fundusz bez błędu')
    ctx['st'].setdefault('sprott_t', {})['q'] = q
    return asof


def _su_fu_iau(H, fund):
    """IAU — tony złota wyliczone: wartość aktywów (NAV × liczba jednostek z pliku funduszy strony; dni bez błędu pliku wg _fund_clean) ÷ cena
    złota z tego samego dnia (LBMA PM wyliczona z archiwum GLD — tą ceną fundusz wycenia złoto) ÷ 32 150,7466. Sprawdzone 06.10.2026: 463,52 t
    wobec 463,54 t na stronie wydawcy (−0,003%). Plik funduszy z poprzedniego przebiegu (ten budowniczy działa przed funduszami) — dzień później
    o jeden przebieg. Oznaczenie x 'wyl'."""
    fi = ((fund or {}).get('f') or {}).get('IAU') if isinstance(fund, dict) and isinstance(fund.get('f'), dict) else None
    h = fi.get('h') if isinstance(fi, dict) else None
    if not isinstance(h, list):
        return None
    G, tgt, last = H['d'].get('gold') or {}, H['f'].setdefault('IAU', {}), None
    for r in _fund_clean(h)[0]:
        d, nav, u = r
        p = G.get(d) if isinstance(d, str) else None
        if _isnum(nav) and _isnum(u) and nav > 0 and u > 0 and _isnum(p) and p > 0:
            tgt[d] = round(nav * u / p / SU_OZ_T, 3)
            last = [d, round(nav * u / p, 2)] if last is None or d >= last[0] else last
    return last


def _su_w1(rows):
    """Zmiana tygodnia: [dzień odniesienia, ostatnia − wartość z ostatniego dnia ≤ ostatni − 7 dni (w ciągu 14 dni)] albo None."""
    if not rows:
        return None
    ld = datetime.date.fromisoformat(rows[-1][0])
    ref = next((r for r in reversed(rows) if (ld - datetime.date.fromisoformat(r[0])).days >= 7), None)
    if not ref or (ld - datetime.date.fromisoformat(ref[0])).days > 14 or not _isnum(ref[1]) or not _isnum(rows[-1][1]):
        return None
    return [ref[0], round(rows[-1][1] - ref[1], 3)]


def _su_fu_sumy(F):
    """Sumy złota w funduszach ({id sumy: [[dzień, t]]}) w dniach sesji NYSE według GLD: dzień tylko, gdy każdy fundusz ma wartość — z tego dnia
    albo (dziura wewnątrz serii: święto giełdy) z ostatniego dnia ≤ SU_FU_LUKA dni wcześniej; nigdy za końcem serii (bez przedłużania)."""
    out = {}
    for sid, sklad in SU_FU_SUMY:
        S = {f: sorted((d, v) for d, v in (F.get(f) or {}).items() if _isnum(v)) for f in sklad}
        if not all(S.values()):
            continue
        K = {f: [d for d, _ in s] for f, s in S.items()}
        rows = []
        for D in K['GLD']:
            tot = 0.0
            for f in sklad:
                i = bisect.bisect_right(K[f], D) - 1
                if i < 0:
                    break
                if K[f][i] != D and (i + 1 >= len(K[f]) or (datetime.date.fromisoformat(D) - datetime.date.fromisoformat(K[f][i])).days > SU_FU_LUKA):
                    break
                tot += S[f][i][1]
            else:
                rows.append([D, round(tot, 3)])
        if rows:
            out[sid] = rows
    return out


# ---- banki ----
def _su_bk_imf(ctx):
    """Banki — MFW IL: złoto w uncjach dla 55 krajów (jedno zapytanie, ok. 65 KB); historia łączona z poprzednią (kraj ze swoim miesiącem)."""
    odrz = []
    got, inna = parse_imf_il_zloto(_su_json(_su_get(ctx, 'imf_il', SU_IMF_IL_ZL_URL, {'Accept': 'application/json'})), odrz)
    if odrz:
        ctx['uwagi'].append('banki: kraj poza zakresem skali (pominięty, poprzednie dane zostają) — ' + ', '.join(odrz))
    if inna:
        ctx['uwagi'].append('banki: inna jednostka złota niż uncje (pominięte) — ' + ', '.join(inna))
    brak = [c2 for c2, _ in SU_BANKI if c2 not in got]
    if brak:
        ctx['uwagi'].append('banki: brak kraju w odpowiedzi MFW (poprzednie dane zostają) — ' + ', '.join(brak))
    for c2, rows in got.items():
        ctx['H']['b'].setdefault(c2, {}).update(rows)
    return max(max(r) for r in got.values())


def _su_bk_safe(ctx):
    """Banki — SAFE (Chiny): strona „Official Reserve Assets” (18 KB) → plik miesiąca (16 KB; adres zmienia się co miesiąc)."""
    page = _su_get(ctx, 'safe_zl', SU_SAFE_ZL_PAGE).decode('utf-8', 'replace')
    if 'Official Reserve Assets' not in page:
        raise RuntimeError('strona bez tytułu „Official Reserve Assets” — zmiana adresu?')
    m = re.search(r'href="([^"]+\.xlsx)"', page)
    if not m:
        raise RuntimeError('brak odnośnika do pliku na stronie')
    url = m.group(1) if m.group(1).startswith('http') else 'https://www.safe.gov.cn' + m.group(1)
    data = _su_get(ctx, 'safe_zl', url)
    rows = parse_safe_zloto(data)
    ctx['H']['b'].setdefault('CN_safe', {}).update(rows)
    try:   # v338 (F1Z4): z tego samego pliku — rezerwy Chin razem (tabela rezerw na stronie); błąd tej części nie odrzuca złota
        ctx.setdefault('rez', {})['CN'] = parse_safe_rezerwy(data)
    except Exception as e:  # noqa: BLE001
        ctx['uwagi'].append(f'banki: rezerwy Chin z pliku odrzucone ({mask(str(e))[:100]}) — złoto zapisane')
    return max(rows)


# ---- v338 (F1Z4): druga tabela MFW (IRFCL, rezerwy płynne w walutach) — Rosja o miesiące świeższa niż w głównej tabeli (IL); Polska — kontrola ----
# Główna tabela (IL) ma Rosję tylko do listopada 2025 (kraj publikuje tam z dużym opóźnieniem), a IRFCL — do sierpnia 2026, w tych samych uncjach
# (nagranie 10.10.2026: lipiec–listopad 2025 identyczne). IRFCL bierzemy WYŁĄCZNIE dla krajów sprawdzonych na nagraniach: Brazylia podaje tam
# złoto w innej skali (5,54 mld „uncji” zamiast 5,54 mln), więc inne kraje wymagałyby osobnego sprawdzenia skali. Z drugiej tabeli na stronę trafiają
# miesiące WYŁĄCZNIE Rosji (i tylko nowsze niż w głównej tabeli); Polska służy tylko do kontroli dziennej (IRFCL zaokrągla do 1000 uncji: 20 833 000
# wobec 20 833 322,9 w IL; Rosja — do 100 000 uncji, więc mieszanie źródeł w jednym szeregu Polski dawałoby sztuczne ±0,03 t).
SU_IRFCL = (('RU', 'RUS'), ('PL', 'POL'))
SU_IMF_IRFCL_URL = ('https://api.imf.org/external/sdmx/3.0/data/dataflow/IMF.STA/IRFCL/+/' + '+'.join(c3 for _, c3 in SU_IRFCL)
                    + '.IRFCLDT1_IRFCL56V_FTO.S1XS1311.M?lastNObservations=24')   # ok. 6 KB; 10.10.2026: Rosja VIII 2026 (IL: XI 2025), Polska VIII 2026; 24 mies. — długie okno wspólne z IL do sprawdzenia skali
SU_IRFCL_TOL = 0.01   # największa względna różnica wobec głównej tabeli w miesiącach wspólnych (zaokrąglenia IRFCL: do 0,07%); więcej = kraj odrzucony


def parse_irfcl_zloto(j, odrz=None):
    """MFW IRFCL, wskaźnik IRFCL56V_FTO (złoto w rezerwach oficjalnych, uncje trojańskie) → {kraj ISO2: {RRRR-MM: uncje}} dla krajów SU_IRFCL.
    Straż skali jak w głównej tabeli (SU_BANKI_T): kraj spoza zakresu ton jest pomijany (odrz — jego opis), odpowiedź bez żadnego kraju = błąd."""
    ser = parse_imf_sdmx(j)
    iso = {c3: c2 for c2, c3 in SU_IRFCL}
    out = {}
    for lab, rows in ser.items():
        if len(lab) != 4 or lab[1] != 'IRFCLDT1_IRFCL56V_FTO' or lab[3] != 'M' or lab[0] not in iso:
            continue
        out[iso[lab[0]]] = {m: v for m, v in rows}
    if not out:
        raise RuntimeError('brak serii złota (IRFCL56V_FTO) dla Rosji i Polski')
    for c2 in sorted(out):
        t = out[c2][max(out[c2])] / SU_OZ_T
        if not SU_BANKI_T[0] <= t <= SU_BANKI_T[1]:
            if odrz is not None:
                odrz.append(f'{c2} ({t:.1f} t poza zakresem)')
            del out[c2]
    if not out:
        raise RuntimeError('złoto z drugiej tabeli poza zakresem skali — zmiana skali? odpowiedź odrzucona')
    return out


def _su_bk_irfcl(ctx):
    """Banki — MFW IRFCL: złoto Rosji (miesiące nowsze niż w IL) i Polski (kontrola). Źródło uzupełniające (SU_MIEKKIE) po imf_il: każdy kraj musi
    zgadzać się z główną tabelą w miesiącach wspólnych (SU_IRFCL_TOL) — inaczej ten kraj jest pominięty (zła skala albo inna definicja).
    Wzorzec skali: główna tabela, a w miesiącach, których w niej brak — wcześniej PRZYJĘTA seria drugiej tabeli (c2_irfcl; jej skala była już sprawdzona
    wobec głównej). Dzięki temu Rosja nie przestaje się odświeżać, gdy główna tabela stoi dłużej niż okno pobrania (przegląd v338)."""
    odrz = []
    got = parse_irfcl_zloto(_su_json(_su_get(ctx, 'irfcl', SU_IMF_IRFCL_URL, {'Accept': 'application/json'})), odrz)
    dobre, uwagi = {}, list(odrz)
    for c2, rows in sorted(got.items()):
        il = {m: v for m, v in (ctx['H']['b'].get(c2) or {}).items() if _isnum(v)}
        il = dict({m: v for m, v in (ctx['H']['b'].get(c2 + '_irfcl') or {}).items() if _isnum(v)}, **il)   # główna tabela ma pierwszeństwo
        wsp = sorted(set(rows) & set(il))
        if not wsp:
            uwagi.append(f'{c2}: brak miesięcy wspólnych z główną tabelą — skali nie da się sprawdzić'); continue
        zly = [m for m in wsp if abs(rows[m] - il[m]) > SU_IRFCL_TOL * il[m]]
        if zly:
            m = zly[-1]
            uwagi.append(f'{c2}: {m} {rows[m] / SU_OZ_T:.1f} t wobec {il[m] / SU_OZ_T:.1f} t w głównej tabeli'); continue
        dobre[c2] = rows
    if not dobre:
        raise RuntimeError('złoto z drugiej tabeli odrzucone — ' + '; '.join(uwagi))
    if uwagi:
        ctx['uwagi'].append('banki: druga tabela — kraj pominięty: ' + '; '.join(uwagi))
    for c2, rows in dobre.items():
        ctx['H']['b'].setdefault(c2 + '_irfcl', {}).update(rows)
    return max(max(r) for r in dobre.values())


SU_POBIERZ.update({'cftcd': _su_poz_cftcd, 'ice': _su_poz_ice, 'iceab': _su_poz_iceab, 'cit': _su_poz_cit, 'tff': _su_poz_tff, 'gld_t': _su_fu_gld, 'gldm': _su_fu_gldm,
                   'sprott_t': _su_fu_sprott, 'imf_il': _su_bk_imf, 'irfcl': _su_bk_irfcl, 'safe_zl': _su_bk_safe})


def _su_hist3(H, prev):
    """Historia etapu 3 z poprzedniego surowce.json (gdy brak surowce-hist.json): ilości funduszy (f) i złoto banków (b; uncje z ton — ostatni
    miesiąc dokładnie z pola oz)."""
    if not (isinstance(prev, dict) and prev.get('v') == SU_V):
        return
    fu = prev.get('fundusze') if isinstance(prev.get('fundusze'), dict) else {}
    for fid, e in ((fu.get('f') or {}).items() if isinstance(fu.get('f'), dict) else ()):
        for r in (e.get('d') or []) if isinstance(e, dict) else []:
            if isinstance(r, list) and len(r) == 2 and isinstance(r[0], str) and _isnum(r[1]):
                H['f'].setdefault(fid, {}).setdefault(r[0], r[1])
    bk = prev.get('banki') if isinstance(prev.get('banki'), dict) else {}
    for c2, e in ((bk.get('kr') or {}).items() if isinstance(bk.get('kr'), dict) else ()):
        if not isinstance(e, dict):
            continue
        od = e.get('safe_od') if c2 == 'CN' and isinstance(e.get('safe_od'), str) else None   # miesiące z SAFE (Chiny) — do osobnej serii
        odi = e.get('irfcl_od') if isinstance(e.get('irfcl_od'), str) else None   # v338: miesiące z drugiej tabeli MFW (Rosja, Polska) — też osobna seria
        for r in e.get('d') or []:
            if isinstance(r, list) and len(r) == 2 and isinstance(r[0], str) and _isnum(r[1]):
                tgt = H['b'].setdefault('CN_safe' if od and r[0] >= od else (c2 + '_irfcl' if odi and r[0] >= odi else c2), {})
                tgt.setdefault(r[0], e['oz'] if r[0] == e.get('asof') and _isnum(e.get('oz')) else round(r[1] * SU_OZ_T, 2))


def _su_etap3(ctx, prev):
    """Części pozycje, fundusze i banki pliku surowce.json (z historii H i wyników źródeł tego przebiegu; źródło bez pobrania = poprzednie
    dane z ich datą) oraz sumy złota w funduszach do surowce-hist.json (klucz fs)."""
    H, st = ctx['H'], ctx['st']
    prev = prev if isinstance(prev, dict) and prev.get('v') == SU_V else {}
    # pozycje
    pp = prev.get('pozycje') if isinstance(prev.get('pozycje'), dict) else {}
    poz = {'unit': 'kontrakty', 'asof': {}}
    for sub, ids in (('cftc', [k for k, _, _ in SU_POZ_CFTC]), ('ice', [k for k, _, _ in SU_POZ_ICE]), ('iceab', [k for k, _, _ in SU_POZ_AB]), ('cit', list(SU_POZ_CIT)),
                     ('tff', [k for k, _ in SU_POZ_TFF])):
        src = ctx['poz'].get(sub)
        if src is None:   # podczęść bez pobrania w tym przebiegu — poprzednie wpisy (z ich datami)
            src = {k: e for k, e in (pp.get(sub) or {}).items() if isinstance(e, dict)} if isinstance(pp.get(sub), dict) else {}
        poz[sub] = {k: src[k] for k in ids if k in src}
        a = [e['asof'] for e in poz[sub].values() if isinstance(e.get('asof'), str)]
        if a:
            poz['asof'][sub] = max(a)
    # fundusze
    iau = _su_fu_iau(H, ctx.get('fund'))
    q = {}
    for src in ('gld_t', 'gldm', 'sprott_t'):
        q.update((st.get(src) or {}).get('q') or {})
    if iau:
        q['IAU'] = iau
    nav = {**((st.get('gld_t') or {}).get('nav_r') or {}), **((st.get('gldm') or {}).get('nav_r') or {})}
    f = {}
    for fid, metal, u, z, qu in SU_FU:
        rows = [[d, v] for d, v in sorted((H['f'].get(fid) or {}).items()) if _isnum(v)][-SU_FU_DNI:]
        if not rows:
            continue
        e = {'m': metal, 'u': u, 'z': z, 'asof': rows[-1][0], 'd': rows, 'w1': _su_w1(rows), 'qu': qu}
        if fid == 'IAU':
            e['x'] = ['wyl']
        if isinstance(q.get(fid), list) and len(q[fid]) == 2:
            e['q'] = q[fid]
        if fid in nav and nav[fid] is not None:
            e['nav_r'] = nav[fid]
        f[fid] = e
    sumy = _su_fu_sumy(H['f'])
    suma = {}
    for sid, sklad in SU_FU_SUMY:
        rows = (sumy.get(sid) or [])[-SU_FU_DNI:]
        if rows:
            suma[sid] = {'u': 't', 'sklad': list(sklad), 'asof': rows[-1][0], 'd': rows, 'w1': _su_w1(rows)}
            xs = [x for fid in sklad for x in ((f.get(fid) or {}).get('x') or [])]   # v301: suma z funduszem wyliczonym (IAU: 'wyl') — też
            if xs:                                                                  # oznaczona (zasada strony: szacunki są opisane)
                suma[sid]['x'] = list(dict.fromkeys(xs))
    fund = {'u': 't', 'f': f, 'suma': suma}
    # banki
    safe = {m: v for m, v in (H['b'].get('CN_safe') or {}).items() if _isnum(v)}
    irfcl = {c2: {m: v for m, v in (H['b'].get(c2 + '_irfcl') or {}).items() if _isnum(v)} for c2 in ('RU', 'PL')}   # v338: druga tabela MFW
    kr = {}
    for c2, _c3 in SU_BANKI:
        imf = {m: v for m, v in (H['b'].get(c2) or {}).items() if _isnum(v)}
        rows, zr = dict(imf), {m: 'imf' for m in imf}
        if c2 == 'CN':
            for m, v in safe.items():
                if not imf or m > max(imf):
                    rows[m], zr[m] = v, 'safe'
        for m, v in ((irfcl.get(c2) or {}).items() if c2 == 'RU' else ()):   # v338 (F1Z4): miesiące z drugiej tabeli MFW — tylko Rosja i tylko nowsze niż w głównej
            if not imf or m > max(imf):                # tabeli (stare miesiące zawsze z głównej; Polska z drugiej tabeli — wyłącznie kontrola, jej zaokrąglenia do 1000 uncji)
                rows[m], zr[m] = v, 'irfcl'
        if not rows:
            continue
        ks = sorted(rows)[-(SU_BANKI_M if c2 in SU_BANKI_PIERWSZE else SU_BANKI_M_NOWE):]
        last = ks[-1]
        p1, p12 = _imf_month_add(last, -1), _imf_month_add(last, -12)
        e = {'u': 't', 'asof': last, 'z': zr[last], 'oz': rows[last], 'd': [[m, round(rows[m] / SU_OZ_T, 3)] for m in ks],
             'm1': round((rows[last] - rows[p1]) / SU_OZ_T, 3) if p1 in rows else None,
             'm12': round((rows[last] - rows[p12]) / SU_OZ_T, 3) if p12 in rows else None}
        if c2 == 'CN':
            od = [m for m in ks if zr[m] == 'safe']
            if od:
                e['safe_od'] = od[0]   # pierwszy miesiąc z SAFE (nowszy niż ostatni miesiąc MFW)
            wsp = sorted(set(imf) & set(safe))[-6:]
            if wsp:
                e['kontr'] = [[m, imf[m], safe[m]] for m in wsp]   # ten sam miesiąc z dwóch źródeł (uncje) — kontrola dzienna
        if irfcl.get(c2):   # v338: Rosja i Polska — druga tabela MFW (miesiące na stronie tylko Rosji; u Polski — wspólne miesiące do kontroli)
            od = [m for m in ks if zr[m] == 'irfcl']
            if od:
                e['irfcl_od'] = od[0]   # pierwszy miesiąc z drugiej tabeli (nowszy niż ostatni miesiąc głównej)
            wsp = sorted(set(imf) & set(irfcl[c2]))[-6:]
            if wsp:
                e['kontr'] = [[m, imf[m], irfcl[c2][m]] for m in wsp]   # ten sam miesiąc z dwóch tabel (uncje) — kontrola dzienna
        kr[c2] = e
    banki = {'u': 't', 'order': sorted(kr, key=lambda c: -kr[c]['d'][-1][1]), 'kr': kr}
    rc, pr = {}, (prev.get('banki') or {}).get('rez_cn') if isinstance(prev.get('banki'), dict) else None   # v338: rezerwy Chin razem (SAFE) — dla tabeli rezerw
    for r in ((pr or {}).get('d') or []) if isinstance(pr, dict) else []:
        if isinstance(r, list) and len(r) == 4 and isinstance(r[0], str) and all(_isnum(x) for x in r[1:]):
            rc[r[0]] = r[1:]
    rc.update((ctx.get('rez') or {}).get('CN') or {})
    if rc:
        mm = sorted(rc)[-SU_BANKI_M_NOWE:]
        banki['rez_cn'] = {'u': 'mld USD', 'z': 'safe', 'asof': mm[-1], 'd': [[m] + list(rc[m]) for m in mm]}
    return {'pozycje': poz, 'fundusze': fund, 'banki': banki}, sumy


def _su_crack(H):
    """Marża rafinerii 3:2:1 (USD/bbl, wyliczona): (2 × benzyna NYH + 1 × olej napędowy NYH) × 42 ÷ 3 − WTI; brak składnika = null."""
    W, G, U = (H['d'].get(k) or {} for k in ('wti', 'gas_nyh', 'ulsd_nyh'))
    H['d']['crack321'] = {d: (round((2 * G[d] + U[d]) * 42 / 3 - w, 2) if _isnum(w) and _isnum(G.get(d)) and _isnum(U.get(d)) else None)
                          for d, w in W.items()}


def build_surowce(prev=None, prev_hist=None, keys=None, now=None, fetch=None, budzet_s=None, run_t0=None, fund=None):   # v298: fund — data/fundusze.json (IAU)
    """v295: data/surowce.json w wersji 2 i data/surowce-hist.json → (surowce, historia, zbiór źródeł pobranych w tym przebiegu).
    Każde źródło ma własną bramkę (_su_due) i budżet czasu; źródło bez klucza — pominięte z notatką; źródło z błędem — poprzednie dane z datą
    (część z ok False i krótkim błędem err). Bez wyjątku na zewnątrz poza błędem w samym budowniczym (main zostawia wtedy poprzednie pliki)."""
    now = now or _now_utc()
    now_iso = now.replace(microsecond=0).isoformat()
    keys = keys if isinstance(keys, dict) else {}
    prev = prev if isinstance(prev, dict) else {}
    v2 = prev.get('v') == SU_V
    st = json.loads(json.dumps(prev.get('st'))) if v2 and isinstance(prev.get('st'), dict) else {}
    H = _su_hist_load(prev_hist, prev)
    _su_hist3(H, prev)   # v298: historia etapu 3 z poprzedniego pliku, gdy brak surowce-hist.json
    P = {}
    for part in ('ceny', 'zapasy'):
        for cid, e in ((prev.get(part) or {}).items() if v2 else ()):
            if isinstance(e, dict) and isinstance(e.get('pre'), list):
                P[cid] = {d for d in e['pre'] if isinstance(d, str)}
    live = {cid: e['live'] for cid, e in ((prev.get('ceny') or {}).items() if v2 else ()) if isinstance(e, dict) and isinstance(e.get('live'), dict)}
    tdl = (st.get('td') or {}).get('live') if isinstance(st.get('td'), dict) else None   # notowanie zapisane, gdy seria dzienna złota była pusta
    if isinstance(tdl, dict) and isinstance(tdl.get('at'), str) and str(tdl['at']) > str((live.get('gold') or {}).get('at') or ''):
        live['gold'] = tdl
    kontr = json.loads(json.dumps(prev.get('kontr'))) if v2 and isinstance(prev.get('kontr'), dict) else {}
    ctx = {'now': now, 'now_iso': now_iso, 'keys': keys, 'H': H, 'P': P, 'live': live, 'st': st, 'kontr': kontr, 'prev': prev,
           'bledy': [], 'uwagi': [], 'markets': None, 'avg5_zr': None, 't0': time.monotonic(),
           'budzet': SU_BUDZET_S if budzet_s is None else budzet_s,
           'fetch': fetch or (lambda url, timeout, headers=None: get_bytes(url, headers, timeout=timeout))}
    late = run_t0 is not None and time.monotonic() - run_t0 > SU_LATE
    S = {'st': st, 'markets_asof': prev.get('asof')}
    proby, udane, zle = {p: 0 for p in SU_PARTS}, set(), {}
    S['udane'] = ctx['udane'] = udane   # v298: źródła udane w tym przebiegu — naśladowcy (SU_ZA) biorą odpowiedź lidera
    ctx.update(raw={}, poz={}, fund=fund)
    pominiete, miekkie = [], []   # v301: miekkie — błędy źródeł uzupełniających (SU_MIEKKIE), rozstrzygane po pętli
    for src, part in SU_ZR:
        z = st.setdefault(src, {})
        if not (_su_due(src, z, now, S) or _su_cfg_zmiana(src, z, now)):   # v344: albo kalendarz źródła, albo zmiana jego konfiguracji
            continue
        if SU_KLUCZ.get(src) and not keys.get(SU_KLUCZ[src]):
            pominiete.append(f'{src} (brak {SU_KLUCZ[src]})'); continue
        if late and src in SU_CIEZKIE:
            pominiete.append(f'{src} (długi przebieg)'); continue
        # v301: naśladowca (SU_ZA), którego lider udał się w tym przebiegu, bierze odpowiedź lidera bez zapytania — rezerwa jednego limitu
        # (najwyżej jedno zapytanie spoza tej odpowiedzi, np. plik roku poprzedniego przy krótkiej historii), nie SU_ZAPYTANIA × limit. Dawniej
        # cftcd rezerwował 2 × 60 s ze 150 s: po wolniejszym początku przebiegu był pomijany, a w następnym sam pobierał 2,4 MB (10 min później)
        nz = 1 if SU_ZA.get(src) in udane else SU_ZAPYTANIA.get(src, 1)
        if time.monotonic() - ctx['t0'] + nz * SU_LIMIT_S[src] > ctx['budzet']:
            pominiete.append(f'{src} (budżet czasu)'); continue
        nb = len(ctx['bledy'])
        z['try'] = now_iso
        try:
            asof = SU_POBIERZ[src](ctx)
        except Exception as e:
            msg = mask(f'{src}: {e}')[:160]
            z['err'] = msg
            if src in SU_MIEKKIE:   # v301: źródło uzupełniające — notatka albo błąd części rozstrzygane po pętli (wynik źródła głównego)
                miekkie.append((src, part, msg)); continue
            proby[part] += 1
            zle.setdefault(part, []).append(msg)
            continue
        proby[part] += 1
        z['at'] = now_iso; z['asof'] = asof; z.pop('err', None); udane.add(src)
        if _su_cfg(src):
            z['cfg'] = _su_cfg(src)   # v344: odcisk konfiguracji tylko po udanym pobraniu — nieudane ponowienie nie gasi wymuszenia
        if src == 'cftc':
            S['markets_asof'] = asof
        if len(ctx['bledy']) > nb:   # częściowy błąd źródła (np. jeden z kilku symboli) — dane pozostałych zapisane
            zle.setdefault(part, []).extend(mask(x)[:160] for x in ctx['bledy'][nb:])
    for src, part, msg in miekkie:   # v301: błąd SAFE — gdy MFW (imf_il) udał się w tym przebiegu albo część ma wcześniejsze dane: notatka (Chiny
        # zostają z danymi MFW albo poprzednimi z datą), nie błąd części; bez żadnych danych części — błąd jak dotąd
        if SU_MIEKKIE[src] in udane or _su_ma_dane(prev, part, v2):
            ctx['uwagi'].append(f'{msg} — notatka, nie błąd części {part} (dane z {SU_MIEKKIE[src]} albo wcześniejsze zostają; ponowienie ' + ('w oknie publikacji w piątek' if src == 'iceab' else 'po ≥ 6 h') + ')')
        else:
            proby[part] += 1
            zle.setdefault(part, []).append(msg)
    _su_crack(H)
    qlim = {}   # v300: ciąg cen bez potwierdzenia ucięty bezpiecznikiem → ceny[ropa].q_lim (kontrola)
    q = su_q(H['d'].get('brent') or {}, H['d'].get('wti') or {}, H['d'].get('brent_fut') or {},
             {k: (prev.get('ceny') or {}).get(k, {}).get('q') for k in ('brent', 'wti')} if v2 else None, qlim)
    pc = prev.get('ceny') if v2 and isinstance(prev.get('ceny'), dict) else {}
    ceny = {}
    for cid, g, u, z, x in SU_CENY:
        rows = sorted(H['d'].get(cid, {}).items())[-SU_D:]
        if not rows:
            continue
        e = {'g': g, 'u': u, 'f': 'D', 'd': [[d, v] for d, v in rows], 'z': z}
        if x:
            e['x'] = list(x)
        pe = pc.get(cid) if isinstance(pc.get(cid), dict) else {}
        pl = _su_last(pe.get('d') or []) if isinstance(pe.get('d'), list) else None
        nl = _su_last(e['d'])
        e['t'] = pe['t'] if (pl == nl and isinstance(pe.get('t'), str)) else now_iso
        pre = sorted(d for d in P.get(cid, ()) if d >= rows[0][0])
        if pre:
            e['pre'] = pre
        if q.get(cid):
            e['q'] = q[cid]
        if qlim.get(cid):
            e['q_lim'] = qlim[cid]
        if isinstance(live.get(cid), dict):
            e['live'] = live[cid]
        ceny[cid] = e
    pz = prev.get('zapasy') if v2 and isinstance(prev.get('zapasy'), dict) else {}
    zapasy = {}
    for cid, u in SU_ZAP:
        rows = sorted((d, v) for d, v in H['w'].get(cid, {}).items() if _isnum(v))[-SU_W:]
        if not rows:
            continue
        e = {'u': u, 'f': 'W', 'd': [[d, v] for d, v in rows], 'z': 'eia'}
        pe = pz.get(cid) if isinstance(pz.get(cid), dict) else {}
        e['t'] = pe['t'] if (_su_last(pe.get('d') or []) == _su_last(e['d']) and isinstance(pe.get('t'), str)) else now_iso
        pre = sorted(d for d in P.get(cid, ()) if d >= rows[0][0])
        if pre:
            e['pre'] = pre
        if cid in SU_AVG5:
            a5 = _su_avg5(H['w'][cid], [d for d, _ in rows])
            if a5:
                e['avg5'] = a5
        if cid == 'us_gas':
            a = ctx['avg5_zr'] or pe.get('avg5_zr')
            if isinstance(a, list) and len(a) == 2:
                e['avg5_zr'] = a
        zapasy[cid] = e
    s, ix, kk = {}, {}, {}
    for cid, _n, _uj, g, u in SU_WB:
        rows = sorted(H['m'].get(cid, {}).items())[-SU_M:]
        if rows:
            s[cid] = {'g': g, 'u': u, 'd': [[a, b] for a, b in rows], 'z': 'wb'}
    for cid, _ind, _tr, g, u, p in SU_IMF:
        rows = sorted(H['m'].get(cid, {}).items())[-(SU_K if p == 'k' else SU_M):]
        if not rows:
            continue
        if p == 's':
            e = {'g': g, 'u': u, 'd': [[a, b] for a, b in rows], 'z': 'imf'}
            stl = _su_staly(e['d'])
            if stl:
                e['x'] = ['niepewny']; e['staly'] = stl
            s[cid] = e
        elif p == 'ix':
            ix[cid] = {'u': u, 'd': [[a, b] for a, b in rows], 'z': 'imf'}
        else:
            kk[cid] = {'u': u, 'd': [[a, b] for a, b in rows], 'z': 'imf'}
    for cid, _n in SU_WBIX:
        rows = sorted(H['m'].get(cid, {}).items())[-SU_M:]
        if rows:
            ix[cid] = {'u': 'indeks (2010=100)', 'd': [[a, b] for a, b in rows], 'z': 'wb'}
    rows = sorted(H['m'].get('fao', {}).items())[-SU_M:]
    if rows:
        ix['fao'] = {'u': 'indeks (' + str((st.get('fao') or {}).get('baza') or '2014-2016=100') + ')', 'd': [[a, b] for a, b in rows], 'z': 'fao'}
    wbz = st.get('wb') or {}
    mies = {'asof': wbz.get('asof'), 'pub': wbz.get('pub'), 's': s, 'ix': ix, 'k': kk,
            'src': {k: {x: (st.get(k) or {}).get(x) for x in ('asof', 'pub', 'baza') if (st.get(k) or {}).get(x)} for k in ('wb', 'imf', 'fao')}}
    m = ctx['markets'] if isinstance(ctx['markets'], dict) else prev
    out = {'v': SU_V, 'at': None, 'src': m.get('src') or 'CFTC — Commitments of Traders: Disaggregated (futures only)',
           'url': m.get('url') or CFTC_HOME, 'data_url': m.get('data_url') or CFTCD_WEEK_URL, 'unit': m.get('unit') or 'kontrakty',
           'asof': m.get('asof'), 'order': m.get('order') or [g for g, _, _, _ in CFTCD_GROUPS],
           'markets': m.get('markets') if isinstance(m.get('markets'), dict) else {}}
    part_src = {p: [s_ for s_, pp in SU_ZR if pp == p] for p in SU_PARTS}
    pat = dict(prev.get('part_at') or {}) if v2 and isinstance(prev.get('part_at'), dict) else ({'markets': prev['at']} if prev.get('at') else {})
    perr = dict(prev.get('err') or {}) if v2 and isinstance(prev.get('err'), dict) else {}
    ok = {}
    for p in SU_PARTS:
        if any(x in udane for x in part_src[p]):
            pat[p] = now_iso
        if zle.get(p):
            ok[p] = False; perr[p] = '; '.join(zle[p])[:240]
        elif proby[p]:
            ok[p] = True; perr.pop(p, None)
        else:
            ok[p] = 'cached' if p in pat else False
            if p not in pat and p not in perr:
                perr[p] = 'brak danych (źródło jeszcze nie pobrane)'
    out.update({'part_at': {p: pat[p] for p in SU_PARTS if pat.get(p)}, 'ok': ok, 'next': {}, 'err': {p: perr[p] for p in SU_PARTS if perr.get(p)},
                'st': st, 'ceny': ceny, 'zapasy': zapasy, 'mies': mies})
    if kontr:
        out['kontr'] = kontr
    try:
        e3, su_fs = _su_etap3(ctx, prev)   # v298: części pozycje, fundusze, banki (+ sumy złota w funduszach do historii)
    except Exception as e:   # błąd składania etapu 3 nie zatrzymuje pozostałych części — poprzednie dane etapu 3 z ich datami
        META['errors'].append(mask(f'surowce etap 3: {e}')[:200])
        e3, su_fs = {p: prev[p] for p in ('pozycje', 'fundusze', 'banki') if v2 and isinstance(prev.get(p), dict)}, {}
    out.update(e3)
    pi = ((((prev.get('fundusze') or {}).get('f') or {}).get('IAU') or {}).get('asof')) if v2 and isinstance(prev.get('fundusze'), dict) else None
    if ((((e3.get('fundusze') or {}).get('f') or {}).get('IAU') or {}).get('asof')) not in (None, pi):   # IAU z pliku funduszy strony (bez źródła) — nowy dzień
        out['part_at']['fundusze'] = now_iso                                                            # = nowe dane części
    out['at'] = max(out['part_at'].values()) if out['part_at'] else (prev.get('at') or now_iso)
    out['next'] = {p: _su_next(p, out, now) for p in SU_PARTS}
    for x in ctx['uwagi']:
        META['notes'].append(mask('surowce: ' + x)[:200])
    for p in SU_PARTS:
        for x in zle.get(p, []):
            META['errors'].append(mask('surowce ' + x)[:200])
    if pominiete:
        META['notes'].append('surowce: pominięte w tym przebiegu — ' + ', '.join(pominiete))
    hist = {'v': 1, 'at': out['at'], 'src': 'CapitalFlowAI — historia działu SUROWCE (te same pobrania co data/surowce.json; kody źródeł jak tam)',
            'd': {k: [[d, v] for d, v in sorted(r.items())][-SU_H:] for k, r in sorted(H['d'].items()) if r},
            'w': {k: [[d, v] for d, v in sorted(r.items())][-SU_WH:] for k, r in sorted(H['w'].items()) if r},
            'm': {k: [[d, v] for d, v in sorted(r.items())][-SU_MH:] for k, r in sorted(H['m'].items()) if r},
            'f': {k: [[d, v] for d, v in sorted(r.items())][-SU_H:] for k, r in sorted(H['f'].items()) if r},    # v298: ilości w funduszach
            'fs': {k: r[-SU_H:] for k, r in sorted(su_fs.items()) if r},                                           # sumy złota (wyliczone)
            'b': {k: [[d, v] for d, v in sorted(r.items())][-SU_MH:] for k, r in sorted(H['b'].items()) if r}}   # złoto banków (uncje)
    return out, hist, udane


def energia_z_surowcow(su, prev=None):
    """v295: data/energia.json z TEGO SAMEGO pobrania co surowce.json — identyczne liczby: ropa WTI i Brent, gaz Henry Hub (dzień po dniu,
    bez braków) oraz zapasy ropy i rezerwa SPR w tys. baryłek (jak dotąd czyta panel USA). Seria, której nie ma w surowcach — poprzednia."""
    old = (prev or {}).get('s') if isinstance(prev, dict) and isinstance(prev.get('s'), dict) else {}
    C, Z = su.get('ceny') or {}, su.get('zapasy') or {}
    out = {'at': NOW, 'src': 'U.S. Energy Information Administration (EIA) — Open Data API v2, Daily Prices (T+1), Weekly Petroleum Status Report',
           'url': 'https://www.eia.gov/opendata/', 'z': 'surowce', 's': {}}
    for name, cid, sid, unit in SU_ENERGIA:
        d = [[a, b] for a, b in ((C.get(cid) or {}).get('d') or []) if _isnum(b)]
        if d:
            out['s'][name] = {'id': sid, 'freq': 'daily', 'unit': unit, 'd': d}
        elif isinstance(old.get(name), dict):
            out['s'][name] = old[name]
    for name, cid, sid in (('crude', 'us_crude', 'WCESTUS1'), ('spr', 'us_spr', 'WCSSTUS1')):
        d = [[a, int(round(b * 1000))] for a, b in ((Z.get(cid) or {}).get('d') or []) if _isnum(b)]
        if d:
            out['s'][name] = {'id': sid, 'freq': 'weekly', 'unit': 'MBBL', 'd': d}
        elif isinstance(old.get(name), dict):
            out['s'][name] = old[name]
    if not out['s']:
        raise RuntimeError('surowce bez cen i zapasów ropy')
    return out


# ===================== v320: SUROWCE — RAPORTY MIESIĘCZNE: podaż ropy OPEC+, bilans zbóż, cena uranu (data/surowce-raporty.json) =====================
# Dział SUROWCE, etap 4 (reszta) i etap 6 (zadanie SUROWCE46). Osobny plik i osobny budowniczy (surowce.json bez zmian); strona wczytuje go dopiero
# po rozwinięciu bloku „Podaż ropy: OPEC+ i wolne moce” albo „Światowe zapasy zbóż” (część C panelu #g-surowce). Trzy części, każda z part_at / ok /
# next / err jak w szlaki.json:
#   ropa  — wydobycie ropy z miesięcznego raportu urzędu energii USA (krótkoterminowa prognoza; API v2 z kluczem EIA_KEY — tym samym mechanizmem
#           kluczy co dział SUROWCE, wartość nigdy w pliku ani w komunikacie): OPEC+ razem (opec_plus — w definicji urzędu TYLKO kraje objęte
#           porozumieniem OPEC+, tabela 3d raportu, przypisy b i d), w nim kraje OPEC objęte porozumieniem (objeci) i pozostali uczestnicy (inni, m.in.
#           Rosja, Kazachstan, Meksyk); cały OPEC (opec — z krajami OPEC poza porozumieniem: w raportach 10.2024–10.2026 Iran, Libia i Wenezuela),
#           zdolność wydobywcza OPEC (moce) i Arabia Saudyjska (sa); wyliczone: wolne moce OPEC (wolne = zdolność − wydobycie OPEC) i kraje OPEC poza
#           porozumieniem (poza = cały OPEC − objęci). v320 po przeglądzie: wcześniej „pozostali w OPEC+” liczone jako OPEC+ − OPEC — błędnie (OPEC+
#           nie zawiera Iranu, Libii i Wenezueli, więc część zaniżona o ich wydobycie, a zdanie „OPEC+ …, w tym OPEC …” nieprawdziwe). Straż serii
#           (_sr_opec_straz): brak którejś z czterech serii wydobycia, OPEC+ ≠ objęci + pozostali (±SR_STEO_SUMA) albo OPEC < objęci = błąd części
#           (zły identyfikator serii albo zmiana definicji u źródła — dane zostają poprzednie); test wsteczny ws53/v320-surowce46/bt/bt_opecplus.py
#           (arkusze 5 wydań 10.2024–10.2026, 207 miesięcy): 0 niezgodnych, największa różnica 0,001. Skład „poza porozumieniem” sprawdzany co
#           wydanie: poza = Iran + Libia + Wenezuela w miesiącach szacunku (ilv: True/False/None — strona nazywa te kraje tylko przy True).
#           SR_STEO_HIST miesięcy przed miesiącem wydania i wszystkie miesiące prognozy (kraje — tylko szacunki; prognoz krajów urząd nie podaje).
#           API NIE oznacza granicy historia/prognoza — dzień wydania (wyd) i następnego wydania (nast) są ze strony raportu (bez klucza, ok. 67 KB);
#           pierwszy miesiąc prognozy (pr_od) = miesiąc wydania, wcześniejsze miesiące to szacunki urzędu. Straż wydania: wydobycie Arabii Saudyjskiej
#           urząd podaje tylko do ostatniego miesiąca przed wydaniem (prognozy krajów OPEC nie publikuje), więc musi ono sięgać co najmniej miesiąca
#           przed miesiącem wydania — inaczej API ma jeszcze poprzednie wydanie (strona bywa szybsza): dane zostają poprzednie (notatka do SR_ZALEGLE_H
#           h po wydaniu, potem błąd części). Strona raportu niedostępna — dzień wydania z oficjalnej reguły wydawcy (pierwszy wtorek po pierwszym
#           czwartku miesiąca; poniedziałek albo ten wtorek świętem federalnym — środa; Nowy Rok w czwartek — następny czwartek), przyjęty tylko przy
#           DOKŁADNIE zgodnej straży wydania (ostatni miesiąc Arabii Saudyjskiej = miesiąc przed miesiącem wydania). Reguła odtwarza wszystkie
#           24 terminy 2026–2027 ze strony harmonogramu (nagranie 10.10.2026);
#   zboza — bilans zbóż świata i USA (pszenica, kukurydza, ryż — bielony, soja: produkcja, zużycie, zapasy końcowe, zapasy w % zużycia)
#           z miesięcznego raportu ministerstwa rolnictwa USA (v332: plik XML raportu z oficjalnego archiwum ministerstwa, ok. 3,6 MB; zapas — plik CSV
#           raportu, ok. 1 MB; bez klucza): sezon prognozy (flaga Proj.) z bieżącego
#           raportu, TEN SAM sezon z poprzedniego raportu (p; w maju, gdy raport otwiera nowy sezon — brak) i poprzedni sezon (r0, szacunek).
#           Zużycie: świat — zużycie krajowe łącznie (handel między krajami się znosi), USA — krajowe + eksport (jak w bilansach urzędu); zapasy
#           w % zużycia = zapasy końcowe ÷ zużycie. Straże pliku: jeden numer i jedna data raportu, miesiąc raportu = miesiąc pliku, jednostka
#           „Million Metric Tons”, świat = USA + reszta świata (±SR_WASDE_TOL mln t; nagranie 09.2026: różnice ≤ 0,01 — zaokrąglenia; towar
#           niezgodny — pominięty z błędem). To zabezpieczenie ODCZYTU pliku (złe wiersze, przesunięte kolumny), nie niezależna kontrola zgodności
#           źródeł: „Total Foreign” w pliku to z definicji świat − USA. Kalendarz raportów 2026 (SR_WASDE_KAL, 12:00 czasu Nowego Jorku); miesiąc spoza kalendarza — od
#           SR_WASDE_DZIEN. dnia (raport zwykle 8.–12.). Plik CSV pojawia się zwykle dzień po raporcie: brak pliku (HTTP 404) do SR_WASDE_404_DNI
#           dni po terminie = notatka (dane poprzedniego raportu zostają), potem błąd części (zaległy raport albo zmieniony adres pliku);
#   uran  — średnia branżowa ceny uranu z końca miesiąca (spot i długoterminowa, USD za funt U3O8) ze strony producenta uranu (ok. 330 KB, bez
#           klucza), SR_CAMECO_M miesięcy — do porównania w kontroli dziennej z ceną wyliczoną z funduszu fizycznego (ceny.uran w surowce.json;
#           tylko informacja — inne definicje i chwile wyceny).
# Kody źródeł (z, st) — pełne nazwy wyłącznie na stronie „Źródła”: steo, wasde, cameco. Bramki (_sr_due): pierwsze pobranie co godzinę do skutku;
# po terminie publikacji, dopóki nowe dane nie przyszły — steo co 60 min, wasde co 2 h (po SR_ZALEGLE_H h od terminu — co 6 h), cameco w dniach
# 1–15 co 6 h, później raz na dobę; poza oknem raz na 7 dni (poprawki wstecz, stały dostęp do źródła); po odmowie dostępu (HTTP 403 — ochrona
# przed automatami — albo 429) ponowienie najwcześniej po 6 h, bez zmiany nagłówków (stan źródła: kod). Budżet czasu SR_BUDZET_S s (źródło startuje
# tylko, gdy zmieszczą się wszystkie jego zapytania z pełnymi limitami); w długim przebiegu (BACK_LATE) — bez pobrań (dane miesięczne: 10 min
# później nic nie zmienia). Źródło z błędem = poprzednia część z datą (ok False, krótki zamaskowany err); brak = null, nigdy 0.
# v332 (F1Z1): zboża z OFICJALNEGO ARCHIWUM biblioteki ministerstwa rolnictwa USA (plik XML raportu), CSV tylko jako zapas. Od ok. 09/10.10.2026
# serwer plików CSV odpowiada maszynom GitHuba HTTP 403 (część zboza pusta, err „wasde: HTTP Error 403”) — odmowy nie obchodzimy (żadnych innych
# nagłówków ani ścieżek). Archiwum (inny serwer) ma te same raporty: strona wydań (tabela: dzień wydania i odnośniki do plików) → najnowszy plik
# wasdeMMRR[v2].xml (ok. 3,6 MB; sonda z GitHuba 10.10.2026: strona 200, plik 200, 11 odnośników XML). Z jednego pliku wychodzi i raport bieżący, i
# prognoza poprzedniego miesiąca (kolumna „poprzedni miesiąc” w tabelach sezonu prognozy) — bez drugiego zapytania; zgodność z CSV: 144 liczby
# identyczne (nagranie 10.2026). Zapytania: strona wydań (najwyżej SR_WASDE_STRONA_MAX B) i plik (SR_WASDE_XML_MAX B); XML bez deklaracji DOCTYPE/ENTITY
# (encje nie są rozwijane); adres pliku tylko ze wzorca ścieżki na stałym hoście archiwum. Awaria archiwum (jakikolwiek błąd) = zapas CSV, ale
# nie wcześniej niż SR_WASDE_CSV_PAUZA_MIN min po odmowie (403/429) tamtego serwera (st.wasde.csv_od); st.wasde.via = skąd przyszedł raport.
SR_V = 1
SR_PARTS = ('ropa', 'zboza', 'uran')
SR_ZR = (('cameco', 'uran'), ('steo', 'ropa'), ('wasde', 'zboza'))    # kolejność: najlżejsze zapytania najpierw
SR_LIMIT_S = {'cameco': 30, 'steo': 30, 'wasde': 40}                 # s — limit jednego zapytania (10.10.2026: strona raportu 1,2 s, API 7–16 s z USA)
SR_ZAPYTANIA = {'steo': 2, 'wasde': 2}                               # strona + API; raport bieżący + poprzedni (trzecie zapytanie — z reszty budżetu)
SR_BUDZET_S = 120
