SR_CAMECO_ZAKRES = (5, 1000)   # USD/lb — cena spoza zakresu = brak (inna kolumna albo zła liczba)
SR_MIES_EN = ('jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec')


def _sr_dz(s):
    """'RRRR-MM-DD…' → data; inaczej None."""
    try:
        return datetime.date.fromisoformat(str(s)[:10]) if isinstance(s, str) and len(s) >= 10 else None
    except ValueError:
        return None


def _sr_mies(ym, k):
    """Miesiąc 'RRRR-MM' przesunięty o k miesięcy."""
    n = int(ym[:4]) * 12 + int(ym[5:7]) - 1 + k
    return f'{n // 12:04d}-{n % 12 + 1:02d}'


def _sr_dst(d):
    """Czas letni w USA (od 2007): od 2. niedzieli marca do 1. niedzieli listopada (dzień zmiany liczony już jako nowy czas)."""
    m = datetime.date(d.year, 3, 1)
    n = datetime.date(d.year, 11, 1)
    return m + datetime.timedelta(days=(6 - m.weekday()) % 7 + 7) <= d < n + datetime.timedelta(days=(6 - n.weekday()) % 7)


def _sr_et(d, h, mi=0):
    """Godzina h:mi czasu Nowego Jorku w dniu d → chwila UTC (reguła czasu letniego USA, bez bazy stref — tak samo w testach i w Actions)."""
    return datetime.datetime(d.year, d.month, d.day, h, mi, tzinfo=datetime.timezone.utc) + datetime.timedelta(hours=4 if _sr_dst(d) else 5)


def _sr_nty(y, m, wd, n):
    d = datetime.date(y, m, 1)
    return d + datetime.timedelta(days=(wd - d.weekday()) % 7 + 7 * (n - 1))


def _sr_swieta(y):
    """Święta federalne USA, które mogą wypaść w poniedziałek albo wtorek tuż przed wydaniem (6.–13. dnia miesiąca): Nowy Rok, Dzień
    Niepodległości, Dzień Pracy, Kolumba, Weteranów, Boże Narodzenie (obchodzone: sobota → piątek, niedziela → poniedziałek)."""
    obs = lambda d: d - datetime.timedelta(days=1) if d.weekday() == 5 else d + datetime.timedelta(days=1) if d.weekday() == 6 else d   # noqa: E731
    return {obs(datetime.date(y, 1, 1)), obs(datetime.date(y, 7, 4)), _sr_nty(y, 9, 0, 1), _sr_nty(y, 10, 0, 2), obs(datetime.date(y, 11, 11)),
            obs(datetime.date(y, 12, 25))}


def _sr_steo_wyd(y, m):
    """Dzień wydania raportu ropy w miesiącu (y, m) z oficjalnej reguły wydawcy: pierwszy wtorek po pierwszym czwartku; Nowy Rok w czwartek —
    pierwszy czwartek roboczy (13.01.2026); poniedziałek przed nim albo ten wtorek świętem federalnym — środa (09.09.2026, 13.10.2027)."""
    c = _sr_nty(y, m, 3, 1)
    if c == datetime.date(y, 1, 1):
        c += datetime.timedelta(days=7)
    t = c + datetime.timedelta(days=5)
    H = _sr_swieta(y)
    return t + datetime.timedelta(days=1) if (t - datetime.timedelta(days=1)) in H or t in H else t


def _sr_steo_ost(now):
    """Ostatnie wydanie z reguły, którego chwila (12:15 czasu Nowego Jorku) nie jest późniejsza niż now → (dzień, chwila UTC)."""
    y, m = now.year, now.month
    for _ in range(3):
        d = _sr_steo_wyd(y, m)
        t = _sr_et(d, 12, 15)
        if t <= now:
            return d, t
        y, m = (y - 1, 12) if m == 1 else (y, m - 1)
    return None, None


def _sr_wasde_exp(ym):
    """Spodziewany raport zbóż z miesiąca ym ('RRRR-MM') → (dzień, chwila UTC 12:00 czasu Nowego Jorku, czy z kalendarza, najpóźniejsza chwila
    terminu). Miesiąc spoza kalendarza — od SR_WASDE_DZIEN[0]. dnia (najwcześniejszy zwykły termin), najpóźniej SR_WASDE_DZIEN[1]. dnia (od niego
    liczy się zwłoka pliku, po której brak pliku jest błędem)."""
    k = next((d for d in SR_WASDE_KAL if d.startswith(ym)), None)
    y, m = int(ym[:4]), int(ym[5:7])
    d = datetime.date.fromisoformat(k) if k else datetime.date(y, m, SR_WASDE_DZIEN[0])
    t = _sr_et(d, 12, 0)
    return d, t, bool(k), (t if k else _sr_et(datetime.date(y, m, SR_WASDE_DZIEN[1]), 12, 0))


def _sr_wasde_cel(now):
    """Najnowszy raport zbóż, który według kalendarza już wyszedł (miesiąc 'RRRR-MM')."""
    ym = f'{now.year:04d}-{now.month:02d}'
    return ym if _sr_wasde_exp(ym)[1] <= now else _sr_mies(ym, -1)


def _sr_due(src, z, now):
    """Czy źródło trzeba pobrać w tym przebiegu: pierwsze pobranie (i po błędzie) — najwcześniej po 60 min; po terminie publikacji, dopóki nowe
    dane nie przyszły — steo co 60 min, wasde co 2 h (po SR_ZALEGLE_H h — co 6 h), cameco w dniach 1–15 co 6 h, potem raz na dobę; poza oknem
    raz na 7 dni; po odmowie dostępu (kod 403/429 w stanie) — najwcześniej po 6 h. z — stan źródła ({at, try, asof — data danych w pliku;
    steo: nast — następne wydanie ze strony raportu; kod — 403/429 ostatniej nieudanej próby})."""
    at, tr = _su_min(now, z.get('at')), _su_min(now, z.get('try'))
    if z.get('kod') in (403, 429) and tr < 360:   # ochrona przed automatami albo limit: rzadziej, bez obchodzenia (nagłówki bez zmian)
        return False
    if at == float('inf'):
        return tr >= 60
    asof = str(z.get('asof') or '')
    if src == 'steo':   # termin: zapowiedź ze strony raportu (nowsza niż wydanie w pliku), inaczej reguła wydawcy
        n = _sr_dz(z.get('nast'))
        if n and n.isoformat() > asof:
            d, t = n, _sr_et(n, 12, 15)
            if t > now:
                d = None
        else:
            d, t = _sr_steo_ost(now)
        if d and asof < d.isoformat():
            return tr >= (60 if (now - t).total_seconds() <= SR_ZALEGLE_H * 3600 else 360)
    elif src == 'wasde':
        cel = _sr_wasde_cel(now)
        if asof < cel:
            t = _sr_wasde_exp(cel)[1]
            return tr >= (120 if (now - t).total_seconds() <= SR_ZALEGLE_H * 3600 else 360)
    elif src == 'cameco':   # koniec poprzedniego miesiąca — cena jest zwykle w pierwszych dniach następnego
        kon = (now.date().replace(day=1) - datetime.timedelta(days=1)).isoformat()
        if asof < kon:
            return tr >= (360 if now.day <= 15 else 24 * 60)
    return at >= 7 * 24 * 60 and tr >= 60


def _sr_next(part, out, now):
    """Najbliższa spodziewana publikacja części (ISO, UTC); termin w przeszłości = publikacja zaległa (święto, przerwa w pracy urzędu)."""
    P = out.get(part) if isinstance(out.get(part), dict) else {}
    if part == 'ropa':
        wyd = _sr_dz(P.get('wyd'))
        n = _sr_dz(P.get('nast'))
        if not (n and wyd and n > wyd):
            base = wyd or now.date()
            y, m, n = base.year, base.month, None
            for _ in range(3):
                d = _sr_steo_wyd(y, m)
                if d > base:
                    n = d; break
                y, m = (y + 1, 1) if m == 12 else (y, m + 1)
        return _sr_et(n, 12, 0).isoformat() if n else None
    if part == 'zboza':
        ym = P.get('mies') if isinstance(P.get('mies'), str) and re.match(r'^\d{4}-\d{2}$', P.get('mies')) else None
        nx = _sr_mies(ym, 1) if ym else _sr_wasde_cel(now)
        return _sr_wasde_exp(nx)[1].isoformat()
    if part == 'uran':   # koniec następnego miesiąca po ostatnim w pliku, publikacja w pierwszych dniach — do 7. dnia (model testu wstecznego)
        a = _sr_dz(P.get('asof')) or (now.date().replace(day=1) - datetime.timedelta(days=1))
        y, m = (a.year + 1, 1) if a.month == 12 else (a.year, a.month + 1)
        y, m = (y + 1, 1) if m == 12 else (y, m + 1)
        return datetime.datetime(y, m, 7, 12, 0, tzinfo=datetime.timezone.utc).isoformat()
    return None


# ---- parsery (nagrania w testach SurowceRaportyV320) ----
def _sr_data_en(mies, dzien, rok):
    """'October', '6', '2026' (także skrót „Oct.”, „Sept.”) → 'RRRR-MM-DD'; inaczej None."""
    k = str(mies)[:3].lower()
    if k not in SR_MIES_EN:
        return None
    try:
        return datetime.date(int(rok), SR_MIES_EN.index(k) + 1, int(dzien)).isoformat()
    except ValueError:
        return None


def parse_steo_strona(text, today=None):
    """Strona raportu ropy → (dzień wydania 'RRRR-MM-DD', dzień następnego wydania albo None). Wiersz „Release Date: October 6, 2026 |
    Forecast Completed: … | Next Release Date: November 10, 2026” (po usunięciu znaczników). Dzień wydania z przyszłości albo starszy niż
    60 dni = błąd (inna strona albo strona nieaktualizowana); następne wydanie — po dniu wydania i najwyżej 70 dni później, inaczej None."""
    t = re.sub(r'\s+', ' ', re.sub(r'<[^>]+>', ' ', text).replace('&nbsp;', ' '))
    m = re.search(r'(?<!Next )Release Date:\s*([A-Za-z]{3,9})\.?\s+(\d{1,2}),\s*(\d{4})', t)
    n = re.search(r'Next Release Date:\s*([A-Za-z]{3,9})\.?\s+(\d{1,2}),\s*(\d{4})', t)
    wyd = _sr_data_en(*m.groups()) if m else None
    if not wyd:
        raise RuntimeError('brak dnia wydania na stronie raportu')
    today = today or _now_utc().date()
    d = datetime.date.fromisoformat(wyd)
    if not (today - datetime.timedelta(days=60) <= d <= today):
        raise RuntimeError(f'dzień wydania {wyd} poza oknem 60 dni')
    nast = _sr_data_en(*n.groups()) if n else None
    if nast and not (d < datetime.date.fromisoformat(nast) <= d + datetime.timedelta(days=70)):
        nast = None
    return wyd, nast


def sr_steo_url(key, start):
    """Adres API v2 (trasa steo): serie miesięczne SR_STEO_SER od miesiąca start, rosnąco, do 5000 wierszy."""
    q = ([('api_key', key), ('frequency', 'monthly'), ('data[0]', 'value')] + [('facets[seriesId][]', s) for s in SR_STEO_SER]
         + [('start', start), ('sort[0][column]', 'period'), ('sort[0][direction]', 'asc'), ('offset', '0'), ('length', '5000')])
    return f'{EIA_API}steo/data/?' + urllib.parse.urlencode(q)


def parse_steo(j):
    """API v2 (trasa steo) → ({id: {'RRRR-MM': mln b/d}}, [serie z inną jednostką]). Wiersz innej serii pominięty; nie-liczba albo poza (0, 200)
    = brak (nigdy 0); seria z inną jednostką niż „million barrels per day” — cała pominięta (zła liczba gorsza niż brak); pole error = błąd."""
    if not isinstance(j, dict) or j.get('error'):
        raise RuntimeError(str((j or {}).get('error') if isinstance(j, dict) else 'nieznany kształt odpowiedzi')[:140])
    rows = (j.get('response') or {}).get('data') if isinstance(j.get('response'), dict) else None
    if not isinstance(rows, list):
        raise RuntimeError('nieznany kształt odpowiedzi')
    out, bad = {}, set()
    for r in rows:
        if not isinstance(r, dict) or r.get('seriesId') not in SR_STEO_SER:
            continue
        sid = r['seriesId']
        if re.sub(r'\s+', ' ', str(r.get('unit') or '')).strip().lower() != SR_STEO_JEDN:
            bad.add(sid); continue
        ym, v = str(r.get('period') or ''), _num(r.get('value'))
        if re.match(r'^\d{4}-\d{2}$', ym) and _isnum(v) and 0 < v < 200:
            out.setdefault(SR_STEO_SER[sid], {})[ym] = round(v, 3)
    for sid in bad:
        out.pop(SR_STEO_SER[sid], None)
    return out, sorted(bad)


def _sr_roznica(A, B, od):
    """Różnica A − B w tych samych miesiącach od miesiąca od → ([[miesiąc, liczba|None]], [miesiące zbyt ujemne]); ujemna do SR_STEO_TOL = 0
    (zaokrąglenie), bardziej ujemna = brak (nigdy liczba ujemna)."""
    w, zle = [], []
    for m in sorted(set(A) & set(B)):
        if m < od:
            continue
        x = round(A[m] - B[m], 3)
        if x < -SR_STEO_TOL:
            zle.append(m); w.append([m, None])
        else:
            w.append([m, max(x, 0.0)])
    return w, zle


def _sr_ilv(S, pr):
    """Skład krajów OPEC poza porozumieniem w miesiącach szacunku (przed miesiącem wydania pr): True — w każdym miesiącu z liczbami cały OPEC −
    objęci porozumieniem = Iran + Libia + Wenezuela (±SR_STEO_SUMA); False — w którymś nie (zmiana składu u źródła — strona nie nazywa wtedy
    krajów); None — żadnego miesiąca z kompletem liczb."""
    O, B = S.get('opec') or {}, S.get('objeci') or {}
    K = [S.get(k) or {} for k in ('ir', 'ly', 've')]
    ms = [m for m in sorted(set(O) & set(B)) if m < pr and all(m in x for x in K)]
    if not ms:
        return None
    return all(abs(O[m] - B[m] - sum(x[m] for x in K)) <= SR_STEO_SUMA for m in ms)


def _sr_opec_straz(S):
    """Straż serii wydobycia przed przyjęciem danych → lista opisów (pusta = w porządku): brak serii wymaganej (SR_STEO_WYM), miesiące z OPEC+ ≠
    objęci + pozostali (±SR_STEO_SUMA) i z OPEC < objęci (−SR_STEO_SUMA) — zły identyfikator serii albo zmiana definicji u źródła."""
    ids = {v: k for k, v in SR_STEO_SER.items()}
    brak = [ids[c] for c in SR_STEO_WYM if not S.get(c)]
    if brak:
        return ['brak serii ' + ', '.join(brak) + ' — sprawdzić identyfikatory serii']
    P, B, I, O = (S[c] for c in ('opec_plus', 'objeci', 'inni', 'opec'))
    zle = []
    suma = [m for m in sorted(set(P) & set(B) & set(I)) if abs(P[m] - B[m] - I[m]) > SR_STEO_SUMA]
    if suma:
        zle.append('OPEC+ ≠ objęci porozumieniem + pozostali uczestnicy (' + ', '.join(suma[:3]) + ')')
    mn = [m for m in sorted(set(O) & set(B)) if O[m] < B[m] - SR_STEO_SUMA]
    if mn:
        zle.append('OPEC < kraje OPEC objęte porozumieniem (' + ', '.join(mn[:3]) + ')')
    return zle


def sr_ropa(S, wyd, nast, uw=None):
    """Część ropa z serii parse_steo: SR_STEO_HIST miesięcy przed miesiącem wydania i cała prognoza (serie SR_STEO_PLIK); wyliczone w tym samym
    miesiącu: wolne moce = zdolność − wydobycie OPEC, poza = cały OPEC − kraje OPEC objęte porozumieniem (ujemne do SR_STEO_TOL = 0 —
    zaokrąglenie, bardziej ujemne = brak z notatką w uw); ilv — skład krajów poza porozumieniem (_sr_ilv)."""
    pr = wyd[:7]
    od = _sr_mies(pr, -SR_STEO_HIST)
    s = {}
    for cid in SR_STEO_PLIK:
        rows = sorted((m, v) for m, v in (S.get(cid) or {}).items() if m >= od)
        if rows:
            s[cid] = [[m, v] for m, v in rows]
    for cid, a, b, opis in (('wolne', 'moce', 'opec', 'zdolność wydobywcza OPEC mniejsza niż wydobycie ({}) — wolne moce: brak'),
                            ('poza', 'opec', 'objeci', 'wydobycie OPEC mniejsze niż krajów OPEC objętych porozumieniem ({}) — kraje OPEC poza porozumieniem: brak')):
        w, zle = _sr_roznica(S.get(a) or {}, S.get(b) or {}, od)
        if zle and uw is not None:
            uw.append('steo: ' + opis.format(', '.join(zle[:4])))
        if w:
            s[cid] = w
    ilv = _sr_ilv(S, pr)
    if ilv is False and uw is not None:
        uw.append('steo: kraje OPEC poza porozumieniem ≠ Iran + Libia + Wenezuela (zmiana składu u źródła?) — strona bez nazw tych krajów; sprawdzić opis')
    hist = [m for m, _ in s.get('opec') or [] if m < pr]
    return {'wyd': wyd, 'nast': nast, 'pr_od': pr, 'asof': max(hist) if hist else None, 'u': 'mln b/d', 'z': 'steo', 'x': ['sz'], 'ilv': ilv, 's': s}


def _sr_wasde_straz(k):
    """Straż odczytu raportu zbóż: świat = USA + reszta świata (±SR_WASDE_TOL) w produkcji i zapasach każdego sezonu; towar niezgodny usuwany z k
    (opis na liście wyniku). To zabezpieczenie ODCZYTU (złe wiersze, przesunięte kolumny), nie niezależna kontrola zgodności źródeł."""
    zle = []
    for cid in list(k):
        for my in sorted({y for R in k[cid].values() for y in R}):
            W, U, F = (k[cid].get(x, {}).get(my, {}) for x in ('swiat', 'usa', 'zagr'))
            for a in ('prod', 'zapasy'):
                if all(_isnum(x.get(a)) for x in (W, U, F)) and abs(W[a] - U[a] - F[a]) > SR_WASDE_TOL:
                    zle.append(f'{cid} {my} {a}: świat {W[a]} ≠ USA {U[a]} + reszta {F[a]}')
        if any(z.startswith(cid + ' ') for z in zle):
            del k[cid]
    return zle


def parse_wasde(text):
    """Plik CSV raportu zbóż → {'nr', 'wyd' (dzień raportu), 'mies' (miesiąc raportu), 'lata': {sezon: flaga}, 'k': {towar: {region: {sezon:
    {prod, kraj, eksp, zapasy}}}}} dla pszenicy, kukurydzy, ryżu i soi (tabele SR_WASDE_T; regiony świat, USA, reszta świata), w mln t. Kolumny po
    nazwie; spacje w nazwach ujednolicone (ryż: „Total  Domestic”); wiersz z inną jednostką niż „Million Metric Tons” pominięty; różne numery
    albo daty raportu w pliku = błąd; towar, w którym świat ≠ USA + reszta świata (±SR_WASDE_TOL) — pominięty, opis w polu 'zle'."""
    rows = list(csv.DictReader(io.StringIO(text.lstrip('\ufeff'))))
    need = ('WasdeNumber', 'ReportDate', 'ReportTitle', 'Attribute', 'Region', 'MarketYear', 'ProjEstFlag', 'Value', 'Unit', 'ReleaseDate')
    if not rows or any(c not in rows[0] for c in need):
        raise RuntimeError('nieznany nagłówek pliku (to nie plik raportu?)')
    sp = lambda x: re.sub(r'\s+', ' ', str(x or '')).strip()   # noqa: E731
    nr, wyd, rd = {sp(r['WasdeNumber']) for r in rows}, {sp(r['ReleaseDate'])[:10] for r in rows}, {sp(r['ReportDate']) for r in rows}
    if len(nr) != 1 or len(wyd) != 1 or len(rd) != 1:
        raise RuntimeError('różne numery albo daty raportu w jednym pliku')
    nr, wyd, rd = nr.pop(), wyd.pop(), rd.pop()
    m = re.match(r'^([A-Za-z]+)\s+(\d{4})$', rd)
    mies = (_sr_data_en(m.group(1), 1, m.group(2)) or '')[:7] if m else ''
    if not (nr.isdigit() and _sr_dz(wyd) and mies):
        raise RuntimeError(f'zły numer albo data raportu ({nr}, {wyd}, {rd})')
    k, lata = {}, {}
    for r in rows:
        t = sp(r['ReportTitle'])
        cid = next((c for c, n in SR_WASDE_T if t == n or t.startswith(n + ' ')), None)
        reg, atr = SR_WASDE_REG.get(sp(r['Region'])), SR_WASDE_ATR.get(sp(r['Attribute']))
        if not (cid and reg and atr) or sp(r['Unit']) != 'Million Metric Tons':
            continue
        my, v = sp(r['MarketYear']), _num(r['Value'])
        if not re.match(r'^\d{4}/\d{2}$', my) or not _isnum(v) or v < 0:
            continue
        k.setdefault(cid, {}).setdefault(reg, {}).setdefault(my, {})[atr] = round(v, 2)
        lata.setdefault(my, set()).add(sp(r['ProjEstFlag']).strip('()'))
    zle = _sr_wasde_straz(k)   # v332: ta sama straż dla pliku CSV i XML
    if not k:
        raise RuntimeError('brak tabel zbóż świata' + (' (' + '; '.join(zle[:2]) + ')' if zle else ''))
    return {'nr': int(nr), 'wyd': wyd, 'mies': mies, 'lata': {y: sorted(f) for y, f in sorted(lata.items())}, 'k': k, 'zle': zle}


def _sr_zb_wpis(reg, v):
    """Wartości regionu i sezonu ({prod, kraj, eksp, zapasy}) → wpis strony {prod, uzycie, zapasy, su (%), [eksp — USA]}; brak składnika = None."""
    if not isinstance(v, dict):
        return None
    uz = v.get('kraj') if reg == 'swiat' else (round(v['kraj'] + v['eksp'], 2) if _isnum(v.get('kraj')) and _isnum(v.get('eksp')) else None)
    e = {'prod': v.get('prod'), 'uzycie': uz, 'zapasy': v.get('zapasy'),
         'su': round(v['zapasy'] / uz * 100, 2) if _isnum(v.get('zapasy')) and _isnum(uz) and uz > 0 else None}
    if reg == 'usa':
        e['eksp'] = v.get('eksp')
    return e if any(_isnum(x) for x in e.values()) else None


def _sr_rok(lata, flaga):
    return max((y for y, f in (lata or {}).items() if flaga in f), default=None)


def sr_zboza(cur, pop=None, stary=None):
    """Część zboza: raport bieżący cur (parse_wasde), poprzedni raport pop (parse_wasde) albo — gdy go nie pobierano — poprzednia część
    stary (jej wpisy sezonu prognozy, gdy to raport o numerze o 1 niższym, albo jej wartości p, gdy to ten sam raport sprawdzony ponownie)."""
    rok, rok0 = _sr_rok(cur['lata'], 'Proj.'), _sr_rok(cur['lata'], 'Est.')
    if not rok:
        raise RuntimeError('brak sezonu prognozy (flaga Proj.) w pliku')
    st = stary if isinstance(stary, dict) and isinstance(stary.get('k'), dict) else None
    snr = st.get('nr') if st else None
    k = {}
    for cid, _t in SR_WASDE_T:
        C = cur['k'].get(cid)
        if not C:
            continue
        for reg in ('swiat', 'usa'):
            e = _sr_zb_wpis(reg, (C.get(reg) or {}).get(rok))
            if not e:
                continue
            p = None
            if pop:
                p = _sr_zb_wpis(reg, ((pop['k'].get(cid) or {}).get(reg) or {}).get(rok))
            elif st and snr == cur['nr'] - 1 and st.get('rok') == rok:
                q = ((st['k'].get(cid) or {}).get(reg) or {})
                p = {x: q.get(x) for x in ('prod', 'uzycie', 'zapasy', 'su', 'eksp') if x in q} or None
            elif st and snr == cur['nr'] and st.get('rok') == rok:
                q = (((st['k'].get(cid) or {}).get(reg) or {}).get('p'))
                p = dict(q) if isinstance(q, dict) else None
            e['p'] = p
            e['r0'] = _sr_zb_wpis(reg, (C.get(reg) or {}).get(rok0)) if rok0 else None
            k.setdefault(cid, {})[reg] = e
    if not k:
        raise RuntimeError(f'brak wpisów sezonu {rok}')
    if pop:
        pp = {'nr': pop['nr'], 'wyd': pop['wyd'], 'mies': pop['mies']}
    elif st and snr == cur['nr'] - 1:
        pp = {'nr': snr, 'wyd': st.get('wyd'), 'mies': st.get('mies')}
    elif st and snr == cur['nr'] and isinstance(st.get('poprz'), dict):
        pp = dict(st['poprz'])
    else:
        pp = None
    return {'nr': cur['nr'], 'wyd': cur['wyd'], 'mies': cur['mies'], 'rok': rok, 'rok0': rok0, 'u': 'mln t', 'z': 'wasde', 'poprz': pp, 'k': k}


def parse_cameco(text, today=None):
    """Strona ceny uranu → [(dzień 'RRRR-MM-DD', spot, długoterminowa)] rosnąco, USD za funt U3O8 (jeden wiersz na miesiąc — późniejsza data).
    Tabela z kolumnami po klasach komórek (monthly-date, spot-price, long-term-price) i nagłówkiem „Uranium Spot Price”; data RRRR/MM/DD (od 06.2017
    koniec miesiąca, wcześniej pierwszy dzień); cena spoza SR_CAMECO_ZAKRES = brak; najnowszy dzień z przyszłości albo starszy niż 100 dni = błąd."""
    tab = next((t for t in re.findall(r'<table.*?</table>', text, re.S) if 'field-monthly-date' in t and 'Uranium Spot Price' in t), None)
    if not tab:
        raise RuntimeError('brak tabeli cen miesięcznych')
    cl = lambda x: re.sub(r'\s+', ' ', _html.unescape(re.sub(r'<[^>]+>', ' ', x))).strip()   # noqa: E731
    lo, hi = SR_CAMECO_ZAKRES
    cena = lambda x: round(x, 2) if _isnum(x) and lo <= x <= hi else None   # noqa: E731
    M = {}
    for r in re.findall(r'<tr[^>]*>(.*?)</tr>', tab, re.S):
        c = {k: cl(v) for k, v in re.findall(r'<td[^>]*class="[^"]*views-field-field-([\w-]+)[^"]*"[^>]*>(.*?)</td>', r, re.S)}
        m = re.match(r'^(\d{4})/(\d{2})/(\d{2})$', c.get('monthly-date', ''))
        if not m:
            continue
        try:
            d = datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3))).isoformat()
        except ValueError:
            continue
        sp, lt = cena(_num(c.get('spot-price'))), cena(_num(c.get('long-term-price')))
        if (sp is not None or lt is not None) and (d[:7] not in M or d > M[d[:7]][0]):
            M[d[:7]] = (d, sp, lt)
    if not M:
        raise RuntimeError('brak wierszy z ceną')
    rows = sorted(M.values())
    today = today or _now_utc().date()
    last = datetime.date.fromisoformat(rows[-1][0])
    if not (today - datetime.timedelta(days=100) <= last <= today + datetime.timedelta(days=1)):
        raise RuntimeError(f'najnowszy miesiąc {rows[-1][0]} poza oknem 100 dni')
    return rows


# ---- pobrania ----
def get_bytes_maks(url, headers=None, timeout=60, maks=None):
    """v332: jak get_bytes, ale odpowiedź dłuższa niż maks bajtów = błąd (czytanie przerwane po maks + 1 B — bez pobierania reszty)."""
    _zuz_licz(url, headers)
    with _otworz(url, headers, timeout) as r:
        b = r.read(maks + 1) if maks else r.read()
    if maks and len(b) > maks:
        raise RuntimeError(f'odpowiedź dłuższa niż {maks} B (limit)')
    return b


def _sr_fetch(url, timeout, headers=None, maks=None):
    """Zapytanie budowniczego raportów (domyślne): z limitem rozmiaru odpowiedzi, gdy maks podany (v332)."""
    return get_bytes_maks(url, headers, timeout, maks) if maks else get_bytes(url, headers, timeout=timeout)


def _sr_get(ctx, src, url, maks=None):
    """Jedno zapytanie z limitem źródła, nie dłuższym niż reszta budżetu budowniczego (reszta < 5 s = błąd źródła; ponowienie później). maks —
    najwyżej tyle bajtów odpowiedzi (v332; dłuższa = błąd)."""
    lim = SR_LIMIT_S[src]
    if ctx.get('t0') is not None and ctx.get('budzet') is not None:
        left = ctx['budzet'] - (time.monotonic() - ctx['t0'])
        if left < 5:
            raise RuntimeError('budżet czasu budowniczego wyczerpany')
        lim = min(lim, round(left, 1))
    if maks is None:
        return ctx['fetch'](url, lim)
    b = ctx['fetch'](url, lim, maks=maks)
    if len(b) > maks:
        raise RuntimeError(f'odpowiedź dłuższa niż {maks} B (limit)')
    return b


def _sr_cameco(ctx):
    rows = parse_cameco(_sr_get(ctx, 'cameco', SR_CAMECO_URL).decode('utf-8', 'replace'), ctx['now'].date())[-SR_CAMECO_M:]
    ctx['parts']['uran'] = {'asof': rows[-1][0], 'u': 'USD/lb', 'z': 'cameco', 'd': [[d, s] for d, s, _ in rows],
                            'lt': [[d, x] for d, _, x in rows]}
    return rows[-1][0]


def _sr_steo(ctx):
    """Wydanie ze strony raportu (zapasowo — z reguły wydawcy); to samo wydanie co w pliku = bez zapytania do API (część potwierdzona, nast
    uaktualnione; część bez podziału OPEC+ — pobierana ponownie); nowe — API z kluczem, straż serii (_sr_opec_straz) i straż wydania (ostatni
    miesiąc Arabii Saudyjskiej)."""
    now, z = ctx['now'], ctx['st'].setdefault('steo', {})
    P = ctx['pp'].get('ropa')
    P = P if isinstance(P, dict) and isinstance(P.get('s'), dict) and isinstance(P.get('wyd'), str) else None
    try:
        wyd, nast = parse_steo_strona(_sr_get(ctx, 'steo', SR_STEO_STRONA).decode('utf-8', 'replace'), now.date())
        regula = False
    except Exception as e:
        d, _t = _sr_steo_ost(now)
        if d is None:
            raise
        wyd, nast, regula = d.isoformat(), None, True
        ctx['uwagi'].append(f'steo: strona raportu — {e}; dzień wydania z reguły wydawcy ({wyd})')
    pelna = P and all(isinstance(P['s'].get(c), list) for c in SR_STEO_WYM)   # część bez podziału OPEC+ (sprzed poprawki) — pobrać ponownie
    if pelna and (P['wyd'] == wyd or (regula and P['wyd'][:7] == wyd[:7])):   # to samo wydanie (reguła nie zna dnia dokładniej niż strona)
        if nast:
            z['nast'] = nast
        ctx['parts']['ropa'] = dict(P, nast=nast or P.get('nast'))
        return P['wyd']
    if P and wyd < P['wyd']:
        raise RuntimeError(f'wydanie {wyd} starsze niż w pliku ({P["wyd"]})')
    pr = wyd[:7]
    S, bad = parse_steo(_su_json(_sr_get(ctx, 'steo', sr_steo_url(ctx['keys'].get('EIA_KEY'), _sr_mies(pr, -(SR_STEO_HIST + 2))))))
    if bad:
        ctx['uwagi'].append('steo: inna jednostka serii ' + ', '.join(bad) + ' — pominięte')
    zs = _sr_opec_straz(S)   # v320 po przeglądzie: podział OPEC+ wymagany i spójny (zły identyfikator serii = błąd, nie zła liczba na stronie)
    if zs:
        raise RuntimeError('serie wydobycia: ' + '; '.join(zs))
    sa = max(S['sa']) if S.get('sa') else ''
    if sa < _sr_mies(pr, -1) or (regula and sa != _sr_mies(pr, -1)):
        msg = f'API ma jeszcze poprzednie wydanie (Arabia Saudyjska do {sa or "—"}, wydanie z {wyd})'
        if P and not regula and (now - _sr_et(datetime.date.fromisoformat(wyd), 12, 0)).total_seconds() <= SR_ZALEGLE_H * 3600:
            ctx['uwagi'].append('steo: ' + msg + ' — dane poprzedniego wydania zostają, ponowienie za godzinę')
            return P['wyd']
        raise RuntimeError(msg)
    ctx['parts']['ropa'] = sr_ropa(S, wyd, nast, ctx['uwagi'])
    if nast:   # zapowiedź następnego wydania — tylko razem z przyjętymi danymi (przy API z poprzednim wydaniem bramka czeka dalej co godzinę)
        z['nast'] = nast
    return wyd


def _sr_wasde_csv(ctx):
    """ZAPAS (v332; do v331 jedyne źródło): plik CSV raportu. Raport z ostatniego terminu kalendarza; brak jego pliku (404, zwykle dzień po raporcie)
    — poprzedni miesiąc, gdy pliku jeszcze nie ma (start), inaczej dane w pliku zostają (notatka; po SR_WASDE_404_DNI dniach — błąd). Poprzedni
    raport: z pliku strony (numer o 1 niższy albo ten sam raport z jego p) albo pobrany (start, przerwa w pobraniach)."""
    now = ctx['now']
    P = ctx['pp'].get('zboza')
    P = P if isinstance(P, dict) and isinstance(P.get('k'), dict) and isinstance(P.get('mies'), str) and isinstance(P.get('nr'), int) else None
    cel = _sr_wasde_cel(now)
    cur, url = None, lambda ym: SR_WASDE_URL.format(ym)   # noqa: E731
    for ym in (cel, _sr_mies(cel, -1)):
        if ym != cel and P and P['mies'] >= ym:
            break
        try:
            cur = parse_wasde(_sr_get(ctx, 'wasde', url(ym)).decode('utf-8', 'replace'))
        except urllib.error.HTTPError as e:
            if e.code != 404:
                raise
            t = _sr_wasde_exp(ym)[3]
            if (now - t).total_seconds() > SR_WASDE_404_DNI * 86400:
                raise RuntimeError(f'raport {ym}: brak pliku (HTTP 404) ponad {SR_WASDE_404_DNI} dni po terminie — zaległy raport albo zmieniony adres pliku') from None
            ctx['uwagi'].append(f'wasde: raport {ym} — pliku jeszcze nie ma (HTTP 404; zwykle dzień po raporcie)')
            continue
        if cur['mies'] != ym:
            raise RuntimeError(f'plik {ym} zawiera raport z {cur["mies"]}')
        break
    if cur is None:
        if P:
            return P['mies']
        raise RuntimeError('brak pliku raportu (HTTP 404)')
    if cur['zle']:
        ctx['bledy'].append('wasde: świat ≠ USA + reszta świata — ' + '; '.join(cur['zle'][:2]))
    pop = None
    rok = _sr_rok(cur['lata'], 'Proj.')
    ma_p = P and P['nr'] == cur['nr'] and P.get('rok') == rok and isinstance(P.get('poprz'), dict)   # ten sam raport, poprzedni już porównany
    if not (P and P['nr'] == cur['nr'] - 1) and not ma_p:   # (maj: poprzedni raport nie ma nowego sezonu — p brak, poprz zostaje: bez ponawiania)
        ym = _sr_mies(cur['mies'], -1)
        try:
            pop = parse_wasde(_sr_get(ctx, 'wasde', url(ym)).decode('utf-8', 'replace'))
            if pop['mies'] != ym or pop['nr'] >= cur['nr']:
                raise RuntimeError(f'plik {ym}: raport {pop["mies"]} nr {pop["nr"]}')
        except Exception as e:
            pop = None
            ctx['uwagi'].append(f'wasde: poprzedni raport ({ym}) — {e}; bez porównania z poprzednim raportem (ponowienie przy następnym sprawdzeniu)')
    ctx['parts']['zboza'] = sr_zboza(cur, pop, P)
    return cur['mies']


import xml.etree.ElementTree as _SrXml   # v332: biblioteka standardowa (parser expat nie pobiera encji zewnętrznych; DOCTYPE/ENTITY i tak odrzucane)


def parse_wasde_lista(text, today=None):
    """v332: strona wydań raportu zbóż w oficjalnym archiwum → {'RRRR-MM': (dzień wydania 'RRRR-MM-DD', ścieżka pliku XML)}. Wiersz tabeli: znacznik
    czasu z dniem wydania i odnośniki do plików; przyjęte tylko ścieżki wg SR_WASDE_SCIEZKA (host zawsze SR_WASDE_ESMIS — odnośnik na inny host albo
    inną ścieżkę jest pomijany), miesiąc z nazwy pliku = miesiąc dnia wydania, dzień wydania nie później niż jutro; kilka plików tego samego
    miesiąca — późniejszy dzień, wyższa wersja (v2 po poprawce), większy numer. Brak wierszy = pusty słownik (wywołujący zgłasza zmianę układu)."""
    today = today or _now_utc().date()
    out, naj = {}, {}
    for row in re.findall(r'<tr\b.*?</tr>', text, re.S | re.I):
        d = re.search(r'<time[^>]*\bdatetime="(\d{4}-\d{2}-\d{2})', row)
        wyd = _sr_dz(d.group(1)) if d else None
        if not wyd or wyd > today + datetime.timedelta(days=1):
            continue
        for href in re.findall(r'href="([^"]+)"', row):
            m = SR_WASDE_SCIEZKA.match(href)
            if not m:
                continue
            ym = f'20{m.group(3)}-{m.group(2)}'
            if ym != wyd.isoformat()[:7]:
                continue
            klucz = (wyd.isoformat(), int(m.group(4) or 1), int(m.group(1)))
            if ym not in naj or klucz > naj[ym]:
                naj[ym] = klucz
                out[ym] = (wyd.isoformat(), href)
    return out


def parse_wasde_xml(raw, wyd):
    """v332: raport zbóż w XML (oficjalne archiwum) → ten sam kształt co parse_wasde ({'nr', 'wyd', 'mies', 'lata', 'k', 'zle'}) plus 'poprz' —
    prognoza poprzedniego miesiąca z tych samych tabel (kolumna z nazwą poprzedniego miesiąca w sezonie prognozy; {towar: {region: {sezon: {prod,
    kraj, eksp, zapasy}}}}) i 'zle_p' (straż tej części). wyd — dzień wydania ze strony wydań (w pliku go nie ma): musi wypadać w miesiącu raportu.
    Tabele: Report[sub_report_title] → matrix → region_header (sezon + „Est.”/„Proj.”) → region („World 3/”, „United States”, „Total Foreign”) →
    [forecast_month] → attribute → Cell[cell_value]; przypisy w etykietach („2/”, „/2”) pomijane; tabele w innej jednostce niż mln t pomijane.
    Bez DOCTYPE/ENTITY; jeden numer i jeden miesiąc raportu w całym pliku; ta sama komórka z dwiema różnymi wartościami = błąd."""
    b = raw.encode('utf-8') if isinstance(raw, str) else bytes(raw)
    if len(b) > SR_WASDE_XML_MAX:
        raise RuntimeError(f'plik raportu dłuższy niż {SR_WASDE_XML_MAX} B')
    if re.search(rb'<!\s*(?:DOCTYPE|ENTITY)', b, re.I):
        raise RuntimeError('plik zawiera deklarację typu dokumentu albo encji — odrzucony (encje nie są rozwijane)')
    try:
        root = _SrXml.fromstring(b)
    except _SrXml.ParseError:
        raise RuntimeError('to nie jest poprawny plik XML raportu') from None
    sp = lambda x: re.sub(r'\s+', ' ', str(x or '')).strip()   # noqa: E731
    bez = lambda x: sp(re.sub(r'(?:\b\d+/|/\d+\b)', ' ', str(x or '')))   # noqa: E731  przypisy „3/” i „/2” (ryż: „Total /2 Domestic”)
    raporty = list(root.iter('Report'))
    nr, miesiace = set(), set()
    for rep in raporty:
        m = re.search(r'WASDE\s*-\s*(\d+)\s*-', rep.get('page_title') or '')
        if m:
            nr.add(int(m.group(1)))
        if rep.get('Report_Month'):
            miesiace.add(sp(rep.get('Report_Month')))
    if len(nr) != 1 or len(miesiace) != 1:
        raise RuntimeError('różne numery albo miesiące raportu w pliku albo to nie plik raportu')
    nr, rm = nr.pop(), re.match(r'^([A-Za-z]+)\s+(\d{4})$', miesiace.pop())
    mies = (_sr_data_en(rm.group(1), 1, rm.group(2)) or '')[:7] if rm else ''
    if not mies or not _sr_dz(wyd) or wyd[:7] != mies:
        raise RuntimeError(f'zły miesiąc raportu albo dzień wydania ({mies or "—"}, {wyd})')
    m_biez, m_poprz = int(mies[5:7]), int(_sr_mies(mies, -1)[5:7])
    k, kp, lata = {}, {}, {}

    def wpisz(cid, c, val):
        reg, atr = SR_WASDE_REG.get(bez(c.get('region'))), SR_WASDE_ATR.get(bez(c.get('attribute')))
        mm = re.match(r'^(\d{4}/\d{2})\s*(Est\.|Proj\.)?', sp(c.get('region_header')))
        x = _num(val)
        if not (reg and atr and mm and _isnum(x) and x >= 0):
            return
        my, fl, fm = mm.group(1), mm.group(2) or '', sp(c.get('forecast_month'))
        cel = k
        if fl == 'Proj.' and fm:   # sezon prognozy: kolumny miesięcy — bieżący (do k) i poprzedni (do poprz); inny miesiąc pomijany
            n = SR_MIES_EN.index(fm[:3].lower()) + 1 if fm[:3].lower() in SR_MIES_EN else None
            if n == m_poprz and n != m_biez:
                cel = kp
            elif n != m_biez:
                return
        lata.setdefault(my, set()).add(fl)
        e = cel.setdefault(cid, {}).setdefault(reg, {}).setdefault(my, {})
        x = round(x, 2)
        if atr in e and e[atr] != x:
            raise RuntimeError(f'ta sama komórka z dwiema wartościami ({cid} {reg} {my} {atr})')
        e[atr] = x

    def idz(el, cid, c):
        for a, v in el.attrib.items():
            nazwa = a.rstrip('0123456789')
            if nazwa in SR_WASDE_XML_KLUCZE:
                c = {**c, nazwa: v}
        if el.tag == 'Cell':
            v = next((v for a, v in el.attrib.items() if a.startswith('cell_value')), None)
            if v is not None:
                wpisz(cid, c, v)
        for ch in el:
            idz(ch, cid, c)

    for rep in raporty:
        t = sp(rep.get('sub_report_title'))
        cid = next((c for c, n in SR_WASDE_T if t == n or t.startswith(n + ' ')), None)
        if cid and 'million metric tons' in sp(rep.get('sub_report_subtitle')).lower():
            idz(rep, cid, {})
    zle, zle_p = _sr_wasde_straz(k), _sr_wasde_straz(kp)
    if not k:
        raise RuntimeError('brak tabel zbóż świata' + (' (' + '; '.join(zle[:2]) + ')' if zle else ''))
    return {'nr': nr, 'wyd': wyd, 'mies': mies, 'lata': {y: sorted(f) for y, f in sorted(lata.items())}, 'k': k, 'zle': zle, 'poprz': kp, 'zle_p': zle_p}


def _sr_wasde_pop(cur, lista, P, uw):
    """Poprzedni raport z TEGO SAMEGO pliku XML (bez drugiego zapytania) w kształcie parse_wasde dla sr_zboza; None, gdy plik nie ma kolumny poprzedniego
    miesiąca (maj: nowy sezon) — wtedy p z części strony jak dawniej. Dzień wydania poprzedniego raportu: ze strony wydań, z poprzedniej części
    strony albo z kalendarza; numer: z poprzedniej części strony albo o 1 niższy. Zgodność: prognoza poprzedniego miesiąca z pliku = zapisana przy
    poprzednim raporcie (±SR_WASDE_TOL) — różnica tylko w notatce (urząd mógł poprawić plik)."""
    if cur.get('zle_p'):
        uw.append('wasde: prognoza poprzedniego raportu w pliku — świat ≠ USA + reszta świata (' + '; '.join(cur['zle_p'][:2]) + ') — pominięta')
    kp = cur.get('poprz') or {}
    if not kp:
        return None
    pm = _sr_mies(cur['mies'], -1)
    jest = bool(P) and P.get('mies') == pm   # poprzednia część strony to właśnie ten raport
    wyd = (lista.get(pm) or (None,))[0]
    if not wyd and jest and _sr_dz(P.get('wyd')):
        wyd = P['wyd']
    if not wyd:
        d, _t, z_kal, _x = _sr_wasde_exp(pm)
        wyd = d.isoformat() if z_kal else None
    rok = _sr_rok(cur['lata'], 'Proj.')
    if jest and P.get('rok') == rok:
        roz = []
        for cid, R in kp.items():
            for reg, S in R.items():
                e, q = _sr_zb_wpis(reg, S.get(rok)), ((P.get('k') or {}).get(cid) or {}).get(reg)
                for a in ('prod', 'zapasy'):
                    if e and isinstance(q, dict) and _isnum(e.get(a)) and _isnum(q.get(a)) and abs(e[a] - q[a]) > SR_WASDE_TOL:
                        roz.append(f'{cid} {reg} {a}: {e[a]} (plik) ≠ {q[a]} (zapisane przy poprzednim raporcie)')
        if roz:
            uw.append('wasde: prognoza poprzedniego raportu w pliku różni się od zapisanej — ' + '; '.join(roz[:3]))
    return {'nr': P['nr'] if jest else cur['nr'] - 1, 'wyd': wyd, 'mies': pm, 'k': kp}


def _sr_wasde_esmis(ctx, P):
    """Raport zbóż z oficjalnego archiwum: strona wydań → plik XML raportu z ostatniego terminu kalendarza (brak go w archiwum — poprzedni miesiąc,
    gdy części jeszcze nie ma; inaczej dane zostają: notatka, po SR_WASDE_404_DNI dniach od terminu — błąd). Prognoza poprzedniego raportu z tego
    samego pliku (_sr_wasde_pop). Zwraca miesiąc raportu w pliku danych."""
    now, cel = ctx['now'], _sr_wasde_cel(ctx['now'])
    lista = parse_wasde_lista(_sr_get(ctx, 'wasde', SR_WASDE_STRONA, maks=SR_WASDE_STRONA_MAX).decode('utf-8', 'replace'), now.date())
    if not lista:
        raise RuntimeError('strona wydań archiwum: brak odnośników do plików XML (zmieniony układ strony?)')
    cur = None
    for ym in (cel, _sr_mies(cel, -1)):
        if ym != cel and P and P['mies'] >= ym:
            break
        raw = None
        if ym in lista:
            try:
                raw = _sr_get(ctx, 'wasde', SR_WASDE_ESMIS + lista[ym][1], maks=SR_WASDE_XML_MAX)
            except urllib.error.HTTPError as e:
                if e.code != 404:
                    raise
        if raw is None:
            if (now - _sr_wasde_exp(ym)[3]).total_seconds() > SR_WASDE_404_DNI * 86400:
                raise RuntimeError(f'raport {ym}: brak pliku w archiwum ponad {SR_WASDE_404_DNI} dni po terminie — zaległy raport albo zmieniony układ strony wydań')
            ctx['uwagi'].append(f'wasde: raport {ym} — pliku jeszcze nie ma w archiwum (zwykle kilka minut po raporcie)')
            continue
        cur = parse_wasde_xml(raw, lista[ym][0])
        if cur['mies'] != ym:
            raise RuntimeError(f'plik {ym} zawiera raport z {cur["mies"]}')
        break
    if cur is None:
        if P:
            return P['mies']
        raise RuntimeError('brak pliku raportu w archiwum')
    if cur['zle']:
        ctx['bledy'].append('wasde: świat ≠ USA + reszta świata — ' + '; '.join(cur['zle'][:2]))
    if P and _sr_mies(P['mies'], 1) == cur['mies'] and cur['nr'] != P['nr'] + 1:   # kolejne miesiące = kolejne numery raportów
        ctx['uwagi'].append(f'wasde: numer raportu {cur["nr"]} nie następuje bezpośrednio po {P["nr"]} (poprzednia część) — sprawdzić')
    ctx['parts']['zboza'] = sr_zboza(cur, _sr_wasde_pop(cur, lista, P, ctx['uwagi']), P)
    return cur['mies']


def _sr_wasde(ctx):
    """Źródło zbóż: oficjalne archiwum (_sr_wasde_esmis); jego awaria (jakikolwiek błąd) = zapas, plik CSV (_sr_wasde_csv) — nie wcześniej niż
    SR_WASDE_CSV_PAUZA_MIN min po odmowie (403/429) tamtego serwera (st.wasde.csv_od; nagłówków ani ścieżek nie zmieniamy). Oba zawiodły = błąd archiwum
    (kod 403/429 archiwum wydłuża ponowienie do 6 h w _sr_due), przyczyna zapasu w notatce. st.wasde.via — skąd przyszedł raport."""
    now, z = ctx['now'], ctx['st'].setdefault('wasde', {})
    P = ctx['pp'].get('zboza')
    P = P if isinstance(P, dict) and isinstance(P.get('k'), dict) and isinstance(P.get('mies'), str) and isinstance(P.get('nr'), int) else None
    try:
        r = _sr_wasde_esmis(ctx, P)
        z['via'] = 'esmis'
        return r
    except Exception as e:
        blad = e
    if _su_min(now, z.get('csv_od')) < SR_WASDE_CSV_PAUZA_MIN:
        raise blad
    try:
        r = _sr_wasde_csv(ctx)
    except Exception as e2:
        if isinstance(e2, urllib.error.HTTPError) and e2.code in (403, 429):
            z['csv_od'] = now.replace(microsecond=0).isoformat()
        ctx['uwagi'].append(mask(f'wasde: zapas (plik CSV) też zawiódł — {e2}')[:160])
        raise blad from None
    z.pop('csv_od', None)
    z['via'] = 'csv'
    ctx['uwagi'].append(mask(f'wasde: archiwum — {blad}; raport z zapasu (plik CSV)')[:200])
    return r


SR_POBIERZ = {'cameco': _sr_cameco, 'steo': _sr_steo, 'wasde': _sr_wasde}


def build_su_raporty(prev=None, keys=None, now=None, fetch=None, budzet_s=None, run_t0=None):
    """v320: data/surowce-raporty.json. Każde źródło z własną bramką (_sr_due) i budżetem czasu; źródło bez klucza — pominięte z notatką; źródło
    z błędem — poprzednia część z datą (ok False, krótki zamaskowany błąd err); część bez próby — 'cached' (z danymi) albo False (jeszcze nie
    pobrana); błąd częściowy (np. towar ze złą sumą) — ok False i pole cz = {część: True}. Plik innej wersji = start od zera."""
    now = now or _now_utc()
    now_iso = now.replace(microsecond=0).isoformat()
    prev = prev if isinstance(prev, dict) and prev.get('v') == SR_V else {}
    keys = keys if isinstance(keys, dict) else {}
    st = json.loads(json.dumps(prev.get('st'))) if isinstance(prev.get('st'), dict) else {}
    ctx = {'now': now, 'keys': keys, 'st': st, 'pp': {p: prev[p] for p in SR_PARTS if isinstance(prev.get(p), dict)}, 'bledy': [], 'uwagi': [],
           'parts': {}, 't0': time.monotonic(), 'budzet': SR_BUDZET_S if budzet_s is None else budzet_s,
           'fetch': fetch or _sr_fetch}
    late = run_t0 is not None and time.monotonic() - run_t0 > BACK_LATE
    proby, zle, pominiete, czesc = {p: 0 for p in SR_PARTS}, {}, [], set()
    for src, part in SR_ZR:
        z = st.setdefault(src, {})
        if not _sr_due(src, z, now):
            continue
        if SR_KLUCZ.get(src) and not keys.get(SR_KLUCZ[src]):
            pominiete.append(f'{src} (brak {SR_KLUCZ[src]})'); continue
        if late:
            pominiete.append(f'{src} (długi przebieg)'); continue
        if time.monotonic() - ctx['t0'] + SR_ZAPYTANIA.get(src, 1) * SR_LIMIT_S[src] > ctx['budzet']:
            pominiete.append(f'{src} (budżet czasu)'); continue
        nb = len(ctx['bledy'])
        z['try'] = now_iso
        proby[part] += 1
        try:
            asof = SR_POBIERZ[src](ctx)
        except Exception as e:
            msg = mask(f'{src}: {e}')[:160]
            z['err'] = msg; zle.setdefault(part, []).append(msg)
            if isinstance(e, urllib.error.HTTPError) and e.code in (403, 429):   # odmowa dostępu albo limit — następna próba po 6 h (_sr_due)
                z['kod'] = e.code
            else:
                z.pop('kod', None)
            continue
        z['at'] = now_iso; z['asof'] = asof; z.pop('err', None); z.pop('kod', None)
        if len(ctx['bledy']) > nb:
            zle.setdefault(part, []).extend(mask(x)[:160] for x in ctx['bledy'][nb:])
            czesc.add(part)
    out = {'v': SR_V, 'at': None,
           'src': 'CapitalFlowAI — raporty miesięczne o surowcach (kody źródeł z: steo, wasde, cameco — pełne nazwy na stronie Źródła)'}
    pat = dict(prev.get('part_at') or {}) if isinstance(prev.get('part_at'), dict) else {}
    perr = dict(prev.get('err') or {}) if isinstance(prev.get('err'), dict) else {}
    ok = {}
    for p in SR_PARTS:
        if p in ctx['parts']:
            out[p] = ctx['parts'][p]; pat[p] = now_iso
        elif isinstance(prev.get(p), dict):
            out[p] = prev[p]
        if zle.get(p):
            ok[p] = False; perr[p] = '; '.join(zle[p])[:240]
        elif proby[p]:
            ok[p] = True; perr.pop(p, None)
        else:
            ok[p] = 'cached' if isinstance(out.get(p), dict) else False
            if not isinstance(out.get(p), dict) and p not in perr:
                perr[p] = 'brak danych (źródło jeszcze nie pobrane)'
    out['part_at'] = {p: pat[p] for p in SR_PARTS if pat.get(p) and isinstance(out.get(p), dict)}
    out['at'] = max(out['part_at'].values()) if out['part_at'] else (prev.get('at') or now_iso)
    out.update({'ok': ok, 'err': {p: perr[p] for p in SR_PARTS if perr.get(p)}, 'next': {p: _sr_next(p, out, now) for p in SR_PARTS}, 'st': st})
    if czesc:
        out['cz'] = {p: True for p in SR_PARTS if p in czesc}
    for x in ctx['uwagi']:
        META['notes'].append(mask('surowce (raporty): ' + x)[:200])
    for p in SR_PARTS:
        for x in zle.get(p, []):
            META['errors'].append(mask('surowce (raporty) ' + x)[:200])
    if pominiete:
        META['notes'].append('surowce (raporty): pominięte w tym przebiegu — ' + ', '.join(pominiete))
    return out


# ===================== v97: DANE RZĄDU USA (domena publiczna) — EIA, BLS, BEA =====================
# Klucze tylko z GitHub Secrets (EIA_KEY, BLS_KEY, BEA_KEY); nigdy w plikach wynikowych (maskowanie komunikatów: SECRETS).
EIA_API = 'https://api.eia.gov/v2/'
EIA_SERIES = (('wti', 'petroleum/pri/spt', 'daily', 'RWTC', 90),        # ropa WTI, Cushing — cena spot, USD za baryłkę
              ('brent', 'petroleum/pri/spt', 'daily', 'RBRTE', 90),     # ropa Brent — cena spot, USD za baryłkę
              ('gas', 'natural-gas/pri/fut', 'daily', 'RNGWHHD', 90),   # gaz Henry Hub — cena spot, USD za mln BTU
              ('crude', 'petroleum/stoc/wstk', 'weekly', 'WCESTUS1', 60),  # zapasy ropy w USA bez rezerwy strategicznej, tys. baryłek
              ('spr', 'petroleum/stoc/wstk', 'weekly', 'WCSSTUS1', 60))    # rezerwa strategiczna (SPR), tys. baryłek


def eia_series(key, route, freq, sid, n):
    """EIA API v2 → ([[data, wartość], …] rosnąco, jednostka). Kody tras i serii sprawdzone 25.09.2026 (DEMO_KEY);
    nie-liczba = brak (nigdy 0); odpowiedź z polem error = błąd."""
    q = urllib.parse.urlencode([('api_key', key), ('frequency', freq), ('data[0]', 'value'), ('facets[series][]', sid),
                                ('sort[0][column]', 'period'), ('sort[0][direction]', 'desc'), ('offset', '0'), ('length', str(n))])
    j = get_json(f'{EIA_API}{route}/data/?{q}')
    if not isinstance(j, dict) or j.get('error'):
        raise RuntimeError(str((j or {}).get('error') if isinstance(j, dict) else 'nieznany kształt odpowiedzi')[:140])
    rows = (j.get('response') or {}).get('data')
    if not isinstance(rows, list):
        raise RuntimeError('nieznany kształt odpowiedzi')
    out, unit = {}, None
    for r in rows:
        if not isinstance(r, dict) or r.get('series') != sid:
            continue
        d, v = str(r.get('period') or ''), _num(r.get('value'))
        if re.match(r'^\d{4}-\d{2}-\d{2}$', d) and v is not None and v == v and abs(v) != float('inf'):
            out[d] = v; unit = unit or r.get('units')
    if not out:
        raise RuntimeError('brak wartości')
    return [[d, out[d]] for d in sorted(out)], unit


def build_energia(key, prev=None):
    """data/energia.json — ceny ropy (WTI, Brent), gazu (Henry Hub) i zapasy ropy w USA (EIA). Seria bez odpowiedzi zostawia
    poprzednie wartości (z datą); bez żadnej nowej serii = błąd (zostaje poprzedni plik).
    v295: gdy w tym przebiegu jest surowce.json w wersji 2 — z TEGO SAMEGO pobrania (te same liczby, bez osobnych zapytań do EIA)."""
    su = _SU_RUN.get('su')
    if isinstance(su, dict) and su.get('v') == SU_V and isinstance(su.get('ceny'), dict) and (su['ceny'].get('wti') or su['ceny'].get('brent')):
        return energia_z_surowcow(su, prev)
    old = (prev or {}).get('s') if isinstance(prev, dict) else None
    old = old if isinstance(old, dict) else {}
    out = {'at': NOW, 'src': 'U.S. Energy Information Administration (EIA) — Open Data API v2', 'url': 'https://www.eia.gov/opendata/', 's': {}}
    fails, got = [], 0
    for name, route, freq, sid, n in EIA_SERIES:
        try:
            d, unit = eia_series(key, route, freq, sid, n)
            out['s'][name] = {'id': sid, 'freq': freq, 'unit': unit, 'd': d}; got += 1
        except Exception as e:
            fails.append(f'{sid}: {e}')
            if isinstance(old.get(name), dict):
                out['s'][name] = old[name]
    if not got:
        raise RuntimeError('brak serii' + (f' ({fails[0]})' if fails else ''))
    if fails:
        META['errors'].append(mask(f'EIA: {len(fails)} serie bez odpowiedzi, np. {fails[0]}'))
    return out


BLS_URL = 'https://api.bls.gov/publicAPI/v2/timeseries/data/'
BLS_SERIES = (('cpi', 'CUUR0000SA0'),      # inflacja CPI-U (indeks, bez korekty sezonowej — r/r z 12 miesięcy)
              ('core', 'CUUR0000SA0L1E'),  # inflacja bazowa (bez żywności i energii)
              ('unemp', 'LNS14000000'),    # stopa bezrobocia, %, z korektą sezonową
              ('nfp', 'CES0000000001'),    # zatrudnienie poza rolnictwem, tys. osób, z korektą sezonową
              ('ahe', 'CES0500000003'))    # średnia płaca godzinowa w sektorze prywatnym, USD


def post_json(url, obj, timeout=60):
    req = urllib.request.Request(url, data=json.dumps(obj).encode(), headers={'User-Agent': 'CapitalFlowAI-collector/1.0', 'Content-Type': 'application/json'})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode('utf-8', 'replace'))


def _yoy(rows, k=12):
    """Zmiana % wobec wartości sprzed k miesięcy — tylko gdy obie wartości istnieją (brak nie jest zerem)."""
    m = {d: v for d, v in rows}
    out = []
    for d, v in rows:
        y, mo = int(d[:4]), int(d[5:7]) - k
        while mo < 1:
            y, mo = y - 1, mo + 12
        p = m.get(f'{y:04d}-{mo:02d}')
        if v is not None and p:
            out.append([d, round((v / p - 1) * 100, 1)])
    return out


BLS_ZAPAS_DNI = 40   # v328: seria z poprzedniego pliku najwyżej tyle dni od jej pobrania


def _bls_zapas(out, prev, ok):
    """v328 (zb07-01): seria BLS, której zabrakło w odpowiedzi (albo bez miesięcy), zostaje z poprzedniego pliku z własnym czasem pobrania
    (out['part_at'][seria]) — gdy ma te same id i jest młodsza niż BLS_ZAPAS_DNI dni; pochodne (r/r, zmiana m/m) liczone potem z jej wierszy."""
    ps = prev.get('s') if isinstance(prev, dict) and isinstance(prev.get('s'), dict) else {}
    for name, sid in BLS_SERIES:
        o = ps.get(name)
        kiedy = _zapas_czas(prev, name)
        if not ok[name] and isinstance(o, dict) and o.get('id') == sid and isinstance(o.get('d'), list) and o['d'] and _zapas_wiek_ok(kiedy, BLS_ZAPAS_DNI):
            out['s'][name] = {'id': sid, 'd': o['d']}
            out.setdefault('part_at', {})[name] = kiedy


def build_usa_makro(key, prev=None, today=None):
    """data/usa-makro.json — BLS (miesięcznie): inflacja r/r (CPI i bazowa), bezrobocie, zatrudnienie (zmiana m/m), płace r/r.
    „-” w danych BLS (np. październik 2025 — przerwa w pracy rządu USA) = brak, nigdy 0."""
    y = (today or _now_utc().date()).year
    body = {'seriesid': [s for _, s in BLS_SERIES], 'startyear': str(y - 2), 'endyear': str(y)}
    if key:
        body['registrationkey'] = key
    j = post_json(BLS_URL, body)
    if not isinstance(j, dict) or j.get('status') != 'REQUEST_SUCCEEDED':
        raise RuntimeError(f"{(j or {}).get('status') if isinstance(j, dict) else '?'}: {'; '.join(map(str, (j or {}).get('message') or []))[:160] if isinstance(j, dict) else ''}")
    series = {s.get('seriesID'): s for s in ((j.get('Results') or {}).get('series') or []) if isinstance(s, dict)}
    out = {'at': NOW, 'src': 'U.S. Bureau of Labor Statistics (BLS) — Public Data API v2', 'url': 'https://www.bls.gov/developers/', 's': {}}
    for name, sid in BLS_SERIES:
        rows = {}
        for r in (series.get(sid) or {}).get('data') or []:
            p, yr = str(r.get('period') or ''), str(r.get('year') or '')
            if re.match(r'^M(0[1-9]|1[0-2])$', p) and re.match(r'^\d{4}$', yr):   # M13 = średnia roczna — pomijamy
                rows[f'{yr}-{p[1:]}'] = _num(r.get('value'))
        if rows:
            out['s'][name] = {'id': sid, 'd': [[d, rows[d]] for d in sorted(rows)]}
    if not out['s']:
        raise RuntimeError('brak serii w odpowiedzi')
    ok = {name: name in out['s'] for name, _ in BLS_SERIES}   # v328 (zb07-01): która seria odpowiedziała; brakująca — z poprzedniego pliku (_bls_zapas)
    _bls_zapas(out, prev, ok)
    out['ok'] = ok
    for name in ('cpi', 'core', 'ahe'):
        if name in out['s']:
            out['s'][name]['yoy'] = _yoy(out['s'][name]['d'])
    if 'nfp' in out['s']:
        d = out['s']['nfp']['d']
        out['s']['nfp']['chg'] = [[b[0], round(b[1] - a[1], 1)] for a, b in zip(d, d[1:])   # zmiana m/m tylko dla dwóch kolejnych miesięcy z danymi
                                  if a[1] is not None and b[1] is not None and _next_month(a[0]) == b[0]]
    miss = [s for _, s in BLS_SERIES if not (series.get(s) or {}).get('data')]
    if miss:
        META['errors'].append(f'BLS: brak serii {", ".join(miss)}')
    return out


def _next_month(ym):
    y, m = int(ym[:4]), int(ym[5:7]) + 1
    return f'{y + (m - 1) // 12:04d}-{(m - 1) % 12 + 1:02d}'


BEA_URL = 'https://apps.bea.gov/api/data'
BEA_IND = ('BalCurrAcct', 'FinAssetsExclFinDeriv', 'FinLiabsExclFinDeriv', 'NetLendBorrFinAcct')
BEA_AREA_IND = ('FinAssetsExclFinDeriv', 'FinLiabsExclFinDeriv')


def bea_get(key, **params):
    """BEA API → Results; błąd BEA (także „Invalid API UserId”) = wyjątek. Klucz w adresie — komunikaty maskowane (SECRETS)."""
    q = urllib.parse.urlencode({'UserID': key, **params, 'ResultFormat': 'JSON'})
    j = get_json(f'{BEA_URL}?{q}')
    api = (j or {}).get('BEAAPI') if isinstance(j, dict) else None
    if not isinstance(api, dict):
        raise RuntimeError('nieznany kształt odpowiedzi')
    res = api.get('Results')
    err = api.get('Error') or (res.get('Error') if isinstance(res, dict) else None)
    if err:
        raise RuntimeError(str(err.get('APIErrorDescription') if isinstance(err, dict) else err)[:160])
    if isinstance(res, list):
        res = res[0] if res and isinstance(res[0], dict) else {}
    return res if isinstance(res, dict) else {}


def _bea_q(p):
    m = re.match(r'^(\d{4})Q([1-4])$', str(p or ''))
    return f'{m.group(1)}-Q{m.group(2)}' if m else None


def _bea_mln(r):
    """Wartość BEA w mln USD (DataValue z przecinkami × 10^(UNIT_MULT−6)); „(D)”, puste = brak."""
    v = _num(r.get('DataValue'))
    if v is None or v != v or abs(v) == float('inf'):
        return None
    m = _num(r.get('UNIT_MULT'))
    return round(v * 10 ** ((6 if m is None else m) - 6), 1)


BEA_ZAPAS_DNI = 100   # v328: część z poprzedniego pliku najwyżej tyle dni od jej pobrania (dane kwartalne)


def _bea_ost_q(x):
    """v328: ostatni kwartał szeregu [[kwartał, wartość], …] albo ''."""
    return x[-1][0] if isinstance(x, list) and x and isinstance(x[-1], list) and x[-1] else ''


def _bea_zapas(out, prev, ok):
    """v328 (zb07-01): część BEA, której zapytanie zawiodło (ok[klucz] False), zostaje z poprzedniego pliku z własnym czasem pobrania
    (out['part_at'][klucz]); klucze: ind, names, gdp, ita:<wskaźnik>, areas:<wskaźnik>. Okresów nie mieszamy: wskaźnik ITA (obszary) z poprzedniego pliku
    tylko z tym samym ostatnim kwartałem co świeże wskaźniki tej grupy; część starsza niż BEA_ZAPAS_DNI dni — bez zapasu."""
    if not isinstance(prev, dict):
        return
    pat = {}

    def bierz(klucz):
        kiedy = _zapas_czas(prev, klucz)
        return kiedy if _zapas_wiek_ok(kiedy, BEA_ZAPAS_DNI) else None
    for k in ('ind', 'names'):
        if not ok[k] and isinstance(prev.get(k), dict) and prev[k] and bierz(k):
            out[k] = prev[k]; pat[k] = bierz(k)
    if not ok['gdp'] and isinstance(prev.get('gdp'), list) and prev['gdp'] and bierz('gdp'):
        out['gdp'] = prev['gdp']; pat['gdp'] = bierz('gdp')
    ita_q = max((_bea_ost_q(x) for x in out['ita'].values()), default='')
    pita = prev.get('ita') if isinstance(prev.get('ita'), dict) else {}
    for i in BEA_IND:
        x = pita.get(i)
        if not ok['ita:' + i] and isinstance(x, list) and x and (not ita_q or _bea_ost_q(x) == ita_q) and bierz('ita:' + i):
            out['ita'][i] = x; pat['ita:' + i] = bierz('ita:' + i)
    ar_q = max((_bea_ost_q(s) for a in out['areas'].values() for s in a.values()), default='')
    par = prev.get('areas') if isinstance(prev.get('areas'), dict) else {}
    for i in BEA_AREA_IND:
        x = par.get(i)
        if (not ok['areas:' + i] and isinstance(x, dict) and x and bierz('areas:' + i)
                and (not ar_q or max((_bea_ost_q(s) for s in x.values()), default='') == ar_q)):
            out['areas'][i] = x; pat['areas:' + i] = bierz('areas:' + i)
    if pat:
        out['part_at'] = pat


def build_bilans_usa(key, prev=None, today=None):
    """data/bilans-usa.json — BEA: bilans płatniczy USA kwartalnie (rachunek bieżący, kapitał z USA za granicę i z zagranicy do USA,
    także według obszarów) oraz realny PKB (zmiana % kw/kw, w skali roku). Uzupełnia TIC (miesięczne transakcje w papierach)."""
    y = (today or _now_utc().date()).year
    years = ','.join(str(x) for x in range(y - 3, y + 1))
    out = {'at': NOW, 'src': 'U.S. Bureau of Economic Analysis (BEA) — Data API (ITA, NIPA T10101)', 'url': 'https://apps.bea.gov/api/',
           'unit': 'mln USD; PKB: % kw/kw w skali roku', 'ita': {}, 'areas': {}, 'names': {}, 'ind': {}, 'gdp': []}
    fails = []
    try:
        have = {v.get('Key'): v.get('Desc') for v in (bea_get(key, method='GetParameterValues', datasetname='ITA', ParameterName='Indicator').get('ParamValue') or [])
                if isinstance(v, dict) and v.get('Key')}
        out['ind'] = {k: have[k] for k in BEA_IND if k in have}
        missing = [k for k in BEA_IND if k not in have]
        if missing and have:
            META['notes'].append('BEA: brak wskaźników ' + ', '.join(missing))
    except Exception as e:
        fails.append(f'lista wskaźników: {e}')
    try:
        out['names'] = {v.get('Key'): v.get('Desc') for v in (bea_get(key, method='GetParameterValues', datasetname='ITA', ParameterName='AreaOrCountry').get('ParamValue') or [])
                        if isinstance(v, dict) and v.get('Key')}
    except Exception as e:
        fails.append(f'lista obszarów: {e}')
    for ind in BEA_IND:
        try:
            d = {}
            for r in bea_get(key, method='GetData', datasetname='ITA', Indicator=ind, AreaOrCountry='AllCountries', Frequency='QSA', Year=years).get('Data') or []:
                q, v = _bea_q(r.get('TimePeriod')), _bea_mln(r) if isinstance(r, dict) else None
                if q and v is not None:
                    d[q] = v
            if d:
                out['ita'][ind] = [[q, d[q]] for q in sorted(d)]
            else:
                fails.append(f'{ind}: brak wartości')
        except Exception as e:
            fails.append(f'{ind}: {e}')
    for ind in BEA_AREA_IND:
        try:
            A = {}
            for r in bea_get(key, method='GetData', datasetname='ITA', Indicator=ind, AreaOrCountry='All', Frequency='QNSA', Year=years).get('Data') or []:
                if not isinstance(r, dict):
                    continue
                a, q, v = str(r.get('AreaOrCountry') or ''), _bea_q(r.get('TimePeriod')), _bea_mln(r)
                if a and q and v is not None:
                    A.setdefault(a, {})[q] = v
            if A:
                out['areas'][ind] = {a: [[q, x[q]] for q in sorted(x)][-12:] for a, x in sorted(A.items())}
            else:
                fails.append(f'{ind} (obszary): brak wartości')
        except Exception as e:
            fails.append(f'{ind} (obszary): {e}')
    try:
        g = {}
        for r in bea_get(key, method='GetData', datasetname='NIPA', TableName='T10101', Frequency='Q', Year=years).get('Data') or []:
            if isinstance(r, dict) and str(r.get('LineNumber')) == '1':
                q, v = _bea_q(r.get('TimePeriod')), _num(r.get('DataValue'))
                if q and v is not None:
                    g[q] = v
        out['gdp'] = [[q, g[q]] for q in sorted(g)]
        if not g:
            fails.append('PKB: brak wartości')
    except Exception as e:
        fails.append(f'PKB: {e}')
    if not out['ita'] and not out['areas'] and not out['gdp']:
        raise RuntimeError('brak danych' + (f' ({fails[0]})' if fails else ''))
    ok = {'ind': bool(out['ind']), 'names': bool(out['names']), 'gdp': bool(out['gdp'])}   # v328 (zb07-01): która część odpowiedziała;
    ok.update({'ita:' + i: i in out['ita'] for i in BEA_IND})                              # brakująca — z poprzedniego pliku (_bea_zapas)
    ok.update({'areas:' + i: i in out['areas'] for i in BEA_AREA_IND})
    _bea_zapas(out, prev, ok)
    out['ok'] = ok
    if fails:
        META['errors'].append(mask(f'BEA: {len(fails)} zapytań bez danych, np. {fails[0]}'))
    return out


# ===================== v99: OECD na serwerze =====================
# Indeksy giełdowe (SHARE), rentowności 10-letnie (IRLT) i wskaźnik wyprzedzający (CLI) dla 27 krajów mapy GLOBAL.
# Strona pobierała je dotąd prosto z OECD; OECD ogranicza liczbę zapytań z jednego adresu (HTTP 429) i wtedy mapa
# pokazywała „dane przykładowe”. Teraz: zbieracz co 6 h → data/oecd.json; strona pyta OECD tylko, gdy pliku brak.
# Lista krajów = kody ISO z GREG na stronie (test pilnuje zgodności).
OECD_ISO = ['USA', 'CAN', 'BRA', 'MEX', 'CHL', 'COL', 'DEU', 'FRA', 'GBR', 'ITA', 'ESP', 'NLD', 'CHE', 'SWE', 'POL', 'RUS',
            'SAU', 'TUR', 'ISR', 'ZAF', 'IND', 'CHN', 'JPN', 'KOR', 'IDN', 'AUS', 'NZL']
OECD_BASE = 'https://sdmx.oecd.org/public/rest/data/'
OECD_Q = {   # te same zapytania co na stronie (GSRC.oecd / rate / cli)
    'share': 'OECD.SDD.STES,DSD_STES@DF_FINMARK,4.0/{iso}.M.SHARE.IX._Z._Z._Z._Z.N',
    'irlt': 'OECD.SDD.STES,DSD_STES@DF_FINMARK,4.0/{iso}.M.IRLT.PA._Z._Z._Z._Z.N',
    'cli': 'OECD.SDD.STES,DSD_STES@DF_CLI,4.1/{iso}.M.LI...AA...H',
}
OECD_SLEEP = 4       # odstęp między trzema zapytaniami (limit OECD na adres)
OECD_EVERY = 6 * 60  # dane miesięczne — co 6 h wystarczy
OECD_RETRY = 60      # część z błędem — ponów po godzinie, nie co 20 min


def oecd_start(today=None, months=15):
    """Pierwszy miesiąc zapytania — jak gStart() na stronie: bieżący miesiąc minus 15."""
    d = today or datetime.datetime.now(datetime.timezone.utc).date()
    m = d.year * 12 + (d.month - 1) - months
    return f'{m // 12:04d}-{m % 12 + 1:02d}'


def oecd_parse(j):
    """SDMX-JSON (obserwacje płaskie) → {kraj: [[miesiąc, wartość], …]} rosnąco — ten sam kształt co gOecd() na stronie.
    Brak obserwacji albo wartość nieliczbowa = brak wpisu (nigdy zero)."""
    D = j['data']['structure']['dimensions']['observation']
    obs = j['data']['dataSets'][0].get('observations') or {}
    iA = next(i for i, d in enumerate(D) if d.get('id') == 'REF_AREA')
    iT = next(i for i, d in enumerate(D) if d.get('id') == 'TIME_PERIOD')
    A = [v.get('id') for v in D[iA]['values']]
    T = [v.get('id') for v in D[iT]['values']]
    out = {}
    for k, v in obs.items():
        p = k.split(':')
        x = v[0] if isinstance(v, list) and v else None
        if isinstance(x, bool) or not isinstance(x, (int, float)) or x != x:
            continue
        a, tm = A[int(p[iA])], T[int(p[iT])]
        if a and tm:
            out.setdefault(a, {})[tm] = x
    return {a: [[tm, v] for tm, v in sorted(m.items())] for a, m in sorted(out.items())}


def oecd_get(path, start, _retry=True):
    url = f'{OECD_BASE}{path.format(iso="+".join(OECD_ISO))}?startPeriod={start}&format=jsondata&dimensionAtObservation=AllDimensions'
    try:
        return get_json(url, timeout=60)
    except urllib.error.HTTPError as e:
        if e.code == 429 and _retry:   # limit zapytań OECD — jedna ponowna próba po przerwie
            time.sleep(20)
            return oecd_get(path, start, _retry=False)
        raise


def build_oecd(prev=None, today=None):
    start = oecd_start(today)
    prev = prev if isinstance(prev, dict) else {}
    pat = prev.get('part_at') if isinstance(prev.get('part_at'), dict) else {}
    out = {'at': NOW, 'start': start, 'iso': OECD_ISO, 'ok': {}, 'part_at': {}}
    fails = []
    for i, (k, path) in enumerate(OECD_Q.items()):
        if i:
            time.sleep(OECD_SLEEP)
        try:
            ser = oecd_parse(oecd_get(path, start))
            if not ser:
                raise ValueError('pusta odpowiedź')
            out[k] = ser; out['ok'][k] = True; out['part_at'][k] = NOW
        except Exception as e:  # noqa — część bez danych: poprzednia wersja tej części (z własnym czasem), nigdy zera
            fails.append(f'{k}: {e}'); out['ok'][k] = False
            if isinstance(prev.get(k), dict) and prev[k]:
                out[k] = prev[k]; out['part_at'][k] = pat.get(k) or prev.get('at')
    if 'share' not in out:
        raise RuntimeError('brak indeksów giełdowych' + (f' ({fails[0]})' if fails else ''))
    if fails:
        META['errors'].append(mask(f'OECD: {"; ".join(fails)}'))
    return out


# ===================== v101: kursy walut i rentowności 10L na serwerze =====================
# Strona pobierała je z przeglądarki przy każdym wejściu (6 zapytań kursów, 2 pliki XML Skarbu USA po ~0,5 MB, Bundesbank).
# Teraz: zbieracz co godzinę → data/rynki.json; strona pyta źródła sama tylko, gdy części pliku brak albo jest za stara.
FX_URL = 'https://api.frankfurter.dev/v1/{d}?from=USD'
UST_URL = 'https://home.treasury.gov/resource-center/data-chart-center/interest-rates/pages/xml?data=daily_treasury_yield_curve&field_tdr_date_value={y}'
BUBA_URL = 'https://api.statistiken.bundesbank.de/rest/data/BBSIS/D.I.ZAR.ZI.EUR.S1311.B.A604.R10XX.R.A.A._Z._Z.A?startPeriod={f}&format=json'
RYNKI_EVERY = 60     # kursy EBC i rentowności zmieniają się raz dziennie — co godzinę wystarczy
RYNKI_RETRY = 60     # v331 (zb07-04): część z błędem ponawiana najwcześniej po tylu minutach od ostatniej budowy (dawniej co przebieg, 8 zapytań co 10 min)
UST_DNI = 400        # v331 (zb07-06): rentowność USA — wiersze nie starsze niż tyle dni zostają w pliku także z roku y-2 (1R na przełomie roku)
FX_ECB_URL = ('https://data-api.ecb.europa.eu/service/data/EXR/D..EUR.SP00.A?startPeriod={od}&endPeriod={do}&format=csvdata')   # v255: zapas —
#   kursy referencyjne prosto z EBC (pośrednik je tylko przekazuje); 06.10.2026: 29 walut, okno 11 dni ok. 45 KB, 0,6 s
FX_ECB_OKNO = 10     # v255: dni wstecz od daty — ostatni fixing ≤ data (weekendy, święta TARGET)
RYNKI_PX = {'fx': 'Frankfurter', 'ust': 'Skarb USA 10L', 'buba': 'Bundesbank 10L'}   # początek komunikatu błędu (strona Źródła)


def months_back(d, n):
    """Ten sam dzień n miesięcy wcześniej (koniec miesiąca przycięty) — jak back(n) na stronie."""
    m = d.year * 12 + (d.month - 1) - n
    y, mo = m // 12, m % 12 + 1
    last = (datetime.date(y + (mo == 12), mo % 12 + 1, 1) - datetime.timedelta(days=1)).day
    return datetime.date(y, mo, min(d.day, last))


def fx_dates(d0):
    """v178: daty odniesienia kursów od dnia OSTATNIEGO fixingu d0 (jak gDaily na stronie: 1D = poprzedni fixing, pozostałe = ostatni fixing
    ≤ d0 − okres; źródło za dzień bez fixingu podaje ostatni wcześniejszy). Dawniej od dzisiejszej daty — przed publikacją EBC (ok. 14:00 UTC),
    w weekendy i w poniedziałki 1D był tym samym fixingiem co „now” (indeks dolara „dziś” 0,00% przez ok. 15 h na dobę), a 1T obejmował 4 sesje."""
    return {'1M': months_back(d0, 1).isoformat(), '1Q': months_back(d0, 3).isoformat(), '1R': months_back(d0, 12).isoformat(),
            '1D': (d0 - datetime.timedelta(days=1)).isoformat(), '1T': (d0 - datetime.timedelta(days=7)).isoformat()}


def ust_parse(xml_text):
    """Plik XML Skarbu USA (krzywa rentowności) → [[dzień, rentowność 10L], …] rosnąco — jak gUst() na stronie."""
    import xml.etree.ElementTree as ET
    root = ET.fromstring(xml_text)
    loc = lambda e: e.tag.rsplit('}', 1)[-1]
    out = {}
    for ent in root.iter():
        if loc(ent) != 'entry':
            continue
        d = y = None
        for e in ent.iter():
            if loc(e) == 'NEW_DATE':
                d = (e.text or '')[:10]
            elif loc(e) == 'BC_10YEAR':
                y = e.text
        try:
            v = float(y)
        except (TypeError, ValueError):
            continue
        if d and v == v:
            out[d] = v
    return [[k, out[k]] for k in sorted(out)]


def buba_parse(j):
    """SDMX-JSON Bundesbanku → [[dzień, rentowność], …] rosnąco — jak gBuba() na stronie."""
    o = j.get('data') or j
    ser = list(o['dataSets'][0]['series'].values())[0]
    T = [v['id'] for v in o['structure']['dimensions']['observation'][0]['values']]
    out = []
    for k, v in ser['observations'].items():
        try:
            x = float(v[0])
        except (TypeError, ValueError, IndexError):
            continue
        if x == x:
            out.append([T[int(k)], x])
    return sorted(out)


def fx_ecb_csv(text):
    """v255: CSV portalu danych EBC (zbiór EXR, D.<waluta>.EUR.SP00.A) → {dzień: {waluta: jednostek za 1 EUR}}; puste i złe wartości pominięte."""
    import csv
    import io
    out = {}
    for r in csv.DictReader(io.StringIO(str(text or '').lstrip('\ufeff'))):
        d, c = str(r.get('TIME_PERIOD') or '')[:10], r.get('CURRENCY')
        try:
            x = float(r.get('OBS_VALUE'))
        except (TypeError, ValueError):
            continue
        if _d(d) and c and x == x and 0 < x < 1e9:
            out.setdefault(d, {})[c] = x
    return out


def fx_ecb_dzien(by_day, d):
    """v255: ostatni fixing ≤ d w układzie pośrednika — {'amount': 1.0, 'base': 'USD', 'date', 'rates' (waluta za 1 USD, 5 cyfr znaczących, z EUR)};
    brak fixingu z kursem USD = None."""
    dni = [x for x in sorted(by_day) if x <= d and by_day[x].get('USD')]
    if not dni:
        return None
    x = dni[-1]
    v = by_day[x]
    usd = v['USD']
    rates = {c: float(f'{k / usd:.5g}') for c, k in v.items() if c != 'USD'}
    rates['EUR'] = float(f'{1 / usd:.5g}')
    return {'amount': 1.0, 'base': 'USD', 'date': x, 'rates': dict(sorted(rates.items()))}


def fx_z_ecb(today, pobierz=None):
    """v255: kursy now/1D/1T/1M/1Q/1R prosto z EBC — te same daty co z pośrednika (fx_dates od dnia ostatniego fixingu; odniesienie musi być
    wcześniejszym fixingiem). pobierz(url) → tekst CSV."""
    pobierz = pobierz or (lambda url: get(url, timeout=30)[1])
    okno = lambda d: FX_ECB_URL.format(od=(d - datetime.timedelta(days=FX_ECB_OKNO)).isoformat(), do=d.isoformat())  # noqa: E731
    r = {'now': fx_ecb_dzien(fx_ecb_csv(pobierz(okno(today))), today.isoformat())}
    if not r['now']:
        raise ValueError('kursy now: brak')
    d0 = _d(r['now']['date'])
    for k, d in fx_dates(d0).items():
        x = fx_ecb_dzien(fx_ecb_csv(pobierz(okno(_d(d)))), d)
        if not x or _d(x['date']) >= d0:
            raise ValueError(f'kursy {k}: brak fixingu przed {d0.isoformat()}')
        r[k] = x
    return r


def rynki_fx_nota(r):
    """v258 (przegląd v255): kursy z zapasu EBC — notatka w meta z przyczyną (pośrednik nie odpowiadał), w każdym przebiegu, także z pamięci;
    inaczej awaria pośrednika mogłaby trwać niezauważona (zapas działa, błędu brak)."""
    if isinstance(r, dict) and r.get('fx_src') == 'EBC':
        kiedy = str(((r.get('part_at') or {}).get('fx') if isinstance(r.get('part_at'), dict) else None) or r.get('at') or '—')[:16].replace('T', ' ')
        META['notes'].append(mask(f"Kursy walut (odświeżenie {kiedy} UTC): pośrednik nie odpowiadał ({str(r.get('fx_err') or '—')[:100]})"
                                  ' — kursy referencyjne prosto z EBC (te same daty)'))


def build_rynki(prev=None, today=None):
    today = today or datetime.datetime.now(datetime.timezone.utc).date()
    prev = prev if isinstance(prev, dict) else {}
    pat = prev.get('part_at') if isinstance(prev.get('part_at'), dict) else {}
    out = {'at': NOW, 'ok': {}, 'part_at': {}}

    def part(k, fn):
        try:
            v = fn()
            if not v:
                raise ValueError('pusta odpowiedź')
            out[k] = v; out['ok'][k] = True; out['part_at'][k] = NOW
        except Exception as e:  # noqa — część z błędem: poprzednia wersja z własnym czasem, nigdy zera
            META['errors'].append(mask(f'{RYNKI_PX[k]}: {e}')); out['ok'][k] = False
            out.setdefault('errs', {})[k] = mask(str(e))[:160]   # v331: przyczyna zostaje w pliku (wpis w META także w przebiegach z pamięci)
            if prev.get(k):
                out[k] = prev[k]; out['part_at'][k] = pat.get(k) or prev.get('at')

    def fx_frank():
        def one(k, d):
            j = get_json(FX_URL.format(d=d))
            if not isinstance(j, dict) or not isinstance(j.get('rates'), dict) or not j['rates']:
                raise ValueError(f'kursy {k}: brak')
            return {'amount': j.get('amount'), 'base': j.get('base'), 'date': j.get('date'), 'rates': j['rates']}
        r = {'now': one('now', 'latest')}
        d0 = _d(r['now']['date'])   # v178: odniesienia od dnia ostatniego fixingu, nie od dzisiejszej daty
        if d0 is None or d0 > today:
            raise ValueError(f"kursy now: zła data {r['now']['date']!r}")
        for k, d in fx_dates(d0).items():
            r[k] = one(k, d)
            dk = _d(r[k]['date'])
            if dk is None or dk >= d0:   # odniesienie musi być wcześniejszym fixingiem — inaczej zmiana 0,00% zamiast braku
                raise ValueError(f"kursy {k}: data {r[k]['date']!r} nie przed {d0.isoformat()}")
        return r

    def fx():   # v255: pośrednik nie odpowiada — kursy referencyjne prosto z EBC (te same dane, pierwsza ręka); oba zawiodą — błąd jak dotąd
        try:
            return fx_frank()
        except Exception as e1:  # noqa
            try:
                r = fx_z_ecb(today)
            except Exception as e2:  # noqa
                raise ValueError(f'{e1}; zapas EBC: {str(e2)[:80]}')
            out['fx_src'] = 'EBC'; out['fx_err'] = mask(str(e1)[:120])   # v258: przyczyna zostaje w pliku (notatka także w przebiegach z pamięci)
            return r

    def ust():
        y = today.year
        lim = (today - datetime.timedelta(days=UST_DNI)).isoformat()
        rows = [r for r in (prev.get('ust') or []) if isinstance(r, list) and r and isinstance(r[0], str)]
        old = [r for r in rows if r[0].startswith(str(y - 1))]
        if len(old) < 200:   # poprzedni rok zmienia się rzadko — pobierany tylko, gdy w pliku go brak
            old = ust_parse(get(UST_URL.format(y=y - 1), timeout=60)[1])
        if int(lim[:4]) < y - 1:   # v331 (zb07-06): początek roku — okres 1R potrzebuje końca roku y-2 (Skarb USA nowy rok zaczyna pustym kanałem)
            od = f'{y - 1}-01-01'
            tail = [r for r in rows if lim <= r[0] < od]
            if not tail:   # brak w poprzednim pliku (pierwszy przebieg, plik sprzed v331) — jedno dodatkowe zapytanie; jego błąd nie psuje części
                try:
                    tail = [r for r in ust_parse(get(UST_URL.format(y=y - 2), timeout=60)[1]) if lim <= r[0] < od]
                except Exception as e:  # noqa
                    META['notes'].append(mask(f'{RYNKI_PX["ust"]}: koniec roku {y - 2} (odniesienie 1R na początku roku) niedostępny: {str(e)[:80]}'))
            old = tail + old
        cur = ust_parse(get(UST_URL.format(y=y), timeout=60)[1])
        return old + [r for r in cur if not old or r[0] > old[-1][0]]

    def buba():
        return buba_parse(get_json(BUBA_URL.format(f=months_back(today, 13).isoformat()), timeout=60))

    part('fx', fx); part('ust', ust); part('buba', buba)
    if not out['ok'].get('fx') and 'fx' in out and prev.get('fx_src'):   # v258: poprzednie kursy zostają razem z ich pochodzeniem
        out['fx_src'] = prev['fx_src']
        if prev.get('fx_err'):
            out['fx_err'] = prev['fx_err']
    rynki_fx_nota(out)
    if not any(out['ok'].values()):
        raise RuntimeError('żadna część nie odpowiedziała')
    return out


