LNG_SK_MIES = 19                    # import: okno pobrania (miesięcy wstecz od bieżącego); UE27 spóźnia się o 2–4 miesiące, a wiersz „rok wcześniej” musi być w odpowiedzi także tuż przed publikacją
#                                     kolejnego miesiąca (z oknem 15 miesięcy pole rok znikało na ok. 10 dni w miesiącu); szereg hist i tak przycięty do 15 pozycji
LNG_GWH_MLN_M3 = 10.7               # GWh w 1 mln m³ gazu (ciepło spalania ok. 38,5 MJ/m³ — przeliczenie przybliżone; UE27 lipiec 2026: 38,8 TJ/mln m³)
LNG_ENTSOG = 'https://transparency.entsog.eu/api/v1/operationalData?indicator=Physical%20Flow&pointKey='
LNG_ESTAT = 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/'
LNG_GEO = ('EU27_2020', 'DE', 'PL')
LNG_LIMIT_S = {'dz': 45, 'skad': 25, 'zapasy': 25}
LNG_MAKS_B = {'dz': 40_000_000, 'skad': 3_000_000, 'zapasy': 2_000_000}   # po rozpakowaniu (okno 14 dób ≈ 0,5 MB, 120 dób ≈ 4,6 MB)
LNG_GZ_MAKS = 12_000_000            # B na łączu (120 dób ≈ 0,18 MB)
LNG_BUDZET_S = 100
LNG_CZESTO_MIN, LNG_RZADKO_MIN, LNG_ZALEGLE_H = 60, 360, 72
LNG_SLOT_UTC = (21, 30)             # skad, zapasy: raz na dobę po tej godzinie (publikacja zbioru ok. 21:00 UTC)


def _lng_d(s):
    """'RRRR-MM-DD' → data; inaczej None."""
    try:
        return datetime.date.fromisoformat(s) if isinstance(s, str) and re.match(r'^\d{4}-\d{2}-\d{2}$', s) else None
    except ValueError:
        return None


def _lng_przes(ds, k):
    """Dzień ds ('RRRR-MM-DD') przesunięty o k dni."""
    return (datetime.date.fromisoformat(ds) + datetime.timedelta(days=k)).isoformat()


def _lng_rok_wstecz(ds, k):
    """Ten sam dzień kalendarzowy k lat wcześniej (29 lutego → 28 lutego)."""
    d = datetime.date.fromisoformat(ds)
    try:
        return d.replace(year=d.year - k).isoformat()
    except ValueError:
        return d.replace(year=d.year - k, day=28).isoformat()


def _lng_liczba(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)


def _lng_wart(v):
    """Wartość punktu w kWh/d (liczba albo tekst z liczbą) → GWh/d; pusta, ujemna, nie-liczba albo ponad LNG_PUNKT_MAX = None (nigdy 0)."""
    if isinstance(v, str):
        try:
            v = float(v.strip())
        except ValueError:
            return None
    if not _lng_liczba(v) or v < 0 or v / 1e6 > LNG_PUNKT_MAX:
        return None
    return v / 1e6


def parse_lng_dz(j):
    """Odpowiedź platformy (operationalData) → ({punkt: {doba: GWh/d}}, {licznik pominiętych wierszy}). Tylko punkty z LNG_PUNKTY, kierunek entry,
    wskaźnik Physical Flow, doby (periodType day) zaczynające się o 04:00–07:00 (gaz: 06:00 czasu lokalnego operatora; Finlandia 05:00 CET), jednostka kWh/d. Wartości kilku operatorów tego samego punktu
    w tej samej dobie są sumowane; powtórzony wiersz tego samego operatora — wygrywa nowszy lastUpdateDateTime (wiersz z liczbą wygrywa z pustym).
    Odpowiedź bez operationalData (np. komunikat „No result found”) albo bez ani jednego wiersza punktu = błąd."""
    if not isinstance(j, dict):
        raise RuntimeError('nieznany kształt odpowiedzi')
    rows = j.get('operationalData')
    if not isinstance(rows, list):
        raise RuntimeError('brak wierszy: ' + str(j.get('message') or 'nieznany kształt odpowiedzi')[:80])
    pk = set(LNG_PUNKTY)
    O, bad = {}, {}
    for r in rows:
        if not isinstance(r, dict) or r.get('pointKey') not in pk:
            continue
        if r.get('directionKey') != 'entry' or r.get('indicator') != 'Physical Flow' or r.get('periodType') != 'day':
            continue
        if r.get('unit') != 'kWh/d':
            bad['jednostka'] = bad.get('jednostka', 0) + 1; continue
        m = re.match(r'^(\d{4}-\d{2}-\d{2})T0[4-7]:00:00[+-]\d{2}:?\d{2}$', str(r.get('periodFrom') or ''))   # początek doby gazowej 06:00 (Finlandia: 06:00 EET = 05:00 CET)
        if not m or _lng_d(m.group(1)) is None:
            bad['okres'] = bad.get('okres', 0) + 1; continue
        raw = r.get('value')
        v = _lng_wart(raw)
        if v is None and raw is not None and raw != '':
            bad['wartosc'] = bad.get('wartosc', 0) + 1   # ujemna, nie-liczba albo ponad LNG_PUNKT_MAX (pusta wartość to zwykły brak publikacji)
        key = (r['pointKey'], m.group(1), str(r.get('operatorKey') or '?'))
        lu = str(r.get('lastUpdateDateTime') or '')
        old = O.get(key)
        if old is None or (v is not None and old[0] is None) or ((v is None) == (old[0] is None) and lu > old[1]):
            O[key] = (v, lu)
    if not O:
        raise RuntimeError('brak wierszy punktów LNG w odpowiedzi')
    P = {}
    for (p, d, _op), (v, _lu) in O.items():
        if v is not None:
            P.setdefault(p, {})[d] = P.get(p, {}).get(d, 0.0) + v
    return P, bad


def lng_dni(P, od, do):
    """Doby od..do (włącznie) z P (parse_lng_dz; dane muszą sięgać 3 doby przed od) → ({doba: suma UE GWh/d} tylko doby kompletne, {doba: Świnoujście},
    {doba: {punkt: GWh/d}} tej samej doby). Doba kompletna: raportują wszystkie punkty, które miały wartość 2 i 3 doby wcześniej (punkt zastąpiony
    przez LNG_ALIAS jest spełniony, gdy raportuje zastępujący), co najmniej LNG_MIN_PKT punktów, suma w [LNG_UE_MIN, LNG_UE_MAX]."""
    a, b = _lng_d(od), _lng_d(do)
    ue, pl, pt = {}, {}, {}
    if a is None or b is None:
        return ue, pl, pt
    for i in range((b - a).days + 1):
        ds = (a + datetime.timedelta(days=i)).isoformat()
        rep = {p: dd[ds] for p, dd in P.items() if ds in dd}
        if LNG_PL in rep:
            pl[ds] = round(rep[LNG_PL], 1)
        for glowny, zast in LNG_ALIAS.items():
            if glowny in rep:
                for z in zast:
                    rep.pop(z, None)
        d2, d3 = _lng_przes(ds, -2), _lng_przes(ds, -3)
        ref = [p for p, dd in P.items() if d2 in dd and d3 in dd]
        brak = [p for p in ref if p not in rep and not any(p in zast and g in rep for g, zast in LNG_ALIAS.items())]
        if len(rep) >= LNG_MIN_PKT and not brak:
            tot = sum(rep.values())
            if LNG_UE_MIN <= tot <= LNG_UE_MAX:
                ue[ds] = round(tot, 1); pt[ds] = rep
    return ue, pl, pt


def lng_term(rep):
    """Punkty jednej doby {punkt: GWh/d} → [[nazwa, kraj, GWh/d]] malejąco, bez zer; punkty o tej samej nazwie (strefa Wilhelmshaven) scalone."""
    S = {}
    for p, v in rep.items():
        n, c = LNG_NAZWY.get(p, (p, ''))
        S[(n, c)] = S.get((n, c), 0.0) + v
    return [[n, c, round(v, 1)] for (n, c), v in sorted(S.items(), key=lambda kv: (-kv[1], kv[0])) if round(v, 1) > 0]


def lng_centyl(V, p):
    """Centyl p (0–100) listy liczb, interpolacja liniowa; pusta lista = None."""
    V = sorted(V)
    if not V:
        return None
    k = (len(V) - 1) * p / 100.0
    lo = int(math.floor(k)); hi = min(lo + 1, len(V) - 1)
    return V[lo] + (V[hi] - V[lo]) * (k - lo)


def lng_pasmo(H, dni):
    """Pasmo sezonowe dla dób `dni`: [doba, 10. centyl, mediana, 90. centyl] z wartości H ({doba: GWh/d}) tego samego dnia kalendarzowego ± LNG_PASMO_DNI
    w LNG_PASMO_LAT poprzednich latach; doba bez co najmniej LNG_PASMO_MIN wartości z co najmniej 2 lat — pominięta (nigdy zero)."""
    out = []
    for ds in dni:
        V, lata = [], set()
        for k in range(1, LNG_PASMO_LAT + 1):
            c = _lng_rok_wstecz(ds, k)
            for j in range(-LNG_PASMO_DNI, LNG_PASMO_DNI + 1):
                v = H.get(_lng_przes(c, j))
                if _lng_liczba(v):
                    V.append(v); lata.add(k)
        if len(V) >= LNG_PASMO_MIN and len(lata) >= 2:
            out.append([ds] + [round(lng_centyl(V, p), 1) for p in LNG_PASMO_P])
    return out


def _lng_szereg(H, do, n):
    """Ostatnie n dób kończące się w `do`: [[doba, wartość | None]] (doba bez wartości = None)."""
    return [[_lng_przes(do, -i), H.get(_lng_przes(do, -i))] for i in range(n - 1, -1, -1)]


def _lng_hist_z_pliku(h):
    """Pole hist pliku ({od, pl, ue} — listy po kolei od doby od) → ({doba: Świnoujście}, {doba: UE}); zły kształt = puste słowniki."""
    pl, ue = {}, {}
    d0 = _lng_d(h.get('od')) if isinstance(h, dict) else None
    if d0 is not None:
        for nm, D in (('pl', pl), ('ue', ue)):
            L = h.get(nm)
            for i, v in enumerate(L if isinstance(L, list) else []):
                if _lng_liczba(v) and v >= 0:
                    D[(d0 + datetime.timedelta(days=i)).isoformat()] = round(float(v), 1)
    return pl, ue


def _lng_hist_do_pliku(pl, ue):
    """({doba: Świnoujście}, {doba: UE}) → hist: ciągły szereg od najstarszej doby (None = brak)."""
    dni = sorted(set(pl) | set(ue))
    if not dni:
        return None
    a, b = _lng_d(dni[0]), _lng_d(dni[-1])
    n = (b - a).days + 1
    ds = [(a + datetime.timedelta(days=i)).isoformat() for i in range(n)]
    return {'od': dni[0], 'pl': [pl.get(d) for d in ds], 'ue': [ue.get(d) for d in ds]}


def lng_dz_czesc(pl, ue, term, bf, uw=None):
    """Część dz z historii: dwa wykresy (ostatnie LNG_WYKRES dób każdy kończący się na swojej ostatniej dobie z wartością), pasmo (tylko przy
    kompletnej historii), podział ostatniej pełnej doby UE na terminale, historia."""
    if not pl and not ue:
        raise RuntimeError('brak dób z wartościami')
    out = {'u': 'GWh/d', 'przel': LNG_GWH_MLN_M3, 'asof': max(pl) if pl else max(ue)}
    for nm, H in (('pl', pl), ('ue', ue)):
        if not H:
            continue
        last = max(H)
        e = {'asof': last, 'd': _lng_szereg(H, last, LNG_WYKRES)}
        if bf.get('gotowe'):
            pas = lng_pasmo(H, [x[0] for x in e['d']])
            if pas:
                e['pasmo'] = pas
        out[nm] = e
    if ue and term:
        d = max(ue)
        T = term.get(d)
        if T:
            out['term'] = {'d': d, 'r': T['r'], 'n': T['n']}   # r — terminale z dodatnią wysyłką, n — wszystkie punkty raportujące w tej dobie (także z zerem)
    out['lat'] = LNG_PASMO_LAT; out['hist'] = _lng_hist_do_pliku(pl, ue); out['bf'] = {'od': bf.get('od'), 'gotowe': bool(bf.get('gotowe'))}
    return out


# ---- Eurostat: import wg pochodzenia i zapasy ----
def _lng_ym(s):
    return s if isinstance(s, str) and re.match(r'^\d{4}-(0[1-9]|1[0-2])$', s) else None


def _lng_ym_przes(ym, k):
    y, m = int(ym[:4]), int(ym[5:7])
    t = y * 12 + (m - 1) + k
    return f'{t // 12:04d}-{t % 12 + 1:02d}'


def _lng_ym_od(now, k):
    """Miesiąc `k` miesięcy przed miesiącem chwili now ('RRRR-MM')."""
    return _lng_ym_przes(f'{now.year:04d}-{now.month:02d}', -k)


def parse_lng_skad(j):
    """Import LNG (G3200) wg kraju pochodzenia, TJ (GCV), UE27 i Polska → część skad. UE27: ostatni miesiąc z sumą (TOTAL), jego partnerzy > 0
    malejąco, ten sam miesiąc rok wcześniej, szereg sum; Polska: ostatni miesiąc z sumą, udział NSP („nieokreślone”), najwięksi partnerzy.
    Suma partnerów musi zgadzać się z sumą (±3%) — inaczej błąd (zmiana układu zbioru)."""
    vals, ids, _fl = parse_jsonstat(j)
    pos = {d: i for i, d in enumerate(ids)}
    for d in ('siec', 'partner', 'unit', 'geo', 'time'):
        if d not in pos:
            raise RuntimeError(f'brak wymiaru {d}')
    M = {}
    for lab, v in vals.items():
        if lab[pos['siec']] != 'G3200' or lab[pos['unit']] != 'TJ_GCV' or v < 0:
            continue
        g, p, t = lab[pos['geo']], lab[pos['partner']], lab[pos['time']]
        if g in ('EU27_2020', 'PL') and _lng_ym(t):
            M.setdefault(g, {}).setdefault(t, {})[p] = v
    out = {'u': 'TJ (ciepło spalania)'}
    for g, nm, lo, hi in (('EU27_2020', 'ue', 20000.0, 2000000.0), ('PL', 'pl', 100.0, 200000.0)):
        mm = {t: pp for t, pp in M.get(g, {}).items() if 'TOTAL' in pp}
        if not mm:
            if g == 'EU27_2020':
                raise RuntimeError('brak miesiąca z sumą UE27')
            continue
        t = max(mm)
        pp = mm[t]
        tot = pp['TOTAL']
        if not lo <= tot <= hi:
            raise RuntimeError(f'import {nm} {t}: suma {tot:.0f} TJ poza zakresem')
        reszta = {p: v for p, v in pp.items() if p != 'TOTAL'}
        if abs(sum(reszta.values()) - tot) > 0.03 * tot:
            raise RuntimeError(f'import {nm} {t}: suma partnerów {sum(reszta.values()):.0f} ≠ suma {tot:.0f} TJ')
        e = {'m': t, 'razem': round(tot, 1), 'k': [[p, round(v, 1)] for p, v in sorted(reszta.items(), key=lambda kv: (-kv[1], kv[0])) if v > 0][:40]}
        if g == 'EU27_2020':
            y = _lng_ym_przes(t, -12)
            if y in mm:
                yp = {p: v for p, v in mm[y].items() if p != 'TOTAL'}
                e['rok'] = {'m': y, 'razem': round(mm[y]['TOTAL'], 1), 'k': [[p, round(v, 1)] for p, v in sorted(yp.items(), key=lambda kv: (-kv[1], kv[0])) if v > 0][:40]}
        else:
            e['nsp'] = round(reszta.get('NSP', 0.0), 1)
        e['hist'] = [[m, round(mm[m]['TOTAL'], 1)] for m in sorted(mm)][-15:]
        out[nm] = e
    out['asof'] = out['ue']['m']
    return out


def parse_lng_zapasy(j):
    """Zapasy gazu na koniec miesiąca (stan roboczy na terytorium kraju, STKCL_NAT) → część zapasy: {kraj: {m: ostatni miesiąc z TJ, d: [[miesiąc, TJ,
    mln m³ | None]] (LNG_ZAP_MIES miesięcy), pasmo: [[miesiąc, najmniej, średnia, najwięcej]] z tego samego miesiąca w 5 poprzednich latach}}.
    mln m³ tylko, gdy TJ / mln m³ mieści się w 30–45 (inaczej None — nie zgadujemy). Brak miesiąca = brak wiersza, nigdy 0."""
    vals, ids, _fl = parse_jsonstat(j)
    pos = {d: i for i, d in enumerate(ids)}
    for d in ('stk_flow', 'unit', 'geo', 'time'):
        if d not in pos:
            raise RuntimeError(f'brak wymiaru {d}')
    S = {}
    for lab, v in vals.items():
        if lab[pos['stk_flow']] != 'STKCL_NAT' or v < 0:
            continue
        g, u, t = lab[pos['geo']], lab[pos['unit']], lab[pos['time']]
        if g in LNG_GEO and u in ('TJ_GCV', 'MIO_M3') and _lng_ym(t):
            S.setdefault(g, {}).setdefault(t, {})[u] = v
    k, gr = {}, {'EU27_2020': (100000.0, 5000000.0), 'DE': (20000.0, 1500000.0), 'PL': (5000.0, 500000.0)}
    for g in LNG_GEO:
        tj = {t: x['TJ_GCV'] for t, x in S.get(g, {}).items() if 'TJ_GCV' in x}
        if not tj:
            continue
        m = max(tj)
        if not gr[g][0] <= tj[m] <= gr[g][1]:
            raise RuntimeError(f'zapasy {g} {m}: {tj[m]:.0f} TJ poza zakresem')

        def m3(t):
            x = S[g][t]
            return round(x['MIO_M3'], 1) if 'MIO_M3' in x and 'TJ_GCV' in x and x['MIO_M3'] > 0 and 30 <= x['TJ_GCV'] / x['MIO_M3'] <= 45 else None
        ms = sorted(tj)[-LNG_ZAP_MIES:]
        e = {'m': m, 'd': [[t, round(tj[t], 1), m3(t)] for t in ms]}
        pas = []
        for t in ms:
            B = [tj[_lng_ym_przes(t, -12 * i)] for i in range(1, LNG_ZAP_PASMO_LAT + 1) if _lng_ym_przes(t, -12 * i) in tj]
            if len(B) >= 3:
                pas.append([t, round(min(B), 1), round(sum(B) / len(B), 1), round(max(B), 1)])
        if pas:
            e['pasmo'] = pas
        k[g] = e
    if 'EU27_2020' not in k:
        raise RuntimeError('brak zapasów UE27')
    return {'u': 'TJ (ciepło spalania) i mln m³', 'asof': k['EU27_2020']['m'], 'lat': LNG_ZAP_PASMO_LAT, 'k': k}


# ---- terminy publikacji (UTC) ----
def _lng_oczek(now):
    """(doba Świnoujścia, doba UE) oczekiwane w pliku w chwili now: Świnoujście publikuje wynik ok. 05:03–06:04 UTC następnego dnia, wszyscy operatorzy
    UE do ok. 17:56 UTC (11.10.2026: lastUpdateDateTime Amber Grid 19:56 czasu polskiego); zapasy czasu 6 h 30 min i 18 h 30 min."""
    pl = (now - datetime.timedelta(hours=6, minutes=30)).date() - datetime.timedelta(days=1)
    ue = (now - datetime.timedelta(hours=18, minutes=30)).date() - datetime.timedelta(days=1)
    return pl.isoformat(), ue.isoformat()


def _lng_slot(now):
    """Ostatnia chwila LNG_SLOT_UTC (21:30 UTC) nie późniejsza niż now."""
    t = datetime.datetime(now.year, now.month, now.day, LNG_SLOT_UTC[0], LNG_SLOT_UTC[1], tzinfo=datetime.timezone.utc)
    return t if t <= now else t - datetime.timedelta(days=1)


def _lng_termin(asof, exp, h, m):
    """Chwila publikacji pierwszej brakującej doby (po ostatniej dobie asof): asof + 2 dni o h:m UTC; brak asof — chwila publikacji doby oczekiwanej exp."""
    d = _lng_d(asof) if isinstance(asof, str) else None
    base = d + datetime.timedelta(days=1) if d else datetime.date.fromisoformat(exp)
    return datetime.datetime(base.year, base.month, base.day, h, m, tzinfo=datetime.timezone.utc) + datetime.timedelta(days=1)


def _lng_due(src, z, now, part):
    """(czy pobrać źródło w tym przebiegu, czy pilnie). dz: pierwsze pobranie — co godzinę do skutku; oczekiwane doby jeszcze nie przyszły — co
    LNG_CZESTO_MIN min (gdy brakująca doba jest spóźniona o ponad LNG_ZALEGLE_H h — co 6 h), pilnie; poza tym co LNG_RZADKO_MIN min (poprawki wstecz),
    niepilnie. skad, zapasy: pierwsze pobranie pilnie, potem raz na dobę po 21:30 UTC; po błędzie najwcześniej po 60 min."""
    at, tr = _su_min(now, z.get('at')), _su_min(now, z.get('try'))
    if src == 'dz':
        if at == float('inf'):
            return tr >= 60, True
        ep, eu = _lng_oczek(now)
        pl = (part.get('pl') or {}).get('asof') if isinstance(part, dict) else None
        ue = (part.get('ue') or {}).get('asof') if isinstance(part, dict) else None
        brak = []
        if str(pl or '') < ep:
            brak.append(_lng_termin(pl, ep, 6, 30))
        if str(ue or '') < eu:
            brak.append(_lng_termin(ue, eu, 18, 30))
        if brak:
            return tr >= (LNG_CZESTO_MIN if (now - min(brak)).total_seconds() <= LNG_ZALEGLE_H * 3600 else 360), True
        return at >= LNG_RZADKO_MIN and tr >= 60, False
    if at == float('inf'):
        return tr >= 60, True
    t_at = _aw_t(z.get('at'))
    return (t_at is None or t_at < _lng_slot(now)) and tr >= 60, False


def _lng_next(src, part, now):
    """Najbliższa spodziewana zmiana źródła (ISO, UTC); termin w przeszłości = zaległa. dz: pierwsza brakująca doba (Świnoujście 06:30, UE 18:30 UTC
    następnego dnia po niej), gdy nic nie brakuje — jutro 06:30."""
    if src == 'dz':
        ep, eu = _lng_oczek(now)
        pl = (part.get('pl') or {}).get('asof') if isinstance(part, dict) else None
        ue = (part.get('ue') or {}).get('asof') if isinstance(part, dict) else None
        brak = []
        if str(pl or '') < ep:
            brak.append(_lng_termin(pl, ep, 6, 30))
        if str(ue or '') < eu:
            brak.append(_lng_termin(ue, eu, 18, 30))
        if brak:
            return min(brak).isoformat()
        t = datetime.datetime(now.year, now.month, now.day, 6, 30, tzinfo=datetime.timezone.utc)
        return (t if t > now else t + datetime.timedelta(days=1)).isoformat()
    return (_lng_slot(now) + datetime.timedelta(days=1)).isoformat()


# ---- pobrania ----
def _lng_pobierz(url, timeout, maks=None):
    """GET z nagłówkami zbieracza i Accept-Encoding: gzip → bajty po rozpakowaniu (limit LNG_GZ_MAKS na łączu i maks po rozpakowaniu). Czytanie
    kawałkami z terminem (limit czasu całego pobierania, nie tylko pojedynczego odczytu)."""
    kon = time.monotonic() + timeout
    buf = bytearray()
    with _otworz(url, {'Accept-Encoding': 'gzip', 'Accept': 'application/json'}, timeout) as r:
        while chunk := r.read(1 << 16):
            buf += chunk
            if len(buf) > LNG_GZ_MAKS:
                raise RuntimeError('odpowiedź większa niż limit')
            if time.monotonic() > kon:
                raise TimeoutError('limit czasu pobierania')
    return rwa_gunzip(bytes(buf), maks or LNG_MAKS_B['dz'])


def _lng_get(ctx, src, url):
    """Jedno zapytanie z limitem źródła, nie dłuższym niż reszta budżetu budowniczego (reszta < 5 s = błąd; ponowienie później)."""
    lim = LNG_LIMIT_S[src]
    if ctx.get('t0') is not None and ctx.get('budzet') is not None:
        left = ctx['budzet'] - (time.monotonic() - ctx['t0'])
        if left < 5:
            raise RuntimeError('budżet czasu budowniczego wyczerpany')
        lim = min(lim, round(left, 1))
    maks = LNG_MAKS_B[src]
    b = ctx['fetch'](url, lim, maks)
    if len(b) > maks:
        raise RuntimeError(f'odpowiedź większa niż {maks} B (limit)')
    return b


def _lng_dz_url(od, do):
    return f"{LNG_ENTSOG}{','.join(LNG_PUNKTY)}&from={od}&to={do}&periodType=day&timezone=CET&limit=-1&directionKey=entry"


def _lng_dz_okno(ctx, od, do):
    """Pobranie [od − 3 doby, do] i przeliczenie dób od..do → (UE, Świnoujście, punkty doby, {licznik pominiętych})."""
    P, bad = parse_lng_dz(json.loads(_lng_get(ctx, 'dz', _lng_dz_url(_lng_przes(od, -3), do))))
    ue, pl, pt = lng_dni(P, od, do)
    return ue, pl, pt, P, bad


def _lng_bf_krok(ctx, H_pl, H_ue, st):
    """Jedno żądanie historii wstecz: [max(LNG_START, od − LNG_CHUNK), od − 1], gdzie od = najstarsza dotąd pobrana doba. Zwraca True, gdy zapisano."""
    bf = st.setdefault('bf', {})
    od = bf.get('od')
    if bf.get('gotowe') or not _lng_d(od):
        return False
    a = max(LNG_START, _lng_przes(od, -LNG_CHUNK))
    b = _lng_przes(od, -1)
    ue, pl, _pt, _P, bad = _lng_dz_okno(ctx, a, b)
    H_ue.update(ue); H_pl.update(pl)
    bf['od'] = a
    if a <= LNG_START:
        bf['gotowe'] = True
    if bad:
        ctx['uwagi'].append('dz historia: pominięte wiersze ' + ', '.join(f'{k} {v}' for k, v in sorted(bad.items())))
    return True


def _lng_pobierz_dz(ctx):
    now = ctx['now']
    prev = ctx['prev'].get('dz') if isinstance(ctx['prev'].get('dz'), dict) else {}
    H_pl, H_ue = _lng_hist_z_pliku(prev.get('hist'))
    ep, _eu = _lng_oczek(now)
    od = _lng_przes(ep, -(LNG_OKNO_DNI - 1))
    ue, pl, pt, P, bad = _lng_dz_okno(ctx, od, ep)
    if not ue and not pl:
        raise RuntimeError('brak dób z wartościami w oknie')
    H_ue.update(ue); H_pl.update(pl)
    if bad:
        ctx['uwagi'].append('dz: pominięte wiersze ' + ', '.join(f'{k} {v}' for k, v in sorted(bad.items())))
    bf = ctx['st'].setdefault('bf', {})
    if not _lng_d(bf.get('od')) and not bf.get('gotowe'):
        bf['od'] = od   # start historii: najstarsza doba pierwszego okna
    term = {d: {'r': lng_term(pt[d]), 'n': len(pt[d])} for d in pt if ue.get(d) is not None}
    if not term and isinstance(prev.get('term'), dict):
        term = {prev['term']['d']: {'r': prev['term']['r'], 'n': prev['term'].get('n', len(prev['term']['r']))}}
    ctx['dz_hist'] = (H_pl, H_ue, term)
    part = lng_dz_czesc(H_pl, H_ue, term, bf)
    ctx['parts']['dz'] = part
    return part['asof']


def _lng_pobierz_skad(ctx):
    now = ctx['now']
    url = f"{LNG_ESTAT}nrg_ti_gasm?format=JSON&lang=EN&geo=EU27_2020&geo=PL&siec=G3200&unit=TJ_GCV&sinceTimePeriod={_lng_ym_od(now, LNG_SK_MIES)}"
    part = parse_lng_skad(json.loads(_lng_get(ctx, 'skad', url)))
    ctx['parts']['skad'] = part
    return part['asof']


def _lng_pobierz_zapasy(ctx):
    url = (f"{LNG_ESTAT}nrg_stk_gasm?format=JSON&lang=EN&geo=EU27_2020&geo=DE&geo=PL&siec=G3000&stk_flow=STKCL_NAT&unit=TJ_GCV&unit=MIO_M3"
           f"&sinceTimePeriod={_lng_ym_od(ctx['now'], LNG_ZAP_MIES + 12 * LNG_ZAP_PASMO_LAT + 3)}")
    part = parse_lng_zapasy(json.loads(_lng_get(ctx, 'zapasy', url)))
    ctx['parts']['zapasy'] = part
    return part['asof']


LNG_POBIERZ = {'dz': _lng_pobierz_dz, 'skad': _lng_pobierz_skad, 'zapasy': _lng_pobierz_zapasy}


def build_lng(prev=None, now=None, fetch=None, budzet_s=None, run_t0=None):
    """v340: data/lng.json. Każde źródło z własną bramką (_lng_due) i budżetem czasu; źródło z błędem — poprzednia część z datą (ok False, krótki
    zamaskowany błąd err); część bez próby — 'cached' (z danymi) albo False (jeszcze nie pobrana). Plik innej wersji = start od zera. Historia
    (dz) dobierana wstecz po jednym żądaniu w przebiegu (najwyżej co LNG_BF_ODSTEP_MIN min, nie w długim przebiegu); jej błąd to notatka, nie błąd części."""
    now = now or _now_utc()
    now_iso = now.replace(microsecond=0).isoformat()
    prev = prev if isinstance(prev, dict) and prev.get('v') == LNG_V else {}
    st = json.loads(json.dumps(prev.get('st'))) if isinstance(prev.get('st'), dict) else {}
    ctx = {'now': now, 'bledy': [], 'uwagi': [], 'parts': {}, 'prev': prev, 'st': st, 't0': time.monotonic(),
           'budzet': LNG_BUDZET_S if budzet_s is None else budzet_s,
           'fetch': fetch or (lambda url, timeout, maks=None: _lng_pobierz(url, timeout, maks))}
    late = run_t0 is not None and time.monotonic() - run_t0 > BACK_LATE
    proby, zle, pominiete = {p: 0 for p in LNG_PARTS}, {}, []
    for src in LNG_PARTS:
        z = st.setdefault(src, {})
        due, pilne = _lng_due(src, z, now, prev.get(src))
        if not due:
            continue
        if late and not pilne:
            pominiete.append(f'{src} (długi przebieg)'); continue
        if time.monotonic() - ctx['t0'] + LNG_LIMIT_S[src] > ctx['budzet']:
            pominiete.append(f'{src} (budżet czasu)'); continue
        z['try'] = now_iso
        proby[src] += 1
        try:
            asof = LNG_POBIERZ[src](ctx)
        except Exception as e:
            msg = mask(f'{src}: {e}')[:160]
            z['err'] = msg; zle.setdefault(src, []).append(msg)
            continue
        z['at'] = now_iso; z['asof'] = asof; z.pop('err', None)
    # historia wstecz (po oknie bieżącym; tylko gdy jest od czego zacząć)
    bf = st.setdefault('bf', {})
    wstecz = ctx.get('dz_hist')
    dz_prev = prev.get('dz') if isinstance(prev.get('dz'), dict) else None
    if (dz_prev or wstecz) and not bf.get('gotowe') and _lng_d(bf.get('od')) and not late and not zle.get('dz') \
            and _su_min(now, bf.get('try')) >= LNG_BF_ODSTEP_MIN and time.monotonic() - ctx['t0'] + LNG_LIMIT_S['dz'] + 5 <= ctx['budzet']:
        if wstecz:
            H_pl, H_ue, term = wstecz
        else:
            H_pl, H_ue = _lng_hist_z_pliku(dz_prev.get('hist'))
            term = ({dz_prev['term']['d']: {'r': dz_prev['term']['r'], 'n': dz_prev['term'].get('n', len(dz_prev['term']['r']))}}
                    if isinstance(dz_prev.get('term'), dict) else {})
        bf['try'] = now_iso
        try:
            if _lng_bf_krok(ctx, H_pl, H_ue, st):
                ctx['parts']['dz'] = lng_dz_czesc(H_pl, H_ue, term, bf)
        except Exception as e:
            ctx['uwagi'].append(mask(f'dz historia od {bf.get("od")}: {e}')[:160])
    out = {'v': LNG_V, 'at': None, 'src': 'CapitalFlowAI — gaz i LNG (kody źródeł z: dz, skad, zapasy — pełne nazwy na stronie Źródła)'}
    pat = dict(prev.get('part_at') or {}) if isinstance(prev.get('part_at'), dict) else {}
    perr = dict(prev.get('err') or {}) if isinstance(prev.get('err'), dict) else {}
    ok = {}
    for p in LNG_PARTS:
        if p in ctx['parts']:
            out[p] = ctx['parts'][p]
            if proby[p]:
                pat[p] = now_iso
        elif isinstance(prev.get(p), dict):
            out[p] = prev[p]
        if zle.get(p):
            ok[p] = False; perr[p] = '; '.join(zle[p])[:240]
        elif proby[p]:
            ok[p] = True; perr.pop(p, None)
        else:
            ok[p] = False if (perr.get(p) or not isinstance(out.get(p), dict)) else 'cached'   # błąd ostatniej próby zostaje widoczny do udanego pobrania
            if not isinstance(out.get(p), dict) and p not in perr:
                perr[p] = 'brak danych (źródło jeszcze nie pobrane)'
    out['part_at'] = {p: pat[p] for p in LNG_PARTS if pat.get(p) and isinstance(out.get(p), dict)}
    out['at'] = max(out['part_at'].values()) if out['part_at'] else (prev.get('at') or now_iso)
    out.update({'ok': ok, 'err': {p: perr[p] for p in LNG_PARTS if perr.get(p)},
                'next': {p: _lng_next(p, out.get(p), now) for p in LNG_PARTS}, 'st': st})
    for x in ctx['uwagi']:
        META['notes'].append(mask('gaz i LNG: ' + x)[:200])
    for p in LNG_PARTS:
        for x in zle.get(p, []):
            META['errors'].append(mask('surowce (gaz i LNG) ' + x)[:200])
    if pominiete:
        META['notes'].append('gaz i LNG: pominięte w tym przebiegu — ' + ', '.join(pominiete))
    return out


# ===================== v353: ROSJA — data/rosja.json (GLOBAL, karta regionu „Rosja”; zadanie v353) =====================
# Decyzja właściciela 11.10: wszystkie DARMOWE i LEGALNE dane o Rosji. Mieszka w Niemczech (sankcje UE i USA), więc BEZ giełdy moskiewskiej i podmiotów
# z list sankcyjnych (jej instytucje rozliczeniowe i depozytowe, bank centralny Rosji bezpośrednio) — wyłącznie otwarte źródła MIĘDZYNARODOWE, bez klucza:
#   ue   — handel UE27 z Rosją, miesięcznie (urzędowa statystyka UE, wszystkie towary; licencja CC BY 4.0): import, eksport, saldo, ten sam miesiąc rok
#          wcześniej, sumy 12 miesięcy i średnia miesięczna z 2021 r. (przed 2022); wartości w mln EUR, 1 zapytanie ok. 8 KB;
#   bis  — należności banków świata wobec Rosji, kwartalnie (statystyki lokalizacyjne banków; wszystkie kraje raportujące razem + 6 największych): wartość
#          jak publikowana (mln USD) i zmiany po korekcie PRZERW w szeregu (kwartał z przerwą liczony od wartości sprzed przerwy), 1 zapytanie ok. 40 KB;
#   imts — handel Rosji wg partnerów jako KONTROLA, miesięcznie (dwustronny handel towarami, dane zgłoszone przez Rosję; MFW): świat, UE, Chiny, Indie,
#          Turcja — eksport (FOB), import (CIF), saldo; mld USD; różni się od liczb UE (kraj pochodzenia a kraj wysyłki, CIF a FOB, USD a EUR);
#   rez  — rezerwy walutowe Rosji (MFW, tabela płynności międzynarodowej; mld USD): razem, bez złota, waluty obce, złoto = razem − bez złota (wyliczenie);
#          Rosja publikuje tam z dużym opóźnieniem (10.10.2026: do 2025-11) — data i wiek zawsze przy liczbie;
#   zloto — złoto banku centralnego w tonach: kopia z pliku surowce.json z tego przebiegu (MFW, tabela IRFCL; BEZ nowych zapytań), data danych w polu asof.
# Stopa banku Rosji (BIS), kurs efektywny i bilans płatniczy strona ma już w kartach regionu — tu ich nie powtarzamy.
# Bramki: ue — gdy spodziewany miesiąc (publikacja ok. 15. dnia, dane sprzed 2 miesięcy: 15.09.2026 lipiec) jeszcze nie przyszedł — co godzinę, poza tym co 12 h
# (poprawki wstecz); bis, imts, rez — raz na dobę; po błędzie najwcześniej po 60 min; część z błędem zostaje z datą i z krótkim zamaskowanym opisem (err).
# Budżet czasu budowniczego RU_BUDZET_S s; brak = None, nigdy 0.
RU_V = 1
RU_PARTS = ('ue', 'bis', 'imts', 'rez')
RU_ESTAT = ('https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/ext_st_eu27_2020sitc?format=JSON&lang=EN&partner=RU&sitc06=TOTAL'
            '&freq=M&geo=EU27_2020&indic_et=TRD_VAL&sinceTimePeriod=2021-01')
RU_IMF = 'https://api.imf.org/external/sdmx/3.0/data/dataflow/IMF.STA/'
RU_BIS_URL = 'https://stats.bis.org/api/v2/data/dataflow/BIS/WS_LBS_D_PUB/1.0/Q.S.C.A.TO1.A.5J.A...RU.N?lastNObservations=9&format=csv'
RU_IMTS_PART = ('G001', 'G998', 'CHN', 'IND', 'TUR')    # świat, Unia Europejska, Chiny, Indie, Turcja (G998 = grupa „UE” w tabeli krajów MFW)
RU_IMTS_URL = RU_IMF + 'IMTS/+/RUS.*.' + '+'.join(RU_IMTS_PART) + '.M?lastNObservations=14'
RU_IL_URL = RU_IMF + 'IL/+/RUS.TRGMV_REVS+RXF11_REVS+RXF11FX_REVS.USD.M?lastNObservations=13'
RU_URL = {'ue': RU_ESTAT, 'bis': RU_BIS_URL, 'imts': RU_IMTS_URL, 'rez': RU_IL_URL}
RU_LIMIT_S = {'ue': 25, 'bis': 40, 'imts': 40, 'rez': 25}
RU_MAKS_B = {'ue': 400_000, 'bis': 800_000, 'imts': 400_000, 'rez': 100_000}
RU_BUDZET_S = 110
RU_UE_GODZ, RU_RZADKO_MIN, RU_DOBA_MIN, RU_PO_BLEDZIE_MIN = 12, 720, 1440, 60
RU_UE_OD = '2021-01'
RU_UE_H = 26            # miesięcy szeregu w pliku (2 lata + zapas)
RU_BIS_TOP = 6
_RU_MIES = re.compile(r'^\d{4}-(0[1-9]|1[0-2])$')
_RU_KW = re.compile(r'^\d{4}-Q[1-4]$')


def _ru_ok(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and v == v and v not in (float('inf'), float('-inf'))


def _ru_kw_przes(q, k):
    """'2026-Q1' przesunięty o k kwartałów."""
    t = int(q[:4]) * 4 + int(q[6]) - 1 + k
    return f'{t // 4:04d}-Q{t % 4 + 1}'


def parse_ru_ue(j):
    """Eurostat (ext_st_eu27_2020sitc, partner RU, wszystkie towary, UE27, wartość w mln EUR) → część ue. Miesiąc liczy się, gdy ma import I eksport;
    saldo z pliku (BAL_RT) musi zgadzać się z eksport − import (±2 mln EUR), inaczej błąd (zmiana układu zbioru). Sumy 12 miesięcy tylko z kompletu
    12 kolejnych miesięcy; średnia 2021 tylko z 12 miesięcy 2021 — brak = None."""
    vals, ids, _fl = parse_jsonstat(j)
    pos = {d: i for i, d in enumerate(ids)}
    for d in ('stk_flow', 'indic_et', 'time', 'partner', 'geo'):
        if d not in pos:
            raise RuntimeError(f'brak wymiaru {d}')
    M = {}
    for lab, v in vals.items():
        if lab[pos['indic_et']] != 'TRD_VAL' or lab[pos['partner']] != 'RU' or lab[pos['geo']] != 'EU27_2020':
            continue
        t, f = lab[pos['time']], lab[pos['stk_flow']]
        if _RU_MIES.match(t) and f in ('IMP', 'EXP', 'BAL_RT') and _ru_ok(v):
            M.setdefault(t, {})[f] = float(v)
    B = {t: (x['IMP'], x['EXP']) for t, x in M.items() if 'IMP' in x and 'EXP' in x}
    if len(B) < 14:
        raise RuntimeError('za mało miesięcy z importem i eksportem')
    asof = max(B)
    imp, exp = B[asof]
    if not (100.0 <= imp <= 100000.0 and 100.0 <= exp <= 100000.0):
        raise RuntimeError(f'import/eksport {asof} poza zakresem ({imp:.0f}/{exp:.0f} mln EUR)')
    bal = M[asof].get('BAL_RT')
    if bal is not None and abs(bal - (exp - imp)) > 2.0:
        raise RuntimeError(f'saldo {bal:.1f} ≠ eksport − import {exp - imp:.1f} mln EUR')

    def suma(od, n, k):
        mm = [_imf_month_add(od, i) for i in range(n)]
        return round(sum(B[m][k] for m in mm), 1) if all(m in B for m in mm) else None
    r1 = lambda v: None if v is None else round(v, 1)   # noqa: E731
    rok = B.get(_imf_month_add(asof, -12))
    s21 = [suma(RU_UE_OD, 12, 0), suma(RU_UE_OD, 12, 1)]
    return {'asof': asof, 'u': 'mln EUR', 'imp': r1(imp), 'exp': r1(exp), 'bal': r1(exp - imp),
            'imp_r': r1(rok[0]) if rok else None, 'exp_r': r1(rok[1]) if rok else None,
            'imp12': suma(_imf_month_add(asof, -11), 12, 0), 'exp12': suma(_imf_month_add(asof, -11), 12, 1),
            'imp12_p': suma(_imf_month_add(asof, -23), 12, 0), 'exp12_p': suma(_imf_month_add(asof, -23), 12, 1),
            'imp21': None if s21[0] is None else round(s21[0] / 12, 1), 'exp21': None if s21[1] is None else round(s21[1] / 12, 1),
            'h': [[m, r1(B[m][0]), r1(B[m][1])] for m in sorted(B)][-RU_UE_H:]}


def parse_ru_bis(text):
    """BIS, statystyki lokalizacyjne (LBS), należności (C) wszystkich banków (A) wobec Rosji (RU), wszystkie sektory (N), mln USD → część bis.
    razem = suma wszystkich krajów raportujących (5A; obejmuje kraje, których dane dwustronne są poufne — jest większa niż suma wierszy krajów);
    zmiany kwartał do kwartału po korekcie przerw w szeregu (kwartał ze statusem B liczony od wartości sprzed przerwy, jeśli ją podano), zmiana
    4 kwartałów = iloczyn czterech takich zmian (None, gdy któregoś brak). top = kraje z wartością w ostatnim kwartale (bez NaN), malejąco."""
    rd = csv.DictReader(io.StringIO(text))
    need = {'L_MEASURE', 'L_POSITION', 'L_REP_CTY', 'L_CP_SECTOR', 'L_CP_COUNTRY', 'TIME_PERIOD', 'OBS_VALUE', 'OBS_STATUS', 'UNIT_MULT'}
    if not need <= set(rd.fieldnames or ()):
        raise RuntimeError('brak kolumn ' + ', '.join(sorted(need - set(rd.fieldnames or ())))[:120])
    S = {}
    for r in rd:
        if r['L_CP_COUNTRY'] != 'RU' or r['L_CP_SECTOR'] != 'N' or r['L_MEASURE'] != 'S' or r['L_POSITION'] != 'C' or r['UNIT_MULT'] != '6':
            continue
        q = r['TIME_PERIOD']
        v = _num(r['OBS_VALUE'])
        if not _RU_KW.match(q) or v is None or not _ru_ok(v) or v < 0:
            continue
        pre = _num(r.get('OBS_PRE_BREAK') or '')
        S.setdefault(r['L_REP_CTY'], {})[q] = (v, r['OBS_STATUS'] == 'B', pre if pre is not None and _ru_ok(pre) else None)
    A = S.get('5A')
    if not A or len(A) < 5:
        raise RuntimeError('brak szeregu sumy wszystkich krajów raportujących (5A)')
    qs = sorted(A)
    asof = qs[-1]
    if any(_ru_kw_przes(qs[i], 1) != qs[i + 1] for i in range(len(qs) - 1)):
        raise RuntimeError('kwartały sumy nie są kolejne')
    if not 500.0 <= A[asof][0] <= 500000.0:
        raise RuntimeError(f'suma {asof} poza zakresem ({A[asof][0]:.0f} mln USD)')

    def zm(q):   # zmiana kwartał do kwartału po korekcie przerwy: ułamek albo None
        p = _ru_kw_przes(q, -1)
        if q not in A or p not in A or not A[p][0]:
            return None
        v, brk, pre = A[q]
        return (pre if brk and pre is not None else v) / A[p][0] - 1
    zk = zm(asof)
    zs = [zm(q) for q in qs[1:]]
    chain = lambda L: None if not L or any(x is None for x in L) else round((math.prod(1 + x for x in L) - 1) * 100, 1)   # noqa: E731
    top = []
    for c, ser in S.items():
        if c != '5A' and asof in ser:
            ya = ser.get(_ru_kw_przes(asof, -4))
            top.append([c, round(ser[asof][0], 1), None if ya is None else round(ya[0], 1)])
    top.sort(key=lambda x: (-x[1], x[0]))
    return {'asof': asof, 'u': 'mln USD', 'razem': [[q, round(A[q][0], 1), 1 if A[q][1] else 0] for q in qs],
            'zm_k': None if zk is None else round(zk * 100, 1), 'zm_r': chain(zs[-4:]) if len(zs) >= 4 else None,
            'zm_od': chain(zs), 'od': qs[0], 'brk': 1 if A[asof][1] else 0,
            'top': top[:RU_BIS_TOP], 'n': len(top)}


def parse_ru_imts(j):
    """MFW IMTS (dwustronny handel towarami; Rosja jako zgłaszający) → część imts: dla świata, UE, Chin, Indii i Turcji w ostatnim miesiącu, w którym
    świat ma i eksport (FOB), i import (CIF): x eksport Rosji, m import Rosji, b saldo (x − m; zgodne z wskaźnikiem salda ±0,02 mld USD), x12 / m12
    — ten sam miesiąc rok wcześniej, h — 13 miesięcy [miesiąc, x, m] (brak = None). Partner bez obu wartości w tym miesiącu pominięty (strona: „—”);
    brak świata albo UE = błąd."""
    ser = parse_imf_sdmx(j)
    S = lambda ind, cp: dict(ser.get(('RUS', ind, cp, 'M')) or [])   # noqa: E731
    mld = lambda v: round(v / 1e9, 3)   # noqa: E731
    wx, wm = S('XG_FOB_USD', 'G001'), S('MG_CIF_USD', 'G001')
    wsp = sorted(set(wx) & set(wm))
    if not wsp:
        raise RuntimeError('brak miesiąca z eksportem i importem świata')
    asof = wsp[-1]
    if not 5e9 <= wx[asof] <= 400e9:
        raise RuntimeError(f'eksport Rosji {asof} poza zakresem ({wx[asof] / 1e9:.1f} mld USD)')
    P = {}
    for cp in RU_IMTS_PART:
        x, m, tb = S('XG_FOB_USD', cp), S('MG_CIF_USD', cp), S('TBG_USD', cp)
        if asof not in x or asof not in m:
            continue
        b = mld(x[asof] - m[asof])
        if asof in tb and abs(mld(tb[asof]) - b) > 0.02:
            raise RuntimeError(f'saldo {cp} {asof} ≠ eksport − import')
        y = _imf_month_add(asof, -12)
        P[cp] = {'x': mld(x[asof]), 'm': mld(m[asof]), 'b': b,
                 'x12': mld(x[y]) if y in x else None, 'm12': mld(m[y]) if y in m else None,
                 'h': [[ym, mld(x[ym]) if ym in x else None, mld(m[ym]) if ym in m else None]
                       for ym in (_imf_month_add(asof, i) for i in range(-12, 1))]}
    if 'G001' not in P or 'G998' not in P:
        raise RuntimeError('brak świata albo UE w ostatnim miesiącu')
    return {'asof': asof, 'u': 'mld USD', 'p': P}


def parse_ru_rez(j):
    """MFW IL, Rosja: rezerwy razem ze złotem po cenie rynkowej (TRGMV), bez złota (RXF11) i waluty obce (RXF11FX), mld USD, ostatni miesiąc z sumą.
    zloto_war = razem − bez złota (wyliczenie strony; wartość rynkowa złota). Suma poza [100, 3000] mld USD = błąd (skala)."""
    ser = parse_imf_sdmx(j)
    g = lambda code: dict(ser.get(('RUS', code, 'USD', 'M')) or [])   # noqa: E731
    tot, exg, fx = g('TRGMV_REVS'), g('RXF11_REVS'), g('RXF11FX_REVS')
    if not tot:
        raise RuntimeError('brak rezerw razem')
    asof = max(tot)
    if not 100e9 <= tot[asof] <= 3000e9:
        raise RuntimeError(f'rezerwy {asof} poza zakresem ({tot[asof] / 1e9:.0f} mld USD)')
    r1 = lambda v: None if v is None else round(v / 1e9, 1)   # noqa: E731
    p1, p12, e = tot.get(_imf_month_add(asof, -1)), tot.get(_imf_month_add(asof, -12)), exg.get(asof)
    return {'asof': asof, 'u': 'mld USD', 'razem': r1(tot[asof]), 'bez_zlota': r1(e), 'waluty': r1(fx.get(asof)),
            'zloto_war': None if e is None else r1(tot[asof] - e),
            'd1m': None if p1 is None else r1(tot[asof] - p1), 'd12m': None if p12 is None else r1(tot[asof] - p12)}


def ru_zloto(su):
    """Złoto banku centralnego Rosji w tonach z pliku surowce.json (banki.kr.RU.d, szereg miesięczny) → {asof, t, m1, m12} albo None. Zmiany liczone
    z szeregu: miesiąc i 12 miesięcy wcześniej (brak miesiąca = None). Bez zapytań."""
    try:
        d = su['banki']['kr']['RU']['d']
        D = {r[0]: float(r[1]) for r in d if isinstance(r, list) and len(r) >= 2 and isinstance(r[0], str) and _RU_MIES.match(r[0]) and _ru_ok(r[1])}
    except (KeyError, TypeError, IndexError, ValueError):
        return None
    if not D:
        return None
    a = max(D)
    if not 100.0 <= D[a] <= 20000.0:
        return None
    dm = lambda k: round(D[a] - D[_imf_month_add(a, k)], 1) if _imf_month_add(a, k) in D else None   # noqa: E731
    return {'asof': a, 't': round(D[a], 1), 'm1': dm(-1), 'm12': dm(-12)}


def _ru_oczek_ue(now):
    """Miesiąc, który powinien już być w Eurostacie: publikacja ok. 15. dnia (15.09.2026 — lipiec), więc od 16. dnia miesiąca M — miesiąc M−2, wcześniej M−3."""
    m = now.year * 12 + now.month - 1 - (2 if now.day >= 16 else 3)
    return f'{m // 12:04d}-{m % 12 + 1:02d}'


def _ru_due(src, z, now, part):
    """Czy pobrać źródło w tym przebiegu (patrz opis bloku)."""
    at, tr = _su_min(now, z.get('at')), _su_min(now, z.get('try'))
    if tr < RU_PO_BLEDZIE_MIN:
        return False
    if at == float('inf'):
        return True
    if src == 'ue':
        asof = part.get('asof') if isinstance(part, dict) else None
        return str(asof or '') < _ru_oczek_ue(now) or at >= RU_RZADKO_MIN
    return at >= RU_DOBA_MIN


def _ru_next(src, z, part, now):
    """Spodziewana następna zmiana źródła (ISO UTC): ue — gdy spodziewany miesiąc nie przyszedł: za godzinę od ostatniej próby, inaczej 12 h od pobrania."""
    t = _aw_t(z.get('at')) or now
    if src == 'ue' and str((part or {}).get('asof') or '') < _ru_oczek_ue(now):
        t = _aw_t(z.get('try')) or t
        return (t + datetime.timedelta(minutes=RU_PO_BLEDZIE_MIN)).isoformat()
    return (t + datetime.timedelta(minutes=RU_RZADKO_MIN if src == 'ue' else RU_DOBA_MIN)).isoformat()


def _ru_pobierz(url, timeout, maks=None):
    """GET z identyfikatorem zbieracza; BIS — CSV, MFW — JSON; odpowiedź dłuższa niż maks = błąd."""
    h = {'Accept': 'text/csv'} if 'stats.bis.org' in url else {'Accept': 'application/json'}
    return get_bytes_maks(url, h, timeout, maks)


def build_rosja(prev=None, now=None, fetch=None, budzet_s=None, run_t0=None, su=None):
    """v353: data/rosja.json. Każde źródło z własną bramką (_ru_due) i budżetem czasu; źródło z błędem — poprzednia część z datą (ok False, krótki
    zamaskowany błąd err); część bez próby — 'cached' (z danymi) albo False (jeszcze nie pobrana). Plik innej wersji = start od zera. Złoto (zloto)
    kopiowane z su (surowce.json tego przebiegu) bez zapytań."""
    now = now or _now_utc()
    now_iso = now.replace(microsecond=0).isoformat()
    prev = prev if isinstance(prev, dict) and prev.get('v') == RU_V else {}
    st = json.loads(json.dumps(prev.get('st'))) if isinstance(prev.get('st'), dict) else {}
    fetch = fetch or _ru_pobierz
    budzet = RU_BUDZET_S if budzet_s is None else budzet_s
    t0 = time.monotonic()
    late = run_t0 is not None and time.monotonic() - run_t0 > BACK_LATE
    PARSE = {'ue': lambda b: parse_ru_ue(json.loads(b)), 'bis': lambda b: parse_ru_bis(b.decode('utf-8', 'replace')),
             'imts': lambda b: parse_ru_imts(json.loads(b)), 'rez': lambda b: parse_ru_rez(json.loads(b))}
    parts, proby, zle, pominiete = {}, {p: 0 for p in RU_PARTS}, {}, []
    for src in RU_PARTS:
        z = st.setdefault(src, {})
        if not _ru_due(src, z, now, prev.get(src)):
            continue
        if late:
            pominiete.append(f'{src} (długi przebieg)'); continue
        left = budzet - (time.monotonic() - t0)
        if left < 5:
            pominiete.append(f'{src} (budżet czasu)'); continue
        z['try'] = now_iso
        proby[src] = 1
        try:
            raw = fetch(RU_URL[src], min(RU_LIMIT_S[src], round(left, 1)), RU_MAKS_B[src])
            if len(raw) > RU_MAKS_B[src]:
                raise RuntimeError(f'odpowiedź większa niż {RU_MAKS_B[src]} B (limit)')
            part = PARSE[src](raw)
        except Exception as e:
            msg = mask(f'{src}: {e}')[:160]
            z['err'] = msg; zle[src] = msg
            continue
        parts[src] = part
        z['at'] = now_iso; z['asof'] = part['asof']; z.pop('err', None)
    out = {'v': RU_V, 'at': None, 'src': 'CapitalFlowAI — Rosja z otwartych źródeł międzynarodowych (kody części: ue, bis, imts, rez, zloto — pełne nazwy na stronie Źródła)'}
    pat = dict(prev.get('part_at') or {}) if isinstance(prev.get('part_at'), dict) else {}
    perr = dict(prev.get('err') or {}) if isinstance(prev.get('err'), dict) else {}
    ok = {}
    for p in RU_PARTS:
        if p in parts:
            out[p] = parts[p]; pat[p] = now_iso
        elif isinstance(prev.get(p), dict):
            out[p] = prev[p]
        if zle.get(p):
            ok[p] = False; perr[p] = zle[p]
        elif proby[p]:
            ok[p] = True; perr.pop(p, None)
        else:
            ok[p] = False if (perr.get(p) or not isinstance(out.get(p), dict)) else 'cached'
            if not isinstance(out.get(p), dict) and p not in perr:
                perr[p] = 'brak danych (źródło jeszcze nie pobrane)'
    zl = ru_zloto(su)
    if zl:
        out['zloto'] = zl
        if zl != prev.get('zloto') or not pat.get('zloto'):
            pat['zloto'] = now_iso   # chwila zmiany kopii (bez zmiany — plik nie wygląda na świeższy)
    elif isinstance(prev.get('zloto'), dict):
        out['zloto'] = prev['zloto']
    out['part_at'] = {p: pat[p] for p in RU_PARTS + ('zloto',) if pat.get(p) and isinstance(out.get(p), dict)}
    out['at'] = max(out['part_at'].values()) if out['part_at'] else (prev.get('at') or now_iso)
    out.update({'ok': ok, 'err': {p: perr[p] for p in RU_PARTS if perr.get(p)},
                'next': {p: _ru_next(p, st.get(p, {}), out.get(p), now) for p in RU_PARTS}, 'st': st})
    for p in RU_PARTS:
        if zle.get(p):
            META['errors'].append(mask('Rosja ' + zle[p])[:200])
    if pominiete:
        META['notes'].append('Rosja: pominięte w tym przebiegu — ' + ', '.join(pominiete))
    return out


# ===================== v305: SZLAKI HANDLOWE I ŁAŃCUCHY DOSTAW — data/szlaki.json (dział SUROWCE, etapy 4 i 9 — część) =====================
# Osobny plik i osobny budowniczy (surowce.json bez zmian). Trzy części, każda z part_at / ok / next / err jak w surowce.json:
#   cies   — ruch statków przez 8 cieśnin i kanałów (Ormuz, Bab el-Mandeb, Kanał Sueski, Bosfor, Kanał Panamski, Malakka, Gibraltar, Przylądek
#            Dobrej Nadziei): dzienna liczba przejść (n_total; przejście = statek przecina granicę cieśniny, liczony raz na 48 h) z sygnałów
#            pozycji statków (AIS) — 90 dni; średnia 7 ostatnich dni (s7) wobec średniej z tych samych 7 dni tygodnia rok wcześniej
#            (52 tygodnie = 364 dni wstecz: r7; zmiana chg = (s7 / r7 − 1) × 100, tylko gdy r7 ≥ SZ_R7_MIN — inaczej null), w tym
#            tankowce (t7) i szacowany ładunek w tonach (c7: wydawca szacuje zanurzenie × nośność statku — szacunek, nie pomiar); m7 — średnia
#            krocząca 7 dni do każdego dnia wykresu (tylko z pełnych 7 dni). Średnie wyłącznie z KOMPLETU 7 kolejnych dni (brak dnia = null);
#            0 przejść to pomiar (Ormuz 4.03.2026), nie brak;
#   presja — światowy wskaźnik presji w łańcuchach dostaw: plik CSV wersji interaktywnej (macierz wydań: wiersz = koniec miesiąca danych,
#            kolumna = wydanie „Mon-YY”; bierzemy NAJNOWSZE wydanie wg daty nagłówka, nie wg pozycji) — 36 miesięcy; odchylenia standardowe
#            od średniej (0 = przeciętnie). Plik .xlsx ze strony wydawcy to stary plik z 2024 r. — pułapka, nieużywany;
#   bcpi   — indeks cen surowców (grupa tygodniowa: całość, energia, metale i minerały, rolne) — 36 tygodni; średnia 5 dni roboczych do
#            środy, 1972 = 100, w USD; ostatnie tygodnie bywają wstępne (wydawca powtarza ostatnią cenę do czasu nowej i poprawia wstecz) —
#            co pobranie cała seria od nowa.
# Kody źródeł (pole z, stan st) — pełne nazwy wyłącznie na stronie „Źródła”: pw — PortWatch (ArcGIS, bez klucza), gscpi — CSV wskaźnika
# presji, bcpi — API Valet banku centralnego (bez klucza). Bramki wg terminów publikacji (_sz_oczek): pw — wtorek ok. 12:10 UTC (dane do
# niedzieli; sprawdzone 06.10.2026: edycja warstwy 12:09 UTC, najnowszy dzień 04.10), bcpi — tydzień po środzie (07.10 najnowsza 30.09),
# gscpi — 4. dzień roboczy miesiąca (wydanie „Oct-26” było 07.10). W oknie publikacji, dopóki nowe dane nie przyszły: co SZ_CZESTO min (po
# SZ_ZALEGLE_H h — co 6 h); poza nim co SZ_RZADKO min (poprawki wstecz). Źródło z błędem = poprzednie dane z ich datą; brak = null, nigdy 0.
# Budżet czasu: cały budowniczy SZ_BUDZET_S s; źródło startuje tylko, gdy zmieszczą się wszystkie jego zapytania z pełnymi limitami (typowo
# 3 zapytania, ok. 2–3 s i ok. 140 KB razem, gdy wszystkie są należne; zwykle 0 — dane tygodniowe i miesięczne).
SZ_V = 1
SZ_PARTS = ('cies', 'presja', 'bcpi')
SZ_ZR = (('bcpi', 'bcpi'), ('gscpi', 'presja'), ('pw', 'cies'))     # kolejność: najlżejsze najpierw
SZ_LIMIT_S = {'bcpi': 20, 'gscpi': 30, 'pw': 30}                   # s — limit jednego zapytania (07–08.10.2026: 0,4 s, 0,5 s, 0,9–1,9 s)
SZ_ZAPYTANIA = {'pw': 2}                                           # okno bieżące + rok wcześniej (strony ponad pierwszą — z reszty budżetu)
SZ_BUDZET_S = 120
SZ_CZESTO = {'pw': 60, 'bcpi': 120, 'gscpi': 180}                  # min — w oknie publikacji, dopóki spodziewane dane nie przyszły
SZ_RZADKO = {'pw': 24 * 60, 'bcpi': 24 * 60, 'gscpi': 7 * 24 * 60}  # min — poza oknem (poprawki wstecz)
SZ_ZALEGLE_H = 72                                                  # h po spodziewanej publikacji — dalej ponowienie co 6 h
SZ_D, SZ_OKNO, SZ_ROK = 90, 7, 364                                 # dni wykresu; dni średniej; dni wstecz porównania (52 tygodnie)
SZ_OPOZN = 14                                                      # dni — zapas na opóźnienie źródła w zapytaniu bieżącym
SZ_R7_MIN = 1.0                                                    # statków dziennie rok wcześniej — mniej = zmiana w % bez sensu (null)
SZ_M, SZ_W = 36, 36                                                # miesięcy wskaźnika presji; tygodni indeksu cen surowców
SZ_PW_STRONA, SZ_PW_STRON = 1000, 3                                # wierszy na stronę (limit warstwy: 1000); najwięcej stron w zapytaniu
SZ_CIES = (   # id strony, identyfikator u źródła, fragment nazwy u źródła (sprawdzany: zmiana numeracji = brak, nie zła cieśnina)
    ('ormuz', 'chokepoint6', 'hormuz'), ('bab', 'chokepoint4', 'mandeb'), ('suez', 'chokepoint1', 'suez'), ('bosfor', 'chokepoint3', 'bosporus'),
    ('panama', 'chokepoint2', 'panama'), ('malakka', 'chokepoint5', 'malacca'), ('gibraltar', 'chokepoint8', 'gibraltar'),
    ('przyladek', 'chokepoint7', 'good hope'))
SZ_PW_URL = 'https://services9.arcgis.com/weJ1QsnbMYJlCHdG/arcgis/rest/services/Daily_Chokepoints_Data/FeatureServer/0/query'
SZ_PW_POLA = 'date,portid,portname,n_total,n_tanker,n_cargo,capacity'
SZ_GSCPI_URL = 'https://www.newyorkfed.org/medialibrary/research/interactives/data/gscpi/gscpi_interactive_data.csv'
SZ_BCPI_URL = 'https://www.bankofcanada.ca/valet/observations/group/BCPI_WEEKLY/json?recent=' + str(SZ_W)
SZ_BCPI = (('calosc', 'W.BCPI'), ('energia', 'W.ENER'), ('metale', 'W.MTLS'), ('rolne', 'W.AGRI'))
SZ_MIES_EN = ('jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec')


def _sz_dzien(v):
    """Data dnia: 'RRRR-MM-DD' (pole DateOnly) albo milisekundy UTC (pole Date) → 'RRRR-MM-DD'; inaczej None."""
    if isinstance(v, str) and re.match(r'^\d{4}-\d{2}-\d{2}', v):
        try:
            return datetime.date.fromisoformat(v[:10]).isoformat()
        except ValueError:
            return None
    if _isnum(v):
        try:
            return datetime.datetime.fromtimestamp(v / 1000, datetime.timezone.utc).date().isoformat()
        except (OverflowError, OSError, ValueError):
            return None
    return None


def _sz_int(v):
    return _isnum(v) and v >= 0 and float(v) == int(v)


def _sz_odm(n, f1, f2, f5):
    """v307: polska odmiana po liczbie całkowitej — 1 wiersz, 2 wiersze, 5 wierszy, 12 wierszy, 22 wiersze."""
    n = abs(int(n))
    return f1 if n == 1 else f2 if n % 10 in (2, 3, 4) and n % 100 not in (12, 13, 14) else f5


def sz_pw_url(od, do=None, offset=0):
    """Zapytanie warstwy cieśnin: 8 identyfikatorów, dni od `od` (do `do` włącznie), rosnąco po dniu i identyfikatorze (stała kolejność stron)."""
    ids = ','.join(f"'{p}'" for _, p, _ in SZ_CIES)
    w = f"portid IN ({ids}) AND date >= DATE '{od}'" + (f" AND date <= DATE '{do}'" if do else '')
    q = [('where', w), ('outFields', SZ_PW_POLA), ('orderByFields', 'date,portid'), ('returnGeometry', 'false'),
         ('resultOffset', str(int(offset))), ('resultRecordCount', str(SZ_PW_STRONA)), ('f', 'json')]
    return SZ_PW_URL + '?' + urllib.parse.urlencode(q)


def parse_pw(j):
    """Odpowiedź warstwy cieśnin → ({id: {dzień: (statki, tankowce|None, ładunek t|None)}}, niezgodne sumy, złe identyfikatory, jest dalsza strona).
    Pole error = błąd; identyfikator z nazwą inną niż oczekiwana — pominięty (lista złych; zmiana numeracji u źródła nie podmieni cieśniny);
    statki nie-liczba albo < 0 = brak wiersza (nigdy 0); 0 = pomiar. Suma statki ≠ tankowce + pozostałe — wiersz zostaje (źródło podaje sumę),
    liczony w niezgodnych (kontrola: ⚠️; 2019-01-01 – 2026-10-04: 0 z 22 672 wierszy)."""
    if not isinstance(j, dict):
        raise RuntimeError('nieznany kształt odpowiedzi')
    if j.get('error'):
        e = j['error']
        raise RuntimeError('błąd warstwy: ' + str(e.get('message') if isinstance(e, dict) else e)[:120])
    F = j.get('features')
    if not isinstance(F, list):
        raise RuntimeError('nieznany kształt odpowiedzi')
    pid = {p: (cid, nm) for cid, p, nm in SZ_CIES}
    out, nz, zle = {}, 0, set()
    for f in F:
        a = f.get('attributes') if isinstance(f, dict) else None
        if not isinstance(a, dict) or a.get('portid') not in pid:
            continue
        cid, nm = pid[a['portid']]
        if nm not in str(a.get('portname') or '').lower():
            zle.add(a['portid']); continue
        d, n, tk, cg, cap = _sz_dzien(a.get('date')), a.get('n_total'), a.get('n_tanker'), a.get('n_cargo'), a.get('capacity')
        if not d or not _sz_int(n):
            continue
        if _sz_int(tk) and _sz_int(cg) and int(n) != int(tk) + int(cg):
            nz += 1
        out.setdefault(cid, {})[d] = (int(n), int(tk) if _sz_int(tk) else None, float(cap) if _isnum(cap) and cap >= 0 else None)
    return out, nz, sorted(zle), bool(j.get('exceededTransferLimit'))


def _sz_vint(h):
    """Nagłówek kolumny wydania 'Oct-26' → '2026-10'; inaczej None."""
    m = re.match(r'^\s*([A-Za-z]{3})-(\d{2})\s*$', str(h or ''))
    if not m or m.group(1).lower() not in SZ_MIES_EN:
        return None
    return f'20{m.group(2)}-{SZ_MIES_EN.index(m.group(1).lower()) + 1:02d}'


def _sz_mies(s):
    """Koniec miesiąca danych '30-Sep-2026' → '2026-09'; inaczej None."""
    m = re.match(r'^\s*(\d{1,2})-([A-Za-z]{3})-(\d{4})\s*$', str(s or ''))
    if not m or m.group(2).lower() not in SZ_MIES_EN:
        return None
    return f'{m.group(3)}-{SZ_MIES_EN.index(m.group(2).lower()) + 1:02d}'


def parse_gscpi(text):
    """CSV wersji interaktywnej → (wydanie 'RRRR-MM', {miesiąc 'RRRR-MM': liczba}). Najnowsze wydanie = kolumna z najpóźniejszą datą nagłówka;
    '#N/A', puste i nie-liczby = brak (nigdy 0). Plik bez nagłówka 'Date' (np. strona HTML zamiast pliku) albo bez kolumn wydań = błąd."""
    if isinstance(text, bytes):
        text = text.decode('utf-8-sig', 'replace')
    R = list(csv.reader(io.StringIO(str(text).lstrip('\ufeff'))))
    if not R or not R[0] or R[0][0].strip().lower() != 'date':
        raise RuntimeError('nieznany układ pliku (brak nagłówka Date)')
    K = [(i, v) for i, v in ((i, _sz_vint(h)) for i, h in enumerate(R[0])) if i and v]
    if not K:
        raise RuntimeError('brak kolumn wydań')
    ci, wyd = max(K, key=lambda x: x[1])
    out = {}
    for r in R[1:]:
        m = _sz_mies(r[0]) if r else None
        if not m or ci >= len(r):
            continue
        v = _num(r[ci])
        if _isnum(v):
            out[m] = round(v, 2)
    if not out:
        raise RuntimeError(f'wydanie {wyd} bez liczb')
    return wyd, out


def parse_bcpi(j):
    """Grupa tygodniowa indeksu cen surowców → ({id: {dzień: liczba}}, [opisy pominiętych]). Seria nieobecna w seriesDetail = brak serii (opis);
    wartość pusta, nie-liczba albo ≤ 0 (indeks 1972 = 100 nie bywa ≤ 0) = brak tego tygodnia (nigdy 0)."""
    if not isinstance(j, dict) or not isinstance(j.get('observations'), list):
        raise RuntimeError('nieznany kształt odpowiedzi')
    det = j.get('seriesDetail') if isinstance(j.get('seriesDetail'), dict) else {}
    out, uw = {}, []
    for cid, s in SZ_BCPI:
        if s not in det:
            uw.append(f'brak serii {s}'); continue
        bad = 0
        for o in j['observations']:
            d = _sz_dzien(o.get('d')) if isinstance(o, dict) else None
            x = o.get(s) if d else None
            raw = x.get('v') if isinstance(x, dict) else None
            if raw in (None, ''):   # tydzień bez wartości — brak (bez opisu)
                continue
            v = _num(raw)
            if not _isnum(v) or v <= 0:
                bad += 1; continue
            out.setdefault(cid, {})[d] = round(v, 2)
        if bad:
            uw.append(f'{s}: {bad} wartości ≤ 0 albo nie-liczby pominięte')
    if not out:
        raise RuntimeError('brak serii indeksu')
    return out, uw


# ---- kalendarz publikacji ----
def _sz_utc(d, h, mi=0):
    return datetime.datetime(d.year, d.month, d.day, h, mi, tzinfo=datetime.timezone.utc)


def _sz_4rob(y, m):
    """4. dzień roboczy (pn–pt) miesiąca."""
    return _su_dzien_rob(datetime.date(y, m, 1) - datetime.timedelta(days=1), 4)


def _sz_oczek(src, now):
    """(najnowsze dane spodziewane według kalendarza, chwila ich publikacji) dla źródła: pw — ostatni wtorek 12:10 UTC → dane do soboty
    przed nim (zwykle są do niedzieli; sobota — zapas na dzień krótszą paczkę); bcpi — środa W, gdy minął wtorek W + 6 dni 12:00 UTC;
    gscpi — miesiąc przed ostatnim 4. dniem roboczym (15:00 UTC) — dane za poprzedni miesiąc."""
    if src == 'pw':
        for back in range(8):
            d = (now - datetime.timedelta(days=back)).date()
            if d.weekday() == 1 and _sz_utc(d, 12, 10) <= now:
                return (d - datetime.timedelta(days=3)).isoformat(), _sz_utc(d, 12, 10)
    if src == 'bcpi':
        for back in range(6, 14):
            d = (now - datetime.timedelta(days=back)).date()
            if d.weekday() == 2 and _sz_utc(d + datetime.timedelta(days=6), 12) <= now:
                return d.isoformat(), _sz_utc(d + datetime.timedelta(days=6), 12)
    if src == 'gscpi':
        y, m = now.year, now.month
        for _ in range(3):
            t = _sz_utc(_sz_4rob(y, m), 15)
            if t <= now:
                py, pm = (y - 1, 12) if m == 1 else (y, m - 1)
                return f'{py:04d}-{pm:02d}', t
            y, m = (y - 1, 12) if m == 1 else (y, m - 1)
    raise ValueError(f'kalendarz: {src}')


def _sz_due(src, z, now):
    """Czy źródło trzeba pobrać w tym przebiegu: pierwsze pobranie — co godzinę do skutku; spodziewane dane jeszcze nie przyszły — co
    SZ_CZESTO min (po SZ_ZALEGLE_H h od publikacji — co 6 h); poza tym co SZ_RZADKO min (poprawki wstecz); po błędzie — najwcześniej po 60 min."""
    at, tr = _su_min(now, z.get('at')), _su_min(now, z.get('try'))
    if at == float('inf'):
        return tr >= 60
    exp, pub = _sz_oczek(src, now)
    if str(z.get('asof') or '') < exp:
        return tr >= (SZ_CZESTO[src] if (now - pub).total_seconds() <= SZ_ZALEGLE_H * 3600 else 360)
    return at >= SZ_RZADKO[src] and tr >= 60


def _sz_next(src, asof, now):
    """Najbliższa spodziewana publikacja (ISO, UTC); termin w przeszłości = publikacja zaległa (święto, przerwa u źródła)."""
    exp, pub = _sz_oczek(src, now)
    if str(asof or '') < exp:
        return pub.isoformat()
    if src in ('pw', 'bcpi'):
        return (pub + datetime.timedelta(days=7)).isoformat()
    y, m = (pub.year + 1, 1) if pub.month == 12 else (pub.year, pub.month + 1)
    return _sz_utc(_sz_4rob(y, m), 15).isoformat()


# ---- pobrania ----
def _sz_get(ctx, url, src):
    """Jedno zapytanie z limitem źródła, nie dłuższym niż reszta budżetu budowniczego (reszta < 5 s = błąd źródła; ponowienie później)."""
    lim = SZ_LIMIT_S[src]
    if ctx.get('t0') is not None and ctx.get('budzet') is not None:
        left = ctx['budzet'] - (time.monotonic() - ctx['t0'])
        if left < 5:
            raise RuntimeError('budżet czasu budowniczego wyczerpany')
        lim = min(lim, left)
    return ctx['fetch'](url, lim)


def _sz_pw_zap(ctx, od, do):
    """Zapytanie z kolejnymi stronami (najwyżej SZ_PW_STRON) → (wiersze, niezgodne sumy, złe identyfikatory)."""
    R, nz, zle, off = {}, 0, set(), 0
    for _ in range(SZ_PW_STRON):
        j = json.loads(_sz_get(ctx, sz_pw_url(od, do, off), 'pw'))
        r, n, z, dalej = parse_pw(j)
        for cid, rows in r.items():
            R.setdefault(cid, {}).update(rows)
        nz += n; zle.update(z)
        if not dalej:
            return R, nz, zle
        off += len(j.get('features') or [])
    raise RuntimeError(f'więcej niż {SZ_PW_STRON} strony wyników')


def _sz_mean(V):
    return round(sum(V) / len(V), 2) if V and all(_isnum(v) for v in V) else None


def _sz_okno(rows, end, k=0):
    """Wartości (pole k krotki) z 7 kolejnych dni kończących się w dniu end; brak któregoś dnia albo pola = None."""
    e = datetime.date.fromisoformat(end)
    V = []
    for i in range(SZ_OKNO - 1, -1, -1):
        r = rows.get((e - datetime.timedelta(days=i)).isoformat())
        if r is None or r[k] is None:
            return None
        V.append(r[k])
    return V


def sz_cies(R, Y, nz=0):
    """Część cies z wierszy okna bieżącego R i okna sprzed roku Y ({id: {dzień: (statki, tankowce, ładunek)}})."""
    k = {}
    for cid, _p, _n in SZ_CIES:
        rows = R.get(cid) or {}
        if not rows:
            continue
        last = max(rows)
        d0 = (datetime.date.fromisoformat(last) - datetime.timedelta(days=SZ_D - 1)).isoformat()
        dni = sorted(d for d in rows if d >= d0)
        e = {'asof': last, 'd': [[d, rows[d][0]] for d in dni], 'm7': [[d, _sz_mean(_sz_okno(rows, d) or [])] for d in dni]}
        a = (datetime.date.fromisoformat(last) - datetime.timedelta(days=SZ_OKNO - 1)).isoformat()
        ry = (datetime.date.fromisoformat(last) - datetime.timedelta(days=SZ_ROK)).isoformat()
        rya = (datetime.date.fromisoformat(ry) - datetime.timedelta(days=SZ_OKNO - 1)).isoformat()
        yr = (Y or {}).get(cid) or {}
        s7, t7, c7 = (_sz_mean(_sz_okno(rows, last, i) or []) for i in range(3))
        r7, rt7, rc7 = (_sz_mean(_sz_okno(yr, ry, i) or []) for i in range(3))
        e.update({'okno': [a, last], 'rok': [rya, ry], 's7': s7, 't7': t7, 'c7': c7, 'r7': r7, 'rt7': rt7, 'rc7': rc7,
                  'chg': round((s7 / r7 - 1) * 100, 2) if _isnum(s7) and _isnum(r7) and r7 >= SZ_R7_MIN else None})
        k[cid] = e
    if not k:
        raise RuntimeError('brak danych cieśnin')
    return {'asof': max(e['asof'] for e in k.values()), 'u': 'statki/dzień', 'okno': SZ_OKNO, 'rok': SZ_ROK, 'nz': nz, 'k': k}


def _sz_pobierz_pw(ctx):
    now = ctx['now']
    R, nz, zle = _sz_pw_zap(ctx, (now.date() - datetime.timedelta(days=SZ_D + SZ_OKNO - 1 + SZ_OPOZN)).isoformat(), None)
    if not R:
        raise RuntimeError('brak wierszy cieśnin' + (f' (zmieniona numeracja: {", ".join(sorted(zle))})' if zle else ''))
    L = [datetime.date.fromisoformat(max(r)) for r in R.values() if r]
    a = (min(L) - datetime.timedelta(days=SZ_ROK + SZ_OKNO - 1)).isoformat()
    b = (max(L) - datetime.timedelta(days=SZ_ROK)).isoformat()
    Y, nz2, zle2 = _sz_pw_zap(ctx, a, b)
    zle |= zle2
    if zle:
        ctx['bledy'].append('pw: identyfikatory z inną nazwą (pominięte): ' + ', '.join(sorted(zle)))
    braki = [cid for cid, _p, _n in SZ_CIES if cid not in R]
    if braki:
        ctx['bledy'].append('pw: brak cieśnin: ' + ', '.join(braki))
    if nz + nz2:
        n = nz + nz2   # v307: odmiana („1 wiersz”, „2 wiersze”, „5 wierszy”)
        ctx['uwagi'].append(f'pw: {n} {_sz_odm(n, "wiersz", "wiersze", "wierszy")} z sumą statków ≠ tankowce + pozostałe')
    part = sz_cies(R, Y, nz + nz2)
    ctx['parts']['cies'] = part
    return part['asof']


def _sz_pobierz_gscpi(ctx):
    wyd, M = parse_gscpi(_sz_get(ctx, SZ_GSCPI_URL, 'gscpi'))
    ms = sorted(M)[-SZ_M:]
    ctx['parts']['presja'] = {'asof': ms[-1], 'wyd': wyd, 'u': 'odchylenia standardowe od średniej (0 = przeciętnie)', 'd': [[m, M[m]] for m in ms]}
    return ms[-1]


def _sz_pobierz_bcpi(ctx):
    S, uw = parse_bcpi(json.loads(_sz_get(ctx, SZ_BCPI_URL, 'bcpi')))
    ctx['bledy'].extend('bcpi: ' + x for x in uw)
    s = {}
    for cid, _s in SZ_BCPI:
        rows = sorted((S.get(cid) or {}).items())[-SZ_W:]
        if rows:
            s[cid] = {'d': [[d, v] for d, v in rows]}
    asof = max(e['d'][-1][0] for e in s.values())
    ctx['parts']['bcpi'] = {'asof': asof, 'f': 'W', 'u': 'indeks (1972 = 100, USD)', 's': s}
    return asof


SZ_POBIERZ = {'pw': _sz_pobierz_pw, 'gscpi': _sz_pobierz_gscpi, 'bcpi': _sz_pobierz_bcpi}


def build_szlaki(prev=None, now=None, fetch=None, budzet_s=None, run_t0=None):
    """v305: data/szlaki.json. Każde źródło z własną bramką (_sz_due) i budżetem czasu; źródło z błędem — poprzednia część z datą (ok False,
    krótki zamaskowany błąd err); część bez próby — 'cached' (z danymi) albo False (jeszcze nie pobrana). Plik innej wersji = start od zera.
    v307: błąd częściowy (źródło odpowiedziało, ale czegoś zabrakło — np. jednej cieśniny albo serii indeksu) — ok False jak dotąd i pole
    cz = {część: True} (tylko w przebiegu z taką próbą, jak ok): strona mówi „część danych niedostępna”, nie „pobranie się nie udało”."""
    now = now or _now_utc()
    now_iso = now.replace(microsecond=0).isoformat()
    prev = prev if isinstance(prev, dict) and prev.get('v') == SZ_V else {}
    st = json.loads(json.dumps(prev.get('st'))) if isinstance(prev.get('st'), dict) else {}
    ctx = {'now': now, 'bledy': [], 'uwagi': [], 'parts': {}, 't0': time.monotonic(),
           'budzet': SZ_BUDZET_S if budzet_s is None else budzet_s,
           'fetch': fetch or (lambda url, timeout, headers=None: get_bytes(url, headers, timeout=timeout))}
    late = run_t0 is not None and time.monotonic() - run_t0 > BACK_LATE
    proby, zle, pominiete, czesc = {p: 0 for p in SZ_PARTS}, {}, [], set()
    for src, part in SZ_ZR:
        z = st.setdefault(src, {})
        if not _sz_due(src, z, now):
            continue
        if late and src == 'pw':
            pominiete.append('pw (długi przebieg)'); continue
        if time.monotonic() - ctx['t0'] + SZ_ZAPYTANIA.get(src, 1) * SZ_LIMIT_S[src] > ctx['budzet']:
            pominiete.append(f'{src} (budżet czasu)'); continue
        nb = len(ctx['bledy'])
        z['try'] = now_iso
        proby[part] += 1
        try:
            asof = SZ_POBIERZ[src](ctx)
        except Exception as e:
            msg = mask(f'{src}: {e}')[:160]
            z['err'] = msg; zle.setdefault(part, []).append(msg)
            continue
        z['at'] = now_iso; z['asof'] = asof; z.pop('err', None)
        if len(ctx['bledy']) > nb:
            zle.setdefault(part, []).extend(mask(x)[:160] for x in ctx['bledy'][nb:])
            czesc.add(part)   # v307: błąd częściowy — dane tej części z tego pobrania, czegoś w nich brak
    out = {'v': SZ_V, 'at': None, 'src': 'CapitalFlowAI — szlaki handlowe i łańcuchy dostaw (kody źródeł z: pw, gscpi, bcpi — pełne nazwy na stronie Źródła)'}
    pat = dict(prev.get('part_at') or {}) if isinstance(prev.get('part_at'), dict) else {}
    perr = dict(prev.get('err') or {}) if isinstance(prev.get('err'), dict) else {}
    ok, src_of = {}, {p: s for s, p in SZ_ZR}
    for p in SZ_PARTS:
        if p in ctx['parts']:
            out[p] = ctx['parts'][p]; pat[p] = now_iso
        elif isinstance(prev.get(p), dict):
            out[p] = prev[p]
        if zle.get(p):   # błąd źródła (część z poprzednimi danymi) albo błąd częściowy (np. brak jednej cieśniny — reszta zapisana)
            ok[p] = False; perr[p] = '; '.join(zle[p])[:240]
        elif proby[p]:
            ok[p] = True; perr.pop(p, None)
        else:
            ok[p] = 'cached' if isinstance(out.get(p), dict) else False
            if not isinstance(out.get(p), dict) and p not in perr:
                perr[p] = 'brak danych (źródło jeszcze nie pobrane)'
    out['part_at'] = {p: pat[p] for p in SZ_PARTS if pat.get(p) and isinstance(out.get(p), dict)}
    out['at'] = max(out['part_at'].values()) if out['part_at'] else (prev.get('at') or now_iso)
    out.update({'ok': ok, 'err': {p: perr[p] for p in SZ_PARTS if perr.get(p)},
                'next': {p: _sz_next(src_of[p], (out.get(p) or {}).get('asof'), now) for p in SZ_PARTS}, 'st': st})
    if czesc:   # v307: tylko części z błędem częściowym w tym przebiegu (ok False) — brak pola = bez braków
        out['cz'] = {p: True for p in SZ_PARTS if p in czesc}
    for x in ctx['uwagi']:
        META['notes'].append(mask('szlaki: ' + x)[:200])
    for p in SZ_PARTS:
        for x in zle.get(p, []):
            META['errors'].append(mask('szlaki ' + x)[:200])
    if pominiete:
        META['notes'].append('szlaki: pominięte w tym przebiegu — ' + ', '.join(pominiete))
    return out


# ===================== v393 (F11Z7): PORTY ŚWIATA — data/porty.json (dział SUROWCE, obok szlaków handlowych) =====================
# Osobny plik i osobny budowniczy (szlaki.json bez zmian). Dzienne dane o ruchu w portach świata z tej samej warstwy ArcGIS co cieśniny (v305): dla ok. 2065 portów
# liczba zawinięć statków oraz SZACOWANE tony wyładowane (import) i załadowane (export), w tym osobno kontenerowce, masowce suche i tankowce. Szacunek, nie pomiar —
# oblicza go wydawca z sygnałów pozycji statków (AIS), nośności i zanurzenia. Dwie niezależne części, każda z part_at / ok / next / err jak w szlaki.json:
#   sw — świat wg ładunku: JEDNO zapytanie statystyczne po stronie serwera (suma po wszystkich portach, grupowanie po dniu) — 4 grupy (wszystkie statki, kontenerowce,
#        masowce suche, tankowce): 90 dni, średnia 7 ostatnich dni (zawinięcia, import, export w t/dzień) wobec tych samych 7 dni tygodnia rok wcześniej (364 dni
#        wstecz), zmiana w %; m7 — średnia krocząca 7 dni importu do każdego dnia wykresu, y7 — ta sama średnia sprzed 364 dni na osi bieżącej. Dzień, w którym warstwa ma
#        mniej niż PRT_N_MIN × mediany liczby portów z okna (paczka niepełna), jest odrzucany; średnie tylko z KOMPLETU 7 kolejnych dni (brak dnia = null);
#   pt — 20 portów (lista stała PRT_PORTY: identyfikator u źródła + fragment nazwy sprawdzany przy każdym pobraniu — zmiana numeracji u źródła = brak portu, nie zły port):
#        średnia 7 dni zawinięć i ton (import, export, razem = przeładunek), podział importu i exportu wg ładunku, zmiana przeładunku wobec tych samych 7 dni rok
#        wcześniej, m7 — średnia krocząca 7 dni przeładunku z 90 dni. Zapytania stronicowane (resultOffset, stała kolejność date,portid), najwyżej PRT_STRON stron.
# Kod źródła (stan st): pw — PortWatch (ArcGIS, bez klucza; ten sam wydawca co cieśniny — liczba źródeł na stronie bez zmian, ZRODLA_META: imf). Licencja: strona danych wydawcy
# (17.10.2026) nie podaje osobnej licencji (CC BY nie znaleziono) i odsyła do ogólnych warunków instytucji (adres warunków odpowiada naszemu zbieraczowi „403” — nie obchodzone);
# licencje drugorzędne (decyzja właściciela 11.10); nazwy wydawcy na stronie poza „Źródła” nie ma. Bramka wg terminu publikacji (_prt_oczek): aktualizacja tygodniowa we wtorek rano
# czasu wschodnich USA (komunikaty strony wydawcy: wtorek 9:00 ET, przy święcie środa) ≈ 12:10–13:00 UTC, ale warstwa portów bywa uzupełniona o dzień-dwa później niż cieśniny
# (sprawdzone 17.10.2026: warstwa cieśnin edytowana w środę 14.10 12:39 UTC, portów w czwartek 15.10 11:11 UTC, ostatni dzień 09.10, 2065 portów) — dlatego oczekiwany najnowszy dzień
# to wtorek − PRT_OCZEK_DNI (10) dni, a zaległość dopiero po tej luce. W oknie publikacji, dopóki nowych danych nie ma:
# co PRT_CZESTO min (po PRT_ZALEGLE_H h — co 6 h); poza nim co PRT_RZADKO min (poprawki wstecz). Źródło z błędem = poprzednia część z datą; brak = null, nigdy 0.
# Zapytanie statystyczne ma twardą granicę długości adresu (IIS: 2048 znaków — dłuższy adres kończy się „404”; sprawdzone 17.10.2026) — adres sprawdzany przed wysłaniem.
PRT_V = 1
PRT_PARTS = ('sw', 'pt')
PRT_URL = 'https://services9.arcgis.com/weJ1QsnbMYJlCHdG/arcgis/rest/services/Daily_Ports_Data/FeatureServer/0/query'
PRT_LIMIT_S = {'sw': 40, 'pt': 40}      # s — limit jednego zapytania (17.10.2026: statystyka 100–200 dni 1–26 s, strona 1000 wierszy 2–14 s)
PRT_ZAPYTANIA = {'sw': 2, 'pt': 3}      # okno bieżące + rok wcześniej (sw); 3 strony okna bieżącego (20 portów × ok. 111 dni) + rok wcześniej (pt) — strony ponad to z reszty budżetu
PRT_BUDZET_S = 170
PRT_CZESTO, PRT_RZADKO, PRT_ZALEGLE_H = 120, 3 * 24 * 60, 72
PRT_OCZEK_DNI = 10                       # dni — oczekiwany najnowszy dzień = dzień wtorkowej publikacji − tyle
PRT_D, PRT_OKNO, PRT_ROK, PRT_OPOZN = 90, 7, 364, 21
PRT_N_MIN = 0.9                          # dzień z mniejszą liczbą portów niż tyle × mediana okna = paczka niepełna (odrzucony)
PRT_R_MIN = {'sw': 1.0, 'pt': 1000.0}    # t/dzień rok wcześniej — mniej = zmiana w % bez sensu (null); zawinięć dziennie: PRT_RC_MIN
PRT_RC_MIN = 0.5
PRT_ADRES_MAX = 2000                     # znaków — granica serwera 2048
PRT_STRONA, PRT_STRON = 1000, 4          # wierszy na stronę (limit warstwy: 1000); najwięcej stron w zapytaniu
PRT_GR = ('all', 'kon', 'mas', 'tan')    # grupy części sw: wszystkie statki, kontenerowce, masowce suche, tankowce
PRT_POLA_SW = ('portcalls', 'portcalls_container', 'portcalls_dry_bulk', 'portcalls_tanker',
               'import', 'import_container', 'import_dry_bulk', 'import_tanker',
               'export', 'export_container', 'export_dry_bulk', 'export_tanker')   # s0 … s11: zawinięcia (4), import (4), export (4)
PRT_POLA_PT = ('portcalls', 'import', 'export', 'import_container', 'import_dry_bulk', 'import_tanker', 'export_container', 'export_dry_bulk', 'export_tanker')
PRT_PORTY = (   # id strony, identyfikator u źródła, fragment nazwy u źródła (małymi literami)
    ('singapur', 'port1201', 'singapore'), ('szanghaj', 'port1188', 'shanghai'), ('yangshan', 'port2027', 'yangshan'), ('ningbo', 'port824', 'ningbo'),
    ('tianjin', 'port1297', 'tianjin'), ('qingdao', 'port1069', 'qingdao'), ('shekou', 'port1189', 'shekou'), ('hongkong', 'port474', 'hong kong'),
    ('busan', 'port1065', 'busan'), ('portklang', 'port960', 'klang'), ('nhavasheva', 'port776', 'nhava'), ('porthedland', 'port955', 'hedland'),
    ('rotterdam', 'port1114', 'rotterdam'), ('antwerpia', 'port57', 'antwerp'), ('hamburg', 'port446', 'hamburg'), ('algeciras', 'port31', 'algeciras'),
    ('gdansk', 'port380', 'gdansk'), ('losangeles', 'port664', 'los angeles'), ('houston', 'port481', 'houston'), ('santos', 'port1160', 'santos'))
PRT_STAT = json.dumps([{'statisticType': 'sum', 'onStatisticField': f, 'outStatisticFieldName': f's{i}'} for i, f in enumerate(PRT_POLA_SW)]
                      + [{'statisticType': 'count', 'onStatisticField': 'ObjectId', 'outStatisticFieldName': 'n'}], separators=(',', ':'))


def _prt_dzien(v):
    """Data dnia: 'RRRR-MM-DD' (pole DateOnly) albo milisekundy UTC (pole Date) → 'RRRR-MM-DD'; inaczej None."""
    if isinstance(v, str) and re.match(r'^\d{4}-\d{2}-\d{2}', v):
        try:
            return datetime.date.fromisoformat(v[:10]).isoformat()
        except ValueError:
            return None
    if _isnum(v) and not isinstance(v, bool):
        try:
            return datetime.datetime.fromtimestamp(v / 1000, datetime.timezone.utc).date().isoformat()
        except (OverflowError, OSError, ValueError):
            return None
    return None


def _prt_t(v):
    """Tony / zawinięcia z odpowiedzi: liczba ≥ 0 (suma po serwerze bywa zmiennoprzecinkowa) → liczba całkowita; inaczej None (brak, nigdy 0)."""
    if _isnum(v) and not isinstance(v, bool) and v >= 0 and v == v and v != float('inf'):
        return int(round(v))
    return None


def prt_url_sw(od, do=None):
    """Zapytanie statystyczne: sumy po wszystkich portach, grupowanie po dniu (bez sortowania po stronie serwera — adres krótszy), dni od `od` (do `do` włącznie)."""
    w = f"date >= DATE '{od}'" + (f" AND date <= DATE '{do}'" if do else '')
    u = PRT_URL + '?' + urllib.parse.urlencode([('where', w), ('groupByFieldsForStatistics', 'date'), ('outStatistics', PRT_STAT), ('f', 'json')])
    if len(u) > PRT_ADRES_MAX:
        raise RuntimeError(f'adres zapytania za długi ({len(u)} znaków, granica serwera 2048)')
    return u


def prt_url_pt(od, do=None, offset=0):
    """Zapytanie o wiersze 20 portów, dni od `od` (do `do` włącznie), rosnąco po dniu i identyfikatorze (stała kolejność stron)."""
    ids = ','.join(f"'{p}'" for _, p, _ in PRT_PORTY)
    w = f"portid IN ({ids}) AND date >= DATE '{od}'" + (f" AND date <= DATE '{do}'" if do else '')
    q = [('where', w), ('outFields', 'date,portid,portname,' + ','.join(PRT_POLA_PT)), ('orderByFields', 'date,portid'), ('returnGeometry', 'false'),
         ('resultOffset', str(int(offset))), ('resultRecordCount', str(PRT_STRONA)), ('f', 'json')]
    return PRT_URL + '?' + urllib.parse.urlencode(q)


def _prt_features(j):
    if not isinstance(j, dict):
        raise RuntimeError('nieznany kształt odpowiedzi')
    if j.get('error'):
        e = j['error']
        raise RuntimeError('błąd warstwy: ' + str(e.get('message') or e.get('code') if isinstance(e, dict) else e)[:120])
    F = j.get('features')
    if not isinstance(F, list):
        raise RuntimeError('nieznany kształt odpowiedzi')
    return F


def parse_prt_sw(j):
    """Odpowiedź statystyczna → ({dzień: (12 sum…)}, {dzień: liczba portów}, liczba odrzuconych wierszy). Wiersz z dniem nieczytelnym albo sumą nie-liczbą / ujemną —
    odrzucony (nigdy 0). Trzy grupy ładunku (kontenerowce, masowce suche, tankowce) razem nie mogą przekroczyć sumy wszystkich (reszta: drobnicowce, ro-ro): niezgodność —
    wiersz odrzucony."""
    F = _prt_features(j)
    if j.get('exceededTransferLimit'):
        raise RuntimeError('odpowiedź ucięta (limit warstwy)')
    R, N, zle = {}, {}, 0
    for f in F:
        a = f.get('attributes') if isinstance(f, dict) else None
        d = _prt_dzien(a.get('date')) if isinstance(a, dict) else None
        V = [_prt_t(a.get(f's{i}')) for i in range(len(PRT_POLA_SW))] if d else []
        n = a.get('n') if d else None
        if not d or any(v is None for v in V) or not (_isnum(n) and n > 0):
            zle += 1; continue
        if any(V[b + 1] + V[b + 2] + V[b + 3] > V[b] * 1.001 + 1 for b in (0, 4, 8)):
            zle += 1; continue
        R[d] = tuple(V); N[d] = int(n)
    return R, N, zle


def parse_prt_pt(j):
    """Odpowiedź warstwy portów → ({id: {dzień: (zawinięcia, import, export, import: kontenery, masowce, tankowce, export: kontenery, masowce, tankowce)}}, niezgodne wiersze,
    złe identyfikatory, jest dalsza strona). Identyfikator z nazwą inną niż oczekiwana — pominięty (lista złych); pole nie-liczba albo < 0 = brak wiersza (nigdy 0). Wiersz,
    w którym trzy ładunki razem przekraczają sumę, zostaje (źródło podaje sumy), liczony w niezgodnych (kontrola: ⚠️)."""
    F = _prt_features(j)
    pid = {p: (cid, nm) for cid, p, nm in PRT_PORTY}
    out, nz, zle = {}, 0, set()
    for f in F:
        a = f.get('attributes') if isinstance(f, dict) else None
        if not isinstance(a, dict) or a.get('portid') not in pid:
            continue
        cid, nm = pid[a['portid']]
        if nm not in str(a.get('portname') or '').lower():
            zle.add(a['portid']); continue
        d = _prt_dzien(a.get('date'))
        V = [_prt_t(a.get(k)) for k in PRT_POLA_PT]
        if not d or any(v is None for v in V):
            continue
        if V[3] + V[4] + V[5] > V[1] * 1.001 + 1 or V[6] + V[7] + V[8] > V[2] * 1.001 + 1:
            nz += 1
        out.setdefault(cid, {})[d] = tuple(V)
    return out, nz, sorted(zle), bool(j.get('exceededTransferLimit'))


def _prt_okno(rows, end, k):
    """Wartości (pole k krotki) z PRT_OKNO kolejnych dni kończących się w dniu end; brak któregoś dnia albo pola = None."""
    e = datetime.date.fromisoformat(end)
    V = []
    for i in range(PRT_OKNO - 1, -1, -1):
        r = rows.get((e - datetime.timedelta(days=i)).isoformat())
        if r is None or r[k] is None:
            return None
        V.append(r[k])
    return V


def _prt_mean(V, dec=1):
    """Średnia z kompletu liczb (brak liczby w komplecie albo pusty komplet = None); dec 0 — liczba całkowita (tony), inaczej zaokrąglona."""
    if not V or not all(_isnum(v) for v in V):
        return None
    r = round(sum(V) / len(V), dec)
    return int(r) if dec == 0 else r


def _prt_chg(s, r, rmin):
    return round((s / r - 1) * 100, 2) if _isnum(s) and _isnum(r) and r >= rmin and r > 0 else None


def _prt_dni(od, do):
    return (datetime.date.fromisoformat(do) - datetime.date.fromisoformat(od)).days


def prt_dni_pelne(R, N):
    """Dni z pełną paczką portów: liczba portów ≥ PRT_N_MIN × mediany z okna → ({dzień: sumy}, odrzucone dni)."""
    if not R:
        return {}, []
    L = sorted(N[d] for d in R)
    med = L[len(L) // 2]
    ok = {d: v for d, v in R.items() if N[d] >= PRT_N_MIN * med}
    return ok, sorted(d for d in R if d not in ok)


def prt_sw(R, Y, n, odrz=0):
    """Część sw z wierszy okna bieżącego R i okna sprzed roku Y ({dzień: 12 sum}); n — liczba portów w ostatnim dniu."""
    if not R:
        raise RuntimeError('brak dni z pełną paczką portów')
    last = max(R)
    d0 = (datetime.date.fromisoformat(last) - datetime.timedelta(days=PRT_D - 1)).isoformat()
    ry = (datetime.date.fromisoformat(last) - datetime.timedelta(days=PRT_ROK)).isoformat()
    rya = (datetime.date.fromisoformat(ry) - datetime.timedelta(days=PRT_OKNO - 1)).isoformat()
    a = (datetime.date.fromisoformat(last) - datetime.timedelta(days=PRT_OKNO - 1)).isoformat()
    dni = sorted(d for d in R if d >= d0)
    G = {}
    for gi, gid in enumerate(PRT_GR):
        kc, ki, ke = gi, 4 + gi, 8 + gi
        e = {'m7': [], 'y7': []}
        for d in dni:
            e['m7'].append([d, _prt_mean(_prt_okno(R, d, ki) or [], 0)])
            yd = (datetime.date.fromisoformat(d) - datetime.timedelta(days=PRT_ROK)).isoformat()
            e['y7'].append([d, _prt_mean(_prt_okno(Y, yd, ki) or [], 0)])
        c7, i7, e7 = (_prt_mean(_prt_okno(R, last, k) or [], 1 if k == kc else 0) for k in (kc, ki, ke))
        rc7, ri7, re7 = (_prt_mean(_prt_okno(Y, ry, k) or [], 1 if k == kc else 0) for k in (kc, ki, ke))
        e.update({'c7': c7, 'i7': i7, 'e7': e7, 'rc7': rc7, 'ri7': ri7, 're7': re7,
                  'chgc': _prt_chg(c7, rc7, PRT_RC_MIN), 'chgi': _prt_chg(i7, ri7, PRT_R_MIN['sw']), 'chge': _prt_chg(e7, re7, PRT_R_MIN['sw'])})
        G[gid] = e
    return {'asof': last, 'n': n, 'u': 't/dzień', 'okno': [a, last], 'rok': [rya, ry], 'odrz': odrz, 'g': G}


def prt_pt(R, Y, nz=0):
    """Część pt z wierszy okna bieżącego R i okna sprzed roku Y ({id: {dzień: 9 pól}})."""
    P = {}
    for cid, _p, _n in PRT_PORTY:
        rows = R.get(cid) or {}
        if not rows:
            continue
        last = max(rows)
        d0 = (datetime.date.fromisoformat(last) - datetime.timedelta(days=PRT_D - 1)).isoformat()
        tot = {d: ((r[1] + r[2]),) for d, r in rows.items()}   # przeładunek = wyładunek + załadunek
        yr = (Y or {}).get(cid) or {}
        ytot = {d: ((r[1] + r[2]),) for d, r in yr.items()}
        ry = (datetime.date.fromisoformat(last) - datetime.timedelta(days=PRT_ROK)).isoformat()
        e = {'asof': last, 'm7': [[d, _prt_mean(_prt_okno(tot, d, 0) or [], 0)] for d in sorted(x for x in rows if x >= d0)]}
        c7, i7, e7 = (_prt_mean(_prt_okno(rows, last, k) or [], 1 if k == 0 else 0) for k in (0, 1, 2))
        ki = [_prt_mean(_prt_okno(rows, last, k) or [], 0) for k in (3, 4, 5)]
        ke = [_prt_mean(_prt_okno(rows, last, k) or [], 0) for k in (6, 7, 8)]
        s7 = _prt_mean(_prt_okno(tot, last, 0) or [], 0)
        rs7 = _prt_mean(_prt_okno(ytot, ry, 0) or [], 0)
        rc7 = _prt_mean(_prt_okno(yr, ry, 0) or [], 1)
        e.update({'c7': c7, 'i7': i7, 'e7': e7, 's7': s7, 'ki': ki, 'ke': ke, 'rs7': rs7, 'rc7': rc7,
                  'chg': _prt_chg(s7, rs7, PRT_R_MIN['pt']), 'chgc': _prt_chg(c7, rc7, PRT_RC_MIN)})
        P[cid] = e
    if not P:
        raise RuntimeError('brak danych portów')
    last = max(e['asof'] for e in P.values())
    a = (datetime.date.fromisoformat(last) - datetime.timedelta(days=PRT_OKNO - 1)).isoformat()
    ry = (datetime.date.fromisoformat(last) - datetime.timedelta(days=PRT_ROK)).isoformat()
    rya = (datetime.date.fromisoformat(ry) - datetime.timedelta(days=PRT_OKNO - 1)).isoformat()
    return {'asof': last, 'u': 't/dzień', 'okno': [a, last], 'rok': [rya, ry], 'nz': nz, 'p': P}


# ---- kalendarz i bramki ----
def _prt_oczek(now):
    """(najnowszy dzień danych spodziewany według kalendarza, chwila publikacji): ostatni wtorek 12:10 UTC; dane do (wtorek − PRT_OCZEK_DNI) dni."""
    for back in range(8):
        d = (now - datetime.timedelta(days=back)).date()
        if d.weekday() == 1 and _sz_utc(d, 12, 10) <= now:
            return (d - datetime.timedelta(days=PRT_OCZEK_DNI)).isoformat(), _sz_utc(d, 12, 10)
    raise ValueError('kalendarz: porty')


def _prt_due(z, now):
    """Czy część trzeba pobrać w tym przebiegu: pierwsze pobranie — co godzinę do skutku; spodziewane dane jeszcze nie przyszły — co PRT_CZESTO min (po PRT_ZALEGLE_H h
    od publikacji — co 6 h); poza tym co PRT_RZADKO min (poprawki wstecz); po błędzie — najwcześniej po 60 min."""
    at, tr = _su_min(now, z.get('at')), _su_min(now, z.get('try'))
    if at == float('inf'):
        return tr >= 60
    exp, pub = _prt_oczek(now)
    if str(z.get('asof') or '') < exp:
        return tr >= (PRT_CZESTO if (now - pub).total_seconds() <= PRT_ZALEGLE_H * 3600 else 360)
    return at >= PRT_RZADKO and tr >= 60


def _prt_next(asof, now):
    """Najbliższa spodziewana publikacja (ISO, UTC); termin w przeszłości = publikacja zaległa (opóźnienie u źródła)."""
    exp, pub = _prt_oczek(now)
    if str(asof or '') < exp:
        return pub.isoformat()
    return (pub + datetime.timedelta(days=7)).isoformat()


# ---- pobrania ----
def _prt_get(ctx, url, src):
    """Jedno zapytanie z limitem części, nie dłuższym niż reszta budżetu budowniczego (reszta < 5 s = błąd; ponowienie później)."""
    lim = PRT_LIMIT_S[src]
    if ctx.get('t0') is not None and ctx.get('budzet') is not None:
        left = ctx['budzet'] - (time.monotonic() - ctx['t0'])
        if left < 5:
            raise RuntimeError('budżet czasu budowniczego wyczerpany')
        lim = min(lim, left)
    return ctx['fetch'](url, lim)


def _prt_pobierz_sw(ctx):
    now = ctx['now']
    od = (now.date() - datetime.timedelta(days=PRT_D + PRT_OKNO - 1 + PRT_OPOZN)).isoformat()
    R0, N0, z1 = parse_prt_sw(json.loads(_prt_get(ctx, prt_url_sw(od), 'sw')))
    R, odrz = prt_dni_pelne(R0, N0)
    if not R:
        raise RuntimeError('brak dni z pełną paczką portów')
    last = max(R)
    a = (datetime.date.fromisoformat(last) - datetime.timedelta(days=PRT_ROK + PRT_D + PRT_OKNO - 2)).isoformat()
    b = (datetime.date.fromisoformat(last) - datetime.timedelta(days=PRT_ROK)).isoformat()
    Y0, YN, z2 = parse_prt_sw(json.loads(_prt_get(ctx, prt_url_sw(a, b), 'sw')))
    Y, _o = prt_dni_pelne(Y0, YN)
    if z1 + z2:
        ctx['uwagi'].append(f'sw: {z1 + z2} {_sz_odm(z1 + z2, "wiersz", "wiersze", "wierszy")} odrzucony (pusta lub niezgodna suma)')
    if odrz:
        ctx['uwagi'].append(f'sw: {len(odrz)} {_sz_odm(len(odrz), "dzień", "dni", "dni")} z niepełną paczką portów pominięty')
    part = prt_sw(R, Y, N0[last], len(odrz))
    ctx['parts']['sw'] = part
    return part['asof']


def _prt_pt_zap(ctx, od, do):
    """Zapytanie z kolejnymi stronami (najwyżej PRT_STRON) → (wiersze, niezgodne, złe identyfikatory)."""
    R, nz, zle, off = {}, 0, set(), 0
    for _ in range(PRT_STRON):
        j = json.loads(_prt_get(ctx, prt_url_pt(od, do, off), 'pt'))
        r, n, z, dalej = parse_prt_pt(j)
        for cid, rows in r.items():
            R.setdefault(cid, {}).update(rows)
        nz += n; zle.update(z)
        if not dalej:
            return R, nz, zle
        off += len(j.get('features') or [])
    raise RuntimeError(f'więcej niż {PRT_STRON} strony wyników')


def _prt_pobierz_pt(ctx):
    now = ctx['now']
    od = (now.date() - datetime.timedelta(days=PRT_D + PRT_OKNO - 1 + PRT_OPOZN)).isoformat()
    R, nz, zle = _prt_pt_zap(ctx, od, None)
    if not R:
        raise RuntimeError('brak wierszy portów' + (f' (zmieniona numeracja: {", ".join(sorted(zle))})' if zle else ''))
    last = max(max(r) for r in R.values())
    a = (datetime.date.fromisoformat(last) - datetime.timedelta(days=PRT_ROK + PRT_OKNO - 1)).isoformat()
    b = (datetime.date.fromisoformat(last) - datetime.timedelta(days=PRT_ROK)).isoformat()
    Y, nz2, zle2 = _prt_pt_zap(ctx, a, b)
    zle |= zle2
    if zle:
        ctx['bledy'].append('pt: identyfikatory z inną nazwą (pominięte): ' + ', '.join(sorted(zle)))
    braki = [cid for cid, _p, _n in PRT_PORTY if cid not in R]
    if braki:
        ctx['bledy'].append('pt: brak portów: ' + ', '.join(braki))
    if nz + nz2:
        n = nz + nz2
        ctx['uwagi'].append(f'pt: {n} {_sz_odm(n, "wiersz", "wiersze", "wierszy")} z ładunkami większymi niż suma')
    part = prt_pt(R, Y, nz + nz2)
    ctx['parts']['pt'] = part
    return part['asof']


PRT_POBIERZ = {'sw': _prt_pobierz_sw, 'pt': _prt_pobierz_pt}


def build_porty(prev=None, now=None, fetch=None, budzet_s=None, run_t0=None):
    """v393: data/porty.json. Każda część z własną bramką (_prt_due) i budżetem czasu; część z błędem — poprzednia część z datą (ok False, krótki zamaskowany błąd err); część bez
    próby — 'cached' (z danymi) albo False (jeszcze nie pobrana). Plik innej wersji = start od zera. Błąd częściowy (źródło odpowiedziało, ale czegoś zabrakło — np. jednego portu)
    — ok False i pole cz = {część: True} (tylko w przebiegu z taką próbą): strona mówi „część danych niedostępna”, nie „pobranie się nie udało”."""
    now = now or _now_utc()
    now_iso = now.replace(microsecond=0).isoformat()
    prev = prev if isinstance(prev, dict) and prev.get('v') == PRT_V else {}
    st = json.loads(json.dumps(prev.get('st'))) if isinstance(prev.get('st'), dict) else {}
    ctx = {'now': now, 'bledy': [], 'uwagi': [], 'parts': {}, 't0': time.monotonic(),
           'budzet': PRT_BUDZET_S if budzet_s is None else budzet_s,
           'fetch': fetch or (lambda url, timeout, headers=None: get_bytes(url, headers, timeout=timeout))}
    late = run_t0 is not None and time.monotonic() - run_t0 > BACK_LATE
    proby, zle, pominiete, czesc = {p: 0 for p in PRT_PARTS}, {}, [], set()
    for part in PRT_PARTS:
        z = st.setdefault(part, {})
        if not _prt_due(z, now):
            continue
        if late:
            pominiete.append(f'{part} (długi przebieg)'); continue
        if time.monotonic() - ctx['t0'] + PRT_ZAPYTANIA[part] * PRT_LIMIT_S[part] > ctx['budzet']:
            pominiete.append(f'{part} (budżet czasu)'); continue
        nb = len(ctx['bledy'])
        z['try'] = now_iso
        proby[part] += 1
        try:
            asof = PRT_POBIERZ[part](ctx)
        except Exception as e:
            msg = mask(f'{part}: {e}')[:160]
            z['err'] = msg; zle.setdefault(part, []).append(msg)
            continue
        z['at'] = now_iso; z['asof'] = asof; z.pop('err', None)
        if len(ctx['bledy']) > nb:
            zle.setdefault(part, []).extend(mask(x)[:160] for x in ctx['bledy'][nb:])
            czesc.add(part)
    out = {'v': PRT_V, 'at': None, 'src': 'CapitalFlowAI — porty świata (kod źródła: pw — pełna nazwa na stronie Źródła)'}
    pat = dict(prev.get('part_at') or {}) if isinstance(prev.get('part_at'), dict) else {}
    perr = dict(prev.get('err') or {}) if isinstance(prev.get('err'), dict) else {}
    ok = {}
    for p in PRT_PARTS:
        if p in ctx['parts']:
            out[p] = ctx['parts'][p]; pat[p] = now_iso
        elif isinstance(prev.get(p), dict):
            out[p] = prev[p]
        if zle.get(p):
            ok[p] = False; perr[p] = '; '.join(zle[p])[:240]
        elif proby[p]:
            ok[p] = True; perr.pop(p, None)
        else:
            ok[p] = 'cached' if isinstance(out.get(p), dict) else False
            if not isinstance(out.get(p), dict) and p not in perr:
                perr[p] = 'brak danych (źródło jeszcze nie pobrane)'
    out['part_at'] = {p: pat[p] for p in PRT_PARTS if pat.get(p) and isinstance(out.get(p), dict)}
    out['at'] = max(out['part_at'].values()) if out['part_at'] else (prev.get('at') or now_iso)
    out.update({'ok': ok, 'err': {p: perr[p] for p in PRT_PARTS if perr.get(p)},
                'next': {p: _prt_next((out.get(p) or {}).get('asof'), now) for p in PRT_PARTS}, 'st': st})
    if czesc:
        out['cz'] = {p: True for p in PRT_PARTS if p in czesc}
    for x in ctx['uwagi']:
        META['notes'].append(mask('porty: ' + x)[:200])
    for p in PRT_PARTS:
        for x in zle.get(p, []):
            META['errors'].append(mask('porty ' + x)[:200])
    if pominiete:
        META['notes'].append('porty: pominięte w tym przebiegu — ' + ', '.join(pominiete))
    return out


