CTW_CN_STARE = 20              # dni — ostatnia sesja krzywej / Shibor starsza = błąd części (z historii CSI 2021–2026 najdłuższa przerwa między sesjami to 11 dni: Złoty Tydzień, Nowy Rok księżycowy)
CTW_CSI_STARE = 20
CTW_TW_STARE = 20              # dni — ostatnia sesja Tajwanu (najdłuższa przerwa: Nowy Rok księżycowy, 12 dni z weekendami)
CTW_STRONY = 3                 # strony dnia krzywej (terminy do 41 lat; 30 lat jest na stronie 3)
CTW_Y = (0.0, 12.0)            # % — rentowność / Shibor poza przedziałem = błąd odczytu (Chiny 2021–2026: 0,6–4 %)
CTW_TW_INST_NAZWY = {'自營商': 'd', '投信': 't', '外資及陸資': 'f'}   # dealerzy, krajowe fundusze (investment trust), zagraniczni i z Chin kontynentalnych
CTW_TW_MAX = 2e7               # mln TWD — wartość pozycji jednej grupy poza ±tym = błąd odczytu (zmierzone: do 1,4 bln TWD = 1,4e6 mln)
CTW_HK_PROB = 16               # prób pobrania pliku dnia na dobę (okno ma 7 h, rytm co ok. 30–40 min)
CTW_HK_OKNO = (16 * 60 + 40, 23 * 60 + 55)   # minuty doby czasu Hongkongu (UTC+8): od 16:40 do 23:55
CTW_HK_OBROT = (2e9, 3e12)     # HKD — obrót rynku w dniu poza przedziałem = błąd odczytu (dzień typowy 0,1–0,4 bln)
CTW_HK_MAXUDZ = 0.6            # udział krótkiej sprzedaży w obrocie powyżej = błąd odczytu (zmierzone ok. 10–20 %)
CTW_SRC = ('CapitalFlowAI — Chiny: krzywa rentowności obligacji skarbowych i Shibor; Tajwan: put/call i pozycje inwestorów w kontraktach; Hongkong: udział krótkiej sprzedaży w obrocie; '
           'indeks CSI 300; publiczne dane urzędowe i giełdowe, dzień danych przy każdej części')
ZRODLA_META.update({'chtw_cn': 'chinamoney', 'chtw_sh': 'chinamoney', 'chtw_tw': 'taifex', 'chtw_hk': 'hkex', 'chtw_csi': 'csindex'})   # v400: HKEX jest już źródłem (Stock Connect); +3 źródła: rynek międzybankowy Chin, giełda kontraktów Tajwanu, dostawca indeksów Chin
import zlib as _ctw_zlib   # v400: rozpakowanie odpowiedzi skompresowanej mimo braku prośby (biblioteka standardowa; ponowny import jest nieszkodliwy)
_CTW_T0 = [None]
_CTW_MIES = {m: i + 1 for i, m in enumerate(('JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'))}
_CTW_DNI = ('MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY')


def ctw_get(url, maks):
    """Jedno zapytanie GET (publiczne, bez klucza) z odstępem CTW_SLEEP, limitem czasu (CTW_TIMEOUT, nie więcej niż reszta budżetu budowy) i limitem rozmiaru `maks` B (dłuższa odpowiedź = błąd);
    odpowiedź skompresowana (gzip) bez prośby jest rozpakowywana z tym samym limitem."""
    t0 = _CTW_T0[0]
    lim = CTW_TIMEOUT
    if t0 is not None:
        left = CTW_LIMIT_S - (time.monotonic() - t0)
        if left < 3:
            raise RuntimeError(f'limit czasu budowy ({CTW_LIMIT_S} s)')
        lim = max(3, min(CTW_TIMEOUT, left))
    time.sleep(CTW_SLEEP)
    b = get_bytes_maks(url, timeout=lim, maks=maks)
    if b[:2] == b'\x1f\x8b':
        d = _ctw_zlib.decompressobj(16 + _ctw_zlib.MAX_WBITS)
        b = d.decompress(b, maks + 1)
        if len(b) > maks:
            raise RuntimeError(f'odpowiedź dłuższa niż {maks} B (limit)')
        if not d.eof:
            raise RuntimeError('odpowiedź skompresowana jest ucięta albo uszkodzona')
    return b


def ctw_json(raw):
    """Odpowiedź → obiekt JSON; HTML (strona błędu / odmowy) albo ucięty tekst = ValueError."""
    try:
        return json.loads(raw.decode('utf-8') if isinstance(raw, (bytes, bytearray)) else raw)
    except ValueError:
        raise ValueError('odpowiedź nie jest JSON (strona błędu albo odmowa)') from None


def ctw_liczba(x, lo, hi, co):
    """Liczba skończona z liczby albo tekstu dziesiętnego (bez przecinków tysięcy) w przedziale [lo, hi]; wartość logiczna, brak („---”, pusty tekst), NaN i poza przedziałem = ValueError."""
    if isinstance(x, bool):
        raise ValueError(f'{co}: wartość logiczna')
    try:
        v = float(x.strip()) if isinstance(x, str) else float(x)
    except (TypeError, ValueError, AttributeError):
        raise ValueError(f'{co}: nie liczba ({str(x)[:12]!r})') from None
    if v != v or v in (float('inf'), float('-inf')) or not lo <= v <= hi:
        raise ValueError(f'{co}: poza zakresem ({v})')
    return v


def ctw_dzien(s, fmt, dzis, co):
    """Dzień z tekstu w układzie fmt ('iso' RRRR-MM-DD albo 'cyfry' RRRRMMDD) → date; zły zapis, nieistniejący dzień albo więcej niż dzień po dniu przebiegu = ValueError."""
    ok = isinstance(s, str) and re.fullmatch(r'\d{4}-\d{2}-\d{2}' if fmt == 'iso' else r'\d{8}', s)
    if not ok:
        raise ValueError(f'{co}: zły dzień {str(s)[:12]!r}')
    try:
        d = datetime.date.fromisoformat(s if fmt == 'iso' else f'{s[:4]}-{s[4:6]}-{s[6:]}')
    except ValueError:
        raise ValueError(f'{co}: nieistniejący dzień {s[:10]!r}') from None
    if d > dzis + datetime.timedelta(days=1):
        raise ValueError(f'{co}: dzień {d} z przyszłości')
    return d


def ctw_scal(stare, nowe, ile=None):
    """Historia wierszy [dzień, …]: wiersze `nowe` zastępują stare z tym samym dniem, wynik rosnąco wg dnia, najwyżej `ile` ostatnich (domyślnie CTW_KEEP); wiersz o złym kształcie jest pomijany."""
    m = {}
    for r in list(stare or []) + list(nowe or []):
        if isinstance(r, (list, tuple)) and r and isinstance(r[0], str):
            m[r[0]] = list(r)
    return [m[k] for k in sorted(m)][-(ile or CTW_KEEP):]


# ---------------------------------------------------------------- cn, sh: rynek międzybankowy Chin ----------------------------------------------------------------
def ctw_cm_strona(raw, dzis):
    """Strona wyników krzywej → (lista (dzień, termin w latach, rentowność albo None), liczba wierszy razem). Zły kształt albo kod odpowiedzi ≠ 200 = ValueError. Rentowność „---” = None."""
    j = ctw_json(raw)
    h = j.get('head') if isinstance(j, dict) else None
    d = j.get('data') if isinstance(j, dict) else None
    rec = j.get('records') if isinstance(j, dict) else None
    if not (isinstance(h, dict) and str(h.get('rep_code')) == '200' and isinstance(d, dict) and isinstance(rec, list)):
        raise ValueError('krzywa Chin: odpowiedź ma zły kształt')
    tot = d.get('total')
    if not (isinstance(tot, int) and not isinstance(tot, bool) and 0 <= tot <= 20000):
        raise ValueError('krzywa Chin: zła liczba wierszy')
    out = []
    for r in rec:
        if not isinstance(r, dict):
            raise ValueError('krzywa Chin: wiersz ma zły kształt')
        dz = ctw_dzien(r.get('newDateValueCN'), 'iso', dzis, 'krzywa Chin')
        tm = ctw_liczba(r.get('yearTermStr'), 0.01, 60, 'krzywa Chin: termin')
        yr = r.get('maturityYieldStr')
        y = None if isinstance(yr, str) and yr.strip() in ('---', '') else ctw_liczba(yr, CTW_Y[0], CTW_Y[1], 'krzywa Chin: rentowność')
        out.append((dz, tm, y))
    return out, tot


def ctw_cm_najnowsza(dzis, dni_wstecz, koniec=None):
    """Najnowszy dzień z danymi krzywej w oknie [koniec − dni_wstecz, koniec] (koniec domyślnie dzień przebiegu): jedno zapytanie, pierwsza strona (źródło sortuje dni malejąco); okno bez danych = ValueError."""
    koniec = koniec or dzis
    a = koniec - datetime.timedelta(days=dni_wstecz)
    rows, tot = ctw_cm_strona(ctw_get(CTW_CM_KRZYWA.format(a=a.isoformat(), b=koniec.isoformat(), p=1), CTW_MAXB['cm']), dzis)
    if not rows or tot <= 0:
        raise ValueError(f'krzywa Chin: brak danych w oknie {a}…{koniec}')
    d = max(r[0] for r in rows)
    if d != rows[0][0] or d > koniec:
        raise ValueError('krzywa Chin: pierwsza strona nie zaczyna się od najnowszego dnia')
    return d


def ctw_cm_doba(d, dzis):
    """Krzywa jednego dnia → {etykieta: rentowność %} dla terminów CTW_LAB: trzy strony po 15 wierszy tego dnia (terminy rosnące bez powtórzeń, razem co najmniej 45 wierszy); brak terminu albo rentowności = ValueError."""
    terminy = {}
    ost = 0.0
    for p in range(1, CTW_STRONY + 1):
        rows, tot = ctw_cm_strona(ctw_get(CTW_CM_KRZYWA.format(a=d.isoformat(), b=d.isoformat(), p=p), CTW_MAXB['cm']), dzis)
        if tot < 15 * CTW_STRONY or len(rows) != 15:
            raise ValueError(f'krzywa Chin {d}: strona {p} ma {len(rows)} wierszy z {tot}')
        for dz, tm, y in rows:
            if dz != d:
                raise ValueError(f'krzywa Chin {d}: wiersz z dnia {dz}')
            if tm <= ost:
                raise ValueError(f'krzywa Chin {d}: terminy nie rosną ({ost} → {tm})')
            ost = tm
            terminy[tm] = y
    o = {}
    for lab, tm in CTW_LAB:
        y = terminy.get(tm)
        if y is None:
            raise ValueError(f'krzywa Chin {d}: brak rentowności {lab}')
        o[lab] = round(y, 4)
    if abs(o['10Y'] - o['2Y']) > 5:
        raise ValueError(f'krzywa Chin {d}: nachylenie 10 lat − 2 lata poza zakresem')
    return o


def ctw_cn(pk, now):
    """Część cn: krzywa najnowszego dnia i sprzed miesiąca + historia 2/5/10/30 lat. Bez nowego dnia w źródle — jedno zapytanie i poprzednia część."""
    dzis = now.date()
    L = ctw_cm_najnowsza(dzis, 10)
    if (dzis - L).days > CTW_CN_STARE:
        raise ValueError(f'krzywa Chin: ostatni dzień {L} sprzed {(dzis - L).days} dni (źródło stoi)')
    pk = pk if isinstance(pk, dict) else {}
    if pk.get('asof') == L.isoformat() and isinstance(pk.get('now'), dict) and set(pk['now']) == {l for l, _ in CTW_LAB}:
        return pk
    now_c = ctw_cm_doba(L, dzis)
    pas, prev_c = None, None
    try:
        P = ctw_cm_najnowsza(dzis, 10, koniec=L - datetime.timedelta(days=30))
        prev_c = ctw_cm_doba(P, dzis)
        pas = P.isoformat()
    except Exception as e:  # noqa — krzywa sprzed miesiąca jest dodatkiem: bez niej krzywa dnia zostaje, wiek poprzedniej oceni strona
        META['notes'].append(mask(f'{CTW_PX}: krzywa sprzed miesiąca niedostępna ({str(e)[:100]})')[:200])
        if isinstance(pk.get('prev'), dict) and isinstance(pk.get('pasof'), str) and (L - datetime.date.fromisoformat(pk['pasof'])).days <= 45:
            prev_c, pas = pk['prev'], pk['pasof']
    h = ctw_scal(pk.get('h'), [[L.isoformat(), now_c['2Y'], now_c['5Y'], now_c['10Y'], now_c['30Y']]])
    return {'asof': L.isoformat(), 'now': now_c, 'pasof': pas, 'prev': prev_c, 'h': h}


def ctw_sh(pk, now):
    """Część sh: Shibor ośmiu terminów z ostatnich 28 dni (jedno zapytanie), historia dokładana wg dnia."""
    dzis = now.date()
    a = dzis - datetime.timedelta(days=28)
    j = ctw_json(ctw_get(CTW_CM_SHIBOR.format(a=a.isoformat(), b=dzis.isoformat()), CTW_MAXB['cm']))
    hd = j.get('head') if isinstance(j, dict) else None
    rec = j.get('records') if isinstance(j, dict) else None
    if not (isinstance(hd, dict) and str(hd.get('rep_code')) == '200' and isinstance(rec, list) and rec):
        raise ValueError('Shibor: odpowiedź ma zły kształt albo jest pusta')
    nowe, widziane = [], set()
    for r in rec:
        if not isinstance(r, dict):
            raise ValueError('Shibor: wiersz ma zły kształt')
        dz = ctw_dzien(r.get('showDateCN'), 'iso', dzis, 'Shibor')
        if dz in widziane:
            raise ValueError(f'Shibor: dzień {dz} powtórzony')
        widziane.add(dz)
        nowe.append([dz.isoformat()] + [round(ctw_liczba(r.get(k), CTW_Y[0], CTW_Y[1], f'Shibor {k}'), 4) for k in CTW_SHIBOR])
    nowe.sort()
    L = datetime.date.fromisoformat(nowe[-1][0])
    if (dzis - L).days > CTW_CN_STARE:
        raise ValueError(f'Shibor: ostatni dzień {L} sprzed {(dzis - L).days} dni (źródło stoi)')
    pk = pk if isinstance(pk, dict) else {}
    return {'asof': L.isoformat(), 'h': ctw_scal(pk.get('h'), nowe)}


# ---------------------------------------------------------------- tw: Tajwan ----------------------------------------------------------------
def ctw_tw_pc(raw, dzis):
    """Put/call z odpowiedzi giełdy kontraktów → wiersze [dzień, wolumen opcji sprzedaży, wolumen opcji kupna, otwarte pozycje sprzedaży, otwarte pozycje kupna] rosnąco wg dnia.
    Co najmniej 10 sesji, dni bez powtórzeń, liczby całkowite ≥ 0, opcji kupna > 0, podane stosunki (%) = sprzedaż / kupno ± 0,06 p. proc. — inaczej ValueError."""
    j = ctw_json(raw)
    if not (isinstance(j, list) and len(j) >= 10):
        raise ValueError('Tajwan put/call: odpowiedź ma zły kształt albo mało sesji')
    out, widziane = [], set()
    for r in j:
        if not isinstance(r, dict):
            raise ValueError('Tajwan put/call: wiersz ma zły kształt')
        d = ctw_dzien(r.get('Date'), 'cyfry', dzis, 'Tajwan put/call')
        if d in widziane:
            raise ValueError(f'Tajwan put/call: dzień {d} powtórzony')
        widziane.add(d)
        pv, cv, po, co = (int(ctw_liczba(r.get(k), 0, 5e8, f'Tajwan {k}')) for k in ('PutVolume', 'CallVolume', 'PutOI', 'CallOI'))
        if cv <= 0 or co <= 0:
            raise ValueError(f'Tajwan put/call {d}: zero opcji kupna')
        for rep, a, b, nm in (('PutCallVolumeRatio%', pv, cv, 'wolumen'), ('PutCallOIRatio%', po, co, 'otwarte pozycje')):
            if abs(ctw_liczba(r.get(rep), 0, 1e5, f'Tajwan {rep}') - a / b * 100) > 0.06:
                raise ValueError(f'Tajwan put/call {d}: stosunek ({nm}) nie zgadza się z liczbami')
        out.append([d.isoformat(), pv, cv, po, co])
    out.sort()
    return out


def ctw_tw_inst(raw, dzis):
    """Pozycje trzech grup inwestorów w kontraktach terminowych razem (jedna sesja) → (dzień, {grupa: [pozycja netto w kontraktach, netto wartość otwartych pozycji, wartość długich, wartość krótkich, netto wartość obrotu,
    netto kontrakty obrotu]}) w kontraktach i mln TWD. Nazwy grup muszą być dokładnie trzy znane, jeden dzień; netto = długie − krótkie (± 1) — inaczej ValueError."""
    j = ctw_json(raw)
    if not (isinstance(j, list) and len(j) == 3 and all(isinstance(r, dict) for r in j)):
        raise ValueError('Tajwan pozycje: odpowiedź ma zły kształt')
    dni = {r.get('Date') for r in j}
    if len(dni) != 1:
        raise ValueError('Tajwan pozycje: wiersze z różnych dni')
    d = ctw_dzien(next(iter(dni)), 'cyfry', dzis, 'Tajwan pozycje')
    g = {}
    for r in j:
        k = CTW_TW_INST_NAZWY.get(r.get('Item'))
        if k is None or k in g:
            raise ValueError('Tajwan pozycje: nieznana albo powtórzona grupa inwestorów')
        v = {n: int(ctw_liczba(r.get(n), -CTW_TW_MAX, CTW_TW_MAX, f'Tajwan {n}')) for n in (
            'TradingVolume(Long)', 'TradingVolume(Short)', 'TradingVolume(Net)', 'TradingValue(Long)(Millions)', 'TradingValue(Short)(Millions)', 'TradingValue(Net)(Millions)',
            'OpenInterest(Long)', 'OpenInterest(Short)', 'OpenInterest(Net)', 'ContractValueOfOpenInterest(Long)(Millions)', 'ContractValueOfOpenInterest(Short)(Millions)',
            'ContractValueOfOpenInterest(Net)(Millions)')}
        for a, b, c in (('TradingVolume(Long)', 'TradingVolume(Short)', 'TradingVolume(Net)'), ('TradingValue(Long)(Millions)', 'TradingValue(Short)(Millions)', 'TradingValue(Net)(Millions)'),
                        ('OpenInterest(Long)', 'OpenInterest(Short)', 'OpenInterest(Net)'),
                        ('ContractValueOfOpenInterest(Long)(Millions)', 'ContractValueOfOpenInterest(Short)(Millions)', 'ContractValueOfOpenInterest(Net)(Millions)')):
            if abs(v[a] - v[b] - v[c]) > 1:
                raise ValueError(f'Tajwan pozycje {k}: netto ≠ długie − krótkie ({c})')
        g[k] = [v['OpenInterest(Net)'], v['ContractValueOfOpenInterest(Net)(Millions)'], v['ContractValueOfOpenInterest(Long)(Millions)'],
                v['ContractValueOfOpenInterest(Short)(Millions)'], v['TradingValue(Net)(Millions)'], v['TradingVolume(Net)']]
    return d, g


def ctw_tw(pk, now):
    """Część tw: put/call (20 sesji, historia dokładana wg dnia) i pozycje trzech grup inwestorów (ostatnia sesja + historia od wdrożenia)."""
    dzis = now.date()
    pk = pk if isinstance(pk, dict) else {}
    pc = ctw_tw_pc(ctw_get(CTW_TW_PC, CTW_MAXB['tw']), dzis)
    di, g = ctw_tw_inst(ctw_get(CTW_TW_INST, CTW_MAXB['tw']), dzis)
    L = datetime.date.fromisoformat(pc[-1][0])
    if (dzis - L).days > CTW_TW_STARE or (dzis - di).days > CTW_TW_STARE:
        raise ValueError(f'Tajwan: ostatnia sesja {min(L, di)} sprzed {(dzis - min(L, di)).days} dni (źródło stoi)')
    pi = pk.get('in') if isinstance(pk.get('in'), dict) else {}
    ph = pk.get('pc') if isinstance(pk.get('pc'), dict) else {}
    return {'pc': {'asof': L.isoformat(), 'h': ctw_scal(ph.get('h'), pc)},
            'in': {'asof': di.isoformat(), 'g': g, 'h': ctw_scal(pi.get('h'), [[di.isoformat(), g['d'][1], g['t'][1], g['f'][1]]])}}


# ---------------------------------------------------------------- hk: Hongkong, krótka sprzedaż ----------------------------------------------------------------
def ctw_hk_okno(now):
    """Czas przebiegu (UTC) → dzień Hongkongu (date), gdy trwa okno pobierania pliku dnia (dzień roboczy Hongkongu, 16:40–23:55 jego czasu, UTC+8), inaczej None."""
    hk = now.astimezone(datetime.timezone(datetime.timedelta(hours=8)))
    m = hk.hour * 60 + hk.minute
    return hk.date() if hk.weekday() < 5 and CTW_HK_OKNO[0] <= m <= CTW_HK_OKNO[1] else None


def _ctw_hk_blok(linie, i0, i1, co):
    """Blok (A), (B) albo (C) pliku: akcje (liczba, wartość w HKD), obrót rynku i podany udział w % — każda pozycja dokładnie raz, inaczej ValueError."""
    t = '\n'.join(linie[i0:i1])
    out = []
    for rx in (r'Short Selling Turnover Total Shares \(SH\)\s*:\s*([\d,]+)', r'Short Selling Turnover Total Value \(\$\)\s*:\s*HKD\s*([\d,]+)',
               r'Total market turnover\s*:\s*HKD\s*([\d,]+)', r'as % total turnover\s*:\s*(\d{1,3})%'):
        m = re.findall(rx, t)
        if len(m) != 1:
            raise ValueError(f'krótka sprzedaż {co}: pozycja „{rx[:40]}” {len(m)} razy zamiast raz')
        out.append(int(m[0].replace(',', '')))
    return out


def parse_ctw_hk(raw, dzien_hk):
    """Plik dnia krótkiej sprzedaży (HTML z tekstem stałej szerokości) → None, gdy pliku dnia jeszcze nie ma (zdanie „będzie dostępny po zamknięciu” albo plik z wcześniejszego dnia), albo wiersz
    [dzień, akcje bez ETP mln HKD, fundusze ETP mln HKD, obrót rynku mln HKD, liczba papierów]. Zmieniony układ, dzień z przyszłości, zły dzień tygodnia, sumy niezgodne (akcje + ETP = razem, udział
    = razem / obrót ± 1 p. proc.) albo liczby poza zakresem = ValueError."""
    text = raw.decode('latin-1') if isinstance(raw, (bytes, bytearray)) else str(raw)
    m = re.search(r'TRADING DATE\s*:\s*(\d{1,2}) ([A-Z]{3}) (\d{4}) \(([A-Z]+)\)', text)
    if not m:
        if 'will be available after' in text and 'SHORTSELL REPORT' not in text:
            return None
        raise ValueError('krótka sprzedaż: brak daty sesji i brak zdania o dostępności (zmieniony układ?)')
    if 'Short Selling Turnover (Main Board) up to day close today' not in text:
        raise ValueError('krótka sprzedaż: inny tytuł pliku')
    try:
        d = datetime.date(int(m.group(3)), _CTW_MIES[m.group(2)], int(m.group(1)))
    except (KeyError, ValueError):
        raise ValueError('krótka sprzedaż: zła data sesji') from None
    if _CTW_DNI[d.weekday()] != m.group(4):
        raise ValueError('krótka sprzedaż: dzień tygodnia nie zgadza się z datą')
    if d > dzien_hk:
        raise ValueError(f'krótka sprzedaż: sesja {d} z przyszłości')
    if d < dzien_hk:
        return None
    L = text.split('\n')
    idx = {}
    for i, s in enumerate(L):
        mm = re.match(r'\(([ABC])\) Short Selling of ', s)
        if mm:
            if mm.group(1) in idx:
                raise ValueError('krótka sprzedaż: powtórzony blok')
            idx[mm.group(1)] = i
    if set(idx) != {'A', 'B', 'C'} or not idx['A'] < idx['B'] < idx['C']:
        raise ValueError('krótka sprzedaż: brak bloków (A), (B), (C)')
    kon = next((i for i in range(idx['C'] + 1, len(L)) if L[i].startswith('*Total No.')), len(L))
    A = _ctw_hk_blok(L, idx['A'], idx['B'], '(A)')
    B = _ctw_hk_blok(L, idx['B'], idx['C'], '(B)')
    C = _ctw_hk_blok(L, idx['C'], kon, '(C)')
    if not (A[2] == B[2] == C[2] and CTW_HK_OBROT[0] <= A[2] <= CTW_HK_OBROT[1]):
        raise ValueError('krótka sprzedaż: obrót rynku różny w blokach albo poza zakresem')
    if A[1] < 0 or B[1] < 0 or abs(A[1] + B[1] - C[1]) > max(1000, C[1] * 1e-4):
        raise ValueError('krótka sprzedaż: akcje + fundusze ETP ≠ razem')
    tot = A[2]
    if C[1] > tot * CTW_HK_MAXUDZ or abs(C[1] / tot * 100 - C[3]) > 1.0 or abs(A[1] / tot * 100 - A[3]) > 1.0 or abs(B[1] / tot * 100 - B[3]) > 1.0:
        raise ValueError('krótka sprzedaż: udział w obrocie nie zgadza się z podanym')
    n = re.findall(r'Total No\. of all Securities recording Short Selling\s*:\s*(\d+)', text)
    if len(n) != 1 or not 0 < int(n[0]) <= 4000:
        raise ValueError('krótka sprzedaż: liczba papierów z krótką sprzedażą')
    return [d.isoformat(), round(A[1] / 1e6), round(B[1] / 1e6), round(tot / 1e6), int(n[0])]


def ctw_hk(pk, now):
    """Część hk: w oknie dnia Hongkongu jedno zapytanie o plik dnia (najwyżej CTW_HK_PROB prób na dobę); plik jeszcze niegotowy = część bez zmian z zapisaną próbą (to nie błąd)."""
    pk = pk if isinstance(pk, dict) else {}
    dz = ctw_hk_okno(now)
    h = [r for r in (pk.get('h') or []) if isinstance(r, list)]
    prob = pk.get('try') if isinstance(pk.get('try'), list) and len(pk['try']) == 2 else [None, 0]
    if dz is None or (h and h[-1][0] == dz.isoformat()):
        return pk if pk else {'asof': None, 'h': [], 'try': [None, 0]}
    n = prob[1] + 1 if prob[0] == dz.isoformat() else 1
    if n > CTW_HK_PROB:
        return pk
    w = parse_ctw_hk(ctw_get(CTW_HK_URL, CTW_MAXB['hk']), dz)
    return {'asof': (w[0] if w else pk.get('asof')), 'h': ctw_scal(h, [w] if w else []), 'try': [dz.isoformat(), n]}


# ---------------------------------------------------------------- csi: indeks CSI 300 ----------------------------------------------------------------
def parse_ctw_csi(raw, now):
    """Odpowiedź o indeksie CSI 300 → wiersze [dzień, zamknięcie, zmiana %] rosnąco: okno zaczynające się w święto podstawia w pierwszym wierszu dane następnej sesji — ciąg wierszy o tych samych
    cenach i wolumenie zostawia ostatni; dzisiejszy wiersz przed 16:30 czasu Chin (sesja trwa) odpada; zamknięcie − poprzednie zamknięcie = zmiana w wierszu (± 0,02 p. proc. po zaokrągleniu).
    Zły kod, inny indeks, ceny niespójne (niskie ≤ otwarcie, zamknięcie ≤ wysokie) albo poza zakresem, mało sesji — ValueError."""
    dzis = now.date()
    j = ctw_json(raw)
    d = j.get('data') if isinstance(j, dict) else None
    if not (isinstance(j, dict) and str(j.get('code')) == '200' and isinstance(d, list) and len(d) >= 20):
        raise ValueError('CSI 300: odpowiedź ma zły kształt albo mało sesji')
    rows, widziane = [], set()
    for r in d:
        if not isinstance(r, dict) or r.get('indexCode') != '000300':
            raise ValueError('CSI 300: inny indeks albo zły wiersz')
        dz = ctw_dzien(r.get('tradeDate'), 'cyfry', dzis, 'CSI 300')
        if dz in widziane:
            raise ValueError(f'CSI 300: dzień {dz} powtórzony')
        widziane.add(dz)
        o, h, l, c = (ctw_liczba(r.get(k), 500, 20000, f'CSI 300 {k}') for k in ('open', 'high', 'low', 'close'))
        if not (l <= min(o, c) and max(o, c) <= h):
            raise ValueError(f'CSI 300 {dz}: ceny niespójne')
        vol = ctw_liczba(r.get('tradingVol'), 1e8, 1e12, 'CSI 300 wolumen')
        rows.append((dz, (o, h, l, c, vol), c, ctw_liczba(r.get('changePct'), -15, 15, 'CSI 300 zmiana %')))
    rows.sort(key=lambda x: x[0])
    sc = []
    for r in rows:   # ciąg tych samych cen i wolumenu = podstawienie na początku okna w święto: zostaje ostatni wiersz ciągu (prawdziwa sesja)
        if sc and sc[-1][1] == r[1]:
            sc[-1] = r
        else:
            sc.append(r)
    cst = now.astimezone(datetime.timezone(datetime.timedelta(hours=8)))
    if sc and sc[-1][0] == cst.date() and cst.hour * 60 + cst.minute < 16 * 60 + 30:
        sc.pop()
    if len(sc) < 15:
        raise ValueError('CSI 300: za mało sesji po oczyszczeniu')
    for a, b in zip(sc, sc[1:]):
        if abs((b[2] / a[2] - 1) * 100 - b[3]) > 0.02:
            raise ValueError(f'CSI 300 {b[0]}: zamknięcie nie zgadza się ze zmianą w wierszu')
    return [[r[0].isoformat(), round(r[2], 2), round(r[3], 2)] for r in sc]


def ctw_csi(pk, now):
    """Część csi: okno 75 dni jednym zapytaniem, wiersze dokładane wg dnia (nowe zastępują stare)."""
    dzis = now.date()
    a = dzis - datetime.timedelta(days=75)
    nowe = parse_ctw_csi(ctw_get(CTW_CSI_URL.format(a=a.strftime('%Y%m%d'), b=dzis.strftime('%Y%m%d')), CTW_MAXB['csi']), now)
    L = datetime.date.fromisoformat(nowe[-1][0])
    if (dzis - L).days > CTW_CSI_STARE:
        raise ValueError(f'CSI 300: ostatnia sesja {L} sprzed {(dzis - L).days} dni (źródło stoi)')
    pk = pk if isinstance(pk, dict) else {}
    return {'asof': L.isoformat(), 'h': ctw_scal(pk.get('h'), nowe)}


# ---------------------------------------------------------------- budowa pliku ----------------------------------------------------------------
CTW_BUDOWA = {'cn': ctw_cn, 'sh': ctw_sh, 'tw': ctw_tw, 'hk': ctw_hk, 'csi': ctw_csi}


def ctw_wymagana(k, pk, pok, pat, now):
    """Czy część k wymaga odczytu: hk — tylko w oknie dnia Hongkongu i bez zapisanego dnia; pozostałe — brak części, poprzedni błąd albo odczyt starszy niż CTW_INT[k] min."""
    if k == 'hk':
        dz = ctw_hk_okno(now)
        h = pk.get('h') if isinstance(pk, dict) and isinstance(pk.get('h'), list) else []
        return dz is not None and not (h and isinstance(h[-1], list) and h[-1][0] == dz.isoformat())
    if not isinstance(pk, dict) or pok.get(k) is False:
        return True
    t = _ix_dt(pat.get(k))
    return t is None or (now - t).total_seconds() >= CTW_INT[k] * 60


def build_chiny_tw(prev=None, run_t0=None):
    """Plik data/chiny-tw.json (v400): pięć części (cn, sh, tw, hk, csi) z własnym ok / part_at / errs; część z błędem zostaje z poprzedniego pliku z własną chwilą, nigdy pusta zamiast ostatnich danych;
    część, której odczyt nie jest jeszcze potrzebny (rytm, okno Hongkongu), zostaje bez zmian z ok 'cached'. Żadna część nie ma danych = wyjątek (przebieg główny zostawia poprzedni plik)."""
    prev = prev if isinstance(prev, dict) and prev.get('v') == CTW_V else {}
    pat, pok = _dict(prev.get('part_at')), _dict(prev.get('ok'))
    now = datetime.datetime.fromisoformat(NOW).astimezone(datetime.timezone.utc)
    out = {'v': CTW_V, 'at': NOW, 'od': prev.get('od') if isinstance(prev.get('od'), str) else now.date().isoformat(), 'src': CTW_SRC, 'ok': {}, 'part_at': {}, 'errs': {}}
    _CTW_T0[0] = time.monotonic()
    try:
        for k in CTW_PARTS:
            pk = prev.get(k) if isinstance(prev.get(k), dict) else None
            if not ctw_wymagana(k, pk, pok, pat, now):
                if pk is not None:
                    out[k] = pk
                    out['part_at'][k] = pat.get(k) or prev.get('at')
                out['ok'][k] = 'cached'
                continue
            try:
                out[k] = CTW_BUDOWA[k](pk, now)
                out['ok'][k] = True
                out['part_at'][k] = NOW
            except Exception as e:  # noqa — część z błędem: poprzednie dane z własną chwilą
                msg = mask(f'{e}')[:160]
                META['errors'].append(mask(f'{CTW_PX} {CTW_LABEL[k]}: {msg}')[:220])
                out['ok'][k] = False
                out['errs'][k] = msg
                if pk is not None:
                    out[k] = pk
                    out['part_at'][k] = pat.get(k) or prev.get('at')
    finally:
        _CTW_T0[0] = None
    if not any(isinstance(out.get(k), dict) for k in CTW_PARTS):
        raise RuntimeError('żadna część nie odpowiedziała')
    return out


# ===================== v410 (F11Z19): KANADA — AUKCJE OBLIGACJI (UDZIAŁ ZAGRANICY), KTO TRZYMA DŁUG, CORRA, BILANS BANKU KANADY, ROPOCIĄGI (data/kanada-dlug.json) =====================
# Pięć niezależnych części jednego pliku, każda z własnym ok / part_at / errs i własną poprzednią wersją przy błędzie (nigdy puste zamiast ostatnich danych); publiczne zapytania GET bez klucza,
# nagłówek zbieracza, odstęp KDL_SLEEP s, limit czasu i rozmiaru KAŻDEGO zapytania, cała budowa KDL_LIMIT_S s. Dwa źródła: interfejs danych banku centralnego Kanady (już liczone) i regulator energii Kanady (nowe).
#   au — wyniki aukcji obligacji rządu Kanady (nominalne): termin, kwota, rentowność, pokrycie (oferty / kwota), tail (pb), udział kont zagranicznych i kanadyjskich w przydziale, udział dystrybutorów;
#        źródło zwraca całą historię (od 1998, ok. 1,4 MB) — bierzemy tylko aukcje z podanym udziałem zagranicy (pole jest od 3.04.2025), do KDL_KEEP['au'] ostatnich; zapowiedzi przyszłych aukcji (bez wyników) pomijane.
#   dr — struktura posiadaczy długu rządu Kanady (tygodniowo, środa; mln CAD): Bank Kanady, konta rządu, rynek (reszta) i ich suma; z rynku bony i obligacje osobno.
#   co — CORRA (stopa overnight repo w dolarach kanadyjskich): stawka, 25. i 75. centyl obrotu, obrót po przycięciu (mld CAD), liczba zgłaszających; dni z opublikowaną stawką.
#   bs — bilans tygodniowy Banku Kanady (środa; mln CAD): aktywa razem, papiery rządowe (bony, obligacje, obligacje indeksowane, obligacje hipoteczne), same obligacje, transakcje z odkupem (aktywa), banknoty,
#        depozyty rządu i depozyty członków systemu płatności (rezerwy banków).
#   rp — przepustowość ropociągów Keystone (Hardisty → USA) i Trans Mountain (Alberta → Zatoka Vancouver / USA): miesięcznie, średnia dobowa w tys. baryłek na dobę (przeliczone z tys. m3), wolna zdolność tego samego miesiąca.
#        Plik regulatora jest uzupełniany z opóźnieniem ok. 2 miesięcy po końcu miesiąca, kwartalnie — w pliku jest miesiąc, a nie dzień.
# Bramki: każda liczba skończona i w zakresie wiarygodności, daty istniejące, nie z przyszłości i rosnące bez powtórzeń, tożsamości księgowe (suma składników = razem: posiadacze długu, aktywa i pasywa
# bilansu, udział zagranicy + kanadyjskich = 100 %, dystrybutorzy + klienci = 100 %), stawka CORRA między 25. a 75. centylem; inny kształt albo brak serii = błąd części (nigdy cicha zmiana liczb).
KDL_V = 1
KDL_PARTS = ('au', 'dr', 'co', 'bs', 'rp')
KDL_LABEL = {'au': 'aukcje obligacji', 'dr': 'posiadacze długu', 'co': 'CORRA', 'bs': 'bilans Banku Kanady', 'rp': 'ropociągi'}
KDL_PX = 'Kanada dług i ropa'
KDL_EVERY_MIN = 30              # min — plik budowany najwyżej co tyle (plik z nieudaną częścią: NIEPELNY_MIN), części mają własne rytmy poniżej
KDL_INT = {'au': 240, 'dr': 360, 'co': 180, 'bs': 360, 'rp': 1440}   # min — odstęp między odczytami części (aukcje: kilka tygodniowo; posiadacze i bilans: raz na tydzień; CORRA: dzienna; plik regulatora: raz na dobę)
KDL_TIMEOUT = 40                # s — jedno zapytanie
KDL_SLEEP = 1.0                 # s — odstęp między zapytaniami
KDL_LIMIT_S = 150               # s — budżet czasu budowy pliku; po nim kolejne części zgłaszają błąd limitu (poprzednie dane zostają)
KDL_MAXB = {'au': 4000000, 'dr': 600000, 'co': 600000, 'bs': 800000, 'rp': 800000}   # B — największa dopuszczalna odpowiedź (zmierzone 17.10.2026: 1,44 MB / 96 kB / 150 kB / 114 kB / 169 kB + 344 kB)
KDL_KEEP = {'au': 80, 'dr': 104, 'co': 260, 'bs': 104, 'rp': 48}   # wierszy historii w części (aukcje; tygodnie; dni z CORRA; tygodnie; miesiące)
KDL_NEW = {'dr': 8, 'co': 15, 'bs': 8}   # ile ostatnich obserwacji prosić, gdy historia już jest (pierwszy odczyt: KDL_KEEP + zapas)
KDL_VALET = 'https://www.bankofcanada.ca/valet/observations/group/'
KDL_AU_URL = KDL_VALET + 'AUC_BOND_RESULTS/json'
KDL_DR_URL = KDL_VALET + 'G4_WEEKLY/json?recent={n}'
KDL_CO_URL = KDL_VALET + 'CORRA_METRICS/json?recent={n}'
KDL_BS_URL = KDL_VALET + 'B2_WEEKLY/json?recent={n}'
KDL_RP_URL = 'https://www.cer-rec.gc.ca/open/energy/throughput-capacity/{p}-throughput-and-capacity.csv'
KDL_AU_OD = '2025-04-03'        # od tej aukcji źródło podaje udział kont zagranicznych (wynik aukcji z tej daty bez udziału = błąd części)
KDL_AU_STARE = 60               # dni — ostatnia aukcja starsza = błąd części (najdłuższa przerwa między aukcjami w latach 2015–2026 to 28 dni; święta 20)
KDL_DR_STARE = 28               # dni — ostatni tydzień posiadaczy długu i bilansu (publikacja co tydzień)
KDL_CO_STARE = 12               # dni — ostatni dzień CORRA (najdłuższa przerwa dni roboczych: 4 dni)
KDL_RP_STARE = 400              # dni od początku ostatniego miesiąca — starsze = błąd części (plik regulatora ma ok. 2 miesiące opóźnienia i uzupełnia się kwartalnie)
KDL_BBL = 6.28981               # baryłek w metrze sześciennym
KDL_TERMY = (2, 3, 5, 7, 10, 30)
KDL_SRC = ('CapitalFlowAI — Kanada: wyniki aukcji obligacji rządu (udział zagranicy), posiadacze długu rządu, stawka CORRA i bilans tygodniowy banku centralnego; przepustowość ropociągów Keystone i Trans Mountain; '
          'publiczne dane urzędowe, dzień (miesiąc) danych przy każdej części')
ZRODLA_META.update({'kandlug_au': 'bank-kanady', 'kandlug_dr': 'bank-kanady', 'kandlug_co': 'bank-kanady', 'kandlug_bs': 'bank-kanady', 'kandlug_rp': 'cer-kanada'})   # v410: bank centralny Kanady już liczony; regulator energii Kanady (+1 źródło)
_KDL_T0 = [None]


def kdl_get(url, maks):
    """Jedno zapytanie GET (publiczne, bez klucza) z odstępem KDL_SLEEP, limitem czasu (KDL_TIMEOUT, nie więcej niż reszta budżetu budowy) i limitem rozmiaru `maks` B (dłuższa odpowiedź = błąd)."""
    t0 = _KDL_T0[0]
    lim = KDL_TIMEOUT
    if t0 is not None:
        left = KDL_LIMIT_S - (time.monotonic() - t0)
        if left < 3:
            raise RuntimeError(f'limit czasu budowy ({KDL_LIMIT_S} s)')
        lim = max(3, min(KDL_TIMEOUT, left))
    time.sleep(KDL_SLEEP)
    return get_bytes_maks(url, timeout=lim, maks=maks)


def kdl_json(raw):
    """Odpowiedź → obiekt JSON; HTML (strona błędu / odmowy) albo ucięty tekst = ValueError."""
    try:
        return json.loads(raw.decode('utf-8') if isinstance(raw, (bytes, bytearray)) else raw)
    except ValueError:
        raise ValueError('odpowiedź nie jest JSON (strona błędu albo odmowa)') from None


def kdl_liczba(x, lo, hi, co):
    """Liczba skończona z tekstu dziesiętnego (albo liczby) w przedziale [lo, hi]; wartość logiczna, brak, NaN i poza przedziałem = ValueError."""
    if isinstance(x, bool):
        raise ValueError(f'{co}: wartość logiczna')
    try:
        v = float(x.strip()) if isinstance(x, str) else float(x)
    except (TypeError, ValueError, AttributeError):
        raise ValueError(f'{co}: nie liczba ({str(x)[:12]!r})') from None
    if v != v or v in (float('inf'), float('-inf')) or not lo <= v <= hi:
        raise ValueError(f'{co}: poza zakresem ({v})')
    return v


def kdl_dzien(s, dzis, co):
    """Dzień RRRR-MM-DD → date; zły zapis, nieistniejący dzień albo więcej niż dzień po dniu przebiegu = ValueError."""
    if not (isinstance(s, str) and re.fullmatch(r'\d{4}-\d{2}-\d{2}', s)):
        raise ValueError(f'{co}: zły dzień {str(s)[:12]!r}')
    try:
        d = datetime.date.fromisoformat(s)
    except ValueError:
        raise ValueError(f'{co}: nieistniejący dzień {s[:10]!r}') from None
    if d > dzis + datetime.timedelta(days=1):
        raise ValueError(f'{co}: dzień {d} z przyszłości')
    return d


def kdl_scal(stare, nowe, ile, klucz=lambda r: r[0]):
    """Historia wierszy: wiersze `nowe` zastępują stare o tym samym kluczu (domyślnie dzień r[0]), wynik rosnąco wg klucza, najwyżej `ile` ostatnich; wiersz o złym kształcie jest pomijany."""
    m = {}
    for r in list(stare or []) + list(nowe or []):
        if isinstance(r, (list, tuple)) and r and isinstance(r[0], str):
            m[klucz(r)] = list(r)
    return [m[k] for k in sorted(m)][-ile:]


def kdl_obs(raw, serie):
    """Odpowiedź interfejsu danych (seriesDetail + observations) → lista obserwacji; brak którejś z wymaganych serii albo inny kształt = ValueError."""
    j = kdl_json(raw)
    sd = j.get('seriesDetail') if isinstance(j, dict) else None
    ob = j.get('observations') if isinstance(j, dict) else None
    if not (isinstance(sd, dict) and isinstance(ob, list) and all(k in sd for k in serie)):
        raise ValueError('odpowiedź ma zły kształt albo brak wymaganej serii')
    return ob


def kdl_v(o, k):
    x = o.get(k) if isinstance(o, dict) else None
    return x.get('v') if isinstance(x, dict) else None


def kdl_stare(asof, dzis, limit, co):
    """Ostatni dzień danych starszy niż limit dni = ValueError (źródło stoi)."""
    d = datetime.date.fromisoformat(asof)
    if (dzis - d).days > limit:
        raise ValueError(f'{co}: ostatni dzień {asof} sprzed {(dzis - d).days} dni (źródło stoi)')


# ---------------------------------------------------------------- au: aukcje obligacji ----------------------------------------------------------------
KDL_AU_S = ('AUC_BOND_AUCTION_DATE', 'AUC_BOND_TERM_YEARS', 'AUC_BOND_AMOUNT', 'AUC_BOND_AVG_YIELD', 'AUC_BOND_COVERAGE', 'AUC_BOND_TAIL',
           'AUC_BOND_PERCENT_ALLOTTED_TO_DISTRIBUTORS', 'AUC_BOND_PERCENT_ALLOTTED_TO_CUSTOMERS', 'AUC_BOND_PERCENT_ALLOTTED_TO_CANADIAN', 'AUC_BOND_PERCENT_ALLOTTED_TO_FOREIGN')


def parse_kdl_au(raw, now):
    """Wyniki aukcji obligacji → wiersze [dzień, termin w latach, kwota mln CAD, rentowność %, pokrycie, tail pb, udział zagranicy %, udział dystrybutorów %] rosnąco wg dnia i terminu.
    Wiersz bez udziału zagranicy to zapowiedź albo aukcja sprzed udostępnienia pola (pomijany) — wynik aukcji od KDL_AU_OD bez udziału = ValueError; identyfikator musi zaczynać się od dnia aukcji,
    termin z listy KDL_TERMY, udział zagranicy + kanadyjskich = 100 % i dystrybutorzy + klienci = 100 % (± 0,1), liczby w zakresach; powtórzony identyfikator, mało aukcji albo zły kształt = ValueError."""
    dzis = now.date()
    rows, ids = [], set()
    for o in kdl_obs(raw, KDL_AU_S):
        if not isinstance(o, dict):
            raise ValueError('aukcje: obserwacja ma zły kształt')
        zag = kdl_v(o, 'AUC_BOND_PERCENT_ALLOTTED_TO_FOREIGN')
        ds = kdl_v(o, 'AUC_BOND_AUCTION_DATE')
        if zag is None:
            if kdl_v(o, 'AUC_BOND_COVERAGE') is not None and isinstance(ds, str) and ds >= KDL_AU_OD:
                raise ValueError(f'aukcje: wynik aukcji {ds[:10]} bez udziału zagranicy')
            continue
        d = kdl_dzien(ds, dzis, 'aukcje')
        bid = o.get('bond_id')
        if not (isinstance(bid, str) and bid.startswith(d.isoformat() + '_')) or bid in ids:
            raise ValueError(f'aukcje: zły albo powtórzony identyfikator {str(bid)[:30]!r}')
        ids.add(bid)
        term = kdl_liczba(kdl_v(o, 'AUC_BOND_TERM_YEARS'), 1, 40, 'aukcje: termin')
        if term not in KDL_TERMY:
            raise ValueError(f'aukcje {d}: termin {term:g} lat spoza listy')
        amt = kdl_liczba(kdl_v(o, 'AUC_BOND_AMOUNT'), 100, 30000, 'aukcje: kwota')
        yld = kdl_liczba(kdl_v(o, 'AUC_BOND_AVG_YIELD'), 0, 15, 'aukcje: rentowność')
        cov = kdl_liczba(kdl_v(o, 'AUC_BOND_COVERAGE'), 1, 10, 'aukcje: pokrycie')
        tail = kdl_liczba(kdl_v(o, 'AUC_BOND_TAIL'), -5, 20, 'aukcje: tail')
        dis, cus, can, zg = (kdl_liczba(kdl_v(o, k), 0, 100, 'aukcje: udział') for k in ('AUC_BOND_PERCENT_ALLOTTED_TO_DISTRIBUTORS', 'AUC_BOND_PERCENT_ALLOTTED_TO_CUSTOMERS',
                                                                                     'AUC_BOND_PERCENT_ALLOTTED_TO_CANADIAN', 'AUC_BOND_PERCENT_ALLOTTED_TO_FOREIGN'))
        if abs(can + zg - 100) > 0.1 or abs(dis + cus - 100) > 0.1:
            raise ValueError(f'aukcje {d}: udziały nie dają 100 %')
        rows.append([d.isoformat(), int(term), round(amt), round(yld, 3), round(cov, 3), round(tail, 2), round(zg, 2), round(dis, 2)])
    if len(rows) < 20:
        raise ValueError('aukcje: za mało aukcji z udziałem zagranicy')
    rows.sort(key=lambda r: (r[0], r[1]))
    return rows


def kdl_au(pk, now):
    """Część au: jedno zapytanie o całą historię wyników, wiersze dokładane wg dnia i terminu, ostatnie KDL_KEEP['au']."""
    nowe = parse_kdl_au(kdl_get(KDL_AU_URL, KDL_MAXB['au']), now)
    kdl_stare(nowe[-1][0], now.date(), KDL_AU_STARE, 'aukcje')
    pk = pk if isinstance(pk, dict) else {}
    h = kdl_scal(pk.get('h'), nowe, KDL_KEEP['au'], klucz=lambda r: (r[0], r[1]))
    return {'asof': h[-1][0], 'h': h}


# ---------------------------------------------------------------- dr: posiadacze długu rządu ----------------------------------------------------------------
KDL_DR_S = ('DTBOCTOTUAW', 'DTGOCTOTUAW', 'DTGPTOTUAW', 'DTTOTUAW', 'DTGPTBUAW', 'DTGPOTHUAW')


def parse_kdl_dr(raw, now):
    """Posiadacze długu rządu Kanady → wiersze [dzień, Bank Kanady, konta rządu, rynek, razem, bony w rynku, obligacje w rynku] w mln CAD rosnąco wg dnia. Obserwacja bez żadnej z serii jest pomijana;
    częściowa, powtórzony dzień, składniki ≠ razem (± 2 mln) albo bony + obligacje w rynku > rynek = ValueError."""
    dzis = now.date()
    rows, widziane = [], set()
    for o in kdl_obs(raw, KDL_DR_S):
        if not isinstance(o, dict):
            raise ValueError('posiadacze długu: obserwacja ma zły kształt')
        v = [kdl_v(o, k) for k in KDL_DR_S]
        if all(x is None for x in v):
            continue
        d = kdl_dzien(o.get('d'), dzis, 'posiadacze długu')
        if d in widziane:
            raise ValueError(f'posiadacze długu: dzień {d} powtórzony')
        widziane.add(d)
        boc, goc, pub, tot, pb, po = (kdl_liczba(x, 0, 5e7, 'posiadacze długu') for x in v)
        if abs(boc + goc + pub - tot) > 2 or pb + po > pub + 2 or tot < 1e5:
            raise ValueError(f'posiadacze długu {d}: składniki nie dają sumy')
        rows.append([d.isoformat(), round(boc), round(goc), round(pub), round(tot), round(pb), round(po)])
    if len(rows) < 3:
        raise ValueError('posiadacze długu: za mało tygodni')
    rows.sort(key=lambda r: r[0])
    return rows


def kdl_dr(pk, now):
    pk = pk if isinstance(pk, dict) else {}
    n = KDL_NEW['dr'] if len(pk.get('h') or []) >= 20 else KDL_KEEP['dr'] + 4
    nowe = parse_kdl_dr(kdl_get(KDL_DR_URL.format(n=n), KDL_MAXB['dr']), now)
    kdl_stare(nowe[-1][0], now.date(), KDL_DR_STARE, 'posiadacze długu')
    h = kdl_scal(pk.get('h'), nowe, KDL_KEEP['dr'])
    return {'asof': h[-1][0], 'h': h}


# ---------------------------------------------------------------- co: CORRA ----------------------------------------------------------------
KDL_CO_S = ('AVG.INTWO', 'CORRA_TRIMMED_VOLUME', 'CORRA_NUMBER_OF_SUBMITTERS', 'CORRA_RATE_AT_PERCENTILE_5', 'CORRA_RATE_AT_PERCENTILE_25', 'CORRA_RATE_AT_PERCENTILE_75', 'CORRA_RATE_AT_PERCENTILE_95', 'CORRA_PUBLICATION_STATUS')


def parse_kdl_co(raw, now):
    """CORRA → wiersze [dzień, stawka %, 25. centyl, 75. centyl, obrót po przycięciu w mld CAD, liczba zgłaszających] rosnąco wg dnia. Dni ze statusem innym niż „Published” są pomijane; stawka
    poza przedziałem, centyle w złej kolejności (5 ≤ 25 ≤ stawka ≤ 75 ≤ 95, ± 0,0001), obrót albo liczba zgłaszających poza zakresem, powtórzony dzień albo mało dni = ValueError."""
    dzis = now.date()
    rows, widziane = [], set()
    for o in kdl_obs(raw, KDL_CO_S):
        if not isinstance(o, dict):
            raise ValueError('CORRA: obserwacja ma zły kształt')
        if kdl_v(o, 'CORRA_PUBLICATION_STATUS') != 'Published':
            continue
        d = kdl_dzien(o.get('d'), dzis, 'CORRA')
        if d in widziane:
            raise ValueError(f'CORRA: dzień {d} powtórzony')
        widziane.add(d)
        c = kdl_liczba(kdl_v(o, 'AVG.INTWO'), -1, 15, 'CORRA: stawka')
        p5, p25, p75, p95 = (kdl_liczba(kdl_v(o, k), -1, 15, 'CORRA: centyl') for k in ('CORRA_RATE_AT_PERCENTILE_5', 'CORRA_RATE_AT_PERCENTILE_25', 'CORRA_RATE_AT_PERCENTILE_75', 'CORRA_RATE_AT_PERCENTILE_95'))
        e = 0.0001
        if not (p5 <= p25 + e and p25 <= c + e and c <= p75 + e and p75 <= p95 + e):
            raise ValueError(f'CORRA {d}: stawka i centyle w złej kolejności')
        vol = kdl_liczba(kdl_v(o, 'CORRA_TRIMMED_VOLUME'), 1e9, 5e12, 'CORRA: obrót')
        n = kdl_liczba(kdl_v(o, 'CORRA_NUMBER_OF_SUBMITTERS'), 3, 100, 'CORRA: zgłaszający')
        rows.append([d.isoformat(), round(c, 4), round(p25, 4), round(p75, 4), round(vol / 1e9, 2), int(n)])
    if len(rows) < 5:
        raise ValueError('CORRA: za mało dni')
    rows.sort(key=lambda r: r[0])
    return rows


def kdl_co(pk, now):
    pk = pk if isinstance(pk, dict) else {}
    n = KDL_NEW['co'] if len(pk.get('h') or []) >= 30 else KDL_KEEP['co'] + 5
    nowe = parse_kdl_co(kdl_get(KDL_CO_URL.format(n=n), KDL_MAXB['co']), now)
    kdl_stare(nowe[-1][0], now.date(), KDL_CO_STARE, 'CORRA')
    h = kdl_scal(pk.get('h'), nowe, KDL_KEEP['co'])
    return {'asof': h[-1][0], 'h': h}


# ---------------------------------------------------------------- bs: bilans Banku Kanady ----------------------------------------------------------------
KDL_BS_AKT = ('V36612', 'V36613', 'V1160788296', 'V1038114416', 'v1146067261', 'v1154426989', 'v1146067262', 'v1146067263', 'v1154426990', 'V36634', 'V44201362', 'v1154426991', 'V36635')   # składniki aktywów
KDL_BS_PAS = ('V36625', 'V36628', 'V36636', 'v1146067264', 'V1203435186', 'V1210798115')   # składniki pasywów poza „pozostałymi” (V36632 albo V1490410223 + V1490410224)
KDL_BS_S = ('V36610', 'V36624') + KDL_BS_AKT + KDL_BS_PAS + ('V1490410223', 'V1490410224')


def parse_kdl_bs(raw, now):
    """Bilans tygodniowy → wiersze [dzień, aktywa razem, papiery rządowe (bony + obligacje + indeksowane + hipoteczne), same obligacje, transakcje z odkupem (aktywa), banknoty, depozyty rządu, depozyty członków
    systemu płatności] w mln CAD rosnąco wg dnia. Obserwacje starej serii (bez sum aktywów i pasywów) są pomijane; aktywa ≠ pasywa (± 1), suma składników aktywów ≠ aktywa (± 2) albo pasywów ≠ pasywa
    (± 2), powtórzony dzień, brak składnika albo mało tygodni = ValueError."""
    dzis = now.date()
    rows, widziane = [], set()
    for o in kdl_obs(raw, KDL_BS_S):
        if not isinstance(o, dict):
            raise ValueError('bilans: obserwacja ma zły kształt')
        if kdl_v(o, 'V36610') is None and kdl_v(o, 'V36624') is None:
            continue
        d = kdl_dzien(o.get('d'), dzis, 'bilans')
        if d in widziane:
            raise ValueError(f'bilans: dzień {d} powtórzony')
        widziane.add(d)
        N = lambda k: kdl_liczba(kdl_v(o, k), -1e6, 3e6, f'bilans {k}')   # noqa: E731
        akt, pas = N('V36610'), N('V36624')
        sa = sum(N(k) for k in KDL_BS_AKT)
        inne = N('V36632') if kdl_v(o, 'V36632') is not None else N('V1490410223') + N('V1490410224')
        sp = sum(N(k) for k in KDL_BS_PAS) + inne
        if abs(akt - pas) > 1 or abs(sa - akt) > 2 or abs(sp - pas) > 2 or not 1e4 <= akt <= 2e6:
            raise ValueError(f'bilans {d}: aktywa, pasywa i składniki nie zgadzają się')
        goc = N('V36612') + N('V36613') + N('V1160788296') + N('V1038114416')
        rows.append([d.isoformat(), round(akt), round(goc), round(N('V36613')), round(N('V44201362')), round(N('V36625')), round(N('V36628')), round(N('V36636'))])
    if len(rows) < 3:
        raise ValueError('bilans: za mało tygodni')
    rows.sort(key=lambda r: r[0])
    return rows


def kdl_bs(pk, now):
    pk = pk if isinstance(pk, dict) else {}
    n = KDL_NEW['bs'] if len(pk.get('h') or []) >= 20 else KDL_KEEP['bs'] + 6
    nowe = parse_kdl_bs(kdl_get(KDL_BS_URL.format(n=n), KDL_MAXB['bs']), now)
    kdl_stare(nowe[-1][0], now.date(), KDL_DR_STARE, 'bilans')
    h = kdl_scal(pk.get('h'), nowe, KDL_KEEP['bs'])
    return {'asof': h[-1][0], 'h': h}


# ---------------------------------------------------------------- rp: ropociągi ----------------------------------------------------------------
KDL_RP_KOL = ('Date', 'Pipeline', 'Key Point', 'Direction Of Flow', 'Product', 'Throughput (1000 m3/d)', 'Available Capacity (1000 m3/d)')


def _kdl_rp_csv(raw, rurociag):
    """Plik regulatora → {miesiąc 'RRRR-MM': [wiersze słowników]}; bez kolumn, z inną nazwą ropociągu albo dniem innym niż pierwszy dzień miesiąca = ValueError."""
    txt = (raw.decode('utf-8-sig') if isinstance(raw, (bytes, bytearray)) else str(raw))
    rd = csv.DictReader(io.StringIO(txt))
    if not rd.fieldnames or not all(k in rd.fieldnames for k in KDL_RP_KOL):
        raise ValueError('ropociągi: plik bez oczekiwanych kolumn (zmieniony układ?)')
    out = {}
    for r in rd:
        if not isinstance(r.get('Pipeline'), str) or r['Pipeline'].strip() != rurociag:
            raise ValueError(f'ropociągi: inny ropociąg niż {rurociag}')
        ds = r.get('Date')
        if not (isinstance(ds, str) and re.fullmatch(r'\d{4}-\d{2}-01', ds)):
            raise ValueError(f'ropociągi: zły dzień {str(ds)[:12]!r}')
        out.setdefault(ds[:7], []).append(r)
    if not out:
        raise ValueError('ropociągi: pusty plik')
    return out


def _kdl_rp_okno(mies, dzis):
    """Ostatnie KDL_KEEP['rp'] miesięcy z pliku: kolejne bez luk, ostatni nie z przyszłości i nie starszy niż KDL_RP_STARE dni od jego początku."""
    ks = sorted(mies)[-KDL_KEEP['rp']:]
    ym = [int(k[:4]) * 12 + int(k[5:]) - 1 for k in ks]
    if len(ks) < 24 or any(b - a != 1 for a, b in zip(ym, ym[1:])):
        raise ValueError('ropociągi: za mało miesięcy albo luka w miesiącach')
    d = datetime.date.fromisoformat(ks[-1] + '-01')
    if d > dzis:
        raise ValueError(f'ropociągi: miesiąc {ks[-1]} z przyszłości')
    if (dzis - d).days > KDL_RP_STARE:
        raise ValueError(f'ropociągi: ostatni miesiąc {ks[-1]} sprzed {(dzis - d).days} dni (źródło stoi)')
    return ks


def _kdl_rp_num(r, k):
    x = r.get(k)
    return None if x is None or str(x).strip() == '' else kdl_liczba(x, 0, 5000, f'ropociągi {k[:10]}')


def parse_kdl_rp(raw_k, raw_t, now):
    """Keystone i Trans Mountain → {'asof': 'RRRR-MM', 'k': [[miesiąc, przepływ, zdolność]], 't': [[miesiąc, Westridge, Sumas, Burnaby, zdolność]]}, w tys. baryłek na dobę (z tys. m3 × 6,28981, 1 miejsce).
    Keystone: suma przepływu ciężkiej i lekkiej ropy na granicy (kierunek południowy), zdolność jedna dla wierszy miesiąca (± 0,01); Trans Mountain: przepływ w trzech punktach (Westridge, Sumas, Burnaby) i
    zdolność z wiersza całego systemu; przepływ ≤ 1,02 zdolności (Keystone) albo ≤ 1,6 (Trans Mountain, w 2024 przy uruchomieniu rozbudowy zdarzały się 1,2–1,4), wartości ujemne, brak punktu = ValueError."""
    dzis = now.date()
    K = _kdl_rp_csv(raw_k, 'Keystone pipeline')
    T = _kdl_rp_csv(raw_t, 'Trans Mountain pipeline')
    kr, tr = [], []
    for m in _kdl_rp_okno(K, dzis):
        thr, caps = 0.0, []
        n = 0
        for r in K[m]:
            if r['Product'].strip() in ('domestic heavy', 'domestic light') and r['Direction Of Flow'].strip() == 'south':
                v = _kdl_rp_num(r, 'Throughput (1000 m3/d)')
                c = _kdl_rp_num(r, 'Available Capacity (1000 m3/d)')
                if v is None or c is None:
                    raise ValueError(f'Keystone {m}: brak przepływu albo zdolności')
                thr += v; caps.append(c); n += 1
        if n != 2 or max(caps) - min(caps) > 0.01 or caps[0] <= 0 or thr > caps[0] * 1.02:
            raise ValueError(f'Keystone {m}: przepływ i zdolność niespójne')
        kr.append([m, round(thr * KDL_BBL, 1), round(caps[0] * KDL_BBL, 1)])
    for m in _kdl_rp_okno(T, dzis):
        punkty, cap = {'Westridge': 0.0, 'Sumas': 0.0, 'Burnaby': 0.0}, []
        wid = set()
        for r in T[m]:
            kp = r['Key Point'].strip()
            if kp == 'system':
                c = _kdl_rp_num(r, 'Available Capacity (1000 m3/d)')
                if c is not None:
                    cap.append(c)
            elif kp in punkty:
                v = _kdl_rp_num(r, 'Throughput (1000 m3/d)')
                if v is not None:
                    punkty[kp] += v; wid.add(kp)
        if len(cap) != 1 or cap[0] <= 0 or wid != set(punkty) or sum(punkty.values()) > cap[0] * 1.6:
            raise ValueError(f'Trans Mountain {m}: punkty, zdolność albo przepływ niespójne')
        tr.append([m, round(punkty['Westridge'] * KDL_BBL, 1), round(punkty['Sumas'] * KDL_BBL, 1), round(punkty['Burnaby'] * KDL_BBL, 1), round(cap[0] * KDL_BBL, 1)])
    return {'asof': min(kr[-1][0], tr[-1][0]), 'k': kr, 't': tr}


def kdl_rp(pk, now):
    """Część rp: dwa zapytania (pliki obu ropociągów), cała historia z plików (źródło trzyma ją w całości) — bez dokładania wg dnia."""
    k = kdl_get(KDL_RP_URL.format(p='keystone'), KDL_MAXB['rp'])
    t = kdl_get(KDL_RP_URL.format(p='trans-mountain'), KDL_MAXB['rp'])
    return parse_kdl_rp(k, t, now)


# ---------------------------------------------------------------- budowa pliku ----------------------------------------------------------------
KDL_BUDOWA = {'au': kdl_au, 'dr': kdl_dr, 'co': kdl_co, 'bs': kdl_bs, 'rp': kdl_rp}


def kdl_wymagana(k, pk, pok, pat, now):
    """Czy część k wymaga odczytu: brak części, poprzedni błąd albo odczyt starszy niż KDL_INT[k] min."""
    if not isinstance(pk, dict) or pok.get(k) is False:
        return True
    t = _ix_dt(pat.get(k))
    return t is None or (now - t).total_seconds() >= KDL_INT[k] * 60


def build_kanada_dlug(prev=None, run_t0=None):
    """Plik data/kanada-dlug.json (v410): pięć części (au, dr, co, bs, rp) z własnym ok / part_at / errs; część z błędem zostaje z poprzedniego pliku z własną chwilą, nigdy pusta zamiast ostatnich danych;
    część, której odczyt nie jest jeszcze potrzebny (rytm), zostaje bez zmian z ok 'cached'. Żadna część nie ma danych = wyjątek (przebieg główny zostawia poprzedni plik)."""
    prev = prev if isinstance(prev, dict) and prev.get('v') == KDL_V else {}
    pat, pok = _dict(prev.get('part_at')), _dict(prev.get('ok'))
    now = datetime.datetime.fromisoformat(NOW).astimezone(datetime.timezone.utc)
    out = {'v': KDL_V, 'at': NOW, 'od': prev.get('od') if isinstance(prev.get('od'), str) else now.date().isoformat(), 'src': KDL_SRC, 'ok': {}, 'part_at': {}, 'errs': {}}
    _KDL_T0[0] = time.monotonic()
    try:
        for k in KDL_PARTS:
            pk = prev.get(k) if isinstance(prev.get(k), dict) else None
            if not kdl_wymagana(k, pk, pok, pat, now):
                if pk is not None:
                    out[k] = pk
                    out['part_at'][k] = pat.get(k) or prev.get('at')
                out['ok'][k] = 'cached'
                continue
            try:
                out[k] = KDL_BUDOWA[k](pk, now)
                out['ok'][k] = True
                out['part_at'][k] = NOW
            except Exception as e:  # noqa — część z błędem: poprzednie dane z własną chwilą
                msg = mask(f'{e}')[:160]
                META['errors'].append(mask(f'{KDL_PX} {KDL_LABEL[k]}: {msg}')[:220])
                out['ok'][k] = False
                out['errs'][k] = msg
                if pk is not None:
                    out[k] = pk
                    out['part_at'][k] = pat.get(k) or prev.get('at')
    finally:
        _KDL_T0[0] = None
    if not any(isinstance(out.get(k), dict) for k in KDL_PARTS):
        raise RuntimeError('żadna część nie odpowiedziała')
    return out


# v410: koniec modułu Kanada


# ===================== v423 (F11Z26): FED — BANKI KOMERCYJNE USA, PAPIERY KOMERCYJNE, ANKIETA DEALERÓW, ANKIETA KREDYTOWA BANKÓW (data/fed-ddp.json) =====================
# Cztery niezależne części jednego pliku, każda z własnym ok / part_at / errs i własną poprzednią wersją przy błędzie (nigdy puste zamiast ostatnich danych); publiczne zapytania GET bez klucza,
# nagłówek zbieracza, odstęp FDD_SLEEP s, limit czasu i rozmiaru KAŻDEGO zapytania, cała budowa FDD_LIMIT_S s. Jedno źródło (Rada Gubernatorów Fed — już liczone w kalendarzu): gotowe paczki ZIP z XML
# (SDMX „Data Download Program”) pobierane z adresów wydań; XML czytany strumieniowo (parser expat, DOCTYPE odrzucany, limity rozmiaru spakowanego i rozpakowanego), do pamięci trafiają tylko potrzebne serie.
#   h8 — banki komercyjne w USA, tygodniowo (środa, dane wyrównane sezonowo, mld $): aktywa razem, kredyt bankowy, papiery wartościowe, kredyty i leasing, w tym przemysłowe i handlowe (C&I), nieruchomości
#        komercyjne, konsumenckie i dla instytucji finansowych poza bankami; depozyty, duże depozyty terminowe, pożyczki zaciągnięte, gotówka.
#   cp — papiery komercyjne: (w) w obiegu tygodniowo (środa, wyrównane sezonowo, mld $): razem, niefinansowe, finansowe, zabezpieczone aktywami; (r) stawki dzienne 30-dniowych papierów: AA niefinansowe,
#        A2/P2 niefinansowe (niższa jakość) — rozstęp A2/P2 do AA mierzy premię za ryzyko kredytowe.
#   so — ankieta dealerów o warunkach finansowania funduszy hedgingowych (kwartalnie): netto % dealerów zaostrzających ceny, warunki poza ceną, netto % zwiększających się dźwigni funduszy i dostępności dalszej dźwigni.
#   sl — ankieta kredytowa starszych urzędników bankowych (kwartalnie): netto % banków zaostrzających standardy (duże i średnie firmy, małe firmy, karty kredytowe, nieruchomości komercyjne, ważone: biznes i
#        gospodarstwa domowe) oraz netto % banków widzących silniejszy popyt (duże firmy, karty).
# Wersja z 18.10.2026: ogłoszono wygaszanie aplikacji Data Download Program (od 9.11 znika „Build Your Package”, pełne wycofanie później); paczki z wydań są nadal na swoich adresach — jeśli znikną, część zgłosi błąd
# i zostanie z ostatnimi danymi (kontrola: ⚠ po przekroczeniu progu rytmu), bez zerowania liczb.
# Bramki: każda liczba skończona i w zakresie wiarygodności, daty istniejące, nie z przyszłości i rosnące bez powtórzeń (tygodnie co 7 dni, środy), tożsamości (kredyt bankowy = papiery + kredyty; papiery
# komercyjne razem = niefinansowe + finansowe + zabezpieczone aktywami; liczność ankiety = suma odpowiedzi), atrybuty serii zgodne z oczekiwanymi (wyrównanie sezonowe, grupa banków, mnożnik); inny kształt
# albo brak serii = błąd części (nigdy cicha zmiana liczb).
import zipfile as _fdd_zip
import xml.parsers.expat as _fdd_expat
import collections as _fdd_col
import zlib as _fdd_zlib
FDD_V = 1
FDD_PARTS = ('h8', 'cp', 'so', 'sl')
FDD_LABEL = {'h8': 'banki komercyjne', 'cp': 'papiery komercyjne', 'so': 'ankieta dealerów', 'sl': 'ankieta kredytowa banków'}
