IW_TIMEOUT = 40               # s — jedno zapytanie
IW_SLEEP = 0.7                # s — odstęp między zapytaniami
IW_N = 262                    # sesji w szeregach dziennych (rok z zapasem: odniesienie sprzed 365 dni musi się w nich mieścić)
IW_DNI_WSTECZ = 400           # dni kalendarzowe wstecz w zapytaniach o szeregi dzienne
IW_JP_CSV = 'https://www.mof.go.jp/english/policy/international_policy/reference/feio/foreign_exchange_intervention_operations.csv'
IW_JP_IDX = 'https://www.mof.go.jp/english/policy/international_policy/reference/feio/monthly/index.html'
IW_JP_MON = 'https://www.mof.go.jp/english/policy/international_policy/reference/feio/monthly/{f}'   # f = nazwa pliku z listy (zwykle RRRRMMDDe.html; raz w 2025 bez „e”)
IW_JP_TOL = 3                 # setki mln jenów — zaokrąglenia dni względem sumy kwartału (w całym pliku od 1991 największa różnica: 1)
IW_JP_MAX_NOWYCH = 8          # najwyżej tyle nowych komunikatów miesięcznych na przebieg
IW_JP_MAX_OKRES = 100000      # mld jenów — górna granica kwoty okresu
IW_HK_URL = ('https://api.hkma.gov.hk/public/market-data-and-statistics/daily-monetary-statistics/daily-figures-interbank-liquidity'
             '?pagesize=1000&sortby=end_of_date&sortorder=desc&fields=end_of_date,closing_balance,market_activities,cu_weakside,cu_strongside')
IW_HK_MIN = 200               # sesji — mniej = błąd (odpowiedź ucięta)
IW_HK_MAX = 1000000           # mln HK$ — saldo zbiorcze
IW_HK_AKT = 150000            # mln HK$ — największa dzienna interwencja uznana za wiarygodną
IW_AR_URL = 'https://api.bcra.gob.ar/estadisticas/v4.0/monetarias/{id}?desde={a}&hasta={b}&limit=1000'
IW_AR_RES, IW_AR_BUY = 1, 78  # 1 = rezerwy międzynarodowe (mln USD); 78 = zmiana rezerw z tytułu zakupu walut (mln USD, przepływ dzienny)
IW_BR_SGS = 13621             # rezerwy międzynarodowe — płynność międzynarodowa, dziennie, mln USD
IW_CA_URL = 'https://www.bankofcanada.ca/valet/observations/group/OFFICIAL_INT_RES/json?recent=60'
IW_CA_IDS = ('V15943316', 'V15943317', 'V15943318', 'V15943319', 'V15943320', 'V15943321', 'OIRORA')   # razem, USD, inne waluty, złoto, SDR, MFW, pozostałe
IW_FOCUS_URL = ('https://olinda.bcb.gov.br/olinda/servico/Expectativas/versao/v1/odata/ExpectativasMercadoAnuais?$top=1000&$orderby=Data%20desc&$format=json'
                '&$select=Data,DataReferencia,Mediana,Media,DesvioPadrao,Minimo,Maximo,numeroRespondentes'
                "&$filter=Indicador%20eq%20'{ind}'%20and%20baseCalculo%20eq%200%20and%20Data%20ge%20'{od}'")
IW_FOCUS_IND = (('selic', 'Selic', 0, 60), ('ipca', 'IPCA', -5, 100), ('pib', 'PIB%20Total', -20, 20), ('cambio', 'C%C3%A2mbio', 0.5, 50))
IW_FOCUS_DNI = 125            # dni wstecz w zapytaniu (ok. 17 tygodni)
IW_FOCUS_TYG = 18             # tygodni w próbce
IW_FOCUS_MAX_DNI = 14         # dni — ostatni dzień badania starszy = błąd części
import html as _html   # v401: rozpakowanie encji w komunikatach miesięcznych (biblioteka standardowa)
IW_SRC = ('CapitalFlowAI — interwencje walutowe i rezerwy banków centralnych (Japonia: dni interwencji i komunikaty miesięczne; Hongkong: saldo zbiorcze i działania rynkowe; Argentyna: rezerwy i zakupy walut; '
          'Brazylia: rezerwy; Kanada: oficjalne rezerwy) oraz oczekiwania rynku w Brazylii; daty z samych źródeł, pobranie części w part_at (UTC)')
IW_MIES = {m: i for i, m in enumerate(('January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'), 1)}
IW_MIES3 = {m[:3]: i for m, i in IW_MIES.items()}


def iw_dzien(s):
    """„RRRR-MM-DD” → date; inny zapis albo nieistniejący dzień = None."""
    if not isinstance(s, str) or not re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
        return None
    try:
        return datetime.date.fromisoformat(s)
    except ValueError:
        return None


def iw_liczba(x, lo, hi):
    """Liczba skończona z przedziału [lo, hi] (wartość logiczna i tekst nie są liczbą) → float albo None."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        return None
    x = float(x)
    return x if x == x and lo <= x <= hi else None


def iw_pobierz(url, bajty=False):
    """Jedno zapytanie GET (publiczne, bez klucza, z identyfikatorem zbieracza) z odstępem IW_SLEEP; tekst (albo bajty) odpowiedzi; pusta odpowiedź = błąd."""
    time.sleep(IW_SLEEP)
    if bajty:
        b = get_bytes(url, timeout=IW_TIMEOUT)
        if not isinstance(b, (bytes, bytearray)) or len(b) < 100:
            raise RuntimeError('odpowiedź bez treści')
        return bytes(b)
    st, body = get(url, timeout=IW_TIMEOUT)
    if st != 200 or not isinstance(body, str) or len(body) < 20:
        raise RuntimeError(f'odpowiedź bez treści (HTTP {st})')
    return body


def iw_json(url):
    try:
        return json.loads(iw_pobierz(url))
    except urllib.error.HTTPError as e:
        if e.code in (404, 410):
            raise RuntimeError(f'adres wyłączony albo zmieniony (HTTP {e.code})') from None
        raise
    except ValueError:
        raise RuntimeError('odpowiedź nie jest JSON-em') from None


# ---------- Japonia ----------
def iw_jp_kier(opis):
    """Opis operacji z pliku → 'S' sprzedaż dolarów za jeny (obrona jena), 'B' kupno dolarów za jeny, 'E' kupno euro za jeny, 'X' inne (marka, rupia)."""
    s = re.sub(r'\s+', ' ', str(opis).replace('　', ' ')).strip()
    if 'US dollar (sold)' in s and 'Japanese yen (bought)' in s:
        return 'S'
    if 'US dollar (bought)' in s and 'Japanese yen (sold)' in s:
        return 'B'
    if 'Euro (bought)' in s and 'Japanese yen (sold)' in s:
        return 'E'
    return 'X'


def iw_jp_csv(tekst):
    """Plik historii (po dekodowaniu Shift_JIS) → (zdarzenia [[RRRR-MM-DD, kwota w setkach mln jenów, kierunek]], kwartały [(rok, miesiąc od, miesiąc do, suma)]). Rok (kolumna 4) i miesiąc (kolumna 5)
    przenoszone w dół; wiersz „…期計” = suma kwartału. Bramki: 9 kolumn; co najmniej 300 dni i 100 kwartałów; dni rosnąco; kwartały po kolei bez luk; każdy dzień w kwartale; suma kwartału = suma jego dni (±IW_JP_TOL)."""
    wz = list(csv.reader(io.StringIO(tekst.lstrip(chr(0xFEFF)))))
    ev, kw = [], []
    rok = mies = None
    for w in wz:
        if len(w) != 9:
            continue
        if w[0].strip().endswith('期計'):
            ms = re.findall(r'[A-Za-z]+', w[3])
            lat = re.findall(r'\d{4}', w[3])
            razem = w[6].replace(',', '').strip()
            if not ms or not lat or any(m not in IW_MIES for m in ms) or not razem.isdigit():
                raise RuntimeError(f'Japonia: wiersz sumy kwartału w złym układzie ({w[3][:30]!r})')
            m1, m2 = IW_MIES[ms[0]], IW_MIES[ms[-1]]
            if m2 - m1 != 2 or m1 % 3 != 1:
                raise RuntimeError(f'Japonia: kwartał {w[3][:30]!r} nie jest pełnym kwartałem')
            kw.append((int(lat[-1]), m1, m2, int(razem)))
            continue
        if not w[5].strip().isdigit() or not re.fullmatch(r'\d{1,3}(?:,\d{3})*', w[6].strip()):
            continue
        if w[3].strip().isdigit():
            rok = int(w[3])
        if w[4].strip():
            if w[4].strip() not in IW_MIES3:
                raise RuntimeError(f'Japonia: zły miesiąc {w[4][:10]!r}')
            mies = IW_MIES3[w[4].strip()]
        if rok is None or mies is None:
            raise RuntimeError('Japonia: dzień bez roku albo miesiąca')
        try:
            d = datetime.date(rok, mies, int(w[5]))
        except ValueError:
            raise RuntimeError(f'Japonia: zły dzień {rok}-{mies}-{w[5]}') from None
        ev.append([d.isoformat(), int(w[6].replace(',', '')), iw_jp_kier(w[8])])
    if len(ev) < 300 or len(kw) < 100:
        raise RuntimeError(f'Japonia: za mało wierszy ({len(ev)} dni, {len(kw)} kwartałów)')
    if any(ev[i][0] < ev[i - 1][0] for i in range(1, len(ev))) or any(not 1 <= e[1] <= 300000 for e in ev):
        raise RuntimeError('Japonia: dni nie idą rosnąco albo kwota poza zakresem')
    for i in range(1, len(kw)):
        a, b = kw[i - 1], kw[i]
        if (b[0], b[1]) != ((a[0] + 1, 1) if a[2] == 12 else (a[0], a[2] + 1)):
            raise RuntimeError(f'Japonia: luka między kwartałami {a[0]}/{a[1]} i {b[0]}/{b[1]}')
    for y, m1, m2, razem in kw:
        s = sum(e[1] for e in ev if e[0][:4] == str(y) and m1 <= int(e[0][5:7]) <= m2)
        if abs(s - razem) > IW_JP_TOL:
            raise RuntimeError(f'Japonia: suma kwartału {y}/{m1}–{m2} = {razem}, suma dni = {s}')
    pierwszy = (kw[0][0], kw[0][1])
    for e in ev:
        y, m = int(e[0][:4]), int(e[0][5:7])
        if (y, m) < pierwszy or not any(y == k[0] and k[1] <= m <= k[2] for k in kw):
            raise RuntimeError(f'Japonia: dzień {e[0]} poza kwartałami pliku')
    return ev, kw


def iw_jp_koniec(kw):
    """Ostatni dzień ostatniego kwartału pliku."""
    y, m2 = kw[-1][0], kw[-1][2]
    return (datetime.date(y + (m2 == 12), m2 % 12 + 1, 1) - datetime.timedelta(days=1))


def iw_jp_lista(html_txt):
    """Strona z listą komunikatów miesięcznych → posortowane [(data publikacji, nazwa pliku)] z odnośników „RRRRMMDDe.html” (raz w 2025 komunikat miał nazwę bez „e” — też z listy); mniej niż 20 albo zła data = błąd."""
    nazwy = sorted(set(re.findall(r'(?<!\d)(\d{8}e?\.html)', html_txt)))
    out = []
    for n in nazwy:
        try:
            out.append((datetime.date(int(n[:4]), int(n[4:6]), int(n[6:8])), n))
        except ValueError:
            raise RuntimeError(f'Japonia: zła data komunikatu {n}') from None
    if len(out) < 20:
        raise RuntimeError(f'Japonia: lista komunikatów miesięcznych ma {len(out)} pozycji')
    return out


def iw_jp_data_ang(s):
    m = re.fullmatch(r'([A-Z][a-z]+) (\d{1,2}), (\d{4})', s.strip())
    if not m or m.group(1) not in IW_MIES:
        raise RuntimeError(f'Japonia: zła data {s[:30]!r}')
    try:
        return datetime.date(int(m.group(3)), IW_MIES[m.group(1)], int(m.group(2)))
    except ValueError:
        raise RuntimeError(f'Japonia: zła data {s[:30]!r}') from None


def iw_jp_okres(html_txt):
    """Komunikat miesięczny → (od, do, kwota w mld jenów). Kwota „¥ 0” albo „¥ 15,399.3 billion” — inna jednostka przy kwocie niezerowej = błąd."""
    t = re.sub(r'<script.*?</script>|<style.*?</style>', ' ', html_txt, flags=re.S | re.I)
    t = re.sub(r'\s+', ' ', _html.unescape(re.sub(r'<[^>]+>', ' ', t)))
    m = re.search(r'for the period from ([A-Z][a-z]+ \d{1,2}, \d{4}) through ([A-Z][a-z]+ \d{1,2}, \d{4}) [¥￥] ?([\d,]+(?:\.\d+)?)( billion)?', t)
    if not m:
        raise RuntimeError('Japonia: komunikat miesięczny w innym układzie')
    od, do = iw_jp_data_ang(m.group(1)), iw_jp_data_ang(m.group(2))
    v = float(m.group(3).replace(',', ''))
    if v and not m.group(4):
        raise RuntimeError('Japonia: kwota komunikatu bez jednostki')
    if not od < do or (do - od).days > 45 or not 0 <= v <= IW_JP_MAX_OKRES:
        raise RuntimeError(f'Japonia: okres {od}–{do} albo kwota {v} poza zakresem')
    return od, do, round(v, 1)


def iw_jp_czesc(prev):
    ev, kw = iw_jp_csv(iw_pobierz(IW_JP_CSV, bajty=True).decode('cp932', 'replace'))
    kon = iw_jp_koniec(kw)
    lista = iw_jp_lista(iw_pobierz(IW_JP_IDX))
    stare = {r[3]: r for r in (prev.get('mo') if isinstance(prev, dict) and isinstance(prev.get('mo'), list) else []) if isinstance(r, list) and len(r) == 4}
    mo, nowe = [], 0
    for pub, nazwa in (x for x in lista if x[0] > kon):
        r = stare.get(pub.isoformat())
        if r is None:
            if nowe >= IW_JP_MAX_NOWYCH:
                raise RuntimeError('Japonia: za dużo nowych komunikatów miesięcznych naraz')
            nowe += 1
            od, do, v = iw_jp_okres(iw_pobierz(IW_JP_MON.format(f=nazwa)))
            if not do <= pub <= do + datetime.timedelta(days=10):
                raise RuntimeError(f'Japonia: komunikat z {pub} dla okresu do {do}')
            r = [od.isoformat(), do.isoformat(), v, pub.isoformat()]
        if iw_dzien(r[1]) > kon:
            mo.append(r)
    mo.sort(key=lambda r: r[1])
    for i, r in enumerate(mo):
        nast = iw_dzien(mo[i - 1][1]) + datetime.timedelta(days=1) if i else None
        if (i and iw_dzien(r[0]) != nast) or (not i and iw_dzien(r[0]) > kon + datetime.timedelta(days=1)):
            raise RuntimeError(f'Japonia: luka w komunikatach miesięcznych przed okresem {r[0]}–{r[1]}')
    asof = iw_dzien(mo[-1][1]) if mo else kon
    return {'asof': asof.isoformat(), 'kw_do': kon.isoformat(), 'ev': ev, 'mo': mo}


# ---------- Hongkong ----------
def iw_hk_czesc(prev, dzis):
    j = iw_json(IW_HK_URL)
    h = j.get('header') if isinstance(j, dict) else None
    if not isinstance(h, dict) or h.get('success') is not True or str(h.get('err_code')) != '0000':
        raise RuntimeError('Hongkong: odpowiedź z kodem błędu')
    rec = j['result'].get('records') if isinstance(j.get('result'), dict) else None
    if not isinstance(rec, list) or len(rec) < IW_HK_MIN:
        raise RuntimeError(f'Hongkong: za mało sesji ({len(rec) if isinstance(rec, list) else "brak"})')
    wz = []
    for r in rec:
        d = iw_dzien(r.get('end_of_date')) if isinstance(r, dict) else None
        zam = iw_liczba(r.get('closing_balance'), 0, IW_HK_MAX) if d else None
        a = r.get('market_activities')
        if d is None or zam is None or zam != int(zam) or not isinstance(a, str) or not re.fullmatch(r'[+-]?\d{1,6}', a.strip()):
            raise RuntimeError(f'Hongkong: zły wiersz {str(r)[:60]}')
        akt = int(a)
        if abs(akt) > IW_HK_AKT:
            raise RuntimeError(f'Hongkong: interwencja {akt} poza zakresem')
        wz.append((d, int(zam), akt, iw_liczba(r.get('cu_weakside'), 7.0, 8.5), iw_liczba(r.get('cu_strongside'), 7.0, 8.5)))
    wz.sort(key=lambda x: x[0])
    if any(wz[i][0] == wz[i - 1][0] for i in range(1, len(wz))):
        raise RuntimeError('Hongkong: powtórzony dzień')
    ost = wz[-1]
    if ost[3] is None or ost[4] is None or not ost[4] < ost[3]:
        raise RuntimeError('Hongkong: pasmo kursu w złym kształcie')
    if (dzis - ost[0]).days > 10 or ost[0] > dzis:
        raise RuntimeError(f'Hongkong: ostatni dzień {ost[0]} (stoi albo z przyszłości)')
    return {'asof': ost[0].isoformat(), 'od': wz[0][0].isoformat(), 'band': [ost[4], ost[3]],
            's': [[x[0].isoformat(), x[1], x[2]] for x in wz[-IW_N:]],
            'ev': [[x[0].isoformat(), x[2], x[1]] for x in wz if x[2] != 0]}


# ---------- Argentyna ----------
def iw_ar_szereg(j, idv, lo, hi, dzis):
    if not isinstance(j, dict) or j.get('status') != 200 or not isinstance(j.get('results'), list) or len(j['results']) != 1:
        raise RuntimeError('Argentyna: odpowiedź w innym układzie')
    r = j['results'][0]
    if not isinstance(r, dict) or r.get('idVariable') != idv or not isinstance(r.get('detalle'), list):
        raise RuntimeError(f'Argentyna: seria {idv} w innym układzie')
    meta = j.get('metadata', {}).get('resultset', {}) if isinstance(j.get('metadata'), dict) else {}
    if meta.get('count') != len(r['detalle']):
        raise RuntimeError(f'Argentyna: seria {idv} ucięta ({meta.get("count")} wobec {len(r["detalle"])})')
    wz = []
    for x in r['detalle']:
        if isinstance(x, dict) and x.get('valor') is None and iw_dzien(x.get('fecha')):
            continue   # dzień bez wartości w źródle = dzień pominięty (nigdy zero); zły tekst albo liczba poza zakresem = błąd
        d = iw_dzien(x.get('fecha')) if isinstance(x, dict) else None
        v = iw_liczba(x.get('valor'), lo, hi) if d else None
        if d is None or v is None:
            raise RuntimeError(f'Argentyna: seria {idv}, zły wiersz {str(x)[:50]}')
        wz.append((d, round(v, 1)))
    wz.sort(key=lambda x: x[0])
    if len(wz) < 100 or any(wz[i][0] == wz[i - 1][0] for i in range(1, len(wz))):
        raise RuntimeError(f'Argentyna: seria {idv} za krótka albo z powtórzeniem ({len(wz)})')
    if (dzis - wz[-1][0]).days > 14 or wz[-1][0] > dzis:
        raise RuntimeError(f'Argentyna: seria {idv}, ostatni dzień {wz[-1][0]}')
    return wz


def iw_ar_czesc(prev, dzis):
    a, b = (dzis - datetime.timedelta(days=IW_DNI_WSTECZ)).isoformat(), dzis.isoformat()
    rez = iw_ar_szereg(iw_json(IW_AR_URL.format(id=IW_AR_RES, a=a, b=b)), IW_AR_RES, 1000, 300000, dzis)
    for i in range(1, len(rez)):
        if abs(rez[i][1] / rez[i - 1][1] - 1) > 0.4:
            raise RuntimeError(f'Argentyna: rezerwy {rez[i][0]} zmieniły się o ponad 40% w dzień')
    buy = iw_ar_szereg(iw_json(IW_AR_URL.format(id=IW_AR_BUY, a=a, b=b)), IW_AR_BUY, -6000, 6000, dzis)
    return {'asof_res': rez[-1][0].isoformat(), 'asof_buy': buy[-1][0].isoformat(),
            'res': [[x[0].isoformat(), x[1]] for x in rez[-IW_N:]], 'buy': [[x[0].isoformat(), x[1]] for x in buy[-IW_N:]]}


# ---------- Brazylia ----------
def iw_br_czesc(prev, dzis):
    _BCB_WS['chw'] = []; _BCB_WS.pop('ws_zle', None)   # liczniki chwilowych błędów interfejsu JSON — od nowa w każdym przebiegu (jak w bcb_part)
    _BCB_WS.pop('json_zle', None); _BCB_WS['soap_ok'] = 0
    now_br = datetime.datetime.fromisoformat(NOW).astimezone(datetime.timezone.utc) - datetime.timedelta(hours=3)
    a, b = (now_br - datetime.timedelta(days=IW_DNI_WSTECZ)).strftime('%d/%m/%Y'), now_br.strftime('%d/%m/%Y')
    j = _bcb_get(IW_BR_SGS, a, b)
    if not isinstance(j, list):
        raise RuntimeError('Brazylia: nieznany kształt odpowiedzi')
    wz = {}
    for r in j:
        d = iw_dzien(_bcb_date(r.get('data'))) if isinstance(r, dict) else None
        v = iw_liczba(_num(r.get('valor')), 100000, 1000000) if d else None
        if d is None or v is None:
            raise RuntimeError(f'Brazylia: zły wiersz {str(r)[:50]}')
        wz[d] = v
    wz = sorted(wz.items())
    if len(wz) < 150:
        raise RuntimeError(f'Brazylia: za mało sesji ({len(wz)})')
    for i in range(1, len(wz)):
        if abs(wz[i][1] / wz[i - 1][1] - 1) > 0.05:
            raise RuntimeError(f'Brazylia: rezerwy {wz[i][0]} zmieniły się o ponad 5% w dzień')
    if (dzis - wz[-1][0]).days > 12 or wz[-1][0] > dzis:
        raise RuntimeError(f'Brazylia: ostatni dzień {wz[-1][0]}')
    return {'asof': wz[-1][0].isoformat(), 's': [[d.isoformat(), v] for d, v in wz[-IW_N:]]}


# ---------- Kanada ----------
def iw_ca_czesc(prev, dzis):
    """Odczyty oficjalnych rezerw: razem, dolary, inne waluty, złoto, SDR, pozycja w MFW (mln USD) + pozycja „pozostałe aktywa” (tylko w części odczytów, w starszych jej brak — wtedy liczymy ją jako resztę).
    Odczyt bez całości albo któregoś składnika (zdarza się wiersz z samą pozycją „pozostałe”) jest pomijany; ostatni odczyt musi być pełny. Bramki: całość − pięć składników = reszta w [0, 10% całości] i równa podanej
    pozycji „pozostałe” (±2), odstęp między odczytami najwyżej 14 dni, ostatni odczyt nie starszy niż 75 dni."""
    j = iw_json(IW_CA_URL)
    obs = j.get('observations') if isinstance(j, dict) else None
    if not isinstance(obs, list) or len(obs) < 20:
        raise RuntimeError('Kanada: za mało odczytów')
    wz, pominiete = [], []
    for o in obs:
        d = iw_dzien(o.get('d')) if isinstance(o, dict) else None
        if d is None:
            raise RuntimeError(f'Kanada: zły odczyt {str(o)[:60]}')
        v = []
        for i in IW_CA_IDS[:6]:
            x = o.get(i)
            n = iw_liczba(_num(x.get('v')) if isinstance(x, dict) else None, 0, 1000000)
            v.append(None if n is None else int(round(n)))
        if None in v:
            pominiete.append(d)
            continue
        reszta = v[0] - sum(v[1:])
        x = o.get(IW_CA_IDS[6])
        inne = iw_liczba(_num(x.get('v')) if isinstance(x, dict) else None, 0, 1000000)
        if not 0 <= reszta <= v[0] * 0.1 or (inne is not None and abs(reszta - inne) > 2):
            raise RuntimeError(f'Kanada: składniki ≠ razem w odczycie {d}')
        wz.append((d, v))
    wz.sort(key=lambda x: x[0])
    if len(wz) < 20 or (pominiete and max(pominiete) > wz[-1][0]):
        raise RuntimeError('Kanada: za mało pełnych odczytów albo ostatni odczyt niepełny')
    if any(wz[i][0] == wz[i - 1][0] or (wz[i][0] - wz[i - 1][0]).days > 14 for i in range(1, len(wz))):
        raise RuntimeError('Kanada: powtórzenie albo luka większa niż 14 dni')
    if (dzis - wz[-1][0]).days > 75 or wz[-1][0] > dzis:
        raise RuntimeError(f'Kanada: ostatni odczyt {wz[-1][0]}')
    return {'asof': wz[-1][0].isoformat(), 's': [[d.isoformat()] + v for d, v in wz]}


# ---------- oczekiwania rynku w Brazylii ----------
def iw_focus_ind(klucz, wiersze, lo, hi, dzis):
    """Wiersze jednego wskaźnika (dzienne, trzy lata odniesienia od roku ostatniego dnia) → {'last': [[mediana, średnia, odchylenie, min, max, respondenci] × 3], 'w': [[[dzień, mediana] …] × 3]}; ostatni dzień każdego
    tygodnia (do IW_FOCUS_TYG tygodni). Bramki: komplet trzech lat w ostatnim dniu, mediana w [min, max] i w zakresie, odchylenie ≥ 0, co najmniej 5 respondentów, ostatni dzień nie starszy niż IW_FOCUS_MAX_DNI."""
    if not isinstance(wiersze, list) or not wiersze:
        raise RuntimeError(f'Focus {klucz}: brak wierszy')
    dni_ok = [iw_dzien(r.get('Data')) for r in wiersze if isinstance(r, dict)]
    if not all(dni_ok):
        raise RuntimeError(f'Focus {klucz}: zły dzień w wierszu')
    ost = max(dni_ok)
    if (dzis - ost).days > IW_FOCUS_MAX_DNI or ost > dzis or ost.weekday() > 4:
        raise RuntimeError(f'Focus {klucz}: ostatni dzień {ost}')
    lata = [ost.year, ost.year + 1, ost.year + 2]
    by = {}
    for r in wiersze:   # ścisła walidacja tylko lat odniesienia z ostatniego dnia (dalsze lata w odpowiedzi są pomijane)
        d, ref = iw_dzien(r.get('Data')), r.get('DataReferencia')
        if not isinstance(ref, str) or not re.fullmatch(r'\d{4}', ref) or int(ref) not in lata:
            continue
        med, sr, sd = iw_liczba(r.get('Mediana'), lo, hi), iw_liczba(r.get('Media'), lo, hi), iw_liczba(r.get('DesvioPadrao'), 0, 1000)
        mn, mx, n = iw_liczba(r.get('Minimo'), lo, hi), iw_liczba(r.get('Maximo'), lo, hi), iw_liczba(r.get('numeroRespondentes'), 0, 100000)
        if None in (med, sr, sd, mn, mx, n) or not mn <= med <= mx:
            raise RuntimeError(f'Focus {klucz}: zły wiersz {str(r)[:60]}')
        by.setdefault(d, {})[int(ref)] = [round(med, 4), round(sr, 4), round(sd, 4), round(mn, 4), round(mx, 4), int(n)]
    dni = sorted(by)
    if ost not in by or any(y not in by[ost] for y in lata):
        raise RuntimeError(f'Focus {klucz}: w dniu {ost} brakuje lat {[y for y in lata if y not in by.get(ost, {})]}')
    if any(by[ost][y][5] < 5 for y in lata):
        raise RuntimeError(f'Focus {klucz}: mniej niż 5 respondentów')
    tyg = {}
    for d in dni:
        if all(y in by[d] for y in lata):
            tyg[d.isocalendar()[:2]] = d
    pr = sorted(tyg.values())[-IW_FOCUS_TYG:]
    return {'last': [by[ost][y] for y in lata], 'w': [[[d.isoformat(), by[d][y][0]] for d in pr] for y in lata]}, ost, lata


def iw_focus_czesc(prev, dzis):
    od = (dzis - datetime.timedelta(days=IW_FOCUS_DNI)).isoformat()
    out, ost, lata = {}, None, None
    for klucz, ind, lo, hi in IW_FOCUS_IND:
        j = iw_json(IW_FOCUS_URL.format(ind=ind, od=od))
        w = j.get('value') if isinstance(j, dict) else None
        o, d, l = iw_focus_ind(klucz, w, lo, hi, dzis)
        if ost is not None and (d != ost or l != lata):
            raise RuntimeError('Focus: wskaźniki z różnych dni badania')
        out[klucz], ost, lata = o, d, l
    return {'asof': ost.isoformat(), 'y': lata, 'i': out}


def iw_czesc(k, prev_part, dzis):
    if k == 'jp':
        out = iw_jp_czesc(prev_part)
    elif k == 'hk':
        out = iw_hk_czesc(prev_part, dzis)
    elif k == 'ar':
        out = iw_ar_czesc(prev_part, dzis)
    elif k == 'br':
        out = iw_br_czesc(prev_part, dzis)
    elif k == 'ca':
        out = iw_ca_czesc(prev_part, dzis)
    else:
        out = iw_focus_czesc(prev_part, dzis)
    out['t'] = NOW
    return out


def iw_swieza(prev, k):
    """Czy udana część poprzedniego pliku jest młodsza niż IW_REUSE_MIN[k] min (wtedy bez ponownego pytania)."""
    if not isinstance(prev.get(k), dict) or _dict(prev.get('ok')).get(k) is not True:
        return False
    tk, tn = _ix_dt(_dict(prev.get('part_at')).get(k)), _ix_dt(NOW)
    return tk is not None and tn is not None and 0 <= (tn - tk).total_seconds() < IW_REUSE_MIN[k] * 60


def iw_br_przerwa_nota(czesc, msg):
    """v427: notatka o przerwie banku w części Brazylia (jedna dla przebudowy i dla ponownego użycia poprzedniego pliku): przyczyna i dzień poprzednich danych."""
    return mask(f"{IW_PX} {IW_LABEL['br']}: bank nie podaje danych ({msg}) — zostają dane z dnia {_dict(czesc).get('asof') or '—'}")[:260]


def iw_br_przerwa_trwa(prev):
    """v427: czy część br poprzedniego pliku niesie znacznik przerwy banku (v416/v427), a jej dane są młodsze niż BCB_PRZERWA_DNI dób (wiek wg part_at, w razie braku — chwili pliku)."""
    pp = _dict(prev).get('br')
    if not isinstance(pp, dict) or not isinstance(pp.get('przerwa'), dict):
        return False
    return bcb_przerwa_dozwolona(BcbPrzerwa('przerwa'), pp, _dict(_dict(prev).get('part_at')).get('br') or _dict(prev).get('at'))


def iw_bez_przerwy(czesc):
    """v427: poprzednia część bez znacznika przerwy (inny błąd niż przerwa banku nie dziedziczy starego znacznika)."""
    return {kk: vv for kk, vv in czesc.items() if kk != 'przerwa'}


def build_interwencje(prev=None, run_t0=None):
    """Plik data/interwencje.json (v401): sześć części (jp, hk, ar, br, ca, focus) z własnym ok / part_at / errs; udana część młodsza niż IW_REUSE_MIN[k] min jest używana ponownie; część z błędem zostaje z poprzedniego
    pliku z własną chwilą, nigdy pusta zamiast ostatnich danych; żadna część nie odpowiedziała (i żadna nie jest świeża) = wyjątek (przebieg główny zostawia poprzedni plik)."""
    prev = prev if isinstance(prev, dict) and prev.get('v') == IW_V else {}
    pat = _dict(prev.get('part_at'))
    dzis = datetime.datetime.fromisoformat(NOW).astimezone(datetime.timezone.utc).date()
    out = {'v': IW_V, 'at': NOW, 'src': IW_SRC, 'ok': {}, 'part_at': {}, 'errs': {}}
    for k in IW_PARTS:
        if iw_swieza(prev, k):
            out[k] = prev[k]
            out['ok'][k] = True
            out['part_at'][k] = pat.get(k)
            continue
        try:
            out[k] = iw_czesc(k, prev.get(k), dzis)
            out['ok'][k] = True
            out['part_at'][k] = NOW
        except Exception as e:  # noqa — część z błędem: poprzednie dane z własną chwilą
            msg = mask(f'{e}')[:160]
            if k == 'br' and bcb_przerwa_dozwolona(e, prev.get(k), pat.get(k) or prev.get('at')):   # v416: przerwa banku, dane młodsze niż 3 doby — poprzednie z datą + notatka (⚠️)
                out[k] = bcb_przerwa_wynik(prev[k], msg)   # v427: znacznik przerwy w części (od kiedy, ostatnia próba, ile prób, przyczyna) — czyta go też ścieżka „cached” w main()
                META['notes'].append(iw_br_przerwa_nota(out[k], msg))
                out['ok'][k] = False; out['errs'][k] = msg; out['part_at'][k] = pat.get(k) or prev.get('at')
                continue
            META['errors'].append(mask(f'{IW_PX} {IW_LABEL[k]}: {msg}')[:220])
            out['ok'][k] = False
            out['errs'][k] = msg
            if isinstance(prev.get(k), dict):
                out[k] = iw_bez_przerwy(prev[k])   # v427: inny błąd niż przerwa banku — bez starego znacznika
                out['part_at'][k] = pat.get(k) or prev.get('at')
    if not any(out['ok'].values()):
        raise RuntimeError('żadna część nie odpowiedziała')
    return out


ZRODLA_META.update({'interw_jp': 'mof-japonii', 'interw_hk': 'hkma', 'interw_ar': 'bcra', 'interw_br': 'bcb', 'interw_ca': 'bank-kanady', 'interw_focus': 'bcb-focus'})   # v401: trzy nowe źródła (hkma, bcra, bcb-focus); reszta to już liczone


# ===================== v402 (F11Z15): DeFi 2 — OPŁATY I PRZYCHODY PROTOKOŁÓW, CENY STABLECOINÓW, WŁAMANIA, OPCJE NA DEX (data/defi2.json) =====================
# Cztery niezależne części jednego pliku (każda z własnym czasem pobrania, 'ok' i poprzednią wersją przy awarii), publiczne zapytania GET bez klucza, nagłówek zbieracza, Accept-Encoding: gzip.
# Ta sama usługa co stablecoiny, RWA, giełdy i DEX (zgoda właściciela z 11.10.2026) — liczba źródeł bez zmian. Bez endpointów płatnych (HTTP 402) i bez list pul (yields: odpowiedź 11,5 MB — pominięta).
#  (1) fees — opłaty i przychody protokołów (/overview/fees, drugi raz z dataType=dailyRevenue; odpowiedzi ok. 1 MB po spakowaniu): sumy doby, 7 i 30 dób, 12 największych produktów wg opłat z 30 dób
#      (wersje i produkty tej samej firmy liczone osobno), kategorie, dzienna seria sum z 90 dób. Doba total24h NIE jest podana w odpowiedzi: ostatni punkt wykresu to doba w toku, więc dobę wskazuje
#      punkt wykresu najbliższy total24h (tolerancja 1 %) i zgodna z nim suma 7 dób (tolerancja 5 %; sprawdzone 17.10.2026: różnica 0,04 % i 0,13 %) — brak zgodności = błąd części, nigdy zgadywanie.
#      Suma wierszy protokołów jest o kilka procent większa niż suma serwisu (podwójne liczenie warstw; sprawdzone 17.10.2026: doba +0,5 %, 30 dób +8,1 %) — udziały liczymy względem sumy kategorii, a sumy doby/7/30 dób bierzemy z serwisu.
#  (2) peg — dzienne ceny stablecoinów w USD (/stablecoinprices, 6 MB, ok. 215 monet od 2021; jedna cena na dobę) dla monet dolarowych (lista monet jak w panelu emitentów: pegType peggedUSD)
#      z podażą co najmniej DF2_PEG_MIN. Odchylenie od 1 USD, liczba monet powyżej 0,5 / 1 / 5 %, 12 największych (cena, najgorsza doba z 30 dób), monety odchylone o ≥ 1 %, największe odchylenie
#      10 największych monet w całej historii i seria 90 dób „najgorsze odchylenie z 10 największych”. Cena starsza niż 3 doby = moneta bez ceny (liczona osobno, nigdy zero). Cena dzienna to
#      jeden odczyt na dobę — wahania w ciągu doby mogą być większe (marzec 2023: USDC 0,9611 w odczycie dziennym).
#  (3) hacks — lista włamań i wycieków (/hacks, 356 KB): kwoty skradzione w latach, 90 dób i 12 miesiącach, podział wg rodzaju ataku i celu, 6 największych z 12 miesięcy i 6 najnowszych (od 0,1 mln USD).
#      Kwota brak = nieznana (liczona osobno, nie zero). Pole o odzyskanych środkach pominięte (u jednego wpisu większe od kwoty).
#  (4) opt — wolumen opcji na zdecentralizowanych giełdach (/overview/options, dataType=dailyNotionalVolume — wartość nominalna kontraktów; domyślny wariant źródła to premia, ok. 50 razy mniejsza).
# Rytm: część odświeżana raz na dobę UTC po godz. DF2_OD_GODZ (doba danych starsza niż wczoraj = ponowienie co DF2_PONOW_H h, bo serwis uzupełnia dane z opóźnieniem); część po błędzie ponawia co DF2_BLAD_H h.
# Część, która zawiodła, zostaje z poprzedniego pliku z własnym czasem najwyżej DF2_MAX_D dób. Odpowiedzi czytane kawałkami z limitem czasu i rozmiaru (gx_pobierz).
DF2_V = 1
DF2_API = 'https://api.llama.fi'
DF2_URL = {'fees': DF2_API + '/overview/fees?excludeTotalDataChartBreakdown=true',
           'rev': DF2_API + '/overview/fees?excludeTotalDataChart=true&excludeTotalDataChartBreakdown=true&dataType=dailyRevenue',
           'opt': DF2_API + '/overview/options?excludeTotalDataChartBreakdown=true&dataType=dailyNotionalVolume',
           'hacks': DF2_API + '/hacks',
           'ceny': 'https://stablecoins.llama.fi/stablecoinprices'}
DF2_PARTS = ('fees', 'peg', 'hacks', 'opt')
DF2_OD_GODZ = 2            # godzina UTC — przed nią serwis nie ma jeszcze pełnej wczorajszej doby
DF2_PONOW_H = 3            # h — doba danych starsza niż wczoraj: ponowienie nie częściej niż co tyle
DF2_BLAD_H = 2             # h — część, która zawiodła w poprzednim przebiegu: ponowienie nie częściej niż co tyle
DF2_MAX_D = 10             # dób — część po błędzie zostaje z poprzedniego pliku najwyżej tyle
DF2_SLEEP = 1.5            # s — odstęp między zapytaniami
DF2_REQ_S = 50             # s — limit jednego zapytania (czytanie kawałkami)
DF2_LIMIT = 170            # s — budżet czasu budowy pliku
DF2_MAKS = {'fees': (40_000_000, 12_000_000), 'rev': (40_000_000, 12_000_000), 'opt': (10_000_000, 3_000_000), 'hacks': (6_000_000, 2_000_000),
            'ceny': (40_000_000, 8_000_000), 'lista': (12_000_000, 4_000_000)}   # (po rozpakowaniu, na łączu) — bajty
DF2_TOL_DOBA = 0.01        # dopuszczalna różnica total24h i punktu wykresu (część) — gdy doba poprzednia nie potwierdza wskazania
DF2_TOL_DOBA_LUZ = 0.03    # v417: ta różnica, gdy doba poprzednia (total48hto24h) zgadza się z punktem tuż przed wskazanym (DF2_TOL_48)
DF2_TOL_48 = 0.02          # v417: dopuszczalna różnica total48hto24h i punktu wykresu z doby wcześniej (18.10.2026: 0,18 %)
DF2_CEL = {'fees': 1, 'opt': 1, 'peg': 0}   # doba, którą część ma mieć po godz. DF2_OD_GODZ: opłaty i opcje — wczorajszą (pełna doba), ceny — dzisiejszą (etykieta doby to jej początek, 00:00 UTC)
DF2_TOL_7D = 0.05          # dopuszczalna różnica total7d i sumy 7 punktów wykresu (część)
DF2_TOP = 12               # tyle największych produktów w tabeli opłat
DF2_KAT_N = 8              # tyle największych kategorii (reszta jako 'x')
DF2_SER = 90               # dób w seriach
DF2_FEES_ZAKRES = (1e6, 1e10)   # USD — suma opłat doby poza przedziałem to błąd odczytu (17.10.2026: 74 mln)
DF2_KAT = {'Stablecoin Issuer': 'stab', 'Dexs': 'dex', 'Launchpad': 'lau', 'Derivatives': 'der', 'Liquid Staking': 'lst', 'Prediction Market': 'pre', 'Lending': 'len', 'Chain': 'cha',
           'Trading App': 'app', 'RWA': 'rwa', 'Staking Pool': 'stp', 'NFT Marketplace': 'nft', 'Interface': 'int', 'CDP': 'cdp', 'Onchain Capital Allocator': 'oca', 'Basis Trading': 'bas',
           'Risk Curators': 'rsk', 'MEV': 'mev', 'DEX Aggregator': 'agg', 'Bridge': 'bri', 'Wallets': 'wal', 'Yield': 'yld', 'Liquid Restaking': 'lrs', 'Block Builders': 'blb'}
DF2_PEG_MIN = 50e6         # USD — najmniejsza podaż monety w statystykach odklejenia
DF2_PEG_PROGI = (0.5, 1.0, 5.0)   # % — progi liczby monet odchylonych od 1 USD
DF2_PEG_STARE_D = 3        # dób — cena starsza niż tyle = moneta bez ceny; ostatnia doba serii starsza niż tyle wobec chwili przebiegu = błąd
DF2_PEG_TOPN = 10          # tyle największych monet w serii „najgorsze odchylenie” i w historii
DF2_PEG_MIN_TOP = 6        # tyle monet z ceną musi mieć doba, żeby weszła do serii
DF2_PEG_OUT_N = 8
DF2_CL = {'Access Control': 'ac', 'Protocol Logic': 'pl', 'Token & Share Accounting': 'ts', 'Oracle Manipulation': 'om', 'Key Compromise': 'kc', 'Frontend & Infrastructure': 'fi',
          'Input Validation': 'iv', 'Reentrancy': 're', 'Social Engineering': 'se', 'Bridge & Cross-Chain': 'bx', 'Rugpull': 'rp', 'Governance': 'gv', 'Market Manipulation': 'mm'}
DF2_TT = {'DeFi Protocol': 'defi', 'CEX': 'cex', 'Token': 'tok', 'Chain': 'cha', 'Layer 1': 'cha', 'Wallet': 'wal'}
DF2_HACK_LATA = 6          # tyle ostatnich lat kalendarzowych (z bieżącym)
DF2_HACK_MIN_WIERSZY = 500
DF2_HACK_KWOTA_MAX = 1e11  # USD — kwota powyżej tego to błąd odczytu (największa w historii: 3,5 mld)
DF2_HACK_NOWE_OD = 1e5     # USD — najnowsze włamania pokazujemy od tej kwoty
DF2_HACK_STARE_D = 120     # dób — najnowszy wpis starszy niż tyle wobec chwili przebiegu = błąd odczytu
_DF2_TERMIN = [None]


def df2_num(v, lo=None, hi=None):
    """Skończona liczba (nie wartość logiczna) w przedziale [lo, hi] albo None."""
    if isinstance(v, bool) or not isinstance(v, (int, float)) or not _etf_math.isfinite(v):
        return None
    if (lo is not None and v < lo) or (hi is not None and v > hi):
        return None
    return float(v)


def df2_dzien(ts):
    """Sekundy epoki → data UTC RRRR-MM-DD; zły znacznik = None."""
    v = df2_num(ts, 1, 4e9)
    return datetime.datetime.fromtimestamp(v, datetime.timezone.utc).strftime('%Y-%m-%d') if v is not None else None


def df2_pobierz(klucz, url=None):
    """Jedyne miejsce sieci części DeFi 2 (testy je łatają): GET z gzip i limitami → obiekt JSON. Budżet czasu budowy: DF2_LIMIT s; po nim wyjątek."""
    zostalo = DF2_REQ_S
    if _DF2_TERMIN[0] is not None:
        zostalo = min(DF2_REQ_S, _DF2_TERMIN[0] - time.monotonic())
        if zostalo < 3:
            raise RuntimeError(f'limit czasu budowy ({DF2_LIMIT} s)')
    time.sleep(DF2_SLEEP)
    maks, gz = DF2_MAKS[klucz]
    raw, _ = gx_pobierz(url or DF2_URL[klucz], zostalo, maks, gz)
    return json.loads(raw.decode('utf-8'))


def df2_wykres(j):
    """totalDataChart → [(doba, wartość)] rosnąco, bez powtórzeń; zły punkt pomijany; za mało punktów = wyjątek."""
    W = {}
    for p in (j.get('totalDataChart') if isinstance(j, dict) else None) or []:
        if isinstance(p, (list, tuple)) and len(p) == 2:
            d, v = df2_dzien(p[0]), df2_num(p[1], 0)
            if d and v is not None:
                W[d] = v
    if len(W) < 40:
        raise ValueError('wykres sum: za mało punktów')
    return sorted(W.items())


def df2_doba(j, W):
    """Doba, której dotyczy total24h: punkt wykresu (jeden z dwóch ostatnich) najbliższy total24h w granicach DF2_TOL_DOBA (albo DF2_TOL_DOBA_LUZ, gdy potwierdza go doba
    poprzednia: total48hto24h) i zgodna z nim suma 7 dób (DF2_TOL_7D).
    → (doba, indeks punktu). Ostatni punkt wykresu bywa dobą w toku, więc wskazanie z wartości, nie z pozycji."""
    t24, t7, t48 = df2_num(j.get('total24h'), 0), df2_num(j.get('total7d'), 0), df2_num(j.get('total48hto24h'), 0)
    if not t24:
        raise ValueError('brak total24h')
    # v417: dwie kotwice tej samej doby — total24h w DF2_TOL_DOBA_LUZ od punktu k ORAZ total48hto24h (doba wcześniej) w DF2_TOL_48 od punktu k-1.
    # Serwis liczy sumę doby z innej chwili niż wykres (18.10.2026: 1,23 % przy 0,04–0,29 % dotąd), a doba w toku leży blisko wartości doby pełnej (1,31 %) —
    # sama wartość total24h nie rozstrzyga, doba poprzednia tak (0,18 % wobec 21 %). Remis w granicach 0,5 pp = doba starsza (pełna).
    zak = []
    if t48:
        for k in range(max(1, len(W) - 2), len(W)):
            e24, e48 = abs(W[k][1] - t24) / t24, abs(W[k - 1][1] - t48) / t48
            if e24 <= DF2_TOL_DOBA_LUZ and e48 <= DF2_TOL_48:
                zak.append((e24 + e48, k))
    if zak:
        s0, i = zak[0]
        for s, k in zak[1:]:
            if s < s0 - 0.005:
                s0, i = s, k
    else:
        i = min(range(max(0, len(W) - 2), len(W)), key=lambda k: abs(W[k][1] - t24))   # bez kotwicy: jak dotąd — sama wartość, 1 %
        if abs(W[i][1] - t24) > DF2_TOL_DOBA * t24:
            raise ValueError('doba total24h nie pasuje do wykresu')
    if t7 and i >= 6 and abs(sum(v for _, v in W[i - 6:i + 1]) - t7) > DF2_TOL_7D * t7:
        raise ValueError('suma 7 dób nie pasuje do wykresu')
    return W[i][0], i


def df2_wiersze(j):
    return [p for p in (j.get('protocols') if isinstance(j, dict) else None) or [] if isinstance(p, dict)]


def df2_fees(fj, rj=None):
    """/overview/fees (+ wariant przychodów) → część 'fees': {dzien, f24, f7, f7p, f30, f30p, r24, r30, rows, kat, seria, t}. Wiersz produktu: [nazwa, kategoria, opłaty doby, 7 dób, 30 dób,
    przychód 30 dób albo None, opłaty poprzednich 7 dób albo None]."""
    W = df2_wykres(fj)
    dzien, i = df2_doba(fj, W)
    g = lambda k: df2_num(fj.get(k), 0)  # noqa: E731
    f24, f7, f7p, f30, f30p = g('total24h'), g('total7d'), g('total14dto7d'), g('total30d'), g('total60dto30d')
    if f24 is None or not DF2_FEES_ZAKRES[0] <= f24 <= DF2_FEES_ZAKRES[1] or f30 is None or f30 < f24:
        raise ValueError('sumy opłat poza przedziałem')
    rev = {}
    r24 = r30 = None
    if isinstance(rj, dict):
        r24, r30 = df2_num(rj.get('total24h'), 0), df2_num(rj.get('total30d'), 0)
        if r24 is not None and r30 is not None and r24 <= f24 * 1.05 and r30 <= f30 * 1.05:
            for p in df2_wiersze(rj):
                v = df2_num(p.get('total30d'), 0)
                if v is not None and p.get('id') is not None:
                    rev[str(p['id'])] = v
        else:
            r24 = r30 = None   # przychody niespójne z opłatami (przychód ≤ opłaty) — pomijamy całą część, opłaty zostają
    wier, kat = [], {}
    for p in df2_wiersze(fj):
        a30 = df2_num(p.get('total30d'), 0)
        nm = re.sub(r'[\x00-\x1f]', '', str(p.get('name') or '')).strip()[:40]
        if not a30 or not nm:
            continue
        k = DF2_KAT.get(p.get('category'), 'x')
        a24, a7, a7p = df2_num(p.get('total24h'), 0), df2_num(p.get('total7d'), 0), df2_num(p.get('total14dto7d'), 0)
        rv = rev.get(str(p.get('id')))
        wier.append([nm, k, round(a24 or 0), round(a7 or 0), round(a30), round(rv) if rv else None, round(a7p) if a7p else None])
        s = kat.setdefault(k, [0.0, 0.0, 0.0])
        s[0] += a24 or 0
        s[1] += a30
        s[2] += rv or 0
    if len(wier) < 5:
        raise ValueError('za mało produktów z opłatami')
    wier.sort(key=lambda r: -r[4])
    jawne = sorted(((k, v) for k, v in kat.items() if k != 'x'), key=lambda kv: -kv[1][1])
    reszta = [0.0, 0.0, 0.0]
    for k, v in jawne[DF2_KAT_N:] + ([('x', kat['x'])] if 'x' in kat else []):
        reszta = [a + b for a, b in zip(reszta, v)]
    kat_out = [[k, round(v[0]), round(v[1]), round(v[2]) if r30 is not None else None] for k, v in jawne[:DF2_KAT_N]]
    if reszta[1] > 0:
        kat_out.append(['x', round(reszta[0]), round(reszta[1]), round(reszta[2]) if r30 is not None else None])
    seria = [[d, round(v / 1e6, 3)] for d, v in W[:i + 1]][-DF2_SER:]
    return {'dzien': dzien, 'f24': round(f24), 'f7': round(f7) if f7 is not None else None, 'f7p': round(f7p) if f7p is not None else None, 'f30': round(f30),
            'f30p': round(f30p) if f30p is not None else None, 'r24': round(r24) if r24 is not None else None, 'r30': round(r30) if r30 is not None else None,
            'rows': wier[:DF2_TOP], 'kat': kat_out, 'seria': seria, 't': NOW}


def df2_lista(lista):
    """Lista monet (/stablecoins) → {gecko_id: (symbol, nazwa, podaż USD)} dla monet dolarowych z podażą ≥ DF2_PEG_MIN; ta sama moneta pod dwoma wpisami = większa podaż."""
    A = lista.get('peggedAssets') if isinstance(lista, dict) else None
    if not isinstance(A, list) or not A:
        raise ValueError('lista monet: brak peggedAssets')
    uni = {}
    for a in A:
        if not isinstance(a, dict) or a.get('pegType') != 'peggedUSD' or not isinstance(a.get('gecko_id'), str) or not a['gecko_id']:
            continue
        c = df2_num((a.get('circulating') or {}).get('peggedUSD') if isinstance(a.get('circulating'), dict) else None, DF2_PEG_MIN)
        sy = re.sub(r'[\x00-\x1f]', '', str(a.get('symbol') or '')).strip()[:12]
        if c is None or not sy:
            continue
        if a['gecko_id'] not in uni or uni[a['gecko_id']][2] < c:
            uni[a['gecko_id']] = (sy, re.sub(r'[\x00-\x1f]', '', str(a.get('name') or sy)).strip()[:40], c)
    return uni


def df2_peg(lista, ceny, teraz=None):
    """Lista monet + dzienne ceny → część 'peg'. Pola: dzien (ostatnia doba serii), n (monety z ceną), sup (ich podaż), bez ([liczba, podaż] monet bez ceny z ostatnich 3 dób), lic ({próg: [liczba, podaż]}),
    top (12 największych: [symbol, nazwa, podaż, cena, cena najgorszej doby z 30 dób, ta doba]), out (odchylone o ≥ 1 %: [symbol, nazwa, podaż, cena]), ev (10 największych: [symbol, doba najgorszej ceny, cena]),
    seria ([doba, najgorsze odchylenie z 10 największych w %] z 90 dób), t."""
    uni = df2_lista(lista)
    S = {}
    tn = _ix_dt(teraz or NOW)
    jutro = (tn.date() + datetime.timedelta(days=1)).isoformat() if tn is not None else '9999-12-31'
    for s in ceny if isinstance(ceny, list) else []:
        if isinstance(s, dict) and isinstance(s.get('prices'), dict):
            d = df2_dzien(s.get('date'))
            if d and d <= jutro:   # doba z dalekiej przyszłości (zepsuty wiersz) nie wyznacza doby danych; etykieta bieżącej doby UTC bywa już w pliku
                S[d] = s['prices']
    if len(S) < 100:
        raise ValueError('ceny stablecoinów: za mało dób')
    dni = sorted(S)
    ost = dni[-1]
    if tn is not None and (tn.date() - datetime.date.fromisoformat(ost)).days > DF2_PEG_STARE_D:
        raise ValueError(f'ceny stablecoinów: ostatnia doba {ost} jest za stara')
    ost_d = datetime.date.fromisoformat(ost)
    hist = {g: [] for g in uni}
    for d in dni:
        P = S[d]
        for g in uni:
            v = df2_num(P.get(g), 1e-12, 1e6)
            if v is not None:
                hist[g].append((d, v))
    obecne, bez = {}, [0, 0.0]
    for g, (sy, nm, c) in uni.items():
        H = hist[g]
        if H and (ost_d - datetime.date.fromisoformat(H[-1][0])).days <= DF2_PEG_STARE_D:
            obecne[g] = H[-1][1]
        else:
            bez[0] += 1
            bez[1] += c
    if len(obecne) < 15:
        raise ValueError('ceny stablecoinów: za mało monet z ceną')
    wg_podazy = sorted(obecne, key=lambda g: -uni[g][2])
    sup = sum(uni[g][2] for g in obecne)
    lic = {}
    for pr in DF2_PEG_PROGI:
        gs = [g for g in obecne if abs(obecne[g] - 1) * 100 > pr]
        lic[str(pr)] = [len(gs), round(sum(uni[g][2] for g in gs))]
    od30 = (ost_d - datetime.timedelta(days=29)).isoformat()

    def najgorsza(g, od=None):
        H = [x for x in hist[g] if od is None or x[0] >= od]
        return max(H, key=lambda x: (abs(x[1] - 1), x[0])) if H else (None, None)
    top = []
    for g in wg_podazy[:DF2_TOP]:
        d30, p30 = najgorsza(g, od30)
        top.append([uni[g][0], uni[g][1], round(uni[g][2]), round(obecne[g], 5), round(p30, 5) if p30 is not None else None, d30])
    out = [[uni[g][0], uni[g][1], round(uni[g][2]), round(obecne[g], 5)] for g in wg_podazy if abs(obecne[g] - 1) * 100 >= 1.0][:DF2_PEG_OUT_N]
    dziesiec = wg_podazy[:DF2_PEG_TOPN]
    ev = []
    for g in dziesiec:
        d, p = najgorsza(g)
        if d is not None:
            ev.append([uni[g][0], d, round(p, 5)])
    od90 = (ost_d - datetime.timedelta(days=DF2_SER - 1)).isoformat()
    seria = []
    for d in dni:
        if d < od90:
            continue
        v = [abs(S[d][g] - 1) * 100 for g in dziesiec if df2_num(S[d].get(g), 1e-12, 1e6) is not None]
        if len(v) >= DF2_PEG_MIN_TOP:
            seria.append([d, round(max(v), 3)])
    if len(seria) < 30:
        raise ValueError('ceny stablecoinów: za krótka seria 90 dób')
    return {'dzien': ost, 'n': len(obecne), 'sup': round(sup), 'bez': [bez[0], round(bez[1])], 'lic': lic, 'top': top, 'out': out, 'ev': ev, 'seria': seria, 't': NOW}


def df2_hacks(j, teraz=None):
    """/hacks → część 'hacks'. Pola: lat (doba najnowszego wpisu), n (liczba wpisów w całości), lata ([rok, liczba, suma znanych kwot, liczba bez kwoty]), w90 i w365 ([liczba, suma, bez kwoty]),
    cl (rodzaje ataku z 12 miesięcy: [kod, liczba, suma]), tt (cele z 12 miesięcy), top (6 największych z 12 miesięcy: [nazwa, doba, kwota, rodzaj, cel]), nowe (6 najnowszych od 0,1 mln USD), t."""
    if not isinstance(j, list) or len(j) < DF2_HACK_MIN_WIERSZY:
        raise ValueError('lista włamań: za mało wpisów')
    tn = _ix_dt(teraz or NOW) or datetime.datetime.now(datetime.timezone.utc)
    dzis = tn.date()
    W = []
    for x in j:
        if not isinstance(x, dict):
            continue
        d = df2_dzien(x.get('date'))
        nm = re.sub(r'[\x00-\x1f]', '', str(x.get('name') or '')).strip()[:40]
        if not d or not nm or datetime.date.fromisoformat(d) > dzis + datetime.timedelta(days=1):
            continue
        kw = df2_num(x.get('amount'), 0, DF2_HACK_KWOTA_MAX)
        W.append((d, nm, kw if kw else None, DF2_CL.get(x.get('classification'), 'x'), DF2_TT.get(x.get('targetType'), 'x')))
    if len(W) < DF2_HACK_MIN_WIERSZY:
        raise ValueError('lista włamań: za mało poprawnych wpisów')
    W.sort(key=lambda w: (w[0], w[1]))
    lat = W[-1][0]
    if (dzis - datetime.date.fromisoformat(lat)).days > DF2_HACK_STARE_D:
        raise ValueError(f'lista włamań: najnowszy wpis {lat} jest za stary')
    od90, od365 = (dzis - datetime.timedelta(days=89)).isoformat(), (dzis - datetime.timedelta(days=364)).isoformat()
    lata = {y: [y, 0, 0, 0] for y in range(dzis.year - DF2_HACK_LATA + 1, dzis.year + 1)}
    w90, w365 = [0, 0, 0], [0, 0, 0]
    cl, tt = {}, {}
    for d, nm, kw, c, t_ in W:
        y = int(d[:4])
        if y in lata:
            lata[y][1] += 1
            lata[y][2] += kw or 0
            lata[y][3] += 0 if kw else 1
        for okno, od in ((w90, od90), (w365, od365)):
            if d >= od:
                okno[0] += 1
                okno[1] += kw or 0
                okno[2] += 0 if kw else 1
        if d >= od365 and kw:
            for m, k in ((cl, c), (tt, t_)):
                s = m.setdefault(k, [k, 0, 0])
                s[1] += 1
                s[2] += kw
    z12 = [w for w in W if w[0] >= od365 and w[2]]
    if w365[0] < 20:
        raise ValueError('lista włamań: za mało wpisów z 12 miesięcy')
    rows = lambda ws: [[nm, d, round(kw), c, t_] for d, nm, kw, c, t_ in ws]  # noqa: E731
    return {'lat': lat, 'n': len(W), 'lata': [[y, a, round(b), c] for y, a, b, c in lata.values()], 'w90': [w90[0], round(w90[1]), w90[2]], 'w365': [w365[0], round(w365[1]), w365[2]],
            'cl': sorted(([k, a, round(b)] for k, a, b in cl.values()), key=lambda r: -r[2]), 'tt': sorted(([k, a, round(b)] for k, a, b in tt.values()), key=lambda r: -r[2]),
            'top': rows(sorted(z12, key=lambda w: -w[2])[:6]), 'nowe': rows(sorted([w for w in W if w[2] and w[2] >= DF2_HACK_NOWE_OD], key=lambda w: w[0], reverse=True)[:6]), 't': NOW}


def df2_opt(j):
    """/overview/options (wartość nominalna) → część 'opt': {dzien, o24, o7, o7p, o30, o30p, top: [[nazwa, doba, 30 dób]], t}."""
    W = df2_wykres(j)
    dzien, i = df2_doba(j, W)
    g = lambda k: df2_num(j.get(k), 0)  # noqa: E731
    o24, o7, o7p, o30, o30p = g('total24h'), g('total7d'), g('total14dto7d'), g('total30d'), g('total60dto30d')
    if o24 is None or o30 is None or o30 < o24 or o24 > 1e12:
        raise ValueError('sumy opcji poza przedziałem')
    wier = []
    for p in df2_wiersze(j):
        a30 = df2_num(p.get('total30d'), 0)
        nm = re.sub(r'[\x00-\x1f]', '', str(p.get('name') or '')).strip()[:40]
        if a30 and nm:
            a24 = df2_num(p.get('total24h'), 0)
            wier.append([nm, round(a24) if a24 is not None else None, round(a30)])
    wier.sort(key=lambda r: -r[2])
    if not wier:
        raise ValueError('opcje: brak protokołów')
    return {'dzien': dzien, 'o24': round(o24), 'o7': round(o7) if o7 is not None else None, 'o7p': round(o7p) if o7p is not None else None, 'o30': round(o30),
            'o30p': round(o30p) if o30p is not None else None, 'top': wier[:4], 't': NOW}


def df2_trzeba(czas, dzien, ok_prev, teraz, cel=1):
    """Czy część pobrać w tym przebiegu. czas — chwila poprzedniego pobrania części (brak = tak); dzien — doba danych części (None: część dobowa bez doby — raz na dobę UTC);
    ok_prev — poprzednie pobranie się udało; cel — ile dób przed bieżącą ma mieć doba danych (1 = wczorajsza, 0 = dzisiejsza). Po błędzie: co DF2_BLAD_H h. Inaczej: po godz. DF2_OD_GODZ UTC, gdy doba danych
    starsza niż cel (albo dobowa część nie była dziś pobrana) i minęło DF2_PONOW_H h."""
    tk, tn = _ix_dt(czas), _ix_dt(teraz)
    if tn is None:
        return True
    if tk is None or tk > tn:
        return True
    h = (tn - tk).total_seconds() / 3600
    if not ok_prev:
        return h >= DF2_BLAD_H
    if tn.hour < DF2_OD_GODZ or h < DF2_PONOW_H:
        return False
    nowa = (tn.date() - datetime.timedelta(days=cel)).isoformat()
    return (dzien < nowa) if dzien else tk.date() < tn.date()


def df2_zadania(pv, teraz):
    """Które części pobrać w tym przebiegu → {część: bool}."""
    ok, pat = (pv.get('ok') if isinstance(pv.get('ok'), dict) else {}), (pv.get('part_at') if isinstance(pv.get('part_at'), dict) else {})
    out = {}
    for n in DF2_PARTS:
        c = pv.get(n) if isinstance(pv.get(n), dict) else None
        out[n] = True if c is None else df2_trzeba(pat.get(n) or pv.get('at'), c.get('dzien') if n != 'hacks' else None, ok.get(n, True) is not False, teraz, DF2_CEL.get(n, 1))
    return out


def df2_job(n):
    """Odczyt jednej części z sieci → gotowa część pliku (testy łatają df2_pobierz)."""
    if n == 'fees':
        fj = df2_pobierz('fees')
        try:
            rj = df2_pobierz('rev')
        except Exception as e:  # noqa — przychody to dodatek; opłaty zostają
            META['errors'].append(mask(f'DeFi 2: przychody protokołów: {e}')[:200])
            rj = None
        return df2_fees(fj, rj)
    if n == 'peg':
        lista = STE_LLAMA.get('j') if STE_LLAMA.get('at') == NOW else None
        if lista is None:
            lista = df2_pobierz('lista', STE_URL_LLAMA)
        return df2_peg(lista, df2_pobierz('ceny'))
    if n == 'hacks':
        return df2_hacks(df2_pobierz('hacks'))
    return df2_opt(df2_pobierz('opt'))


def build_defi2(prev=None, zadania=None):
    """v402: data/defi2.json {v, at, src, ok, part_at, fees, peg, hacks, opt} → (plik, {część: True | False | 'cached'}). Część pominięta (rytm) zostaje z poprzedniego pliku bez zmian; część po błędzie
    — z poprzedniego pliku z własnym czasem (najwyżej DF2_MAX_D dób), błąd do META['errors']. Żadna część w pliku = wyjątek (main zostawia poprzedni plik)."""
    pv = prev if isinstance(prev, dict) and prev.get('v') == DF2_V else {}
    zad = zadania if zadania is not None else df2_zadania(pv, NOW)
    pat0, ok0 = (pv.get('part_at') if isinstance(pv.get('part_at'), dict) else {}), (pv.get('ok') if isinstance(pv.get('ok'), dict) else {})
    out = {'v': DF2_V, 'at': NOW, 'src': 'opłaty i przychody protokołów DeFi, dzienne ceny stablecoinów, lista włamań i wolumen opcji na zdecentralizowanych giełdach (publiczne API DefiLlama)',
           'ok': {}, 'part_at': {}}
    st = {}
    _DF2_TERMIN[0] = time.monotonic() + DF2_LIMIT
    try:
        for n in DF2_PARTS:
            stara = pv.get(n) if isinstance(pv.get(n), dict) else None
            if not zad.get(n) and stara is not None:
                out[n], out['ok'][n], out['part_at'][n], st[n] = stara, ok0.get(n, True), pat0.get(n) or pv.get('at'), 'cached'
                continue
            try:
                out[n] = df2_job(n)
                out['ok'][n], out['part_at'][n], st[n] = True, NOW, True
            except Exception as e:  # noqa — jedna część nie psuje pozostałych
                META['errors'].append(mask(f'DeFi 2: {n}: {e}')[:200])
                out['ok'][n], st[n] = False, False
                if stara is not None and _zapas_wiek_ok(pat0.get(n) or pv.get('at'), DF2_MAX_D):
                    out[n], out['part_at'][n] = stara, pat0.get(n) or pv.get('at')
    finally:
        _DF2_TERMIN[0] = None
    if not any(isinstance(out.get(n), dict) for n in DF2_PARTS):
        raise RuntimeError('żadna część DeFi 2 nie ma danych')
    return out, st


def df2_czesc():
    """v402: część przebiegu → krotka wartości dla META['ok'] w kolejności DF2_PARTS: True = pobrane, 'cached' = poprzednia wersja wystarcza (rytm dobowy), False = część zawiodła. Nieudana budowa zostawia poprzedni plik."""
    prev = previous('defi2')
    prev = prev if isinstance(prev, dict) and prev.get('v') == DF2_V else None
    zad = df2_zadania(prev or {}, NOW)
    if prev and not any(zad.values()):
        save('defi2', prev)
        return tuple('cached' for _ in DF2_PARTS)
    try:
        obj, st = build_defi2(prev, zad)
        save('defi2', obj)
        return tuple(st.get(n, False) for n in DF2_PARTS)
    except Exception as e:  # noqa
        META['errors'].append(mask(f'DeFi 2: {e}')[:200])
        if prev:
            save('defi2', prev)
        return tuple(False for _ in DF2_PARTS)


