_KAP_T0 = [None]


def kap_get(url, maks, headers=None):
    """Jedno zapytanie GET (publiczne, bez klucza) z odstępem KAP_SLEEP, limitem czasu (KAP_TIMEOUT, nie więcej niż reszta budżetu budowy) i limitem rozmiaru `maks` B (dłuższa odpowiedź = błąd)."""
    t0 = _KAP_T0[0]
    lim = KAP_TIMEOUT
    if t0 is not None:
        left = KAP_LIMIT_S - (time.monotonic() - t0)
        if left < 3:
            raise RuntimeError(f'limit czasu budowy ({KAP_LIMIT_S} s)')
        lim = max(3, min(KAP_TIMEOUT, left))
    time.sleep(KAP_SLEEP)
    return get_bytes_maks(url, headers, timeout=lim, maks=maks)


def kap_json(raw):
    """Odpowiedź → obiekt JSON; HTML (strona błędu / odmowy) albo ucięty tekst = ValueError."""
    try:
        return json.loads(raw.decode('utf-8') if isinstance(raw, (bytes, bytearray)) else raw)
    except ValueError:
        raise ValueError('odpowiedź nie jest JSON (strona błędu albo odmowa)') from None


def kap_liczba(x, lo, hi, co):
    """Liczba skończona z tekstu dziesiętnego (albo liczby) w przedziale [lo, hi]; wartość logiczna, brak, NaN i poza przedziałem = ValueError."""
    if isinstance(x, bool):
        raise ValueError(f'{co}: wartość logiczna')
    try:
        v = float(x.strip()) if isinstance(x, str) else float(x)
    except (TypeError, ValueError, AttributeError):
        raise ValueError(f'{co}: nie liczba ({str(x)[:12]!r})') from None
    if v != v or v in (float('inf'), float('-inf')) or not lo <= v <= hi:
        raise ValueError(f'{co}: poza zakresem ({v})')
    return v


def kap_scal(stare, nowe, ile):
    """Historia wierszy [dzień, liczba]: nowe zastępują stare o tym samym dniu, wynik rosnąco, najwyżej `ile` ostatnich; wiersz o złym kształcie jest pomijany."""
    m = {}
    for r in list(stare or []) + list(nowe or []):
        if isinstance(r, (list, tuple)) and len(r) == 2 and isinstance(r[0], str) and isinstance(r[1], (int, float)) and not isinstance(r[1], bool):
            m[r[0]] = [r[0], r[1]]
    return [m[k] for k in sorted(m)][-ile:]


# ---------------------------------------------------------------- kursy EBC ----------------------------------------------------------------
def kap_fx(d, fxc):
    """Kursy EBC na dzień d (RRRR-MM-DD): {'f': dzień fixingu, 'usd_eur': dolarów za euro, 'jpy_usd': jenów za dolara}; ostatni fixing nie później niż d i nie wcześniej niż d − KAP_FX_OKNO dni. Wynik zapamiętany w fxc
    (kursy z końca kwartału i miesiąca nie zmieniają się — drugie zapytanie o ten dzień nie jest potrzebne)."""
    if isinstance(fxc.get(d), dict):
        return fxc[d]
    dd = datetime.date.fromisoformat(d)
    od = (dd - datetime.timedelta(days=KAP_FX_OKNO + 3)).isoformat()
    by_day = fx_ecb_csv(kap_get(KAP_FX_URL.format(od=od, do=d), KAP_MAXB['fx']).decode('utf-8', 'replace'))
    dni = [x for x in sorted(by_day) if x <= d and by_day[x].get('USD') and by_day[x].get('JPY')]
    if not dni:
        raise ValueError(f'kursy EBC na {d}: brak fixingu')
    f = dni[-1]
    if (dd - datetime.date.fromisoformat(f)).days > KAP_FX_OKNO:
        raise ValueError(f'kursy EBC na {d}: ostatni fixing {f} jest za stary')
    usd_eur = kap_liczba(by_day[f]['USD'], 0.5, 2.0, 'kurs USD za EUR')
    jpy_usd = kap_liczba(by_day[f]['JPY'] / by_day[f]['USD'], 60.0, 300.0, 'kurs JPY za USD')
    fxc[d] = {'f': f, 'usd_eur': round(usd_eur, 4), 'jpy_usd': round(jpy_usd, 3)}
    return fxc[d]


# ---------------------------------------------------------------- us: zestawienie spółek USA ----------------------------------------------------------------
def kap_us_sesja(now):
    """Dzień (RRRR-MM-DD) ostatniej zamkniętej sesji USA według kalendarza tygodnia, gdy teraz trwa „cisza” między sesjami (poza notowaniami przed sesją i po niej), inaczej None. Cisza: dni robocze
    01:30–07:30 UTC (dzień = poprzedni dzień roboczy), sobota od 01:30 i niedziela cały dzień (dzień = piątek). Święta giełdy w kalendarzu nie są znane — patrz kap_us (identyczna suma = nie nowa sesja)."""
    now = now.astimezone(datetime.timezone.utc)
    d, m, wd = now.date(), now.hour * 60 + now.minute, now.weekday()
    if wd == 6 or (wd == 5 and m >= 90):
        return (d - datetime.timedelta(days=wd - 4)).isoformat()
    if wd < 5 and 90 <= m < 450:
        return (d - datetime.timedelta(days=3 if wd == 0 else 1)).isoformat()
    return None


def kap_baza_nazwy(nazwa):
    """Nazwa spółki bez oznaczenia klasy akcji i rodzaju papieru („Alphabet Inc. Class A Common Stock” i „Alphabet Inc. Class C Capital Stock” → „alphabet inc”) — klucz grupy klas tej samej spółki."""
    n = re.sub(r'\s*[-,]?\s*(class|series)\s+[a-z0-9]+\b.*$', '', str(nazwa), flags=re.I)
    n = re.sub(r'\s+(common stock|common shares|ordinary shares|capital stock|shares of beneficial interest|common units?|limited partnership interests|beneficial interest)\b.*$', '', n, flags=re.I)
    return re.sub(r'\s+', ' ', re.sub(r'[.,]', '', n)).strip().lower()


def kap_us_parse(raw):
    """Zestawienie spółek → {'n_wierszy', 'n': liczba spółek po odsianiu, 'mld': suma mld USD, 'zm': zmiana dnia w % (ważona kapitalizacją), 'top': [[symbol, mld]] (5), 'top10': udział 10 największych w %,
    'sek': [[sektor, mld]] malejąco}. Odsiew: kraj „United States”, kapitalizacja > 0, nazwa bez obligacji / akcji uprzywilejowanych / kwitów / jednostek; grupa klas = największa kapitalizacja.
    Zła powłoka, mało wierszy albo spółek, suma poza zakresem, udział jednej spółki > 30 % = ValueError."""
    j = kap_json(raw)
    d = j.get('data') if isinstance(j, dict) else None
    rows = d.get('rows') if isinstance(d, dict) else None
    if not isinstance(rows, list) or len(rows) < KAP_US_MIN_WIERSZY:
        raise ValueError('zestawienie spółek: zły kształt albo za mało wierszy')
    grupy = {}
    for r in rows:
        if not isinstance(r, dict) or r.get('country') != 'United States' or not isinstance(r.get('name'), str) or not isinstance(r.get('symbol'), str):
            continue
        if KAP_NIE_AKCJE.search(r['name']):
            continue
        try:
            cap = float(str(r.get('marketCap') or '').strip())
        except ValueError:
            continue
        if not (cap == cap and 1e6 <= cap <= 2e13):
            continue
        k = kap_baza_nazwy(r['name'])
        if k not in grupy or cap > grupy[k][0]:
            grupy[k] = (cap, r['symbol'].strip(), r.get('sector') if isinstance(r.get('sector'), str) else '', r.get('pctchange'))
    if len(grupy) < KAP_US_MIN_SPOLEK:
        raise ValueError(f'zestawienie spółek: tylko {len(grupy)} spółek po odsianiu')
    razem = sum(v[0] for v in grupy.values()) / 1e9
    if not KAP_US_ZAKRES[0] <= razem <= KAP_US_ZAKRES[1]:
        raise ValueError(f'zestawienie spółek: suma {razem:.0f} mld USD poza zakresem')
    wg = sorted(grupy.values(), key=lambda v: -v[0])
    if wg[0][0] / 1e9 > 0.30 * razem:
        raise ValueError('zestawienie spółek: jedna spółka ponad 30 % sumy')
    sek = {}
    for cap, _s, sk, _p in wg:
        i = KAP_SEKTORY.get(sk, 'inne')
        sek[i] = sek.get(i, 0.0) + cap / 1e9
    teraz = pop = 0.0   # zmiana dnia: kapitalizacja teraz ÷ kapitalizacja przed zmianą (z procentu każdego wiersza), tylko spółki z procentem
    for cap, _s, _sk, p in wg:
        try:
            x = float(str(p).strip().rstrip('%'))
        except ValueError:
            continue
        if x == x and -90 < x < 1000:
            teraz += cap
            pop += cap / (1 + x / 100)
    zm = None
    if pop > 0 and teraz / (razem * 1e9) >= 0.9:
        zm = round((teraz / pop - 1) * 100, 2)
        if abs(zm) > 25:
            raise ValueError(f'zestawienie spółek: zmiana dnia {zm} % nieprawdopodobna')
    return {'n_wierszy': len(rows), 'n': len(grupy), 'mld': round(razem, 1), 'zm': zm, 'top': [[s, round(c / 1e9, 1)] for c, s, _sk, _p in wg[:5]],
            'top10': round(sum(v[0] for v in wg[:10]) / 1e9 / razem * 100, 1), 'sek': [[k, round(v, 1)] for k, v in sorted(sek.items(), key=lambda kv: -kv[1])]}


def kap_us(pk, now):
    """Część us: jedno zapytanie, dzień = kap_us_sesja(now); suma identyczna jak poprzednia (święto) = dzień nie rusza się, sprawdzenie zapisane (checked_for); suma różna o więcej niż KAP_US_SKOK = ValueError."""
    exp = kap_us_sesja(now)
    if exp is None:
        raise RuntimeError('odczyt poza ciszą między sesjami')
    o = kap_us_parse(kap_get(KAP_US_URL, KAP_MAXB['us'], {'Accept': 'application/json'}))
    if isinstance(pk, dict) and isinstance(pk.get('mld'), (int, float)) and isinstance(pk.get('asof'), str):
        if abs(o['mld'] - pk['mld']) < 0.05:   # to samo zestawienie co poprzednio: nie było nowej sesji (święto giełdy) — dzień zostaje
            return dict(pk, checked_for=exp)
        if pk['asof'] >= exp:
            raise ValueError(f'zestawienie zmieniło się mimo tego samego dnia sesji ({exp})')
        if (datetime.date.fromisoformat(exp) - datetime.date.fromisoformat(pk['asof'])).days <= 10 and abs(o['mld'] / pk['mld'] - 1) > KAP_US_SKOK:
            raise ValueError(f"zestawienie spółek: suma {o['mld']:.0f} mld USD przy poprzedniej {pk['mld']:.0f} — skok ponad {int(KAP_US_SKOK * 100)} %")
    o['asof'] = exp
    o['checked_for'] = exp
    o['h'] = kap_scal(pk.get('h') if isinstance(pk, dict) else None, [[exp, o['mld']]], KAP_H['us'])
    return o


# ---------------------------------------------------------------- eu: rachunki kwartalne (akcje notowane) ----------------------------------------------------------------
def kap_kwartal_koniec(q):
    """'2026-Q2' → data ostatniego dnia kwartału ('2026-06-30'); zły zapis = ValueError."""
    m = re.fullmatch(r'(\d{4})-Q([1-4])', str(q))
    if not m:
        raise ValueError(f'zły kwartał {str(q)[:10]!r}')
    y, k = int(m.group(1)), int(m.group(2))
    return (datetime.date(y + (k == 4), k * 3 % 12 + 1, 1) - datetime.timedelta(days=1)).isoformat()


def kap_eu_parse(raw, now):
    """Odpowiedź JSON-stat (wymiary w kolejności id: freq, unit, sector, finpos, na_item, geo, time) → {'kraje': {kraj: {'q', 'd', 'eur': mld EUR}}, 'h': {kraj: [[kwartał, mld EUR]]}}, tylko kwartały KOMPLETNE
    (liczba dla obu sektorów S11 i S12). Zły kształt, brak wymiaru, kraj poza listą, liczba poza zakresem, kwartał z przyszłości, skok ostatniego kwartału większy niż KAP_EU_SKOK, ostatni kompletny kwartał
    starszy niż KAP_EU_NAJSTARSZY dni = kraj pomijany (błąd części, gdy nie zostaje żaden); mniej niż 5 krajów = ValueError."""
    j = kap_json(raw)
    if not isinstance(j, dict) or not isinstance(j.get('value'), dict) or not isinstance(j.get('id'), list) or not isinstance(j.get('size'), list) or not isinstance(j.get('dimension'), dict):
        raise ValueError('rachunki kwartalne: zły kształt odpowiedzi')
    ids, size, dim = j['id'], j['size'], j['dimension']
    if len(ids) != len(size) or not all(k in ids for k in ('sector', 'geo', 'time')) or not all(isinstance(n, int) and n >= 1 for n in size):
        raise ValueError('rachunki kwartalne: brak wymiaru sector / geo / time')
    idx = {}
    for k in ('sector', 'geo', 'time'):
        c = dim.get(k, {}).get('category', {}).get('index') if isinstance(dim.get(k), dict) else None
        if isinstance(c, list):
            c = {x: i for i, x in enumerate(c)}
        if not isinstance(c, dict) or not c:
            raise ValueError(f'rachunki kwartalne: wymiar {k} bez kategorii')
        idx[k] = c
    krok, s = {}, 1
    for k, n in zip(reversed(ids), reversed(size)):
        krok[k] = s
        s *= n
    dzis = now.date()
    kraje, hist = {}, {}
    for g in idx['geo']:
        if g not in KAP_EU_GEO:
            raise ValueError(f'rachunki kwartalne: kraj {str(g)[:6]!r} spoza listy')
        wiersze = []
        for q in sorted(idx['time']):
            suma, ok = 0.0, True
            for sk in idx['sector']:
                x = j['value'].get(str(idx['sector'][sk] * krok['sector'] + idx['geo'][g] * krok['geo'] + idx['time'][q] * krok['time']))
                if x is None:
                    ok = False
                    break
                suma += kap_liczba(x, 0, 1e8, f'{g} {q}')
            if ok:
                if datetime.date.fromisoformat(kap_kwartal_koniec(q)) > dzis:
                    raise ValueError(f'rachunki kwartalne: kwartał {q} z przyszłości')
                mld = suma / 1000.0
                if not KAP_EU_ZAKRES[0] <= mld <= KAP_EU_ZAKRES[1]:
                    raise ValueError(f'rachunki kwartalne: {g} {q} {mld:.0f} mld EUR poza zakresem')
                wiersze.append([q, round(mld, 1)])
        if len(wiersze) > 1 and abs(wiersze[-1][1] / wiersze[-2][1] - 1) > KAP_EU_SKOK:   # skok sprawdzany tylko dla ostatniego kwartału (stary skok w historii nie blokuje pliku na zawsze)
            raise ValueError(f'rachunki kwartalne: {g} {wiersze[-1][0]} skok o {abs(wiersze[-1][1] / wiersze[-2][1] - 1) * 100:.0f} %')
        if wiersze and (dzis - datetime.date.fromisoformat(kap_kwartal_koniec(wiersze[-1][0]))).days <= KAP_EU_NAJSTARSZY:
            kraje[g] = {'q': wiersze[-1][0], 'd': kap_kwartal_koniec(wiersze[-1][0]), 'eur': wiersze[-1][1]}
            hist[g] = wiersze[-6:]
    if len(kraje) < 5:
        raise ValueError(f'rachunki kwartalne: tylko {len(kraje)} krajów z kompletnym kwartałem')
    return {'kraje': kraje, 'h': hist}


def kap_eu(pk, now, fxc):
    """Część eu: jedno zapytanie o rachunki kwartalne + kurs EBC na koniec kwartału każdego kraju (zwykle jedna data) → kraje[kraj] z polami usd (mld USD), kurs (USD za EUR), kurs_d (dzień fixingu)."""
    o = kap_eu_parse(kap_get(KAP_EU_URL.format(od=f'{now.year - 1}-Q1'), KAP_MAXB['eu']), now)
    for g, v in o['kraje'].items():
        fx = kap_fx(v['d'], fxc)
        v['kurs'], v['kurs_d'], v['usd'] = fx['usd_eur'], fx['f'], round(v['eur'] * fx['usd_eur'], 1)
    o['asof'] = max(v['d'] for v in o['kraje'].values())
    return o


# ---------------------------------------------------------------- jp: giełda w Tokio (koniec miesiąca) ----------------------------------------------------------------
def kap_xlsx_wiersze(raw, arkusz='xl/worksheets/sheet1.xml'):
    """Skoroszyt (xlsx) → {numer wiersza: {kolumna: liczba}} z komórek liczbowych arkusza; napisy (t="s"/"str") pomijane. Bez bibliotek zewnętrznych (zipfile + wyrażenia regularne); zły plik = ValueError."""
    import io as _io
    import zipfile as _zf
    try:
        with _zf.ZipFile(_io.BytesIO(raw)) as z:
            info = z.getinfo(arkusz)
            if info.file_size > 5000000:
                raise ValueError('arkusz za duży')
            xml = z.read(arkusz).decode('utf-8', 'replace')
    except (_zf.BadZipFile, KeyError) as e:
        raise ValueError(f'plik giełdy nie jest skoroszytem ({type(e).__name__})') from None
    out = {}
    for m in re.finditer(r'<c r="([A-Z]+)(\d+)"([^>]*?)(?:/>|>(.*?)</c>)', xml, re.S):
        kol, nr, atr, wn = m.group(1), int(m.group(2)), m.group(3), m.group(4) or ''
        if 't="s"' in atr or 't="str"' in atr or 't="inlineStr"' in atr:
            continue
        v = re.search(r'<v>([^<]*)</v>', wn)
        if v:
            try:
                out.setdefault(nr, {})[kol] = float(v.group(1))
            except ValueError:
                pass
    return out


def kap_jp_parse(raw, now):
    """Plik historyczny giełdy w Tokio → {'asof': dzień ostatniej sesji miesiąca, 'jpy_bln': razem w bilionach JPY, 'rynki': {prime, standard, growth, pro}, 'h': [[dzień, bln JPY]] (KAP_H['jp'] ostatnich)}.
    Wiersz = A: dzień (numer seryjny; ostatnia sesja miesiąca), B–E: rynki, F: razem (mln JPY). Suma rynków = razem (± 0,001 %), kolejne miesiące, każdy dzień w ostatnich 4 dniach miesiąca, razem w zakresie, skok do 25 % miesięcznie,
    ostatni miesiąc nie starszy niż KAP_JP_STARE dni i nie z przyszłości; mniej niż 12 wierszy = ValueError."""
    W = kap_xlsx_wiersze(raw)
    baza = datetime.date(1899, 12, 30)
    wiersze, ost = [], None
    for nr in sorted(W):
        c = W[nr]
        if not all(k in c for k in 'ABCDEF') or not 40000 <= c['A'] <= 60000:
            continue   # nagłówki i puste wiersze
        d = baza + datetime.timedelta(days=int(c['A']))
        if (datetime.date(d.year + (d.month == 12), d.month % 12 + 1, 1) - d).days > 4:   # ostatnia sesja miesiąca bywa 1–3 dni przed jego końcem (święta)
            raise ValueError(f'giełda w Tokio: {d} nie jest końcem miesiąca')
        if ost is not None and (d <= ost or (d.year, d.month) == (ost.year, ost.month)):
            raise ValueError(f'giełda w Tokio: miesiące nie rosną ({d})')
        ost = d
        razem = kap_liczba(c['F'], KAP_JP_ZAKRES[0], KAP_JP_ZAKRES[1], f'razem {d}')
        skl = [kap_liczba(c[k], 0, KAP_JP_ZAKRES[1], f'rynek {k} {d}') for k in 'BCDE']
        if abs(sum(skl) - razem) > max(1000.0, razem * 1e-5):
            raise ValueError(f'giełda w Tokio: suma rynków ≠ razem w {d}')
        if wiersze and abs(razem / wiersze[-1][1] - 1) > KAP_JP_SKOK:
            raise ValueError(f'giełda w Tokio: skok {abs(razem / wiersze[-1][1] - 1) * 100:.0f} % w {d}')
        wiersze.append((d.isoformat(), razem, skl))
    if len(wiersze) < 12:
        raise ValueError('giełda w Tokio: za mało wierszy miesięcznych')
    d, razem, skl = wiersze[-1]
    dd = datetime.date.fromisoformat(d)
    if dd > now.date():
        raise ValueError(f'giełda w Tokio: miesiąc {d} z przyszłości')
    if (now.date() - dd).days > KAP_JP_STARE:
        raise ValueError(f'giełda w Tokio: ostatni miesiąc {d} sprzed {(now.date() - dd).days} dni (źródło stoi)')
    return {'asof': d, 'jpy_bln': round(razem / 1e6, 2), 'rynki': dict(zip(('prime', 'standard', 'growth', 'pro'), [round(x / 1e6, 3) for x in skl])),
            'h': [[x[0], round(x[1] / 1e6, 2)] for x in wiersze[-KAP_H['jp']:]]}


def kap_jp(pk, now, fxc):
    """Część jp: strona z odnośnikiem + plik historyczny (xlsx) + kurs EBC na koniec miesiąca → pola d, usd_mld, kurs, kurs_d."""
    html = kap_get(KAP_JP_STRONA, KAP_MAXB['jp_html']).decode('utf-8', 'replace')
    m = re.search(r'href="(/[A-Za-z0-9_./-]*historical-jika\.xlsx)"', html)
    if not m:
        raise ValueError('strona giełdy w Tokio: brak odnośnika do pliku historycznego')
    o = kap_jp_parse(kap_get(KAP_JP_HOST + m.group(1), KAP_MAXB['jp_xlsx']), now)
    fx = kap_fx(o['asof'], fxc)
    o['kurs'], o['kurs_d'], o['usd_mld'] = fx['jpy_usd'], fx['f'], round(o['jpy_bln'] * 1000.0 / fx['jpy_usd'], 1)
    return o


# ---------------------------------------------------------------- budowa pliku ----------------------------------------------------------------
KAP_BUDOWA = {'us': lambda pk, now, fxc: kap_us(pk, now), 'eu': kap_eu, 'jp': kap_jp}


def kap_wymagana(k, pk, pok, pat, now):
    """Czy część k wymaga odczytu: brak części, poprzedni błąd; USA — cisza między sesjami i sesja jeszcze nie sprawdzona; Europa i Japonia — odczyt starszy niż KAP_INT[k] min."""
    if not isinstance(pk, dict) or pok.get(k) is False:
        return k != 'us' or kap_us_sesja(now) is not None
    if k == 'us':
        exp = kap_us_sesja(now)
        return exp is not None and pk.get('checked_for') != exp
    t = _ix_dt(pat.get(k))
    return t is None or (now - t).total_seconds() >= KAP_INT[k] * 60


def build_kapitalizacje(prev=None, run_t0=None):
    """Plik data/kapitalizacje.json (v420): trzy części (us, eu, jp) z własnym ok / part_at / errs; część z błędem zostaje z poprzedniego pliku z własną chwilą, nigdy pusta zamiast ostatnich danych;
    część, której odczyt nie jest jeszcze potrzebny (rytm, okno sesji), zostaje bez zmian z ok 'cached'. Żadna część nie ma danych = wyjątek (przebieg główny zostawia poprzedni plik)."""
    prev = prev if isinstance(prev, dict) and prev.get('v') == KAP_V else {}
    pat, pok = _dict(prev.get('part_at')), _dict(prev.get('ok'))
    now = datetime.datetime.fromisoformat(NOW).astimezone(datetime.timezone.utc)
    fxc = {k: v for k, v in _dict(prev.get('fx')).items() if isinstance(v, dict)}
    out = {'v': KAP_V, 'at': NOW, 'od': prev.get('od') if isinstance(prev.get('od'), str) else now.date().isoformat(), 'src': KAP_SRC, 'ok': {}, 'part_at': {}, 'errs': {}}
    _KAP_T0[0] = time.monotonic()
    try:
        for k in KAP_PARTS:
            pk = prev.get(k) if isinstance(prev.get(k), dict) else None
            if not kap_wymagana(k, pk, pok, pat, now):
                if pk is not None:
                    out[k] = pk
                    out['part_at'][k] = pat.get(k) or prev.get('at')
                out['ok'][k] = 'cached'
                continue
            try:
                out[k] = KAP_BUDOWA[k](pk, now, fxc)
                out['ok'][k] = True
                out['part_at'][k] = NOW
            except Exception as e:  # noqa — część z błędem: poprzednie dane z własną chwilą
                msg = mask(f'{e}')[:160]
                META['errors'].append(mask(f'{KAP_PX} {KAP_LABEL[k]}: {msg}')[:220])
                out['ok'][k] = False
                out['errs'][k] = msg
                if pk is not None:
                    out[k] = pk
                    out['part_at'][k] = pat.get(k) or prev.get('at')
    finally:
        _KAP_T0[0] = None
    if not any(isinstance(out.get(k), dict) for k in KAP_PARTS):
        raise RuntimeError('żadna część nie odpowiedziała')
    uzyte = {v['d'] for v in _dict(out.get('eu')).get('kraje', {}).values() if isinstance(v, dict)} | ({out['jp']['asof']} if isinstance(out.get('jp'), dict) and out['jp'].get('asof') else set())
    out['fx'] = {d: fxc[d] for d in sorted(fxc) if d in uzyte}
    return out


# v420: koniec modułu Kapitalizacje rynków


# ===================== v422 (F11Z25): SKARBCE SPÓŁEK — BTC I ETH W SPÓŁKACH PUBLICZNYCH I NOWE WNIOSKI O FUNDUSZE KRYPTO W KOLEJCE URZĘDU — data/krypto-firmy.json =====================
# Trzy niezależne części, każda z własnym czasem pobrania i raz na ~dobę (jedno zapytanie na dobę na część — limit publicznego planu usługi cen krypto):
#   btc / eth — zestawienie spółek publicznych z ich posiadaniem BTC albo ETH (to samo źródło i klucz co ceny krypto: klucz tylko w nagłówku, nigdy w adresie ani w pliku).
#               Zestawienie to deklaracje spółek zebrane przez dostawcę, bez daty stanu — data pliku = chwila pobrania. Historia sum (po jednym punkcie na dobę UTC) i zrzuty posiadania
#               co ≥ 6 dób pozwalają policzyć zmianę posiadania spółek od dnia zrzutu (nowe spółki na liście liczone osobno — to nie zakup).
#   sec       — nowe wnioski o fundusze oparte na krypto w kolejce amerykańskiego urzędu nadzoru: wyszukiwanie tekstowe wniosków rejestracyjnych (S-1) i rejestracji do notowania (8-A) z wzmianką
#               o bitcoinie albo aktywach cyfrowych. Fundusze = podmioty z ETF/ETP w nazwie i kodem branży funduszy towarowych/inwestycyjnych (wyszukiwanie tekstowe jest przybliżeniem:
#               fundusz o innym profilu, który tylko wspomina krypto, odpada, bo nie ma ETF/ETP w nazwie). Adres kontaktowy do nagłówka — wyłącznie z sekretu (jak insiderzy).
KF_V = 1
KF_URL = CG + '/companies/public_treasury/{a}'
KF_AKT = {'btc': 'bitcoin', 'eth': 'ethereum'}
KF_PARTS = ('btc', 'eth', 'sec')
KF_CO_H = 22              # h — pobranie raz na ~dobę (jedno zapytanie na dobę na część)
KF_BLAD_H = 3             # h — część, która zawiodła: ponowienie nie częściej niż co tyle
KF_MAX_D = 3              # dób — część po błędzie zostaje z poprzedniego pliku najwyżej tyle
KF_SLEEP = 2.5            # s — odstęp przed zapytaniem do usługi cen
KF_TIMEOUT = 30           # s
KF_ZAKRES = {'btc': (300_000, 3_000_000, 20), 'eth': (1_000_000, 30_000_000, 8)}   # suma posiadania poza przedziałem albo mniej spółek niż trzeci element = błąd odczytu (17.10.2026: 1,30 mln BTC w 180 spółkach; 8,10 mln ETH w 34)
KF_CENA = {'btc': (1_000, 1_000_000), 'eth': (50, 100_000)}   # USD — cena wynikająca z wartości i posiadania poza przedziałem = błąd odczytu (17.10.2026: 81,6 tys. i 2,41 tys.)
KF_ZGODA = 0.02           # dopuszczalna różnica sumy spółek i sumy źródła (część; 17.10.2026: 0)
KF_TOP = 15               # tyle największych spółek w pliku
KF_KRAJE = 6              # tyle największych krajów
KF_RUCH_N = 5             # tyle największych zwiększeń i zmniejszeń posiadania
KF_RUCH_MAX = 0.25        # zmiana sumy większa niż tyle (część) wobec zrzutu = zmiana zestawienia, nie zakupy — porównania nie pokazujemy
KF_HIST_MAX = 400         # punktów historii (po jednym na dobę UTC)
KF_SNAP_D = 6             # dób — zrzut posiadania nie częściej niż co tyle
KF_SNAP_N = 6             # zrzutów w pliku
KF_REF_MIN_D = 6          # dób — zrzut do porównania ma co najmniej tyle dób
KF_REF_MAX_D = 40         # dób — zrzut starszy niż tyle nie służy do porównania
KF_SEC_URL = 'https://efts.sec.gov/LATEST/search-index?q={q}&forms={f}&dateRange=custom&startdt={a}&enddt={b}'
KF_SEC_ZAPYTANIA = (('S-1', 'bitcoin'), ('S-1', 'digital asset'), ('8-A12B', 'bitcoin'), ('8-A12B', 'digital asset'))
KF_SEC_OKNO = 30          # dób — okno bieżące i poprzednie (razem 60 dób w jednym zapytaniu)
KF_SEC_LISTA = 10         # tyle funduszy na liście
KF_SEC_SIC = ('6221', '6199', '6211', '')   # branże funduszy towarowych i inwestycyjnych; pusty = nowy podmiot bez kodu
KF_ETF = re.compile(r'\b(?:ETF|ETP)s?\b', re.I)
KF_8A = re.compile(r'\b(?:ETF|ETP|Trust|Fund)s?\b', re.I)
_KF_NAWIAS = re.compile(r'\s*\([^()]*\)\s*$')
_KF_DZIEN = re.compile(r'^\d{4}-\d{2}-\d{2}$')


def kf_num(v, lo=None, hi=None):
    """Skończona liczba (nie wartość logiczna) w przedziale [lo, hi] albo None."""
    if isinstance(v, bool) or not isinstance(v, (int, float)) or not _etf_math.isfinite(v):
        return None
    if (lo is not None and v < lo) or (hi is not None and v > hi):
        return None
    return float(v)


def kf_dzien(iso):
    """Chwila ISO → data UTC RRRR-MM-DD albo None."""
    d = _ix_dt(iso)
    return d.date().isoformat() if d is not None else None


def kf_dni_miedzy(a, b):
    """Liczba dób od dnia a do dnia b (RRRR-MM-DD); zły zapis = None."""
    try:
        return (datetime.date.fromisoformat(b) - datetime.date.fromisoformat(a)).days
    except (TypeError, ValueError):
        return None


def kf_ref(snaps, dzien):
    """Najnowszy zrzut posiadania, który ma od KF_REF_MIN_D do KF_REF_MAX_D dób wobec dnia `dzien`; brak = None. Zrzut: [dzień, chwila, suma, {symbol: posiadanie}]."""
    best = None
    for s in snaps if isinstance(snaps, list) else []:
        if not (isinstance(s, list) and len(s) == 4 and isinstance(s[0], str) and kf_num(s[2], 0) is not None and isinstance(s[3], dict)):
            continue
        a = kf_dni_miedzy(s[0], dzien)
        if a is not None and KF_REF_MIN_D <= a <= KF_REF_MAX_D and (best is None or s[0] > best[0]):
            best = s
    return best


def kf_firmy(j, akt, teraz, prev=None):
    """Odpowiedź usługi (skarbce spółek) → część pliku (btc / eth). Zła odpowiedź = wyjątek (część zostaje z poprzedniego pliku)."""
    if not isinstance(j, dict) or not isinstance(j.get('companies'), list):
        raise RuntimeError('zły kształt odpowiedzi (brak listy spółek)')
    lo, hi, min_f = KF_ZAKRES[akt]
    total = kf_num(j.get('total_holdings'), lo, hi)
    usd = kf_num(j.get('total_value_usd'), 1e8, 1e13)
    dom = kf_num(j.get('market_cap_dominance'), 0.01, 50)
    if total is None or usd is None or dom is None:
        raise RuntimeError('suma posiadania, wartość albo udział w podaży poza zakresem sensu')
    cena = usd / total
    if not KF_CENA[akt][0] <= cena <= KF_CENA[akt][1]:
        raise RuntimeError(f'cena z wartości i posiadania poza zakresem sensu ({cena:.4g})')
    C = []
    for c in j['companies']:
        if not isinstance(c, dict):
            continue
        nazwa, h = c.get('name'), kf_num(c.get('total_holdings'), 0, total * 1.0001)
        if not isinstance(nazwa, str) or not nazwa.strip() or len(nazwa) > 80 or h is None or h <= 0:
            continue
        sym = c.get('symbol') if isinstance(c.get('symbol'), str) and 0 < len(c['symbol']) <= 24 else None
        kr = c.get('country') if isinstance(c.get('country'), str) and re.fullmatch(r'[A-Z]{2}', c['country']) else 'x'
        C.append([nazwa.strip(), sym, kr, round(h, 4), kf_num(c.get('percentage_of_total_supply'), 0, 100)])
    if len(C) < min_f:
        raise RuntimeError(f'za mało spółek z posiadaniem ({len(C)} < {min_f})')
    suma = sum(r[3] for r in C)
    if abs(suma - total) > total * KF_ZGODA:
        raise RuntimeError(f'suma posiadania spółek ({suma:.0f}) różni się od sumy usługi ({total:.0f})')
    C.sort(key=lambda r: -r[3])
    dzien = kf_dzien(teraz)
    kraje = {}
    for r in C:
        k = kraje.setdefault(r[2], [0.0, 0])
        k[0] += r[3]; k[1] += 1
    kr_l = sorted(([k, round(v[0], 2), v[1]] for k, v in kraje.items()), key=lambda x: -x[1])
    kr_top = [x for x in kr_l if x[0] != 'x'][:KF_KRAJE]
    sym_n = {}
    for r in C:
        if r[1]:
            sym_n[r[1]] = sym_n.get(r[1], 0) + 1
    mapa = {r[1]: r[3] for r in C if r[1] and sym_n[r[1]] == 1}   # symbol powtórzony = niejednoznaczny, bez porównania
    pv = prev if isinstance(prev, dict) else {}
    ref = kf_ref(pv.get('snaps'), dzien)
    zm = None
    if ref:
        dtot = suma - ref[2]
        if ref[2] > 0 and abs(dtot) <= ref[2] * KF_RUCH_MAX:
            ruch, nowe_n, nowe = [], 0, 0.0
            for r in C:
                if not r[1] or r[1] not in mapa:
                    continue
                if r[1] not in ref[3]:
                    nowe_n += 1; nowe += r[3]
                    continue
                d = r[3] - ref[3][r[1]]
                if abs(d) >= 1e-6:
                    ruch.append([r[0], r[1], round(d, 4)])
            plus = sorted((x for x in ruch if x[2] > 0), key=lambda x: -x[2])[:KF_RUCH_N]
            minus = sorted((x for x in ruch if x[2] < 0), key=lambda x: x[2])[:KF_RUCH_N]
            zm = {'od': ref[0], 'dtot': round(dtot, 4), 'nowe_n': nowe_n, 'nowe': round(nowe, 4), 'plus': plus, 'minus': minus,
                  'istniejace': round(dtot - nowe, 4)}
    top = []
    for r in C[:KF_TOP]:   # wiersz: [nazwa, symbol, kraj, posiadanie, udział w podaży, zmiana od zrzutu (None: brak porównania), nowa na liście]
        if ref and r[1] and r[1] in mapa:
            nw = r[1] not in ref[3]
            top.append(r + [None if nw else round(r[3] - ref[3][r[1]], 4), nw])
        else:
            top.append(r + [None, False])
    hist = [h for h in (pv.get('hist') if isinstance(pv.get('hist'), list) else [])
            if isinstance(h, list) and len(h) == 4 and isinstance(h[0], str) and _KF_DZIEN.match(h[0]) and h[0] != dzien and kf_num(h[1], 0) is not None]
    hist.append([dzien, round(suma, 2), len(C), round(cena, 2)])
    hist = sorted(hist, key=lambda h: h[0])[-KF_HIST_MAX:]
    snaps = [s for s in (pv.get('snaps') if isinstance(pv.get('snaps'), list) else []) if isinstance(s, list) and len(s) == 4 and isinstance(s[0], str) and isinstance(s[3], dict)]
    if not snaps or (kf_dni_miedzy(snaps[-1][0], dzien) or 0) >= KF_SNAP_D:
        snaps.append([dzien, teraz, round(suma, 4), mapa])
    snaps = snaps[-KF_SNAP_N:]
    return {'t': teraz, 'dzien': dzien, 'n': len(C), 'total': round(suma, 2), 'usd': round(usd, 2), 'cena': round(cena, 2), 'dom': dom,
            'top': top, 'kraje': kr_top, 'top5': round(sum(r[3] for r in C[:5]) / suma * 100, 2), 'zm': zm, 'hist': hist, 'snaps': snaps}


def kf_nazwa(dn):
    """Nazwa podmiotu z wpisu wyszukiwarki: bez końcowych nawiasów (symbole giełdowe i numer CIK)."""
    s = str(dn or '').strip()
    for _ in range(4):
        n = _KF_NAWIAS.sub('', s)
        if n == s:
            break
        s = n
    return re.sub(r'\s+', ' ', s).strip()


def kf_hity(j):
    """Odpowiedź wyszukiwarki wniosków → (lista wpisów, ucięta). Wpis: {adsh, cik, nazwa, form, data, sic}. Zły kształt = wyjątek; zły pojedynczy wpis pomijany."""
    h = j.get('hits') if isinstance(j, dict) else None
    if not (isinstance(h, dict) and isinstance(h.get('hits'), list) and isinstance(h.get('total'), dict) and isinstance(h['total'].get('value'), int)):
        raise RuntimeError('zły kształt odpowiedzi wyszukiwarki')
    out = []
    for x in h['hits']:
        s = x.get('_source') if isinstance(x, dict) else None
        if not isinstance(s, dict):
            continue
        dn = s.get('display_names') if isinstance(s.get('display_names'), list) and s['display_names'] else None
        ciks = s.get('ciks') if isinstance(s.get('ciks'), list) and s['ciks'] else None
        if not (dn and ciks and isinstance(s.get('form'), str) and isinstance(s.get('file_date'), str) and _KF_DZIEN.match(s['file_date']) and isinstance(s.get('adsh'), str)):
            continue
        sics = s.get('sics') if isinstance(s.get('sics'), list) else []
        out.append({'adsh': s['adsh'], 'cik': str(ciks[0]), 'nazwa': kf_nazwa(dn[0]), 'form': s['form'], 'data': s['file_date'], 'sic': str(sics[0]) if sics else ''})
    if h['hits'] and not out:
        raise RuntimeError('żaden wpis wyszukiwarki nie ma oczekiwanych pól')
    rel = h['total'].get('relation')
    return out, bool(rel and rel != 'eq') or h['total']['value'] > len(h['hits'])


def kf_sec(hity, dzis, ucieta=False, prev=None, teraz=None):
    """Wpisy wyszukiwarki (połączone z zapytań, bez powtórzeń) → część `sec`: fundusze w kolejce w ostatnich 30 dobach wobec poprzednich 30. `dzis` — ostatnia doba okna (RRRR-MM-DD)."""
    k_do = datetime.date.fromisoformat(dzis)
    a_cur = (k_do - datetime.timedelta(days=KF_SEC_OKNO - 1)).isoformat()
    a_prev = (k_do - datetime.timedelta(days=2 * KF_SEC_OKNO - 1)).isoformat()
    b_prev = (k_do - datetime.timedelta(days=KF_SEC_OKNO)).isoformat()
    seen, H = set(), []
    for h in hity:
        if h['adsh'] in seen or not a_prev <= h['data'] <= dzis:
            continue
        seen.add(h['adsh']); H.append(h)
    s1 = [h for h in H if h['form'] in ('S-1', 'S-1/A') and KF_ETF.search(h['nazwa']) and h['sic'] in KF_SEC_SIC]
    a8 = [h for h in H if h['form'] in ('8-A12B', '8-A12B/A') and KF_8A.search(h['nazwa'])]
    w_cur = lambda h: h['data'] >= a_cur   # noqa: E731
    w_prev = lambda h: a_prev <= h['data'] <= b_prev   # noqa: E731
    f30 = {h['cik'] for h in s1 if w_cur(h)}
    f30p = {h['cik'] for h in s1 if w_prev(h)}
    n30 = {h['cik'] for h in s1 if w_cur(h) and h['form'] == 'S-1'}
    n30p = {h['cik'] for h in s1 if w_prev(h) and h['form'] == 'S-1'}
    l30 = {h['cik'] for h in a8 if w_cur(h)}
    l30p = {h['cik'] for h in a8 if w_prev(h)}
    lista = []
    for cik in f30:
        F = sorted((h for h in s1 if h['cik'] == cik and w_cur(h)), key=lambda h: (h['data'], h['form']))
        pierw = [h['data'] for h in s1 if h['cik'] == cik and h['form'] == 'S-1']
        lista.append([F[-1]['nazwa'], F[-1]['form'], F[-1]['data'], len(F), min(pierw) if pierw else None])
    lista.sort(key=lambda r: (r[2], r[0]), reverse=True)
    pv = prev if isinstance(prev, dict) else {}
    hist = [h for h in (pv.get('hist') if isinstance(pv.get('hist'), list) else [])
            if isinstance(h, list) and len(h) == 3 and isinstance(h[0], str) and _KF_DZIEN.match(h[0]) and h[0] != dzis and kf_num(h[1], 0) is not None]
    hist.append([dzis, len(f30), len(n30)])
    hist = sorted(hist, key=lambda h: h[0])[-KF_HIST_MAX:]
    return {'t': teraz, 'do': dzis, 'od': a_cur, 'f30': len(f30), 'f30p': len(f30p), 'n30': len(n30), 'n30p': len(n30p), 'l30': len(l30), 'l30p': len(l30p),
            'lista': lista[:KF_SEC_LISTA], 'ucieta': bool(ucieta), 'hist': hist}


def kf_trzeba(czas, ok_prev, teraz):
    """Czy część pobrać w tym przebiegu. czas — chwila poprzedniego pobrania części (brak = tak); po błędzie co KF_BLAD_H h, inaczej co KF_CO_H h."""
    tk, tn = _ix_dt(czas), _ix_dt(teraz)
    if tn is None or tk is None or tk > tn:
        return True
    h = (tn - tk).total_seconds() / 3600
    return h >= (KF_CO_H if ok_prev else KF_BLAD_H)


def kf_zadania(pv, teraz, ma_ua=True):
    """Które części pobrać w tym przebiegu → {część: bool}; część `sec` bez adresu kontaktowego (ma_ua=False) nigdy."""
    ok, pat = (pv.get('ok') if isinstance(pv.get('ok'), dict) else {}), (pv.get('part_at') if isinstance(pv.get('part_at'), dict) else {})
    out = {}
    for n in KF_PARTS:
        if n == 'sec' and not ma_ua:
            out[n] = False
            continue
        out[n] = True if not isinstance(pv.get(n), dict) else kf_trzeba(pat.get(n) or pv.get('at'), ok.get(n, True) is not False, teraz)
    return out


def kf_pobierz(url, naglowki=None):
    """Jedyne miejsce sieci części btc / eth (testy je łatają): zapytanie do usługi cen z odstępem → obiekt JSON."""
    time.sleep(KF_SLEEP)
    return get_json(url, naglowki, KF_TIMEOUT)


def kf_sec_pobierz(url, ua):
    """Jedyne miejsce sieci części sec (testy je łatają): zapytanie do wyszukiwarki urzędu z nagłówkiem User-Agent i odstępem (_ins_get) → obiekt JSON."""
    st, body = _ins_get(url, ua)
    return json.loads(body)


def kf_job(n, cg_key, ua, prev_part, teraz):
    """Odczyt jednej części z sieci → gotowa część pliku."""
    if n in KF_AKT:
        j = kf_pobierz(KF_URL.format(a=KF_AKT[n]), {'x-cg-demo-api-key': cg_key} if cg_key else None)
        return kf_firmy(j, n, teraz, prev_part)
    dzis = (datetime.date.fromisoformat(kf_dzien(teraz)) - datetime.timedelta(days=1)).isoformat()   # ostatnia pełna doba UTC (wnioski z bieżącej doby wpływają do 22:00 czasu wschodniego)
    od = (datetime.date.fromisoformat(dzis) - datetime.timedelta(days=2 * KF_SEC_OKNO - 1)).isoformat()
    wszystkie, ucieta = [], False
    for forma, fraza in KF_SEC_ZAPYTANIA:
        url = KF_SEC_URL.format(q=urllib.parse.quote('"' + fraza + '"'), f=urllib.parse.quote(forma), a=od, b=dzis)
        h, u = kf_hity(kf_sec_pobierz(url, ua))
        wszystkie += h; ucieta = ucieta or u
    return kf_sec(wszystkie, dzis, ucieta, prev_part, teraz)


def build_krypto_firmy(cg_key, contact, prev=None, zadania=None):
    """v422: data/krypto-firmy.json {v, at, src, ok, part_at, btc, eth, sec} → (plik, {część: True | False | 'cached'}). Część pominięta (rytm) zostaje z poprzedniego pliku bez zmian; część po błędzie
    — z poprzedniego pliku z własnym czasem (najwyżej KF_MAX_D dób), błąd do META['errors']. Żadna część w pliku = wyjątek (main zostawia poprzedni plik)."""
    pv = prev if isinstance(prev, dict) and prev.get('v') == KF_V else {}
    ua = ins_ua(contact)
    zad = zadania if zadania is not None else kf_zadania(pv, NOW, bool(ua))
    pat0, ok0 = (pv.get('part_at') if isinstance(pv.get('part_at'), dict) else {}), (pv.get('ok') if isinstance(pv.get('ok'), dict) else {})
    out = {'v': KF_V, 'at': NOW, 'src': 'zestawienie skarbców spółek publicznych (BTC, ETH) z publicznego API usługi cen krypto oraz wyszukiwanie wniosków o fundusze krypto w publicznym indeksie amerykańskiego urzędu nadzoru',
           'ok': {}, 'part_at': {}}
    st = {}
    for n in KF_PARTS:
        stara = pv.get(n) if isinstance(pv.get(n), dict) else None
        if not zad.get(n):
            if stara is not None:
                out[n], out['ok'][n], out['part_at'][n], st[n] = stara, ok0.get(n, True), pat0.get(n) or pv.get('at'), 'cached'
            else:
                st[n] = 'cached'
            continue
        try:
            out[n] = kf_job(n, cg_key, ua, stara, NOW)
            out['ok'][n], out['part_at'][n], st[n] = True, NOW, True
        except Exception as e:  # noqa — jedna część nie psuje pozostałych
            META['errors'].append(mask(f'Skarbce spółek: {n}: {e}')[:200])
            out['ok'][n], st[n] = False, False
            if stara is not None and _zapas_wiek_ok(pat0.get(n) or pv.get('at'), KF_MAX_D):
                out[n], out['part_at'][n] = stara, pat0.get(n) or pv.get('at')
    if not any(isinstance(out.get(n), dict) for n in KF_PARTS):
        raise RuntimeError('żadna część skarbców spółek nie ma danych')
    return out, st


def kf_czesc(cg_key, contact):
    """v422: część przebiegu → krotka wartości dla META['ok'] w kolejności KF_PARTS: True = pobrane, 'cached' = poprzednia wersja wystarcza (rytm dobowy) albo część wyłączona (brak adresu kontaktowego),
    False = część zawiodła. Nieudana budowa zostawia poprzedni plik."""
    prev = previous('krypto-firmy')
    prev = prev if isinstance(prev, dict) and prev.get('v') == KF_V else None
    zad = kf_zadania(prev or {}, NOW, bool(ins_ua(contact)))
    if prev and not any(zad.values()):
        save('krypto-firmy', prev)
        return tuple('cached' for _ in KF_PARTS)
    try:
        obj, st = build_krypto_firmy(cg_key, contact, prev, zad)
        save('krypto-firmy', obj)
        return tuple(st.get(n, False) for n in KF_PARTS)
    except Exception as e:  # noqa
        META['errors'].append(mask(f'Skarbce spółek: {e}')[:200])
        if prev:
            save('krypto-firmy', prev)
        return tuple(False for _ in KF_PARTS)


ZRODLA_META.update({'skarbce_btc': 'coingecko', 'skarbce_eth': 'coingecko', 'skarbce_sec': 'sec'})   # v422: to samo źródło cen krypto i ten sam urząd co insiderzy — liczba źródeł bez zmian


# ===================== v429 (F11Z28): KRÓTKA SPRZEDAŻ W EUROPIE — POZYCJE NETTO W WIELKIEJ BRYTANII I W SZWECJI — data/short-eu.json =====================
# Dwie niezależne części, każda z własnym czasem pobrania i rytmem ~6 h (urzędy dopisują zgłoszenia w dni robocze); po błędzie ponowienie po 1 h, część zostaje z poprzedniego pliku najwyżej 3 doby:
#   uk — zagregowane pozycje krótkie netto w spółkach (plik CSV urzędu nadzoru rynku kapitałowego w Wielkiej Brytanii: spółka, ISIN, pozycja w % kapitału, data pozycji; od 13.07.2026 zamiast listy posiadaczy).
#        Raz (do skutku) pobieramy też plik pozycji, które przestały obowiązywać (od 13.07.2026): razem z bieżącym odtwarza liczbę spółek z pozycją na każdy dzień roboczy od 13.07.2026,
#        więc wykres historii jest od pierwszego dnia (odtworzenie na dzień danych musi zgadzać się z bieżącym plikiem — inaczej historii nie przyjmujemy).
#   se — rejestr pozycji krótkich netto na spółkach szwedzkich (tabela HTML urzędu nadzoru w Szwecji: spółka, LEI, data ostatniej pozycji, suma pozycji krótkich w %; historia zbierana od pierwszego pobrania).
# Do liczników i rankingu bierzemy pozycje co najmniej 0,5% kapitału spółki (próg publicznego ujawniania); w obu plikach są też mniejsze (ostatnio zgłoszone) — liczone tylko w „n”.
# Pozycja netto = akcje sprzedane krótko minus długie: to często zabezpieczenie albo arbitraż, nie zakład na spadek. To nie jest porada inwestycyjna.
import html as _sh_html   # v429: odkodowanie nazw w tabeli HTML (biblioteka standardowa; ponowny import jest nieszkodliwy)
SH_V = 1
SH_PARTS = ('uk', 'se')
SH_URL = {'uk': 'https://www.fca.org.uk/publication/documents/aggregated-current-net-short-positions.csv',
          'ukh': 'https://www.fca.org.uk/publication/documents/aggregated-historic-net-short-positions.csv',
          'se': 'https://www.fi.se/en/our-registers/net-short-positions/'}
SH_CO_H = 6               # h — pobranie co ~6 h
SH_BLAD_H = 1             # h — część, która zawiodła: ponowienie nie częściej niż co tyle
SH_MAX_D = 3              # dób — część po błędzie zostaje z poprzedniego pliku najwyżej tyle
SH_SLEEP = 1.0            # s — odstęp przed zapytaniem
SH_TIMEOUT = 40           # s
SH_MAX_B = {'uk': 400_000, 'ukh': 4_000_000, 'se': 1_500_000}   # B — limit odpowiedzi (18.10.2026: 21 KB, 500 KB, 104 KB)
SH_PROG = 0.5             # % kapitału — próg publicznego ujawniania (liczniki, ranking)
SH_ROZK = (0.5, 1.0, 2.0, 3.0, 5.0, 10.0)   # dolne granice przedziałów rozkładu pozycji (ostatni przedział otwarty)
SH_TOP = 12               # tyle największych pozycji w pliku
SH_RUCH_N = 5             # tyle największych zwiększeń i zmniejszeń
SH_RUCH_MIN = 0.1         # p.p. — mniejsza zmiana pozycji nie jest ruchem
SH_RUCH_MAX = 0.4         # zmiana liczby spółek z pozycją ≥ 0,5% większa niż tyle (część) wobec zrzutu = zmiana zestawienia, nie ruch — porównania nie pokazujemy
SH_HIST_MAX = 400         # punktów historii (po jednym na dzień danych)
SH_SNAP_N = 10            # zrzutów w pliku (po jednym na dobę UTC)
SH_REF_MIN_D, SH_REF_CEL_D, SH_REF_MAX_D = 1, 7, 14   # dób — zrzut do porównania: od 1 do 14 dób, najbliżej 7
SH_MIN_N = {'uk': 100, 'se': 50}            # mniej wierszy = błąd odczytu (18.10.2026: 425 i 335)
SH_MAX_N = {'uk': 3000, 'se': 2000}
SH_PCT_MAX = 60.0         # % — pozycja większa = błąd odczytu (18.10.2026: najwyższa 17,2% i 16,6%)
SH_DATA_MIN = '2019-01-01'   # data pozycji wcześniejsza = błąd wiersza (18.10.2026: najstarsza 2019-12-19 w Szwecji)
SH_SEED_OD = '2026-07-13'    # początek odtwarzanej historii (start nowego pliku zagregowanego)
SH_SEED_MIN_ROWS = 1000      # plik pozycji nieobowiązujących: mniej wierszy = błąd odczytu (18.10.2026: 8186)
SH_BLEDNE_MAX = 0.05         # część wierszy odrzuconych jako błędne, powyżej której cały plik jest błędny
_SH_ISIN = re.compile(r'^[A-Z]{2}[A-Z0-9]{9}[0-9]$')
_SH_LEI = re.compile(r'^[A-Z0-9]{18}[0-9]{2}$')
_SH_DZIEN = re.compile(r'^\d{4}-\d{2}-\d{2}$')
_SH_TAB = re.compile(r'<table\b[^>]*\bid="aktuella"[^>]*>(.*?)</table>', re.S | re.I)
_SH_TR = re.compile(r'<tr\b[^>]*>(.*?)</tr>', re.S | re.I)
_SH_TD = re.compile(r'<td\b[^>]*>(.*?)</td>', re.S | re.I)
_SH_TH = re.compile(r'<th\b[^>]*>(.*?)</th>', re.S | re.I)
_SH_TAG = re.compile(r'<[^>]+>')
_SH_WYD = re.compile(r'List updated:\s*(\d{4}-\d{2}-\d{2})')


def sh_num(v, lo=None, hi=None):
    """Skończona liczba (nie wartość logiczna) w przedziale [lo, hi] albo None."""
    if isinstance(v, bool) or not isinstance(v, (int, float)) or not _etf_math.isfinite(v):
        return None
    if (lo is not None and v < lo) or (hi is not None and v > hi):
        return None
    return float(v)


def sh_dzien_ok(d):
    return isinstance(d, str) and bool(_SH_DZIEN.match(d)) and _ix_dt(d + 'T00:00:00+00:00') is not None


def sh_dni_miedzy(a, b):
    """Liczba dób od dnia a do dnia b (RRRR-MM-DD); zły zapis = None."""
    try:
        return (datetime.date.fromisoformat(b) - datetime.date.fromisoformat(a)).days
    except (TypeError, ValueError):
        return None


def sh_dzien_chwili(iso):
    d = _ix_dt(iso)
    return d.date().isoformat() if d is not None else None


def sh_pozycja(txt):
    """Tekst pozycji w % → liczba w (0, SH_PCT_MAX] albo None (przecinek lub kropka dziesiętna)."""
    try:
        return sh_num(float(str(txt).strip().replace(',', '.')), 1e-9, SH_PCT_MAX)
    except ValueError:
        return None


def sh_nazwa(txt):
    s = re.sub(r'\s+', ' ', str(txt or '')).strip()
    return s if 0 < len(s) <= 120 else None


def sh_wybierz(rows):
    """Wiersze (nazwa, id, pct, dzień) → bez powtórzeń identyfikatora: późniejsza data pozycji, przy remisie wyższa pozycja."""
    best = {}
    for r in rows:
        b = best.get(r[1])
        if b is None or (r[3], r[2]) > (b[3], b[2]):
            best[r[1]] = r
    return sorted(best.values(), key=lambda r: (-r[2], r[0], r[1]))


def sh_kontrola_bledow(wszystkie, dobre, nazwa):
    if wszystkie == 0 or (wszystkie - dobre) > max(3, wszystkie * SH_BLEDNE_MAX):
        raise RuntimeError(f'{nazwa}: za dużo wierszy o złym kształcie ({wszystkie - dobre} z {wszystkie})')


def sh_data_pl(txt, teraz):
    """Data DD/MM/RRRR → RRRR-MM-DD w oknie [SH_DATA_MIN, jutro]; inaczej None."""
    try:
        d = datetime.datetime.strptime(str(txt).strip(), '%d/%m/%Y').date()
    except ValueError:
        return None
    dz = sh_dzien_chwili(teraz)
    if dz is None or d.isoformat() < SH_DATA_MIN or d > datetime.date.fromisoformat(dz) + datetime.timedelta(days=1):
        return None
    return d.isoformat()


def sh_csv(tekst):
    rd = list(csv.reader(io.StringIO(tekst.lstrip('\ufeff'))))
    if not rd or len(rd[0]) < 4:
        raise RuntimeError('zły kształt pliku (brak nagłówka z czterema kolumnami)')
    return [x.strip().lower() for x in rd[0]], rd[1:]


def sh_uk_wiersze(tekst, teraz):
    """Bieżący plik CSV urzędu (Wielka Brytania) → [(nazwa, ISIN, pozycja %, dzień)]; zły nagłówek, za mało wierszy albo za dużo błędnych = wyjątek."""
    h, rows = sh_csv(tekst)
    if not (('isin' in h[1] or 'securities identification' in h[1]) and 'net short' in h[2] and 'date' in h[3]):
        raise RuntimeError('nagłówek pliku nie ma oczekiwanych kolumn (spółka, ISIN, pozycja, data)')
    out = []
    for r in rows:
        if not r or not any(x.strip() for x in r):
            continue
        nz, isin, p, d = (sh_nazwa(r[0]), r[1].strip().upper() if len(r) > 1 else '', sh_pozycja(r[2]) if len(r) > 2 else None,
                          sh_data_pl(r[3], teraz) if len(r) > 3 else None)
        if nz and _SH_ISIN.match(isin) and p is not None and d is not None:
            out.append((nz, isin, p, d))
    sh_kontrola_bledow(sum(1 for r in rows if r and any(x.strip() for x in r)), len(out), 'plik brytyjski')
    out = sh_wybierz(out)
    if not SH_MIN_N['uk'] <= len(out) <= SH_MAX_N['uk']:
        raise RuntimeError(f'liczba spółek w pliku brytyjskim poza zakresem sensu ({len(out)})')
    return out


def sh_ukh_wiersze(tekst, teraz):
    """Plik pozycji, które przestały obowiązywać (Wielka Brytania) → [(ISIN, pozycja %, dzień pozycji, dzień zastąpienia)]."""
    h, rows = sh_csv(tekst)
    if len(h) < 5 or not ('isin' in h[1] or 'securities identification' in h[1]) or 'net short' not in h[2] or 'date' not in h[3] or 'historical' not in h[4]:
        raise RuntimeError('nagłówek pliku historycznego nie ma oczekiwanych kolumn')
    out, n = [], 0
    for r in rows:
        if not r or not any(x.strip() for x in r):
            continue
        n += 1
        if len(r) < 5:
            continue
        isin, p, d1, d2 = r[1].strip().upper(), sh_pozycja(r[2]), sh_data_pl(r[3], teraz), sh_data_pl(r[4], teraz)
        if _SH_ISIN.match(isin) and p is not None and d1 and d2 and d1 <= d2:
            out.append((isin, p, d1, d2))
    sh_kontrola_bledow(n, len(out), 'plik historyczny')
    if len(out) < SH_SEED_MIN_ROWS:
        raise RuntimeError(f'za mało wierszy w pliku historycznym ({len(out)} < {SH_SEED_MIN_ROWS})')
    return out


def sh_uk_odtworz(biez, hist, od, do):
    """Liczba spółek z pozycją w każdy dzień roboczy od `od` do `do` (włącznie): pozycja obowiązuje od dnia pozycji do dnia zastąpienia (bez niego); w dniu obowiązuje ostatnia z pozycji danego ISIN.
    Wynik: [[dzień, n05, n1, n2]]. Wiersze bieżące: obowiązują bez końca."""
    iv = {}
    for nz, isin, p, d in biez:
        iv.setdefault(isin, []).append((d, '9999-12-31', p))
    for isin, p, d1, d2 in hist:
        iv.setdefault(isin, []).append((d1, d2, p))
    out = []
    dz, koniec = datetime.date.fromisoformat(od), datetime.date.fromisoformat(do)
    while dz <= koniec:
        if dz.weekday() < 5 or dz == koniec:   # dzień danych zawsze (także gdyby wypadł w weekend)
            s = dz.isoformat()
            v = []
            for L in iv.values():
                c = [x for x in L if x[0] <= s < x[1]]
                if c:
                    v.append(max(c, key=lambda x: (x[0], x[2]))[2])
            out.append([s, sum(1 for x in v if x >= SH_PROG), sum(1 for x in v if x >= 1.0), sum(1 for x in v if x >= 2.0)])
        dz += datetime.timedelta(days=1)
    return out


def sh_se_wiersze(tekst, teraz):
    """Strona rejestru (Szwecja) → ([(nazwa, LEI, pozycja %, dzień)], dzień aktualizacji listy albo None)."""
    m = _SH_TAB.search(tekst)
    if not m:
        raise RuntimeError('brak tabeli pozycji na stronie rejestru')
    tr = _SH_TR.findall(m.group(1))
    th = [_SH_TAG.sub('', x).strip().lower() for x in _SH_TH.findall(tr[0])] if tr else []
    if len(th) != 4 or 'issuer' not in th[0] or 'date' not in th[2] or 'sum short' not in th[3]:
        raise RuntimeError('nagłówek tabeli nie ma oczekiwanych kolumn (spółka, LEI, data, suma)')
    dz = sh_dzien_chwili(teraz)
    out, n = [], 0
    for row in tr[1:]:
        td = _SH_TD.findall(row)
        if len(td) != 4:
            continue
        n += 1
        c = [_sh_html.unescape(_SH_TAG.sub('', x)).strip() for x in td]
        nz, lei, d, p = sh_nazwa(c[0]), c[1].upper(), c[2], sh_pozycja(c[3])
        if nz and _SH_LEI.match(lei) and p is not None and sh_dzien_ok(d) and SH_DATA_MIN <= d <= (datetime.date.fromisoformat(dz) + datetime.timedelta(days=1)).isoformat():
            out.append((nz, lei, p, d))
    sh_kontrola_bledow(n, len(out), 'tabela szwedzka')
    out = sh_wybierz(out)
    if not SH_MIN_N['se'] <= len(out) <= SH_MAX_N['se']:
        raise RuntimeError(f'liczba spółek w tabeli szwedzkiej poza zakresem sensu ({len(out)})')
    w = _SH_WYD.search(tekst)
    return out, (w.group(1) if w and sh_dzien_ok(w.group(1)) else None)


def sh_rozklad(pcts):
    """Liczby spółek w przedziałach SH_ROZK (ostatni otwarty); pozycje poniżej progu pomijane."""
    c = [0] * len(SH_ROZK)
    for p in pcts:
        if p < SH_ROZK[0]:
            continue
        i = max(k for k, g in enumerate(SH_ROZK) if p >= g)
        c[i] += 1
    return c


def sh_ref(snaps, dzien):
    """Zrzut do porównania: od SH_REF_MIN_D do SH_REF_MAX_D dób wobec dnia `dzien`, najbliższy SH_REF_CEL_D (przy remisie młodszy); brak = None. Zrzut: [dzień, chwila, {id: pozycja}]."""
    best, bk = None, None
    for s in snaps if isinstance(snaps, list) else []:
        if not (isinstance(s, list) and len(s) == 3 and isinstance(s[0], str) and isinstance(s[2], dict)):
            continue
        a = sh_dni_miedzy(s[0], dzien)
        if a is None or not SH_REF_MIN_D <= a <= SH_REF_MAX_D:
            continue
        k = (abs(a - SH_REF_CEL_D), a)
        if bk is None or k < bk:
            best, bk = s, k
    return best


def sh_buduj(wiersze, teraz, prev=None, seed=None, wyd=None):
    """Wiersze (nazwa, id, pozycja %, dzień) → część pliku. prev — poprzednia wersja części (historia, zrzuty); seed — odtworzona historia [[dzień, n05, n1, n2]] (tylko dni wcześniejsze niż dzień danych)."""
    pv = prev if isinstance(prev, dict) else {}
    dzien = sh_dzien_chwili(teraz)
    wiersze = sorted(wiersze, key=lambda r: (-r[2], r[0], r[1]))   # parsery zwracają już posortowane; budowniczy nie zakłada kolejności
    now = {r[1]: r[2] for r in wiersze}
    nazwy = {r[1]: r[0] for r in wiersze}
    nad = [r for r in wiersze if r[2] >= SH_PROG]
    n05, n1, n2, n5 = len(nad), sum(1 for r in nad if r[2] >= 1.0), sum(1 for r in nad if r[2] >= 2.0), sum(1 for r in nad if r[2] >= 5.0)
    asof = max(r[3] for r in wiersze)
    ref = sh_ref(pv.get('snaps'), dzien)
    rm = ref[2] if ref else None
    zm = None
    if rm and len(rm) >= 20 and abs(n05 - len(rm)) <= len(rm) * SH_RUCH_MAX:
        wej = sum(1 for i, p in now.items() if p >= SH_PROG and i not in rm)
        wyj = sum(1 for i in rm if now.get(i, 0) < SH_PROG)
        ruch = [(nazwy[i], i, round(now[i] - rm[i], 2), now[i]) for i in rm if i in now and abs(now[i] - rm[i]) >= SH_RUCH_MIN - 1e-9]
        zm = {'od': ref[0], 'n05_ref': len(rm), 'n1_ref': sum(1 for p in rm.values() if p >= 1.0), 'wej': wej, 'wyj': wyj,
              'plus': [[a, b, c, round(d, 2)] for a, b, c, d in sorted((x for x in ruch if x[2] > 0), key=lambda x: (-x[2], x[0]))[:SH_RUCH_N]],
              'minus': [[a, b, c, round(d, 2)] for a, b, c, d in sorted((x for x in ruch if x[2] < 0), key=lambda x: (x[2], x[0]))[:SH_RUCH_N]]}
    top = []
    for r in nad[:SH_TOP]:   # wiersz: [nazwa, id, pozycja, dzień, zmiana od zrzutu (None: brak porównania), nowa ponad progiem]
        top.append([r[0], r[1], round(r[2], 2), r[3], round(r[2] - rm[r[1]], 2) if (zm and r[1] in rm) else None, bool(zm and r[1] not in rm)])
    hist = [h for h in (pv.get('hist') if isinstance(pv.get('hist'), list) else [])
            if isinstance(h, list) and len(h) == 4 and sh_dzien_ok(h[0]) and h[0] != asof and all(isinstance(x, int) and not isinstance(x, bool) and x >= 0 for x in h[1:])]
    have = {h[0] for h in hist}
    for h in seed or []:
        if h[0] < asof and h[0] not in have:
            hist.append(list(h))
    hist.append([asof, n05, n1, n2])
    hist = sorted(hist, key=lambda h: h[0])[-SH_HIST_MAX:]
    snaps = [s for s in (pv.get('snaps') if isinstance(pv.get('snaps'), list) else []) if isinstance(s, list) and len(s) == 3 and isinstance(s[0], str) and isinstance(s[2], dict) and s[0] != dzien]
    snaps.append([dzien, teraz, {r[1]: round(r[2], 2) for r in nad}])
    snaps = snaps[-SH_SNAP_N:]
    return {'t': teraz, 'dzien': dzien, 'asof': asof, 'wyd': wyd, 'n': len(wiersze), 'n05': n05, 'n1': n1, 'n2': n2, 'n5': n5,
            'max': [nad[0][0], nad[0][1], round(nad[0][2], 2)] if nad else None, 'top': top, 'rozk': sh_rozklad(r[2] for r in nad), 'zm': zm,
            'hist': hist, 'snaps': snaps, 'seed': bool(pv.get('seed') or seed), 'seed_try': pv.get('seed_try')}


def sh_trzeba(czas, ok_prev, teraz):
    """Czy część pobrać w tym przebiegu. czas — chwila poprzedniego pobrania części (brak = tak); po błędzie co SH_BLAD_H h, inaczej co SH_CO_H h."""
    tk, tn = _ix_dt(czas), _ix_dt(teraz)
    if tn is None or tk is None or tk > tn:
        return True
    h = (tn - tk).total_seconds() / 3600
    return h >= (SH_CO_H if ok_prev else SH_BLAD_H)


def sh_zadania(pv, teraz):
    """Które części pobrać w tym przebiegu → {część: bool}."""
    ok, pat = (pv.get('ok') if isinstance(pv.get('ok'), dict) else {}), (pv.get('part_at') if isinstance(pv.get('part_at'), dict) else {})
    return {n: (True if not isinstance(pv.get(n), dict) else sh_trzeba(pat.get(n) or pv.get('at'), ok.get(n, True) is not False, teraz)) for n in SH_PARTS}


def sh_pobierz(url, maks):
    """Jedyne miejsce sieci tego pliku (testy je łatają): zapytanie GET z odstępem, limitem czasu i rozmiaru → bajty."""
    time.sleep(SH_SLEEP)
    return get_bytes_maks(url, None, SH_TIMEOUT, maks)


def sh_job(n, prev_part, teraz):
    """Odczyt jednej części z sieci → gotowa część pliku."""
    if n == 'se':
        w, wyd = sh_se_wiersze(sh_pobierz(SH_URL['se'], SH_MAX_B['se']).decode('utf-8', 'replace'), teraz)
        return sh_buduj(w, teraz, prev_part, None, wyd)
    w = sh_uk_wiersze(sh_pobierz(SH_URL['uk'], SH_MAX_B['uk']).decode('utf-8-sig'), teraz)
    pv = prev_part if isinstance(prev_part, dict) else {}
    seed, dzien, asof = None, sh_dzien_chwili(teraz), max(r[3] for r in w)
    prob = pv.get('seed_try')
    if not pv.get('seed') and prob != dzien:   # historia odtwarzana do skutku, najwyżej raz na dobę
        try:
            hist = sh_ukh_wiersze(sh_pobierz(SH_URL['ukh'], SH_MAX_B['ukh']).decode('utf-8-sig'), teraz)
            seed = sh_uk_odtworz(w, hist, SH_SEED_OD, asof)
            ost = seed[-1] if seed else None
            nad = [r[2] for r in w if r[2] >= SH_PROG]
            if not ost or ost[0] != asof or ost[1:] != [len(nad), sum(1 for p in nad if p >= 1.0), sum(1 for p in nad if p >= 2.0)]:
                raise RuntimeError('odtworzenie na dzień danych nie zgadza się z bieżącym plikiem')
        except Exception as e:  # noqa — historia jest dodatkiem, nie psuje części
            seed = None
            META['notes'].append(mask(f'Krótka sprzedaż (Wielka Brytania): historia nieodtworzona: {e}')[:200])
    o = sh_buduj(w, teraz, pv, seed, None)
    if not o['seed']:
        o['seed_try'] = dzien
    return o


def build_short_eu(prev=None, zadania=None):
    """v429: data/short-eu.json {v, at, src, ok, part_at, uk, se} → (plik, {część: True | False | 'cached'}). Część pominięta (rytm) zostaje z poprzedniego pliku bez zmian; część po błędzie
    — z poprzedniego pliku z własnym czasem (najwyżej SH_MAX_D dób), błąd do META['errors']. Żadna część w pliku = wyjątek (main zostawia poprzedni plik)."""
    pv = prev if isinstance(prev, dict) and prev.get('v') == SH_V else {}
    zad = zadania if zadania is not None else sh_zadania(pv, NOW)
    pat0, ok0 = (pv.get('part_at') if isinstance(pv.get('part_at'), dict) else {}), (pv.get('ok') if isinstance(pv.get('ok'), dict) else {})
    out = {'v': SH_V, 'at': NOW, 'src': 'rejestry pozycji krótkich netto w spółkach: urząd nadzoru rynku kapitałowego w Wielkiej Brytanii (plik zagregowany) i w Szwecji (rejestr na stronie urzędu)',
           'ok': {}, 'part_at': {}}
    st = {}
    for n in SH_PARTS:
        stara = pv.get(n) if isinstance(pv.get(n), dict) else None
        if not zad.get(n):
            if stara is not None:
                out[n], out['ok'][n], out['part_at'][n], st[n] = stara, ok0.get(n, True), pat0.get(n) or pv.get('at'), 'cached'
            else:
                st[n] = 'cached'
            continue
        try:
            out[n] = sh_job(n, stara, NOW)
            out['ok'][n], out['part_at'][n], st[n] = True, NOW, True
        except Exception as e:  # noqa — jedna część nie psuje drugiej
            META['errors'].append(mask(f'Krótka sprzedaż w Europie: {n}: {e}')[:200])
            out['ok'][n], st[n] = False, False
            if stara is not None and _zapas_wiek_ok(pat0.get(n) or pv.get('at'), SH_MAX_D):
                out[n], out['part_at'][n] = stara, pat0.get(n) or pv.get('at')
    if not any(isinstance(out.get(n), dict) for n in SH_PARTS):
        raise RuntimeError('żadna część krótkiej sprzedaży w Europie nie ma danych')
    return out, st


def sh_czesc():
    """v429: część przebiegu → krotka wartości dla META['ok'] w kolejności SH_PARTS: True = pobrane, 'cached' = poprzednia wersja wystarcza (rytm), False = część zawiodła.
    Nieudana budowa zostawia poprzedni plik."""
    prev = previous('short-eu')
    prev = prev if isinstance(prev, dict) and prev.get('v') == SH_V else None
    zad = sh_zadania(prev or {}, NOW)
    if prev and not any(zad.values()):
        save('short-eu', prev)
        return tuple('cached' for _ in SH_PARTS)
    try:
        obj, st = build_short_eu(prev, zad)
        save('short-eu', obj)
        return tuple(st.get(n, False) for n in SH_PARTS)
    except Exception as e:  # noqa
        META['errors'].append(mask(f'Krótka sprzedaż w Europie: {e}')[:200])
        if prev:
            save('short-eu', prev)
        return tuple(False for _ in SH_PARTS)


ZRODLA_META.update({'short_uk': 'fca', 'short_se': 'finansinspektionen'})   # v429: dwa urzędy nadzoru (+2 źródła)


# ===================== v430 (F11Z29): ROPA ŚWIATA — BILANS KRAJÓW (PRODUKCJA, PRZERÓB, IMPORT, EKSPORT, ZAPASY) I ZAPASY ROPY I PALIW W EUROPIE — data/ropa-swiat.json =====================
import email.utils   # v430: nagłówek Last-Modified (biblioteka standardowa; ponowny import jest nieszkodliwy)
# Dwie niezależne części, każda z własnym czasem sprawdzenia (pole t) i rytmem ~22 h (po błędzie ponowienie po 3 h, zapas najwyżej ROP_MAX_D dób):
#   jodi — miesięczne dane o ropie naftowej (bez gazu ziemnego płynnego) wg kraju, ok. 100 krajów, które je przekazują: wydobycie, przerób w rafineriach, import, eksport (tys. baryłek na dobę)
#          i stan zapasów na koniec miesiąca (tys. baryłek). Dwa pliki roczne (poprzedni i bieżący rok) — ok. 17 MB razem, ale pobierane TYLKO gdy plik bieżącego roku się zmienił
#          (zapytanie warunkowe z czasem ostatniej zmiany: 304 = bez pobierania, raz na miesiąc ~40 s). W pliku: ostatnie 24 miesiące, tysiące baryłek zamienione na mln (b/d) i mln baryłek.
#          Kraj bez liczby w danym miesiącu = brak (null), nigdy zero; wartości ujemne, poza zakresem i znaczniki braku („-”, „..”, „x”) = brak. Kraje przekazują dane z różnym opóźnieniem — okres
#          każdego kraju to jego ostatni miesiąc z liczbą (liczy strona). Dane przekazywane przez rządy dobrowolnie: największych producentów (m.in. Rosji, Indii) w zestawieniu może brakować.
#   eu   — miesięczne zapasy ropy naftowej, benzyny silnikowej, oleju napędowego i paliwa lotniczego (koniec miesiąca, tys. ton; bez części biopaliwowej) w krajach Unii Europejskiej, Norwegii i Turcji
#          oraz zapasy awaryjne ropy (zapasy obowiązkowe wg prawa UE); ostatnie 26 miesięcy (rok wcześniej do porównania). Suma UE27 w danych = suma 27 państw (kontrola spójności).
# Źródła: JODI (nowe źródło, +1) i urząd statystyczny UE (już liczony). Bez kluczy i sekretów; publiczne GET z identyfikatorem zbieracza, limit rozmiaru i czasu, odstęp między zapytaniami.
ROP_V = 1
ROP_CZESCI = ('kr', 'eu')
ROP_CO_H = 22             # h — sprawdzenie raz na ~dobę
ROP_BLAD_H = 3            # h — część, która zawiodła: ponowienie nie częściej niż co tyle
ROP_MAX_D = 10            # dób — część po błędzie zostaje z poprzedniego pliku najwyżej tyle
ROP_SLEEP = 1.5           # s — odstęp przed zapytaniem
ROP_TIMEOUT = 60          # s — limit jednego odczytu z gniazda
ROP_CZAS_MAX = 120        # s — limit całego pobrania jednego pliku
ROP_MAX_B = 40_000_000    # bajtów — większy plik = błąd
ROP_OKNO = 24             # miesięcy w pliku (jodi)
ROP_EU_OKNO = 26          # miesięcy w pliku (eu)
ROP_MIN_KRAJE = 15        # tyle krajów z wydobyciem w miesiącu, by miesiąc uznać za pełny (17.10.2026: 47–62)
ROP_MIN_KRAJE_PLIK = 15   # tyle krajów w pliku, mniej = błąd odczytu
ROP_MIN_WIERSZE = 200     # tyle wierszy pięciu serii ropy w pliku rocznym, mniej = plik ucięty (17.10.2026: ok. 3,4 tys. w bieżącym roku, ok. 480 na jeden miesiąc — w styczniu plik ma jeden miesiąc)
ROP_JODI_URL = 'https://www.jodidata.org/_resources/files/downloads/oil-data/annual-csv/primary/'
ROP_JODI_KOLUMNY = ['REF_AREA', 'TIME_PERIOD', 'ENERGY_PRODUCT', 'FLOW_BREAKDOWN', 'UNIT_MEASURE', 'OBS_VALUE', 'ASSESSMENT_CODE']
ROP_JODI_SERIE = {('INDPROD', 'KBD'): 'p', ('REFINOBS', 'KBD'): 'r', ('TOTIMPSB', 'KBD'): 'i', ('TOTEXPSB', 'KBD'): 'e', ('CLOSTLV', 'KBBL'): 'z'}
ROP_JODI_ZAKRES = {'p': (0, 40000), 'r': (0, 40000), 'i': (0, 40000), 'e': (0, 40000), 'z': (0.5, 3_000_000)}   # tys. b/d i tys. baryłek (USA: 13,8 mln b/d, zapasy 0,57 mld baryłek)
ROP_EU_URL = ('https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/nrg_stk_oilm?format=JSON&lang=EN&unit=THS_T&stk_flow=STK_CL&stk_flow=STKCL_EUE'
              '&siec=O4100_TOT&siec=O4652XR5210B&siec=O4671XR5220B&siec=O4661XR5230B&sinceTimePeriod={od}')
ROP_EU_SERIE = {'ropa': ('STK_CL', 'O4100_TOT'), 'benz': ('STK_CL', 'O4652XR5210B'), 'ole': ('STK_CL', 'O4671XR5220B'), 'lot': ('STK_CL', 'O4661XR5230B'), 'awar': ('STKCL_EUE', 'O4100_TOT')}
ROP_EU_UE = ('BE', 'BG', 'CZ', 'DK', 'DE', 'EE', 'IE', 'EL', 'ES', 'FR', 'HR', 'IT', 'CY', 'LV', 'LT', 'LU', 'HU', 'MT', 'NL', 'AT', 'PL', 'PT', 'RO', 'SI', 'SK', 'FI', 'SE')
ROP_EU_KRAJE = ('EU27_2020',) + ROP_EU_UE + ('NO', 'TR')
ROP_EU_ZAKRES = (0, 300000)   # tys. ton (UE27: ropa 55 mln t, olej napędowy 47 mln t)
_ROP_KRAJ = re.compile(r'^[A-Z]{2}$')
_ROP_MIES = re.compile(r'^\d{4}-(0[1-9]|1[0-2])$')


def rop_mies_przed(teraz, n):
    """Miesiąc RRRR-MM, który jest n miesięcy przed miesiącem chwili ISO `teraz`."""
    d = _ix_dt(teraz)
    k = d.year * 12 + (d.month - 1) - n
    return '%04d-%02d' % (k // 12, k % 12 + 1)


def rop_liczba(txt, lo, hi):
    """Tekst liczby z pliku → liczba w przedziale [lo, hi] albo None (znaczniki braku „-”, „..”, „x”, liczby ujemne i poza zakresem = brak)."""
    try:
        v = float(str(txt).strip())
    except (TypeError, ValueError):
        return None
    return v if _etf_math.isfinite(v) and lo <= v <= hi else None


def rop_pobierz(url, ims=None):
    """Jedyne miejsce sieci części jodi (testy je łatają): GET z identyfikatorem zbieracza, odstępem, limitem rozmiaru i czasu → (kod, bajty | None, Last-Modified | None).
    ims = czas ostatniej zmiany z poprzedniego pobrania (zapytanie warunkowe): 304 → (304, None, ims); 404 → (404, None, None); inny błąd = wyjątek."""
    time.sleep(ROP_SLEEP)
    t0 = time.monotonic()
    try:
        with _otworz(url, {'If-Modified-Since': ims} if ims else None, ROP_TIMEOUT) as r:
            lm = r.headers.get('Last-Modified')
            czesci, n = [], 0
            while True:
                b = r.read(1 << 20)
                if not b:
                    break
                n += len(b)
                if n > ROP_MAX_B:
                    raise RuntimeError('plik większy niż limit')
                if time.monotonic() - t0 > ROP_CZAS_MAX:
                    raise RuntimeError('pobranie trwa dłużej niż limit')
                czesci.append(b)
            return r.status, b''.join(czesci), lm
    except urllib.error.HTTPError as e:
        if e.code in (304, 404):
            e.close()   # odpowiedź błędu nie jest potrzebna — zamknięcie połączenia
            return e.code, None, (ims if e.code == 304 else None)
        raise


def rop_http_iso(lm):
    """Nagłówek Last-Modified → chwila ISO UTC albo None."""
    try:
        d = email.utils.parsedate_to_datetime(lm)
        return d.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace('+00:00', 'Z')
    except (TypeError, ValueError):
        return None


def rop_jodi_czytaj(tresc, od_mies):
    """Bajty pliku rocznego → ({kraj: {seria: {miesiąc: tys.}}}, zbiór miesięcy z wierszy ropy). Zmieniony nagłówek albo za mało wierszy = wyjątek."""
    rd = csv.reader(io.StringIO(tresc.decode('utf-8-sig', 'replace')))
    nag = next(rd, None)
    if nag is None or [c.strip() for c in nag] != ROP_JODI_KOLUMNY:
        raise RuntimeError('zmieniony nagłówek pliku')
    out, mies, n = {}, set(), 0
    for w in rd:
        if len(w) != 7 or w[2] != 'CRUDEOIL':
            continue
        s = ROP_JODI_SERIE.get((w[3], w[4]))
        if s is None:
            continue
        n += 1
        k, m = w[0], w[1]
        if not (_ROP_KRAJ.match(k) and _ROP_MIES.match(m)) or m < od_mies:
            continue
        mies.add(m)
        v = rop_liczba(w[5], *ROP_JODI_ZAKRES[s])
        if v is not None:
            out.setdefault(k, {}).setdefault(s, {})[m] = v
    if n < ROP_MIN_WIERSZE:
        raise RuntimeError(f'za mało wierszy ropy w pliku ({n})')
    return out, mies


def rop_jodi_zloz(dane, mies_all):
    """Dane z plików → (okres, miesiące, kraje {kod: {seria: [liczby | None]}}); liczby: przepływy w mln b/d (3 miejsca), zapasy w mln baryłek (2 miejsca)."""
    licz = {m: sum(1 for k in dane if m in dane[k].get('p', {})) for m in mies_all}
    pelne = [m for m in sorted(mies_all) if licz[m] >= ROP_MIN_KRAJE]
    if not pelne:
        raise RuntimeError('żaden miesiąc nie ma wydobycia w co najmniej %d krajach' % ROP_MIN_KRAJE)
    okres = pelne[-1]
    mies = [m for m in sorted(mies_all) if m <= okres][-ROP_OKNO:]
    kraje = {}
    for k in sorted(dane):
        ser = {}
        for s, d in dane[k].items():
            arr = [round(d[m] / 1000.0, 2 if s == 'z' else 3) if m in d else None for m in mies]
            if any(x is not None for x in arr):
                ser[s] = arr
        if ser and sum(1 for a in ser.values() for x in a if x is not None) >= 3:
            kraje[k] = ser
    if len(kraje) < ROP_MIN_KRAJE_PLIK:
        raise RuntimeError('za mało krajów w pliku (%d)' % len(kraje))
    return okres, mies, kraje


def rop_jodi_pliki(rok):
    """Nazwy pliku rocznego do wypróbowania: bieżący rok ma nazwę z przedrostkiem, lata zamknięte — sam rok (strona pobrań źródła); po zmianie roku obie nazwy są możliwe."""
    return ('primaryyear%d.csv' % rok, '%d.csv' % rok)


def rop_jodi_plik(rok, biezacy, ims=None):
    """Plik roczny z sieci → (bajty | None, Last-Modified | None, status); 404 pod obiema nazwami = (None, None, 404)."""
    nazwy = rop_jodi_pliki(rok) if biezacy else rop_jodi_pliki(rok)[::-1]
    for nm in nazwy:
        kod, b, lm = rop_pobierz(ROP_JODI_URL + nm, ims if biezacy else None)
        if kod == 304:
            return None, lm, 304
        if kod != 404:
            return b, lm, kod
    return None, None, 404


def rop_jodi(prev_part, teraz):
    """Część jodi → gotowa część pliku. Bieżący rok nie zmieniony od poprzedniego pobrania (304) = poprzednia część z nowym czasem sprawdzenia."""
    rok = _ix_dt(teraz).year
    ims = prev_part.get('lm_http') if isinstance(prev_part, dict) and isinstance(prev_part.get('kraje'), dict) else None
    b1, lm1, kod1 = rop_jodi_plik(rok, True, ims)
    if kod1 == 304:
        return dict(prev_part, t=teraz)
    if b1 is None and _ix_dt(teraz).month > 3:
        raise RuntimeError('brak pliku bieżącego roku')   # w styczniu–marcu pliku nowego roku może jeszcze nie być (opóźnienie danych ok. 2 miesiące)
    b0, lm0, kod0 = rop_jodi_plik(rok - 1, False)
    if b0 is None:
        raise RuntimeError('brak pliku poprzedniego roku')
    od = rop_mies_przed(teraz, ROP_OKNO + 2)
    dane, mies = {}, set()
    for b in (b0, b1):
        if b is None:
            continue
        d, m = rop_jodi_czytaj(b, od)
        mies |= m
        for k, ser in d.items():
            for s, v in ser.items():
                dane.setdefault(k, {}).setdefault(s, {}).update(v)
    okres, mies_l, kraje = rop_jodi_zloz(dane, mies)
    return {'t': teraz, 'lm': rop_http_iso(lm1 or lm0), 'lm_http': lm1, 'okres': okres, 'mies': mies_l, 'kraje': kraje}


def rop_eu_dekoduj(j):
    """Odpowiedź JSON-stat → (chwila aktualizacji ISO | None, miesiące, {seria: {kraj: [liczby | None]}}). Zła budowa = wyjątek."""
    if not isinstance(j, dict) or not isinstance(j.get('id'), list) or not isinstance(j.get('size'), list) or not isinstance(j.get('dimension'), dict) or 'value' not in j:
        raise RuntimeError('zła budowa odpowiedzi')
    ids, sz = j['id'], j['size']
    if set(ids) != {'freq', 'stk_flow', 'siec', 'unit', 'geo', 'time'} or len(ids) != len(sz):
        raise RuntimeError('zmieniony układ wymiarów')
    kat = {}
    for d in ids:
        ix = j['dimension'][d]['category']['index']
        kat[d] = sorted(ix, key=lambda c: ix[c]) if isinstance(ix, dict) else list(ix)
    if [len(kat[d]) for d in ids] != sz:
        raise RuntimeError('rozmiary wymiarów niezgodne z listą kategorii')
    krok, m = {}, 1
    for d, n in reversed(list(zip(ids, sz))):
        krok[d] = m
        m *= n
    val = j['value']
    pobierz = (lambda p: val.get(str(p))) if isinstance(val, dict) else (lambda p: val[p] if 0 <= p < len(val) else None)
    mies = kat['time']
    if any(not _ROP_MIES.match(x) for x in mies) or mies != sorted(mies):
        raise RuntimeError('miesiące nie rosną')
    out = {}
    for nm, (sf, sc) in ROP_EU_SERIE.items():
        if sf not in kat['stk_flow'] or sc not in kat['siec'] or 'THS_T' not in kat['unit'] or 'M' not in kat['freq']:
            raise RuntimeError('brak serii w odpowiedzi: ' + nm)
        baza = kat['stk_flow'].index(sf) * krok['stk_flow'] + kat['siec'].index(sc) * krok['siec'] + kat['unit'].index('THS_T') * krok['unit'] + kat['freq'].index('M') * krok['freq']
        for g in ROP_EU_KRAJE:
            if g not in kat['geo']:
                continue
            arr = []
            for i, _m in enumerate(mies):
                v = pobierz(baza + kat['geo'].index(g) * krok['geo'] + i * krok['time'])
                v = rop_liczba(v, *ROP_EU_ZAKRES) if isinstance(v, (int, float)) and not isinstance(v, bool) else None
                arr.append(round(v, 1) if v is not None else None)
            if any(x is not None for x in arr):
                out.setdefault(nm, {})[g] = arr
    upd = None
    try:
        upd = datetime.datetime.strptime(str(j.get('updated')), '%Y-%m-%dT%H:%M:%S%z').astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace('+00:00', 'Z')
    except ValueError:
        pass
    return upd, mies, out


def rop_eu(teraz):
    """Część eu → gotowa część pliku."""
    time.sleep(ROP_SLEEP)
    kod, b, _lm = rop_pobierz_json(ROP_EU_URL.format(od=rop_mies_przed(teraz, ROP_EU_OKNO - 1)))
    upd, mies, s = rop_eu_dekoduj(b)
    ropa = s.get('ropa') or {}
    if 'EU27_2020' not in ropa or 'PL' not in ropa or len(mies) < 12 or len(ropa) < 15:
        raise RuntimeError('odpowiedź bez UE27, Polski albo z za małą liczbą krajów')
    ok_ue = [m for m, v in zip(mies, ropa['EU27_2020']) if v is not None]
    kraje = [g for g in ROP_EU_KRAJE if any(g in s.get(n, {}) for n in s)]
    return {'t': teraz, 'upd': upd, 'okres': ok_ue[-1] if ok_ue else None, 'mies': mies, 'kraje': kraje, 's': s}


def rop_pobierz_json(url):
    """Jedyne miejsce sieci części eu (testy je łatają): GET z limitem → (kod, obiekt JSON, None)."""
    return 200, get_json(url, None, ROP_TIMEOUT), None


def rop_trzeba(czas, ok_prev, teraz):
    """Czy część sprawdzić w tym przebiegu. czas — chwila poprzedniego sprawdzenia (brak = tak); po błędzie co ROP_BLAD_H h, inaczej co ROP_CO_H h."""
    tk, tn = _ix_dt(czas), _ix_dt(teraz)
    if tn is None or tk is None or tk > tn:
        return True
    return (tn - tk).total_seconds() / 3600 >= (ROP_CO_H if ok_prev else ROP_BLAD_H)


def rop_zadania(pv, teraz):
    """Które części sprawdzić w tym przebiegu → {część: bool}."""
    ok, pat = (pv.get('ok') if isinstance(pv.get('ok'), dict) else {}), (pv.get('part_at') if isinstance(pv.get('part_at'), dict) else {})
    return {n: True if not isinstance(pv.get(n), dict) else rop_trzeba(pat.get(n) or pv.get('at'), ok.get(n, True) is not False, teraz) for n in ROP_CZESCI}


def build_ropa_swiat(prev=None, zadania=None):
    """v430: data/ropa-swiat.json {v, at, src, ok, part_at, kr, eu} → (plik, {część: True | False | 'cached'}). Część pominięta (rytm) zostaje z poprzedniego pliku; część po błędzie —
    z poprzedniego pliku z własnym czasem (najwyżej ROP_MAX_D dób), błąd do META['errors']. Żadna część w pliku = wyjątek (main zostawia poprzedni plik)."""
    pv = prev if isinstance(prev, dict) and prev.get('v') == ROP_V else {}
    zad = zadania if zadania is not None else rop_zadania(pv, NOW)
    pat0, ok0 = (pv.get('part_at') if isinstance(pv.get('part_at'), dict) else {}), (pv.get('ok') if isinstance(pv.get('ok'), dict) else {})
    out = {'v': ROP_V, 'at': NOW, 'src': 'miesięczne dane krajów o ropie naftowej (wydobycie, przerób, handel, zapasy) z międzynarodowej bazy danych o ropie oraz zapasy ropy i paliw w Europie z urzędu statystycznego UE',
           'ok': {}, 'part_at': {}}
    st = {}
    for n in ROP_CZESCI:
        stara = pv.get(n) if isinstance(pv.get(n), dict) else None
        if not zad.get(n):
            if stara is not None:
                out[n], out['ok'][n], out['part_at'][n], st[n] = stara, ok0.get(n, True), pat0.get(n) or pv.get('at'), 'cached'
            else:
                st[n] = 'cached'
            continue
        try:
            out[n] = rop_jodi(stara, NOW) if n == 'kr' else rop_eu(NOW)
            out['ok'][n], out['part_at'][n], st[n] = True, NOW, True
        except Exception as e:  # noqa — jedna część nie psuje drugiej
            META['errors'].append(mask(f'Ropa świata: {n}: {e}')[:200])
            out['ok'][n], st[n] = False, False
            if stara is not None and _zapas_wiek_ok(pat0.get(n) or pv.get('at'), ROP_MAX_D):
                out[n], out['part_at'][n] = stara, pat0.get(n) or pv.get('at')
    if not any(isinstance(out.get(n), dict) for n in ROP_CZESCI):
        raise RuntimeError('żadna część ropy świata nie ma danych')
    return out, st


def rop_czesc():
    """v430: część przebiegu → krotka wartości dla META['ok'] w kolejności ROP_CZESCI: True = sprawdzone, 'cached' = poprzednia wersja wystarcza (rytm dobowy), False = część zawiodła.
    Nieudana budowa zostawia poprzedni plik."""
    prev = previous('ropa-swiat')
    prev = prev if isinstance(prev, dict) and prev.get('v') == ROP_V else None
    zad = rop_zadania(prev or {}, NOW)
    if prev and not any(zad.values()):
        save('ropa-swiat', prev)
        return tuple('cached' for _ in ROP_CZESCI)
    try:
        obj, st = build_ropa_swiat(prev, zad)
        save('ropa-swiat', obj)
        return tuple(st.get(n, False) for n in ROP_CZESCI)
    except Exception as e:  # noqa
        META['errors'].append(mask(f'Ropa świata: {e}')[:200])
        if prev:
            save('ropa-swiat', prev)
        return tuple(False for _ in ROP_CZESCI)


ZRODLA_META.update({'ropa_kr': 'jodi', 'ropa_eu': 'eurostat'})   # v430: baza danych o ropie (+1 źródło); urząd statystyczny UE już liczony


